/* The integration shell keeps its existing name while the persistent owner is
 * the explicit BounceGame context defined by game.h. */
typedef BounceGame BounceApp;

/*
 * STEP 13E -- the debug tracker is reached through one accessor so every
 * instrumentation site below is a single statement that is inert when the
 * tracker is absent. A NULL tracker makes each tracker call return on its
 * enabled test, so a default run pays one branch and nothing else.
 */
static BounceDebugTracker *app_debug(const BounceApp *app)
{
    return app == NULL ? NULL : app->debug_tracker;
}

typedef struct X11PresentationContext {
    Display *display;
    int screen;
    Window window;
    GC graphics_context;
    Atom delete_window_atom;
    RenderTrace *render_trace;
    int running;
    int failed;
    /*
     * STEP 46G -- e.java:57 `private int g = 0;`, the GodMode sequence detector.
     *
     * LIFETIME IS THE POINT OF PUTTING IT HERE. Java declares `g` on the
     * gameplay canvas `e` (e.java:57), and `e` is constructed exactly once per
     * application run (BounceGame.java:96, the only `new e(...)` in the tree).
     * This context is likewise constructed once, in x11_create(), and
     * zero-initialised by the memset at :10880 -- so the field starts at 0,
     * survives every gameplay frame, level load, death and respawn, and dies
     * with the session. That is exactly `e`'s lifetime.
     *
     * It is deliberately NOT in BounceInputState: that module models held key
     * state and is shared with every verification, whereas `g` is an ordered
     * event counter and Java keeps it on the canvas, not the player.
     *
     * It is NOT persisted, NOT reset by a level load, and NOT derived from
     * held-key state, timestamp or timer -- none of which exist in e.java.
     */
    int god_mode_sequence;
} X11PresentationContext;

static int create_level001_player(
    const BounceLevel *level,
    BouncePlayer *player_out
)
{
    BouncePlayerSpawn spawn;

    if (level == NULL || player_out == NULL)
        return -1;

    if (bounce_player_initialize_from_level(level, player_out, &spawn) != 0
        || !spawn.initialized
        || spawn.world_x != 30
        || spawn.world_y != 18
        || spawn.tile_x != 2
        || spawn.tile_y != 1
        || spawn.ball_size != BOUNCE_REGULAR_BALL_SIZE
        || spawn.half_size != BOUNCE_REGULAR_BALL_P
        || player_out->ballSize != BOUNCE_REGULAR_BALL_SIZE
        || player_out->p != BOUNCE_REGULAR_BALL_P
        || player_out->current_ball_mode
            != BOUNCE_PLAYER_BALL_MODE_REGULAR)
        return -1;

    return 0;
}

static int validate_level001(const BounceLevel *level)
{
    if (level == NULL
        || bounce_level_width(level) != BOUNCE_LEVEL001_WIDTH
        || bounce_level_height(level) != BOUNCE_LEVEL001_HEIGHT
        || bounce_level_initial_x(level) != 2u
        || bounce_level_initial_y(level) != 1u
        || bounce_level_is_big_ball(level) != 0u
        || bounce_level_thorn_count(level) != 0u)
        return -1;
    return 0;
}

static int verify_runtime_tile_copy(
    const BounceLevel *level,
    const BounceRuntimeLevelTiles *runtime
)
{
    uint32_t y;
    uint32_t x;

    if (level == NULL
        || runtime == NULL
        || bounce_runtime_level_tiles_width(runtime) != bounce_level_width(level)
        || bounce_runtime_level_tiles_height(runtime) != bounce_level_height(level))
        return -1;

    for (y = 0u; y < bounce_level_height(level); ++y) {
        for (x = 0u; x < bounce_level_width(level); ++x) {
            uint8_t structural_value;
            uint16_t runtime_value;

            if (bounce_level_get_tile(
                    level,
                    (int)x,
                    (int)y,
                    &structural_value
                ) != 0
                || bounce_runtime_level_tiles_get(
                    runtime,
                    (int)x,
                    (int)y,
                    &runtime_value
                ) != 0
                || runtime_value != (uint16_t)structural_value)
                return -1;
        }
    }
    return 0;
}

static int app_load_level001(BounceApp *app, const char *level_path)
{
    if (app == NULL || level_path == NULL)
        return -1;
    if (app->level != NULL)
        return 0;

    if (bounce_game_load_level(app, level_path, 1) != 0) {
        fprintf(stderr, "could not load %s through gameplay lifecycle\n", level_path);
        return -1;
    }
    if (validate_level001(app->level) != 0
        || verify_runtime_tile_copy(app->level, app->runtime) != 0
        || create_level001_player(app->level, &app->player) != 0) {
        fprintf(stderr, "asset is not the expected regular-ball Level 001\n");
        bounce_game_release_level(app);
        return -1;
    }
    return 0;
}

/*
 * Native level-load integration seam:
 *   GAMEPLAY_ENTRY -> native level load -> LEVEL_LOADED -> STOP
 *
 * This uses the existing verified level-loader seam through
 * bounce_game_load_level_entry. It creates no runtime tiles, no player, no
 * camera state, and no tick, and it is deliberately deterministic-only: the
 * X11 runtime deliberately stays on the UI 6 gameplay-entry screen because
 * this milestone must not add a renderer screen.
 */
static int app_advance_gameplay_entry_to_level_loaded(BounceApp *app)
{
    int level_id;

    if (app == NULL || app->flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY)
        return -1;
    level_id = bounce_app_flow_entry_level_id(&app->flow);
    if (bounce_game_load_level_entry(app, level_id) != 0)
        return -1;
    if (bounce_app_flow_record_level_loaded(&app->flow) != 0) {
        bounce_game_release_level(app);
        return -1;
    }
    return bounce_game_sync_ui_state(app);
}

/*
 * Native player-initialization seam:
 *   LEVEL_LOADED -> bounce_player_initialize_from_level -> PLAYER_INITIALIZED
 *   -> STOP
 *
 * Like the level-load seam this is deterministic-only: no renderer screen is
 * added, so the X11 runtime stays on the UI 6 gameplay-entry screen.
 */
static int app_advance_level_loaded_to_player_initialized(BounceApp *app)
{
    if (app == NULL || app->flow.state != BOUNCE_APP_STATE_LEVEL_LOADED)
        return -1;
    if (bounce_game_initialize_player_entry(app) != 0)
        return -1;
    if (bounce_app_flow_record_player_initialized(&app->flow) != 0) {
        bounce_player_reset(&app->player);
        memset(&app->spawn, 0, sizeof app->spawn);
        return -1;
    }
    return bounce_game_sync_ui_state(app);
}

/*
 * Native runtime-initialization seam:
 *   PLAYER_INITIALIZED -> mutable runtime tile copy + dynamic-thorn state
 *   -> RUNTIME_INITIALIZED -> STOP
 *
 * This is an implementation seam, not a recovered Java lifecycle step. It is
 * deterministic-only: no camera, timer, tick, PLAYING transition, or renderer
 * work is performed, so the X11 runtime stays on the UI 6 gameplay-entry screen.
 */
static int app_advance_player_initialized_to_runtime_initialized(BounceApp *app)
{
    if (app == NULL || app->flow.state != BOUNCE_APP_STATE_LEVEL_LOADED)
        return -1;
    if (bounce_game_initialize_runtime_entry(app) != 0)
        return -1;
    if (bounce_app_flow_entry_runtime_tiles_created(&app->flow) == false) {
        bounce_runtime_level_tiles_destroy(app->runtime);
        app->runtime = NULL;
        return -1;
    }
    return bounce_game_sync_ui_state(app);
}

/*
 * Native gameplay-activation seam:
 *   CAMERA_INITIALIZED -> bounce_game_activate_staged_level -> ACTIVATED
 *   -> STOP (no tick)
 *
 * The original's activation is `this.display.setCurrent(this.v)` at
 * BounceGame.java:155, the only source-backed action in the post-camera block;
 * see bounce_game_activate_staged_level() in game.c for the full source
 * accounting. This driver exists only to place the seam in the staged route.
 *
 * It deliberately does NOT call app_update_game(), so entering PLAYING does not
 * itself execute a tick. Deterministic-only: the X11 run loop never drives these
 * staged seams, so the interactive path still stops at gameplay-entry.
 */
static int app_advance_camera_initialized_to_activated(BounceApp *app)
{
    if (app == NULL
        || app->flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
        || app->state != BOUNCE_GAME_STATE_LEVEL_LOADED)
        return -1;
    if (bounce_game_activate_staged_level(app) != 0)
        return -1;
    if (!bounce_app_flow_entry_gameplay_activated(&app->flow)
        || app->state != BOUNCE_GAME_STATE_PLAYING) {
        return -1;
    }
    return 0;
}

/* TEMPORARY NATURAL CAMERA DIAGNOSTIC LEVEL LOADER — LEVEL001 VALIDATION IS BYPASSED ONLY HERE. */
static int app_load_natural_camera_level(
    BounceApp *app,
    const char *level_path
)
{
    if (app == NULL || level_path == NULL || app->level != NULL)
        return -1;

    if (bounce_game_start_level(app, level_path, 0, 3) != 0)
        return -1;
    if (app->player.current_ball_mode
            != BOUNCE_PLAYER_BALL_MODE_REGULAR
        || app->player.ballSize != BOUNCE_REGULAR_BALL_SIZE
        || app->player.p != BOUNCE_REGULAR_BALL_P) {
        bounce_game_release_level(app);
        return -1;
    }
    return 0;
}

static int32_t java_int32_add(int32_t left, int32_t right)
{
    uint32_t bits = (uint32_t)left + (uint32_t)right;
    int32_t result;

    (void)memcpy(&result, &bits, sizeof result);
    return result;
}

static int32_t java_int32_subtract(int32_t left, int32_t right)
{
    uint32_t bits = (uint32_t)left - (uint32_t)right;
    int32_t result;

    (void)memcpy(&result, &bits, sizeof result);
    return result;
}

static int32_t java_int32_negate(int32_t value)
{
    uint32_t bits = UINT32_C(0) - (uint32_t)value;
    int32_t result;

    (void)memcpy(&result, &bits, sizeof result);
    return result;
}

static int32_t java_int32_abs(int32_t value)
{
    return value < 0 ? java_int32_negate(value) : value;
}

static int32_t java_int32_shift_right_one(int32_t value)
{
    uint32_t bits = ((uint32_t)value >> 1)
        | ((uint32_t)value & UINT32_C(0x80000000));
    int32_t result;

    (void)memcpy(&result, &bits, sizeof result);
    return result;
}

static int32_t java_int32_divide_by_two(int32_t value)
{
    return value / 2;
}

