static int app_begin_player_ticks(BounceApp *app)
{
    int64_t now;

    if (app == NULL)
        return -1;
    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    app->next_player_tick_ms = now;
    return 0;
}

static int app_begin_ui_ticks(BounceApp *app)
{
    int64_t now;

    if (app == NULL)
        return -1;
    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    app->flow.next_tick_ms = now;
    return 0;
}

/*
 * STEP G-R3-R2 -- forward declarations.
 *
 * app_update_ui() below is the splash-to-menu transition, which is the first of
 * the three production arrivals at the main menu and therefore the first caller of
 * the availability refresh. The definitions sit beside the R1 restore code they
 * cooperate with, further down this file.
 */
static void app_refresh_continue_availability(BounceApp *app);
static int app_begin_resume_from_menu(BounceApp *app);

/* The splash uses the same 40 ms cadence requested by the Java timer. */
static int app_update_ui(BounceApp *app)
{
    int64_t now;

    if (app == NULL)
        return -1;

    /*
     * Mirror the flow's applied language into the one runtime value the label
     * and render helpers read. The flow stays the owner; nothing is persisted,
     * so a fresh launch always starts on index 0, the default English resource.
     */
    bounce_locale_set_active_language(
        (BounceLanguage)bounce_app_flow_settings_applied_language_index(
            &app->flow));

    /*
     * Mirror the flow's applied color profile into the single active UI palette.
     * The flow remains the owner. Only the ui_shell palette changes; the
     * gameplay scene, level renderer, and renderer primitives are untouched.
     */
    bounce_ui_shell_set_color_profile(
        bounce_app_flow_settings_applied_theme_index(&app->flow));

    /*
     * Mirror the same applied language into the script font so the UI shell can
     * measure and draw CJK and Thai. EN and ID have no script set and therefore
     * keep the 5x7 font, which is why this is harmless for them.
     */
    bounce_script_font_set_active_language(
        bounce_app_flow_settings_applied_language_index(&app->flow)
            == (unsigned int)BOUNCE_LANGUAGE_ID
            ? BOUNCE_LANGUAGE_ID
            : (BounceLanguage)
                bounce_app_flow_settings_applied_language_index(&app->flow));

    if (app->flow.state != BOUNCE_APP_STATE_SPLASH)
        return 0;

    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    if (app->flow.next_tick_ms <= 0)
        app->flow.next_tick_ms = now;
    while (now >= app->flow.next_tick_ms) {
        int transition = bounce_app_flow_tick(&app->flow);

        app->flow.next_tick_ms += BOUNCE_APP_TICK_MS;
        if (transition < 0)
            return -1;
        if (transition == 1) {
            if (bounce_game_enter_menu(app) != 0)
                return -1;
            /*
             * STEP G-R3-R2 -- first production menu arrival. Native's
             * continue_available lives in the menu struct, which enter_menu just
             * reset, so it is re-derived from the store here rather than cached at
             * startup.
             */
            app_refresh_continue_availability(app);
            /*
             * STEP 12X-G-P2 -- no level range is published here any more.
             *
             * This block used to call
             * bounce_app_flow_set_available_level_count(&app->flow,
             * BOUNCE_APP_LAST_LEVEL_ID), which made the model report all eleven
             * shipped level files as unlocked. That was a stand-in for the
             * RMS-backed MaxLevels, whose real value is unavailable here because
             * there is no persistence layer in this tree. It was wrong in both
             * directions: it unlocked levels no fresh install has reached, and it
             * took the Level Select branch at app_flow.c:321 for
             * BounceGame.java:238's `MaxLevels > 1` test on a fresh install.
             *
             * The source-backed value is the one bounce_app_flow_init() already
             * writes, 0. BounceGame.java:276-279 shows why that is the correct
             * fresh-install state: when the store does not already hold three
             * records, LoadRecords() writes three zero-filled records and reads
             * none of them, so MaxLevels is never assigned and keeps its Java
             * default of 0 from :21. With MaxLevels 0 the New Game gate at :238
             * is false, so `a(true, 1)` runs and the first level starts directly,
             * with no Level Select.
             *
             * The count is now advanced only where the source advances it, by
             * bounce_app_flow_complete_level() in bounce_game_mark_level_complete()
             * -- game.c -- which mirrors e.java:317 and BounceGame.java:418-420.
             * The model default stays 0 and
             * bounce_app_flow_set_available_level_count() still refuses any count
             * above BOUNCE_APP_LAST_LEVEL_ID; it is now reached only by the
             * verifiers, which set an explicit count to exercise the list bounds.
             */
            break;
        }
    }
    return 0;
}

static int app_run_player_ticks(BounceApp *app)
{
    int64_t now;
    bool gravity_inverted;
    bool update_horizontal;

    if (app == NULL)
        return -1;
    if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY)
        return 0;
    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    if (app->next_player_tick_ms <= 0)
        app->next_player_tick_ms = now;
    while (now >= app->next_player_tick_ms) {
        bool camera_gate;

        camera_gate = app_camera_needs_update(app);
        camera_diagnostic_tick_begin(app, camera_gate);
        if (camera_gate) {
            if (app_update_camera(app) != 0) {
                camera_diagnostic_camera_updated(app, false);
                return -1;
            }
            camera_diagnostic_camera_updated(app, true);
        }
        vertical_diagnostic_tick_begin(app);
        /* Java e.Tick() uses the camera branch OR the player-physics branch. */
        if (!camera_gate) {
            update_horizontal = app->player.z != 2;
            if (app_step_vertical(app, &gravity_inverted) != 0)
                return -1;
            if (update_horizontal
                && app_step_horizontal(app, gravity_inverted) != 0)
                return -1;
        }
        /* Java LoadSpriteSheet() follows either branch on every game tick. */
        if (app_update_camera_horizontal(app) != 0)
            return -1;
        vertical_diagnostic_tick_end(app);
        camera_diagnostic_tick_after_movement(app);
        app->next_player_tick_ms += BOUNCE_HORIZONTAL_TICK_MS;
    }
    return 0;
}

static int app_update_game(BounceApp *app)
{
    if (app == NULL)
        return -1;

    switch (app->state) {
        case BOUNCE_GAME_STATE_PLAYING:
            if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY)
                return -1;
            return app_run_player_ticks(app);
        case BOUNCE_GAME_STATE_SPLASH:
        case BOUNCE_GAME_STATE_MENU:
        case BOUNCE_GAME_STATE_LEVEL_COMPLETE:
        case BOUNCE_GAME_STATE_DEAD:
        case BOUNCE_GAME_STATE_RESPAWN:
        case BOUNCE_GAME_STATE_GAME_OVER:
        case BOUNCE_GAME_STATE_PAUSED:
        case BOUNCE_GAME_STATE_ACTION_BOUNDARY:
        case BOUNCE_GAME_STATE_INSTRUCTIONS:
        case BOUNCE_GAME_STATE_HIGH_SCORE:
        case BOUNCE_GAME_STATE_LEVEL_SELECTION:
        case BOUNCE_GAME_STATE_GAMEPLAY_ENTRY:
        case BOUNCE_GAME_STATE_LEVEL_LOADED:
        /* NATIVE EXTENSION mirrors: no gameplay update runs in these screens. */
        case BOUNCE_GAME_STATE_SETTINGS:
        case BOUNCE_GAME_STATE_ABOUT:
        /* STEP 12X-P4-B: the terminal state routes no gameplay update, exactly
         * as the states above it do. Java is terminal for the same reason
         * BounceGame.java:178 gives: the timer is stopped, so Tick() cannot run. */
        case BOUNCE_GAME_STATE_GAME_END:
            return 0;
        case BOUNCE_GAME_STATE_UNKNOWN:
        default:
            return -1;
    }
}

/*
 * STEP 12X-F2-B -- the single horizontal clamp, with the limit supplied by the
 * caller.
 *
 * Java has TWO different upper bounds on the same camera origin `k`, and which
 * one is in force depends on which of the two routines last ran:
 *
 *   e.java:139                i > this.TODO_width * 12 - 156
 *   b.java:631-632 (inside b.LoadSpriteSheet(int))
 *                             k > (this.TODO_width + 1) * 12 - 156
 *
 * The second is 12 px wider. They are not interchangeable, and collapsing them
 * is what made the Level 1 exit unreachable: b.m() and b.g() (b.java:663-669)
 * return l*12 - v and l*12 - v + 128, and both are derived from the value
 * LoadSpriteSheet stored at b.java:660 (`this.v = this.l * 12 - k`), so
 * m() == k and g() == k + 128 exactly.
 *
 * Therefore the caller decides the bound and this function owns the arithmetic
 * and the store, so the two source expressions are never duplicated.
 */
static int app_update_camera_horizontal_to_limit(
    BounceApp *app,
    int32_t camera_x_limit
)
{
    int32_t camera_x;

    if (app == NULL || camera_x_limit < 0)
        return -1;

    camera_x = java_int32_add(
        app->player.TODO_unkX,
        -BOUNCE_CAMERA_LEFT_MARGIN
    );
    if (camera_x < 0)
        camera_x = 0;
    else if (camera_x > camera_x_limit)
        camera_x = camera_x_limit;
    /* Store the effective tile origin; the native renderer has no Java E-buffer
     * seam column, but this preserves Java's l/v viewport origin exactly. */
    app->l = camera_x / BOUNCE_TILE_SIZE;
    app->v = java_int32_subtract(
        app->l * BOUNCE_TILE_SIZE,
        camera_x
    );
    return 0;
}

static int app_update_camera_horizontal_for_width(
    BounceApp *app,
    int32_t level_width
)
{
    if (app == NULL || level_width <= 0)
        return -1;
    /* The e.e() bound, e.java:139. Unchanged by Step 12X-F2-B. */
    return app_update_camera_horizontal_to_limit(
        app,
        level_width * BOUNCE_TILE_SIZE - BOUNCE_CAMERA_E_BUFFER_WIDTH
    );
}

/*
 * STEP 12X-I-FIX -- THE HORIZONTAL-EXPOSURE b.z PRODUCER. e.java:310.
 *
 * THE GAP THIS EXISTS TO CLOSE. b.z has exactly one `true` write in the source,
 * b.java:461, inside `case 9` of the four-argument CreateTiles(b.java:398). That
 * method has THREE native-reachable callers in Java, and this file already
 * reproduced two of them:
 *
 *   b.f()              b.java:602-607, walked over the whole 13x8 window, called
 *                      from e() at e.java:150.  -> app_produce_b_z() at :5438.
 *   b.LoadSpriteSheet  b.java:625-661, called from e.Tick() at e.java:310. It does
 *                      NOT walk the window; it walks only the newly exposed edge
 *                      column, 8 cells at a time:
 *                        b.java:645  CreateTiles(this.G - 13, this.k + b1, ...)
 *                        b.java:658  CreateTiles(this.l + m/12, this.k + b1, ...)
 *                      for b1 in [0,8). Those calls reach `case 9` and so set z.
 *
 * app_update_camera_horizontal() is this file's LoadSpriteSheet role (see :5257,
 * :5484 and :8021). Until now it performed only the origin arithmetic and
 * exposed no b.z, so a door column that first entered the window on a physics
 * tick -- where no app_produce_b_z() call happens, because that call lives
 * behind app_update_camera_for_width() at :5413 -- could never latch. Java
 * latches at the end of that same tick (e.java:310 runs after the gate at
 * e.java:286), so native could only ever latch on a later camera tick.
 *
 * WHY A HELPER AND NOT A REUSE OF app_produce_b_z(). app_produce_b_z() scans the
 * whole 13x8 window; LoadSpriteSheet() scans only what this update newly
 * exposed. Calling the former here would turn an incremental exposure test into a
 * full-window rescan on every physics tick, which is a different computation and
 * not the one b.java:625-661 performs. This helper therefore takes the previous
 * column origin and inspects exactly the symmetric difference of the old and new
 * 13-column windows. The existing producer is untouched.
 *
 * WHAT IS REPRODUCED, LINE FOR LINE.
 *   b.java:401-404  out-of-range cell returns before the switch -> `continue`.
 *   b.java:405      clear the dirty bit;  b.java:409 clear the water bit.
 *   b.java:412/:455/:461  case 9 -> this.z = true.
 *   Rows are k..k+7 exactly, which is b.java:644/:657's `b1 < 8` and equals
 *   BOUNCE_CAMERA_GATE_HEIGHT / BOUNCE_TILE_SIZE, the same `rows` app_produce_b_z()
 *   uses at :5360. Columns are the 13-cell window width, the same `cols`
 *   app_produce_b_z() uses at :5361.
 *
 * MONOTONE, LIKE EVERY OTHER b_z WRITE. There is no `b_z = false` here and none
 * may be added: Java only clears z at e.java:288, inside the gate's own M arm,
 * which this native gate cannot reach once door_open_flag is true (see the
 * note at :5352-5356). The early return on an already-set latch mirrors
 * app_produce_b_z()'s at :5370.
 *
 * NOT TOUCHED HERE: no door field other than b_z, no camera arithmetic, no
 * cadence, no tile-grid write. b.java:405's dirty-bit clear is deliberately NOT
 * reproduced -- it is a rasterisation side effect on LevelTiles, and this helper
 * is a read-only query whose only output is the latch.
 */
static void app_note_exposed_exit_b_z(
    BounceApp *app,
    int32_t previous_l
)
{
    const int32_t rows = BOUNCE_CAMERA_GATE_HEIGHT / BOUNCE_TILE_SIZE;
    const int32_t cols = BOUNCE_CAMERA_E_BUFFER_WIDTH / BOUNCE_TILE_SIZE;
    uint32_t width;
    uint32_t height;
    int32_t row_last;
    int32_t col;
    int32_t row;

    if (app == NULL || app->runtime == NULL)
        return;
    /* The latch is already set: W2 has no clearing counterpart here either. */
    if (app->b_z)
        return;
    width = bounce_runtime_level_tiles_width(app->runtime);
    height = bounce_runtime_level_tiles_height(app->runtime);
    row_last = app->k + rows;
    for (col = app->l; col < app->l + cols; col++) {
        /* Skip every column this update did not newly expose. */
        if (col >= previous_l && col < previous_l + cols)
            continue;
        for (row = app->k; row < row_last; row++) {
            uint16_t value = 0;
            uint32_t tile_id;

            /* b.java:401-404 -- the only early return in CreateTiles. */
            if (col < 0
                || row < 0
                || (uint32_t)col >= width
                || (uint32_t)row >= height)
                continue;
            if (bounce_runtime_level_tiles_get(
                    app->runtime,
                    (int)col,
                    (int)row,
                    &value) != 0)
                continue;
            tile_id = (uint32_t)value;
            tile_id &= ~UINT32_C(0x40);
            tile_id &= ~UINT32_C(0x80);
            /* b.java:412 `case 9` -> b.java:461 `this.z = true`. */
            if (tile_id == 9u) {
                app->b_z = true;
                return;
            }
        }
    }
}

static int app_update_camera_horizontal(BounceApp *app)
{
    int32_t level_width;
    int32_t previous_l;

    if (app == NULL || app->level == NULL)
        return -1;
    level_width = (int32_t)bounce_level_width(app->level);
    /*
     * STEP 12X-I-FIX: the column origin this call is about to replace. Java's
     * LoadSpriteSheet() knows which edge columns it exposed because it carries
     * Z/G across calls (b.java:626-627); this routine recomputes the origin from
     * scratch every tick, so the previous origin is captured here instead and
     * handed to app_note_exposed_exit_b_z() below. Nothing else reads it.
     */
    previous_l = app->l;
    /*
     * Java LoadSpriteSheet(paramInt) is the per-tick horizontal hand-off, and it
     * clamps to the WIDER expression at b.java:631-632:
     *
     *   } else if (k > (this.TODO_width + 1) * 12 - 156) {
     *       k = (this.TODO_width + 1) * 12 - 156;
     *   }
     *
     * STEP 12X-F2-B substitutes exactly that bound here, and only here.
     *
     * WHY THIS ROLE MATTERS. e.Tick() performs the exit-visibility test at :286
     * and only afterwards calls LoadSpriteSheet at :310, so the test observes the
     * PREVIOUS frame's LoadSpriteSheet value, not e()'s. The native order is the
     * same: the exit gate at vertical_slice.c:3882-3883 reads app->l / app->v
     * and app_update_camera_horizontal() is called later in the same function at
     * :3894. With the narrower e.e() bound substituted here, m() maxed out at
     * width*12-28 and g() at width*12-156+128, so the gate term
     *
     *   e.java:286   this.exitX * 12 < g()
     *
     * was false for every level whose exit sits at exitX == width - 2 -- Levels
     * 1, 2 and 5 -- by exactly 4 px. Levels 1 and 2 are the two levels the
     * Step 12X-G-P4 progression work is about, and Level 1 is the level a
     * fresh install starts. The door object, its asset, its animation, the tile
     * 9 collision and the completion condition are all unchanged and already
     * correct; only this bound was blocking them from ever being reached.
     *
     * Ordinary camera behaviour is unaffected wherever the camera is not already
     * clamped at the right edge: camera_x = unkX - 64 is below both limits for
     * every position left of that, and the bound only widens the clamped region.
     */
    if (app_update_camera_horizontal_to_limit(
            app,
            (level_width + 1) * BOUNCE_TILE_SIZE
                - BOUNCE_CAMERA_E_BUFFER_WIDTH
        ) != 0)
        return -1;
    /*
     * STEP 12X-I-FIX: e.java:310 LoadSpriteSheet() -> b.java:645/:658 ->
     * CreateTiles() -> b.java:461 `this.z = true`, for the columns this call
     * newly exposed.
     *
     * ORDER IS THE REQUIREMENT, not an accident. Java runs LoadSpriteSheet at
     * e.java:310, i.e. AFTER the exit-visibility test at e.java:286, so the value
     * it produces is first visible to the NEXT tick's gate. Placing the call
     * here, at the end of this routine, reproduces that: the physics-branch door
     * gate at :5590 has already run by the time its caller reaches this function
     * at :5611, so the current tick's gate cannot observe a value Java would not
     * yet have produced, and the following tick's gate can.
     *
     * The latch is monotone, so this can only ever turn a door that Java would
     * already have latched one tick earlier into the same state. It cannot
     * produce a value Java never produces, and it cannot clear one.
     */
    app_note_exposed_exit_b_z(app, previous_l);
    return 0;
}

/*
 * STEP 63 -- b.z PRODUCER. Java b.java:461, reproduced as a state production.
 *
 * WHAT THIS IS. Java sets b.z inside `case 9:` of CreateTiles(int,int,int,int)
 * (b.java:455-462), i.e. while rasterising a tile-9 cell, the exit door. The
 * tile identity test that reaches :461 is decided at b.java:406/:412, BEFORE
 * any drawing, and the arm is straight-line: no `if`, no `return`, no `break`
 * between :455 and :461. STEP 57 §4.1 established that z production is
 * therefore logically independent of drawing success, and STEP 57 §9 that the
 * whole verdict needs only {l, k, LevelTiles, width, height}. So the producer
 * is a TILE SCAN, not a traversal and not a draw: no E-buffer, no surface, no
 * sprite lookup, no clip, and no use of v, Z or G (STEP 57 §3.3 answers 2-7,
 * all NO).
 *
 * WHY IT LIVES HERE. This is the callee boundary STEP 56 identified at :5055
 * and the adoption site STEP 57 §11 specified: inside
 * app_update_camera_for_width(), immediately after the two vertical k loops and
 * before `return 0`, which is the same lifecycle position as Java's
 * `f()` at e.java:150 -- itself the first statement after e.java:149. At this
 * point app->l is final (:4973) and app->k is final (:5054), which is what
 * STEP 55's SAME-TICK requirement needs: the gate at :5206/:5553 then reads the
 * value produced from the camera this very tick, never the previous one.
 *
 * THE WINDOW. Java b.f() (b.java:602-607) is
 *
 *     for (byte b1 = 0; b1 < 13; b1++)
 *         for (byte b2 = 0; b2 < 8; b2++)
 *             CreateTiles(this.l + b1, this.k + b2, b1 * 12, b2 * 12);
 *
 * so 13 columns x 8 rows, i.e. [l, l+12] x [k, k+7] inclusive (STEP 57 §11
 * item 5). Both extents are derived here from the camera constants the file
 * already owns rather than re-spelled as new magic numbers:
 * BOUNCE_CAMERA_E_BUFFER_WIDTH is 156 = 13 tiles and BOUNCE_CAMERA_GATE_HEIGHT
 * is 96 = 8 tiles. Java scans for ANY tile-9 cell in the window, not for a
 * nominated door cell (STEP 57 §7), and that general form is what is
 * implemented; STEP 50's tile scan found the tile-9 set is exactly the door's
 * 2x2 block in all 11 original levels, so the two forms coincide on the
 * original data, but the general scan is the source's own form.
 *
 * THE RANGE GUARD is b.java:401-404, the only early return in CreateTiles:
 *
 *     if (paramInt1 < 0 || paramInt2 < 0
 *         || paramInt1 >= this.TODO_width || paramInt2 >= this.TODO_height)
 *
 * TODO_width/TODO_height are the LevelTiles extents, so the bound used here is
 * the runtime tile grid's own width and height, which is the same pair the
 * accessor indexes.
 *
 * WHAT IS DELIBERATELY NOT REPRODUCED.
 *
 *  1. b.java:405 MUTATES LevelTiles, clearing the 0x80 dirty bit. That write is
 *     part of Java's dirty-pass bookkeeping, not of the z verdict, and it is
 *     not reproduced: native has no dirty pass at all
 *     (bounce_level_tile_value_set_dirty at level.c:467 is defined and never
 *     called). The bit is masked off on read instead, exactly as the existing
 *     native tile reads do at :2506-2507.
 *  2. The remaining 103 CreateTiles arms -- drawing, pickups, blocking, kill
 *     checks -- are not adopted (STEP 57 §11 [F]).
 *  3. b.z is a latch, so once true the verdict cannot change and the scan may
 *     stop early. This is an exact short-circuit of a monotone latch, not a
 *     behavioural difference: Java also never re-clears it except from inside
 *     the gate's own M-arm (e.java:288), which this native gate cannot reach
 *     once door_open_flag is true.
 */
static void app_produce_b_z(BounceApp *app)
{
    const int32_t rows = BOUNCE_CAMERA_GATE_HEIGHT / BOUNCE_TILE_SIZE;
    const int32_t cols = BOUNCE_CAMERA_E_BUFFER_WIDTH / BOUNCE_TILE_SIZE;
    uint32_t width;
    uint32_t height;
    int32_t row;
    int32_t col;

    if (app == NULL || app->runtime == NULL)
        return;
    /* The latch is already set: W2 has no clearing counterpart here. */
    if (app->b_z)
        return;
    width = bounce_runtime_level_tiles_width(app->runtime);
    height = bounce_runtime_level_tiles_height(app->runtime);
    for (row = 0; row < rows; row++) {
        for (col = 0; col < cols; col++) {
            int32_t x = app->l + col;
            int32_t y = app->k + row;
            uint16_t value = 0;
            uint32_t tile_id;

            /* b.java:401-404 -- the only early return in CreateTiles. */
            if (x < 0
                || y < 0
                || (uint32_t)x >= width
                || (uint32_t)y >= height)
                continue;
            if (bounce_runtime_level_tiles_get(
                    app->runtime,
                    (int)x,
                    (int)y,
                    &value) != 0)
                continue;
            tile_id = (uint32_t)value;
            /* b.java:405-409: clear the dirty bit, then the water bit. Native's
             * existing tile reads apply the same two masks, in this order, at
             * :2506-2507. */
            tile_id &= ~UINT32_C(0x40);
            tile_id &= ~UINT32_C(0x80);
            /* b.java:412 `case 9` -> b.java:461 `this.z = true`. */
            if (tile_id == 9u) {
                app->b_z = true;
                return;
            }
        }
    }
}

static int app_update_camera_for_width(
    BounceApp *app,
    int32_t level_width
)
{
    if (app_update_camera_horizontal_for_width(app, level_width) != 0)
        return -1;

    /* These are the recovered e.e() vertical camera loops. */
    while (java_int32_add(app->player.TODO_unkY, -6)
        < app->k * BOUNCE_TILE_SIZE)
        app->k -= BOUNCE_CAMERA_VERTICAL_STEP;
    while (java_int32_add(app->player.TODO_unkY, 6)
        > java_int32_add(app->k * BOUNCE_TILE_SIZE, BOUNCE_CAMERA_GATE_HEIGHT))
        app->k += BOUNCE_CAMERA_VERTICAL_STEP;

    /*
     * STEP 63 -- b.z producer, at the STEP 56 CALLEE-BOUNDARY. Position is
     * exact and load-bearing: this is the first statement after the k loops
     * (:5054) and precedes `return 0`, which is Java's e.java:150 f() sitting
     * immediately after e.java:149. app->l and app->k are both final here
     * (:4973 and :5054), so the value the gate reads later on this same tick is
     * derived from the camera this tick -- STEP 55 SAME-TICK CAMERA REQUIRED.
     * It also runs on the two other Role-A callers, load-time and respawn, with
     * no caller-side cooperation (STEP 57 §11 item 7), which is what makes the
     * load-time case I4-LOAD-PERSISTENT reachable at all (STEP 58 §15).
     *
     * The call cannot fail, so the existing return value and control flow of
     * this function are unchanged.
     */
    app_produce_b_z(app);
    return 0;
}

static int app_update_camera(BounceApp *app)
{
    if (app == NULL || app->level == NULL)
        return -1;
    /*
     * Uses e.e()'s width*12-156 boundary (e.java:139), which is what this
     * routine is: e() clamps with the narrower expression.
     *
     * STEP 12X-F2-B: the previously-unresolved LoadSpriteSheet alternate
     * (width+1)*12-156 (b.java:631-632) is now implemented, in
     * app_update_camera_horizontal(), which is the routine that plays the
     * LoadSpriteSheet role. This e.e()-equivalent function deliberately keeps the
     * narrow bound, because substituting the wide one here would invent a third
     * bound that no recovered source line states.
     */
    return app_update_camera_for_width(
        app,
        (int32_t)bounce_level_width(app->level)
    );
}

static bool app_camera_needs_update(const BounceApp *app)
{
    if (app == NULL)
        return false;
    return java_int32_add(app->player.TODO_unkY, -6)
        < app->k * BOUNCE_TILE_SIZE
        || java_int32_add(app->player.TODO_unkY, 6)
        > java_int32_add(app->k * BOUNCE_TILE_SIZE, BOUNCE_CAMERA_GATE_HEIGHT);
}

/*
 * Thin physics continuation for the new canonical 40 ms timer path.
 *
 * This is the exact sequence the previously working app_run_player_ticks()
 * executed for the player branch (vertical_slice.c:2199-2213), reusing the same
 * unmodified functions:
 *
 *   update_horizontal is captured BEFORE the vertical step, exactly as the
 *   legacy path did, because app_step_vertical() may change player.z;
 *   app_step_vertical()            f.b() from f.java:670
 *   app_step_horizontal()          existing horizontal physics/input/collision
 *   app_update_camera_horizontal() e.java:310 LoadSpriteSheet hand-off
 *
 * Deliberately absent: app_run_player_ticks(), app_update_game(), any
 * app_update_camera() call, and bounce_dyn_thorns_update(). The legacy scheduler
 * is bypassed, not modified.
 */
static int app_player_physics_continuation(BounceGame *game, void *context)
{
    BounceApp *app = (BounceApp *)game;
    bool gravity_inverted;
    bool update_horizontal;

    (void)context;
    if (app == NULL)
        return -1;

    /* Legacy order: sampled before the vertical step can change z. */
    update_horizontal = app->player.z != 2;
    if (app_step_vertical(app, &gravity_inverted) != 0)
        return -1;
    if (update_horizontal
        && app_step_horizontal(app, gravity_inverted) != 0)
        return -1;

    /*
     * DEATH CORE RESPAWN BOUNDARY -- e.java:267-281.
     *
     * Source position: inside the synchronized(aq) region, immediately after the
     * aq.b() branch at e.java:265 and BEFORE UpdateDynThorns() at e.java:282.
     * That is exactly where this sits: after the two physics steps, before the
     * dyn-thorn switch below.
     *
     * Reached only when z just became 1, because while z == 2 app_step_vertical()
     * returned at f.java:665 and app_step_horizontal() was skipped by
     * `update_horizontal = app->player.z != 2` -- the structural equivalent of the
     * source's f.java:658-666 early return.
     *
     * Return values from app_respawn_after_death():
     *    0  respawned; play continues on the next tick
     *    1  the e.java:268 game-over boundary; see below
     *   -1  error
     *
     * GAME OVER BOUNDARY -- DEFERRED, deliberately. e.java:268-272 is
     *
     *   if (this.lives < 0) { this.game.WriteToStore(); StopGameTimer();
     *                          this.game.TODO_ShowInstructions(false); return; }
     *
     * WriteToStore() is persistence and is out of scope for this milestone, and
     * TODO_ShowInstructions -> ShowGameEnd is a UI destination that does not exist
     * natively, so neither is fabricated. StopGameTimer() (e.java:270) IS
     * implemented, because it is neither of those and it is what makes the arm
     * observable: see app_respawn_after_death().
     *
     * f.java:662-663 (`if (this.n.lives < 0) this.n.e = true;`) is also not
     * written. In the source it has no observable effect: it runs during the
     * countdown, but e.java:272 returns before e.Tick() can reach the only
     * reader of that flag at e.java:313, and the timer has by then been stopped.
     */
    if (app->player.z == 1) {
        int respawn = app_respawn_after_death(app);

        /*
         * STEP 13E -- emitted for both arms: respawn == 0 is the checkpoint
         * restore, respawn == 1 is the game-over boundary. The two are reported
         * with the same RESPAWN tag and are told apart by the flow transition
         * the observer prints next, which keeps "death vs game over" visible
         * without the tracker deciding which happened. Observation only.
         */
        bounce_debug_event_respawn(app_debug(app), app);
        if (respawn < 0)
            return -1;
        if (respawn == 1) {
            /* GAME OVER / PERSISTENCE BOUNDARY -- DEFERRED. */
            return 0;
        }
    }

    /*
     * e.java:282-283, still inside the synchronized(aq) region and still AFTER
     * aq.b(): `if (this.DynThornsCount != 0) UpdateDynThorns();`.
     *
     * The update runs on the runtime owner only. It is placed here, between the
     * player physics and the LoadSpriteSheet-equivalent hand-off, because that is
     * the source position. The count is recorded only when the source guard
     * allowed the call to run.
     */
    switch (bounce_runtime_level_tiles_update_dyn_thorns(app->runtime)) {
        case 1:
            if (bounce_game_timer_record_dynamic_thorn_update(
                    &app->game_timer) != 0)
                return -1;
            break;
        case 0:
            /* Source skipped the call entirely: no dynamic thorns. */
            break;
        default:
            return -1;
    }

    /*
     * STEP 12F — Door animation update.
     *
     * Placed after player physics/collision to preserve the verified tick order:
     * collision → dynamic thorns → hoop completion → door animation.
     * The door cannot trigger finish in the same tick it opens.
     */
    /*
     * D-09 -- e.java:286-297, THE WHOLE GATE, IN THE SOURCE'S OWN SHAPE.
     *
     *     286:  if (this.TODO_ExitUnlocked && this.z
     *     287:          && (this.exitX + 1) * 12 > m() && this.exitX * 12 < g()) {
     *     288:          if (this.M) {
     *     289:              this.z = false;
     *     290:              this.TODO_ExitUnlocked = false;
     *     291:          } else {
     *     292:              h();
     *     293:          }
     *     294:          ... four cells |= 0x80 ...
     *     297:      }
     *
     * THE THREE OPERANDS AND THE BRANCH. The gate tests exactly three things --
     * TODO_ExitUnlocked, b.z and the camera window -- and then BRANCHES on M. It
     * does not test M in the condition.
     *
     * THE OLD NATIVE GATE COULD ONLY EVER TAKE THE `else` PATH, which is D-09.
     * It read
     *
     *     if (TODO_ExitUnlocked && door_animation_active && !door_open_flag && b_z)
     *
     * so the moment h() set M -- i.e. the moment door_open_flag became true --
     * the `!door_open_flag` operand turned the gate off, and the clear at :288-290
     * was unreachable on every tick of every run. door_animation_active was a
     * NATIVE-ADDED operand with no Java counterpart: game.h claimed it was "the
     * `else h()` arm of the gate (e.java:291), i.e. it is Java's `!M`", which is
     * the error this removes. Java has no `!M` operand; it has an `if (M) clear
     * else h()` BODY, and standing the branch up as an operand is what suppressed
     * it. The field is removed rather than left unread.
     *
     * THE TWO-TICK SEQUENCE IS NOW THE SOURCE'S. Tick N advances the animation
     * and may set M. Tick N+1 takes the clear branch, which is what makes the exit
     * a ONE-SHOT: afterwards b_z is false -- and b.z is a per-frame render latch
     * (b.java:461, set by rasterising a tile-9 cell) -- so the gate goes quiet on
     * its own, exactly as in Java.
     */
    if (app->TODO_ExitUnlocked && app->b_z) {
        int32_t exit_x = (int32_t)bounce_level_exit_x(app->level);
        int32_t camera_left = app->l * BOUNCE_TILE_SIZE - app->v;
        int32_t camera_right = camera_left + 128;
        bool exit_visible = ((exit_x + 1) * 12 > camera_left)
            && (exit_x * 12 < camera_right);
        if (exit_visible) {
            if (app->door_open_flag) {
                /* e.java:288-290 -- the one-shot clear. */
                app->b_z = false;
                app->TODO_ExitUnlocked = false;
            } else {
                /*
                 * e.java:292, b.h() at b.java:824-831:
                 *
                 *     public void h() {
                 *         this.b += 4;
                 *         if (this.b >= 24) {
                 *             this.b = 24;
                 *             this.M = true;
                 *         }
                 *         p();
                 *     }
                 *
                 * The three state writes are reproduced; p() redraws the 24x24
                 * door image, which native does every frame anyway and so has
                 * nothing to do here.
                 */
                app->door_image_offset += 4;
                if (app->door_image_offset >= 24) {
                    app->door_image_offset = 24;
                    app->door_open_flag = true;
                }
            }
            /*
             * D-08 -- e.java:294-297's `|= 0x80` on the ball's 2x2 IS DELIBERATELY
             * NOT REPRODUCED, and the reason is that it is a RENDER-INVALIDATION
             * bit with no reader in this architecture.
             *
             * Bit 0x80 is written in three places in Java -- b.java:384 (k(), the
             * change log), b.java:405 (clearing it) and f.java:482/:484/:494/:495/
             * :615 (the crystal and boost tiles) -- and READ in exactly one:
             *
             *     b.java:616   if ((this.LevelTiles[j][i] & 0x80) != 0)
             *                      CreateTiles(i, j, b1 * 12, b2 * 12);
             *
             * inside b.i(), the method that rasterises the tiles. So the bit marks
             * which cells need re-rasterising, and nothing else consults it: the
             * collision path masks it off (f.java:431,
             * `int tileId = this.n.LevelTiles[tileY][tileX] & (~0x40) & (~0x80)`),
             * and native does the same at player.c:399 and in collision_query.c.
             *
             * Native redraws the whole window every loop iteration, so there is no
             * invalidation cache for the bit to invalidate, and reproducing it
             * would add state with no reader.
             *
             * IT CANNOT AFFECT THE RESUME SNAPSHOT EITHER. Record 3 carries the
             * ball's tile (BounceGame.java:375-376) and the tile DELTAS computed by
             * k() (:380-397) -- never the raw grid -- and k() reads the tile id with
             * the flag already stripped, so a 0x80 set or not is invisible to what
             * is persisted. That is the check this note is here to record: the one
             * place where the bit might have mattered was the snapshot, and it does
             * not.
             */
        }
    }

    if (app_update_camera_horizontal(app) != 0)
        return -1;
    return 0;
}

/*
 * GAMEPLAY HUD -- e.java:174-189, the block guarded by `if (this.y)`.
 *
 * Source, transcribed element by element:
 *
 *   e.java:175      this.X.setColor(0x0853aa);
 *   e.java:176      this.X.fillRect(0, 97, 128, 32);
 *   e.java:177      for (byte b1 = 0; b1 < this.lives; b1++)
 *   e.java:178          this.X.drawImage(this.imageBall,
 *   e.java:178              5 + b1 * (this.imageBall.getWidth() - 1), 99, TOP|LEFT);
 *   e.java:179      for (byte b2 = 0; b2 < this.HoopsTotal - this.HoopsScored; b2++)
 *   e.java:180          this.X.drawImage(this.imageHoop,
 *   e.java:180              5 + b2 * (this.imageHoop.getWidth() - 4), 112, TOP|LEFT);
 *
 * SPACING. imageBall and imageHoop are both CreateTiles() crops, i.e. one
 * 12x12 atlas cell: b.java:772 `imageBall = CreateTiles(ss, 2, 1)` and
 * b.java:773 `imageHoop = CreateTiles(ss, 1, 4)`, and the native crops are
 * visual_tile_from_atlas() at BOUNCE_ATLAS_TILE_SIZE. getWidth() is therefore
 * 12 in both, so the source's multipliers are literal:
 *
 *   lives  x = 5 + i * (12 - 1) = 5 + i * 11,  y = 99
 *   hoops  x = 5 + i * (12 - 4) = 5 + i *  8,  y = 112
 *
 * The two are DIFFERENT pitches on purpose: the source uses -1 for the ball and
 * -4 for the hoop, so the rows are not aligned to a common column grid and the
 * icons overlap by design. That is preserved rather than tidied.
 *
 * REMAINING HOOPS is HoopsTotal - HoopsScored, i.e. the count still to collect,
 * NOT the number collected. e.java:179 is the only HUD reader of either field.
 *
 * SCREEN SPACE. The source draws this on imageFullscreen (e.java:71, a 128x128
 * image) after widening the clip from 128x96 to 128x128 at e.java:173, so the
 * HUD is fixed to the screen and is not affected by l / k / v. The native
 * reproduces that by resetting the clip -- draw_level_grid() installs the
 * Step 12I world window at :3800 -- and then drawing in surface coordinates.
 * BOUNCE_SURFACE_WIDTH/HEIGHT are both 128, the same as imageFullscreen.
 *
 * NOT IMPLEMENTED, and why -- no state is invented for any of these:
 *
 *   e.java:183  drawString(PadZeroes(this.score), 64, 100, TOP|LEFT)
 *       `score` has no native counterpart at all: there is no score field, no
 *       AddScore(), and none of the three real score sources
 *       (f.java:229 hoop +500, f.java:481 crystal +200, f.java:610 extra life
 *       +1000) nor e.java:318 (+5000 on completion) exists. Adding one would be
 *       new gameplay state, which this task forbids, and the HUD must read
 *       canonical state rather than keep a copy. DEFERRED with the score.
 *       e.java:45 `Font.getFont(32, 0, 8)` is an 8px system font that has no
 *       native equivalent either, so the digits could not be drawn faithfully
 *       even if a score existed.
 *
 *   e.java:184-187  the boostTimer bar
 *       `boostTimer` (e.java:298-308) has no native counterpart either. DEFERRED
 *       with the boost timers.
 *
 *   e.java:174 / e.java:188  the `this.y` dirty flag
 *       `y` is the game's score/HUD dirty flag and, as the Death Core audit
 *       recorded, the native has no `y` field. The source therefore redraws this
 *       band only when something changed. The native redraws it every frame, which
 *       is output-equivalent because the band's content is a pure function of
 *       lives, HoopsTotal and HoopsScored: no native producer sets a dirty bit
 *       for it, and adding one would mean adding the state this task forbids.
 */
/*
 * D-13 / J-01 -- THE LEVEL-START BANNER.
 *
 * JAVA EVIDENCE, e.java:192-207 in full for the non-splash arm:
 *
 *     } else {
 *         paramGraphics.drawImage(this.imageFullscreen, 0, 0, 20);
 *         if (this.p != 0) {
 *             paramGraphics.setColor(0xfffffe);
 *             paramGraphics.setFont(this.font);
 *             paramGraphics.drawString(this.LevelString, 44, 84, 20);
 *         }
 *     }
 *
 * and `this.p` is the countdown InitializeGame() arms at e.java:119
 * (`this.p = 120;`), which e.java:258-259 then decrements once per tick
 * (`if (this.p != 0) this.p--;`). Its native counterpart already exists and is
 * already maintained on the right tick: app_flow.c's
 * bounce_app_flow_tick_pre_countdown(), called from bounce_game_tick_dispatch
 * after the reset and splash gates, exactly as e.java:258 sits after e.java:222
 * and e.java:227. It simply had no reader outside the verifiers, which is what
 * the J-01 search recorded.
 *
 * POSITION, COLOUR AND ANCHOR ARE THE SOURCE'S. The banner is drawn at (44, 84)
 * with colour 0xfffffe -- COLOR_HUD_SCORE below is TOKEN(255,255,254), which is
 * that literal -- under anchor 20 = Graphics.TOP | Graphics.LEFT, so it is
 * top-left and runs right rather than being centred.
 *
 * WHICH LEVEL IS NAMED. Java formats LevelString once, at LoadLevelId time,
 * from `Integer.valueOf(this.level)` (b.java:216-217). `this.level` is advanced
 * later, in the completion block at e.java:317, so the string always names the
 * level that is on screen. app->level_id is the LOADED level at render time --
 * the same argument bounce_ui_shell_render_level_complete already relies on at
 * ui_shell.h:236-238 -- so it names the same level.
 *
 * WHY IT IS DRAWN AFTER draw_hud. In Java, paint() blits imageFullscreen, which
 * already contains BOTH the 128x96 world and the 128x32 HUD band, and only then
 * draws the banner, so the banner is on top of everything. draw_hud() is the
 * last world/HUD step in render_gameplay_scene, so drawing after it reproduces
 * that stacking exactly. The clip is reset first, because draw_hud leaves the
 * full 128x128 clip installed (e.java:173) and draw_level_grid() had narrowed it
 * to the 128x96 world window; the banner sits at y=84..91, which is inside the
 * world rows, so it must not inherit a narrower clip than Java had.
 *
 * The banner is deliberately NOT part of the HUD dirty-flag story. Java gates
 * the whole HUD block on `y` (e.java:174) but draws the banner in paint(),
 * outside q() and outside that gate, keyed only on `p`. Native re-renders the
 * frame every loop iteration, so a dirty flag would be a second, redundant
 * invalidation model; the countdown itself is the gate, as in the source.
 */
static int draw_level_banner(BounceRenderer *renderer, const BounceApp *app)
{
    if (renderer == NULL || app == NULL)
        return -1;

    /* e.java:201 -- `if (this.p != 0)`. */
    if (bounce_app_flow_entry_countdown(&app->flow) == 0)
        return 0;

    if (bounce_renderer_reset_clip(renderer) != 0)
        return -1;
    return bounce_ui_shell_render_level_banner(
        renderer,
        app->level_id,
        COLOR_HUD_SCORE
    );
}

static int draw_hud(BounceRenderer *renderer, const BounceApp *app)
{
    int remaining;
    int index;

    if (renderer == NULL || app == NULL)
        return -1;
    /*
     * Tolerant of an absent level or asset set, exactly as draw_player_ball() is
     * at :4090. A verification that renders without a loaded level or without
     * visuals must still get its frame; the HUD simply contributes nothing. The
     * failure return is reserved for a NULL renderer, which is a real error.
     */
    if (app->visuals == NULL || app->level == NULL)
        return 0;

    /* e.java:173 -- the HUD is drawn with the clip widened back to the full
     * 128x128 surface, undoing the 128x96 game window at e.java:161 and the
     * native world window installed by draw_level_grid(). */
    if (bounce_renderer_reset_clip(renderer) != 0)
        return -1;

    /* e.java:175-176 */
    if (bounce_renderer_fill_rect(renderer, 0, 97, 128, 32, COLOR_HUD_BAND) != 0)
        return -1;

    /* e.java:177-178 -- one ball icon per remaining life. */
    for (index = 0; index < app->lives; ++index) {
        if (bounce_visual_assets_draw_hud_ball(
                renderer,
                app->visuals,
                5 + index * 11,
                99
            ) != 0)
            return -1;
    }

    /* e.java:179-180 -- one hoop icon per hoop still to collect. */
    remaining = (int)bounce_level_hoops_total(app->level) - app->hoops_scored;
    for (index = 0; index < remaining; ++index) {
        if (bounce_visual_assets_draw_hud_hoop(
                renderer,
                app->visuals,
                5 + index * 8,
                112
            ) != 0)
            return -1;
    }

    /*
     * STEP 12X-HUD-SCORE-IMPL-B -- e.java:181-183.
     *
     *     this.X.setColor(0xfffffe);
     *     this.X.setFont(this.font);
     *     this.X.drawString(PadZeroes(this.score), 64, 100, Graphics.TOP | Graphics.LEFT);
     *
     * Placed after the hoop loop because that is where the source draws it, although the
     * three rows do not overlap so the order is not visually load-bearing.
     *
     * The LIVE score is read here, exactly as the lives and hoop rows above read their own
     * live state. There is no second copy and no invalidation: the source gates this block on
     * `e.y` (e.java:174), but native redraws and re-presents the whole frame on every loop
     * iteration (vertical_slice.c:16409-16422), so the value read now is the value displayed
     * now. A dirty flag here would be a second, redundant invalidation model.
     *
     * The origin is the source's own (64, 100), passed through unmodified; the seam never
     * re-centres or shifts it for the formatted length. Formatting, the 6px pitch and the
     * digit shapes all live in the visual-asset HUD seam, so this is the single gameplay
     * integration point and draw_hud keeps no copy of the formatted text.
     */
    if (bounce_visual_assets_draw_hud_score(
            renderer,
            64,
            100,
            app->score,
            COLOR_HUD_SCORE
        ) != 0)
        return -1;

    /*
     * STEP 40 -- BOOSTBAR. e.java:298-305 and e.java:184-187.
     *
     * THE DERIVATION, e.java:298-305, verbatim:
     *
     *   this.boostTimer = 0;
     *   if (this.aq.TODO_somePowerUp1 != 0 || this.aq.powerUpGravity != 0
     *           || this.aq.TODO_somePowerUp3 != 0) {
     *       if (this.aq.TODO_somePowerUp1 > this.boostTimer)
     *           this.boostTimer = this.aq.TODO_somePowerUp1;
     *       if (this.aq.powerUpGravity > this.boostTimer)
     *           this.boostTimer = this.aq.powerUpGravity;
     *       if (this.aq.TODO_somePowerUp3 > this.boostTimer)
     *           this.boostTimer = this.aq.TODO_somePowerUp3;
     *   }
     *
     * So boostTimer is the running MAXIMUM of the three active-power-up timers.
     * It is not a fourth timer: it has no writer anywhere else, no decrement of
     * its own, and no other reader. It exists only to drive this bar, which is
     * why it is derived here rather than stored. All three inputs already exist
     * natively and are read, never written:
     *
     *   TODO_somePowerUp1  f.java:642 = 300 (tile 38),   :800-802 decrements
     *   powerUpGravity     f.java:631 = 300 (tiles 47-50), :687-692 decrements
     *   TODO_somePowerUp3  f.java:637 = 300 (tiles 51-54), :699-706 decrements
     *
     * The e.java:299 guard is not reproduced as a separate test because it is
     * unobservable: all three timers are set to 300 and then only ever counted
     * down to zero (each decrement site is guarded by `!= 0`), so none can be
     * negative and the three `>` comparisons already leave boostTimer at 0
     * exactly when the source's guard would have skipped the whole block. The
     * e.java:306-307 side effect inside that block (`boostTimer % 30 == 0 ||
     * boostTimer == 1 -> this.y = true`) is likewise absent: `y` is the HUD
     * dirty flag, which has no native counterpart and which draw_hud's own
     * comment above (:5218-5220) explains is redundant here.
     *
     * THE BAR, e.java:184-187, verbatim:
     *
     *   if (this.boostTimer != 0) {
     *       this.X.setColor(0xff9813);
     *       this.X.fillRect(1, 128 - 3 * this.boostTimer / 30, 5, 128);
     *   }
     *
     * Every value is the source's own: x = 1, width = 5, height = 128, and the
     * y origin 128 - 3 * boostTimer / 30. The visible sliver above the canvas
     * bottom is therefore boostTimer / 10 pixels, i.e. 3 px per 10 ticks and at
     * most 30 px when a timer is at its full 300. Nothing here is invented: the
     * colour, the geometry and the divisor are all read out of e.java:186.
     *
     * `3 * boost_timer / 30` is evaluated in int with the multiply first, which
     * is the source's evaluation order and matters for the truncation: for
     * boostTimer 1..9 the quotient is 0, so the bar draws at y = 128 and is not
     * visible, exactly as in the original.
     *
     * MIDP clips a rectangle that runs past the surface; the renderer clips the
     * same way, so the height of 128 is passed through unchanged rather than
     * clamped, which keeps the two implementations doing the same thing instead
     * of agreeing by accident.
     *
     * Placed after the score because that is where the source draws it. This is
     * purely informational: it reads state and draws, and it is not a control.
     * Nothing here accepts input, and nothing was hidden or removed to add it.
     */
    {
        int boost_timer = 0;

        if (app->player.TODO_somePowerUp1 > boost_timer)
            boost_timer = app->player.TODO_somePowerUp1;
        if (app->player.powerUpGravity > boost_timer)
            boost_timer = app->player.powerUpGravity;
        if (app->player.TODO_somePowerUp3 > boost_timer)
            boost_timer = app->player.TODO_somePowerUp3;

        if (boost_timer != 0
            && bounce_renderer_fill_rect(
                   renderer,
                   1,
                   128 - 3 * boost_timer / 30,
                   5,
                   128,
                   COLOR_HUD_BOOST_BAR
               ) != 0)
            return -1;
    }

    return 0;
}

/*
 * Native Tick-dispatch driver:
 *   verified timer callback (GAME_TIMER_CALLBACK -> TICK ENTRY)
 *     -> bounce_game_tick_dispatch (pre-dispatch gates, p--, camera gate)
 *     -> PLAYER TICK DISPATCH boundary
 *     -> STOP
 *
 * The camera condition is supplied by app_camera_needs_update(), the already
 * verified CLOSED implementation, so no camera formula is duplicated and the
 * camera implementation is not modified.
 *
 * reset_pending and splash_active are NATIVE PRECONDITIONS, supplied as false:
 * `d` is cleared by LoadLevelId (b.java:213) and its only setters (e.java:316,
 * :340, :345) are unreachable in the staged path, and SplashId is -1 from
 * e.java:246 onward while the native splash is the already-verified
 * BOUNCE_APP_STATE_SPLASH application path. The gates stay explicit parameters
 * of bounce_game_tick_dispatch() so they are never deleted, only satisfied.
 *
 * This driver deliberately does NOT call app_update_game(), so the legacy
 * app_run_player_ticks() catch-up path is never reached and no physics runs.
 */
static int app_timer_callback_dispatch(
    BounceApp *app,
    BounceTickDispatchBranch *branch_out
)
{
    BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
    int rc;

    if (app == NULL)
        return -1;
    if (bounce_game_timer_callback(&app->game_timer) != 0)
        return -1;
    rc = bounce_game_tick_dispatch(
        app,
        /*
         * STEP 65-B2 -- the literal `false` this slot has always carried is
         * replaced by the live latch. The comment above recorded the slot as a
         * precondition "supplied as false" because it could prove that e.java:316
         * was the only reachable setter of `d` in the staged path. STEP 65-B2
         * makes the other two reachable -- e.java:340 ('1') and :345 ('3'), the
         * af-gated level-skip keys -- so the slot now has a real producer.
         *
         * NO OTHER ARGUMENT CHANGES. splash_active stays false because
         * SplashId is still -1 from e.java:246 onward; the camera gate keeps
         * deriving from live player state; the body, context and branch_out are
         * untouched.
         *
         * The latch is one-shot and is cleared by the RESET_GATE arm below once
         * its reload and camera have both succeeded, so it cannot be observed
         * true on a second consecutive tick.
         */
        app->af_reload_requested,
        false,
        app_camera_needs_update(app),
        app_player_physics_continuation,
        NULL,
        &branch
    );
    if (rc != 0)
        return rc;
    if (branch_out != NULL)
        *branch_out = branch;
    /*
     * e.java:262-266. The source selects e() INSTEAD OF this.aq.b(); the two arms
     * are mutually exclusive and neither returns before the other runs. The
     * dispatch runs no game step of its own, so the camera update for the gated
     * tick is supplied here, by the layer that owns the file-local
     * app_update_camera(). BOUNCE_TICK_DISPATCH_CAMERA is set only by the gate
     * arm, so this is mutually exclusive with app_player_physics_continuation(),
     * and app_update_camera() is never reached on a physics tick.
     */
    if (branch == BOUNCE_TICK_DISPATCH_CAMERA) {
        /*
         * STEP 62 -- I2 CAMERA-TICK CADENCE SEAM.
         *
         * Java's finish gate is at e.java:286, OUTSIDE the e.java:262-266
         * if/else, so the source runs it on the camera tick AND on the physics
         * tick. The native gate at :5206 lives inside
         * app_player_physics_continuation(), which bounce_game_tick_dispatch()
         * skips entirely when camera_gate_needed is set (game.c:959-963 returns
         * before the body). That is the I2-CADENCE-GAP of STEP 59: the tick on
         * which l/v/k change is a tick on which the gate does not run.
         *
         * This restores the missing cadence arm. ORDERING is the STEP 60
         * requirement: app_update_camera() finalises app->l (:4973), app->v
         * (:4974-4976) and app->k (:5051/:5054) and returns through :5055
         * BEFORE this block is reached, so the gate observes the same fresh
         * camera state that Java's e() -> f() -> gate chain observes on a camera
         * tick. :5055 itself is untouched.
         *
         * DUPLICATION IS DELIBERATE. STEP 61 proved the gate block is a pure
         * function of `app`: three app-> field reads plus the pure accessor
         * bounce_level_exit_x(const BounceLevel *) at level.c:179, which takes a
         * const pointer and performs a single return with no writes. STEP 61 also
         * proved duplication and helper extraction semantically equivalent, and
         * recorded that the choice of form is NOT determined by the recovered
         * source. Duplication is used because it is the smaller source surface:
         * the physics-tick gate at :5206-5222 stays byte-identical, no new
         * function is introduced, and no existing call-graph node is altered.
         *
         * WHAT THIS IS NOT. Java's gate has FOUR operands -- e.java:286 reads
         * TODO_ExitUnlocked, z, (exitX+1)*12 > m() and exitX*12 < g(). The `z`
         * operand has NO native counterpart and is NOT supplied here. b.z remains
         * an independent unresolved gap (STEP 48/52 MISSING; STEP 55 same-tick
         * camera REQUIRED; STEP 56 producer boundary :5055; STEP 57
         * ISOLATED-PRODUCER-VALID; STEP 58 I4-LOAD-PERSISTENT). This block
         * restores CADENCE ONLY and does NOT claim full Java gate equivalence.
         */
        rc = app_update_camera(app);
        if (rc != 0)
            return rc;
        /*
         * D-09 -- THE SECOND COPY OF THE GATE, kept byte-identical in BEHAVIOUR
         * to the one in app_player_physics_continuation(). STEP 61 established
         * that the gate block is a pure function of `app` and that duplication
         * and extraction are equivalent; the Java citations, the one-shot clear
         * and the D-08 non-reproduction note therefore live at the first copy and
         * are not repeated here. What matters is that both copies branch on
         * door_open_flag the same way, so the animation completes and is consumed
         * on the same tick whichever path the frame took.
         */
        if (app->TODO_ExitUnlocked && app->b_z) {
            int32_t exit_x = (int32_t)bounce_level_exit_x(app->level);
            int32_t camera_left = app->l * BOUNCE_TILE_SIZE - app->v;
            int32_t camera_right = camera_left + 128;
            bool exit_visible = ((exit_x + 1) * 12 > camera_left)
                && (exit_x * 12 < camera_right);
            if (exit_visible) {
                if (app->door_open_flag) {
                    app->b_z = false;
                    app->TODO_ExitUnlocked = false;
                } else {
                    app->door_image_offset += 4;
                    if (app->door_image_offset >= 24) {
                        app->door_image_offset = 24;
                        app->door_open_flag = true;
                    }
                }
            }
        }
        return 0;
    }
    /*
     * STEP 65-B2 -- the RESET_GATE arm, i.e. the e.java:222-226 arm of the tick.
     *
     *   e.java:222-226   if (this.d) { InitializeGame(); repaint(); return; }
     *
     * bounce_game_tick_dispatch has returned BOUNCE_TICK_DISPATCH_RESET_GATE
     * with rc 0 from exactly one place, game.c:925, and that place is reached only
     * when its `reset_pending` argument is true. Every other rc == 0 return sets
     * a different branch value (game.c:937, :961, :1009), and every rc != 0
     * return has already been handled above at :5633, so testing the branch here
     * is exactly equivalent to testing the latch. The dispatcher already
     * returned before timer_record_dispatch (game.c:970), before
     * bounce_player_tick_entry (game.c:982) and before the physics body
     * (game.c:1001), so this arm runs with NO physics having executed for this
     * tick, and returning from it ends the tick. Nothing below is reached.
     *
     * THE ORDER IS JAVA'S. InitializeGame() delegates to LoadLevelId(this.level)
     * at e.java:117 and only afterwards runs e(), which it reaches through a()
     * at e.java:121 -- the camera is recalculated from the NEW level's state,
     * never from the outgoing one. Hence the load first and the camera second;
     * reversing them would recalculate against a level that is about to be freed.
     *
     * THIS IS THE STEP 65-B LOAD PATH, MOVED, NOT A NEW ONE. The same three
     * existing operations are used in the same order -- resolve the path with
     * bounce_game_level_resource_path(), reload with bounce_game_load_level(),
     * then app_update_camera() -- and the dispatcher, bounce_game_load_level()
     * and app_update_camera() are all unmodified. What changed is only when the
     * work happens: STEP 65-B ran it inside x11_process_events(), so the reload
     * frame could still run physics on the freshly loaded level, whereas Java
     * spends a whole tick on the reload and that tick returns before physics.
     *
     * bounce_game_load_level() is state-agnostic and performs the whole
     * Java-side re-entry except the camera: it resolves the level id from the
     * path (game.c:328), builds the replacement level, runtime tile copy and
     * player before touching anything (game.c:338-349), releases the outgoing
     * level only once the replacement is ready (game.c:357), and writes
     * flow.level_id as its own existing side effect (game.c:363). It also resets
     * hoops_scored (game.c:367) and the exit flag (game.c:378), which is the
     * b.java:213 / e.java:118 clear phase, so the load is what makes the next
     * level live.
     *
     * NOT THE deferred_init PATH. bounce_game_load_level_entry() is deliberately
     * NOT used here: it writes only level, level_path, level_id, flow.level_id
     * and deferred_init (game.c:516-519, :545), so it would leave runtime == NULL
     * and the player uninitialised, and it is the wrong lifecycle for a run that
     * is continuing rather than beginning.
     *
     * THE TIMER IS NOT TOUCHED. No stop, no start, no reinitialise, no cadence
     * change: canonical_next_tick_ms is not written, next_player_tick_ms is not
     * written, and bounce_game_timer_stop(), bounce_game_timer_start() and
     * bounce_game_initialize_game_timer() are not called. bounce_game_load_level
     * contains no timer reference, so the 40 ms timer that was running on entry
     * is still running on exit and the following tick resumes normally.
     *
     * NEITHER IS THE FLOW. This arm assigns nothing to app->flow.state and
     * nothing to app->state. bounce_game_load_level() writes flow.level_id and
     * nothing else in the flow, so BOUNCE_APP_STATE_GAMEPLAY and
     * BOUNCE_GAME_STATE_PLAYING both hold throughout, exactly as
     * e.java:222-226 does inside a Tick that is already running.
     *
     * FAILURE FOLLOWS THE CALLER'S EXISTING CONVENTION, which is the one the
     * camera arm above already uses: return the error and let the frame loop's
     * existing funnel at :20450 raise x11_context.failed and exit. The camera is
     * not attempted after a failed load, so no work is ever done against an
     * invalid level, and no success is fabricated.
     *
     * THE LATCH IS CLEARED LAST, AFTER THE WORK SUCCEEDED, mirroring the one-shot
     * contract of b.d. Java clears it inside LoadLevelId at the head
     * (b.java:213), i.e. inside the load; the native load touches no latch, so
     * the smallest correct place is here. Clearing before the work would let a
     * second '1'/'3' press inside the same window queue behind a reload that had
     * not happened yet, and clearing before the camera would lose the request if
     * the camera then failed. A failed load or camera leaves the latch armed,
     * which is unreachable in practice because the error above terminates the
     * run, so no retry path is invented.
     */
    if (branch == BOUNCE_TICK_DISPATCH_RESET_GATE) {
        char level_path[64];
        int reload_failed;
        /*
         * D-22 -- LIVES SURVIVE THE AF LEVEL SKIP.
         *
         * JAVA EVIDENCE. The af level skip is e.java:339-348:
         *
         *     case 49:  this.d = true;
         *               if (this.af && --this.level < 1) this.level = 11;
         *     case 51:  this.d = true;
         *               if (this.af && ++this.level > 11) this.level = 1;
         *
         * which `d` then routes into the reset gate at the top of the NEXT tick
         * (e.java:222-226):
         *
         *     if (this.d) { InitializeGame(); repaint(); return; }
         *
         * and InitializeGame() (e.java:115-124) is, in full:
         *
         *     RunGarbageCollector();
         *     LoadLevelId(this.level);
         *     this.HoopsScored = 0;
         *     this.p = 120;
         *     this.y = true;
         *     a(initX*12+6, initY*12+6, this.BallSize, 0, 0);
         *     this.aq.a(initX, initY);
         *     this.T = true;
         *
         * `lives` IS NOT AMONG THEM. A grep of the whole tree for the field
         * yields exactly four writes -- e.java:84 (a(level,score,lives)),
         * e.java:95 (the Record 3 resume), f.java:219 (`lives--` in KillBall)
         * and f.java:611-612 (the 1-up `lives++`) -- and NONE of them is on the
         * level-skip path. Java therefore carries the live life count across an
         * af level skip purely by never writing the field, which is why the
         * count that existed before the skip is the count after it.
         *
         * WHY THE NATIVE NEEDS THIS EXPLICITLY. bounce_game_load_level()
         * releases the outgoing level first (game.c:356, which reaches
         * bounce_game_release_level's `game->lives = 0` at game.c:299) and
         * then re-zeroes the counter itself at game.c:366. Java has no such
         * teardown: RunGarbageCollector() (b.java:330-338) only nulls image and
         * tile references and never touches `lives`, which lives on the `e`
         * canvas that survives the whole operation. Native has to destroy and
         * rebuild the level, so the counter has to be carried across that
         * destruction by hand. That hand-off is this save/restore pair and
         * nothing else.
         *
         * ONLY THIS PATH NEEDS IT. The other two callers of a level load both
         * install `lives` from their own carrier immediately afterwards --
         * bounce_game_start_level -> bounce_game_activate_loaded_level at
         * game.c:409, and the staged chain's stage 5 at game.c:761 -- so the
         * zeroing inside bounce_game_load_level is inert on both of them. The
         * af reset gate is the one production path that reloads without
         * reinstalling, which is exactly where Java's silence has to be
         * reproduced.
         *
         * THE VALUE IS STORED VERBATIM, with no clamp and no validation,
         * because Java does not clamp it either: a run that already reached
         * lives == -1 keeps -1 across the skip.
         *
         * The restore is placed immediately after the load and before the
         * camera, i.e. inside the same window in which Java performs the whole
         * of InitializeGame(). Neither bounce_game_load_level() nor
         * app_update_camera() reads `lives`, so the position is not
         * load-bearing; it is stated so the correspondence is unambiguous.
         */
        int lives_before_reload;

        lives_before_reload = app->lives;

        if (bounce_game_level_resource_path(
                app->flow.level_id,
                level_path,
                sizeof level_path) != 0)
            reload_failed = 1;
        else
            reload_failed = bounce_game_load_level(
                app, level_path, app->flow.level_id);
        if (reload_failed != 0)
            return -1;
        app->lives = lives_before_reload;
        /* e(): the camera, from the new level, after the load. */
        rc = app_update_camera(app);
        if (rc != 0)
            return rc;
        app->af_reload_requested = false;
        return 0;
    }
    /*
     * STEP 65-H -- the W1 consumer, e.java:313-327, at the post-physics
     * fallthrough.
     *
     * THIS POSITION IS THE POINT OF THE STEP. The arm above returns from
     * bounce_game_tick_dispatch at game.c:926, which is BEFORE
     * timer_record_dispatch (game.c:970), BEFORE bounce_player_tick_entry
     * (game.c:982) and BEFORE the physics body (game.c:1001) -- so that path is
     * a pre-physics consumer and it serves af_reload_requested, whose Java
     * counterpart is e.java:222-226 (the top of Tick).
     *
     * Java's `e` consumer is the opposite: e.java:313 is the LAST statement
     * block of Tick(), after the physics body (e.java:262-308) and after
     * LoadSpriteSheet / q() / repaint() (e.java:310-312). This fallthrough is
     * the equivalent position: control only reaches it once
     * bounce_game_tick_dispatch has returned normally, which means the body ran
     * and branch_out was set to BOUNCE_TICK_DISPATCH_PLAYER_TICK at game.c:1009.
     * The two requests therefore have different timings and are deliberately not
     * merged: the AF reload skips physics, W1 runs it.
     *
     * THE TIMING CROSSES THE TICK BOUNDARY. app_request_w1_completion() is
     * called from the input callback, and this arm from
     * app_timer_callback_dispatch, which is only reached through
     * app_run_canonical_gameplay_tick's 40 ms gate (vertical_slice.c:6810).
     * x11_process_events runs at the top of the frame loop, before
     * app_update_production_game, so a request armed during frame N is
     * consumed by the first tick that follows it -- the next Tick(), exactly as
     * e.java:407 is consumed by e.java:313. It cannot be consumed in the frame
     * that armed it, because that frame's tick has either not started or has
     * already run.
     *
     * THE CANONICAL CONSUMER IS THE EXISTING PIPELINE. All seven of Java's
     * operations live inside bounce_game_mark_level_complete (game.c:1151-1397):
     * TODO_ExitUnlocked = false, level_complete = true, the LEVEL_COMPLETE
     * states, deferred_init = true, ++level_id, +5000, and the final-level
     * branch. None of them is reproduced here. This is the same single call the
     * exit-door route makes at vertical_slice.c:2952, so W1 and W2 converge on
     * one implementation and neither has its own.
     *
     * PERSISTENCE USES W2's SEQUENCE. app_persist_records is the native
     * WriteToStore (e.java:319), and the exit-door route calls it immediately
     * after the pipeline (vertical_slice.c:2952 then :2975). Java's own order is
     * the same: the level has advanced and the score has been credited before
     * the store is written. It is a file-local function in this translation
     * unit, so no declaration is needed and no second persistence path is added.
     *
     * CLEARED LAST. e.java:314 clears `e` before its effects run; the native
     * clear is after them instead, which is the smaller correct choice because
     * bounce_game_mark_level_complete is the operation that ends the run
     * (game.c:1266-1267), so a second consumption is not reachable either way.
     * Clearing before would discard the request if the pipeline then failed, and
     * a failed pipeline returns -1 above, which the frame loop already funnels
     * into x11_context.failed, so no retry path is invented.
     *
     * A PRODUCER IS WIRED: STEP 65-H bound XK_c through app_w1_completion_key()
     * (which requires af, e.java:406) and app_request_w1_completion() at :24447,
     * so this arm is reachable from the keyboard. See app_request_w1_completion
     * above and STEP 65-D.
     */
    if (app->completion_requested) {
        if (bounce_game_mark_level_complete(app) != 0)
            return -1;
        app_persist_records(app);
        app->completion_requested = false;
    }
    return 0;
}

/*
 * Native camera-initialization seam:
 *   RUNTIME_INITIALIZED -> l = 0; k = 0 -> app_update_camera() -> CAMERA_INITIALIZED
 *   -> STOP
 *
 * Source order (e.java:126-132): after `new f(...)` has already run the Big Ball
 * probe, the original performs `this.l = 0; this.k = 0;` and then calls `e()`,
 * which is the verified camera setup at e.java:135-151. The existing verified
 * app_update_camera() IS that e() body (horizontal l/v origin plus the two
 * vertical k loops), so it is called here unchanged: the algorithm, its
 * constants, its formulas, and its bounds are not re-implemented, moved, or
 * re-audited. The native E-buffer bookkeeping (this.Z / this.G) and the f()
 * tile re-render have no native seam and remain absent exactly as before.
 *
 * The seam lives beside the verified camera code rather than in game.c because
 * that implementation is file-local here; relocating it would be a refactor of
 * closed, verified code. The l = 0 / k = 0 assignments are this seam's only
 * direct state writes, and they precede the verified call exactly as in the
 * source.
 *
 * On failure nothing is installed and the caller is left unchanged. No timer,
 * tick, dyn-thorn update, renderer, repaint, audio, persistence, input, or
 * PLAYING transition is performed.
 */
static int app_advance_runtime_initialized_to_camera_initialized(
    BounceApp *app
)
{
    int32_t saved_l;
    int32_t saved_k;
    int32_t saved_v;

    if (app == NULL
        || app->flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
        || app->level == NULL
        || app->runtime == NULL
        || app->state != BOUNCE_GAME_STATE_LEVEL_LOADED
        || bounce_app_flow_entry_phase(&app->flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_RUNTIME_INITIALIZED
        || bounce_app_flow_entry_camera_initialized(&app->flow))
        return -1;

    saved_l = app->l;
    saved_k = app->k;
    saved_v = app->v;

    /* e.java:130-131 */
    app->l = 0;
    app->k = 0;

    /* e.java:132 -> e.e(), the already-verified implementation. */
    if (app_update_camera(app) != 0) {
        app->l = saved_l;
        app->k = saved_k;
        app->v = saved_v;
        return -1;
    }

    if (bounce_app_flow_record_camera_initialized(&app->flow) != 0) {
        app->l = saved_l;
        app->k = saved_k;
        app->v = saved_v;
        return -1;
    }
    return bounce_game_sync_ui_state(app);
}

/* Effective Java viewport transform: worldX - (l*12 - v), worldY - k*12. */
static int app_world_to_screen(
    const BounceApp *app,
    int32_t world_x,
    int32_t world_y,
    int32_t *screen_x_out,
    int32_t *screen_y_out
)
{
    if (app == NULL || screen_x_out == NULL || screen_y_out == NULL)
        return -1;
    *screen_x_out = java_int32_add(
        java_int32_add(
            world_x,
            -(app->l * BOUNCE_TILE_SIZE)
        ),
        app->v
    );
    *screen_y_out = java_int32_add(
        world_y,
        -(app->k * BOUNCE_TILE_SIZE)
    );
    return 0;
}

/*
 * This is a deterministic debug visualization of the raw tile bytes. The
 * mapping is not a tile semantic and does not claim original rendering.
 */
static uint32_t debug_tile_color(uint16_t value)
{
    uint32_t gray;

    if (value == 0u)
        return COLOR_EMPTY_TILE;
    if (value > UINT8_MAX)
        return COLOR_BACKGROUND;

    gray = (uint32_t)value;
    return TOKEN(gray, gray, gray);
}

static int draw_level_grid(
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    int32_t y;
    int32_t x;
    int32_t last_x;
    int32_t last_y;

    if (renderer == NULL || app == NULL || app->runtime == NULL)
        return -1;
    if (bounce_renderer_set_clip(
            renderer,
            0,
            0,
            BOUNCE_VIEWPORT_WIDTH,
            BOUNCE_VIEWPORT_HEIGHT
        ) != 0)
        return -1;

    /*
     * Rasterisation domain: the original draws exactly the 13x8 cell rectangle
     * [l .. l+12] x [k .. k+7]. b.f() (b.java:602-607) passes l+b1, k+b2 with
     * b1 in [0,13) and b2 in [0,8); b.i() (b.java:609-623) walks the same
     * rectangle for dirty cells, and the two LoadSpriteSheet scroll loops
     * (b.java:645, b.java:658) add only the newly exposed edge column. This
     * function previously swept the entire level, visiting cells the original
     * never rasterised; every one of them is clipped to zero visible pixels by
     * bounce_renderer_set_clip() above, so the window is output-equivalent.
     *
     * The indices are signed because app->k is a multiple of
     * BOUNCE_CAMERA_VERTICAL_STEP and is negative while the ball is in the top
     * rows (e.java:146-147 decrements it), which the whole-level unsigned sweep
     * could never encounter.
     *
     * Cells outside the level are skipped. The original's out-of-range branch
     * (b.java:401-404) stamps a BRICK_WALL sprite before returning; that border
     * is deliberately NOT introduced here, because the surface is already
     * cleared to COLOR_BACKGROUND by render_gameplay_scene() and adding it would
     * be an unverified behavioural change rather than an iteration-domain fix.
     */
    last_x = app->l + 12;
    last_y = app->k + 7;
    for (y = app->k; y <= last_y; ++y) {
        for (x = app->l; x <= last_x; ++x) {
            uint16_t value;
            int32_t screen_x;
            int32_t screen_y;
            int left;
            int top;

            if (x < 0
                || y < 0
                || (uint32_t)x
                    >= bounce_runtime_level_tiles_width(app->runtime)
                || (uint32_t)y
                    >= bounce_runtime_level_tiles_height(app->runtime))
                continue;

            if (app_world_to_screen(
                    app,
                    (int32_t)(x * BOUNCE_TILE_SIZE),
                    (int32_t)(y * BOUNCE_TILE_SIZE),
                    &screen_x,
                    &screen_y
                ) != 0)
                return -1;
            left = (int)screen_x;
            top = (int)screen_y;

            if (app->camera_diagnostic != NULL
                && x == CAMERA_DIAGNOSTIC_TILE_X
                && y == CAMERA_DIAGNOSTIC_TILE_Y)
                camera_diagnostic_stage_drawn(app, left, top);
            if (app->render_trace != NULL
                && x == CAMERA_DIAGNOSTIC_TILE_X
                && y == CAMERA_DIAGNOSTIC_TILE_Y)
                render_trace_stage_drawn(app, left, top);

            if (bounce_runtime_level_tiles_get(
                    app->runtime,
                    (int)x,
                    (int)y,
                    &value
                ) != 0)
                return -1;
            if (app->visuals != NULL) {
                if (bounce_visual_assets_draw_tile(
                        renderer,
                        app->visuals,
                        value,
                        left,
                        top
                    ) != 0)
                    return -1;
            } else if (bounce_renderer_fill_rect(
                           renderer,
                           left,
                           top,
                           BOUNCE_TILE_SIZE,
                           BOUNCE_TILE_SIZE,
                           debug_tile_color(value)
                       ) != 0) {
                return -1;
            }
        }
    }
    return 0;
}

/* Fallback only for isolated tests that do not load the original assets. */
static int draw_fallback_regular_ball(
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    int x;
    int y;
    int left;
    int top;
    int32_t screen_x;
    int32_t screen_y;
    const BouncePlayer *player;

    if (renderer == NULL
        || app == NULL
        || app_world_to_screen(
            app,
            app->player.TODO_unkX,
            app->player.TODO_unkY,
            &screen_x,
            &screen_y
        ) != 0)
        return -1;
    player = &app->player;
    if (player->current_ball_mode != BOUNCE_PLAYER_BALL_MODE_REGULAR
        || player->ballSize != BOUNCE_REGULAR_BALL_SIZE
        || player->p != BOUNCE_REGULAR_BALL_P)
        return -1;

    left = (int)(screen_x - player->p);
    top = (int)(screen_y - player->p);
    for (y = 0; y < BOUNCE_REGULAR_BALL_SIZE; ++y) {
        for (x = 0; x < BOUNCE_REGULAR_BALL_SIZE; ++x) {
            int dx = x - BOUNCE_REGULAR_BALL_P;
            int dy = y - BOUNCE_REGULAR_BALL_P;
            if (dx * dx + dy * dy <= 36) {
                if (bounce_renderer_fill_rect(
                        renderer,
                        left + x,
                        top + y,
                        1,
                        1,
                        COLOR_BALL
                    ) != 0)
                    return -1;
            }
        }
    }

    return bounce_renderer_fill_rect(
        renderer,
        left + 3,
        top + 2,
        2,
        2,
        COLOR_BALL_HIGHLIGHT
    );
}

static int draw_player_ball(
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    int32_t screen_x;
    int32_t screen_y;

    if (renderer == NULL
        || app == NULL
        || app_world_to_screen(
            app,
            app->player.TODO_unkX,
            app->player.TODO_unkY,
            &screen_x,
            &screen_y
        ) != 0)
        return -1;
    if (app->camera_diagnostic != NULL)
        camera_diagnostic_ball_drawn(app, screen_x, screen_y);
    if (app->render_trace != NULL)
        render_trace_ball_drawn(app, screen_x, screen_y);
    if (app->visuals != NULL) {
        /*
         * e.java:209-219. The live sprite is a pure function of ballSize and
         * the offset is the live p, so both come straight from the player
         * record: no sprite mode is stored natively. A regular ball still
         * selects sprite 47 at -p == -6, which is value-identical to the
         * previous regular-only call.
         *
         * STEP 14B-11, GAP-005. e.java:214 is a two-way branch on aq.z: while
         * z == 2 the source draws spritePoppedBall at a fixed -6. app->player.z
         * is the same field (f.java:218 writes it, :661 clears it) and is
         * already in scope here, so it is passed straight through. No new state
         * is stored and no copy of the death state is introduced.
         *
         * The previous revision of this comment cited e.java:209-219, the whole
         * method including both branches, while implementing only the else
         * branch. Both arms are implemented now.
         */
        return bounce_visual_assets_draw_player_ball(
            renderer,
            app->visuals,
            (int)app->player.ballSize,
            (int)app->player.p,
            (int)app->player.z,
            (int)screen_x,
            (int)screen_y
        );
    }
    return draw_fallback_regular_ball(renderer, app);
}

/* TEMPORARY NATIVE INPUT DIAGNOSTIC — NOT ORIGINAL UI PARITY. */
#define INPUT_DIAG_HEADER_Y 100
#define INPUT_DIAG_LEFT_LABEL_X 4
#define INPUT_DIAG_RIGHT_LABEL_X 28
#define INPUT_DIAG_UP_LABEL_X 52
#define INPUT_DIAG_DOWN_LABEL_X 76
#define INPUT_DIAG_LEFT_X 10
#define INPUT_DIAG_RIGHT_X 34
#define INPUT_DIAG_UP_X 58
#define INPUT_DIAG_DOWN_X 82
#define INPUT_DIAG_Y 106
#define INPUT_DIAG_NUM_LABEL_X 4
#define INPUT_DIAG_NUM_X 8
#define INPUT_DIAG_NUM_Y 113
#define INPUT_DIAG_CONTROL_LABEL_Y 120
#define INPUT_DIAG_PAUSE_X 10
#define INPUT_DIAG_CONFIRM_X 34
#define INPUT_DIAG_ESCAPE_X 58
#define INPUT_DIAG_QUIT_X 82
#define INPUT_DIAG_CONTROL_Y 120

static const char input_glyph_chars[] = "INPTLRUD0123456789CEQV";
static const unsigned char input_glyph_rows[][5] = {
    {7u, 2u, 2u, 2u, 7u}, /* I */
    {5u, 7u, 7u, 7u, 5u}, /* N */
    {6u, 5u, 6u, 4u, 4u}, /* P */
    {7u, 2u, 2u, 2u, 2u}, /* T */
    {4u, 4u, 4u, 4u, 7u}, /* L */
    {6u, 5u, 6u, 5u, 5u}, /* R */
    {5u, 5u, 5u, 5u, 7u}, /* U */
    {6u, 5u, 5u, 5u, 6u}, /* D */
    {7u, 5u, 5u, 5u, 7u}, /* 0 */
    {2u, 6u, 2u, 2u, 7u}, /* 1 */
    {7u, 1u, 7u, 4u, 7u}, /* 2 */
    {7u, 1u, 7u, 1u, 7u}, /* 3 */
    {5u, 5u, 7u, 1u, 1u}, /* 4 */
    {7u, 4u, 7u, 1u, 7u}, /* 5 */
    {7u, 4u, 7u, 5u, 7u}, /* 6 */
    {7u, 1u, 1u, 1u, 1u}, /* 7 */
    {7u, 5u, 7u, 5u, 7u}, /* 8 */
    {7u, 5u, 7u, 1u, 7u}, /* 9 */
    {7u, 4u, 4u, 4u, 7u}, /* C */
    {7u, 4u, 6u, 4u, 7u}, /* E */
    {7u, 5u, 5u, 7u, 1u}, /* Q */
    {5u, 5u, 5u, 5u, 2u}  /* V */
};

static int draw_input_text(
    BounceRenderer *renderer,
    int x,
    int y,
    const char *text,
    uint32_t color
)
{
    int text_index;
    int character_index;

    if (renderer == NULL || text == NULL)
        return -1;
    text_index = 0;
    while (text[text_index] != '\0') {
        const char *found = strchr(input_glyph_chars, text[text_index]);
        int row;
        int column;

        if (found == NULL)
            return -1;
        character_index = (int)(found - input_glyph_chars);
        for (row = 0; row < 5; ++row) {
            for (column = 0; column < 3; ++column) {
                if ((input_glyph_rows[character_index][row]
                        & (1u << (2 - column))) != 0u
                    && bounce_renderer_fill_rect(
                        renderer,
                        x + text_index * 4 + column,
                        y + row,
                        1,
                        1,
                        color
                    ) != 0)
                    return -1;
            }
        }
        ++text_index;
    }
    return 0;
}

static int draw_input_slot(
    BounceRenderer *renderer,
    int x,
    int y,
    int width,
    int height,
    bool active
)
{
    if (renderer == NULL || width < 3 || height < 3)
        return -1;
    if (bounce_renderer_fill_rect(
            renderer,
            x,
            y,
            width,
            height,
            COLOR_INPUT_ACCENT
        ) != 0)
        return -1;
    return bounce_renderer_fill_rect(
        renderer,
        x + 1,
        y + 1,
        width - 2,
        height - 2,
        active ? COLOR_INPUT_ACTIVE : COLOR_INPUT_INACTIVE
    );
}

static int draw_velocity_bar(
    BounceRenderer *renderer,
    int32_t velocity
)
{
    int32_t magnitude;
    int32_t length;
    int center = 64;
    int left;

    if (renderer == NULL
        || velocity < -BOUNCE_HORIZONTAL_VELOCITY_LIMIT
        || velocity > BOUNCE_HORIZONTAL_VELOCITY_LIMIT)
        return -1;
    if (bounce_renderer_fill_rect(
            renderer,
            34,
            INPUT_DIAG_HEADER_Y,
            61,
            5,
            COLOR_INPUT_INACTIVE
        ) != 0
        || bounce_renderer_fill_rect(
            renderer,
            center,
            INPUT_DIAG_HEADER_Y,
            1,
            5,
            COLOR_INPUT_ACCENT
        ) != 0)
        return -1;

    magnitude = velocity < 0 ? -velocity : velocity;
    length = magnitude * 30 / BOUNCE_HORIZONTAL_VELOCITY_LIMIT;
    if (length < 1 && velocity != 0)
        length = 1;
    if (velocity > 0)
        left = center + 1;
    else if (velocity < 0)
        left = center - length;
    else
        return 0;
    return bounce_renderer_fill_rect(
        renderer,
        left,
        INPUT_DIAG_HEADER_Y + 1,
        length,
        3,
        COLOR_INPUT_ACTIVE
    );
}

static int draw_input_diagnostic(
    BounceRenderer *renderer,
    const BounceInputState *input,
    int32_t velocity
)
{
    int index;

    if (renderer == NULL || input == NULL)
        return -1;
    if (bounce_renderer_reset_clip(renderer) != 0
        || bounce_renderer_fill_rect(renderer, 2, 98, 124, 28, COLOR_INPUT_PANEL) != 0
        || bounce_renderer_fill_rect(renderer, 2, 98, 124, 2, COLOR_INPUT_ACCENT) != 0
        || draw_input_text(renderer, 4, INPUT_DIAG_HEADER_Y, "INPUT", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, 27, INPUT_DIAG_HEADER_Y, "V", COLOR_STATE_WHITE) != 0
        || draw_velocity_bar(renderer, velocity) != 0
        || draw_input_text(renderer, INPUT_DIAG_LEFT_LABEL_X, INPUT_DIAG_Y, "L", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, INPUT_DIAG_RIGHT_LABEL_X, INPUT_DIAG_Y, "R", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, INPUT_DIAG_UP_LABEL_X, INPUT_DIAG_Y, "U", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, INPUT_DIAG_DOWN_LABEL_X, INPUT_DIAG_Y, "D", COLOR_STATE_WHITE) != 0
        || draw_input_slot(renderer, INPUT_DIAG_LEFT_X, INPUT_DIAG_Y, 12, 5, input->left) != 0
        || draw_input_slot(renderer, INPUT_DIAG_RIGHT_X, INPUT_DIAG_Y, 12, 5, input->right) != 0
        || draw_input_slot(renderer, INPUT_DIAG_UP_X, INPUT_DIAG_Y, 12, 5, input->up) != 0
        || draw_input_slot(renderer, INPUT_DIAG_DOWN_X, INPUT_DIAG_Y, 12, 5, input->down) != 0)
        return -1;

    for (index = 0; index < 10; ++index) {
        char label[2];
        label[0] = (char)('0' + index);
        label[1] = '\0';
        if (draw_input_text(
                renderer,
                INPUT_DIAG_NUM_LABEL_X + index * 11,
                INPUT_DIAG_NUM_Y,
                label,
                COLOR_STATE_WHITE
            ) != 0
            || draw_input_slot(
                renderer,
                INPUT_DIAG_NUM_X + index * 11,
                INPUT_DIAG_NUM_Y,
                5,
                5,
                input->numeric[index]
            ) != 0)
            return -1;
    }

    if (draw_input_text(renderer, 4, INPUT_DIAG_CONTROL_LABEL_Y, "P", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, 28, INPUT_DIAG_CONTROL_LABEL_Y, "C", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, 52, INPUT_DIAG_CONTROL_LABEL_Y, "E", COLOR_STATE_WHITE) != 0
        || draw_input_text(renderer, 76, INPUT_DIAG_CONTROL_LABEL_Y, "Q", COLOR_STATE_WHITE) != 0
        || draw_input_slot(renderer, INPUT_DIAG_PAUSE_X, INPUT_DIAG_CONTROL_Y, 12, 5, input->pause) != 0
        || draw_input_slot(renderer, INPUT_DIAG_CONFIRM_X, INPUT_DIAG_CONTROL_Y, 12, 5, input->confirm_start) != 0
        || draw_input_slot(renderer, INPUT_DIAG_ESCAPE_X, INPUT_DIAG_CONTROL_Y, 12, 5, input->escape_back) != 0
        || draw_input_slot(renderer, INPUT_DIAG_QUIT_X, INPUT_DIAG_CONTROL_Y, 12, 5, input->quit) != 0)
        return -1;
    return 0;
}

/*
 * STEP 12E — Native Exit Door Rendering.
 *
 * Renders the 24x48 exit door sprite at the level's exit tile position.
 * Uses the existing coordinate transform, camera transform, clipping
 * architecture, and transparent blit mechanism.
 *
 * Insertion point: after draw_level_grid(), before draw_player_ball().
 * The existing 128x96 gameplay clip (set by draw_level_grid) handles clipping.
 */
static int draw_exit_door(
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    int32_t screen_x;
    int32_t screen_y;
    uint8_t exit_x;
    uint8_t exit_y;

    if (renderer == NULL || app == NULL || app->level == NULL)
        return -1;
    /*
     * Tolerant of an absent asset set, exactly as draw_hud() and
     * draw_player_ball() already are. An absent visual asset set is a
     * PRESENTATION-AVAILABILITY condition, not a gameplay-logic condition: the
     * door has no asset-free rasterization of its own, so it contributes
     * nothing and the frame still completes. That is required because a
     * verification that renders a gameplay frame without loading the asset
     * inventory must still get its frame, exactly as the HUD and the ball
     * already do. Nothing here is weakened: a NULL renderer, a NULL app and a
     * NULL level all remain errors, because the door's world position is
     * derived from the level below, and a real blit failure from
     * bounce_visual_assets_draw_exit_door_window() is still propagated.
     */
    if (app->visuals == NULL)
        return 0;

    exit_x = bounce_level_exit_x(app->level);
    exit_y = bounce_level_exit_y(app->level);

    /* Convert tile position to world pixels using the existing transform */
    if (app_world_to_screen(
            app,
            (int32_t)(exit_x * BOUNCE_TILE_SIZE),
            (int32_t)(exit_y * BOUNCE_TILE_SIZE),
            &screen_x,
            &screen_y
        ) != 0)
        return -1;

    /* STEP 12R — Render 24x24 source region at door_image_offset */
    return bounce_visual_assets_draw_exit_door_window(
        renderer,
        app->visuals,
        (int)screen_x,
        (int)screen_y,
        app->door_image_offset
    );
}

/*
 * STEP 12V — Dynamic Thorn Rendering.
 *
 * Renders all dynamic thorns at their current world positions.
 * Uses the existing camera transform, clipping architecture,
 * and transparent blit mechanism.
 *
 * Draw order: after draw_level_grid(), before draw_player_ball().
 */
static int draw_dyn_thorns(
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    const struct BounceDynThorns *thorns;
    BounceDynThornsSource source;
    uint32_t index;
    int32_t screen_x;
    int32_t screen_y;

    if (renderer == NULL || app == NULL || app->runtime == NULL)
        return -1;
    /*
     * Tolerant of an absent asset set, exactly as draw_hud() and
     * draw_player_ball() already are. An absent visual asset set is a
     * PRESENTATION-AVAILABILITY condition, not a gameplay-logic condition: the
     * 24x24 composite is built from the sprite inventory, so with no inventory
     * the thorns contribute nothing and the frame still completes. The runtime
     * owner stays required above, because the thorn records are read from it.
     *
     * This changes NOTHING about the composite, the quarter transforms, the
     * world coordinates, the camera conversion, the draw order or the clip:
     * those are all below this guard and run unchanged whenever an inventory is
     * present. A real blit failure is still propagated, and an absent runtime
     * owner is still an error.
     */
    if (app->visuals == NULL)
        return 0;

    thorns = bounce_runtime_level_tiles_dyn_thorns(app->runtime);
    if (thorns == NULL)
        return 0;

    if (bounce_dyn_thorns_source(thorns, &source) != 0)
        return -1;

    for (index = 0; index < source.count; ++index) {
        BounceDynThornRecord record;

        if (!source.read_record(source.context, index, &record))
            continue;

        /* Calculate world position */
        /* Apply camera transform */
        if (app_world_to_screen(
                app,
                (int32_t)(record.bottom_left.x * 12 + record.w.x),
                (int32_t)(record.bottom_left.y * 12 + record.w.y),
                &screen_x,
                &screen_y
            ) != 0)
            return -1;

        /* Draw 24x24 composite sprite with transparency */
        if (bounce_visual_assets_draw_dyn_thorn(
                renderer,
                app->visuals,
                (int)screen_x,
                (int)screen_y
            ) != 0)
            return -1;
    }

    return 0;
}

static int render_gameplay_scene(
    BounceSurface *surface,
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    if (surface == NULL || renderer == NULL || app == NULL)
        return -1;
    if (bounce_surface_fill(surface, COLOR_BACKGROUND) != 0)
        return -1;
    if (draw_level_grid(renderer, app) != 0
        || draw_exit_door(renderer, app) != 0
        || draw_dyn_thorns(renderer, app) != 0
        || draw_player_ball(renderer, app) != 0)
        return -1;
    /* e.java:174-189, after the game viewport and before presentation. */
    if (draw_hud(renderer, app) != 0)
        return -1;
    /* e.java:201-205, on top of the composed image, gated only on `p`. */
    if (draw_level_banner(renderer, app) != 0)
        return -1;
    if (app->camera_diagnostic != NULL)
        camera_diagnostic_render_complete(app);
    if (app->render_trace != NULL)
        render_trace_frame_complete(app);
    /*
     * INPUT-RELATED UI -- HIDDEN, NOT DELETED.
     *
     * draw_input_diagnostic() paints a debug INPUT panel at
     * fillRect(2, 98, 124, 28), which is the same band as the e.java:176 HUD
     * fill, plus L/R/U/D slots, a velocity bar and digit slots. It has NO
     * counterpart in the recovered source: the original is a numeric-keypad
     * game and its only two drawString() calls are the score at e.java:183 and
     * the level string at e.java:204. There is no on-screen control UI to
     * reproduce, so this panel is a native-only diagnostic and must not be
     * mistaken for original HUD.
     *
     * It is HIDDEN, not deleted. The function, its colour tokens, its geometry
     * constants and the whole input binding it visualises are all retained, and
     * gameplay input is untouched: app->input still drives f.java:806-814, the
     * bit-08 action at f.java:821, and the camera gate exactly as before. Nothing
     * about how input is read or applied has changed.
     *
     * The gate reuses the render_trace pointer, which this file already treats as
     * "extra instrumentation was explicitly requested" -- it is non-NULL only
     * under --render-trace. No new state and no new visibility rule are
     * introduced, and the panel remains reachable for anyone debugging input.
     */
    if (app->render_trace != NULL
        && draw_input_diagnostic(renderer, &app->input, app->player.o) != 0)
        return -1;
    return 0;
}

/* TEMPORARY NATIVE UI REPRESENTATION — NOT ORIGINAL PAUSE PIXEL PARITY. */
static int render_pause_state(
    BounceSurface *surface,
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    if (render_gameplay_scene(surface, renderer, app) != 0)
        return -1;
    if (bounce_renderer_reset_clip(renderer) != 0)
        return -1;
    if (bounce_renderer_fill_rect(renderer, 0, 12, 128, 8, COLOR_PAUSE_BAR) != 0
        || bounce_renderer_fill_rect(renderer, 0, 52, 128, 8, COLOR_PAUSE_BAR) != 0
        || bounce_renderer_fill_rect(renderer, 0, 92, 128, 4, COLOR_PAUSE_BAR) != 0
        || bounce_renderer_fill_rect(renderer, 18, 0, 8, 128, COLOR_PAUSE_BAR) != 0
        || bounce_renderer_fill_rect(renderer, 102, 0, 8, 128, COLOR_PAUSE_BAR) != 0
        || bounce_renderer_fill_rect(renderer, 45, 42, 38, 28, COLOR_PAUSE_ACCENT) != 0
        || bounce_renderer_fill_rect(renderer, 51, 50, 26, 12, COLOR_PAUSE_BAR) != 0)
        return -1;
    return 0;
}

/*
 * STEP 13G-B -- render_game_over_state() was REMOVED here, together with
 * COLOR_GAME_OVER_BASE and COLOR_GAME_OVER_ACCENT, and this follows the precedent
 * STEP 12X-P4-C-B set for the identical situation on the Game End screen.
 *
 * That step's own record of why: the two colours "were invented by Step 12X-P4-B
 * for the Game End placeholder and were used by nothing else. The Game End
 * destination now draws through bounce_ui_shell_render_game_end() and takes its
 * colours from the active theme palette, like every other form." The Game Over
 * destination is now in the same position: the destination draws through
 * bounce_ui_shell_render_game_over() (ui_shell.c) and takes its colours from the
 * palette, so the two placeholder-only tokens have no remaining reader and are
 * removed rather than left dead. The sentence above that recorded why
 * COLOR_GAME_OVER_* was kept is superseded by this one.
 *
 * BOUNCE_APP_STATE_GAME_OVER itself is untouched: app_flow.c:164 still writes it,
 * and render_app_state still dispatches it. Only the presentation moved.
 */

/*
 * STEP 13G-A -- the Level Complete destination now lives in ui_shell.c with the other
 * ten, because tr(), draw_centered_placeholder_text() and
 * draw_centered_placeholder_wrapped() are file-static there and because the source
 * Form is a text Form, not a canvas. The former placeholder that stood here
 * ("TEMPORARY NATIVE UI REPRESENTATION", five rectangles and no text) is removed
 * rather than left as dead code.
 *
 * The two arguments are the completed level and the live score, both read from the
 * app here because this is the only layer that has it:
 *
 *   app->level_id  still holds the LOADED level. The completion block does not write
 *                  it; bounce_app_flow_complete_level() advances only flow->level_id
 *                  (app_flow.c:697), and bounce_game_release_level() -- the only writer
 *                  that clears it -- is not reached until CONTINUE (game.c:1458) or the
 *                  Escape edge (vertical_slice.c:16456), both of which leave
 *                  LEVEL_COMPLETE in the same handler. So at render time it is the level
 *                  that was just completed, which is what the source prints.
 *   app->score     ALREADY includes the +5000 from game.c:1350. Nothing is added here.
 *
 * Nothing else about the lifecycle is touched: the state, the timer stop, the
 * deferred_init latch and the SELECT -> bounce_game_continue_level() branch are all
 * exactly as they were.
 */

/*
 * =============================================================================
 * STEP SHOTS -- writing the logical surface out as a PNG.
 *
 * WHY THIS EXISTS RATHER THAN A SCREENSHOT TOOL. The screenshots in screenshots/ are
 * 128x128, which is BOUNCE_SURFACE_WIDTH x BOUNCE_SURFACE_HEIGHT: they are renders of
 * the logical surface, not captures of an X window. A window capture would come out at
 * whatever size the window manager gave it, with chrome and scaling in it, so it could
 * not replace these files without also changing what they are.
 *
 * Capturing an X window was also not possible here: there is no Xvfb, no xdotool, and
 * libXtst has no header, so nothing could drive the game to the screens that need a key
 * press. Driving the flow directly and rendering each state reaches all of them, needs
 * no display at all, and produces byte-identical output for the same build -- which is
 * what makes the images in the repository reproducible rather than a one-off.
 *
 * The colour conversion is the one real decision. Surface pixels are opaque uint32
 * tokens and this tree does not establish Java ME ARGB byte order, so the bytes are NOT
 * reinterpreted here. Each pixel is split as the shader path already splits it, and the
 * existing screenshots are the reference for whether that is right.
 */
static int bounce_shot_write_png(const char *path, const BounceSurface *surface)
{
    FILE *file;
    png_structp png;
    png_infop info;
    png_bytep *rows;
    uint32_t width;
    uint32_t height;
    uint32_t x;
    uint32_t y;

    if (path == NULL || surface == NULL)
        return -1;
    width = bounce_surface_width(surface);
    height = bounce_surface_height(surface);
    if (width == 0u || height == 0u)
        return -1;

    file = fopen(path, "wb");
    if (file == NULL)
        return -1;
    png = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (png == NULL) {
        (void)fclose(file);
        return -1;
    }
    info = png_create_info_struct(png);
    if (info == NULL) {
        png_destroy_write_struct(&png, NULL);
        (void)fclose(file);
        return -1;
    }
    if (setjmp(png_jmpbuf(png))) {
        png_destroy_write_struct(&png, &info);
        (void)fclose(file);
        return -1;
    }
    png_init_io(png, file);
    png_set_IHDR(
        png,
        info,
        width,
        height,
        8,
        PNG_COLOR_TYPE_RGB,
        PNG_INTERLACE_NONE,
        PNG_COMPRESSION_TYPE_DEFAULT,
        PNG_FILTER_TYPE_DEFAULT
    );
    png_write_info(png, info);

    rows = (png_bytep *)malloc(sizeof(png_bytep) * height);
    if (rows == NULL) {
        png_destroy_write_struct(&png, &info);
        (void)fclose(file);
        return -1;
    }
    for (y = 0u; y < height; ++y)
        rows[y] = (png_bytep)malloc(3u * width);
    for (y = 0u; y < height; ++y) {
        if (rows[y] == NULL) {
            for (uint32_t i = 0u; i < y; ++i)
                free(rows[i]);
            free(rows);
            png_destroy_write_struct(&png, &info);
            (void)fclose(file);
            return -1;
        }
    }
    for (y = 0u; y < height; ++y) {
        for (x = 0u; x < width; ++x) {
            uint32_t pixel = 0u;
            /*
             * THE SAME SPLIT THE RENDERER USES. bounce_renderer_fill_rect() and the
             * image blitter both treat a token as 0xAARRGGBB, so the writer does too
             * rather than guessing a byte order of its own.
             */
            if (bounce_surface_get_pixel(
                    surface, (int)x, (int)y, &pixel) != 0)
                pixel = 0u;
            rows[y][x * 3u + 0u] = (png_byte)((pixel >> 16) & 0xffu);
            rows[y][x * 3u + 1u] = (png_byte)((pixel >> 8) & 0xffu);
            rows[y][x * 3u + 2u] = (png_byte)(pixel & 0xffu);
        }
        png_write_row(png, rows[y]);
    }
    png_write_end(png, info);
    for (y = 0u; y < height; ++y)
        free(rows[y]);
    free(rows);
    png_destroy_write_struct(&png, &info);
    (void)fclose(file);
    return 0;
}

/*
 * =============================================================================
 * STEP SHOTS -- the screenshot set.
 *
 * WHAT IT CAPTURES, AND WHY THESE SCREENS. Every state a player can look at that has
 * a distinct visual identity, reached through the flow rather than by faking the
 * state. The set is not the nine files that were in screenshots/: two of those were
 * already out of date before this mode existed -- settings-menu.png still showed five
 * Settings rows and no Reset to Default, and main-menu.png still carried the old
 * "CONTINUE NO SAVE DATA" wording -- and three screens that the feature added had no
 * image at all.
 *
 * THE FOUR NEW ONES, and what each is for:
 *
 *   settings-reset-confirm   the confirmation page, which is the one screen in the
 *                            shell with no ESC BACK hint and a clickable BACK row.
 *                            It is the screen where the Reset feature lives.
 *   settings-theme            the Theme page, which existed but was never captured.
 *   settings-input-keypad     the Input page with the numeric-keypad setting, which
 *                            is on by default now and so differs from the Audio page
 *                            beside it in exactly one pixel of state.
 *   level-select-progress     Level Select with more than the two fresh-install rows
 *                            unlocked, because with the shipped default of two the
 *                            fresh list looks like a truncation rather than a state.
 *
 * EVERY SCREEN IS RENDERED THROUGH render_app_state(), which is the same dispatcher
 * the frame loop uses. That is what keeps an image honest: there is no second drawing
 * path here that could drift from what the game draws, and a screen that stops being
 * reachable would fail here rather than produce an image of a state nothing enters.
 *
 * THE GAMEPLAY SHOTS ARE TICKED, not posed. Each is driven through the ordinary
 * production update until the state it wants is reached, so what is captured is a frame
 * the game really produced -- the same distinction verify_tick_cadence() turns on, and
 * the reason the level-1 image is taken after a fixed number of ticks rather than at a
 * hand-picked ball position.
 *
 * NOTHING HERE TOUCHES THE PLAYER'S SAVE. The store is redirected to a private
 * mkdtemp root for the duration, on the same discipline every other I/O path in this
 * file follows, and the flow is booted fresh so "no save" is a real state rather than
 * whatever happened to be on disk.
 */
static int render_app_state(
    BounceSurface *surface,
    BounceRenderer *renderer,
    const BounceApp *app
)
{
    if (surface == NULL || renderer == NULL || app == NULL)
        return -1;

    switch (app->flow.state) {
        case BOUNCE_APP_STATE_SPLASH:
            if (app->visuals == NULL)
                return -1;
            return bounce_ui_shell_render_splash(
                surface,
                renderer,
                app->visuals
            );
        case BOUNCE_APP_STATE_MENU:
            return bounce_ui_shell_render_menu(surface, renderer, &app->flow);
        case BOUNCE_APP_STATE_ACTION_BOUNDARY:
            return bounce_ui_shell_render_action_boundary(
                surface,
                renderer,
                &app->flow
            );
        case BOUNCE_APP_STATE_INSTRUCTIONS:
            return bounce_ui_shell_render_instructions(
                surface,
                renderer,
                &app->flow
            );
        case BOUNCE_APP_STATE_HIGH_SCORE:
            return bounce_ui_shell_render_high_score(
                surface,
                renderer,
                &app->flow
            );
        case BOUNCE_APP_STATE_LEVEL_SELECTION:
            return bounce_ui_shell_render_level_selection(
                surface,
                renderer,
                &app->flow
            );
        /* NATIVE EXTENSION destinations. */
        case BOUNCE_APP_STATE_SETTINGS:
            return bounce_ui_shell_render_settings(surface, renderer, &app->flow);
        case BOUNCE_APP_STATE_ABOUT:
            return bounce_ui_shell_render_about(surface, renderer, &app->flow);
        case BOUNCE_APP_STATE_GAMEPLAY_ENTRY:
            return bounce_ui_shell_render_gameplay_entry(
                surface,
                renderer,
                &app->flow
            );
        case BOUNCE_APP_STATE_LEVEL_LOADED:
            /*
             * Native integration seam with no screen by design. This milestone
             * must not add renderer behavior, and the loaded level is verified
             * deterministically instead of being drawn as gameplay.
             */
            return -1;
        case BOUNCE_APP_STATE_GAMEPLAY:
            return render_gameplay_scene(surface, renderer, app);
        case BOUNCE_APP_STATE_PAUSE:
            return render_pause_state(surface, renderer, app);
        case BOUNCE_APP_STATE_GAME_OVER:
            /*
             * STEP 13G-B: the real Game Over Form, in ui_shell.c with the other
             * destinations. The twelve-line render_game_over_state() placeholder
             * that stood here -- five rectangles, no title, no body, no score, no
             * command -- is removed rather than left as dead code. The four items
             * BounceGame.java:177-195 puts in the Form are drawn instead: title
             * (:181), body (:186), score (:192) and the single Command.OK
             * (:180/:193).
             *
             * app->score is passed straight through as the display value.
             * BounceGame.java:427 establishes this.E = this.v.score, which is
             * exactly what :192 prints, so nothing is added, subtracted or
             * recomputed here: Game Over is display-only and this build adds
             * nothing to the total.
             */
            /*
             * D-07 -- `q` is BounceGame.q, read through its own accessor.
             * bounce_app_flow_new_high_score() is that field: set by
             * bounce_app_flow_note_score() at BounceGame.java:424 and cleared
             * only on the new-game routes at :150. It gates the
             * NEW_HIGH_SCORE Item at BounceGame.java:188-190 on this form.
             */
            return bounce_ui_shell_render_game_over(
                surface,
                renderer,
                app->score,
                bounce_app_flow_new_high_score(&app->flow)
            );
        case BOUNCE_APP_STATE_LEVEL_COMPLETE:
            /* STEP 13G-A: the real Level Complete Form, in ui_shell.c. */
            return bounce_ui_shell_render_level_complete(
                surface,
                renderer,
                app->level_id,
                app->score
            );
        /* STEP 12X-P4-B: the game-complete terminal destination. */
        /*
         * STEP 12X-P4-C-B: the Game End destination is drawn by the UI shell,
         * like every other form. The Step 12X-P4-B placeholder that lived here
         * was pure geometry and is gone.
         *
         * D-07 / D-11 -- the score and the NEW_HIGH_SCORE notice are now drawn.
         * They were previously withheld because neither had a reconciled native
         * owner; both do now. ShowGameEnd (BounceGame.java:177-197) has a single
         * body whose ONLY difference between the loss and win forms is the
         * CONGRATS/GAME_OVER line at :182-186, so :188-190 and :192 belong to
         * this screen exactly as they belong to the Game Over one.
         *
         * `app->score` is passed straight through, unchanged, for the same
         * reason the loss form's is: BounceGame.java:427 makes this.E the live
         * v.score, and the completion block wrote it at e.java:319 -- after the
         * +5000 at :318 and before the level > 11 branch at :320 -- so the value
         * already contains the completion bonus.
         */
        case BOUNCE_APP_STATE_GAME_END:
            return bounce_ui_shell_render_game_end(
                surface,
                renderer,
                &app->flow,
                app->score,
                bounce_app_flow_new_high_score(&app->flow)
            );
    }
    return -1;
}

/*
 * Production main-loop routing.
 *
 * The interactive UI records START_LEVEL(N) at BOUNCE_APP_STATE_GAMEPLAY_ENTRY
 * but nothing consumed it: the staged lifecycle was only ever driven by the
 * deterministic harnesses, so the real application stopped at gameplay-entry.
 * These helpers close that gap using the already-verified staged seams, in
 * order, with no second initialization path.
 *
 * Canonical gameplay is active only when the flow is GAMEPLAY **and** the
 * canonical timer has been started. That pair is the existing state used here;
 * the legacy diagnostic modes reach GAMEPLAY with the timer unstarted and
 * therefore keep using app_update_game() exactly as before.
 */
static bool app_canonical_gameplay_active(const BounceApp *app)
{
    return app != NULL
        && app->flow.state == BOUNCE_APP_STATE_GAMEPLAY
        && bounce_game_timer_is_started(&app->game_timer);
}

/*
 * G-R3-R1 -- the Record 3 resume restore, e.a(int,int) (e.java:92-113).
 *
 * Declared here because app_begin_canonical_gameplay() below is its sole caller,
 * while the definition sits further down beside the T2 capture helpers whose
 * state it shares. The restore window itself is between stage 3 and stage 4 of the
 * chain; see the definition for the full ordering rationale.
 */
static void app_resume_restore_payload(BounceApp *app);

/*
 * Consume a recorded START_LEVEL(N) and drive the staged lifecycle to gameplay
 * with the canonical timer started. Returns 0 when there was nothing to start
 * (already in gameplay, or not at the action boundary).
 */
static int app_begin_canonical_gameplay(BounceApp *app)
{
    if (app == NULL)
        return -1;
    if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app->flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL)
        return 0;

    /*
     * D-19 -- CLEAR THE HELD-KEY STATE ON THE MENU -> GAMEPLAY EDGE.
     *
     * JAVA EVIDENCE. The player's key bitmask is cleared by exactly two call
     * sites in the whole tree, and both of them are on a screen transition:
     *
     *   BounceGame.java:148-157
     *       public void a(boolean paramBoolean, int paramInt) {
     *           if (paramBoolean) {
     *               this.q = false;
     *               this.v.a(paramInt, 0, 3);
     *           }
     *           this.v.StartGameTimer();
     *           this.v.aq.a();               <-- :154, UNCONDITIONAL
     *           this.display.setCurrent(this.v);
     *           this.K = 1;
     *       }
     *
     *   e.java:473-480
     *       public void hideNotify() {
     *           if (this.H) {
     *               if (this.aq != null)
     *                   this.aq.a();          <-- :476
     *               this.game.ShowMainMenu();
     *           }
     *           this.H = true;
     *       }
     *
     * and `f.a()` (f.java:150-152) is `this.w &= 0xFFFFFFF0;` -- it drops every
     * bit above the low nibble, so no key can stay latched across a
     * transition.
     *
     * `a(boolean,int)` is the shared menu->gameplay entry and it reaches four
     * routes: the level-list SELECT at BounceGame.java:218, the in-game
     * Continue at :224, the New Game at :242, and the level-complete screen's
     * own `a(false, 0)` at :201 (ShowLevelComplete, e.java path). So the clear
     * happens on every one of them.
     *
     * WHY NATIVE NEEDS IT. Nothing in the native production path cleared the
     * held-source mask between gameplay sessions: bounce_input_reset() is
     * called from bounce_game_init (game.c:134), bounce_game_enter_menu
     * (game.c:279) and bounce_game_shutdown (game.c:1539) only, and the first
     * of those three is startup and the third is teardown. The menu->gameplay
     * edge went through neither. Combined with the X11 auto-repeat filter
     * (vertical_slice.c:21459), which deliberately discards repeat KeyPress
     * events so one physical press produces exactly one edge, a key held
     * while the player left gameplay never received its KeyRelease -- X
     * delivers releases to the focused window -- so its bit stayed set and the
     * ball accelerated on the very first tick of the next run. Java cannot
     * reach that state: :154 drops the mask on entry and :476 on focus loss.
     *
     * THE RESUME ROUTE IS DELIBERATELY EXEMPT, because Java is. The J != 0
     * branch (BounceGame.java:226-234) does NOT call a(boolean,int):
     *
     *     } else if (this.J != 0) {
     *         this.display.setCurrent(this.v);     <-- :226
     *         if (this.J == 1) { this.v.a(this.y, this.M); }
     *         else { this.v.a(this.RecordLevel, this.RecordScore,
     *                          this.RecordLives); }
     *         this.u = null;
     *         this.v.StartGameTimer();
     *         this.K = 1;
     *     }
     *
     * so no `aq.a()` runs on that route. At the moment setCurrent(v) executes
     * the canvas was NOT the current Displayable, so hideNotify does not fire
     * either -- MIDP calls it on the Displayable being removed, and the canvas
     * is being brought back, not removed. resume_requested is the existing
     * discriminator for exactly this route (game.h:490-511), so the exemption
     * costs no new state and invents no new concept. Clearing here anyway
     * would be a superset of the source, so it is not done.
     *
     * `resume_requested` is sampled before the staged chain below, which
     * consumes and clears it, and it is only ever true on the frame that
     * carries a resume: a fresh entry is at most one frame per dispatch.
     */
    if (!app->resume_requested)
        bounce_input_reset(&app->input);

    /*
     * The verified staged order, using only the existing seams and nothing else:
     * LEVEL_LOADED -> PLAYER_INITIALIZED -> RUNTIME_INITIALIZED ->
     * CAMERA_INITIALIZED -> GAMEPLAY_ACTIVATED -> TIMER_INITIALIZED. The Big
     * Ball probe therefore still runs against the pristine level before any
     * runtime copy exists, and the level id still comes from the recorded
     * START_LEVEL(N) through the entry seam.
     *
     * G-R3-R1: the resume restore window below is the only addition to this
     * sequence.
     */
    if (app_advance_gameplay_entry_to_level_loaded(app) != 0
        || app_advance_level_loaded_to_player_initialized(app) != 0
        || app_advance_player_initialized_to_runtime_initialized(app) != 0)
        return -1;
    /*
     * G-R3-R1 -- THE RESUME RESTORE WINDOW.
     *
     * Placed between stage 3 and stage 4, which is the R1-B decision. Stage 3 has
     * created the mutable runtime tiles and the dyn-thorn records; stage 4 has not
     * yet run app_update_camera(), which is why the player restore must precede it
     * (e.java:127 places the player before e.java:132 calls e()). Stage 5 is left
     * outside the window on purpose: it installs lives from the carrier that
     * bounce_app_flow_record_resume_entry() already filled, and it would undo any
     * direct write to game->lives here.
     *
     * The latch is consumed HERE and nowhere else, so it cannot survive into a
     * later New Game, and the restore cannot run twice.
     */
    if (app->resume_requested) {
        app_resume_restore_payload(app);
        app->resume_requested = false;
    } else if (app->continue_record_pending) {
        /*
         * D-03/D-04 -- THE J == 2 WINDOW: e.a(level, score, lives), e.java:81-90.
         *
         * ONE LINE, AND THAT IS THE POINT. e.a(int,int,int) assigns
         *
         *     this.level = level;      -> recorded by the entry, read at stage 1
         *     this.HoopsScored = 0;    -> stage 5's path already leaves it 0
         *     this.lives = paramInt3;  -> stage 5 reads the flow carrier
         *     this.score = paramInt2;  <-- this line
         *     this.e = false;          -> the level load already clears it
         *     this.TODO_ExitUnlocked = false;  -> likewise
         *     InitializeGame();        -> stages 1..5, and the countdown
         *                                   re-arm this milestone added
         *
         * The other five assignments are already performed by the staged chain, so
         * reproducing them here would be a second writer for each. The score is
         * the one that is not, which is why this window exists at all.
         *
         * PLACEMENT IS THE SAME POINT AS THE J == 1 WINDOW, for the same reason:
         * stage 3 has built the runtime tiles and stage 4 has not yet run the
         * camera, and nothing after this point writes the score.
         */
        app->score = app->resume_record3.score;
        app->continue_record_pending = false;
    }
    if (app_advance_runtime_initialized_to_camera_initialized(app) != 0
        || app_advance_camera_initialized_to_activated(app) != 0
        || bounce_game_initialize_game_timer(app) != 0)
        return -1;

    /* BounceTimer.java:17 schedules with a zero initial delay. */
    app->canonical_next_tick_ms = 0;
    return 0;
}

/*
 * Drive the canonical tick from the frame loop.
 *
 * The existing verified 40 ms timer remains authoritative: BounceTimer.java:17
 * schedules `this` with `schedule(this, 0L, 40L)`, i.e. a 40 ms FIXED-DELAY
 * period, ~25 Hz. This is the platform backend deciding WHEN to fire it, and the
 * deadline arithmetic below is what makes the achieved cadence match that period
 * instead of merely being bounded by it.
 *
 * WHY THE DEADLINE ADVANCES FROM THE PREVIOUS DEADLINE, NOT FROM `now`
 *   `now` is sampled once per RENDERED FRAME, and sleep_frame() is 16 ms, so `now`
 *   is quantised to the frame grid. Setting `next = now + PERIOD` therefore adds a
 *   fresh 0..16 ms of quantisation error to EVERY tick and never removes it: the
 *   error accumulates and the game runs permanently slow. Measured over 60 s of
 *   simulated 16 ms frames, that shape yields 1250 ticks, an average period of
 *   48.00 ms and an effective 20.8 Hz -- a 17% shortfall against the source's
 *   25 Hz, and one that silently scales gravity, jump height and every other
 *   per-tick constant in f.java. It is not a rounding artefact; it is the game
 *   running in slow motion.
 *
 *   Advancing by exactly one period from the PREVIOUS DEADLINE makes the period an
 *   identity rather than a bound: the same 60 s yields 1500 ticks, an average
 *   period of 40.00 ms and exactly 25.0 Hz. The quantisation error stays bounded
 *   by one frame, but it stops accumulating. This is the drift-free accumulator
 *   discipline the PSP reference port uses in main.c; what is kept from the source
 *   is the 40 ms period itself, which that port sets to 30 ms.
 *
 * WHY THERE IS STILL NO CATCH-UP BURST
 *   Java's `schedule(task, delay, period)` is FIXED-DELAY, not fixed-rate: the next
 *   run is scheduled `period` after the previous one COMPLETES, so a late run
 *   delays the next one instead of firing a backlog. A java.util.TimerTask also
 *   runs on a single thread, so it cannot overlap itself. The resync branch below
 *   reproduces that exactly: after a stall longer than one period (a debugger
 *   break, a swapped-out process, a suspended window) the missed deadlines are
 *   DISCARDED and the next deadline is placed one period from `now`, which is
 *   what Java computes at completion time. It is not an accumulator and not a
 *   replay loop: at most one tick runs per frame, so `app_timer_callback_dispatch()`
 *   is entered at most once per call and the self-test's one-dispatch-per-frame
 *   invariant still holds.
 *
 *   With lateness strictly below one period -- every tick in normal operation --
 *   the resync branch is not taken and the deadline walks forward one period at a
 *   time, so the cadence is exact. It is taken only when the deadline would
 *   already be in the past, which is precisely the backlog condition.
 *
 * NOTHING ELSE CHANGES: the period constant, the timer object and its counters,
 * the Tick dispatch, the physics continuation, the legacy route and every
 * self-test contract are untouched, and the deadline still sits at most one
 * period ahead of and at most one period behind the clock.
 */
static int app_run_canonical_gameplay_tick(BounceApp *app)
{
    int64_t now;
    int64_t next;
    BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

    if (app == NULL)
        return -1;
    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    if (app->canonical_next_tick_ms <= 0)
        app->canonical_next_tick_ms = now;
    if (now < app->canonical_next_tick_ms)
        return 0;
    /*
     * One period forward from the previous deadline, then the fixed-delay resync.
     * See the header comment: the first line is what removes the drift, the second
     * is what keeps a stall from turning into a burst.
     */
    next = app->canonical_next_tick_ms + BOUNCE_GAME_TIMER_PERIOD_MS;
    if (next <= now)
        next = now + BOUNCE_GAME_TIMER_PERIOD_MS;
    app->canonical_next_tick_ms = next;
    return app_timer_callback_dispatch(app, &branch);
}

/*
 * Leave canonical gameplay: release the owned level/runtime and stop the timer,
 * so no further canonical tick can run and a later start gets fresh state.
 */
static void app_end_canonical_gameplay(BounceApp *app)
{
    if (app == NULL)
        return;
    bounce_game_release_level(app);
    bounce_game_timer_init(&app->game_timer);
    app->canonical_next_tick_ms = 0;
}

/*
 * G-R3-T2 -- the retained mid-level session. The capture and the write are two
 * deliberately separate steps and neither touches gameplay:
 *
 *   app_capture_resume_snapshot()  runs at the gameplay edge, immediately
 *       BEFORE app_end_canonical_gameplay() releases the level. It is the last
 *       moment the values still exist, and it performs no I/O.
 *   app_write_resume_snapshot()    runs at the explicit main-menu Exit, which
 *       is the only Record 3 writer in the Java tree (Bounce.java:25, reached
 *       from destroyApp via BounceGame.java:258).
 *
 * D-14 IS A CONFLICT WITH THE SOURCE, AND THE SOURCE WINS. The audit lists D-14
 * as "Record 3 written on all menu-exit routes", glossed as destroyApp being
 * called on EXIT/BACK/OK while the main menu is active, "including when coming
 * back from Instructions / High Score / Level Select". The last clause does not
 * hold, and the difference is not a matter of emphasis:
 *
 *     BounceGame.java:249-256
 *         } else if (cmd == this.commandBack || cmd == this.commandExit
 *                     || cmd == this.i) {
 *             if (this.display.getCurrent() == this.c) {
 *                 this.s.destroyApp(true);       // <-- writes Record 3
 *                 this.s.notifyDestroyed();
 *             } else {
 *                 ShowMainMenu();                // <-- does NOT
 *             }
 *         }
 *
 * `this.c` is the MAIN MENU List, built by ShowMainMenu() at :112. commandBack is
 * attached only to the level List (:143) and to the High Score (:162) and
 * Instructions (:171) forms, and `this.i` only to the Game Over and Game End forms
 * (:193). Coming back from any of those, `getCurrent()` is that sub-screen's
 * Displayable and NOT this.c, so the handler takes ShowMainMenu() -- which stops
 * the timer at :131 and shows a different List at :132, and writes nothing.
 *
 * In practice only commandExit can reach the destroyApp branch at all, because it
 * is the one command attached to the main menu itself (:120). So the source has
 * exactly ONE Record 3 route, native has exactly one, and they agree. No snapshot
 * write was added to the sub-screen routes, because adding one would reproduce the
 * audit's misreading rather than the game.
 *
 * WHY THEY CANNOT BE ONE STEP. Java takes the snapshot at destroyApp and can,
 * because ShowMainMenu() (BounceGame.java:110-133) never destroys `this.v` --
 * it only stops the game timer at :131 and shows a separate List at :132. Native
 * has no such separation: leaving gameplay destroys the session (see
 * BounceGame.resume_record3 in game.h). A live instrumented run measured the
 * result at the menu-Exit site itself -- after really playing level 1 with
 * lives == 3, every field Record 3 serialises was already NULL or zero there.
 *
 * b1 IS THE SESSION'S JAVA `K`, NOT THE CURRENT STATE. BounceGame.java:354-359
 * encodes K (1 -> 1, 5 -> 2, otherwise 0), and ShowMainMenu() does not touch K,
 * so b1 is the K value at the moment the session ended. The two producers below
 * are exactly its two possibilities: a canonical gameplay session is K == 1
 * (BounceGame.java:156, set by a(boolean, int) on every gameplay start) and the
 * level-complete screen is K == 5 (:202, ShowLevelComplete). b1 == 0 is therefore
 * never produced from a live session, which matches Java: a live `v` implies
 * K is 1 or 5, because both paths that can start one end in K = 1.
 */

/*
 * System.currentTimeMillis(), BounceGame.java:360. CLOCK_REALTIME, not the
 * canonical game clock: Java's is a wall clock, and the value is written but
 * never consumed, so what matters is that it is a real timestamp and not a tick
 * count.
 */
static int64_t app_wall_clock_millis(void)
{
    struct timespec now;

    if (clock_gettime(CLOCK_REALTIME, &now) != 0)
        return 0;
    return (int64_t) now.tv_sec * INT64_C(1000)
        + (int64_t) (now.tv_nsec / 1000000L);
}

/*
 * BounceGame.java:385, the tile ids the snapshot records as deltas, in source
 * order. A tile is compared AFTER the mask below, so the ids are the unmasked
 * ones.
 */
static const uint8_t app_resume_saved_tile_ids[] = {
    7u, 29u, 13u, 14u, 21u, 22u, 15u, 16u, 23u, 24u
};

static bool app_resume_tile_id_is_saved(int32_t normalized_tile)
{
    size_t index;

    for (index = 0u;
         index < sizeof app_resume_saved_tile_ids
             / sizeof app_resume_saved_tile_ids[0];
         ++index) {
        if (normalized_tile == (int32_t) app_resume_saved_tile_ids[index])
            return true;
    }
    return false;
}

/*
 * BounceGame.java:382-398. Java walks rows outermost and columns innermost and
 * stores (row, col, id), and it reads LevelTiles[row][col]; native's
 * bounce_runtime_level_tiles_get() takes (x, y), so col is x and row is y.
 *
 * The mask is Java's `& 0xFF7F & (~0x40)`, which is already the audited
 * bounce_level_tile_value_persistence_without_water(), so the two 0x80 dirty
 * markings and the 0x40 water bit are dropped exactly as Java drops them.
 *
 * Java's array is new int[50][3] (:380) indexed by an unbounded byte, so a
 * level with more than 50 matching tiles makes Java itself throw. Native stops
 * at the same 50 rather than overflowing.
 */
static void app_capture_resume_tile_deltas(
    BounceApp *app,
    BouncePersistenceRecord3 *record
)
{
    uint32_t row;

    for (row = 0u; row < bounce_runtime_level_tiles_height(app->runtime);
         ++row) {
        uint32_t col;

        for (col = 0u; col < bounce_runtime_level_tiles_width(app->runtime);
             ++col) {
            uint16_t value = 0u;
            int32_t normalized;

            if (record->tile_delta_count
                >= BOUNCE_PERSISTENCE_RECORD3_MAX_TILE_DELTAS)
                return;
            if (bounce_runtime_level_tiles_get(
                    app->runtime, (int) col, (int) row, &value) != 0)
                continue;
            normalized = bounce_level_tile_value_persistence_without_water(value);
            if (!app_resume_tile_id_is_saved(normalized))
                continue;
            record->tile_deltas[record->tile_delta_count].row = (int16_t) row;
            record->tile_deltas[record->tile_delta_count].col = (int16_t) col;
            record->tile_deltas[record->tile_delta_count].tile_id
                = (uint8_t) normalized;
            ++record->tile_delta_count;
        }
    }
}

/*
 * BounceGame.java:400-406: the live w/ae animation offsets, short x and short y
 * for each, in thorn order. These are the OWNED runtime values, not the
 * immutable level payload, which is what Java reads: b.java advances w and ae
 * once per tick (e.java:282-283) and Record 3 must capture the advanced state.
 *
 * The count is bounded by 127 because Java reads it from a single byte
 * (b.java:248) and BounceGame.java:401 then loops with a signed byte. A larger
 * count is not representable, so it is reported as no thorns rather than
 * truncated to a wrong-length list.
 */
static void app_capture_resume_dyn_thorns(
    BounceApp *app,
    BouncePersistenceRecord3 *record
)
{
    const BounceDynThorns *thorns
        = bounce_runtime_level_tiles_dyn_thorns(app->runtime);
    uint32_t index;

    if (thorns == NULL || thorns->records == NULL)
        return;
    if (thorns->count > BOUNCE_PERSISTENCE_RECORD3_MAX_DYN_THORNS)
        return;
    for (index = 0u; index < thorns->count; ++index) {
        record->dyn_thorns[index].w_x = thorns->records[index].w.x;
        record->dyn_thorns[index].w_y = thorns->records[index].w.y;
        record->dyn_thorns[index].ae_x = thorns->records[index].ae.x;
        record->dyn_thorns[index].ae_y = thorns->records[index].ae.y;
    }
    record->dyn_thorn_count = thorns->count;
}

static void app_capture_resume_snapshot(
    BounceApp *app,
    BounceAppState from_state
)
{
    BouncePersistenceRecord3 record;

    if (app == NULL)
        return;
    memset(&record, 0, sizeof record);
    if (app->level == NULL
        || app->runtime == NULL
        || !app->player.initialized) {
        /*
         * STEP SAVE-CONTINUE -- NO LIVE LEVEL, AND THE REMEMBERED SNAPSHOT IS KEPT.
         *
         * This used to do `app->resume_record3 = record`, i.e. zero the field and
         * return. That is what destroyed the save, and it is worth being exact about
         * why, because the previous comment here argued for it and argued wrong.
         *
         * WHAT JAVA WRITES. destroyApp runs WriteToStore(3) at BounceGame.java:355-361,
         * and the two things it takes the values from are
         *
         *     b1    <- this.K          a STICKY field
         *     lives <- this.v.lives    the LIVE GAME OBJECT
         *
         * `this.v` is constructed once and is never discarded when the player walks back
         * to the main menu; only the game-over and game-complete paths change K, at
         * :431 and at the ShowLevelComplete call. So after playing a level and pressing
         * BACK, K is still 1 and `this.v` still holds the run, and destroyApp writes a
         * perfectly good record. Coming back to the menu does not invalidate anything.
         *
         * WHICH JAVA FIELD IS `app->resume_record3`. It is the native stand-in for that
         * pair -- sticky K plus the live object -- which is exactly why the main-menu
         * Exit row, which writes this field WITHOUT re-capturing, was right, and this
         * capture, which re-derives b1 from whether a level happens to be loaded right
         * now, was wrong.
         *
         * THE BUG, REPRODUCED. Play, press Escape, close the window:
         *
         *     after Escape   record3 present  b1=1 level=1 lives=3 pos=(30,78)
         *     window closed  record3 present  b1=0 level=0 lives=0 pos=(0,0)
         *     relaunch       Continue NOT available
         *
         * The save was overwritten with an inert one by the close handler's capture.
         * Closing the window from the main menu -- the way most players leave -- threw
         * away the run.
         *
         * SO THE FIELD IS LEFT ALONE. A fresh install still yields an inert record,
         * because `app` is zeroed at boot and nothing has ever captured into it; that is
         * the "never played" case the old comment was reaching for, and it is reached by
         * the field being empty rather than by the field being cleared. A confirmed Reset
         * zeroes it deliberately, in app_apply_reset_to_default(). A game over or a game
         * end writes b1 == 0 over the top, which is Java's K = 3 and is a real change of
         * state rather than an absence of one.
         *
         * Java's own guard at :352-353 -- `if (this.v == null || this.v.aq == null)
         * return;` -- skips the write entirely, which is the same outcome this produces
         * for a session that never existed. It cannot be reproduced literally because
         * `this.v` and `this.v.aq` are eagerly constructed, so native has no null to
         * test; keeping the remembered field is the equivalent.
         */
        return;
    }
    /*
     * STEP DV1 + DV2 -- the b1 mapping, corrected against BounceGame.java:355-358.
     *
     *     if (this.K == 1)      b1 = 1;
     *     else if (this.K == 5) b1 = 2;
     *     // otherwise b1 stays 0
     *
     * So b1 is a function of K alone, and K is the live in-memory state at the
     * moment destroyApp runs -- not the state the session began in. Every K
     * assignment in the recovered source is BounceGame.java:19 (K = 2, initial),
     * :156 (K = 1, StartGame), :202 (K = 5, ShowLevelComplete), :234 (K = 1,
     * resumed), :241 (K = 4, single-level fallback), :264 (K = 1,
     * commandContinue) and :431 (K = 3, TODO_ShowInstructions).
     *
     * THE TWO CORRECTIONS. The previous mapping treated every non-LEVEL_COMPLETE
     * state as in-level, which was wrong for BOTH terminal states:
     *
     *   GAME_OVER -> b1 = 0. TODO_ShowInstructions(false) is called from
     *     e.java:271 and sets K = 3 (BounceGame.java:431) and J = 0 (:432) before
     *     ShowGameEnd is ever reached (:434), so K is 3 and not 1.
     *
     *   GAME_END -> b1 = 0, for the SAME reason. A win does not come through
     *     ShowLevelComplete: e.java:321 routes level > 11 to
     *     TODO_ShowInstructions(true), which sets K = 3 the same way. The old
     *     comment at the game-end call site claimed K "still holds the value the
     *     gameplay start set, 1"; that was based on an enumeration of the K
     *     assignments that omitted :431, which is precisely the assignment that
     *     invokes ShowGameEnd. That comment is corrected at its own site below.
     *
     * WHY 0 IS THE RIGHT ANSWER AND NOT "KEEP THE OLD RECORD". Java does not skip
     * the write: destroyApp writes Record 3 with b1 = 0, overwriting whatever was
     * there. An inert record is therefore the faithful result, not a suppressed
     * write, and not a preserved previous snapshot. Java additionally latches
     * J = 0 in memory, which is what hides the Continue row (BounceGame.java:116
     * admits it only when K == 1 || J == 1 || J == 2). Native has no J latch --
     * it re-derives availability from the stored record on every menu arrival --
     * so writing b1 = 0 is how the same observable outcome is produced here.
     *
     * b1 = 2 remains reachable for exactly one production state, LEVEL_COMPLETE,
     * because K = 5 is set only by ShowLevelComplete and nothing else.
     */
    if (from_state == BOUNCE_APP_STATE_LEVEL_COMPLETE)
        record.b1 = (uint8_t) BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE;
    else if (from_state == BOUNCE_APP_STATE_GAME_OVER
             || from_state == BOUNCE_APP_STATE_GAME_END)
        record.b1 = (uint8_t) BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
    else
        record.b1 = (uint8_t) BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    record.lives = (uint8_t) app->lives;
    record.hoops_scored = (uint8_t) app->hoops_scored;
    record.level = (uint8_t) app->level_id;
    record.ball_size = (uint8_t) app->player.ballSize;
    record.score = app->score;
    /* Written by Java and never read back; see BouncePersistenceRecord3. */
    record.l = app->l;
    record.k = app->k;
    record.unk_x = app->player.TODO_unkX;
    record.unk_y = app->player.TODO_unkY;
    record.aq_l = app->player.horizontal_velocity;
    record.aq_o = app->player.o;
    /* BounceGame.java:373-374 are literal zeros in Java. */
    record.zero_slot_0 = 0;
    record.zero_slot_1 = 0;
    /*
     * aq.d and aq.c (BounceGame.java:375-376) are f.d and f.c, and the STEP
     * G-R3-R1-A audit established what they actually are: NOT the player's
     * current cell.
     *
     * f.d and f.c are written only by f.a(tileX, tileY) (f.java:134-138), and
     * that method has exactly two callers -- e.java:107 (the resume) and
     * e.java:122 (InitializeGame). Nothing in the tick path ever calls it. They
     * are read only by f.java:482, the crystal collector, and e.java:274-280,
     * where the death path rebuilds aq at `d * 12 + 6, c * 12 + 6` before
     * restoring d, c and b onto the new object. So they are the SPAWN/RESPAWN
     * TILE, fixed once when the level or the resume begins, and they stay fixed
     * for the whole session.
     *
     * The native owner of that quantity is BouncePlayerSpawn.tile_x/tile_y,
     * written by bounce_player_initialize_from_level() in the same call that
     * sets player.initialized, so the capture guard above already implies they
     * are valid. game->spawn is assigned by bounce_game_load_level() and
     * bounce_game_initialize_player_entry(), and only bounce_game_release_level()
     * clears it -- which runs immediately AFTER this capture.
     *
     * This replaces an earlier, wrong derivation of TODO_unkX / BOUNCE_TILE_SIZE,
     * which is the live cell. That agrees with the spawn tile only while the ball
     * is still on its starting cell and diverges as soon as it moves, so it was
     * saving a different quantity from the one Java saves. The live cell is still
     * available where it is actually needed -- the audited f.java:155-156 probe
     * derives it from the pixel position on every use -- and is deliberately not
     * persisted here, because Java does not persist it either.
     */
    record.tile_x = app->spawn.tile_x;
    record.tile_y = app->spawn.tile_y;
    record.power_up_1 = app->player.TODO_somePowerUp1;
    record.power_up_gravity = app->player.powerUpGravity;
    record.power_up_3 = app->player.TODO_somePowerUp3;
    app_capture_resume_tile_deltas(app, &record);
    app_capture_resume_dyn_thorns(app, &record);
    app->resume_record3 = record;
}

/*
 * The single production Record 3 writer: the explicit main-menu Exit.
 *
 * The timestamp is stamped HERE and not at the capture, because that is where
 * Java takes it: System.currentTimeMillis() is the second statement of
 * WriteToStore(3) (BounceGame.java:360), which is called from destroyApp, so
 * the value is the moment the record is written and not the moment the session
 * ended. The two can be far apart -- the menu can sit open for as long as the
 * player likes -- and stamping at the capture would quietly report the wrong
 * one. It also means the never-played record is stamped, which is what Java
 * writes when destroyApp runs before any gameplay.
 *
 * It is never fatal. bounce_persistence_save_record3() failing leaves the store
 * untouched, which is the same policy as every other persistence write here and
 * the same one Java has, because WriteToStore's catch block is empty
 * (BounceGame.java:413-414).
 */
static void app_write_resume_snapshot(BounceApp *app)
{
    if (app == NULL)
        return;
    app->resume_record3.timestamp_millis = app_wall_clock_millis();
    (void) bounce_persistence_save_record3(&app->resume_record3);
}

/*
 * STEP G-R3-T2-FIX -- PUBLISH THE CAPTURED SNAPSHOT WHEN A SESSION ENDS.
 *
 * THE DEFECT THIS CLOSES, STATED AS THE SEQUENCE IT PRODUCED.
 *
 *   Record 3 was written in exactly two places in the whole program: the explicit
 *   main-menu Exit row and the window close. Both are application teardown. Every
 *   OTHER way a session can end -- walking out of gameplay with the Escape key,
 *   accepting the Game Over or Game End form -- captured the snapshot into
 *   app->resume_record3 and then threw it away, because the capture is a pure
 *   in-memory read and only app_write_resume_snapshot() performs the store write.
 *
 *   The availability refresh immediately afterwards re-reads the store, not the
 *   capture, so on those edges it derived Continue from whatever the LAST teardown
 *   had written. The observable result is the reported one: die on level 3, press
 *   OK, and the main menu still offers Continue -- pointing at level 2, because
 *   level 2 is what the previous exit happened to save. The run that had just ended
 *   was still resumable and the level it belonged to was wrong.
 *
 * WHY JAVA DOES NOT SHOW THIS, AND WHY THAT IS NOT AN EXCUSE.
 *
 *   In the original the invalidation is a pair of in-memory assignments, not a
 *   store write:
 *
 *     BounceGame.java:431-432   TODO_ShowInstructions: this.K = 3; this.J = 0;
 *     BounceGame.java:116       ShowMainMenu appends Continue only when
 *                               `K == 1 || J == 1 || J == 2`
 *
 *   so the latch J is cleared the moment the terminal form appears and ShowMainMenu
 *   simply never appends the row. Record 3 on disk is left alone, and it does not
 *   matter, because nothing consults it again in that session.
 *
 *   Native has no J latch. Its Continue availability is RE-DERIVED FROM THE STORE on
 *   every menu arrival (app_refresh_continue_availability), which is a deliberate
 *   choice -- it is why a Continue written by a previous launch is honoured at all.
 *   The consequence is that the store, not a field, is the thing that has to be
 *   brought up to date at the transition, because it is the store the next arrival
 *   will read. Java can afford to defer its write to destroyApp; native cannot
 *   defer it past the point where the session ends.
 *
 * WHAT IS WRITTEN. Whichever record the capture just produced, unchanged. That
 * preserves every b1 case the capture already distinguishes, so the four endings
 * each get the right behaviour with no new state and no new branch here:
 *
 *   GAMEPLAY, lives >= 0   b1 = 1   Continue resumes this level at this position
 *                                   with these lives -- the "save while you still
 *                                   have lives" case, kept fresh on every exit.
 *   LEVEL_COMPLETE         b1 = 2   Continue restarts the NEXT level from its
 *                                   beginning, carrying score and lives (the R2
 *                                   record-continue route).
 *   GAME_OVER / GAME_END   b1 = 0   INERT. The refresh that follows reads it and
 *                                   reports Continue unavailable, which is the
 *                                   requested behaviour: after a game over the only
 *                                   way back in is New Game, and from there Level
 *                                   Select offers the levels already unlocked.
 *   no session owned       zeroed record, also inert -- "never played".
 *
 * WHY IT IS NOT DONE PER TICK. This runs on a screen transition, at most once per
 * arrival at the menu, and the payload is a few hundred bytes at most. Writing it
 * every tick would be a filesystem write 25 times a second for a value that only
 * changes when the player leaves a level.
 *
 * IT IS NOT FATAL IF IT FAILS, for the reason given on app_write_resume_snapshot():
 * a failed write leaves the previous record in place, and the refresh then reads
 * that. That is a stale-Continue rather than a crash, which is the same failure
 * mode the game already had.
 */
static void app_persist_resume_snapshot_for_continue(BounceApp *app)
{
    if (app == NULL)
        return;
    app_write_resume_snapshot(app);
}

/*
 * ===================================================================
 * G-R3-R2 -- CONTINUE availability and the menu-to-resume handoff.
 * ===================================================================
 *
 * WHAT JAVAS DOES. BounceGame.LoadRecords() runs once in the constructor and
 * stores the record-3 selector in this.J (BounceGame.java:293), and
 * ShowMainMenu() reads that field every time it builds the menu row list
 * (:116-117). Java's own condition for showing the row is `K == 1 || J == 1 ||
 * J == 2` (BounceGame.java:116), and commandAction maps row 0 to the Continue
 * branch whenever J != 0 (:222-235).
 *
 * WHY NATIVE CANNOT CACHE IT IN THE FLOW. J is a BounceGame field that survives
 * showing the menu. Native's equivalent, menu.continue_available, lives inside
 * BounceMenuState, and bounce_app_flow_enter_menu() calls
 * bounce_app_flow_reset_menu(), which clears it (app_flow.c:10-11). That is why
 * availability is re-established on every production ARRIVAL at the menu rather
 * than once at startup -- the same reason available_level_count is carried
 * outside the menu struct.
 *
 * WHY b1 == 1 ONLY. R1 established the two selectors: b1 == 1 is a mid-level
 * state and b1 == 2 is a level-complete state. Java routes those down different
 * methods -- :228 takes the two-argument e.a(int,int), which is the full R1
 * restore, while :230 takes the three-argument e.a(int,int,int) with
 * RecordLevel/RecordScore/RecordLives, which R1 deliberately did not implement.
 * Treating b1 == 2 as resumable here would advertise a full resume that the R1
 * restore cannot honour, so it is reported unavailable instead. A missing,
 * malformed or rejected record is unavailable by construction: this reads
 * through the existing decoder and adds no validation of its own.
 */
static void app_refresh_continue_availability(BounceApp *app)
{
    BouncePersistenceRecord3 record;
    bool present = false;

    /*
     * Guarded on MENU because bounce_app_flow_menu_set_continue_available()
     * requires it, and because this is called from paths that also serve other
     * states. It must never run while an action is pending: that setter clears
     * menu.pending_action, which would discard a Continue selection in flight.
     */
    if (app == NULL
        || app->flow.state != BOUNCE_APP_STATE_MENU
        || app->flow.menu.pending_action != BOUNCE_MENU_ACTION_NONE)
        return;
    (void)bounce_persistence_load_record3(&record, &present);
    /*
     * D-03/D-04 -- J == 1 OR J == 2, which is the source's own predicate.
     *
     * BounceGame.java:116 appends the Continue row when
     *
     *     this.K == 1 || this.J == 1 || this.J == 2
     *
     * and LoadRecords() assigns J straight from the record's b1 byte
     * (BounceGame.java:293, `this.J = recordDIS.readByte();`), zeroing it only if
     * the trailing magic does not match (:330-331) or anything throws (:332-333).
     * WriteToStore(3) is what chooses that byte, at BounceGame.java:354-359:
     *
     *     b1 = 0;
     *     if (this.K == 1) {
     *         b1 = 1;
     *     } else if (this.K == 5) {
     *         b1 = 2;
     *     }
     *
     * So b1 == 1 is "written while playing a level" and b1 == 2 is "written on the
     * level-complete screen", and BOTH of them make Java offer Continue.
     * Before D-03 this tested b1 == 1 alone, so a b1 == 2 store showed a
     * Continue row that could never work: the row was appended and the SELECT
     * handler then refused the record.
     *
     * b1 == 0 is still refused, and that is correct rather than lenient: it is
     * Java's J == 0, produced whenever K was neither 1 nor 5, and commandAction's
     * `else if (this.J != 0)` has no branch for it.
     */
    (void)bounce_app_flow_menu_set_continue_available(
        &app->flow,
        present && (record.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL
                    || record.b1
                        == BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE)
    );
}

/*
 * The menu half of the resume. This only INITIATES: it decodes the record,
 * hands the level and lives to the R1 entry, and arms the latch. Every gameplay
 * decision -- loading, the tile transform, the thorn install, the player restore,
 * activation and the first tick -- stays in the canonical chain and the R1
 * restore window, exactly as the R1 checkpoint established.
 *
 * Only level_id and lives cross this boundary, per the R2 scope. Score,
 * HoopsScored, player position, spawn, power-ups and the thorn offsets are read
 * by R1 straight out of app->resume_record3, never through the menu.
 *
 * Returns 0 when the resume was initiated, 1 when CONTINUE was selected but no
 * resumable record backs it, and -1 for a NULL app.
 */
static int app_begin_resume_from_menu(BounceApp *app)
{
    BouncePersistenceRecord3 record;
    bool present = false;

    if (app == NULL)
        return -1;
    if (app->flow.menu.pending_action != BOUNCE_MENU_ACTION_CONTINUE)
        return 1;
    if (bounce_persistence_load_record3(&record, &present) != 0)
        return 1;
    if (!present)
        return 1;
    if (record.level < BOUNCE_APP_FIRST_LEVEL_ID
        || record.level > BOUNCE_APP_LAST_LEVEL_ID)
        return 1;

    /*
     * D-03/D-04 -- THE TWO J BRANCHES ARE DIFFERENT OPERATIONS, so b1 selects
     * the route rather than merely gating it.
     *
     * BounceGame.java:227-233:
     *
     *     if (this.J == 1) {
     *         this.v.a(this.y, this.M);               <- e.java:92  POSITION
     *     } else {
     *         this.v.a(this.RecordLevel, this.RecordScore,
     *                  this.RecordLives);              <- e.java:81  RESTART
     *     }
     *
     * which is why this function no longer refuses every record whose b1 is not
     * B1_IN_LEVEL. Before D-03 that single test was the whole condition, and a
     * B1_LEVEL_COMPLETE record -- Java's J == 2 -- produced "no resumable record
     * backs it", leaving the Continue row present and dead.
     *
     * The payload is copied whole rather than field by field, for both routes:
     * app->resume_record3 IS the record, and whichever window consumes the latch
     * reads all of it from there. The copy leaves the T2 capture path untouched --
     * it overwrites the same field at capture time, and nothing here runs during
     * gameplay.
     */
    app->resume_record3 = record;

    if (record.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL) {
        app->resume_requested = true;
        if (bounce_app_flow_begin_resume_entry(
                &app->flow,
                (int) record.level,
                (int) record.lives
            ) != 0) {
            app->resume_requested = false;
            return 1;
        }
        return 0;
    }

    if (record.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE) {
        /*
         * J == 2. `resume_requested` is DELIBERATELY NOT SET, because that flag
         * means "run the mid-level restore window" and Java's J == 2 branch does
         * not restore a position -- it starts the level again. Running the window
         * here would drop the player back on the tile they finished on, which is
         * the exact opposite of e.a(level, score, lives).
         */
        app->continue_record_pending = true;
        if (bounce_app_flow_begin_record_continue_entry(
                &app->flow,
                (int) record.level,
                (int) record.score,
                (int) record.lives
            ) != 0) {
            app->continue_record_pending = false;
            return 1;
        }
        return 0;
    }

    /*
     * THE THIRD ROUTE, `K == 1`, IS NOT IMPLEMENTED, AND THE REASON IS STRUCTURAL
     * RATHER THAN A GAP. BounceGame.java:223-224 is
     *
     *     if (this.K == 1) {
     *         a(false, this.v.level);
     *     } else if (this.J != 0) {
     *
     * and `a(false, level)` re-enters THE SAME `e` OBJECT -- MIDP's display keeps
     * the canvas alive behind the menu, so `this.v` still holds its loaded level,
     * its mutable tiles, its player and its thorns. K only stops being 1 by going
     * to 5 at the level-complete screen (BounceGame.java:202) or to 3 on the
     * game-over form (:431), so at the main menu K == 1 means "the app was
     * backgrounded mid-level and hideNotify called ShowMainMenu()", and the
     * player resumes the canvas they never left.
     *
 * NATIVE HAS NO SUCH OBJECT TO RESUME, AND THE REASON IS ONLY HALF TRUE NOW.
 * app_end_canonical_gameplay() at :7794 calls bounce_game_release_level(),
 * which destroys the level, the player and the timer, and the ESCAPE edge calls
 * it before the menu is entered. So the Escape route ends the session, exactly
 * as the previous revision of this note said.
 *
 * THE FOCUS-LOSS ROUTE DOES NOT, and that landed after this note was written.
 * app_apply_focus_lost() -- the hideNotify edge of 69e5c2d, e.java:473-480 --
 * resets the key mask and applies BOUNCE_APP_EVENT_MENU, and applies NOTHING
 * else. It does not release. Measured, from a canonical gameplay session on level
 * 1:
 *
 *     before  state=GAMEPLAY runtime=1 score=0 level=1
 *     after   state=MENU     runtime=1 canonical=0 continue_available=0
 *
 * So native DOES now hold exactly what Java's K == 1 holds: a loaded level, a
 * score and lives, sitting behind a menu. What it does not do is offer it. The
 * menu's Continue row is gated on menu.continue_available, which that edge leaves
 * false, so the retained session is unreachable -- present and inert.
 *
 * THAT IS WHY THIS IS STILL REPORTED RATHER THAN WIRED. The blocker is no longer
 * "there is nothing to resume". It is that getting back into gameplay from the
 * menu has exactly one shape in native, the staged chain in
 * app_begin_canonical_gameplay(), and that chain is what establishes the level
 * load, the restore window, the camera, the activation and the first tick in that
 * order. a(false, level) needs a route that skips the level load and keeps
 * everything after it, which is a THIRD way into canonical gameplay, not a branch
 * in a menu handler. Adding one here would mean stating, from scratch and without
 * the source to check it against, that the timer start, the camera init, the
 * player activation and the first tick are safe to run on a runtime that was
 * never reloaded -- and the 12X-G-R3 crash class exists precisely because that
 * ordering was wrong once and nothing caught it.
 *
 * THE MENU PATH IS NOT A WAY AROUND IT, and it is worth saying why, because it
 * looks like one. Record 3 holds level, score and b1 -- persistence.h:219 states
 * that b1 is not gameplay state. Resuming from it is Java's J == 2, which native
 * already implements, and presenting it as K == 1 would claim a mid-level resume
 * that the record cannot carry: the mutated tile grid, the collected hoops, the
 * dyn-thorn offsets and the player's own position are all absent from it.
 *
 * THERE IS A SECOND JAVA ROUTE TO A MENU WITH K == 1, and its keys are not
 * readable. e.java:386-390 handles raw key codes -7 and -6 with
 * `this.H = false; this.game.ShowMainMenu();`, which also leaves K alone. Those
 * are raw key codes rather than game actions, and nothing in the repository says
 * what they are -- the same ITUKeyMap gap recorded as
 * EXTERNAL-MAPPING-NOT-RECOVERED in app_request_w1_completion()'s comment. The
 * native Escape edge is the honest counterpart to that route in shape (leave
 * gameplay for the menu) but not in resource handling, and the difference is
 * deliberate: Escape releases the session because the menu is not a MIDP display
 * stack, and MIDP's display is exactly what makes K == 1 resumable at all.
     *
     * The three conditions are therefore not three implementable peers. J == 1 and
     * J == 2 both restore from the RECORD, which is why the routes above are
     * faithful, while K == 1 restores from LIVE STATE that this architecture does
     * not keep. Reported rather than forced.
     *
     * b1 == B1_NONE, and Java's own encoding produces exactly that whenever the
     * snapshot was taken outside a level: BounceGame.java:354-359 writes b1 = 0
     * unless K == 1 or K == 5, and K == 3 (the game-over form's
     * TODO_ShowInstructions, :431) is neither. A record with b1 == 0 therefore
     * means "never in a level", which is Java's J == 0, and commandAction's
     * `else if (this.J != 0)` falls through with no branch at all.
     */
    return 1;
}

/*
 * ===================================================================
 * G-R3-R1 -- the Record 3 resume restore, e.a(int,int) (e.java:92-113).
 * ===================================================================
 *
 * PLACEMENT. This is the single restore window established by R1-B: inside
 * app_begin_canonical_gameplay(), after stage 3 and before stage 4. At that
 * point the mutable runtime tiles, the dyn-thorn records, the player and the
 * spawn all exist, and the camera, the timer and the first tick have not. R1-B
 * proved there is no post-chain window at all: app_update_production_game()
 * dispatches the first tick in the same call as the chain, so a restore placed
 * after the chain would be one tick late.
 *
 * ORDER WITHIN THE WINDOW FOLLOWS THE SOURCE, with the one documented exception
 * that native cannot express the same way:
 *
 *   Java :93  level            -> recorded into the flow by
 *                                 bounce_app_flow_record_resume_entry(), not here
 *   Java :94  HoopsScored      -> here
 *   Java :95  lives            -> recorded into gameplay_entry.initial_lives,
 *                                 installed by stage 5 (R1-E decision L-A)
 *   Java :96  score            -> here (R1-E decision S-C; safe because the
 *                                 resume never sets new_game_score_reset_pending,
 *                                 so stage 5 does not zero it)
 *   Java :98  LoadLevelId      -> stage 1
 *   Java :99  k()              -> here
 *   Java :100 AddScore()       -> here
 *   Java :105 player creation  -> stage 2, then overwritten here
 *   Java :107 aq.a(tile)       -> here, onto the spawn tile
 *   Java :108-110 powerups     -> here
 *   Java :111 T = true         -> NOT reproduced: e.T has zero readers anywhere
 *                                 in the Java tree (R1-A), so it is a dead store
 *   Java :101-102 p, y         -> p is flow.gameplay_entry.countdown, armed by the
 *                                 existing entry (app_flow.c:932). y is NOT
 *                                 reproduced: game.h:144 records that decision
 *
 * The ordering of HoopsScored/score before k() and AddScore() is the Java order
 * and is also the cheapest: none of them touch tiles, thorns, the player or the
 * spawn, so they commute. They are placed first because that is what the source
 * does and because HoopsScored has no canonical-chain writer to race (R1-E).
 */

/*
 * Java e.k(), e.java:494-548. Restores the tile grid.
 *
 * THE SAVED LIST IS AN EXCLUSION SET. Java's a(row,col,id) at e.java:542-548
 * returns FALSE when the coordinate IS in the saved list, and every switch arm is
 * guarded by `if (a(...))`. So a saved coordinate KEEPS its pristine tile, and
 * every other tile of a supported type is transformed. That is the opposite of a
 * patch list, and getting it backwards would invert the level.
 *
 * THE STORED tile_id IS NEVER CONSULTED. The read at e.java:544 compares only
 * u[b1][0] and u[b1][1]; u[b1][2] is written by BounceGame.java:387 and read back
 * at :317, and nothing else in the tree reads it. It is retained in Record 3 for
 * byte fidelity with the original format, not because the restore needs it.
 *
 * THE SWITCH SELECTS ON THE LIVE CELL, masked; the water bit comes from a SEPARATE
 * raw read. e.java:497 computes b3 = cell & 0xFF7F & ~0x40 for the case, while the
 * write at e.java:501 and its nine siblings is `LITERAL | (LevelTiles[b1][b2] &
 * 0x40)` -- the raw value, because & binds tighter than | in Java. One native read
 * per cell is equivalent: no write occurs between the two Java reads for the same
 * cell.
 *
 * 0x80 CANNOT SURVIVE. The mask clears it and the literal replacement discards it,
 * so the transform result never carries it.
 */
static void app_resume_restore_tiles(BounceApp *app)
{
    const BouncePersistenceRecord3 *record = &app->resume_record3;
    uint32_t row;

    for (row = 0u; row < bounce_runtime_level_tiles_height(app->runtime);
         ++row) {
        uint32_t col;

        for (col = 0u; col < bounce_runtime_level_tiles_width(app->runtime);
             ++col) {
            uint16_t raw = 0u;
            int32_t masked;
            int32_t literal;
            uint32_t index;
            bool excluded = false;

            if (bounce_runtime_level_tiles_get(
                    app->runtime, (int) col, (int) row, &raw) != 0)
                continue;
            masked = bounce_level_tile_value_persistence_without_water(raw);
            if (!app_resume_tile_id_is_saved(masked))
                continue;

            /*
             * e.java:543-546 scans the whole saved list and returns on the FIRST
             * match, so duplicate coordinates in the record are equivalent to a
             * single exclusion. Short-circuiting on first match reproduces that.
             */
            for (index = 0u; index < record->tile_delta_count; ++index) {
                if (record->tile_deltas[index].row == (int16_t) row
                    && record->tile_deltas[index].col == (int16_t) col) {
                    excluded = true;
                    break;
                }
            }
            if (excluded)
                continue;

            switch (masked) {
            case 7:
            case 29:
                literal = 0x00;
                break;
            case 13:
                literal = 0x11;
                break;
            case 14:
                literal = 0x12;
                break;
            case 21:
                literal = 0x19;
                break;
            case 22:
                literal = 0x1A;
                break;
            case 15:
                literal = 0x13;
                break;
            case 16:
                literal = 0x14;
                break;
            case 23:
                literal = 0x1B;
                break;
            case 24:
                literal = 0x1C;
                break;
            default:
                continue;
            }
            /*
             * The water bit comes from the RAW cell, matching e.java:501. The
             * literal occupies the low byte and 0x40 sits above it, so the two
             * never collide.
             *
             * A -1 here means the coordinate was rejected by the bounds check.
             * That is native safety on a record the decoder already validated for
             * count and size; it is not a new validation policy and it is not
             * treated as success, so the cell simply keeps its loaded value.
             */
            (void) bounce_runtime_level_tiles_set(
                app->runtime,
                (int) col,
                (int) row,
                (uint16_t)(literal
                    | bounce_level_tile_value_water(raw))
            );
        }
    }
}

/*
 * Java e.AddScore(), e.java:482-492. Restores the dynamic-thorn animation phase.
 *
 * The count bound is the record's own, and the seam refuses a count larger than
 * the records the runtime owns rather than installing a partial state -- Java has
 * no such check and would throw instead. No UpdateDynThorns() equivalent is
 * called here, because Java does not call UpdateDynThorns() from AddScore(): that
 * runs only from the tick at e.java:282-283, and advancing here would corrupt the
 * very phase being restored.
 */
static int app_resume_restore_dyn_thorns(BounceApp *app)
{
    BounceVec2S w_values[BOUNCE_PERSISTENCE_RECORD3_MAX_DYN_THORNS];
    BounceVec2S ae_values[BOUNCE_PERSISTENCE_RECORD3_MAX_DYN_THORNS];
    const BouncePersistenceRecord3 *record = &app->resume_record3;
    uint32_t count = record->dyn_thorn_count;
    uint32_t index;

    if (count == 0u)
        return 0;
    if (count > BOUNCE_PERSISTENCE_RECORD3_MAX_DYN_THORNS)
        return -1;
    for (index = 0u; index < count; ++index) {
        w_values[index].x = record->dyn_thorns[index].w_x;
        w_values[index].y = record->dyn_thorns[index].w_y;
        ae_values[index].x = record->dyn_thorns[index].ae_x;
        ae_values[index].y = record->dyn_thorns[index].ae_y;
    }
    return bounce_runtime_level_tiles_restore_dyn_thorns(
        app->runtime,
        count,
        w_values,
        ae_values
    );
}

/*
 * The whole restore window body. Called once, from app_begin_canonical_gameplay(),
 * between stage 3 and stage 4.
 *
 * Every failure below is contained: a rejected tile coordinate leaves that cell as
 * loaded, and a refused dyn-thorn count leaves the loaded animation phase in
 * place. None of them aborts the chain, because Java's own failure modes here are
 * exceptions that a native port must not convert into "the level will not load".
 */
static void app_resume_restore_payload(BounceApp *app)
{
    const BouncePersistenceRecord3 *record = &app->resume_record3;

    /* Java :94 -- HoopsScored. No canonical-chain writer exists (R1-E). */
    app->hoops_scored = (int) record->hoops_scored;

    /*
     * Java :96 -- score. Safe here because the resume path never sets
     * new_game_score_reset_pending, so stage 5's bounce_game_reset_score() is not
     * reached and cannot overwrite this. R1-E decision S-C.
     */
    app->score = record->score;

    /* Java :99 -- k(). */
    app_resume_restore_tiles(app);

    /* Java :100 -- AddScore(). */
    (void) app_resume_restore_dyn_thorns(app);

    /*
     * Java :105 via a(x, y, ballSize, aq.l, aq.o) at e.java:126-133. Stage 2
     * already built a default player from the level header; these overwrite the
     * five saved scalars. TODO_unkX/TODO_unkY are the saved WORLD position, which
     * is what e.java:127 passes to new f(x, y, ...).
     */
    app->player.TODO_unkX = record->unk_x;
    app->player.TODO_unkY = record->unk_y;
    app->player.ballSize = record->ball_size;
    app->player.horizontal_velocity = record->aq_l;
    app->player.o = record->aq_o;

    /*
     * Java :107 -- aq.a(game.e, game.b), which is f.a(tileX, tileY) at
     * f.java:134-138 and assigns d, c and b=ballSize. d and c are the SPAWN /
     * RESPAWN tile, fixed when the level or resume began and never updated during
     * play (R1-A), so the target is the spawn record rather than anything derived
     * from the current pixel position. F1 already writes these two Record 3
     * fields from app->spawn.
     *
     * e.java:137 also assigns b = ballSize, which is the same value just restored
     * onto player.ballSize above.
     */
    app->spawn.tile_x = record->tile_x;
    app->spawn.tile_y = record->tile_y;

    /* Java :108-110 -- the three power-ups. */
    app->player.TODO_somePowerUp1 = record->power_up_1;
    app->player.powerUpGravity = record->power_up_gravity;
    app->player.TODO_somePowerUp3 = record->power_up_3;
}

/*
 * The single production gameplay-update seam used by the frame loop. Canonical
 * gameplay runs the verified timer path; every other state keeps the legacy
 * app_update_game() path completely unchanged.
 */
static int app_update_production_game(BounceApp *app)
{
    if (app == NULL)
        return -1;
    if (app_begin_canonical_gameplay(app) != 0)
        return -1;
    if (app_canonical_gameplay_active(app))
        return app_run_canonical_gameplay_tick(app);
    /*
     * CANONICAL GAMEPLAY HAS ENDED. Return without routing anywhere.
     *
     * Reaching here with the entry's gameplay_activated marker already set means
     * this run went through bounce_game_activate_staged_level() -- the only
     * production caller of which is app_begin_canonical_gameplay() at :4665 --
     * and the canonical timer has since stopped. In the source there is exactly
     * one way that happens during play:
     *
     *   e.java:267-273   if (this.aq.z == 1) {
     *   e.java:268           if (this.lives < 0) {
     *   e.java:269               this.game.WriteToStore();
     *   e.java:270               StopGameTimer();
     *   e.java:271               this.game.TODO_ShowInstructions(false);
     *   e.java:272               return;
     *
     * Java is terminal there because the timer is the ONLY driver of gameplay.
     * BounceTimer.java:20-22 run() is the sole caller of b.java:848-850
     * GameTimerTick(), which is the sole caller of the b.java:833 Tick() that
     * e.java:221 overrides, and StopGameTimer() (b.java:841-846) cancels the
     * TimerTask via BounceTimer.java:24-30. So Tick() simply never runs again:
     * no e.java:263 e(), no e.java:265 aq.b() physics, no UpdateDynThorns().
     * The e.java:272 return is equally final, because the world render q() and
     * repaint() at e.java:310-312 sit AFTER it, so even the last frame is not
     * redrawn; paint() (e.java:192-207) only blits the frozen imageFullscreen.
     * There is no second gameplay path in the source to fall into.
     *
     * Native has one, and that is what this guard closes. The single
     * `started` boolean was carrying two incompatible meanings: "may a gameplay
     * tick run?" (game.c:662 bounce_game_tick_dispatch and game.c:623
     * bounce_game_initialize_game_timer, which both refuse) and "which route
     * should this frame take?" (app_canonical_gameplay_active() at :4637, which
     * re-routes). Game Over sets started = false through
     * bounce_game_timer_stop() (game_timer.c:51), which faithfully mirrors
     * b.java:845 nulling GameTimer, so the canonical path did stop correctly --
     * but the router read the same flag as "switch to the legacy route".
     *
     * The observable result before this guard: the ball is still overlapping the
     * thorn, so the first legacy tick re-entered the Death Core and moved
     * lives -1 -> -2, z 1 -> 2, q 0 -> 7, stranding the game in a death
     * countdown that nothing could ever finish, because no further tick ran.
     * Java leaves lives == -1 and the frame frozen.
     *
     * Why gameplay_activated is the discriminator and not app->game_over: the
     * source has no state variable for this at all, and e.java:267-273 changes
     * no state -- only the timer. app->game_over means something else
     * entirely: game.c:795-797 raises it together with
     * state = BOUNCE_GAME_STATE_GAME_OVER, a UI transition, and its only
     * raiser is a temporary debug key (vertical_slice.c:14411). It is never
     * written on the staged path. The entry marker, by contrast, is true if and
     * only if the staged activation ran, and the legacy diagnostic path
     * (bounce_game_start_level -> bounce_app_flow_apply(BOUNCE_APP_EVENT_START))
     * never sets it, which is precisely what keeps that path working below.
     *
     * Nothing else changes: the timer, StopGameTimer, the lives < 0 boundary,
     * the Death Core, app_update_game(), app_run_player_ticks() and
     * app_canonical_gameplay_active() are all untouched, and state stays
     * PLAYING exactly as the source leaves it.
     */
    if (bounce_app_flow_entry_gameplay_activated(&app->flow))
        return 0;
    /*
     * Telemetry only: a PLAYING frame reaching here is a frame in which
     * app_run_player_ticks() was allowed to run player ticks. During canonical
     * gameplay the early return above makes this unreachable, so the count
     * must stay 0. Never read for control flow.
     */
    if (app->state == BOUNCE_GAME_STATE_PLAYING)
        ++app->legacy_player_tick_route_count;
    return app_update_game(app);
}

/*
 * Single opt-in live read-out for the production main loop. This is the whole
 * diagnostic: one line per second carrying the canonical tick counters, the
 * legacy player-tick route count, and the player position, so a real run can be
 * checked for double physics without any second scheduler or harness.
 */
static int app_live_status_report(
    BounceApp *app,
    bool enabled,
    int64_t *next_report_ms
)
{
    int64_t now;

    if (app == NULL || !enabled)
        return 0;
    now = monotonic_milliseconds();
    if (now < 0)
        return -1;
    if (*next_report_ms == 0) {
        /* Report immediately so a short run is still observable. */
        *next_report_ms = now;
    }
    if (now < *next_report_ms)
        return 0;
    *next_report_ms = now + INT64_C(1000);
    printf(
        "LIVE state=%d flow=%d timer_started=%d "
        "tick_entry=%llu tick_dispatch=%llu player_tick=%llu physics=%llu "
        "dyn_thorn=%llu legacy_player_tick_route=%lld player=(%d,%d) "
        /*
         * DOOR CHAIN -- OBSERVABILITY ONLY. Six reads of state that already
         * exists, appended to the existing line. Nothing here writes, derives
         * or shadows any of these values: each is the same field the game logic
         * uses, and each is read once at report time. There is no new state, no
         * new mode, and no change to any writer, gate or animation step.
         *
         *   HoopsScored             e.java:29  / app->hoops_scored
         *   HoopsTotal              b.java:150 / bounce_level_hoops_total()
         *   TODO_ExitUnlocked       e.java:41  / app->TODO_ExitUnlocked
         *   (door_animation_active was listed here as "e.java:291 else-arm". It
         *   was not: e.java:291 is a BODY branch, not a state variable, and
         *   D-09 removes it. See the gate.)
         *   door_image_offset       b.java:825 b / app->door_image_offset
         *   door_open_flag          b.java:828 M / app->door_open_flag
         *
         * HoopsTotal is read through the SAME accessor the unlock comparison at
         * :1934 uses, so the printed total and the compared total cannot differ.
         * `b_z` (b.java:461) is deliberately NOT printed: it is not one of the six
         * requested fields, and the six are the whole scope of this step.
         */
        "HoopsScored=%d HoopsTotal=%d TODO_ExitUnlocked=%d "
        /*
         * D-09 -- door_animation_active is dropped from this line because the
         * field is gone; the tracker itself and its other reads are unchanged.
         * door_open_flag (= b.M) is the field that carries the animation's end,
         * so nothing observable is lost.
         */
        "door_image_offset=%d door_open_flag=%d\n",
        (int)app->state,
        (int)app->flow.state,
        bounce_game_timer_is_started(&app->game_timer) ? 1 : 0,
        (unsigned long long)app->game_timer.tick_entry_count,
        (unsigned long long)app->game_timer.tick_dispatch_count,
        (unsigned long long)app->game_timer.player_tick_entry_count,
        (unsigned long long)app->game_timer.player_physics_count,
        (unsigned long long)app->game_timer.dynamic_thorn_update_count,
        (long long)app->legacy_player_tick_route_count,
        (int)app->player.TODO_unkX,
        (int)app->player.TODO_unkY,
        /* appended door-chain reads: */
        app->hoops_scored,
        (int)bounce_level_hoops_total(app->level),
        app->TODO_ExitUnlocked ? 1 : 0,
        app->door_image_offset,
        app->door_open_flag ? 1 : 0
    );
    (void)fflush(stdout);
    return 0;
}

/*
 * Thin render hand-off for the new canonical timer path.
 *
 * Source order (e.java:310-312): after aq.b() and the LoadSpriteSheet hand-off,
 * the original calls q() and then repaint(). The native equivalents already
 * exist and are reused unchanged:
 *
 *   app_update_camera_horizontal()  e.java:310 LoadSpriteSheet hand-off
 *   render_app_state()              e.java:311 q(), via render_gameplay_scene
 *
 * The architectural split is preserved exactly as the production frame loop
 * already has it (vertical_slice.c:8864-8874): GAME UPDATE, then RENDER, then
 * PRESENT. This driver performs only the update and the render. It deliberately
 * does NOT call bounce_presentation_present(), which is X11 work that stays on
 * the main thread, and it does not call app_update_game() or
 * app_run_player_ticks(), so no legacy physics is executed here.
 *
 * The surface and renderer stay owned by the caller, exactly as in main(): the
 * timer path produces game state and this existing boundary consumes it.
 */
static int app_timer_callback_render(
    BounceSurface *surface,
    BounceRenderer *renderer,
    BounceApp *app,
    BounceTickDispatchBranch *branch_out
)
{
    if (app == NULL)
        return -1;
    if (app_timer_callback_dispatch(app, branch_out) != 0)
        return -1;
    return render_app_state(surface, renderer, app);
}

/*
 * D-15 -- position-precise check that each control name landed in its own slot.
 *
 * Returns 0 when the composed text has the LEFT name in the "%0U to move the
 * ball left" slot, the FIRE name in the "%1U to move the ball right" slot and
 * the UP name in the "%2U to bounce the ball" slot; 1 otherwise, with the first
 * mismatch described on stderr.
 *
 * WHY THE ENGLISH SENTENCE IS HARD-CODED HERE. verify_ui_shell is already an
 * English-language assertion block: it compares bounce_ui_shell_menu_label(2u)
 * against "HIGH SCORE" and searches the Instructions text for "Guide the ball
 * past many obstacles" and "Watch out for spikes.". It therefore runs with the
 * active language at index 0, and matching that convention keeps this check
 * free of a new accessor. The substituted NAMES are still not hard-coded by
 * position alone: they are passed in, so the same helper works for any triple
 * and the caller states which is which.
 *
 * The anchors are the words that SURROUND each placeholder in lang.xx id 1:
 * "Use key %0U to move the ball left, key %1U to move the ball right and key
 * %2U to bounce the ball." Requiring the name to sit between the surrounding
 * words is what makes this a slot test rather than a presence test.
 */
static int ui_instructions_slot_mismatch(
    const char *composed,
    const char *left_name,
    const char *fire_name,
    const char *up_name
)
{
    static const struct {
        const char *lead;
        const char *name;
        const char *trail;
    } slots[] = {
        { "Use key ",      NULL, " to move the ball left" },
        { "key ",          NULL, " to move the ball right" },
        { "and key ",      NULL, " to bounce the ball" }
    };
    const char *names[3];
    /*
     * The search is SEQUENTIAL and this cursor is why. lang.xx id 1 reads "Use
     * key %0U to move the ball left, key %1U to move the ball right and key %2U
     * to bounce the ball", so the lead "key " occurs three times and the lead
     * "and key " contains it a fourth time as a substring. Searching the whole
     * string from the front would match the FIRST "key " -- the one belonging
     * to slot 0 -- for every slot, and would then report a false mismatch.
     * Advancing the cursor past each verified slot makes each search start
     * where the previous one ended.
     */
    const char *cursor;
    size_t index;

    if (composed == NULL || left_name == NULL
        || fire_name == NULL || up_name == NULL)
        return 1;
    names[0] = left_name;
    names[1] = fire_name;
    names[2] = up_name;
    cursor = composed;

    for (index = 0u; index < sizeof slots / sizeof slots[0]; ++index) {
        const char *lead = strstr(cursor, slots[index].lead);
        const char *after;

        if (lead == NULL) {
            fprintf(stderr,
                    "instructions: lead \"%s\" for slot %zu not found\n",
                    slots[index].lead, index);
            return 1;
        }
        lead += strlen(slots[index].lead);
        if (strncmp(lead, names[index], strlen(names[index])) != 0) {
            fprintf(stderr,
                    "instructions: slot %zu expected \"%s\"\n",
                    index, names[index]);
            return 1;
        }
        after = strstr(lead + strlen(names[index]), slots[index].trail);
        if (after == NULL) {
            fprintf(stderr,
                    "instructions: trail \"%s\" for slot %zu not found\n",
                    slots[index].trail, index);
            return 1;
        }
        cursor = after + strlen(slots[index].trail);
    }
    return 0;
}

/*
 * surface_digest() is defined further down this file with the other surface
 * helpers. verify_ui_shell() needs it to prove that an Item actually painted,
 * which cannot be shown by a return code alone, so the declaration is lifted
 * rather than the definition duplicated.
 */
static unsigned long surface_digest(const BounceSurface *surface);

static int verify_ui_shell(BounceVisualAssets *assets)
{
    BounceAppFlow flow;
    BounceApp app;
    BounceSurface *surface = NULL;
    BounceRenderer *renderer = NULL;
    unsigned int index;

    if (assets == NULL)
        return -1;

    bounce_app_flow_init(&flow);
    if (flow.state != BOUNCE_APP_STATE_SPLASH
        || flow.splash_timer != 0u
        || flow.splash_skip_requested
        || flow.menu.continue_available
        || flow.menu.enabled_item_count != BOUNCE_MENU_ROW_COUNT - 1u
        || strcmp(bounce_ui_shell_menu_label(0u), "CONTINUE") != 0
        || strcmp(bounce_ui_shell_menu_label(1u), "NEW GAME") != 0
        || strcmp(bounce_ui_shell_menu_label(2u), "HIGH SCORE") != 0
        || strcmp(bounce_ui_shell_menu_label(3u), "INSTRUCTIONS") != 0
        || bounce_ui_shell_menu_label(BOUNCE_MENU_ROW_COUNT) != NULL
        || strcmp(
            bounce_ui_shell_action_label(BOUNCE_MENU_ACTION_NEW_GAME),
            "NEW GAME"
        ) != 0
        || bounce_ui_shell_instructions_text() == NULL
        || strstr(
            bounce_ui_shell_instructions_text(),
            "Guide the ball past many obstacles"
        ) == NULL
        || strstr(bounce_ui_shell_instructions_text(), "%0U") == NULL
        || strstr(bounce_ui_shell_instructions_text(), "%1U") == NULL
        || strstr(bounce_ui_shell_instructions_text(), "%2U") == NULL
        || strstr(
            bounce_ui_shell_instructions_text(),
            "Watch out for spikes."
        ) == NULL
        || strstr(
            bounce_ui_shell_instructions_text(),
            "Use deflators"
        ) == NULL
        || strstr(
            bounce_ui_shell_instructions_text(),
            "Collect crystals"
        ) == NULL
        || bounce_app_flow_high_score(&flow) != 0
        /*
         * D-23 -- the High Score form has exactly the two Items
         * BounceGame.java:161-162 puts in it, so there is NO notice. Asserted
         * here as a NULL rather than merely left unchecked, so a future change
         * cannot quietly re-add a third line to a source-backed screen.
         */
        || bounce_ui_shell_high_score_notice() != NULL)
        return -1;

    /*
     * D-15 / J-04 -- the three control placeholders must be SUBSTITUTED in what
     * the Instructions page draws, while the shipped resource keeps them.
     *
     * The assertions just above already establish the second half: the raw text
     * still contains "%0U", "%1U" and "%2U", which is correct and must stay
     * true, because it is the SHIPPED FILE being described. This block covers
     * the first half, which had no assertion at all before the fix -- the page
     * drew the placeholders literally.
     *
     * The mapping is Java's and is positional. BounceGame.java:169-170 builds
     * the argument array as {getKeyName(getKeyCode(2)),
     * getKeyName(getKeyCode(5)), getKeyName(getKeyCode(1))} and
     * Translation.java:73-79 replaces "%0U", "%1U" and "%2U" with those three
     * entries in order, so:
     *
     *     %0U = LEFT   (e.java:399-401 -> w|=1 -> f.java:808-809 leftward)
     *     %1U = FIRE   (e.java:403-404 -> w|=2 -> f.java:806-807 rightward)
     *     %2U = UP     (e.java:393-394 -> w|=8 -> f.java:821-827 the jump)
     *
     * Each is asserted by its POSITION IN THE SENTENCE, not merely by
     * presence, because a page that put the same name in all three slots would
     * otherwise pass. The English sentence from lang.xx reads "Use key %0U to
     * move the ball left, key %1U to move the ball right and key %2U to bounce
     * the ball", so the surrounding words are what pin the slots down.
     *
     * The names themselves are the NATIVE bindings' labels. Which physical key
     * the original device associated with each game action is UNKNOWN and is
     * not asserted here or guessed: Canvas.getGameAction delegates to a
     * platform KeyMap whose JNI library is absent (game.h:426-432). What is
     * asserted is that the three placeholders are gone and that the three
     * direction labels occupy the three slots in order.
     */
    {
        char composed[1024];

        if (bounce_ui_shell_instructions_composed(
                composed, sizeof composed) != 0
            || strstr(composed, "%0U") != NULL
            || strstr(composed, "%1U") != NULL
            || strstr(composed, "%2U") != NULL
            || strstr(composed, "%") != NULL) {
            fprintf(stderr,
                    "instructions: a control placeholder survived"
                    " composition\n");
            return -1;
        }
        if (ui_instructions_slot_mismatch(
                composed,
                bounce_locale_text(bounce_locale_active_language(),
                                   BOUNCE_LOCALE_LEFT),
                bounce_locale_text(bounce_locale_active_language(),
                                   BOUNCE_LOCALE_RIGHT),
                bounce_locale_text(bounce_locale_active_language(),
                                   BOUNCE_LOCALE_UP)) != 0)
            return -1;
    }

    /*
     * D-07 -- Translation.NEW_HIGH_SCORE, id 12, for all five languages.
     *
     * BounceGame.java:188-190 appends it to BOTH terminal forms when `q` is
     * set, so it is a source string and not a native label. Four of the five
     * values are transcribed from the shipped resources -- the same convention
     * verify_level_complete_form() uses for Translation id 10 and the CONTINUE
     * label -- and Indonesian is the native-extension column, which is asserted
     * as such below by cross-checking it against bounce_locale_resource_name()
     * exactly as that function already does.
     *
     * The Thai value carries a U+200B ZERO WIDTH SPACE between its first two
     * words. It is reproduced here because dropping it would change the string,
     * not just its appearance; the constant below is written with an explicit
     * escape so the invisible code point survives review and editing.
     */
    {
        static const struct {
            BounceLanguage language;
            const char *expected;
            int java_backed;
        } notice_rows[] = {
            { BOUNCE_LANGUAGE_EN,    "New high score!", 1 },
            { BOUNCE_LANGUAGE_ID,    "REKOR BARU!",     0 },
            { BOUNCE_LANGUAGE_TH_TH,
              "คะแนน\u200bสูงสุด ใหม่!", 1 },
            { BOUNCE_LANGUAGE_ZH_CN, "新最高分！", 1 },
            { BOUNCE_LANGUAGE_ZH_TW, "刷新紀錄！", 1 }
        };

        for (index = 0u;
             index < sizeof notice_rows / sizeof notice_rows[0];
             ++index) {
            const bool backed =
                bounce_locale_resource_name(notice_rows[index].language)
                    != NULL;

            if (strcmp(
                    bounce_locale_text(notice_rows[index].language,
                                       BOUNCE_LOCALE_NEW_HIGH_SCORE),
                    notice_rows[index].expected
                ) != 0) {
                fprintf(stderr,
                        "NEW_HIGH_SCORE row %u did not match its expected"
                        " value\n", index);
                return -1;
            }
            /* Same cross-check verify_level_complete_form() applies: a row
             * marked java_backed must have a shipped resource behind it, and
             * the one row that does not must not. */
            if (notice_rows[index].java_backed != 0 && !backed)
                return -1;
            if (notice_rows[index].java_backed == 0 && backed)
                return -1;
        }
    }



    for (index = 0u; index < BOUNCE_APP_SPLASH_TIMER_LIMIT + 1u; ++index) {
        if (bounce_app_flow_tick(&flow) != 0
            || flow.state != BOUNCE_APP_STATE_SPLASH)
            return -1;
    }
    if (bounce_app_flow_tick(&flow) != 1
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.selected_index != 0u
        || bounce_app_flow_menu_enabled_item_count(&flow) != 6u
        || bounce_app_flow_menu_item_enabled(&flow, 0u)
        || !bounce_app_flow_menu_item_enabled(&flow, 1u)
        || !bounce_app_flow_menu_item_enabled(&flow, 2u)
        || !bounce_app_flow_menu_item_enabled(&flow, 3u)
        || bounce_app_flow_menu_row_for_selection(&flow, 0u) != 1u)
        return -1;

    /*
     * Bounded menu navigation remains a menu-only operation. With Continue
     * unavailable the six enabled rows are 1..6, so the selection runs 0..5 and
     * clamps at both ends instead of wrapping. The original device List wrap
     * behavior is UNKNOWN (UI audit section 4, "Navigation unknowns"), so
     * wrapping is deliberately not implemented.
     */
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 1u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 2u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 3u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 4u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 5u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 5u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 4u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 3u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 2u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 1u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 0u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 0u)
        return -1;

    /*
     * Row identity: 0..3 keep the source-verified original order, 4 and 5 are the
     * native extensions, and 6 is the source's Command.EXIT made selectable.
     */
    if (strcmp(bounce_ui_shell_menu_label(4u), "SETTINGS") != 0
        || strcmp(bounce_ui_shell_menu_label(5u), "ABOUT") != 0
        || strcmp(bounce_ui_shell_menu_label(6u), "EXIT") != 0
        || bounce_app_flow_menu_item_enabled(&flow, 4u) == false
        || bounce_app_flow_menu_item_enabled(&flow, 5u) == false
        || bounce_app_flow_menu_item_enabled(&flow, 6u) == false
        || bounce_app_flow_menu_row_for_selection(&flow, 3u) != 4u
        || bounce_app_flow_menu_row_for_selection(&flow, 4u) != 5u
        || bounce_app_flow_menu_row_for_selection(&flow, 5u) != 6u
        || bounce_app_flow_menu_row_for_selection(&flow, 6u) != 6u
        || strcmp(
               bounce_ui_shell_action_label(BOUNCE_MENU_ACTION_SETTINGS),
               "SETTINGS") != 0
        || strcmp(
               bounce_ui_shell_action_label(BOUNCE_MENU_ACTION_ABOUT),
               "ABOUT") != 0)
        return -1;

    /* The source-shaped level List is bounded and never initializes gameplay. */
    if (bounce_app_flow_set_available_level_count(&flow, 3u) != 0
        || bounce_app_flow_available_level_count(&flow) != 3u
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_NEW_GAME
        || bounce_app_flow_pending_level_id(&flow) != 0
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_level_selection_selected_index(&flow) != 1u
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_level_selection_selected_index(&flow) != 2u
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_level_selection_selected_index(&flow) != 2u
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_UP
        ) != 0
        || bounce_app_flow_level_selection_select(&flow) != 2
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&flow) != 2
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_set_available_level_count(&flow, 0u) != 0
        || bounce_app_flow_available_level_count(&flow) != 0u)
        return -1;

    /* New Game remains a bounded action when no level List is available. */
    if (bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&flow) != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != -1
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_NONE
        || flow.menu.selected_index != 0u)
        return -1;

    /*
     * D-05 -- the round trip must COME BACK ON THE ROW THE PLAYER LEFT FROM.
     *
     * Java, on SELECT in the main menu (BounceGame.java:220-221):
     *
     *     String str = this.c.getString(this.c.getSelectedIndex());
     *     this.N = this.c.getSelectedIndex();
     *
     * and on the way back (BounceGame.java:126-130), with no session so the
     * :127 branch does not fire:
     *
     *     } else {
     *         this.c.setSelectedIndex(this.N, true);
     *     }
     *
     * So High Score, entered from position 1, returns with position 1 still
     * highlighted. This assertion used to require 0, which encoded the D-05
     * divergence; the source is explicit that N survives, so 1 is the correct
     * expectation and the old value was the wrong one.
     */
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 1u
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_HIGH_SCORE
        || flow.state != BOUNCE_APP_STATE_HIGH_SCORE
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_HIGH_SCORE
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != -1
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.selected_index != 1u)
        return -1;

    /*
     * D-05 -- one move, not two, because the previous round trip now leaves the
     * highlight on 1 instead of resetting it. Position 2 is Instructions with
     * Continue unavailable, exactly as position 2 was before; the assertion is
     * unchanged in meaning and only its starting point moved.
     *
     * Java: N = 2 on SELECT (BounceGame.java:221), restored on return (:129).
     */
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 2u
        || bounce_app_flow_menu_row_for_selection(&flow, 2u) != 3u
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_INSTRUCTIONS
        || flow.state != BOUNCE_APP_STATE_INSTRUCTIONS
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_INSTRUCTIONS
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != -1
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.selected_index != 2u)
        return -1;

    /*
     * D-05 -- THE HIGHLIGHT'S THREE HALVES, asserted together.
     *
     * Java uses one field and one predicate:
     *
     *   BounceGame.java:89   private int N;                       <- the memory
     *   BounceGame.java:221  this.N = this.c.getSelectedIndex();  <- written once
     *   BounceGame.java:116  if (K == 1 || J == 1 || J == 2)      <- the predicate
     *                             this.c.append(this.menuStrings[0], null);
     *   BounceGame.java:126  if (K == 1 || J == 1 || J == 2)
     *                             this.c.setSelectedIndex(0, true);
     *                         else
     *                             this.c.setSelectedIndex(this.N, true);
     *
     * Three behaviours follow. Each is checked here on a FRESH flow so that one
     * cannot mask another:
     *
     *  1. N PERSISTS across a sub-screen round trip. The blocks above already
     *     walk to High Score and to Instructions and require each to come back
     *     highlighted, which is half 1.
     *
     *  2. N IS FORCED TO 0 when a session exists. Checked through
     *     bounce_app_flow_menu_set_continue_available(), which is native's
     *     :116/:126 predicate.
     *
     *  3. N IS CLAMPED, because the source's list length varies with that same
     *     predicate and MIDP leaves setSelectedIndex out of range undefined.
     *     Native bounds it, which is the strictly safer reading of the same
     *     intent and cannot contradict the source: the clamp only bites in the
     *     case the source leaves undefined.
     */
    {
        BounceAppFlow remembered;

        bounce_app_flow_init(&remembered);
        /* Java's default for `private int N;` (BounceGame.java:89). */
        if (remembered.menu.selected_index != 0u)
            return -1;
        /*
         * The splash has to run out before any menu move, because
         * bounce_app_flow_menu_move() refuses every state but MENU. The blocks
         * above get this for free because they reuse the flow they ticked out;
         * a fresh flow needs its own.
         */
        for (index = 0u; index < BOUNCE_APP_SPLASH_TIMER_LIMIT + 1u; ++index) {
            if (bounce_app_flow_tick(&remembered) != 0
                || remembered.state != BOUNCE_APP_STATE_SPLASH)
                return -1;
        }
        if (bounce_app_flow_tick(&remembered) != 1
            || remembered.state != BOUNCE_APP_STATE_MENU
            /* The splash -> menu arrival runs enter_menu(), so this also
             * exercises the "N is kept" half of the rule on a fresh flow. */
            || remembered.menu.selected_index != 0u)
            return -1;

        /* Half 2: a remembered far row is dropped to 0 once Continue appears. */
        if (bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || remembered.menu.selected_index != 5u
            || bounce_app_flow_menu_set_continue_available(
                   &remembered, true) != 0
            || remembered.menu.selected_index != 0u
            || bounce_app_flow_menu_enabled_item_count(&remembered)
                != BOUNCE_MENU_ROW_COUNT
            /* With Continue present the row mapping is the identity again, so
             * position 0 is row 0 -- the Continue row, as in the source. */
            || bounce_app_flow_menu_row_for_selection(&remembered, 0u) != 0u
            /* Availability going away again must NOT resurrect a far N: the
             * source has no such branch, and by then N holds whatever the last
             * ShowMainMenu stored, which is 0. */
            || bounce_app_flow_menu_set_continue_available(
                   &remembered, false) != 0
            || remembered.menu.selected_index != 0u)
            return -1;

        /* Half 3: six enabled rows mean positions 0..5, and the walk clamps. */
        if (bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || remembered.menu.selected_index != 5u
            || bounce_app_flow_menu_move(&remembered, BOUNCE_MENU_DIRECTION_DOWN)
                != 0
            || remembered.menu.selected_index != 5u)
            return -1;

        /*
         * The clamp proper. N is a plain int on a public struct, so a value
         * larger than any menu the game can present must still resolve to a
         * drawable row. This is reachable in Java whenever the player
         * highlighted a row of a LONGER list and then returned to a shorter one:
         * Instructions sits at index 3 while Continue exists, and at index 2
         * without it, so a remembered 3 meets a two-row-shorter list.
         */
        remembered.menu.selected_index = BOUNCE_MENU_ROW_COUNT;
        if (bounce_app_flow_menu_set_continue_available(
                &remembered, false) != 0
            || remembered.menu.selected_index
                != bounce_app_flow_menu_enabled_item_count(&remembered) - 1u
            || bounce_app_flow_menu_row_for_selection(
                   &remembered,
                   remembered.menu.selected_index)
                != BOUNCE_MENU_ROW_COUNT - 1u)
            return -1;

        printf("MENU-HIGHLIGHT memory=BounceGame.N round_trip=restored"
               " session_forces_zero=yes clamped=yes PASS\n");
    }

    /*
     * Continue is structurally disabled and cannot be selected in this shell.
     *
     * The two moves up are the D-05 consequence: the highlight is now where the
     * Instructions round trip left it (position 2), and this block needs
     * position 0 to reach New Game, which is what it asserted before. Java's own
     * sequence here is unchanged in substance -- N is remembered, so the player
     * navigates from where they were.
     */
    if (flow.menu.continue_available
        || bounce_app_flow_menu_enabled_item_count(&flow) != 6u
        || bounce_app_flow_menu_item_enabled(&flow, 0u)
        || bounce_app_flow_menu_row_for_selection(&flow, 0u) != 1u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 0u
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.selected_index != 0u)
        return -1;

    if (bounce_ui_shell_handle_press(
            &flow,
            BOUNCE_UI_INPUT_EXIT
        ) != 0
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_EXIT
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    bounce_app_flow_init(&flow);
    if (bounce_ui_shell_handle_press(
            &flow,
            BOUNCE_UI_INPUT_OTHER
        ) != 0
        || flow.state != BOUNCE_APP_STATE_SPLASH
        || !flow.splash_skip_requested
        || bounce_app_flow_tick(&flow) != 1
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    if (bounce_game_init(&app) != 0)
        return -1;
    app.next_player_tick_ms = INT64_C(4321);
    if (app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || app.state != BOUNCE_GAME_STATE_SPLASH
        || bounce_game_enter_menu(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.state != BOUNCE_GAME_STATE_MENU
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321))
        goto failure;

    surface = bounce_surface_create();
    if (surface == NULL)
        goto failure;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL)
        goto failure;
    app.visuals = assets;
    if (render_app_state(surface, renderer, &app) != 0
        || bounce_surface_width(surface) != BOUNCE_SURFACE_WIDTH
        || bounce_surface_height(surface) != BOUNCE_SURFACE_HEIGHT)
        goto failure;
    if (bounce_app_flow_set_available_level_count(&app.flow, 3u) != 0
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || app.state != BOUNCE_GAME_STATE_LEVEL_SELECTION
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_NEW_GAME
        || app.level != NULL
        || app.runtime != NULL
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || render_app_state(surface, renderer, &app) != 0
        || bounce_app_flow_level_selection_move(
            &app.flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app.state != BOUNCE_GAME_STATE_GAMEPLAY_ENTRY
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&app.flow) != 2
        || bounce_app_flow_entry_level_id(&app.flow) != 2
        || bounce_app_flow_entry_initial_score(&app.flow)
            != BOUNCE_APP_ENTRY_INITIAL_SCORE
        || bounce_app_flow_entry_initial_lives(&app.flow)
            != BOUNCE_APP_ENTRY_INITIAL_LIVES
        || bounce_app_flow_entry_countdown(&app.flow)
            != BOUNCE_APP_ENTRY_COUNTDOWN
        || bounce_app_flow_entry_phase(&app.flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_INIT_METADATA_RECORDED
        || !bounce_app_flow_entry_step_executed(
            &app.flow,
            false,
            false,
            false
        )
        || app.level != NULL
        || app.runtime != NULL
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || render_app_state(surface, renderer, &app) != 0
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_BACK
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.state != BOUNCE_GAME_STATE_MENU
        || bounce_app_flow_set_available_level_count(&app.flow, 0u) != 0
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    if (bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app.state != BOUNCE_GAME_STATE_GAMEPLAY_ENTRY
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&app.flow) != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_entry_level_id(&app.flow)
            != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_entry_initial_score(&app.flow)
            != BOUNCE_APP_ENTRY_INITIAL_SCORE
        || bounce_app_flow_entry_initial_lives(&app.flow)
            != BOUNCE_APP_ENTRY_INITIAL_LIVES
        || bounce_app_flow_entry_countdown(&app.flow)
            != BOUNCE_APP_ENTRY_COUNTDOWN
        || !bounce_app_flow_entry_step_executed(
            &app.flow,
            false,
            false,
            false
        )
        || app.level != NULL
        || app.runtime != NULL
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    if (bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_BACK
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.state != BOUNCE_GAME_STATE_MENU
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    if (bounce_app_flow_menu_move(
            &app.flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_HIGH_SCORE
        || app.state != BOUNCE_GAME_STATE_HIGH_SCORE
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_HIGH_SCORE
        || app.level != NULL
        || app.runtime != NULL
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    if (bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_BACK
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.state != BOUNCE_GAME_STATE_MENU
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    /*
     * D-05 -- ONE move, not two. The High Score round trip above now restores the
     * highlight to position 1 (BounceGame.java:221 wrote N=1 and :129 restores it),
     * where it used to be reset to 0, so a single DOWN reaches position 2, which
     * is Instructions with Continue unavailable. Java navigates from where the
     * player left the menu, which is what this now does.
     */
    if (bounce_app_flow_menu_move(
            &app.flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || app.flow.menu.selected_index != 2u
        || bounce_app_flow_menu_row_for_selection(&app.flow, 2u) != 3u
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_INSTRUCTIONS
        || app.state != BOUNCE_GAME_STATE_INSTRUCTIONS
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_INSTRUCTIONS
        || app.level != NULL
        || app.runtime != NULL
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;
    if (bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_BACK
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.state != BOUNCE_GAME_STATE_MENU
        || render_app_state(surface, renderer, &app) != 0)
        goto failure;

    /*
     * D-07 / D-11 -- THE TWO TERMINAL FORMS RENDER THE ITEMS.
     *
     * ShowGameEnd (BounceGame.java:177-197) puts four Items in its Form: the
     * title (:181), the body (:183 or :186), the optional NEW_HIGH_SCORE notice
     * plus its blank row (:188-190), and the score (:192). The last two were
     * previously reserved-and-empty on both forms. They are now drawn, and this
     * checks that they really are -- by rendering the same screen with and
     * without each Item and requiring the frame to change, which a no-op draw
     * call cannot satisfy.
     *
     * EACH DIGEST IS TAKEN IMMEDIATELY AFTER ITS OWN RENDER. An earlier
     * revision captured the reference first and then rendered, which compared a
     * Game End frame against Game Over frames and made the check meaningless.
     *
     * PLACEMENT NOTE. This block renders into `surface`, so it must come after
     * bounce_surface_create()/bounce_renderer_create() below; it was first
     * written beside the string assertions, which need no surface, and every
     * render there was refused for a NULL surface.
     */
    {
        unsigned long over_digest[2][2];
        unsigned long end_digest[2][2];
        int score_index;
        int flag_index;
        bool failures_here = false;

        /*
         * bounce_ui_shell_render_game_end() refuses any state other than
         * BOUNCE_APP_STATE_GAME_END, exactly as it always has. The `flow` in
         * scope has been navigated around by the checks above and is not in that
         * state, so a dedicated one is used rather than weakening the guard.
         */
        BounceAppFlow end_flow;

        bounce_app_flow_init(&end_flow);
        end_flow.state = BOUNCE_APP_STATE_GAME_END;

        for (flag_index = 0; flag_index < 2; ++flag_index) {
            for (score_index = 0; score_index < 2; ++score_index) {
                const int32_t score_value =
                    score_index == 0 ? 0 : 1234567;
                const bool flag_value = flag_index != 0;

                if (bounce_ui_shell_render_game_over(
                        surface, renderer, score_value,
                        flag_value) != 0) {
                    fprintf(stderr,
                            "terminal forms: game_over render refused"
                            " score=%ld flag=%d\n",
                            (long)score_value, (int)flag_value);
                    failures_here = true;
                    break;
                }
                over_digest[flag_index][score_index] =
                    surface_digest(surface);

                if (bounce_ui_shell_render_game_end(
                        surface, renderer, &end_flow, score_value,
                        flag_value) != 0) {
                    fprintf(stderr,
                            "terminal forms: game_end render refused"
                            " score=%ld flag=%d\n",
                            (long)score_value, (int)flag_value);
                    failures_here = true;
                    break;
                }
                end_digest[flag_index][score_index] =
                    surface_digest(surface);
            }
            if (failures_here)
                break;
        }
        if (failures_here)
            goto failure;

        /*
         * The notice must paint: (flag on) differs from (flag off) at the SAME
         * score. The score must paint: (score 1234567) differs from (score 0) at
         * the SAME flag. Both must paint: the "both" corner differs from each
         * single-item corner. Four comparisons per form, eight in total, and each
         * one varies exactly one input.
         */
        for (flag_index = 0; flag_index < 2 && !failures_here; ++flag_index) {
            if (over_digest[flag_index][0] == over_digest[flag_index][1]) {
                fprintf(stderr,
                        "terminal forms: game over score did not paint"
                        " at flag=%d\n", flag_index);
                failures_here = true;
            }
            if (end_digest[flag_index][0] == end_digest[flag_index][1]) {
                fprintf(stderr,
                        "terminal forms: game end score did not paint"
                        " at flag=%d\n", flag_index);
                failures_here = true;
            }
        }
        for (score_index = 0; score_index < 2 && !failures_here; ++score_index) {
            if (over_digest[0][score_index] == over_digest[1][score_index]) {
                fprintf(stderr,
                        "terminal forms: game over notice did not paint"
                        " at score index=%d\n", score_index);
                failures_here = true;
            }
            if (end_digest[0][score_index] == end_digest[1][score_index]) {
                fprintf(stderr,
                        "terminal forms: game end notice did not paint"
                        " at score index=%d\n", score_index);
                failures_here = true;
            }
        }
        if (!failures_here
            && over_digest[1][1] == over_digest[0][1]) {
            fprintf(stderr, "terminal forms: game over notice/score"
                    " are not independent\n");
            failures_here = true;
        }
        if (!failures_here
            && end_digest[1][1] == end_digest[0][1]) {
            fprintf(stderr, "terminal forms: game end notice/score"
                    " are not independent\n");
            failures_here = true;
        }
        if (failures_here)
            goto failure;

        /*
         * D-07 -- the `q` LATCH ITSELF, exercised through the public flow API
         * rather than through the renderer's parameter, so the flag the
         * renderer is handed is proved to be BounceGame.q and not a
         * reconstruction of it.
         *
         * BounceGame.java:422-426 is the whole rule:
         *
         *     if (this.v.score > this.HighScore) {
         *         this.HighScore = this.v.score;
         *         this.q = true;
         *         WriteToStore(2);
         *     }
         *
         * so a score that does not beat the record must raise neither the
         * maximum nor `q`, and a fresh flow starts with `q` false because
         * BounceGame.java:19 initialises it and no record carries it.
         */
        {
            BounceAppFlow fresh_flow;

            bounce_app_flow_init(&fresh_flow);
            if (bounce_app_flow_new_high_score(&fresh_flow))
                goto failure;
            if (bounce_app_flow_note_score(&fresh_flow, 500) != 1)
                goto failure;
            if (!bounce_app_flow_new_high_score(&fresh_flow))
                goto failure;
            if (bounce_app_flow_note_score(&fresh_flow, 500) != 0)
                goto failure;
            if (!bounce_app_flow_new_high_score(&fresh_flow))
                goto failure;
            if (bounce_app_flow_note_score(&fresh_flow, 900) != 1)
                goto failure;
            if (!bounce_app_flow_new_high_score(&fresh_flow))
                goto failure;
        }

        printf("TERMINAL-FORMS notice=Translation.NEW_HIGH_SCORE"
               " score=String.valueOf(E) both_forms=verified"
               " item_digests=distinct PASS\n");
    }

    /*
     * D-24 -- THE CJK AND THAI COLUMNS ARE THE SHIPPED RESOURCES, PROVEN.
     *
     * The values below are the fourteen shipped translation ids as they stand in
     * src/main/resources/lang.zh-CN, lang.zh-TW and lang.th-TH, decoded from those
     * files' fourteen-u16 offset table. They are asserted here as literals because
     * the C build cannot read the resource files, and this is the check that
     * makes that acceptable: if a row drifts away from its resource, this fails.
     *
     * Before D-24 the Chinese and Thai columns were TEMPORARY TEST STRINGS, and
     * verify_native_extension_ui's own comment said the Chinese and Thai text was
     * not decoded from the resources. That is now false, and the four rows below
     * are the ones that were outright wrong words rather than merely untested:
     *
     *   zh-TW Exit   was "離開" (to leave)   and is "退出" (to exit)
     *   zh-CN Instr. was "玩法说明"           and is "游戏规则说明"
     *   zh-TW Instr. was "玩法說明"           and is "遊戲規則說明"
     *   th-TH Instr. was "วิธีเล่น"           and is "วิธีการเล่น"
     *   th-TH High   was "คะแนนสูง"           and is "คะแนนสูงสุด"
     *   th-TH Back   was "กลับ"               and is "ย้อนกลับ"
     *   th-TH New    was "เกมใหม่"             and is "เกมส์ใหม่"
     *   th-TH Level  was "ด่าน"               and is "ระดับ"
     *   zh-CN/TW Level was "关卡" / "關卡"     and are "级别" / "等級"
     *
     * The two CONGRATS rows gained the resource's fullwidth "！" and the three
     * Languages' other rows were already correct.
     *
     * WHAT IS *NOT* ASSERTED AS EQUAL, DELIBERATELY:
     *
     *   the fourteen ENGLISH rows stay upper case. ui_shell.c's
     *   placeholder_text_index() folds a-z to A-Z, so "Back" and "BACK" produce
     *   identical pixels and the case is provably invisible. Every screen
     *   assertion in this file compares the upper-case form, so changing it would
     *   be churn with no rendering difference.
     *
     *   the English CONGRATS row keeps no "!". The 5x7 font has no glyph for it,
     *   so the verbatim character would render as the unknown-glyph box.
     *
     *   LEVEL drops the resource's "%U" in all four languages, because native
     *   draws the label and the number as two calls -- placeholder_text_index()
     *   has no digit glyph, which is why the level List and the High Score screen
     *   already do this. The shipped WORD is what is asserted.
     */
    {
        static const struct {
            BounceLanguage language;
            BounceLocaleKey key;
            const char *expected;
        } resource_rows[] = {
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_BACK, "返回" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_GAME_END_CONGRATS, "祝贺你！" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_EXIT, "退出" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_HIGH_SCORE, "最高分" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_INSTRUCTIONS, "游戏规则说明" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_LEVEL, "级别" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_LEVEL_COMPLETED,
              "级别%U\n已完成" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_NEW_GAME, "新游戏" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_NEW_HIGH_SCORE, "新最高分！" },
            { BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_GAME_END_OK, "确认" },

            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_BACK, "返回" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_GAME_END_CONGRATS, "恭喜！" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_EXIT, "退出" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_HIGH_SCORE, "最高分" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_INSTRUCTIONS, "遊戲規則說明" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_LEVEL, "等級" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_LEVEL_COMPLETED,
              "等級%U\n已完成！" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_NEW_GAME, "新遊戲" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_NEW_HIGH_SCORE, "刷新紀錄！" },
            { BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_GAME_END_OK, "確認" },

            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_BACK,
              "ย้อนกลับ" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_GAME_END_CONGRATS,
              "ยินดีด้วย!" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_EXIT, "ออก" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_HIGH_SCORE,
              "คะแนนสูงสุด" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_INSTRUCTIONS,
              "วิธีการเล่น" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_LEVEL,
              "ระดับ" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_LEVEL_COMPLETED,
              "ผ่านระดับ %U!" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_NEW_GAME,
              "เกมส์ใหม่" },
            /* U+200B ZERO WIDTH SPACE inside the first word, exactly as shipped. */
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_NEW_HIGH_SCORE,
              "คะแนน\u200bสูงสุด ใหม่!" },
            { BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_GAME_END_OK,
              "ตกลง" }
        };
        size_t row;

        for (row = 0u; row < sizeof resource_rows / sizeof resource_rows[0];
             ++row) {
            const char *got = bounce_locale_text(
                resource_rows[row].language,
                resource_rows[row].key);
            if (got == NULL
                || strcmp(got, resource_rows[row].expected) != 0) {
                fprintf(stderr,
                        "locale row %u (language %d, key %d) is not the"
                        " shipped resource value\n",
                        (unsigned int)row,
                        (int)resource_rows[row].language,
                        (int)resource_rows[row].key);
                return -1;
            }
        }

        /*
         * AND THE INSTRUCTIONS BODIES, which are the largest strings in the
         * table and the ones most likely to be re-authored by accident. Only the
         * ENGLISH body is spelled out here -- it is the shortest of the four and
         * the one a reader can check -- plus the three distinctive OPENINGS of
         * the others, which is what catches a reverted translation without
         * embedding 800 characters of CJK and Thai in a verifier.
         */
        {
            static const struct {
                BounceLanguage language;
                const char *opening;
            } openings[] = {
                { BOUNCE_LANGUAGE_ZH_CN,
                  "使球越过重重障碍以通过所有环圈并打开大门进入下一级别。" },
                { BOUNCE_LANGUAGE_ZH_TW,
                  "設法讓球通過許多障礙物，穿越所有圓箍，最終打開通往下一個關卡的門。" },
                { BOUNCE_LANGUAGE_TH_TH,
                  "เลื่อนลูกบอลผ่านสิ่งกีดขวาง\nให้ลอดห่วงทั้งหมด" }
            };
            const char *body;

            for (row = 0u; row < sizeof openings / sizeof openings[0]; ++row) {
                body = bounce_locale_text(openings[row].language,
                                          BOUNCE_LOCALE_INSTRUCTIONS_BODY);
                if (body == NULL
                    || strncmp(body, openings[row].opening,
                               strlen(openings[row].opening)) != 0) {
                    fprintf(stderr,
                            "instructions body for language %d does not open"
                            " with the shipped resource text\n",
                            (int)openings[row].language);
                    return -1;
                }
                /* The three placeholders must survive: ui_compose_instructions()
                 * substitutes them at draw time and never in the locale layer. */
                if (strstr(body, "%0U") == NULL
                    || strstr(body, "%1U") == NULL
                    || strstr(body, "%2U") == NULL)
                    return -1;
            }
            printf("LOCALE-RESOURCE rows=%u languages=zh-CN,zh-TW,th-TH"
                   " placeholders=intact prefix_is_leading_span=yes"
                   " thai_glyphs=absent_by_design PASS\n",
                   (unsigned int)(sizeof resource_rows
                                  / sizeof resource_rows[0]));

            /* The bounded prefix the page draws must be a LEADING SPAN of the
             * body, not an independently authored sentence. That is the property
             * the resource replacement had to preserve and the one a future edit
             * is most likely to break. */
            for (row = 0u; row < sizeof openings / sizeof openings[0]; ++row) {
                const char *pre = bounce_locale_text(
                    openings[row].language,
                    BOUNCE_LOCALE_INSTRUCTIONS_PREFIX);
                body = bounce_locale_text(openings[row].language,
                                          BOUNCE_LOCALE_INSTRUCTIONS_BODY);
                if (pre == NULL || body == NULL
                    || strncmp(body, pre, strlen(pre)) != 0) {
                    fprintf(stderr,
                            "instructions prefix for language %d is not a"
                            " leading span of the body\n",
                            (int)openings[row].language);
                    return -1;
                }
            }
        }
    }

    /*
     * D-06 -- THE LEVEL LIST TITLE IS Translation.NEW_GAME.
     *
     * BounceGame.java:142:
     *
     *     this.currentList = new List(
     *         Translation.sprintf_translated(Translation.NEW_GAME),
     *         List.IMPLICIT, levelStrings, null);
     *
     * A MIDP List takes its title as the first constructor argument, so this is
     * a recovered string and not a screen-name of the build's own choosing. It
     * is checked HERE, in the verifier that already asserts every other screen's
     * label, and by IDENTITY rather than by text: the level-list title and the
     * main menu's second row must resolve to the SAME locale row, because in the
     * source they are the same translation id (11). Comparing the English
     * strings would also pass if two different rows happened to read alike.
     *
     * BOUNCE_LOCALE_LEVEL_SELECT is deliberately still asserted to exist and to
     * differ, so a later change cannot quietly restore it as the title by
     * editing only the renderer.
     */
    {
        BounceLanguage original_language =
            bounce_locale_active_language();
        bool distinct;

        bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
        distinct = strcmp(
            bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_NEW_GAME),
            bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_LEVEL_SELECT)
        ) != 0;
        /*
         * THE ASSERTION THAT ACTUALLY BINDS THE RENDERER. An earlier revision
         * only checked that NEW_GAME and LEVEL_SELECT were different rows, which
         * is true no matter which one the renderer passes: a negative control
         * that reverted the renderer to LEVEL_SELECT still went green. This
         * compares the string the renderer uses against the main menu's second
         * row, and because the renderer obtains that string ONLY through
         * bounce_ui_shell_level_selection_title(), the same negative control now
         * fails.
         */
        if (strcmp(
                bounce_ui_shell_menu_label(1u),
                bounce_ui_shell_level_selection_title()
            ) != 0) {
            bounce_locale_set_active_language(original_language);
            return -1;
        }
        bounce_locale_set_active_language(original_language);
        if (!distinct) {
            fprintf(stderr,
                    "level select title: NEW_GAME and LEVEL_SELECT are"
                    " the same row, so the title cannot be asserted by"
                    " identity\n");
            return -1;
        }
        printf("LEVEL-SELECT-TITLE row=Translation.NEW_GAME(id 11)"
               " shared_with_menu_row=yes distinct_from_LEVEL_SELECT=yes"
               " PASS\n");
    }

    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_game_shutdown(&app);
    return 0;

failure:
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_game_shutdown(&app);
    return -1;
}

static int verify_flow_transitions(void)
{
    BounceAppFlow flow;

    bounce_app_flow_init(&flow);
    if (flow.state != BOUNCE_APP_STATE_SPLASH
        || flow.level_id != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_PAUSE) != -1
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_SPLASH_DONE) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_START) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_PAUSE) != 0
        || flow.state != BOUNCE_APP_STATE_PAUSE
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_RESUME) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_GAME_OVER) != 0
        || flow.state != BOUNCE_APP_STATE_GAME_OVER
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_START) != 0
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_LEVEL_COMPLETE) != 0
        || flow.state != BOUNCE_APP_STATE_LEVEL_COMPLETE
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_NEXT_LEVEL) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || flow.level_id != BOUNCE_APP_FIRST_LEVEL_ID + 1
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0)
        return -1;

    bounce_app_flow_init(&flow);
    if (bounce_app_flow_apply(
            &flow,
            BOUNCE_APP_EVENT_SPLASH_DONE
        ) != 0
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_INSTRUCTIONS
        || flow.state != BOUNCE_APP_STATE_INSTRUCTIONS
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    bounce_app_flow_init(&flow);
    if (bounce_app_flow_apply(
            &flow,
            BOUNCE_APP_EVENT_SPLASH_DONE
        ) != 0
        || bounce_app_flow_menu_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_HIGH_SCORE
        || flow.state != BOUNCE_APP_STATE_HIGH_SCORE
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    bounce_app_flow_init(&flow);
    if (bounce_app_flow_apply(
            &flow,
            BOUNCE_APP_EVENT_SPLASH_DONE
        ) != 0
        || bounce_app_flow_set_available_level_count(&flow, 3u) != 0
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_level_selection_select(&flow) != 2
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&flow) != 2
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;
    return 0;
}

/*
 * UI 6 audit boundary: START_LEVEL(N) -> gameplay-entry record -> STOP.
 * No level, player, runtime tile, timer, tick, physics, collision, camera, or
 * persistence action is reachable from this state.
 */
static int verify_gameplay_entry_boundary(void){
    BounceAppFlow flow;
    BounceSurface *surface;
    BounceRenderer *renderer;
    int native_period = BOUNCE_APP_TICK_MS;

    /* BounceTimer.java:17 schedules Timer.schedule(this, 0L, 40L). */
    if (native_period != 40)
        return -1;

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }

    bounce_app_flow_init(&flow);

    /*
     * STEP 38-RESET -- the count is no longer the source's 0.
     *
     * WHAT CHANGED AND WHY IT IS NOT A REGRESSION. BounceGame.java:276-279 leaves
     * MaxLevels at its Java default of 0 on a fresh install, and with 0 the New Game
     * gate at :241 (`MaxLevels > 1`) is false, so `a(true, 1)` runs and level 1 starts
     * directly -- Level Select is unreachable and a second level is unreachable
     * forever. That was reproduced faithfully and is now deliberately 2, so that
     * levels 1 and 2 are both selectable on a new install. See
     * BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT in app_flow.h.
     *
     * THE COUNT OF 0 IS STILL COVERED, as an explicitly SET value rather than as the
     * default. That distinction is the point: the Java branch it exercises -- "the
     * gate is false, so stage the first level directly" -- is a real behaviour of
     * the flow and is worth asserting, but it is no longer reachable by accident on a
     * new install, and pretending otherwise would let the two drift apart silently.
     */
    if (bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_SPLASH_DONE) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_available_level_count(&flow)
            != (unsigned int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT) {
        return -1;
    }
    /*
     * THE SHIPPED DEFAULT ROUTES NEW GAME THROUGH LEVEL SELECT, and that is a
     * behaviour change with a visible consequence: on a new install the player now
     * chooses between levels 1 and 2 instead of being dropped straight into level 1.
     * It is asserted on its own, before the count of 0 is set below, because the two
     * cases are mutually exclusive -- the first SELECT lands on LEVEL_SELECTION and
     * only then can the count be changed back to 0 for the Java-shaped case.
     */
    if (bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || bounce_app_flow_available_level_count(&flow)
            != (unsigned int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT
        || bounce_app_flow_level_selection_selected_index(&flow) != 0u) {
        return -1;
    }
    bounce_app_flow_menu_clear_action(&flow);
    /*
     * Back to the menu before touching the count. bounce_app_flow_set_available_
     * level_count() is guarded on MENU, so setting it from LEVEL_SELECTION would be
     * refused and the Java-shaped case below would silently be testing the default
     * count a second time instead of 0.
     */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_set_available_level_count(&flow, 0u) != 0
        || bounce_app_flow_available_level_count(&flow) != 0u
        || bounce_app_flow_begin_gameplay_entry(&flow) != -1
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_NONE
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&flow) != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_START_LEVEL_RECORDED
        || bounce_app_flow_begin_gameplay_entry(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || bounce_app_flow_entry_level_id(&flow) != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_entry_initial_score(&flow)
            != BOUNCE_APP_ENTRY_INITIAL_SCORE
        || bounce_app_flow_entry_initial_lives(&flow)
            != BOUNCE_APP_ENTRY_INITIAL_LIVES
        || bounce_app_flow_entry_countdown(&flow)
            != BOUNCE_APP_ENTRY_COUNTDOWN
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_INIT_METADATA_RECORDED
        || !bounce_app_flow_entry_step_executed(&flow, false, false, false)
        || strcmp(
            bounce_app_flow_entry_phase_name(
                bounce_app_flow_entry_phase(&flow)
            ),
            "INIT_METADATA_RECORDED"
        ) != 0
        || flow.level_id != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_begin_gameplay_entry(&flow) != -1
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != -1
        || bounce_app_flow_level_selection_select(&flow) != -1
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != -1
        || bounce_app_flow_set_available_level_count(&flow, 5u) != -1
        || bounce_app_flow_tick(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || bounce_ui_shell_render_gameplay_entry(
            surface,
            renderer,
            &flow
        ) != 0)
        goto failure;

    /* The renderer refuses a record that claims a started source step. */
    flow.gameplay_entry.timer_started = true;
    if (bounce_ui_shell_render_gameplay_entry(surface, renderer, &flow) != -1
        || bounce_app_flow_entry_step_executed(&flow, false, false, false)) {
        flow.gameplay_entry.timer_started = false;
        goto failure;
    }
    flow.gameplay_entry.timer_started = false;

    /* Only Back/Exit are honored; every other edge is inert. */
    if (bounce_ui_shell_handle_press(
            &flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_UP) != 0
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_DOWN) != 0
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_OTHER) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || bounce_app_flow_entry_level_id(&flow) != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_EXIT) != 0
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_EXIT
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY)
        goto failure;

    /* Test C: the native development Back escape clears the entry record. */
    if (bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_BACK) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_NONE
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_NONE
        || bounce_app_flow_entry_level_id(&flow) != 0
        || bounce_app_flow_entry_initial_lives(&flow) != 0
        || bounce_app_flow_entry_countdown(&flow) != 0
        || bounce_app_flow_pending_level_id(&flow) != 0
        || !bounce_app_flow_entry_step_executed(&flow, false, false, false)
        || bounce_ui_shell_render_gameplay_entry(surface, renderer, &flow)
            != -1)
        goto failure;

    /* Test B: injected count 3 selects level 2 through the same boundary. */
    if (bounce_app_flow_set_available_level_count(&flow, 3u) != 0
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_DOWN
        ) != 0
        || bounce_app_flow_level_selection_select(&flow) != 2
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || bounce_app_flow_pending_level_id(&flow) != 2
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_START_LEVEL_RECORDED
        || bounce_app_flow_begin_gameplay_entry(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || bounce_app_flow_entry_level_id(&flow) != 2
        || bounce_app_flow_entry_initial_score(&flow)
            != BOUNCE_APP_ENTRY_INITIAL_SCORE
        || bounce_app_flow_entry_initial_lives(&flow)
            != BOUNCE_APP_ENTRY_INITIAL_LIVES
        || bounce_app_flow_entry_countdown(&flow)
            != BOUNCE_APP_ENTRY_COUNTDOWN
        || !bounce_app_flow_entry_step_executed(&flow, false, false, false)
        || bounce_app_flow_tick(&flow) != 0
        || bounce_ui_shell_render_gameplay_entry(
            surface,
            renderer,
            &flow
        ) != 0
        || bounce_app_flow_apply(&flow, BOUNCE_APP_EVENT_MENU) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_entry_phase(&flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_NONE
        || bounce_app_flow_entry_level_id(&flow) != 0)
        goto failure;

    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return 0;

failure:
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return -1;
}

/* Level header facts verified from the original resource files. */
typedef struct LevelEntryExpectation {
    int level_id;
    uint32_t width;
    uint32_t height;
    uint8_t initial_x;
    uint8_t initial_y;
    uint8_t is_big_ball;
    uint8_t exit_x;
    uint8_t exit_y;
    uint8_t hoops_total;
    uint32_t thorn_count;
} LevelEntryExpectation;

static int verify_level_entry_facts(
    const BounceLevel *level,
    const LevelEntryExpectation *expect
)
{
    const uint8_t *payload = NULL;
    size_t payload_length = 0u;
    uint8_t first_tile = 0u;
    uint32_t y;
    uint32_t x;

    if (level == NULL || expect == NULL)
        return -1;
    if (bounce_level_width(level) != expect->width
        || bounce_level_height(level) != expect->height
        || bounce_level_initial_x(level) != expect->initial_x
        || bounce_level_initial_y(level) != expect->initial_y
        || bounce_level_is_big_ball(level) != expect->is_big_ball
        || bounce_level_exit_x(level) != expect->exit_x
        || bounce_level_exit_y(level) != expect->exit_y
        || bounce_level_hoops_total(level) != expect->hoops_total
        || bounce_level_thorn_count(level) != expect->thorn_count
        || bounce_level_tile_count(level)
            != (size_t)expect->width * (size_t)expect->height)
        return -1;
    if (bounce_level_get_thorn_payload(
            level,
            &payload,
            &payload_length
        ) != 0)
        return -1;
    if (expect->thorn_count == 0u) {
        if (payload != NULL || payload_length != 0u)
            return -1;
    } else if (payload == NULL
        || payload_length != (size_t)expect->thorn_count * 8u) {
        return -1;
    }
    /* Every stored tile byte must remain readable at its own coordinates. */
    for (y = 0u; y < expect->height; ++y) {
        for (x = 0u; x < expect->width; ++x) {
            if (bounce_level_get_tile(level, (int)x, (int)y, &first_tile) != 0)
                return -1;
        }
    }
    return 0;
}

/* Drive one New Game route to the level-loaded boundary and assert isolation. */
static int verify_level_entry_route(
    int list_index,
    const LevelEntryExpectation *expect
)
{
    BounceApp app;
    BounceSurface *surface;
    BounceRenderer *renderer;
    int32_t camera_l;
    int32_t camera_k;
    int32_t camera_v;
    int index;
    int result = -1;

    if (expect == NULL
        || expect->level_id < BOUNCE_APP_FIRST_LEVEL_ID
        || expect->level_id > BOUNCE_APP_LAST_LEVEL_ID)
        return -1;
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        return -1;
    surface = bounce_surface_create();
    renderer = bounce_renderer_create(surface);
    if (surface == NULL || renderer == NULL)
        goto cleanup;
    app.next_player_tick_ms = INT64_C(4321);
    camera_l = 111;
    camera_k = 222;
    camera_v = 333;
    app.l = camera_l;
    app.k = camera_k;
    app.v = camera_v;

    if (list_index < 0) {
        /*
         * Direct route: START_LEVEL(1) with no Level Select hop.
         *
         * STEP 38-RESET -- the count is SET to 0 here instead of being inherited from
         * the launch default, which is now 2. `MaxLevels > 1` is then false, so the
         * first SELECT on the main menu stages level 1 directly.
         *
         * It has to be explicit. This branch presses SELECT on the MAIN MENU, so it
         * used to be reading whatever bounce_app_flow_init() happened to write, and
         * the moment the shipped default stopped being 0 the branch silently began
         * exercising the Level Select path instead -- and then failed three lines
         * later on a state it no longer expected, which is a confusing way to learn
         * that a default moved. Naming the value makes this fixture's precondition
         * legible and independent of the default, which is what a fixture is for.
         */
        if (bounce_app_flow_set_available_level_count(&app.flow, 0u) != 0
            || bounce_app_flow_available_level_count(&app.flow) != 0u
            || bounce_ui_shell_handle_press(
                &app.flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0)
            goto cleanup;
    } else {
        if (bounce_app_flow_set_available_level_count(
                &app.flow,
                (unsigned int)expect->level_id
            ) != 0
            || bounce_ui_shell_handle_press(
                &app.flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0
            || app.flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
            goto cleanup;
        for (index = 0; index < list_index; ++index) {
            if (bounce_app_flow_level_selection_move(
                    &app.flow,
                    BOUNCE_MENU_DIRECTION_DOWN
                ) != 0)
                goto cleanup;
        }
        if (bounce_ui_shell_handle_press(
                &app.flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0)
            goto cleanup;
    }

    /* The UI 6 gameplay-entry boundary still owns nothing. */
    if (bounce_game_sync_ui_state(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app.state != BOUNCE_GAME_STATE_GAMEPLAY_ENTRY
        || bounce_app_flow_entry_level_id(&app.flow) != expect->level_id
        || bounce_app_flow_pending_level_id(&app.flow) != expect->level_id
        || bounce_app_flow_entry_phase(&app.flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_INIT_METADATA_RECORDED
        || !bounce_app_flow_entry_step_executed(&app.flow, false, false, false)
        || app.level != NULL
        || app.runtime != NULL
        || app.player.initialized
        || app.spawn.initialized
        || app.l != camera_l
        || app.k != camera_k
        || app.v != camera_v
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321))
        goto cleanup;

    /* The one new step: load the selected level and stop. */
    if (app_advance_gameplay_entry_to_level_loaded(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
        || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED
        || bounce_app_flow_entry_phase(&app.flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_LEVEL_LOADED
        || !bounce_app_flow_entry_step_executed(&app.flow, true, false, false)
        || bounce_app_flow_record_level_loaded(&app.flow) != -1
        || app.level == NULL
        || app.level_path == NULL
        || app.level_id != expect->level_id
        || verify_level_entry_facts(app.level, expect) != 0
        || app.runtime != NULL
        || app.player.initialized
        || app.spawn.initialized
        || app.l != camera_l
        || app.k != camera_k
        || app.v != camera_v
        || app.lives != 0
        || app.hoops_scored != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        /* Activation and gameplay entry stay impossible without a runtime
         * tile copy and an initialized player. */
        || bounce_game_activate_loaded_level(&app, 3) != -1
        /* No screen exists for the seam and no gameplay may be rendered. */
        || render_app_state(surface, renderer, &app) != -1
        || bounce_game_start_level(
            &app,
            BOUNCE_LEVEL001_PATH,
            1,
            3
        ) == 0
        || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED
        || app.next_player_tick_ms != INT64_C(4321))
        goto cleanup;

    result = 0;

cleanup:
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_game_shutdown(&app);
    return result;
}

/* Drive New Game -> GAMEPLAY_ENTRY -> LEVEL_LOADED with isolation checks. */
static int drive_app_to_level_loaded(
    BounceApp *app,
    int list_index,
    int level_id
)
{
    int index;

    if (app == NULL
        || level_id < BOUNCE_APP_FIRST_LEVEL_ID
        || level_id > BOUNCE_APP_LAST_LEVEL_ID)
        return -1;
    if (bounce_game_init(app) != 0 || bounce_game_enter_menu(app) != 0)
        return -1;
    app->next_player_tick_ms = INT64_C(4321);
    app->l = 111;
    app->k = 222;
    app->v = 333;

    if (list_index < 0) {
        /*
         * STEP 38-RESET -- the count is SET to 0 here rather than inherited.
         *
         * This branch means "press SELECT on the main menu and stage level 1 with no
         * Level Select hop", which is BounceGame.java:241's `MaxLevels > 1` gate
         * evaluating false. It used to get that condition by reading whatever
         * bounce_app_flow_init() wrote, and the shipped default is now 2, so without
         * this the branch would silently stop testing the thing it is named for and
         * start testing the Level Select route instead. Naming the value keeps every
         * caller of this helper on the route it asked for.
         */
        if (bounce_app_flow_set_available_level_count(&app->flow, 0u) != 0
            || bounce_app_flow_available_level_count(&app->flow) != 0u
            || bounce_ui_shell_handle_press(
                &app->flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0)
            return -1;
    } else {
        if (bounce_app_flow_set_available_level_count(
                &app->flow,
                (unsigned int)level_id
            ) != 0
            || bounce_ui_shell_handle_press(
                &app->flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0
            || app->flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
            return -1;
        for (index = 0; index < list_index; ++index) {
            if (bounce_app_flow_level_selection_move(
                    &app->flow,
                    BOUNCE_MENU_DIRECTION_DOWN
                ) != 0)
                return -1;
        }
        if (bounce_ui_shell_handle_press(
                &app->flow,
                BOUNCE_UI_INPUT_SELECT
            ) != 0)
            return -1;
    }

    /* The UI 6 gameplay-entry boundary still owns nothing. */
    if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app->level != NULL
        || app->runtime != NULL
        || app->player.initialized
        || bounce_game_sync_ui_state(app) != 0
        || app->state != BOUNCE_GAME_STATE_GAMEPLAY_ENTRY
        || app->l != 111
        || app->k != 222
        || app->v != 333
        || app->next_player_tick_ms != INT64_C(4321))
        return -1;

    if (app_advance_gameplay_entry_to_level_loaded(app) != 0
        || app->flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
        || app->state != BOUNCE_GAME_STATE_LEVEL_LOADED
        || app->level == NULL
        || app->runtime != NULL
        || app->player.initialized
        || app->l != 111
        || app->k != 222
        || app->v != 333
        || app->next_player_tick_ms != INT64_C(4321))
        return -1;
    return 0;
}

/* Player facts derived from the verified level headers, not hard-coded. */
typedef struct PlayerEntryExpectation {
    int level_id;
    uint8_t initial_x;
    uint8_t initial_y;
    uint8_t is_big_ball;
    /* The f constructor input: initial_X * 12 + 6 / initial_Y * 12 + 6. */
    int32_t constructor_x;
    int32_t constructor_y;
    /*
     * The player position after the whole constructor, which for a big-ball
     * level includes the f.UseBigBall() probe at f.java:130.
     */
    int32_t world_x;
    int32_t world_y;
    int32_t ball_size;
    int32_t half_size;
    BouncePlayerBallMode mode;
} PlayerEntryExpectation;

/*
 * Level-load integration verification: GAMEPLAY_ENTRY -> LEVEL_LOADED -> STOP,
 * including invalid-id rejection and the ownership guard.
 */
/*
 * Read-only digest of every pristine BounceLevel tile byte. Used only to prove
 * the big-ball constructor probe leaves the level it reads byte-identical; it
 * calls the public accessor and holds no reference to internal storage.
 */
static int level_pristine_tile_digest(
    const BounceLevel *level,
    unsigned long *digest_out
)
{
    unsigned long digest = 1469598103934665603UL;
    uint32_t width;
    uint32_t height;
    uint32_t x;
    uint32_t y;

    if (level == NULL || digest_out == NULL)
        return -1;

    width = bounce_level_width(level);
    height = bounce_level_height(level);
    for (y = 0; y < height; ++y) {
        for (x = 0; x < width; ++x) {
            uint8_t value;

            if (bounce_level_get_tile(level, (int)x, (int)y, &value) != 0)
                return -1;
            digest ^= (unsigned long)value;
            digest *= 1099511628211UL;
        }
    }
    *digest_out = digest;
    return 0;
}

static int verify_player_initialization_route(
    int list_index,
    const PlayerEntryExpectation *expect
)
{
    BounceApp app;
    BouncePlayer saved_player;
    BouncePlayerSpawn saved_spawn;
    unsigned long digest_before = 0UL;
    unsigned long digest_after = 0UL;
    int result = -1;

    if (expect == NULL)
        return -1;
    if (drive_app_to_level_loaded(&app, list_index, expect->level_id) != 0)
        return -1;

    /* The source inputs must come from the loaded level itself. */
    if (bounce_level_initial_x(app.level) != expect->initial_x
        || bounce_level_initial_y(app.level) != expect->initial_y
        || bounce_level_is_big_ball(app.level) != expect->is_big_ball)
        goto cleanup;

    if (level_pristine_tile_digest(app.level, &digest_before) != 0)
        goto cleanup;

    if (app_advance_level_loaded_to_player_initialized(&app) != 0)
        goto cleanup;

    /* The constructor probe must leave the level it reads byte-identical. */
    if (level_pristine_tile_digest(app.level, &digest_after) != 0
        || digest_after != digest_before)
        goto cleanup;

    /*
     * Trace the source-ordered constructor events. Camera initialization is
     * deliberately not an event here: the original runs it at e.java:132,
     * after `new f(...)` has already run UseBigBall() at e.java:127.
     */
    if (expect->is_big_ball != 0u) {
        printf(
            "BIGBALL level=%d phase=%s order=UseBigBall-before-camera"
            " initial=(%u,%u) constructor=(%d,%d) probe=(%d,%d)"
            " ballSize=%d p=%d pristine=%016lx runtime=%s\n",
            expect->level_id,
            bounce_app_flow_entry_phase_name(
                bounce_app_flow_entry_phase(&app.flow)
            ),
            (unsigned)expect->initial_x,
            (unsigned)expect->initial_y,
            expect->constructor_x,
            expect->constructor_y,
            app.player.TODO_unkX,
            app.player.TODO_unkY,
            app.player.ballSize,
            app.player.p,
            digest_after,
            app.runtime == NULL ? "NULL" : "PRESENT"
        );
    }

    /*
     * Test D: a repeated initialization is rejected and the existing player is
     * preserved. No replacement semantics are invented here.
     */
    saved_player = app.player;
    saved_spawn = app.spawn;
    if (app_advance_level_loaded_to_player_initialized(&app) == 0
        || memcmp(&app.player, &saved_player, sizeof app.player) != 0
        || memcmp(&app.spawn, &saved_spawn, sizeof app.spawn) != 0)
        goto cleanup;

    if (bounce_app_flow_entry_phase(&app.flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_PLAYER_INITIALIZED
        /* level_loaded true, timer_started false, player_created true. */
        || !bounce_app_flow_entry_step_executed(&app.flow, true, false, true)
        || strcmp(
            bounce_app_flow_entry_phase_name(
                bounce_app_flow_entry_phase(&app.flow)
            ),
            "PLAYER_INITIALIZED"
        ) != 0
        /* The coarse application state is unchanged: no new screen or route. */
        || app.flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
        || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED
        /* Source-derived constructor defaults. */
        || !app.player.initialized
        /* The player owns the post-constructor position, probe included. */
        || app.player.TODO_unkX != expect->world_x
        || app.player.TODO_unkY != expect->world_y
        /* The f constructor input is the header-derived tile center. */
        || expect->constructor_x != (int32_t)expect->initial_x * 12 + 6
        || expect->constructor_y != (int32_t)expect->initial_y * 12 + 6
        /* A regular ball never enters UseBigBall(), so it cannot move. */
        || (expect->is_big_ball == 0u
            && (app.player.TODO_unkX != expect->constructor_x
                || app.player.TODO_unkY != expect->constructor_y))
        /*
         * The player's own size is the POST-probe value. ball_size/half_size/mode
         * in the table describe the player after the whole f constructor, which
         * for a big-ball level includes UseBigBall() at f.java:130 -- and that
         * probe can deflate the ball at f.java:618-621, so a big-ball level no
         * longer has to end the constructor at the header size. Only a regular
         * ball is pinned to the header size, because it never enters the probe
         * (f.java:127-128).
         */
        || app.player.ballSize != expect->ball_size
        || (expect->is_big_ball == 0u
            && app.player.ballSize != BOUNCE_REGULAR_BALL_SIZE)
        || app.player.p != expect->half_size
        || app.player.current_ball_mode != expect->mode
        /*
         * The spawn record stays the header-derived respawn point. The original
         * has no separate world spawn field: aq.a(initial_X, initial_Y) writes
         * the header tile coordinates after the probe, so the probe's transient
         * displacement is not a respawn anchor and no new record is invented.
         * The size triple is likewise header-derived, so it is derived from
         * is_big_ball rather than read from the post-probe player fields above:
         * a probe that deflates the ball must not silently move the anchor.
         */
        || !app.spawn.initialized
        || app.spawn.world_x != expect->constructor_x
        || app.spawn.world_y != expect->constructor_y
        || app.spawn.tile_x != (int32_t)expect->initial_x
        || app.spawn.tile_y != (int32_t)expect->initial_y
        || app.spawn.ball_size
            != (expect->is_big_ball == 0u
                ? BOUNCE_REGULAR_BALL_SIZE : BOUNCE_BIG_BALL_SIZE)
        || app.spawn.half_size
            != (expect->is_big_ball == 0u
                ? BOUNCE_REGULAR_BALL_P : BOUNCE_BIG_BALL_P)
        || app.spawn.ball_mode
            != (expect->is_big_ball == 0u
                ? BOUNCE_PLAYER_BALL_MODE_REGULAR
                : BOUNCE_PLAYER_BALL_MODE_BIG)
        /* Source-backed constructor defaults and the aq.l/aq.o literal 0, 0. */
        || app.player.horizontal_velocity != 0
        || app.player.o != 0
        || app.player.t != 0
        || app.player.q != 0
        || app.player.z != 0
        || app.player.C != 0
        || app.player.m
        /*
         * f.java:437/:440 write u from inside the UseBigBall() probe itself, so
         * a big-ball level can end the constructor with u == true. A regular
         * ball never runs the probe, so only that case is pinned.
         *
         * STEP 43B-R2: level 011 no longer sweeps the level while searching.
         * Under the f.java:175-205 control flow the walk ends on the first
         * fitting candidate, which is (1710, 449) -- one pixel above the
         * header-derived constructor point (1710, 450) -- so no further tile is
         * visited after it.
         */
        || (expect->is_big_ball == 0u && app.player.u)
        || app.player.powerUpGravity != 0
        || app.player.TODO_somePowerUp3 != 0
        /* Isolation: level, runtime, camera, counters, and tick are untouched. */
        || app.level == NULL
        || app.level_id != expect->level_id
        || app.runtime != NULL
        || app.l != 111
        || app.k != 222
        || app.v != 333
        || app.lives != 0
        || app.hoops_scored != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || app_update_game(&app) != 0
        || app.next_player_tick_ms != INT64_C(4321)
        || app.player.TODO_unkX != expect->world_x
        || app.player.TODO_unkY != expect->world_y
        || app.player.horizontal_velocity != 0
        || app.player.o != 0
        || app.player.t != 0
        /* Gameplay entry stays impossible without a runtime tile copy. */
        || bounce_game_activate_loaded_level(&app, 3) != -1
        || bounce_game_start_level(&app, BOUNCE_LEVEL001_PATH, 1, 3) == 0
        || app.next_player_tick_ms != INT64_C(4321))
        goto cleanup;

    result = 0;

cleanup:
    bounce_game_shutdown(&app);
    return result;
}

/*
 * Player-initialization boundary verification: LEVEL_LOADED ->
 * PLAYER_INITIALIZED -> STOP, including the runtime-tile guard, the released
 * level case, and NULL-input handling at the existing player seam.
 */
static int verify_player_initialization_boundary(void)
{
    /*
     * constructor_x/constructor_y are initial_X * 12 + 6 and initial_Y * 12 + 6.
     * world_x/world_y are the player position after the whole f constructor,
     * which for level 011 includes the f.UseBigBall() probe at f.java:130.
     * The big-ball values are produced by the source-derived algorithm over the
     * pristine level tiles; no original Java or Nokia runtime was executed.
     *
     * ball_size/half_size/mode are the POST-probe player values, and for level
     * 011 the probe never deflates. f.java:169-170 sets ballSize = 16 and
     * p = 8 before f.java:175 begins, and the first candidate of the
     * f.java:175-206 walk, (1710, 449), fits, so the walk ends there: one
     * probe, no deflater tile reached, and f.java:618-621 UseRegularBall() is
     * never entered from this constructor. The ball therefore ends the
     * constructor as a 16/8 big ball at (1710, 449). The gameplay deflating
     * tiles are 39-42; b.java:96 DEFLATER = 50 is a SpriteID, not a tile.
     *
     * STEP 43B-R2: the earlier 1777/545 and 12/6 expectation came from a native
     * loop that continued after the first fitting candidate instead of ending
     * on it. See STEP 43B and STEP 43B-R1.
     */
    static const PlayerEntryExpectation level001 = {
        1, 2u, 1u, 0u, 30, 18, 30, 18, 12, 6, BOUNCE_PLAYER_BALL_MODE_REGULAR
    };
    static const PlayerEntryExpectation level008 = {
        8, 99u, 1u, 0u, 1194, 18, 1194, 18, 12, 6,
        BOUNCE_PLAYER_BALL_MODE_REGULAR
    };
    static const PlayerEntryExpectation level011 = {
        11, 142u, 37u, 1u, 1710, 450, 1710, 449, 16, 8,
        BOUNCE_PLAYER_BALL_MODE_BIG
    };
    BounceApp app;
    BouncePlayer player;
    BouncePlayerSpawn spawn;
    BounceRuntimeLevelTiles *runtime;

    /* Test A: level 001 through the source-default direct route. */
    if (verify_player_initialization_route(-1, &level001) != 0)
        return -1;
    /* Test B: level 011, the big-ball header. */
    if (verify_player_initialization_route(10, &level011) != 0)
        return -1;
    /* Test C: level 008, a wider regular-ball level. */
    if (verify_player_initialization_route(7, &level008) != 0)
        return -1;

    /* Failure cases: wrong state, missing level, and a runtime tile copy. */
    if (bounce_game_init(&app) != 0 || bounce_game_enter_menu(&app) != 0)
        return -1;
    if (bounce_game_initialize_player_entry(NULL) != -1
        || bounce_game_initialize_player_entry(&app) != -1
        || app.player.initialized
        || drive_app_to_level_loaded(&app, -1, 1) != 0)
        return -1;

    /* A runtime tile copy must block the player-initialization seam. */
    runtime = bounce_runtime_level_tiles_create(app.level);
    if (runtime == NULL)
        return -1;
    app.runtime = runtime;
    if (bounce_game_initialize_player_entry(&app) != -1
        || app.player.initialized
        || bounce_runtime_level_tiles_width(runtime)
            != bounce_level_width(app.level)) {
        bounce_game_shutdown(&app);
        return -1;
    }
    bounce_runtime_level_tiles_destroy(runtime);
    app.runtime = NULL;
    if (bounce_game_initialize_player_entry(&app) != 0
        || !app.player.initialized) {
        bounce_game_shutdown(&app);
        return -1;
    }

    /* A released level leaves the player-initialization step unavailable. */
    bounce_player_reset(&app.player);
    memset(&app.spawn, 0, sizeof app.spawn);
    bounce_game_release_level(&app);
    if (bounce_game_initialize_player_entry(&app) != -1
        || app.player.initialized
        || app.level != NULL) {
        bounce_game_shutdown(&app);
        return -1;
    }
    bounce_game_shutdown(&app);

    /* NULL inputs at the existing seam must not partially initialize. */
    if (bounce_player_initialize_from_level(NULL, &player, &spawn) != -1
        || player.initialized
        || bounce_player_initialize_from_level(NULL, NULL, NULL) != -1) {
        bounce_player_reset(&player);
        return -1;
    }
    bounce_player_reset(&player);
    return 0;
}

/*
 * Runtime-initialization seam verification.
 *
 * A. Levels 001 and 011 initialize successfully; runtime != NULL; the copy owns
 *    its own mutable tiles and initially equals the pristine BounceLevel bytes.
 * B. The BounceLevel tile AND thorn-payload digest is identical before and after
 *    runtime creation, and the level stays usable after runtime destruction.
 * C. Every thorn-bearing level's runtime thorn count equals the source payload
 *    count and its initial w/ae equals the verified decoder output.
 * D. No PLAYING transition, timer, camera, or tick field is written.
 */
/*
 * Convenience wrapper for the pristine BounceLevel tile+payload digest.
 * Returns 0 if the level cannot be read.
 */
static unsigned long level_digest_value(const BounceLevel *level)
{
    unsigned long digest = 0UL;

    if (level_pristine_tile_digest(level, &digest) != 0)
        return 0UL;
    return digest;
}

static int verify_runtime_initialization_boundary(void)
{
    static const int thorn_levels[] = {
        2, 3, 4, 6, 7, 8, 9, 10, 11
    };
    size_t i;
    int failures = 0;

    /* --- A + B + D: staged route on Level 001 (regular) and Level 011 (big). */
    for (i = 0; i < 2u; ++i) {
        static const int ids[2] = { 1, 11 };
        static const int32_t constructor_x[2] = { 30, 1710 };
        static const int32_t constructor_y[2] = { 18, 450 };
        /*
         * Post-walk values, i.e. the state the whole f constructor leaves
         * behind (f.java:109-131 including UseBigBall() at :130).
         *
         * STEP 43B-R4: this comment previously claimed that level 011's probe
         * "walks f.java:175-206 with p == 8 until it reaches a deflater tile,
         * where f.java:618-621 calls UseRegularBall() and p becomes 6; every
         * later candidate is then tested with the regular half size, so the
         * walk settles at y = 545 rather than 547 and the ball ends the
         * constructor as a 12/6 ball." Every clause of that was pre-STEP43B.
         *
         * The constructor selects the big ball through f.java:129-130, which
         * sets ballSize = 16 and p = 8 (f.java:169-170) and then runs the
         * six-candidate settle walk at f.java:175-206. f.java:176 raises the
         * exit flag at the top of every pass and no fitting branch lowers it,
         * so the first candidate that fits ends the walk via `continue` plus the
         * f.java:175 condition. Level 011's constructor point is (1710, 450);
         * candidate 1 is f.java:177's (1710, 449), it fits, and the walk ends
         * there. The constructor therefore yields (1710, 449) as a 16/8 ball,
         * one pixel above the header-derived point.
         *
         * No deflater is part of this constructor path. The 39-42 tiles are
         * only reached from f.java:618-621 inside the walk, and this walk visits
         * exactly one candidate; that tile's handler is consequently not
         * entered here. (b.java:96 DEFLATER = 50 is a SpriteID, not a tile.)
         */
        static const int32_t probe_x[2] = { 30, 1710 };
        static const int32_t probe_y[2] = { 18, 449 };
        static const int32_t ball_size[2] = { 12, 16 };
        static const int32_t half_size[2] = { 6, 8 };
        BounceApp app;
        BouncePlayer player_before;
        BouncePlayerSpawn spawn_before;
        unsigned long level_digest_before;
        unsigned long level_digest_after;
        int32_t saved_l;
        int32_t saved_k;
        int32_t saved_v;
        int64_t saved_tick;
        int expect_id = ids[i];

        memset(&app, 0, sizeof app);
        /* Level 001 is driven through the source-default direct route (-1). */
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, expect_id == 1 ? -1 : expect_id - 1, expect_id) != 0
            || app.runtime != NULL
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            /* The probe ran against the pristine level, before any copy exists. */
            || app.runtime != NULL
            || app.player.TODO_unkX != probe_x[i]
            || app.player.TODO_unkY != probe_y[i]
            || app.player.ballSize != ball_size[i]
            || app.player.p != half_size[i]) {
            /*
             * STEP 43B-R4. The two ordering conjuncts that used to close this
             * block -- `probe_x < constructor_x` and `probe_y < constructor_y`
             * -- are REMOVED, and are deliberately NOT replaced by any other
             * ordering, including `>`.
             *
             * Neither was a Java invariant. f.UseBigBall() (f.java:168-207)
             * probes six candidates whose displacements are, in order,
             *
             *   f.java:177  (0, -offset)       f.java:191  (0, +offset)
             *   f.java:181  (-offset, -offset) f.java:195  (-offset, +offset)
             *   f.java:186  (+offset, -offset) f.java:200  (+offset, +offset)
             *
             * and the FIRST one tried is a Y DECREASE. f.java:176 sets the
             * flag true at the top of every pass and no fit arm clears it, so a
             * fit runs `continue`, increments the offset, and the f.java:175
             * condition `!true` then ends the walk: the loop terminates on the
             * first fitting candidate. Level 011's constructor point is
             * (1710, 450), candidate 1 is (1710, 449), it fits, and the walk
             * ends there with `y` one pixel BELOW the input.
             *
             * The `<` was a monotonicity heuristic that happened to fit the
             * pre-STEP43B native loop, which kept accumulating until an offset
             * with all six candidates blocked and therefore always moved up and
             * to the right. It never came from the source.
             *
             * Nothing is weakened by the removal: the four equality conjuncts
             * above pin the exact post-constructor player -- position, size and
             * half size. verify_player_initialization_boundary() makes the same
             * equality, and "the big ball moved" is already implied by that
             * equality differing from constructor_x/constructor_y.
             */
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        /* Big ball moved from its constructor input; regular ball did not. */
        if (expect_id == 1
            && (app.player.TODO_unkX != constructor_x[i]
                || app.player.TODO_unkY != constructor_y[i]))
            failures++;

        level_digest_before = level_digest_value(app.level);
        player_before = app.player;
        spawn_before = app.spawn;
        saved_l = app.l;
        saved_k = app.k;
        saved_v = app.v;
        saved_tick = app.next_player_tick_ms;

        if (app_advance_player_initialized_to_runtime_initialized(&app) != 0
            /* A: the runtime copy now exists. */
            || app.runtime == NULL
            || bounce_runtime_level_tiles_width(app.runtime)
                != bounce_level_width(app.level)
            || bounce_runtime_level_tiles_height(app.runtime)
                != bounce_level_height(app.level)
            /* Flow: recorded as the native runtime seam, still LEVEL_LOADED. */
            || bounce_app_flow_entry_phase(&app.flow)
                != BOUNCE_GAMEPLAY_ENTRY_PHASE_RUNTIME_INITIALIZED
            || !bounce_app_flow_entry_runtime_tiles_created(&app.flow)
            || !bounce_app_flow_entry_step_executed(
                &app.flow, true, false, true)
            || strcmp(
                bounce_app_flow_entry_phase_name(
                    bounce_app_flow_entry_phase(&app.flow)),
                "RUNTIME_INITIALIZED") != 0
            || app.flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
            || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED
            /* D: nothing else moved. */
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || app.l != saved_l || app.k != saved_k || app.v != saved_v
            || app.next_player_tick_ms != saved_tick
            || app.lives != 0 || app.hoops_scored != 0
            || app.level_complete || app.dead || app.respawn_requested
            || app.game_over
            /* D: no PLAYING transition is reachable from here. */
            || bounce_game_activate_loaded_level(&app, 3) != -1
            || bounce_game_start_level(
                &app, BOUNCE_LEVEL001_PATH, 1, 3) == 0
            || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* A: the copy's bytes initially equal the pristine level bytes. */
        {
            uint32_t width = bounce_level_width(app.level);
            uint32_t height = bounce_level_height(app.level);
            uint32_t x;
            uint32_t y;
            for (y = 0; y < height; ++y) {
                for (x = 0; x < width; ++x) {
                    uint8_t raw = 0;
                    uint16_t cell = 0;
                    if (bounce_level_get_tile(app.level, (int)x, (int)y,
                                              &raw) != 0
                        || bounce_runtime_level_tiles_get(app.runtime, (int)x,
                                                          (int)y, &cell) != 0
                        || cell != bounce_level_tile_value_from_raw(raw)) {
                        failures++;
                        y = height;
                        break;
                    }
                }
            }
        }

        /* B: the level is byte-identical after the copy was created. */
        level_digest_after = level_digest_value(app.level);
        if (level_digest_after != level_digest_before)
            failures++;

        /*
         * B: the copy is genuinely independent, and destroying it leaves the
         * pristine level valid and unchanged.
         */
        if (bounce_runtime_level_tiles_set(app.runtime, 0, 0, 0x1234u) != 0)
            failures++;
        if (level_digest_value(app.level) != level_digest_before)
            failures++;
        {
            /* B: mutating the copy's cell does not reach the pristine level. */
            uint8_t raw_before = 0;
            uint8_t raw_after = 0;
            if (bounce_level_get_tile(app.level, 0, 0, &raw_before) != 0
                || bounce_level_get_tile(app.level, 0, 0, &raw_after) != 0
                || raw_before != raw_after)
                failures++;
        }
        bounce_runtime_level_tiles_destroy(app.runtime);
        app.runtime = NULL;
        if (level_digest_value(app.level) != level_digest_before)
            failures++;
        /* B: the level is still fully valid after the runtime is gone. */
        if (bounce_level_width(app.level) == 0u
            || bounce_level_height(app.level) == 0u
            || bounce_level_thorn_count(app.level) > 12u)
            failures++;

        /* A: the seam refuses to run twice and preserves the existing copy. */
        if (app_advance_player_initialized_to_runtime_initialized(&app) == 0
            || app.runtime != NULL)
            failures++;
        bounce_game_shutdown(&app);
    }

    /* --- C: every thorn-bearing level's runtime state matches the source. */
    for (i = 0; i < sizeof thorn_levels / sizeof thorn_levels[0]; ++i) {
        BounceApp app;
        unsigned long digest_before;
        unsigned long digest_after;
        const BounceDynThorns *owned;
        uint32_t source_count;
        uint32_t t;
        int id = thorn_levels[i];
        char path[64];

        memset(&app, 0, sizeof app);
        if (bounce_game_level_resource_path(id, path, sizeof path) != 0) {
            failures++;
            continue;
        }
        {
            BounceLevel *probe = NULL;
            if (bounce_level_load_file(path, &probe) != BOUNCE_LEVEL_LOAD_OK
                || probe == NULL) {
                failures++;
                continue;
            }
            source_count = bounce_level_thorn_count(probe);
            digest_before = level_digest_value(probe);
            {
                BounceRuntimeLevelTiles *rt =
                    bounce_runtime_level_tiles_create(probe);
                const BounceDynThorns *got;
                BounceDynThornRecord first_record;
                int have_first = 0;
                if (rt == NULL) {
                    failures++;
                } else {
                    got = bounce_runtime_level_tiles_dyn_thorns(rt);
                    if (got == NULL || got->count != source_count) {
                        failures++;
                    } else {
                        BounceDynThornsSource src;
                        if (bounce_dyn_thorns_source(got, &src) != 0)
                            failures++;
                        for (t = 0; t < source_count; ++t) {
                            BounceDynThornRecord a;
                            BounceDynThornRecord b;
                            if (bounce_level_dyn_thorn_record(probe, t, &a) != 0
                                || !src.read_record(src.context, t, &b)
                                || memcmp(&a, &b, sizeof a) != 0) {
                                failures++;
                                break;
                            }
                            if (t == 0u) {
                                first_record = a;
                                have_first = 1;
                            }
                        }
                    }
                    /*
                     * Independence: the runtime copy is a separate allocation.
                     * Destroying it must leave the pristine level decodable and
                     * byte-identical, and its records must still equal a fresh
                     * decode of the same payload.
                     */
                    bounce_runtime_level_tiles_destroy(rt);
                    rt = NULL;
                    {
                        BounceDynThornRecord again;
                        if (have_first
                            && (bounce_level_dyn_thorn_record(
                                    probe, 0u, &again) != 0
                                || memcmp(&again, &first_record,
                                          sizeof again) != 0))
                            failures++;
                    }
                }
                if (rt != NULL)
                    bounce_runtime_level_tiles_destroy(rt);
            }
            digest_after = level_digest_value(probe);
            if (digest_after != digest_before)
                failures++;
            bounce_level_destroy(probe);
        }

        /* The staged route reaches the same runtime ownership. */
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(&app, id - 1, id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app.runtime == NULL) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        owned = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        if (owned == NULL || owned->count != source_count)
            failures++;
        /* The owned state equals a fresh decode of the same pristine payload. */
        if (source_count != 0u) {
            BounceDynThornRecord a;
            if (bounce_level_dyn_thorn_record(app.level, 0u, &a) != 0
                || owned->records == NULL
                || memcmp(&a, &owned->records[0], sizeof a) != 0)
                failures++;
        }
        /* Destroying the runtime leaves the pristine level unchanged. */
        digest_before = level_digest_value(app.level);
        bounce_runtime_level_tiles_destroy(app.runtime);
        app.runtime = NULL;
        if (level_digest_value(app.level) != digest_before
            || bounce_level_thorn_count(app.level) != source_count)
            failures++;
        bounce_game_shutdown(&app);
    }

    /* --- Failure cases: wrong state, missing level, uninitialized player. */
    {
        BounceApp app;
        if (bounce_game_init(&app) != 0 || bounce_game_enter_menu(&app) != 0)
            return -1;
        if (bounce_game_initialize_runtime_entry(NULL) != -1
            || bounce_game_initialize_runtime_entry(&app) != -1
            || app.runtime != NULL)
            failures++;
        if (drive_app_to_level_loaded(&app, -1, 1) != 0
            /* The player must be initialized first. */
            || bounce_game_initialize_runtime_entry(&app) != -1
            || app.runtime != NULL)
            failures++;
        bounce_game_shutdown(&app);
    }

    if (failures != 0)
        fprintf(stderr, "runtime initialization seam: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * STEP 44B -- Big Ball checkpoint respawn: the f.UseBigBall() settle walk.
 *
 * WHAT IS BEING VERIFIED
 *
 * f.UseBigBall() (f.java:168-207) is not a setter. After the three assignments at
 * f.java:169-171 it runs the six-candidate collision-settle walk at
 * f.java:175-206, and that walk MUTATES TODO_unkX / TODO_unkY. The source reaches
 * it from every respawn whose checkpoint ball size is not 12:
 *
 *   e.java:277   a(this.aq.d * 12 + 6, this.aq.c * 12 + 6, this.aq.b, 0, 0);
 *   e.java:127       this.aq = new f(paramInt1, paramInt2, ballSize, this);
 *   f.java:127-131     if (ballSize == 12) UseRegularBall(); else UseBigBall();
 *   f.java:175-206       the walk
 *
 * app_respawn_after_death() reproduced only f.java:169-171, so a Big Ball
 * respawned exactly on the converted checkpoint tile while the source places it
 * on the first free candidate. The STEP 44B call at :2369 closes that.
 *
 * WHY THE EXPECTATIONS ARE DERIVED, NOT HARD-CODED
 *
 * No settled coordinate appears as a literal in this function. For each case a
 * `reference` BouncePlayer is built to reproduce, field for field, the exact
 * pre-settle state the respawn constructs at :2293-2299 -- memset, position from
 * the checkpoint arithmetic of e.java:277, and the three size fields derived
 * from the checkpoint snapshot -- and the EXISTING production helper
 * bounce_player_use_big_ball() is then run on it. The respawn's own result is
 * compared against that reference.
 *
 * On top of that, two structural facts are read straight out of the production
 * pure query, and the expected coordinate is derived from them through
 * f.java:177-180 and f.java:205 rather than asserted as a number:
 *
 *   - if all six offset-1 candidates are FREE, f.java:177-180 takes the FIRST
 *     one, applies y -= offset with offset == 1, and f.java:175's condition then
 *     ends the walk, so the settled position MUST be (centre_x, centre_y - 1);
 *   - if all six offset-1 candidates are BLOCKED, f.java:205 clears the flag and
 *     the walk continues at offset 2, so the settled position MUST differ from
 *     the centre.
 *
 * Which of the two holds is decided by bounce_collision_query() at run time, so
 * the same assertion would hold if the level geometry ever changed -- it is not
 * a memorised coordinate.
 *
 * CASES
 *
 *   A  level 001, tile (56, 3), big snapshot   -- first candidate fits
 *   B  level 003, tile (12, 1), big snapshot   -- offset-1 pass fully blocked,
 *                                                  so the walk escalates
 *   C  level 001, tile (56, 3), regular        -- the guard must not fire
 *   D  folded into B: the wall latch f.u that f.a() raises during the walk
 *      (f.java:437 / :440) must survive the respawn rather than be suppressed.
 *
 * Both checkpoint tiles are real CRYSTAL cells in their own resource: level 001
 * carries tile 7 at (56, 3) and level 003 carries tile 7 at (12, 1). The
 * checkpoint value a crystal establishes is f.b = ballSize at the touch
 * (f.java:137), so both tiles can legitimately carry a 16 snapshot.
 *
 * CAMERA ORDER. After the respawn the camera is recomputed once more; if
 * app_update_camera() had already consumed the post-walk position -- which is
 * what e.java:132 does, the camera running AFTER f.java:175-206 -- then l and v
 * are already at their fixed point and the recomputation changes nothing. The
 * formula is not restated here.
 *
 * REGISTERED EARLY IN main()'s SEQUENCE. This check is placed before
 * verify_runtime_initialization_boundary() so that its result is reported even
 * while the pre-existing STEP43B-R2 fixture blocker at :7942-7943 aborts the run.
 * Nothing is disabled and no other check is moved: it is an ordinary member of
 * the sequence that happens to run early.
 */
static int verify_big_ball_respawn_settle(void)
{
    static const char *const case_path[] = {
        "src/main/resources/levels/J2MElvl.001",
        "src/main/resources/levels/J2MElvl.003",
        "src/main/resources/levels/J2MElvl.001"
    };
    static const int case_from[] = { -1, 2, -1 };
    static const int case_level[] = { 1, 3, 1 };
    static const int case_tile_x[] = { 56, 12, 56 };
    static const int case_tile_y[] = { 3, 1, 3 };
    static const int32_t case_snapshot[] = {
        BOUNCE_BIG_BALL_SIZE,
        BOUNCE_BIG_BALL_SIZE,
        BOUNCE_REGULAR_BALL_SIZE
    };
    static const char *const case_name[] = { "A", "B", "C" };
    size_t index;
    int failures = 0;

    for (index = 0; index < 3u; ++index) {
        BounceApp app;
        BouncePlayer reference;
        int32_t centre_x;
        int32_t centre_y;
        int32_t reference_size;
        int32_t reference_p;
        BouncePlayerBallMode reference_mode;
        bool big = case_snapshot[index] != BOUNCE_REGULAR_BALL_SIZE;
        bool offset1_all_free = false;
        bool offset1_all_blocked = false;
        int32_t saved_l;
        int32_t saved_v;

        centre_x = case_tile_x[index] * BOUNCE_TILE_SIZE + 6;
        centre_y = case_tile_y[index] * BOUNCE_TILE_SIZE + 6;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, case_from[index], case_level[index]) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            /* app_respawn_after_death() requires both of these. */
            || app.runtime == NULL
            || !app.spawn.initialized
            /* The case is anchored to a named resource, not to a level id that
             * happens to resolve the same way: prove the driver loaded the file
             * this case is written against. */
            || app.level_path == NULL
            || strcmp(app.level_path, case_path[index]) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }

        /* The reference: exactly the state :2293-2299 builds, nothing else. */
        bounce_player_reset(&reference);
        reference.TODO_unkX = centre_x;
        reference.TODO_unkY = centre_y;
        reference.ballSize = case_snapshot[index];
        reference.p = (case_snapshot[index] == BOUNCE_BIG_BALL_SIZE)
            ? BOUNCE_BIG_BALL_P
            : BOUNCE_REGULAR_BALL_P;
        reference.current_ball_mode = (case_snapshot[index] == BOUNCE_BIG_BALL_SIZE)
            ? BOUNCE_PLAYER_BALL_MODE_BIG
            : BOUNCE_PLAYER_BALL_MODE_REGULAR;
        reference.initialized = true;

        /* Read the offset-1 geometry through the production pure query. */
        if (big) {
            bool fits[6];

            fits[0] = bounce_collision_query(
                centre_x, centre_y - 1, BOUNCE_BIG_BALL_P, app.runtime);
            fits[1] = bounce_collision_query(
                centre_x - 1, centre_y - 1, BOUNCE_BIG_BALL_P, app.runtime);
            fits[2] = bounce_collision_query(
                centre_x + 1, centre_y - 1, BOUNCE_BIG_BALL_P, app.runtime);
            fits[3] = bounce_collision_query(
                centre_x, centre_y + 1, BOUNCE_BIG_BALL_P, app.runtime);
            fits[4] = bounce_collision_query(
                centre_x - 1, centre_y + 1, BOUNCE_BIG_BALL_P, app.runtime);
            fits[5] = bounce_collision_query(
                centre_x + 1, centre_y + 1, BOUNCE_BIG_BALL_P, app.runtime);
            offset1_all_free = fits[0] && fits[1] && fits[2]
                && fits[3] && fits[4] && fits[5];
            offset1_all_blocked = !fits[0] && !fits[1] && !fits[2]
                && !fits[3] && !fits[4] && !fits[5];
            if (!offset1_all_free && !offset1_all_blocked) {
                /* Neither branch of f.java:175-206 is exercised, so neither
                 * derived expectation below applies. */
                bounce_game_shutdown(&app);
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s level %d tile (%d,%d) "
                    "is neither fully free nor fully blocked at offset 1\n",
                    case_name[index], case_level[index],
                    case_tile_x[index], case_tile_y[index]
                );
                failures++;
                continue;
            }
            if (bounce_player_use_big_ball(
                    &reference,
                    app.runtime,
                    NULL,
                    NULL
                ) != 0) {
                bounce_game_shutdown(&app);
                return -1;
            }
        }

        /* The act under test. */
        app.lives = 3;
        app.checkpoint_tile_x = case_tile_x[index];
        app.checkpoint_tile_y = case_tile_y[index];
        app.checkpoint_ball_size = case_snapshot[index];
        if (app_respawn_after_death(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }

        if (big) {
            /* The respawn must equal the reference walk exactly. */
            if (app.player.TODO_unkX != reference.TODO_unkX
                || app.player.TODO_unkY != reference.TODO_unkY
                || app.player.ballSize != reference.ballSize
                || app.player.p != reference.p
                || app.player.current_ball_mode != reference.current_ball_mode
                || app.player.u != reference.u
                || app.player.v != reference.v
                || app.player.horizontal_velocity != reference.horizontal_velocity
                || app.player.o != reference.o) {
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s mismatch vs the "
                    "production walk: respawn (%d,%d) size %d p %d u %d v %d "
                    "vs reference (%d,%d) size %d p %d u %d v %d\n",
                    case_name[index],
                    app.player.TODO_unkX, app.player.TODO_unkY,
                    app.player.ballSize, app.player.p, app.player.u,
                    app.player.v,
                    reference.TODO_unkX, reference.TODO_unkY,
                    reference.ballSize, reference.p, reference.u, reference.v
                );
                failures++;
            }
            /* f.java:110-125 / :119 / :124: the new player starts counted out
             * no longer; z and q are zero. */
            if (app.player.z != 0 || app.player.q != 0) {
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s left z %d q %d\n",
                    case_name[index], app.player.z, app.player.q
                );
                failures++;
            }
            if (offset1_all_free
                && (app.player.TODO_unkX != centre_x
                    || app.player.TODO_unkY != centre_y - 1)) {
                /* f.java:177-180: the first candidate fits, so y -= 1 and
                 * f.java:175 ends the walk there. */
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s expected f.java:177-180 "
                    "(%d,%d), got (%d,%d)\n",
                    case_name[index], centre_x, centre_y - 1,
                    app.player.TODO_unkX, app.player.TODO_unkY
                );
                failures++;
            }
            if (offset1_all_blocked
                && (app.player.TODO_unkX == centre_x
                    && app.player.TODO_unkY == centre_y)) {
                /* f.java:205: the flag is cleared, so the walk continues at
                 * offset 2 and the ball cannot stay on the centre. */
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s stayed on the raw centre "
                    "(%d,%d) although every offset-1 candidate is blocked\n",
                    case_name[index], centre_x, centre_y
                );
                failures++;
            }
        } else {
            /* CASE C -- the guard must be false, so nothing was called. */
            reference_size = reference.ballSize;
            reference_p = reference.p;
            reference_mode = reference.current_ball_mode;
            if (app.player.TODO_unkX != centre_x
                || app.player.TODO_unkY != centre_y
                || app.player.ballSize != reference_size
                || app.player.p != reference_p
                || app.player.current_ball_mode != reference_mode
                || app.player.u != false
                || app.player.v != false
                || app.player.horizontal_velocity != 0
                || app.player.o != 0
                || app.player.z != 0
                || app.player.q != 0) {
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s regular respawn changed: "
                    "(%d,%d) size %d p %d mode %d u %d v %d\n",
                    case_name[index],
                    app.player.TODO_unkX, app.player.TODO_unkY,
                    app.player.ballSize, app.player.p,
                    app.player.current_ball_mode, app.player.u, app.player.v
                );
                failures++;
            }
        }

        /*
         * CASE D -- f.u raised by f.a() during the walk (f.java:437 / :440) is
         * preserved, not suppressed. Asserted against the reference rather than
         * a literal, and only where the geometry is known to produce it: the
         * level-003 crystal at (12,1) sits in a pocket whose probed windows
         * contain a wall, so the walk raises u and the respawn must carry it.
         * Level 001's open-air crystal must not, which makes the pair
         * discriminating rather than a blanket "u is true".
         */
        if (big) {
            if (app.player.u != reference.u
                || (index == 1u && app.player.u != true)
                || (index == 0u && app.player.u != false)) {
                fprintf(
                    stderr,
                    "big ball respawn settle: case %s f.u latch wrong: "
                    "respawn %d reference %d\n",
                    case_name[index], app.player.u, reference.u
                );
                failures++;
            }
        }

        /* e.java:132 runs the camera AFTER the walk, so it is already at its
         * fixed point for the post-walk position. No formula is restated. */
        saved_l = app.l;
        saved_v = app.v;
        if (app_update_camera_horizontal(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        if (app.l != saved_l || app.v != saved_v) {
            fprintf(
                stderr,
                "big ball respawn settle: case %s camera was not computed from "
                "the settled position: before (%d,%d) after (%d,%d)\n",
                case_name[index], saved_l, saved_v, app.l, app.v
            );
            failures++;
        }

        printf(
            "BIGBALL RESPAWN case %s level %d tile (%d,%d) snapshot %d -> "
            "player (%d,%d) size %d p %d mode %d u %d v %d camera (%d,%d,%d)\n",
            case_name[index], case_level[index],
            case_tile_x[index], case_tile_y[index], case_snapshot[index],
            app.player.TODO_unkX, app.player.TODO_unkY,
            app.player.ballSize, app.player.p,
            (int)app.player.current_ball_mode,
            app.player.u, app.player.v, app.l, app.k, app.v
        );
        (void)fflush(stdout);

        bounce_game_shutdown(&app);
    }

    if (failures != 0)
        fprintf(stderr, "big ball respawn settle: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Camera-initialization seam verification.
 *
 * Expected l/k/v are the values the already-verified app_update_camera()
 * produces from the source formula, and are asserted exactly so a future change
 * to the camera implementation cannot pass unnoticed:
 *
 *   l = clamp(playerX - 64, 0, width*12 - 156) / 12
 *   v = l*12 - clamp(playerX - 64, 0, width*12 - 156)
 *   k: 0, then -7 while (playerY - 6 < k*12), then +7 while (playerY + 6 > k*12+96)
 */
static int verify_camera_initialization_boundary(void)
{
    static const struct {
        int level_id;
        int list_index;
        int32_t player_x;
        int32_t player_y;
        int32_t expected_l;
        int32_t expected_k;
        int32_t expected_v;
        int32_t expected_ball_size;
    } cases[] = {
        /* 001: i = 30-64 -> 0, so l = 0, v = 0; y=18 needs no k step. */
        {  1, -1,   30,  18,   0,  0,   0, 12 },
        /* 008: i = 1130, l = 94, v = -2; y=18 needs no k step. */
        {  8,  7, 1194,  18,  94,  0,  -2, 12 },
        /* 011: post-probe x=1710 -> i=1646, l=137, v=-2; y=449 -> k=35.
         * STEP 43B-R2: the f.java:175-206 walk ends on its first fitting
         * candidate, so the constructor leaves the ball at (1710, 449) as a
         * 16/8 big ball and the f.java:618-621 deflate is never reached. */
        { 11, 10, 1710, 449, 137, 35,  -2, 16 }
    };
    size_t c;
    int failures = 0;

    for (c = 0; c < sizeof cases / sizeof cases[0]; ++c) {
        BounceApp app;
        BouncePlayer player_before;
        BouncePlayerSpawn spawn_before;
        unsigned long digest_level;
        unsigned long digest_runtime;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, cases[c].list_index, cases[c].level_id) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* C: the camera seam is refused before the runtime stage exists. */
        if (app_advance_runtime_initialized_to_camera_initialized(&app) == 0
            || app.runtime != NULL) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        /* C: the Big Ball probe already ran against the pristine level. */
        if (app_advance_level_loaded_to_player_initialized(&app) != 0
            || app.runtime != NULL
            || app.player.TODO_unkX != cases[c].player_x
            || app.player.TODO_unkY != cases[c].player_y
            || app.player.ballSize != cases[c].expected_ball_size
            || bounce_app_flow_entry_camera_initialized(&app.flow)) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        player_before = app.player;
        spawn_before = app.spawn;
        digest_level = level_digest_value(app.level);

        /* C: runtime becomes non-NULL, player/spawn and level unchanged. */
        if (app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app.runtime == NULL
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || level_digest_value(app.level) != digest_level) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        digest_runtime = level_digest_value(app.level);

        /* C: trace the source-ordered staged sequence for observability. */
        printf(
            "CAMERAINIT level=%d order=player-before-runtime-before-camera"
            " phase=%s runtime=%s\n",
            cases[c].level_id,
            bounce_app_flow_entry_phase_name(
                bounce_app_flow_entry_phase(&app.flow)),
            app.runtime == NULL ? "NULL" : "PRESENT"
        );

        /* A: the camera seam runs last and installs the verified state. */
        if (app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            /* A: exact verified l/k/v. */
            || app.l != cases[c].expected_l
            || app.k != cases[c].expected_k
            || app.v != cases[c].expected_v
            /* C: recorded only after both prior stages. */
            || !bounce_app_flow_entry_camera_initialized(&app.flow)
            || !bounce_app_flow_entry_runtime_tiles_created(&app.flow)
            || bounce_app_flow_entry_phase(&app.flow)
                != BOUNCE_GAMEPLAY_ENTRY_PHASE_CAMERA_INITIALIZED
            || strcmp(
                bounce_app_flow_entry_phase_name(
                    bounce_app_flow_entry_phase(&app.flow)),
                "CAMERA_INITIALIZED") != 0
            || !bounce_app_flow_entry_step_executed(
                &app.flow, true, false, true)
            /* D/E: player, spawn, and the pristine level are untouched. */
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || level_digest_value(app.level) != digest_level
            || digest_runtime != digest_level
            /* G: coarse state stays LEVEL_LOADED and PLAYING is unreachable. */
            || app.flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
            || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED
            || bounce_game_activate_loaded_level(&app, 3) != -1
            || bounce_game_start_level(
                &app, BOUNCE_LEVEL001_PATH, 1, 3) == 0
            || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED) {
            fprintf(stderr, "camera seam level %d: l=%d k=%d v=%d phase=%s"
                    " state=%d\n", cases[c].level_id, app.l, app.k, app.v,
                    bounce_app_flow_entry_phase_name(
                        bounce_app_flow_entry_phase(&app.flow)),
                    (int)app.state);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* The seam refuses to run twice and preserves the camera state. */
        if (app_advance_runtime_initialized_to_camera_initialized(&app) == 0
            || app.l != cases[c].expected_l
            || app.k != cases[c].expected_k
            || app.v != cases[c].expected_v) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        bounce_game_shutdown(&app);
    }

    /* F: NULL input is rejected. */
    if (app_advance_runtime_initialized_to_camera_initialized(NULL) != -1)
        failures++;

    if (failures != 0)
        fprintf(stderr, "camera initialization seam: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Gameplay-activation seam verification.
 *
 * A. Initialization preservation: level digest, player bytes, spawn bytes,
 *    runtime, dynamic-thorn state, and camera l/k/v are all unchanged across
 *    activation for Levels 001 and 011.
 * B. Activation succeeds exactly once; the transition is deterministic; a repeat
 *    is rejected with everything preserved; no tick is executed.
 * C. No premature gameplay: verified by the static scan reported alongside, and
 *    by asserting the tick deadline and counters never move.
 * D. Camera regression: only that l/k/v are unchanged (no re-audit).
 * G. State guard: app.state == PLAYING and flow.state == GAMEPLAY.
 */
static int verify_gameplay_activation_boundary(void)
{
    static const struct {
        int level_id;
        int list_index;
        int32_t player_x;
        int32_t player_y;
        int32_t camera_l;
        int32_t camera_k;
        int32_t camera_v;
    } cases[] = {
        {  1, -1,   30,  18,   0,  0,   0 },
        { 11, 10, 1710, 449, 137, 35,  -2 }
    };
    size_t c;
    int failures = 0;

    for (c = 0; c < sizeof cases / sizeof cases[0]; ++c) {
        BounceApp app;
        BouncePlayer player_before;
        BouncePlayerSpawn spawn_before;
        BounceDynThornRecord thorn_record;
        BounceDynThornsSource thorn_source;
        uint32_t thorn_count;
        unsigned long digest_before;
        int64_t saved_tick;
        int32_t l_before;
        int32_t k_before;
        int32_t v_before;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, cases[c].list_index, cases[c].level_id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* B: activation is refused before CAMERA_INITIALIZED. */
        if (bounce_game_activate_staged_level(&app) == 0
            || app.flow.state != BOUNCE_APP_STATE_LEVEL_LOADED
            || app.state != BOUNCE_GAME_STATE_LEVEL_LOADED) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        if (app_advance_runtime_initialized_to_camera_initialized(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        player_before = app.player;
        spawn_before = app.spawn;
        saved_tick = app.next_player_tick_ms;
        digest_before = level_digest_value(app.level);
        l_before = app.l;
        k_before = app.k;
        v_before = app.v;
        thorn_source.read_record = NULL;
        thorn_source.context = NULL;
        thorn_source.count = 0u;
        memset(&thorn_record, 0, sizeof thorn_record);
        {
            const BounceDynThorns *owned =
                bounce_runtime_level_tiles_dyn_thorns(app.runtime);
            thorn_count = owned == NULL ? 0u : owned->count;
            if (owned != NULL && bounce_dyn_thorns_source(owned, &thorn_source)
                != 0) {
                bounce_game_shutdown(&app);
                failures++;
                continue;
            }
            if (thorn_count != 0u
                && !thorn_source.read_record(
                    thorn_source.context, 0u, &thorn_record)) {
                bounce_game_shutdown(&app);
                failures++;
                continue;
            }
        }

        /* B: activation succeeds exactly once. */
        if (app_advance_camera_initialized_to_activated(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* G: the explicit state transition. */
        if (app.state != BOUNCE_GAME_STATE_PLAYING
            || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || !bounce_app_flow_entry_gameplay_activated(&app.flow)
            || bounce_app_flow_entry_phase(&app.flow)
                != BOUNCE_GAMEPLAY_ENTRY_PHASE_ACTIVATED
            || strcmp(
                bounce_app_flow_entry_phase_name(
                    bounce_app_flow_entry_phase(&app.flow)),
                "ACTIVATED") != 0
            || !bounce_app_flow_entry_step_executed(
                &app.flow, true, false, true)
            /* C: no timer was started and no tick deadline was set. */
            || app.flow.gameplay_entry.timer_started
            || app.flow.next_tick_ms != 0
            || app.next_player_tick_ms != saved_tick
            /* C: no gameplay counters moved. */
            || app.hoops_scored != 0
            || app.level_complete || app.dead || app.respawn_requested
            || app.game_over
            /*
             * C (discharged): this assertion used to be `app.lives != 0`, which
             * pinned the pre-fix divergence in place. Activation genuinely left
             * lives at whatever bounce_game_init() wrote, because the staged
             * chain had no writer for it, so production entered PLAYING with
             * lives == 0 and the first KillBall (f.java:219) drove it to -1 --
             * straight past the `lives < 0` game-over boundary (e.java:268,
             * f.java:662) on death #1 instead of death #4. The pin documented
             * the bug as if it were the contract.
             *
             * bounce_game_activate_staged_level() now mirrors the flow-owned
             * initial lives at the same boundary that enters PLAYING (game.c,
             * next to `game->state = BOUNCE_GAME_STATE_PLAYING`), exactly as the
             * legacy bounce_game_activate_loaded_level() mirrors it at its
             * `game->lives = lives`. The value is asserted against the flow
             * rather than a fresh literal, so BOUNCE_APP_ENTRY_INITIAL_LIVES
             * stays the single source of truth and this gate fails if the
             * mirror or the flow ever diverges.
             */
            || app.lives != bounce_app_flow_entry_initial_lives(&app.flow)
            /* A + D: nothing initialized was disturbed. */
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || app.l != l_before || app.k != k_before || app.v != v_before
            || app.l != cases[c].camera_l
            || app.k != cases[c].camera_k
            || app.v != cases[c].camera_v
            || app.player.TODO_unkX != cases[c].player_x
            || app.player.TODO_unkY != cases[c].player_y
            || app.runtime == NULL
            || level_digest_value(app.level) != digest_before) {
            fprintf(stderr, "activation level %d: state=%d flow=%d"
                    " l=%d k=%d v=%d tick=%lld\n",
                    cases[c].level_id, (int)app.state, (int)app.flow.state,
                    app.l, app.k, app.v, (long long)app.next_player_tick_ms);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* A: dynamic-thorn state is still valid and unchanged. */
        {
            const BounceDynThorns *owned =
                bounce_runtime_level_tiles_dyn_thorns(app.runtime);
            if (owned == NULL || owned->count != thorn_count) {
                bounce_game_shutdown(&app);
                failures++;
                continue;
            }
            if (thorn_count != 0u) {
                BounceDynThornRecord again;
                if (!thorn_source.read_record(
                        thorn_source.context, 0u, &again)
                    || memcmp(&again, &thorn_record, sizeof again) != 0) {
                    bounce_game_shutdown(&app);
                    failures++;
                    continue;
                }
            }
        }

        /* B: a repeated activation is rejected and preserves everything. */
        if (bounce_game_activate_staged_level(&app) == 0
            || app.state != BOUNCE_GAME_STATE_PLAYING
            || app.l != l_before || app.k != k_before || app.v != v_before
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || level_digest_value(app.level) != digest_before) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        bounce_game_shutdown(&app);
    }

    /* F: NULL input is rejected. */
    if (bounce_game_activate_staged_level(NULL) != -1)
        failures++;

    if (failures != 0)
        fprintf(stderr, "gameplay activation seam: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Game-timer / Tick-entry seam verification.
 *
 * A. period == 40 ms (BounceTimer.java:17), and the timer struct carries no
 *    delta-time state, accumulator, deadline, or missed-tick field.
 * B. Before: PLAYING / GAMEPLAY / timer_started == false. After: timer started,
 *    period 40, and no Tick body executed.
 * C+E. Exactly one deterministic callback produces exactly one Tick ENTRY and
 *    disturbs nothing initialized.
 * D. No gameplay execution: the timer module is clock-free and the seam calls
 *    no physics, collision, dyn-thorn, render, audio, persistence, or input.
 * F. Determinism: repeated callbacks produce one entry each, with no extra
 *    callback, no recursion, and no accumulated ticks.
 */
static int verify_game_timer_tick_entry_boundary(void)
{
    BounceApp app;
    BouncePlayer player_before;
    BouncePlayerSpawn spawn_before;
    const BounceDynThorns *thorns_before;
    const BounceDynThorns *thorns_after;
    unsigned long digest_before;
    int64_t saved_tick;
    int32_t l_before;
    int32_t k_before;
    int32_t v_before;
    int failures = 0;
    int repeat;

    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0
        || drive_app_to_level_loaded(&app, 10, 11) != 0
        || app_advance_level_loaded_to_player_initialized(&app) != 0
        || app_advance_player_initialized_to_runtime_initialized(&app) != 0
        || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
        || app_advance_camera_initialized_to_activated(&app) != 0) {
        bounce_game_shutdown(&app);
        return -1;
    }

    /* B: state before the timer exists. */
    if (app.state != BOUNCE_GAME_STATE_PLAYING
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || app.flow.gameplay_entry.timer_started
        || bounce_game_timer_is_started(&app.game_timer)
        || bounce_game_timer_tick_entry_count(&app.game_timer) != 0u
        || bounce_game_timer_callback(&app.game_timer) != -1
        || bounce_game_timer_period_ms(&app.game_timer) != BOUNCE_GAME_TIMER_PERIOD_MS) {
        bounce_game_shutdown(&app);
        return -1;
    }

    player_before = app.player;
    spawn_before = app.spawn;
    digest_before = level_digest_value(app.level);
    saved_tick = app.next_player_tick_ms;
    l_before = app.l;
    k_before = app.k;
    v_before = app.v;
    thorns_before = bounce_runtime_level_tiles_dyn_thorns(app.runtime);

    /* B: timer initialization. The seam is refused before ACTIVATION too. */
    if (bounce_game_initialize_game_timer(NULL) != -1
        || bounce_game_initialize_game_timer(&app) != 0
        || !bounce_game_timer_is_started(&app.game_timer)
        || bounce_game_timer_period_ms(&app.game_timer)
            != BOUNCE_GAME_TIMER_PERIOD_MS
        || bounce_game_timer_period_ms(&app.game_timer) != 40
        || !app.flow.gameplay_entry.timer_started
        || bounce_app_flow_entry_phase(&app.flow)
            != BOUNCE_GAMEPLAY_ENTRY_PHASE_TIMER_INITIALIZED
        || strcmp(
            bounce_app_flow_entry_phase_name(
                bounce_app_flow_entry_phase(&app.flow)),
            "TIMER_INITIALIZED") != 0
        || app.state != BOUNCE_GAME_STATE_PLAYING
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        /* No clock, no deadline, no accumulator was introduced. */
        || app.flow.next_tick_ms != 0
        || app.next_player_tick_ms != saved_tick
        /* E: still zero entries; no callback happened. */
        || bounce_game_timer_tick_entry_count(&app.game_timer) != 0u
        /* b.java:836-837 idempotence. */
        || bounce_game_initialize_game_timer(&app) == 0
        || bounce_game_timer_period_ms(&app.game_timer)
            != BOUNCE_GAME_TIMER_PERIOD_MS) {
        fprintf(stderr, "timer init: started=%d period=%d count=%llu\n",
                (int)bounce_game_timer_is_started(&app.game_timer),
                bounce_game_timer_period_ms(&app.game_timer),
                (unsigned long long)
                    bounce_game_timer_tick_entry_count(&app.game_timer));
        bounce_game_shutdown(&app);
        return -1;
    }

    /* C + E + F: one deterministic callback per iteration, nothing else moves. */
    for (repeat = 1; repeat <= 8; ++repeat) {
        if (bounce_game_timer_callback(&app.game_timer) != 0
            /* Exactly one entry per callback, no extras, no accumulation. */
            || bounce_game_timer_tick_entry_count(&app.game_timer)
                != (unsigned long long)repeat
            || bounce_game_timer_period_ms(&app.game_timer)
                != BOUNCE_GAME_TIMER_PERIOD_MS
            /* C: nothing initialized was disturbed. */
            || memcmp(&app.player, &player_before, sizeof app.player) != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || app.l != l_before || app.k != k_before || app.v != v_before
            || app.player.TODO_unkX != 1710 || app.player.TODO_unkY != 449
            || app.next_player_tick_ms != saved_tick
            || app.flow.next_tick_ms != 0
            /* C (discharged): was `app.lives != 0`, pinning the pre-fix
             * divergence; staged activation now mirrors the flow-owned
             * value. See verify_gameplay_activation_boundary() and
             * bounce_game_activate_staged_level(). */
            || app.lives != bounce_app_flow_entry_initial_lives(&app.flow)
            || app.hoops_scored != 0
            || app.level_complete || app.dead || app.respawn_requested
            || app.game_over
            || app.state != BOUNCE_GAME_STATE_PLAYING
            || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || level_digest_value(app.level) != digest_before) {
            fprintf(stderr, "timer callback %d: count=%llu\n", repeat,
                    (unsigned long long)
                        bounce_game_timer_tick_entry_count(&app.game_timer));
            failures++;
            break;
        }
    }

    /* A: the dynamic-thorn state is untouched by timer scheduling/callback. */
    thorns_after = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
    if (thorns_after == NULL
        || thorns_before == NULL
        || thorns_after->count != thorns_before->count
        || memcmp(thorns_after->records, thorns_before->records,
                  (size_t)thorns_after->count * sizeof *thorns_after->records)
            != 0)
        failures++;

    if (failures == 0) {
        printf("TIMER period=%dms start=idempotent callbacks=8"
               " tick_entry=%llu tick_body=0\n",
               bounce_game_timer_period_ms(&app.game_timer),
               (unsigned long long)
                   bounce_game_timer_tick_entry_count(&app.game_timer));
    }
    bounce_game_shutdown(&app);
    return failures == 0 ? 0 : -1;
}

/*
 * Tick-dispatch boundary verification.
 *
 * A. Normal PLAYING path for Levels 001 and 011: timer callback -> Tick entry ->
 *    pre-dispatch gates -> camera gate -> player-tick dispatch -> STOP, with
 *    tick_entry == 1, tick_dispatch == 1, player_tick == 0.
 * B. State preservation across the dispatch boundary.
 * C. Timer unchanged: 40 ms, no clock read, no next_player_tick_ms scheduling,
 *    no routing through the legacy app_run_player_ticks().
 * E. The legacy timing path is not reached.
 *
 * The reset and splash gates are additionally exercised through the public seam,
 * because they are explicit parameters there: this is source-backed ordering
 * verification and adds no new behavior.
 */
/*
 * Compare the player record excluding its f.b() frame state, which the
 * pre-physics entry legitimately fills. Everything the physics body could
 * touch is inside the compared prefix, so this is a strict "no physics field
 * changed" check.
 */
static bool player_equal_excluding_tick_entry(
    const BouncePlayer *a,
    const BouncePlayer *b
)
{
    if (a == NULL || b == NULL)
        return false;
    return memcmp(a, b, offsetof(BouncePlayer, tick_entry)) == 0;
}

static int verify_tick_dispatch_boundary(void)
{
    static const struct {
        int level_id;
        int list_index;
        int32_t player_x;
        int32_t player_y;
        int32_t camera_l;
        int32_t camera_k;
        int32_t camera_v;
    } cases[] = {
        {  1, -1,   30,  18,   0,  0,   0 },
        { 11, 10, 1710, 449, 137, 35,  -2 }
    };
    size_t c;
    int failures = 0;

    for (c = 0; c < sizeof cases / sizeof cases[0]; ++c) {
        BounceApp app;
        BouncePlayer player_before;
        BouncePlayerSpawn spawn_before;
        const BounceDynThorns *thorns_before;
        const BounceDynThorns *thorns_after;
        BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
        unsigned long digest_before;
        int countdown_before;
        int64_t saved_tick;
        int32_t l_before;
        int32_t k_before;
        int32_t v_before;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, cases[c].list_index, cases[c].level_id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        player_before = app.player;
        spawn_before = app.spawn;
        thorns_before = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        digest_before = level_digest_value(app.level);
        countdown_before = bounce_app_flow_entry_countdown(&app.flow);
        saved_tick = app.next_player_tick_ms;
        l_before = app.l;
        k_before = app.k;
        v_before = app.v;

        /*
         * A: for these levels the e.java:262 camera condition is false, so the
         * source takes the else branch at e.java:264 and would call f.b().
         */
        if (app_camera_needs_update(&app)) {
            fprintf(stderr, "tick dispatch level %d: camera gate true\n",
                    cases[c].level_id);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /*
         * A: the seam is refused before TIMER_INITIALIZED is reached.
         *
         * The dispatch is invoked with a NULL body, which is the documented
         * stop-after-prologue contract this test verifies. The physics
         * continuation is covered separately by
         * verify_player_physics_continuation(). Assertions below are unchanged.
         */
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, false, false, false, NULL, NULL, &branch) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* A: exactly one entry, one dispatch, zero player ticks. */
        if (branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK
            || bounce_game_timer_tick_entry_count(&app.game_timer) != 1u
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 1u
            || bounce_game_timer_player_physics_count(&app.game_timer) != 0u
            /* B: player, spawn, runtime, thorns, tiles, camera, counters intact. */
            || !player_equal_excluding_tick_entry(&app.player, &player_before)
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || app.player.TODO_unkX != cases[c].player_x
            || app.player.TODO_unkY != cases[c].player_y
            || app.l != l_before || app.k != k_before || app.v != v_before
            || app.l != cases[c].camera_l
            || app.k != cases[c].camera_k
            || app.v != cases[c].camera_v
            || level_digest_value(app.level) != digest_before
            /* C (discharged): was `app.lives != 0`, pinning the pre-fix
             * divergence; staged activation now mirrors the flow-owned
             * value. See verify_gameplay_activation_boundary() and
             * bounce_game_activate_staged_level(). */
            || app.lives != bounce_app_flow_entry_initial_lives(&app.flow)
            || app.hoops_scored != 0
            || app.level_complete || app.dead || app.respawn_requested
            || app.game_over
            /* C: the timer is unchanged and the legacy schedule is untouched. */
            || bounce_game_timer_period_ms(&app.game_timer) != 40
            || app.next_player_tick_ms != saved_tick
            || app.flow.next_tick_ms != 0
            /* State is preserved. */
            || app.state != BOUNCE_GAME_STATE_PLAYING
            || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || bounce_app_flow_entry_phase(&app.flow)
                != BOUNCE_GAMEPLAY_ENTRY_PHASE_TIMER_INITIALIZED
            || !app.flow.gameplay_entry.timer_started) {
            fprintf(stderr, "tick dispatch level %d: branch=%d entry=%llu"
                    " dispatch=%llu player=%llu l=%d k=%d v=%d\n",
                    cases[c].level_id, (int)branch,
                    (unsigned long long)
                        bounce_game_timer_tick_entry_count(&app.game_timer),
                    (unsigned long long)
                        bounce_game_timer_tick_dispatch_count(&app.game_timer),
                    (unsigned long long)
                        bounce_game_timer_player_physics_count(&app.game_timer),
                    app.l, app.k, app.v);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* The source decrements p at e.java:258-259 exactly once per tick. */
        if (bounce_app_flow_entry_countdown(&app.flow)
            != countdown_before - 1) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* A: one more callback adds exactly one entry and one dispatch. */
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, false, false, false, NULL, NULL, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK
            || bounce_game_timer_tick_entry_count(&app.game_timer) != 2u
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 2u
            || bounce_game_timer_player_physics_count(&app.game_timer) != 0u
            || !player_equal_excluding_tick_entry(&app.player, &player_before)
            || app.l != l_before || app.k != k_before || app.v != v_before
            || level_digest_value(app.level) != digest_before) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        thorns_after = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        if (thorns_after == NULL || thorns_before == NULL
            || thorns_after->count != thorns_before->count
            /* A level with no dynamic thorns owns a NULL record array, and
             * memcmp(NULL, NULL, 0) is undefined even for a zero length. */
            || (thorns_after->count != 0u
                && (thorns_after->records == NULL
                    || thorns_before->records == NULL
                    || memcmp(thorns_after->records, thorns_before->records,
                              (size_t)thorns_after->count
                                  * sizeof *thorns_after->records) != 0))) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        if (failures == 0) {
            printf("TICKDISPATCH level=%d branch=PLAYER_TICK entry=%llu"
                   " dispatch=%llu player_tick=0 p=%d->%d\n",
                   cases[c].level_id,
                   (unsigned long long)
                       bounce_game_timer_tick_entry_count(&app.game_timer),
                   (unsigned long long)
                       bounce_game_timer_tick_dispatch_count(&app.game_timer),
                   countdown_before,
                   bounce_app_flow_entry_countdown(&app.flow));
        }
        bounce_game_shutdown(&app);
    }

    /*
     * Early-return ordering, through the public seam only. e.java:222 and :227
     * both `return` before p--, before the camera gate, and before the dispatch,
     * so neither may touch the countdown or the dispatch counter.
     */
    {
        BounceApp app;
        BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_PLAYER_TICK;
        int countdown_before;
        /*
         * STEP 43B-R6. The camera triple observed across the e.java:262 camera
         * branch is captured live instead of being written as an absolute
         * literal. The block has always asserted one property -- the NULL body
         * does not run, so the camera cannot move -- and an invariant expresses
         * that directly, whereas a literal only restated one camera snapshot.
         *
         * The literal that used to stand here, `l == 142, k == 42, v == -9`,
         * was the camera of the SUPERSEDED pre-STEP43B constructor result
         * (1777, 545): l = (1777-64)/12 = 142, v = 142*12-1713 = -9, and k = 42
         * for y = 545. STEP 43B restored the f.java:175-206 control flow, so the
         * level-011 constructor now settles on its first fitting candidate at
         * (1710, 449) and this phase's camera is (137, 35, -2) -- already
         * asserted by equality at :10015 and by the case row at :9220. The
         * literal therefore became a stale fixture and rejected a correct
         * value.
         *
         * Capturing instead of re-stating keeps this assertion correct across any
         * future constructor or camera change, and it re-establishes exactly
         * the "l/k/v intact" property this block's comment already claimed.
         */
        int32_t l_before_camera_branch;
        int32_t k_before_camera_branch;
        int32_t v_before_camera_branch;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(&app, 10, 11) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        countdown_before = bounce_app_flow_entry_countdown(&app.flow);

        /* e.java:222 reset gate returns first, ahead of the splash gate. */
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, true, true, true, NULL, NULL, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_RESET_GATE
            || bounce_app_flow_entry_countdown(&app.flow)
                != countdown_before
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 0u
            || bounce_game_timer_player_physics_count(&app.game_timer) != 0u) {
            bounce_game_shutdown(&app);
            return -1;
        }

        /* e.java:227 splash gate returns before p-- and the camera gate. */
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, false, true, true, NULL, NULL, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_SPLASH_GATE
            || bounce_app_flow_entry_countdown(&app.flow)
                != countdown_before
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 0u) {
            bounce_game_shutdown(&app);
            return -1;
        }

        /* e.java:262 camera branch: selected, body NOT executed, l/k/v intact. */
        l_before_camera_branch = app.l;
        k_before_camera_branch = app.k;
        v_before_camera_branch = app.v;
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, false, false, true, NULL, NULL, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_CAMERA
            || bounce_app_flow_entry_countdown(&app.flow)
                != countdown_before - 1
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 0u
            /* STEP 43B-R6: the invariant, not a snapshot. */
            || app.l != l_before_camera_branch
            || app.k != k_before_camera_branch
            || app.v != v_before_camera_branch) {
            bounce_game_shutdown(&app);
            return -1;
        }

        /* NULL input is rejected; a NULL body stops after the prologue. */
        if (bounce_game_tick_dispatch(
                NULL, false, false, false, NULL, NULL, &branch) != -1
            || bounce_game_tick_dispatch(
                &app, false, false, false, NULL, NULL, NULL) != 0
            /* Even with a body, the dispatch itself still rejects NULL. */
            || bounce_game_tick_dispatch(
                NULL, false, false, false,
                app_player_physics_continuation, NULL, &branch) != -1) {
            bounce_game_shutdown(&app);
            return -1;
        }

        /*
         * D-22 -- THE af LEVEL SKIP MUST NOT CONSUME LIVES.
         *
         * This block drives the PRODUCTION consumer of the reset gate,
         * app_timer_callback_dispatch(), rather than bounce_game_tick_dispatch()
         * alone, because the reset-gate body -- the reload plus the camera --
         * lives in the former and not in the latter. That is the distinction
         * that made this divergence invisible until now: the three gate arms
         * above all pass with the reload in place.
         *
         * JAVA EVIDENCE, unchanged from the implementation site:
         *
         *   e.java:339-348   key '1' -> `this.d = true; if (this.af &&
         *                     --this.level < 1) this.level = 11;`
         *   e.java:222-226   `if (this.d) { InitializeGame(); repaint();
         *                     return; }`
         *   e.java:115-124   InitializeGame() -- which contains NO write to
         *                     `lives` at all.
         *
         * The whole tree writes `lives` in exactly four places (e.java:84,
         * e.java:95, f.java:219, f.java:611-612) and none of them is on this
         * path, so the count before the skip must equal the count after it.
         *
         * THREE VALUES ARE EXERCISED, and the choice is deliberate:
         *   2   an ordinary in-progress count;
         *   0   the boundary the 1-up (f.java:611-612) refuses to raise past,
         *       i.e. a run that has spent every life;
         *  -1   the value the death path leaves behind (f.java:219 decrements
         *       through zero to -1) and the value e.java:268 tests. It is
         *       included because Java applies no clamp, so an af skip on an
         *       exhausted run must still end at -1 and not be revived to 0 or
         *       1. A fix that clamped here would pass the first two cases and
         *       fail this one.
         *
         * The `'1'` arm is the one reproduced, because this session is on
         * level 11 and the `'1'` decrement (e.java:341) lands on level 10,
         * which is a real level; the `'3'` increment (e.java:346) from 11 would
         * produce 12, which the staged loader refuses by the FIRST..LAST guard
         * and which therefore cannot exercise the reload at all.
         *
         * The level arithmetic is transcribed from the source rather than
         * simplified: `flow.level_id` is decremented first and only then
         * wrapped, so the wrap condition is evaluated on the decremented value,
         * exactly as e.java:341-342 does.
         */
        {
            static const int af_skip_lives[] = { 2, 0, -1 };
            size_t lives_index;

            for (lives_index = 0u;
                 lives_index < sizeof af_skip_lives / sizeof af_skip_lives[0];
                 ++lives_index) {
                BounceTickDispatchBranch af_branch =
                    BOUNCE_TICK_DISPATCH_RESET_GATE;
                const int expected_lives = af_skip_lives[lives_index];
                const int level_before = app.flow.level_id;
                int level_target;

                /* e.java:340-342. */
                level_target = level_before - 1;
                if (level_target < BOUNCE_APP_FIRST_LEVEL_ID)
                    level_target = BOUNCE_APP_LAST_LEVEL_ID;

                app.lives = expected_lives;
                app.flow.level_id = level_target;
                app.af_reload_requested = true;

                if (app_timer_callback_dispatch(&app, &af_branch) != 0
                    || af_branch != BOUNCE_TICK_DISPATCH_RESET_GATE
                    /* e.java:313 clears `d` inside LoadLevelId (b.java:213);
                     * native clears the one-shot latch after the work. */
                    || app.af_reload_requested
                    /* THE ASSERTION: InitializeGame() never writes lives. */
                    || app.lives != expected_lives
                    /* The reload itself must still have happened in full. */
                    || app.flow.level_id != level_target
                    || app.level == NULL
                    || app.runtime == NULL
                    || app.level_id != level_target
                    || !app.player.initialized
                    || !app.spawn.initialized
                    /* e.java:118 HoopsScored = 0 is one of the per-level
                     * resets the reload IS responsible for, and native
                     * bounce_game_load_level performs it (game.c:367). */
                    || app.hoops_scored != 0
                    /*
                     * e.java:119 `this.p = 120;` -- the only write of `p` in
                     * the Java tree. InitializeGame() runs on the af level skip
                     * too, because e.java:340/:345 set `d` and e.java:222-226
                     * routes `d` straight into it, so the countdown is re-armed
                     * and the level banner restarts for 120 ticks.
                     *
                     * This assertion was deliberately weakened to
                     * "unchanged" when the lives fix landed, with the gap
                     * deferred to the banner work on the grounds that `p` is
                     * that banner's gate and the two halves are one feature.
                     * It is now restored to the source expectation: the banner
                     * commit arms the countdown from bounce_game_load_level(),
                     * which is the level load InitializeGame() performs.
                     */
                    || bounce_app_flow_entry_countdown(&app.flow)
                        != BOUNCE_APP_ENTRY_COUNTDOWN
                    /* e.java:222-226 returns before the physics body. */
                    || bounce_game_timer_player_physics_count(
                           &app.game_timer) != 0u) {
                    bounce_game_shutdown(&app);
                    return -1;
                }
            }
        }
        bounce_game_shutdown(&app);
    }

    /*
     * D-09 -- THE EXIT-DOOR GATE, DRIVEN THROUGH THE REAL CHAIN AND THE REAL
     * TICK, ASSERTED TICK BY TICK.
     *
     * It lives here because this is the verifier that already builds a level with
     * drive_app_to_level_loaded() plus the four staged steps and then drives the
     * canonical tick, which is the only path from which the gate is reachable.
     *
     * e.java:286-297 is the whole subject:
     *
     *     if (this.TODO_ExitUnlocked && this.z
     *             && (this.exitX + 1) * 12 > m() && this.exitX * 12 < g()) {
     *         if (this.M) {
     *             this.z = false;
     *             this.TODO_ExitUnlocked = false;
     *         } else {
     *             h();
     *         }
     *     }
     *
     * and b.h() (b.java:824-831) is `b += 4; if (b >= 24) { b = 24; M = true; }`.
     *
     * So the source's sequence is SIX ticks of +4, then a tick that CONSUMES the
     * door. Before D-09 the native gate carried a `!door_open_flag` operand, so
     * the moment the sixth tick set M the gate switched itself off and the consume
     * tick could never happen: TODO_ExitUnlocked stayed true forever.
     *
     * THE FIXTURE. TODO_ExitUnlocked is set the way the source sets it,
     * e.java:284-285 (`HoopsScored == HoopsTotal`), by driving hoops_scored to the
     * level's total rather than by writing the flag. b_z is left to the tick's own
     * producer, app_produce_b_z(), because it is a RENDER latch set as a side
     * effect of rasterising a tile-9 cell (b.java:461) and injecting it would test
     * a state the gate would never see.
     *
     * LEVEL 1 IS USED because its exit is in view at the start: the camera window
     * operand is part of the gate, and a level whose exit is off-screen would make
     * the whole assertion vacuous.
     */
    {
        BounceApp door;
        int32_t total_hoops;
        int tick;
        bool opened = false;
        bool consumed = false;
        bool one_shot = false;

        memset(&door, 0, sizeof door);
        if (bounce_game_init(&door) != 0
            || bounce_game_enter_menu(&door) != 0
            || drive_app_to_level_loaded(&door, -1, 1) != 0
            || app_advance_level_loaded_to_player_initialized(&door) != 0
            || app_advance_player_initialized_to_runtime_initialized(&door) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&door) != 0
            || app_advance_camera_initialized_to_activated(&door) != 0
            || bounce_game_initialize_game_timer(&door) != 0) {
            bounce_game_shutdown(&door);
            return -1;
        }
        /*
         * The total is read from the LEVEL rather than assumed, because
         * e.java:284-285 compares HoopsScored against the level's own HoopsTotal
         * and hard-coding it here would make the producer a different statement
         * from the source's.
         */
        total_hoops = bounce_level_hoops_total(door.level);
        if (total_hoops <= 0) {
            bounce_game_shutdown(&door);
            return -1;
        }

        /*
         * e.java:284-285, REACHED THROUGH THE REAL PRODUCER. Setting the flag
         * directly would test the gate against a state the source never produces,
         * so app_collect_hoop() is called the number of times the level needs.
         * That function IS the e.java:284-285 site -- it is where
         * `HoopsScored == HoopsTotal -> TODO_ExitUnlocked = true` lives.
         */
        door.hoops_scored = 0;
        while (door.hoops_scored < total_hoops) {
            /*
             * tile_id 13 is a real hoop half: app_hoop_pair_for_tile() maps it to
             * tiles 17/18 and returns true, which is what makes this function
             * score the hoop and reach HoopsScored. Any other id returns 0 early
             * without incrementing, so passing one here would loop forever --
             * the argument is a real producer input, not a formality.
             *
             * (1,1) is in range for every level, and the tile the call writes
             * there is irrelevant: the gate under test reads only the exit cell
             * and the camera window.
             */
            if (app_collect_hoop(&door, 1, 1, 13u, 0u) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
        }
        if (!door.TODO_ExitUnlocked
            || door.door_open_flag
            || door.door_image_offset != 0) {
            bounce_game_shutdown(&door);
            return -1;
        }

        /*
         * PUT THE EXIT IN VIEW, BECAUSE THE CAMERA OPERAND IS PART OF THE GATE.
         *
         * e.java:286 tests `(exitX + 1) * 12 > m() && exitX * 12 < g()`, where m()
         * and g() are the camera window's left and right edges (b.java:663-669).
         * Native reproduces both, and the ball starts in the middle of a 112-wide
         * level, so the exit can be off-screen and the whole assertion vacuous.
         *
         * The player is MOVED rather than the camera written, because
         * app_update_camera_*() recomputes l, k and v from the ball every tick and
         * would overwrite a direct write on the next frame. Moving the ball is
         * also the honest way to put the door on screen: it is what happens in
         * play.
         */
        {
            int32_t exit_col = (int32_t)bounce_level_exit_x(door.level);
            if (exit_col <= 0
                || exit_col >= (int32_t)bounce_runtime_level_tiles_width(
                        door.runtime)) {
                bounce_game_shutdown(&door);
                return -1;
            }
            door.player.TODO_unkX = exit_col * BOUNCE_TILE_SIZE + 6;
        }

        /*
         * SIX TICKS OPEN THE DOOR, THE SEVENTH CONSUMES IT. The bound is generous
         * on purpose: what is asserted is that the offset reached 24 with
         * TODO_ExitUnlocked STILL SET, which can only happen if the clear branch
         * did not run on the opening tick -- the exact bug D-09 describes.
         */
        for (tick = 0; tick < 12 && !consumed; ++tick) {
            BounceTickDispatchBranch door_branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
            if (app_timer_callback_dispatch(&door, &door_branch) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
            if (door.door_open_flag && !opened) {
                opened = true;
                /* The opening tick must NOT have consumed it. */
                if (door.TODO_ExitUnlocked
                    && door.b_z
                    && door.door_image_offset == 24) {
                    continue;
                }
                bounce_game_shutdown(&door);
                return -1;
            }
            if (opened) {
                /* e.java:289-290, on a LATER tick than the one that set M. */
                consumed = !door.TODO_ExitUnlocked && !door.b_z;
            }
        }
        one_shot = opened && consumed;

        /*
         * AND IT STAYS CONSUMED: a few more ticks must not re-arm the door, which
         * is what a gate that could still fire would do.
         */
        for (tick = 0; tick < 3; ++tick) {
            BounceTickDispatchBranch door_branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
            if (app_timer_callback_dispatch(&door, &door_branch) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
        }
        if (door.TODO_ExitUnlocked || door.b_z || !door.door_open_flag) {
            bounce_game_shutdown(&door);
            return -1;
        }
        bounce_game_shutdown(&door);
        if (!one_shot) {
            fprintf(stderr,
                    "door gate: opened=%d consumed=%d\n",
                    (int)opened, (int)consumed);
            return -1;
        }
        printf("DOOR-GATE e.java:286-297 animation=6x+4 then_M"
               " consume_tick=clears_z_and_unlock one_shot=yes PASS\n");
    }

    if (failures != 0)
        fprintf(stderr, "tick dispatch seam: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * f.b() pre-physics entry verification (f.java:652-669, stopping before :670).
 *
 * For Levels 001 and 011 this snapshots the player, the runtime LevelTiles, the
 * dynamic-thorn w/ae state, the camera l/k/v, and the gameplay counters, then
 * executes exactly ONE timer callback through the dispatch path and proves that
 * nothing changed except the f.b() frame record and the two boundary counters.
 *
 * It also asserts the f.b() prologue values themselves, so the transcribed Java
 * semantics are checked rather than assumed.
 */
static int verify_player_tick_entry_boundary(void)
{
    static const struct {
        int level_id;
        int list_index;
        int32_t player_x;
        int32_t player_y;
        int32_t camera_l;
        int32_t camera_k;
        int32_t camera_v;
        int32_t expect_tile_x;
        int32_t expect_tile_y;
        bool expect_in_water;
        int32_t expect_ball_size;
        /*
         * The A1 contact state this block observes, which is the state AFTER one
         * gameplay tick, not the constructor output.
         *
         * STEP 43B-R4: this comment previously read "a big-ball level runs the
         * probe, which writes u and v from inside the search
         * (f.java:437/:440/:444/:448/:452/:454/:460), so both are true for level
         * 011". That was wrong twice. It attributed the latches to the
         * constructor's walk when this block asserts a post-tick state, and it
         * assumed a multi-tile sweep. Under f.java:175-206 the walk performs ONE
         * probe and stops on the first fitting candidate, so the constructor
         * never reaches the f.a() arms that raise u (f.java:437) or v
         * (f.java:444).
         *
         * Both are false on both rows now: level 001 because a regular ball
         * never enters UseBigBall() (f.java:127-128), level 011 because its
         * single probe at f.java:177's candidate (1710, 449) touches no brick,
         * rubber or slope tile.
         */
        bool expect_u;
        bool expect_v;
    } cases[] = {
        /* 001: (30,18) -> tile (2,1); LevelTiles[1][2] has no 0x40 water bit. */
        {  1, -1,   30,  18,   0,  0,   0, 2, 1, false, 12, false, false },
        /* 011: (1710,449) -> tile (142,37) by truncation toward zero. STEP 43B-R2:
         * the f.java:175-206 constructor walk ends on its first fitting
         * candidate, so the ball stays 16/8 and no f.java:618-621 deflate fires.
         *
         * STEP 43B-R4: expect_u and expect_v become FALSE here. The previous
         * true/true was inherited from the pre-STEP43B loop, which swept many
         * candidates and therefore crossed brick (f.java:437) and rubber
         * (f.java:444) tiles and raised both latches. Under the corrected
         * control flow the constructor walk runs ONE probe -- f.java:177's
         * candidate (1710, 449) -- and that window contains no brick, no rubber
         * wall and no slope, so u and v stay at the constructor zeros of
         * f.java:117-118. The first gameplay tick leaves them false as well,
         * which is what this post-entry block observes. Level 001 is unchanged
         * and stays false/false, for the different reason that a regular ball
         * never enters UseBigBall() at all (f.java:127-128). */
        { 11, 10, 1710, 449, 137, 35,  -2, 142, 37, false, 16, false, false }
    };
    size_t c;
    int failures = 0;

    for (c = 0; c < sizeof cases / sizeof cases[0]; ++c) {
        BounceApp app;
        BouncePlayer player_before;
        BouncePlayerSpawn spawn_before;
        const BounceDynThorns *thorns_before;
        const BounceDynThorns *thorns_after;
        BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
        unsigned long digest_before;
        int countdown_before;
        int64_t saved_tick;
        int32_t l_before;
        int32_t k_before;
        int32_t v_before;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                &app, cases[c].list_index, cases[c].level_id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        player_before = app.player;
        spawn_before = app.spawn;
        thorns_before = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        digest_before = level_digest_value(app.level);
        countdown_before = bounce_app_flow_entry_countdown(&app.flow);
        saved_tick = app.next_player_tick_ms;
        l_before = app.l;
        k_before = app.k;
        v_before = app.v;

        /* No entry has happened yet. */
        if (app.player.tick_entry.entered
            || bounce_game_timer_player_tick_entry_count(&app.game_timer) != 0u
            || bounce_game_timer_player_physics_count(&app.game_timer) != 0u) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /*
         * Exactly one timer callback through the dispatch path, with a NULL
         * body so the f.b() prologue is the last thing executed. The physics
         * continuation is verified by verify_player_physics_continuation().
         */
        if (bounce_game_timer_callback(&app.game_timer) != 0
            || bounce_game_tick_dispatch(
                &app, false, false, false, NULL, NULL, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK
            || bounce_game_timer_tick_entry_count(&app.game_timer) != 1u
            || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 1u
            || bounce_game_timer_player_tick_entry_count(&app.game_timer) != 1u
            /* PLAYER PHYSICS COUNT MUST REMAIN ZERO. */
            || bounce_game_timer_player_physics_count(&app.game_timer) != 0u) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* f.java:653-669 prologue values. */
        if (!app.player.tick_entry.entered
            || app.player.tick_entry.z2_early_return
            || app.player.tick_entry.i != cases[c].player_x
            || app.player.tick_entry.j != 0
            || app.player.tick_entry.k != 0
            || app.player.tick_entry.b1 != 0
            || app.player.tick_entry.bool1
            || app.player.tick_entry.tileX != cases[c].expect_tile_x
            || app.player.tick_entry.tileY != cases[c].expect_tile_y
            || app.player.tick_entry.is_in_water != cases[c].expect_in_water) {
            fprintf(stderr, "f.b() entry level %d: i=%d j=%d k=%d b1=%d"
                    " bool1=%d tile=(%d,%d) water=%d z2=%d\n",
                    cases[c].level_id, app.player.tick_entry.i,
                    app.player.tick_entry.j, app.player.tick_entry.k,
                    (int)app.player.tick_entry.b1,
                    (int)app.player.tick_entry.bool1,
                    app.player.tick_entry.tileX, app.player.tick_entry.tileY,
                    (int)app.player.tick_entry.is_in_water,
                    (int)app.player.tick_entry.z2_early_return);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        /* No physics field changed; only the f.b() frame record was filled. */
        if (!player_equal_excluding_tick_entry(&app.player, &player_before)
            || app.player.TODO_unkX != cases[c].player_x
            || app.player.TODO_unkY != cases[c].player_y
            || app.player.ballSize != cases[c].expect_ball_size
            || app.player.horizontal_velocity != 0
            || app.player.o != 0
            || app.player.t != 0
            || app.player.C != 0
            || app.player.z != 0
            || app.player.q != 0
            || app.player.m
            || app.player.u != cases[c].expect_u
            || app.player.v != cases[c].expect_v
            || app.player.powerUpGravity != 0
            || app.player.TODO_somePowerUp3 != 0
            || memcmp(&app.spawn, &spawn_before, sizeof app.spawn) != 0
            || app.l != l_before || app.k != k_before || app.v != v_before
            || app.l != cases[c].camera_l
            || app.k != cases[c].camera_k
            || app.v != cases[c].camera_v
            || level_digest_value(app.level) != digest_before
            /* C (discharged): was `app.lives != 0`, pinning the pre-fix
             * divergence; staged activation now mirrors the flow-owned
             * value. See verify_gameplay_activation_boundary() and
             * bounce_game_activate_staged_level(). */
            || app.lives != bounce_app_flow_entry_initial_lives(&app.flow)
            || app.hoops_scored != 0
            || app.level_complete || app.dead || app.respawn_requested
            || app.game_over
            || bounce_app_flow_entry_countdown(&app.flow)
                != countdown_before - 1
            || app.state != BOUNCE_GAME_STATE_PLAYING
            || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || bounce_game_timer_period_ms(&app.game_timer) != 40
            || app.next_player_tick_ms != saved_tick) {
            fprintf(stderr, "post-entry level %d: o=%d t=%d l=%d C=%d"
                    " z=%d q=%d player=(%d,%d) cam=(%d,%d,%d)\n",
                    cases[c].level_id, app.player.o, app.player.t,
                    app.player.horizontal_velocity, app.player.C,
                    app.player.z, app.player.q,
                    app.player.TODO_unkX, app.player.TODO_unkY,
                    app.l, app.k, app.v);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        thorns_after = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        if (thorns_after == NULL || thorns_before == NULL
            || thorns_after->count != thorns_before->count
            || (thorns_after->count != 0u
                && (thorns_after->records == NULL
                    || thorns_before->records == NULL
                    || memcmp(thorns_after->records, thorns_before->records,
                              (size_t)thorns_after->count
                                  * sizeof *thorns_after->records) != 0))) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        if (failures == 0) {
            printf("FBENTRY level=%d i=%d tile=(%d,%d) water=%d"
                   " tick_entry=1 player_tick_entry=%llu player_physics=%llu"
                   " o=0 l=0 C=0\n",
                   cases[c].level_id, app.player.tick_entry.i,
                   app.player.tick_entry.tileX, app.player.tick_entry.tileY,
                   (int)app.player.tick_entry.is_in_water,
                   (unsigned long long)bounce_game_timer_player_tick_entry_count(
                       &app.game_timer),
                   (unsigned long long)bounce_game_timer_player_physics_count(
                       &app.game_timer));
        }
        bounce_game_shutdown(&app);
    }

    /*
     * The z == 2 early return (f.java:658-666) is the only branch reachable
     * before the stop point that changes what is computed. It is exercised
     * through the public player entry with the branch's own side effects
     * deliberately suppressed.
     */
    {
        BouncePlayer player;
        BouncePlayerSpawn spawn;
        BounceRuntimeLevelTiles *runtime = NULL;
        BounceLevel *level = NULL;
        BouncePlayerTickEntry entry;
        int32_t q_before;

        memset(&player, 0, sizeof player);
        memset(&spawn, 0, sizeof spawn);
        if (bounce_level_load_file(BOUNCE_LEVEL001_PATH, &level)
                != BOUNCE_LEVEL_LOAD_OK
            || level == NULL)
            return -1;
        runtime = bounce_runtime_level_tiles_create(level);
        if (runtime == NULL
            || bounce_player_initialize_from_level(level, &player, &spawn) != 0) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        /* Normal path reaches the tile coordinates and the water sample. */
        player.z = 0;
        if (bounce_player_tick_entry(&player, runtime, &entry) != 0
            || !entry.entered || entry.z2_early_return
            || entry.i != player.TODO_unkX
            || entry.tileX != player.TODO_unkX / 12
            || entry.tileY != player.TODO_unkY / 12) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        /* f.java:658: z == 2 returns before :667, so no tile coordinates. */
        player.z = 2;
        q_before = player.q;
        if (bounce_player_tick_entry(&player, runtime, &entry) != 0
            || !entry.entered || !entry.z2_early_return
            || entry.i != player.TODO_unkX
            || entry.tileX != 0 || entry.tileY != 0
            /* The branch's own side effects are NOT performed. */
            || player.q != q_before
            || player.z != 2) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        /*
         * f.java:667-668 division truncates TOWARD ZERO, not toward -infinity.
         * A world X of -7 maps to tile 0 (truncation) and not to tile -1 (floor),
         * and tile 0 is in range so the water sample still runs.
         */
        player.z = 0;
        player.TODO_unkX = -7;
        player.TODO_unkY = 18;
        if (bounce_player_tick_entry(&player, runtime, &entry) != 0
            || entry.tileX != 0 || entry.tileY != 1) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        /*
         * NATIVE BOUNDARY: the source would raise an uncaught
         * ArrayIndexOutOfBoundsException for an out-of-range tile, so the native
         * entry rejects it instead. TODO_unkY = -13 truncates to tile -1.
         */
        player.TODO_unkX = 30;
        player.TODO_unkY = -13;
        if (bounce_player_tick_entry(&player, runtime, &entry) != -1
            || entry.entered) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        /* NULL and uninitialized inputs are rejected. */
        if (bounce_player_tick_entry(NULL, runtime, &entry) != -1
            || bounce_player_tick_entry(&player, NULL, &entry) != -1
            || bounce_player_tick_entry(&player, runtime, NULL) != -1) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }

        bounce_runtime_level_tiles_destroy(runtime);
        bounce_level_destroy(level);
    }

    if (failures != 0)
        fprintf(stderr, "f.b() entry seam: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Thin physics-continuation verification.
 *
 * Proves, on Level 001, that ONE new-timer callback now runs the EXISTING native
 * physics (app_step_vertical -> app_step_horizontal ->
 * app_update_camera_horizontal) and that it reaches the SAME result as the
 * previously working app_update_game() -> app_run_player_ticks() path under
 * equivalent input and state.
 *
 * Level 011 is included to document the existing big-ball limitation:
 * app_step_vertical() rejects ballSize != 12 (vertical_slice.c:1760), so the
 * continuation returns -1 there and no physics runs.
 */
static int verify_player_physics_continuation(void)
{
    BounceApp old_path;
    BounceApp new_path;
    BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
    int failures = 0;
    VerticalDiagnostic big_vertical_diagnostic;

    memset(&old_path, 0, sizeof old_path);
    memset(&new_path, 0, sizeof new_path);

    /* OLD, previously working path: legacy load + app_update_game(). */
    if (bounce_game_init(&old_path) != 0
        || bounce_game_enter_menu(&old_path) != 0
        || bounce_game_start_level(
            &old_path, BOUNCE_LEVEL001_PATH, 0, 3) != 0
        || bounce_input_apply_source(
            &old_path.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0)
        return -1;

    /* NEW canonical path: staged lifecycle + new 40 ms timer callback. */
    if (bounce_game_init(&new_path) != 0
        || bounce_game_enter_menu(&new_path) != 0
        || drive_app_to_level_loaded(&new_path, -1, 1) != 0
        || app_advance_level_loaded_to_player_initialized(&new_path) != 0
        || app_advance_player_initialized_to_runtime_initialized(&new_path) != 0
        || app_advance_runtime_initialized_to_camera_initialized(&new_path) != 0
        || app_advance_camera_initialized_to_activated(&new_path) != 0
        || bounce_game_initialize_game_timer(&new_path) != 0
        /* Same real input the existing verified test uses. */
        || bounce_input_apply_source(
            &new_path.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0) {
        bounce_game_shutdown(&old_path);
        bounce_game_shutdown(&new_path);
        return -1;
    }

    /* Equivalent starting state for both paths. */
    if (old_path.player.TODO_unkX != new_path.player.TODO_unkX
        || old_path.player.TODO_unkY != new_path.player.TODO_unkY
        || old_path.player.ballSize != new_path.player.ballSize
        || old_path.l != new_path.l
        || old_path.k != new_path.k
        || old_path.v != new_path.v
        || bounce_game_timer_tick_entry_count(&new_path.game_timer) != 0u
        || bounce_game_timer_player_tick_entry_count(&new_path.game_timer) != 0u
        || bounce_game_timer_player_physics_count(&new_path.game_timer) != 0u) {
        bounce_game_shutdown(&old_path);
        bounce_game_shutdown(&new_path);
        return -1;
    }

    printf("PHYSICS level=1 BEFORE old=(%d,%d) new=(%d,%d) l=%d k=%d v=%d\n",
           old_path.player.TODO_unkX, old_path.player.TODO_unkY,
           new_path.player.TODO_unkX, new_path.player.TODO_unkY,
           new_path.l, new_path.k, new_path.v);

    /* OLD: exactly one tick through the legacy scheduler. */
    old_path.next_player_tick_ms = 0;
    if (app_update_game(&old_path) != 0) {
        bounce_game_shutdown(&old_path);
        bounce_game_shutdown(&new_path);
        return -1;
    }

    /* NEW: exactly one new-timer callback with the physics continuation. */
    if (app_timer_callback_dispatch(&new_path, &branch) != 0
        || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK
        || bounce_game_timer_tick_entry_count(&new_path.game_timer) != 1u
        || bounce_game_timer_tick_dispatch_count(&new_path.game_timer) != 1u
        || bounce_game_timer_player_tick_entry_count(&new_path.game_timer) != 1u
        || bounce_game_timer_player_physics_count(&new_path.game_timer) != 1u) {
        fprintf(stderr, "physics continuation: branch=%d entry=%llu"
                " tick_entry=%llu physics=%llu\n", (int)branch,
                (unsigned long long)bounce_game_timer_tick_entry_count(
                    &new_path.game_timer),
                (unsigned long long)
                    bounce_game_timer_player_tick_entry_count(
                        &new_path.game_timer),
                (unsigned long long)bounce_game_timer_player_physics_count(
                    &new_path.game_timer));
        bounce_game_shutdown(&old_path);
        bounce_game_shutdown(&new_path);
        return -1;
    }

    printf("PHYSICS level=1 AFTER  old=(%d,%d) new=(%d,%d) l=%d k=%d v=%d\n",
           old_path.player.TODO_unkX, old_path.player.TODO_unkY,
           new_path.player.TODO_unkX, new_path.player.TODO_unkY,
           new_path.l, new_path.k, new_path.v);

    /*
     * The existing physics must have run. This asserts exactly what the already
     * verified verify_gameplay_dispatch() establishes: horizontal velocity
     * increased from 0 and the f.b() C cycle advanced. It deliberately does NOT
     * require a position change, because the existing test does not either: the
     * ball starts at the level's left edge and the first sub-step can be
     * collision-blocked while the velocity still builds.
     */
    if (new_path.player.horizontal_velocity <= 0 || new_path.player.C == 0) {
        fprintf(stderr, "physics continuation: physics did not run x=%d hv=%d"
                " C=%d o=%d\n", new_path.player.TODO_unkX,
                new_path.player.horizontal_velocity, new_path.player.C,
                new_path.player.o);
        failures++;
    }

    /*
     * OLD vs NEW must be identical: same existing implementation, equivalent
     * input and state. Any difference is a call-order or state divergence and is
     * reported rather than forced.
     */
    if (old_path.player.TODO_unkX != new_path.player.TODO_unkX
        || old_path.player.TODO_unkY != new_path.player.TODO_unkY
        || old_path.player.horizontal_velocity
            != new_path.player.horizontal_velocity
        || old_path.player.o != new_path.player.o
        || old_path.player.C != new_path.player.C
        || old_path.player.t != new_path.player.t
        || old_path.player.q != new_path.player.q
        || old_path.player.z != new_path.player.z
        || old_path.player.m != new_path.player.m
        || old_path.player.u != new_path.player.u
        || old_path.player.powerUpGravity != new_path.player.powerUpGravity
        || old_path.player.TODO_somePowerUp3 != new_path.player.TODO_somePowerUp3
        || old_path.l != new_path.l
        || old_path.k != new_path.k
        || old_path.v != new_path.v
        || level_digest_value(old_path.level)
            != level_digest_value(new_path.level)) {
        fprintf(stderr, "old vs new DIVERGED: old x=%d y=%d hv=%d o=%d C=%d"
                " | new x=%d y=%d hv=%d o=%d C=%d\n",
                old_path.player.TODO_unkX, old_path.player.TODO_unkY,
                old_path.player.horizontal_velocity, old_path.player.o,
                old_path.player.C, new_path.player.TODO_unkX,
                new_path.player.TODO_unkY,
                new_path.player.horizontal_velocity, new_path.player.o,
                new_path.player.C);
        failures++;
    } else {
        printf("PHYSICS level=1 old-vs-new IDENTICAL x=%d y=%d hv=%d o=%d"
               " C=%d t=%d u=%d cam=(%d,%d,%d)\n",
               new_path.player.TODO_unkX, new_path.player.TODO_unkY,
               new_path.player.horizontal_velocity, new_path.player.o,
               new_path.player.C, new_path.player.t, (int)new_path.player.u,
               new_path.l, new_path.k, new_path.v);
    }

    /* The legacy path must still schedule its own catch-up loop. */
    if (old_path.next_player_tick_ms <= 0)
        failures++;
    /* The new path must NOT touch the legacy deadline. */
    if (new_path.next_player_tick_ms != INT64_C(4321))
        failures++;
    /* No dyn-thorn update on the new path. */
    if (bounce_runtime_level_tiles_dyn_thorns(new_path.runtime) == NULL)
        failures++;

    bounce_game_shutdown(&old_path);
    bounce_game_shutdown(&new_path);

    /* Level 011: big-ball gravity, verified against the source table. */
    {
        BounceApp big;
        memset(&big, 0, sizeof big);
        memset(&big_vertical_diagnostic, 0, sizeof big_vertical_diagnostic);
        big_vertical_diagnostic.enabled = true;
        if (bounce_game_init(&big) != 0
            || bounce_game_enter_menu(&big) != 0
            || drive_app_to_level_loaded(&big, 10, 11) != 0
            || app_advance_level_loaded_to_player_initialized(&big) != 0
            || app_advance_player_initialized_to_runtime_initialized(&big) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&big) != 0
            || app_advance_camera_initialized_to_activated(&big) != 0
            || bounce_game_initialize_game_timer(&big) != 0) {
            bounce_game_shutdown(&big);
            return -1;
        }
        /* STEP 43B-R2: the constructor leaves level 011's ball big. The probe at
         * f.java:130 walks f.java:175-206, whose first candidate (1710, 449)
         * fits, so the walk ends after one probe and never reaches a 39-42
         * deflater tile; f.java:618-621 UseRegularBall() is therefore not
         * entered and the ball is 16/8 before the first tick. */
        if (big.player.TODO_unkX != 1710 || big.player.TODO_unkY != 449
            || big.player.ballSize != BOUNCE_BIG_BALL_SIZE
            || big.player.p != BOUNCE_BIG_BALL_P
            || big.l != 137 || big.k != 35 || big.v != -2) {
            bounce_game_shutdown(&big);
            return -1;
        }
        /*
         * STEP 14.1a: gravity is no longer refused, so this block no longer
         * asserts the old limitation. It asserts something stronger instead, and
         * the change is deliberate rather than a weakened test:
         *
         *   was: physics did NOT run, and the position was left untouched
         *   now: physics runs exactly once, and the gravity pair it selected is
         *        the exact verified f.java:670-686 row for the water state and
         *        ball size that were actually sampled
         *
         * The old "TODO_unkY == 547" claim is gone for two independent reasons:
         * integrating gravity legitimately moves the ball, and the
         * f.java:175-206 constructor walk now ends on its first fitting
         * candidate, leaving the settled position at 449 with the ball still
         * 16/8 before any tick runs.
         *
         * The expected pair is therefore selected from the ball's real size
         * rather than hard-coded to the big rows, which is a faithful encoding of
         * f.java:670-686 rather than a relaxation of it: all four rows are still
         * checked, and the two big rows are still covered for a genuinely big
         * ball by verify_big_ball_substep, which injects ballSize directly.
         */
        big.vertical_diagnostic = &big_vertical_diagnostic;
        if (app_timer_callback_dispatch(&big, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK)
            failures++;
        if (bounce_game_timer_player_tick_entry_count(&big.game_timer) != 1u
            || bounce_game_timer_player_physics_count(&big.game_timer) != 1u
            || big.vertical_diagnostic == NULL
            /* f.java:670-686, selected by the water bit and the ball's real size. */
            || (big.vertical_diagnostic->is_in_water
                ? (big.player.ballSize == BOUNCE_BIG_BALL_SIZE
                    ? (big.vertical_diagnostic->gravity_k
                            != BOUNCE_BIG_WATER_GRAVITY_K
                        || big.vertical_diagnostic->gravity_j
                            != BOUNCE_BIG_WATER_GRAVITY_J)
                    : (big.vertical_diagnostic->gravity_k
                            != BOUNCE_REGULAR_WATER_GRAVITY_K
                        || big.vertical_diagnostic->gravity_j
                            != BOUNCE_REGULAR_WATER_GRAVITY_J))
                : (big.player.ballSize == BOUNCE_BIG_BALL_SIZE
                    ? (big.vertical_diagnostic->gravity_k
                            != BOUNCE_BIG_GRAVITY_K
                        || big.vertical_diagnostic->gravity_j
                            != BOUNCE_BIG_GRAVITY_J)
                    : (big.vertical_diagnostic->gravity_k
                            != BOUNCE_REGULAR_GRAVITY_K
                        || big.vertical_diagnostic->gravity_j
                            != BOUNCE_REGULAR_GRAVITY_J)))
            /* STEP 43B-R6: the camera of the Java-faithful (1710, 449)
             * constructor, already asserted by equality at the top of this very
             * block: l = (1710-64)/12 = 137, v = 137*12-1646 = -2, and k = 35
             * for y = 449. The 142 / 42 / -9 that stood here was the camera of
             * the superseded pre-STEP43B (1777, 545) result. */
            || big.l != 137 || big.k != 35 || big.v != -2) {
            bounce_game_shutdown(&big);
            return -1;
        }
        printf("PHYSICS level=11 big-ball gravity active: entry=1 physics=1"
               " water=%d k=%d j=%d player=(%d,%d) cam=(%d,%d,%d)\n",
               big.vertical_diagnostic->is_in_water ? 1 : 0,
               big.vertical_diagnostic->gravity_k,
               big.vertical_diagnostic->gravity_j,
               big.player.TODO_unkX, big.player.TODO_unkY,
               big.l, big.k, big.v);
        bounce_game_shutdown(&big);
    }

    if (failures != 0)
        fprintf(stderr, "physics continuation: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Render hand-off verification.
 *
 * Establishes: one new timer-driven gameplay update followed by the EXISTING
 * render boundary produces the same frame as the legacy
 * app_update_game() -> render_app_state() path, and that the renderer consumed
 * exactly the state the new physics path produced.
 *
 * Double-update prevention: the two paths run on two separate BounceApp
 * instances, each ticking exactly once, so no frame is ever updated twice and
 * the legacy production loop is never involved.
 *
 * FAILURE ACCOUNTING. Every check in this function now increments `failures`
 * before it leaves, whether it bails out immediately or falls through to the
 * end. Previously several checks -- the legacy tick/render, the new-path timer
 * callback, the single-physics-tick assertion, the legacy-deadline assertion and
 * both surface allocations -- jumped straight to `cleanup:` without counting,
 * and because `cleanup:` returns `failures == 0 ? 0 : -1`, each of them turned a
 * genuine failure into a reported PASS. That is how this verifier came to return
 * 0 while none of assertions A to E had ever run. The assertions themselves are
 * unchanged and no check was removed or relaxed: the only difference is that a
 * check which fails is now counted, so the verifier reports honestly.
 */
static unsigned long surface_digest(const BounceSurface *surface)
{
    unsigned long digest = 1469598103934665603UL;
    int w = (int)bounce_surface_width(surface);
    int h = (int)bounce_surface_height(surface);
    int x;
    int y;

    for (y = 0; y < h; ++y) {
        for (x = 0; x < w; ++x) {
            uint32_t pixel = 0u;
            if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0)
                return 0UL;
            digest ^= (unsigned long)pixel;
            digest *= 1099511628211UL;
        }
    }
    return digest;
}

static int verify_render_continuation(void)
{
    BounceApp old_path;
    BounceApp new_path;
    BounceSurface *old_surface = NULL;
    BounceSurface *new_surface = NULL;
    BounceRenderer *old_renderer = NULL;
    BounceRenderer *new_renderer = NULL;
    RenderTrace old_trace;
    RenderTrace new_trace;
    BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
    unsigned long old_digest;
    unsigned long new_digest;
    int32_t ball_screen_x;
    int32_t ball_screen_y;
    uint32_t ball_pixel = 0u;
    uint32_t background_pixel = 0u;
    int failures = 0;

    memset(&old_path, 0, sizeof old_path);
    memset(&new_path, 0, sizeof new_path);
    memset(&old_trace, 0, sizeof old_trace);
    memset(&new_trace, 0, sizeof new_trace);
    old_trace.enabled = true;
    new_trace.enabled = true;

    /* OLD: legacy load, one legacy tick, then the existing render boundary. */
    if (bounce_game_init(&old_path) != 0
        || bounce_game_enter_menu(&old_path) != 0
        || bounce_game_start_level(
            &old_path, BOUNCE_LEVEL001_PATH, 0, 3) != 0
        || bounce_input_apply_source(
            &old_path.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0)
        return -1;
    old_path.render_trace = &old_trace;
    old_surface = bounce_surface_create();
    old_renderer = bounce_renderer_create(old_surface);
    if (old_surface == NULL || old_renderer == NULL) {
        failures++;
        goto cleanup;
    }
    old_path.next_player_tick_ms = 0;
    if (app_update_game(&old_path) != 0
        || render_app_state(old_surface, old_renderer, &old_path) != 0) {
        failures++;
        goto cleanup;
    }

    /* NEW: staged lifecycle, one new timer callback, then the same boundary. */
    if (bounce_game_init(&new_path) != 0
        || bounce_game_enter_menu(&new_path) != 0
        || drive_app_to_level_loaded(&new_path, -1, 1) != 0
        || app_advance_level_loaded_to_player_initialized(&new_path) != 0
        || app_advance_player_initialized_to_runtime_initialized(&new_path) != 0
        || app_advance_runtime_initialized_to_camera_initialized(&new_path) != 0
        || app_advance_camera_initialized_to_activated(&new_path) != 0
        || bounce_game_initialize_game_timer(&new_path) != 0
        || bounce_input_apply_source(
            &new_path.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0) {
        failures++;
        goto cleanup;
    }
    new_path.render_trace = &new_trace;
    new_surface = bounce_surface_create();
    new_renderer = bounce_renderer_create(new_surface);
    if (new_surface == NULL || new_renderer == NULL) {
        failures++;
        goto cleanup;
    }
    if (app_timer_callback_render(
            new_surface, new_renderer, &new_path, &branch) != 0
        || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK) {
        failures++;
        goto cleanup;
    }

    /* A. Exactly one physics tick on the new path: no double update. */
    if (bounce_game_timer_tick_entry_count(&new_path.game_timer) != 1u
        || bounce_game_timer_player_tick_entry_count(&new_path.game_timer) != 1u
        || bounce_game_timer_player_physics_count(&new_path.game_timer) != 1u) {
        failures++;
        goto cleanup;
    }
    /* The legacy scheduler was not used and its deadline is untouched. */
    if (new_path.next_player_tick_ms != INT64_C(4321)) {
        failures++;
        goto cleanup;
    }

    /* B. The renderer consumed the state the new physics produced. */
    if (new_trace.frame_id != 1u || !new_trace.stage_seen || !new_trace.ball_seen
        || new_trace.player_x != new_path.player.TODO_unkX
        || new_trace.player_y != new_path.player.TODO_unkY
        || new_trace.camera_l != new_path.l
        || new_trace.camera_k != new_path.k
        || new_trace.camera_v != new_path.v
        || new_trace.ball_actual_x != new_trace.ball_expected_x
        || new_trace.ball_actual_y != new_trace.ball_expected_y) {
        fprintf(stderr, "render trace: frame=%u stage=%d ball=%d px=(%d,%d)"
                " cam=(%d,%d,%d) app=(%d,%d)\n", new_trace.frame_id,
                (int)new_trace.stage_seen, (int)new_trace.ball_seen,
                new_trace.ball_actual_x, new_trace.ball_actual_y,
                new_trace.camera_l, new_trace.camera_k, new_trace.camera_v,
                new_path.player.TODO_unkX, new_path.player.TODO_unkY);
        failures++;
    }

    /* C. Logical surface and gameplay viewport. */
    if (bounce_surface_width(new_surface) != 128u
        || bounce_surface_height(new_surface) != 128u
        || old_trace.frame_id != 1u)
        failures++;

    /* D. The ball really is painted from the current player position. */
    if (app_world_to_screen(
            &new_path,
            new_path.player.TODO_unkX,
            new_path.player.TODO_unkY,
            &ball_screen_x,
            &ball_screen_y
        ) != 0) {
        failures++;
        goto cleanup;
    }
    if (bounce_surface_get_pixel(
            new_surface, ball_screen_x, ball_screen_y, &ball_pixel) != 0
        || bounce_surface_get_pixel(
            new_surface, 0, 0, &background_pixel) != 0
        || ball_pixel == background_pixel
        || ball_pixel != COLOR_BALL) {
        fprintf(stderr, "ball pixel at (%d,%d) = %08lx, background %08lx\n",
                ball_screen_x, ball_screen_y, (unsigned long)ball_pixel,
                (unsigned long)background_pixel);
        failures++;
    }

    /* E. OLD vs NEW frame comparison. */
    old_digest = surface_digest(old_surface);
    new_digest = surface_digest(new_surface);
    if (old_digest != new_digest
        || old_path.player.TODO_unkX != new_path.player.TODO_unkX
        || old_path.player.TODO_unkY != new_path.player.TODO_unkY
        || old_path.l != new_path.l || old_path.k != new_path.k
        || old_path.v != new_path.v
        || old_trace.player_x != new_trace.player_x
        || old_trace.player_y != new_trace.player_y
        || old_trace.stage_actual_x != new_trace.stage_actual_x
        || old_trace.stage_actual_y != new_trace.stage_actual_y
        || old_trace.ball_actual_x != new_trace.ball_actual_x
        || old_trace.ball_actual_y != new_trace.ball_actual_y) {
        fprintf(stderr, "old vs new frame DIVERGED: digest %lx/%lx"
                " ball=(%d,%d)/(%d,%d)\n", old_digest, new_digest,
                old_trace.ball_actual_x, old_trace.ball_actual_y,
                new_trace.ball_actual_x, new_trace.ball_actual_y);
        failures++;
    } else {
        printf("RENDER level=1 old-vs-new frame IDENTICAL digest=%016lx"
               " ball=(%d,%d) cam=(%d,%d,%d) surface=128x128\n",
               new_digest, new_trace.ball_actual_x, new_trace.ball_actual_y,
               new_path.l, new_path.k, new_path.v);
    }

    /*
     * F. D-13 / J-01 -- THE LEVEL BANNER, asserted both present and absent.
     *
     * e.java:201-205:
     *
     *     if (this.p != 0) {
     *         this.X.setColor(0xfffffe);
     *         this.X.setFont(this.font);
     *         this.X.drawString(this.LevelString, 44, 84, 20);
     *     }
     *
     * so the ONLY gate is `p != 0` and the pixels appear at (44, 84) in
     * 0xfffffe. The check is a two-render comparison of the SAME scene rather
     * than a hard-coded digest, so it stays true across any future change to
     * the level, the camera or the ball:
     *
     *   1. with the countdown armed, pixels of exactly the banner colour must
     *      be present inside the banner rectangle;
     *   2. with the countdown forced to 0 and nothing else touched, those
     *      pixels must be GONE and the frame digest must differ.
     *
     * Step 2 is what makes this an assertion about the banner rather than
     * about the text: it proves the rectangle is painted by draw_level_banner
     * and by nothing else in the frame.
     *
     * The rectangle is the source's own geometry. The 5x7 cell is 6 px wide,
     * so "LEVEL 1" occupies cells 0..5 from x=44 and the last glyph's right
     * edge is at 44 + 6*6 - 1 = 79; the 7-row cell spans y=84..90.
     */
    {
        int banner_pixels_with = 0;
        int banner_pixels_without = 0;
        unsigned long digest_with_banner;
        unsigned long digest_without_banner;
        int bx;
        int by;
        int saved_countdown =
            bounce_app_flow_entry_countdown(&new_path.flow);

        for (by = 84; by <= 90; ++by) {
            for (bx = 44; bx <= 79; ++bx) {
                uint32_t px = 0u;
                if (bounce_surface_get_pixel(new_surface, bx, by, &px) != 0
                    || px == 0u) {
                    banner_pixels_with = -1;
                    break;
                }
                if (px == COLOR_HUD_SCORE)
                    ++banner_pixels_with;
            }
            if (banner_pixels_with < 0)
                break;
        }
        digest_with_banner = surface_digest(new_surface);

        /*
         * Force the gate closed. bounce_app_flow_tick_pre_countdown() only ever
         * decrements, so the countdown is written directly here -- this is a
         * fixture adjustment, not a behaviour under test.
         */
        new_path.flow.gameplay_entry.countdown = 0;
        if (render_app_state(new_surface, new_renderer, &new_path) != 0) {
            failures++;
            goto cleanup;
        }
        for (by = 84; by <= 90; ++by) {
            for (bx = 44; bx <= 79; ++bx) {
                uint32_t px = 0u;
                if (bounce_surface_get_pixel(new_surface, bx, by, &px) != 0
                    || px == 0u) {
                    banner_pixels_without = -1;
                    break;
                }
                if (px == COLOR_HUD_SCORE)
                    ++banner_pixels_without;
            }
            if (banner_pixels_without < 0)
                break;
        }
        digest_without_banner = surface_digest(new_surface);
        new_path.flow.gameplay_entry.countdown = saved_countdown;

        if (banner_pixels_with <= 0) {
            fprintf(stderr,
                    "level banner: no %08lx pixels inside (44,84)-(79,90)"
                    " with the countdown armed\n",
                    (unsigned long)COLOR_HUD_SCORE);
            failures++;
        }
        if (banner_pixels_without < 0 || banner_pixels_without > 0
            || digest_without_banner == digest_with_banner) {
            fprintf(stderr,
                    "level banner: %d pixels and digest %lx survived"
                    " count=0 (with: %d, %lx)\n",
                    banner_pixels_without,
                    (unsigned long)digest_without_banner,
                    banner_pixels_with,
                    (unsigned long)digest_with_banner);
            failures++;
        }
        printf("LEVEL-BANNER rect=(44,84)-(79,90) colour=%08lx"
               " pixels_with=%d pixels_without=%d gate=countdown!=0 %s\n",
               (unsigned long)COLOR_HUD_SCORE,
               banner_pixels_with, banner_pixels_without,
               (banner_pixels_with > 0 && banner_pixels_without == 0)
                   ? "PASS" : "FAIL");
    }

cleanup:
    bounce_renderer_destroy(old_renderer);
    bounce_renderer_destroy(new_renderer);
    bounce_surface_destroy(old_surface);
    bounce_surface_destroy(new_surface);
    bounce_game_shutdown(&old_path);
    bounce_game_shutdown(&new_path);
    if (failures != 0)
        fprintf(stderr, "render continuation: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * Independent source-derived reference for UpdateDynThorns (b.java:340-363).
 * Decoded straight from the opaque 8-byte payload, deliberately NOT via
 * dyn_thorns.c, so this cross-checks the production decoder and update.
 */
typedef struct DynThornRef {
    int32_t blx, bly, trx, try_;
    int32_t aex, aey, wx, wy;
} DynThornRef;

static unsigned long thorn_payload_digest(const BounceLevel *level)
{
    const uint8_t *payload = NULL;
    size_t length = 0;
    unsigned long digest = 1469598103934665603UL;
    size_t i;

    if (level == NULL
        || bounce_level_get_thorn_payload(level, &payload, &length) != 0)
        return 0UL;
    for (i = 0; i < length; ++i) {
        digest ^= (unsigned long)payload[i];
        digest *= 1099511628211UL;
    }
    return digest;
}

static int dyn_thorn_refs_load(const BounceLevel *level, DynThornRef **out)
{
    const uint8_t *payload = NULL;
    size_t length = 0;
    uint32_t count;
    uint32_t t;
    DynThornRef *refs;

    if (level == NULL
        || bounce_level_get_thorn_payload(level, &payload, &length) != 0)
        return -1;
    count = bounce_level_thorn_count(level);
    refs = (DynThornRef *)calloc(count ? count : 1u, sizeof *refs);
    if (refs == NULL)
        return -1;
    for (t = 0; t < count; ++t) {
        const uint8_t *r = payload + (size_t)t * 8u;
        refs[t].blx = (int32_t)(int8_t)r[0];
        refs[t].bly = (int32_t)(int8_t)r[1];
        refs[t].trx = (int32_t)(int8_t)r[2];
        refs[t].try_ = (int32_t)(int8_t)r[3];
        refs[t].aex = (int32_t)(int8_t)r[4];
        refs[t].aey = (int32_t)(int8_t)r[5];
        refs[t].wx = (int32_t)(int8_t)r[6];
        refs[t].wy = (int32_t)(int8_t)r[7];
    }
    *out = refs;
    return 0;
}

/* b.java:346-363, transcribed with int32 arithmetic. */
static void dyn_thorn_ref_update(DynThornRef *r)
{
    int32_t n = (r->trx - r->blx - 2) * 12;
    int32_t i1 = (r->try_ - r->bly - 2) * 12;

    r->wx += r->aex;
    if (r->wx < 0) r->wx = 0; else if (r->wx > n) r->wx = n;
    if (r->wx == 0 || r->wx == n) r->aex = -r->aex;
    r->wy += r->aey;
    if (r->wy < 0) r->wy = 0; else if (r->wy > i1) r->wy = i1;
    if (r->wy == 0 || r->wy == i1) r->aey = -r->aey;
}

/*
 * Dynamic-thorn Tick integration verification.
 *
 * 1. Runtime ownership: the update runs on BounceRuntimeLevelTiles only; the
 *    BounceLevel tile bytes and thorn payload are digest-identical before and
 *    after, and the level stays usable.
 * 2. 300-tick comparison of native w/ae against the independent b.java:346-363
 *    reference on Levels 002, 003, 008, 011.
 * 3. Canonical Tick integration on the regular-ball levels (002, 008): one tick
 *    yields player_tick_entry=1, player_physics=1, dynamic_thorn_update=1, and
 *    the thorn state advances.
 * 4. Big-ball levels (003, 011): the existing ball-size limitation still aborts
 *    the continuation before physics, so the thorn update does not run on those
 *    ticks. Recorded, not worked around.
 * 5. Collision query purity and the 0x80 invariant.
 */
static int verify_dyn_thorn_tick_integration(void)
{
    static const struct {
        int level_id;
        const char *path;
        int is_big_ball;
    } levels[] = {
        {  2, "src/main/resources/levels/J2MElvl.002", 0 },
        {  3, "src/main/resources/levels/J2MElvl.003", 1 },
        {  8, "src/main/resources/levels/J2MElvl.008", 0 },
        { 11, "src/main/resources/levels/J2MElvl.011", 1 }
    };
    size_t c;
    int failures = 0;

    for (c = 0; c < sizeof levels / sizeof levels[0]; ++c) {
        BounceLevel *level = NULL;
        BounceRuntimeLevelTiles *runtime = NULL;
        DynThornRef *refs = NULL;
        const BounceDynThorns *before;
        const BounceDynThorns *after;
        unsigned long level_digest_before;
        unsigned long level_digest_after;
        unsigned long payload_digest_before;
        unsigned long payload_digest_after;
        uint32_t count;
        uint32_t t;
        long mismatches = 0;
        int step;
        int16_t w0_before;
        int16_t w1_before;
        int16_t ae0_before;
        int16_t ae1_before;

        if (bounce_level_load_file(levels[c].path, &level)
                != BOUNCE_LEVEL_LOAD_OK
            || level == NULL
            || dyn_thorn_refs_load(level, &refs) != 0) {
            failures++;
            continue;
        }
        runtime = bounce_runtime_level_tiles_create(level);
        if (runtime == NULL) {
            failures++;
            continue;
        }
        count = bounce_level_thorn_count(level);
        if (count == 0u) {
            failures++;
            goto next_level;
        }

        level_digest_before = level_digest_value(level);
        payload_digest_before = thorn_payload_digest(level);
        before = bounce_runtime_level_tiles_dyn_thorns(runtime);
        if (before == NULL || before->count != count) {
            failures++;
            goto next_level;
        }
        /* Capture the pre-update record 0 before the runtime advances. */
        w0_before = before->records[0].w.x;
        w1_before = before->records[0].w.y;
        ae0_before = before->records[0].ae.x;
        ae1_before = before->records[0].ae.y;

        /* One update, then compare the decoded state with the reference. */
        if (bounce_runtime_level_tiles_update_dyn_thorns(runtime) != 1) {
            failures++;
            goto next_level;
        }
        /* Keep the whole reference in step with the whole native state. */
        for (t = 0; t < count; ++t)
            dyn_thorn_ref_update(&refs[t]);
        after = bounce_runtime_level_tiles_dyn_thorns(runtime);
        if (after->records[0].w.x != (int16_t)refs[0].wx
            || after->records[0].w.y != (int16_t)refs[0].wy
            || after->records[0].ae.x != (int16_t)refs[0].aex
            || after->records[0].ae.y != (int16_t)refs[0].aey) {
            fprintf(stderr, "dyn thorn level %d one-tick mismatch:"
                    " native w=(%d,%d) ae=(%d,%d) ref w=(%d,%d) ae=(%d,%d)\n",
                    levels[c].level_id, after->records[0].w.x,
                    after->records[0].w.y, after->records[0].ae.x,
                    after->records[0].ae.y, refs[0].wx, refs[0].wy,
                    refs[0].aex, refs[0].aey);
            failures++;
        }

        printf("DYNTHORN level=%2d thorns=%u bounds[0]=(%d,%d)"
               " before w[0]=(%d,%d) ae[0]=(%d,%d)"
               " after w[0]=(%d,%d) ae[0]=(%d,%d)\n",
               levels[c].level_id, count,
               (refs[0].trx - refs[0].blx - 2) * 12,
               (refs[0].try_ - refs[0].bly - 2) * 12,
               w0_before, w1_before, ae0_before, ae1_before,
               after->records[0].w.x, after->records[0].w.y,
               after->records[0].ae.x, after->records[0].ae.y);

        /* Immutability: the pristine level is untouched by the update. */
        level_digest_after = level_digest_value(level);
        payload_digest_after = thorn_payload_digest(level);
        if (level_digest_after != level_digest_before
            || payload_digest_after != payload_digest_before
            || bounce_level_thorn_count(level) != count) {
            failures++;
        }

        /* 0x80 invariant: the update performs no LevelTiles write. */
        if (level_digest_after != level_digest_before)
            failures++;

        /* Collision query stays pure and still sees tile 10 correctly. */
        {
            BounceDynThornsSource probe_source;
            int32_t hit;
            if (bounce_dyn_thorns_source(after, &probe_source) != 0)
                failures++;
            hit = bounce_dyn_thorns_test_point_inside(
                &probe_source, refs[0].blx, refs[0].bly);
            if (hit != 0)
                failures++;
        }

        /* 300 further ticks against the independent reference. */
        for (step = 1; step < 300; ++step) {
            if (bounce_runtime_level_tiles_update_dyn_thorns(runtime) != 1) {
                failures++;
                break;
            }
            for (t = 0; t < count; ++t)
                dyn_thorn_ref_update(&refs[t]);
        }
        for (t = 0; t < count; ++t) {
            const BounceDynThornRecord *r = &after->records[t];
            if (r->w.x != (int16_t)refs[t].wx
                || r->w.y != (int16_t)refs[t].wy
                || r->ae.x != (int16_t)refs[t].aex
                || r->ae.y != (int16_t)refs[t].aey)
                mismatches++;
        }
        printf("DYNTHORN level=%2d 300-tick mismatches=%ld final w[0]=(%d,%d)"
               " ae[0]=(%d,%d)\n",
               levels[c].level_id, mismatches,
               after->records[0].w.x, after->records[0].w.y,
               after->records[0].ae.x, after->records[0].ae.y);
        failures += mismatches != 0;

next_level:
        free(refs);
        bounce_runtime_level_tiles_destroy(runtime);
        bounce_level_destroy(level);
    }

    /* Canonical Tick integration on the regular-ball levels. */
    for (c = 0; c < sizeof levels / sizeof levels[0]; ++c) {
        BounceApp app;
        BounceSurface *surface = NULL;
        BounceRenderer *renderer = NULL;
        const BounceDynThorns *thorns_before;
        const BounceDynThorns *thorns_after;
        int16_t thorn_w_before;
        int16_t thorn_y_before;
        unsigned long level_digest_before;
        BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;
        int32_t l_before;
        int32_t k_before;
        int32_t v_before;

        if (levels[c].is_big_ball != 0)
            continue;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(&app, levels[c].level_id - 1,
                                         levels[c].level_id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0
            || bounce_input_apply_source(
                &app.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        surface = bounce_surface_create();
        renderer = bounce_renderer_create(surface);
        if (surface == NULL || renderer == NULL) {
            bounce_renderer_destroy(renderer);
            bounce_surface_destroy(surface);
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }

        thorns_before = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
        if (thorns_before == NULL || thorns_before->count == 0u) {
            failures++;
        } else {
            /* Snapshot before the tick: the accessor returns the same live
             * object, so the values must be captured, not the pointers. */
            thorn_w_before = thorns_before->records[0].w.x;
            thorn_y_before = thorns_before->records[0].w.y;
        }
        level_digest_before = level_digest_value(app.level);
        l_before = app.l;
        k_before = app.k;
        v_before = app.v;

        if (app_timer_callback_render(surface, renderer, &app, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK) {
            failures++;
        } else {
            thorns_after = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
            printf("DYNTHORNTICK level=%2d thorns=%u entry=%llu physics=%llu"
                   " thorn_update=%llu w[0]=(%d,%d)->(%d,%d)"
                   " player=(%d,%d) cam=(%d,%d,%d)\n",
                   levels[c].level_id,
                   thorns_before->count,
                   (unsigned long long)
                       bounce_game_timer_player_tick_entry_count(
                           &app.game_timer),
                   (unsigned long long)bounce_game_timer_player_physics_count(
                       &app.game_timer),
                   (unsigned long long)
                       bounce_game_timer_dynamic_thorn_update_count(
                           &app.game_timer),
                   thorn_w_before,
                   thorn_y_before,
                   thorns_after->records[0].w.x,
                   thorns_after->records[0].w.y,
                   app.player.TODO_unkX, app.player.TODO_unkY,
                   app.l, app.k, app.v);

            /* Exactly the three sanctioned counters, each once. */
            if (bounce_game_timer_player_tick_entry_count(&app.game_timer) != 1u
                || bounce_game_timer_player_physics_count(&app.game_timer) != 1u
                || bounce_game_timer_dynamic_thorn_update_count(
                    &app.game_timer) != 1u)
                failures++;
            /* The thorn advanced by exactly one step. */
            if (thorns_after->records[0].w.x == thorn_w_before
                && thorns_after->records[0].w.y == thorn_y_before)
                failures++;
            /* The pristine level is untouched; camera was not changed by it. */
            if (level_digest_value(app.level) != level_digest_before
                || app.l != l_before || app.k != k_before
                || app.v != v_before)
                failures++;
            /* The render boundary still produced a 128x128 frame. */
            if (bounce_surface_width(surface) != 128u
                || bounce_surface_height(surface) != 128u)
                failures++;
        }

        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        bounce_game_shutdown(&app);
    }

    /*
     * STEP 14.1a: big-ball levels no longer abort before the update.
     *
     * Previously app_step_vertical() refused ballSize 16, so the tick died before
     * the dynamic-thorn update and this block could only assert "refused". With
     * big-ball gravity implemented the tick completes the player-tick branch, so
     * the assertion is now the stronger one: entry, physics AND the thorn update
     * all run exactly once.
     *
     * This is a side effect worth stating plainly: it is what makes STEP 14.2
     * observable on the big-ball levels at all, because the thorn state could
     * never advance while the tick aborted ahead of it.
     */
    for (c = 0; c < sizeof levels / sizeof levels[0]; ++c) {
        BounceApp app;
        BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

        if (levels[c].is_big_ball == 0)
            continue;
        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(&app, levels[c].level_id - 1,
                                         levels[c].level_id) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            failures++;
            continue;
        }
        if (app_timer_callback_dispatch(&app, &branch) != 0
            || branch != BOUNCE_TICK_DISPATCH_PLAYER_TICK
            || bounce_game_timer_player_tick_entry_count(&app.game_timer) != 1u
            || bounce_game_timer_player_physics_count(&app.game_timer) != 1u
            || bounce_game_timer_dynamic_thorn_update_count(
                   &app.game_timer) != 1u)
            failures++;
        printf("DYNTHORNTICK level=%2d big-ball: tick completes;"
               " entry=%llu physics=%llu thorn_update=%llu"
               " player=(%d,%d)\n", levels[c].level_id,
               (unsigned long long)
                   bounce_game_timer_player_tick_entry_count(&app.game_timer),
               (unsigned long long)bounce_game_timer_player_physics_count(
                   &app.game_timer),
               (unsigned long long)
                   bounce_game_timer_dynamic_thorn_update_count(&app.game_timer),
               app.player.TODO_unkX, app.player.TODO_unkY);
        bounce_game_shutdown(&app);
    }

    if (failures != 0)
        fprintf(stderr, "dyn thorn tick integration: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

static int verify_level_load_entry_integration(void)
{
    static const LevelEntryExpectation level001 = {
        1, 112u, 8u, 2u, 1u, 0u, 110u, 5u, 6u, 0u
    };
    static const LevelEntryExpectation level008 = {
        8, 156u, 36u, 99u, 1u, 0u, 33u, 23u, 11u, 11u
    };
    static const LevelEntryExpectation level011 = {
        11, 178u, 57u, 142u, 37u, 1u, 0u, 47u, 15u, 5u
    };
    static const int invalid_ids[] = { 0, 12, -1, 99 };
    BounceApp game;
    char path[64];
    char guard[4];
    size_t index;

    /*
     * STEP 38-RESET -- Test A is UNCHANGED and still uses the direct route into
     * level 1.
     *
     * It keeps working because verify_level_entry_route() now sets the count to 0
     * itself on the list_index < 0 branch, instead of inheriting the launch default.
     * That is the right place for the value: this fixture is about the level-load
     * integration, and the shipped default of 2 -- which routes New Game through
     * Level Select -- is a flow-level behaviour covered by
     * verify_gameplay_entry_boundary()'s Test A.
     */
    if (verify_level_entry_route(-1, &level001) != 0)
        return -1;
    /* Test B: a wide level with thorns, then the largest big-ball level. */
    if (verify_level_entry_route(7, &level008) != 0)
        return -1;
    if (verify_level_entry_route(10, &level011) != 0)
        return -1;

    /* Test C: invalid ids are rejected before any file access or ownership. */
    if (bounce_game_init(&game) != 0
        || bounce_game_enter_menu(&game) != 0)
        return -1;
    memset(guard, 0x5a, sizeof guard);
    for (index = 0u; index < sizeof invalid_ids / sizeof invalid_ids[0];
         ++index) {
        if (bounce_game_level_resource_path(
                invalid_ids[index],
                path,
                sizeof path
            ) != -1
            || bounce_game_level_resource_path(
                invalid_ids[index],
                NULL,
                sizeof path
            ) != -1
            || bounce_game_load_level_entry(&game, invalid_ids[index]) != -1
            || game.level != NULL
            || game.level_path != NULL
            || game.level_id != BOUNCE_GAME_LEVEL_ID_UNKNOWN
            || game.runtime != NULL
            || game.player.initialized)
            return -1;
    }
    /* A valid id still loads after the rejected attempts. */
    if (bounce_game_load_level_entry(&game, 8) != 0
        || game.level == NULL
        || game.level_id != 8
        || verify_level_entry_facts(game.level, &level008) != 0
        /* A failed replacement must not disturb the owned level. */
        || bounce_game_load_level_entry(&game, 12) != -1
        || game.level == NULL
        || game.level_id != 8
        || verify_level_entry_facts(game.level, &level008) != 0
        || bounce_game_load_level_entry(&game, 1) != 0
        || game.level == NULL
        || game.level_id != 1
        || verify_level_entry_facts(game.level, &level001) != 0
        || game.runtime != NULL
        || game.player.initialized) {
        bounce_game_shutdown(&game);
        return -1;
    }

    /* Ownership guard: a runtime tile copy blocks the level-only seam. */
    bounce_game_release_level(&game);
    if (bounce_game_start_level(&game, BOUNCE_LEVEL001_PATH, 1, 3) != 0
        || game.runtime == NULL
        || !game.player.initialized
        || bounce_game_load_level_entry(&game, 8) != -1
        || game.level_id != 1
        || bounce_level_width(game.level) != BOUNCE_LEVEL001_WIDTH) {
        bounce_game_shutdown(&game);
        return -1;
    }
    bounce_game_shutdown(&game);
    return 0;
}

static unsigned long token_to_x11_pixel(uint32_t token)
{
    return ((unsigned long)((token >> 16) & 0xffu) << 16)
        | ((unsigned long)((token >> 8) & 0xffu) << 8)
        | (unsigned long)(token & 0xffu);
}

static int x11_create(X11PresentationContext *context)
{
    XSetWindowAttributes attributes;
    XGCValues values;
    char *window_title;

    if (context == NULL)
        return -1;
    memset(context, 0, sizeof *context);
    context->display = XOpenDisplay(NULL);
    if (context->display == NULL)
        return -1;

    context->screen = DefaultScreen(context->display);
    context->window = XCreateSimpleWindow(
        context->display,
        RootWindow(context->display, context->screen),
        0,
        0,
        BOUNCE_SURFACE_WIDTH,
        BOUNCE_SURFACE_HEIGHT,
        0,
        BlackPixel(context->display, context->screen),
        BlackPixel(context->display, context->screen)
    );
    if (context->window == None)
        goto fail;

    /*
     * NATIVE EXTENSION: ButtonPressMask adds mouse support to the UI. Only the
     * press is needed, because the click seam is edge-triggered. No motion or
     * release handling was added, so no hover or drag state exists.
     */
    attributes.event_mask = ExposureMask
        | KeyPressMask
        | KeyReleaseMask
        | ButtonPressMask
        | StructureNotifyMask;
    XSelectInput(context->display, context->window, attributes.event_mask);
    context->graphics_context = XCreateGC(
        context->display,
        context->window,
        0,
        NULL
    );
    if (context->graphics_context == NULL)
        goto fail;

    values.foreground = WhitePixel(context->display, context->screen);
    XChangeGC(
        context->display,
        context->graphics_context,
        GCForeground,
        &values
    );

    context->delete_window_atom = XInternAtom(
        context->display,
        "WM_DELETE_WINDOW",
        False
    );
    XSetWMProtocols(
        context->display,
        context->window,
        &context->delete_window_atom,
        1
    );
    window_title = "Nokia Bounce - Level 001 vertical slice";
    XStoreName(context->display, context->window, window_title);
    XMapWindow(context->display, context->window);
    XFlush(context->display);
    context->running = 1;
    return 0;

fail:
    if (context->graphics_context != NULL)
        XFreeGC(context->display, context->graphics_context);
    if (context->window != None)
        XDestroyWindow(context->display, context->window);
    XCloseDisplay(context->display);
    memset(context, 0, sizeof *context);
    return -1;
}

static void x11_destroy(X11PresentationContext *context)
{
    if (context == NULL || context->display == NULL)
        return;
    if (context->graphics_context != NULL)
        XFreeGC(context->display, context->graphics_context);
    if (context->window != None)
        XDestroyWindow(context->display, context->window);
    XCloseDisplay(context->display);
    memset(context, 0, sizeof *context);
}

static bool x11_keysym_to_source(
    KeySym key,
    BounceInputSource *source_out
)
{
    if (source_out == NULL)
        return false;

    switch (key) {
        case XK_Left:
            *source_out = BOUNCE_INPUT_SOURCE_LEFT_ARROW;
            return true;
        case XK_a:
        case XK_A:
            *source_out = BOUNCE_INPUT_SOURCE_LEFT_A;
            return true;
        case XK_Right:
            *source_out = BOUNCE_INPUT_SOURCE_RIGHT_ARROW;
            return true;
        case XK_d:
        case XK_D:
            *source_out = BOUNCE_INPUT_SOURCE_RIGHT_D;
            return true;
        case XK_Up:
            *source_out = BOUNCE_INPUT_SOURCE_UP_ARROW;
            return true;
        case XK_w:
        case XK_W:
            *source_out = BOUNCE_INPUT_SOURCE_UP_W;
            return true;
        case XK_Down:
            *source_out = BOUNCE_INPUT_SOURCE_DOWN_ARROW;
            return true;
        case XK_s:
        case XK_S:
            *source_out = BOUNCE_INPUT_SOURCE_DOWN_S;
            return true;
        case XK_0:
            *source_out = BOUNCE_INPUT_SOURCE_NUM0;
            return true;
        case XK_1:
            *source_out = BOUNCE_INPUT_SOURCE_NUM1;
            return true;
        case XK_2:
            *source_out = BOUNCE_INPUT_SOURCE_NUM2;
            return true;
        case XK_3:
            *source_out = BOUNCE_INPUT_SOURCE_NUM3;
            return true;
        case XK_4:
            *source_out = BOUNCE_INPUT_SOURCE_NUM4;
            return true;
        case XK_5:
            *source_out = BOUNCE_INPUT_SOURCE_NUM5;
            return true;
        case XK_6:
            *source_out = BOUNCE_INPUT_SOURCE_NUM6;
            return true;
        case XK_7:
            *source_out = BOUNCE_INPUT_SOURCE_NUM7;
            return true;
        case XK_8:
            *source_out = BOUNCE_INPUT_SOURCE_NUM8;
            return true;
        case XK_9:
            *source_out = BOUNCE_INPUT_SOURCE_NUM9;
            return true;
        case XK_p:
        case XK_P:
            *source_out = BOUNCE_INPUT_SOURCE_PAUSE;
            return true;
        case XK_Return:
            *source_out = BOUNCE_INPUT_SOURCE_CONFIRM_RETURN;
            return true;
        case XK_KP_Enter:
            *source_out = BOUNCE_INPUT_SOURCE_CONFIRM_KP_ENTER;
            return true;
        case XK_space:
            *source_out = BOUNCE_INPUT_SOURCE_CONFIRM_SPACE;
            return true;
        case XK_Escape:
            *source_out = BOUNCE_INPUT_SOURCE_ESCAPE;
            return true;
        case XK_q:
        case XK_Q:
            *source_out = BOUNCE_INPUT_SOURCE_QUIT;
            return true;
        /*
         * STEP 64-AF -- XK_numbersign is the X11 keysym for '#', which is MIDP
         * Canvas.KEY_POUND, raw key code 35: the e.java:383 `case 35` consumer
         * that sets `af` powerUpGravity = 300.
         */
        case XK_numbersign:
            *source_out = BOUNCE_INPUT_SOURCE_HASH;
            return true;
        /*
         * ===================================================================
         * NATIVE ADDITION -- THE NUMERIC KEYPAD, BOTH NumLock STATES.
         * ===================================================================
         *
         * NOT A RECOVERY. Nothing in the recovered game reads a keypad digit;
         * Bounce drives itself from getGameAction() (e.java:392-408) and the raw
         * codes 35, 49, 51, -6 and -7. The digits this build does read are
         * cheats -- 7-8-7-8-9-8 is the GodMode sequence and 1/3 skip a level only
         * while `af` is set -- and they arrive as XK_7..XK_9, the TOP ROW, which
         * is a different keysym from every key below. There is therefore no
         * collision with the level-select digits, with the GodMode detector or
         * with the af level skip: those are XK_0..XK_9 and these are XK_KP_*.
         *
         * BOTH NumLock STATES ARE LISTED, because X11 delivers a DIFFERENT
         * KEYSYM for the same physical key depending on NumLock, and
         * XLookupKeysym(&event.xkey, 0) returns whichever applies. The names and
         * values are the installed ones, from /usr/include/X11/keysymdef.h:
         *
         *     XK_KP_8     0xffb8    XK_KP_Up     0xff97
         *     XK_KP_2     0xffb2    XK_KP_Down   0xff99
         *     XK_KP_4     0xffb4    XK_KP_Left   0xff96
         *     XK_KP_6     0xffb6    XK_KP_Right  0xff98
         *
         * So the keypad works with NumLock on and off. Mapping only the digit
         * form would have left the feature silently dead on any machine where
         * NumLock is off, which is the common default on a desktop.
         *
         * KEYPAD 5 IS NOW MAPPED, and that is a CHANGE the player asked for rather
         * than a recovery. It was deliberately left unmapped before, and the
         * reason still holds: the recovered game has no FIRE, because action 8 at
         * e.java:405 is `if (this.af) this.e = true`, the af-gated level-skip
         * latch, which is already bound to XK_c as a labelled native binding. The
         * player chose confirm_start instead, so 5 now shares that one action with
         * Return, KP_Enter and Space. The consequence is the reason it was left
         * alone before and it is recorded rather than hidden: confirm_start is a
         * MENU SELECT (app_ui_input_from_source maps it to BOUNCE_UI_INPUT_SELECT)
         * and is not a game input, so numpad 5 confirms menu items rather than
         * performing an action in the level. There is no FIRE in the source to
         * alias instead, so no third option exists that would be a reproduction.
         *
         * This function stays a PURE KEYSYM TABLE. Whether the keypad is
         * allowed to drive the game is decided by the caller through
         * bounce_input_source_is_keypad(), so the mapping can be tested on its
         * own and the policy in one place.
         */
        case XK_KP_8:
        case XK_KP_Up: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_UP;
            return true;
        case XK_KP_2:
        case XK_KP_Down: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_DOWN;
            return true;
        case XK_KP_4:
        case XK_KP_Left: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_LEFT;
            return true;
        case XK_KP_6:
        case XK_KP_Right: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_RIGHT;
            return true;
        /*
         * THE OTHER SIX KEYPAD KEYS. A player asked for the whole keypad, so 0, 1,
         * 3, 5, 7 and 9 join 2, 4, 6 and 8. Both NumLock states are listed for
         * each, for the reason above: X11 delivers a different keysym for the
         * same physical key, and mapping only the digit form would have left the
         * feature dead wherever NumLock is off.
         *
         * THE NAMES ARE THE INSTALLED ONES. From /usr/include/X11/keysymdef.h:
         *
         *     XK_KP_0     0xffb0    XK_KP_Insert 0xff9e
         *     XK_KP_1     0xffb1    XK_KP_End    0xff9c
         *     XK_KP_3     0xffb3    XK_KP_Next   0xff9b
         *     XK_KP_5     0xffb5    XK_KP_Begin  0xff9d
         *     XK_KP_7     0xffb7    XK_KP_Home   0xff95
         *     XK_KP_9     0xffb9    XK_KP_Prior  0xff9a
         *
         * XK_KP_PgUp and XK_KP_PgDn -- the names for 9 and 3 with NumLock off --
         * DO NOT EXIST in that header and are not used here; the real names are
         * XK_KP_Prior (page up) and XK_KP_Next (page down). XK_KP_Equal does
         * exist but is not what the 5 key delivers with NumLock off; that is
         * XK_KP_Begin, which is what the previous stage already asserted.
         *
         * 7 AND 9 ARE NOW BOTH A GAMEPLAY KEY AND A GodMode KEY, and that is not
         * a conflict. app_godmode_source() below switches on the KEYSYM, not on
         * the source this table returns, which is exactly why it was written that
         * way: KP_7 still reaches the detector as NUM7 and KP_9 as NUM9 for the
         * 7-8-7-8-9-8 sequence, while also steering diagonally here. Nothing in
         * the GodMode path is touched, extended or re-derived by this table.
         */
        case XK_KP_0:
        case XK_KP_Insert: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_PAUSE;
            return true;
        case XK_KP_5:
        case XK_KP_Begin: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_CONFIRM;
            return true;
        case XK_KP_7:
        case XK_KP_Home: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_UP_LEFT;
            return true;
        case XK_KP_9:
        case XK_KP_Prior: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_UP_RIGHT;
            return true;
        case XK_KP_1:
        case XK_KP_End: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_DOWN_LEFT;
            return true;
        case XK_KP_3:
        case XK_KP_Next: /* NumLock off */
            *source_out = BOUNCE_INPUT_SOURCE_KP_DOWN_RIGHT;
            return true;
        default:
            return false;
    }
}

static bool expect_x11_source(
    KeySym key,
    BounceInputSource expected
)
{
    BounceInputSource actual;
    return x11_keysym_to_source(key, &actual) && actual == expected;
}

static BounceUiInput app_ui_input_from_source(BounceInputSource source)
{
    switch (source) {
        case BOUNCE_INPUT_SOURCE_UP_ARROW:
        case BOUNCE_INPUT_SOURCE_UP_W:
            return BOUNCE_UI_INPUT_UP;
        case BOUNCE_INPUT_SOURCE_DOWN_ARROW:
        case BOUNCE_INPUT_SOURCE_DOWN_S:
            return BOUNCE_UI_INPUT_DOWN;
        case BOUNCE_INPUT_SOURCE_CONFIRM_RETURN:
        case BOUNCE_INPUT_SOURCE_CONFIRM_KP_ENTER:
        case BOUNCE_INPUT_SOURCE_CONFIRM_SPACE:
            return BOUNCE_UI_INPUT_SELECT;
        case BOUNCE_INPUT_SOURCE_QUIT:
            return BOUNCE_UI_INPUT_EXIT;
        /* X11-only test alias; physical Nokia Back mapping remains UNKNOWN. */
        case BOUNCE_INPUT_SOURCE_ESCAPE:
            return BOUNCE_UI_INPUT_BACK;
        default:
            return BOUNCE_UI_INPUT_OTHER;
    }
}

/*
 * STEP 13E -- debug tracker self-test.
 *
 * WHAT IS PROVEN HERE
 *   1. NBB_DEBUG parsing. Unset, "0", every invalid spelling, and a value with
 *      trailing text all resolve to DISABLED; "1".."3" resolve to themselves.
 *      The parse is exercised through getenv() with setenv()/unsetenv() as well
 *      as through the pure text parser, so the environment path is covered too.
 *   2. Disabled means silent. A tracker at level 0 writes zero bytes, and so
 *      does a tracker whose level is non-zero but whose sink is NULL.
 *   3. The level gate. Each event is emitted at its own level and at every level
 *      above it, and not at any level below it: level 1 carries events, level 2
 *      adds score/lives/ball-size/death-state, level 3 adds the player line.
 *   4. The exact output text, byte for byte, for one event of each category.
 *   5. The edge detector. A state that does not change produces no line; each
 *      change produces exactly one; the first observation is a baseline, not a
 *      change; and the level-3 player line appears once per distinct tick, not
 *      once per call.
 *
 * The tracker writes to a private temporary stream here, never to stderr, so
 * --check keeps its rc=0 / empty-stderr contract. Nothing in this function
 * touches gameplay state: `app` is a local, and no gameplay, level-loading,
 * respawn, collision, physics, rendering or UI function is called.
 */
static int debug_capture(
    BounceDebugLevel level,
    char *out,
    size_t out_size,
    void (*body)(BounceDebugTracker *, BounceGame *)
)
{
    BounceDebugTracker tracker;
    BounceGame app;
    FILE *sink;
    size_t got;

    if (out == NULL || out_size < 2u || body == NULL)
        return -1;
    sink = tmpfile();
    if (sink == NULL)
        return -1;
    bounce_debug_tracker_init(&tracker, level, sink);
    memset(&app, 0, sizeof app);
    app.level_id = 1;
    app.lives = 3;
    app.score = 0;
    app.player.ballSize = 12;
    app.player.p = 6;
    app.player.C = 0;
    app.player.z = 0;
    app.player.q = 0;
    app.player.TODO_unkX = 30;
    app.player.TODO_unkY = 18;
    app.player.horizontal_velocity = 6;
    app.player.o = -4;
    app.checkpoint_tile_x = 2;
    app.checkpoint_tile_y = 3;
    app.checkpoint_ball_size = 12;
    app.flow.state = BOUNCE_APP_STATE_GAMEPLAY;
    app.game_timer.tick_entry_count = 18420u;

    body(&tracker, &app);

    (void)fflush(sink);
    (void)rewind(sink);
    got = fread(out, 1u, out_size - 1u, sink);
    out[got] = '\0';
    (void)fclose(sink);
    return (int)got;
}

static void debug_body_events(BounceDebugTracker *tracker, BounceGame *app)
{
    /*
     * Level-1 vocabulary only. The death z/q ladder is deliberately NOT called
     * here: it is a level-2 state line, and the level gate is asserted below in
     * both directions.
     */
    bounce_debug_event_new_game(tracker, app);
    bounce_debug_event_level_start(tracker, app);
    bounce_debug_event_checkpoint(tracker, app, 2, 3, 12);
    bounce_debug_event_death(tracker, app);
    bounce_debug_event_respawn(tracker, app);
    bounce_debug_flow_change(
        tracker,
        app,
        BOUNCE_APP_STATE_GAMEPLAY,
        BOUNCE_APP_STATE_GAME_OVER
    );
    bounce_debug_tile(tracker, app, BOUNCE_DEBUG_TILE_CRYSTAL, 7u, 2, 3);
    bounce_debug_tile(tracker, app, BOUNCE_DEBUG_TILE_WIDE_HOOP, 21u, 5, 6);
}

static void debug_body_state(BounceDebugTracker *tracker, BounceGame *app)
{
    bounce_debug_score(tracker, app, 500, 1000);
    bounce_debug_life(tracker, app, 3, 2);
    bounce_debug_ball_size(tracker, app, 12, 16);
    bounce_debug_death_tick(tracker, app, 1, 0);
}

static void debug_body_verbose(BounceDebugTracker *tracker, BounceGame *app)
{
    bounce_debug_player_state(tracker, app);
}

static void debug_body_quiet(BounceDebugTracker *tracker, BounceGame *app)
{
    /*
     * Every emitter, called at the highest level, must still write nothing while
     * the tracker is disabled. This is the "default run is silent" guarantee.
     */
    bounce_debug_event_new_game(tracker, app);
    bounce_debug_event_level_start(tracker, app);
    bounce_debug_event_level_complete(tracker, app);
    bounce_debug_event_game_over(tracker, app);
    bounce_debug_event_game_end(tracker, app);
    bounce_debug_event_death(tracker, app);
    bounce_debug_event_respawn(tracker, app);
    bounce_debug_event_checkpoint(tracker, app, 1, 2, 3);
    bounce_debug_flow_change(
        tracker,
        app,
        BOUNCE_APP_STATE_GAMEPLAY,
        BOUNCE_APP_STATE_GAME_END
    );
    bounce_debug_tile(tracker, app, BOUNCE_DEBUG_TILE_HOOP, 13u, 1, 2);
    bounce_debug_score(tracker, app, 0, 1);
    bounce_debug_life(tracker, app, 1, 2);
    bounce_debug_ball_size(tracker, app, 12, 16);
    bounce_debug_death_tick(tracker, app, 2, 7);
    bounce_debug_player_state(tracker, app);
    (void)bounce_debug_tracker_observe(tracker, app);
}

/* Count non-overlapping occurrences of `needle` in `haystack`. */
static int debug_count_occurrences(const char *haystack, const char *needle)
{
    size_t needle_length = strlen(needle);
    int count = 0;
    const char *cursor = haystack;

    if (needle_length == 0u)
        return -1;
    while ((cursor = strstr(cursor, needle)) != NULL) {
        ++count;
        cursor += needle_length;
    }
    return count;
}

/* Drive the edge detector through a scripted sequence of state edits. */
static int debug_expect_edges(void)
{
    BounceDebugTracker tracker;
    BounceGame app;
    FILE *sink;
    char buffer[4096];
    size_t got;

    sink = tmpfile();
    if (sink == NULL)
        return -1;
    bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_STATE, sink);
    memset(&app, 0, sizeof app);
    app.level_id = 1;
    app.lives = 3;
    app.player.ballSize = 12;
    app.player.p = 6;
    app.flow.state = BOUNCE_APP_STATE_GAMEPLAY;
    app.game_timer.tick_entry_count = 100u;

    /* Baseline: seeds the cache and writes nothing at level 2. */
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;
    /* No change: still nothing. */
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;
    app.score = 500;
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;
    /* Re-observing the same value must not repeat the line. */
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;
    app.lives = 2;
    app.player.ballSize = 16;
    app.player.p = 8;
    app.checkpoint_tile_x = 9;
    app.checkpoint_tile_y = 4;
    app.checkpoint_ball_size = 16;
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;
    /* A state change inside the same tick must still be reported once. */
    app.lives = 1;
    if (bounce_debug_tracker_observe(&tracker, &app) != 0)
        goto fail;

    (void)fflush(sink);
    (void)rewind(sink);
    got = fread(buffer, 1u, sizeof buffer - 1u, sink);
    buffer[got] = '\0';
    (void)fclose(sink);

    /* Exactly four lines, in the order score, lives, ball, checkpoint, lives. */
    if (strstr(buffer, "[NBB-SCORE] tick=100 0 -> 500\n") == NULL
        || strstr(buffer, "[NBB-LIFE] tick=100 3 -> 2\n") == NULL
        || strstr(buffer, "[NBB-BALL] tick=100 size=12 -> 16\n") == NULL
        || strstr(buffer, "[NBB-CHECKPOINT] tick=100 x=9 y=4 size=16\n") == NULL
        || strstr(buffer, "[NBB-LIFE] tick=100 2 -> 1\n") == NULL) {
        return -1;
    }
    /* No duplicates: each of those four transitions appears exactly once. */
    if (debug_count_occurrences(buffer, "[NBB-SCORE]") != 1
        || debug_count_occurrences(buffer, "[NBB-BALL]") != 1
        || debug_count_occurrences(buffer, "[NBB-CHECKPOINT]") != 1
        || debug_count_occurrences(buffer, "[NBB-LIFE]") != 2) {
        return -1;
    }
    return 0;
fail:
    (void)fclose(sink);
    return -1;
}

/* Level 3 must emit one player line per distinct tick, not one per call. */
static int debug_expect_verbose_throttle(void)
{
    BounceDebugTracker tracker;
    BounceGame app;
    FILE *sink;
    char buffer[4096];
    size_t got;

    sink = tmpfile();
    if (sink == NULL)
        return -1;
    bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_VERBOSE, sink);
    memset(&app, 0, sizeof app);
    app.level_id = 2;
    app.player.ballSize = 12;
    app.player.p = 6;
    app.flow.state = BOUNCE_APP_STATE_GAMEPLAY;
    app.game_timer.tick_entry_count = 7u;

    if (bounce_debug_tracker_observe(&tracker, &app) != 0
        || bounce_debug_tracker_observe(&tracker, &app) != 0
        || bounce_debug_tracker_observe(&tracker, &app) != 0) {
        (void)fclose(sink);
        return -1;
    }
    app.game_timer.tick_entry_count = 8u;
    if (bounce_debug_tracker_observe(&tracker, &app) != 0) {
        (void)fclose(sink);
        return -1;
    }

    (void)fflush(sink);
    (void)rewind(sink);
    got = fread(buffer, 1u, sizeof buffer - 1u, sink);
    buffer[got] = '\0';
    (void)fclose(sink);

    /* Four calls, two distinct ticks, therefore two lines. */
    if (debug_count_occurrences(buffer, "[NBB-PLAYER]") != 2)
        return -1;
    if (strstr(buffer, "tick=7 flow=GAMEPLAY level=2 x=0 y=0 vx=0 vy=0") == NULL
        || strstr(buffer, "tick=8 flow=GAMEPLAY level=2 x=0 y=0 vx=0 vy=0")
            == NULL) {
        return -1;
    }
    if (strstr(buffer, "cp=0,0,0") == NULL)
        return -1;
    return 0;
}

static int verify_debug_tracker(void)
{
    char buffer[8192];
    int got;
    static const char *const invalid[] = {
        "",
        " ",
        "4",
        "9",
        "-1",
        "01",
        "1x",
        " 1",
        "1 ",
        "true",
        "on",
        "0.5",
        "one",
        "3\n"
    };
    size_t index;

    /* --- 1. pure parser ------------------------------------------------- */
    if (bounce_debug_level_from_text(NULL) != BOUNCE_DEBUG_LEVEL_DISABLED
        || bounce_debug_level_from_text("0") != BOUNCE_DEBUG_LEVEL_DISABLED
        || bounce_debug_level_from_text("1") != BOUNCE_DEBUG_LEVEL_EVENTS
        || bounce_debug_level_from_text("2") != BOUNCE_DEBUG_LEVEL_STATE
        || bounce_debug_level_from_text("3") != BOUNCE_DEBUG_LEVEL_VERBOSE) {
        return -1;
    }
    for (index = 0u; index < sizeof invalid / sizeof invalid[0]; ++index) {
        if (bounce_debug_level_from_text(invalid[index])
            != BOUNCE_DEBUG_LEVEL_DISABLED) {
            return -1;
        }
    }
    if (bounce_debug_level_from_env(NULL) != BOUNCE_DEBUG_LEVEL_DISABLED
        || bounce_debug_level_from_env("") != BOUNCE_DEBUG_LEVEL_DISABLED) {
        return -1;
    }
    if (strcmp(BOUNCE_DEBUG_ENV_NAME, "NBB_DEBUG") != 0)
        return -1;

    /* --- 2. the environment path ---------------------------------------- */
    /*
     * The environment itself is deliberately NOT poked from in here: setenv()
     * and unsetenv() are POSIX, not C11, and this translation unit is built with
     * -std=c11 -pedantic -Werror, so calling them here would need a feature-test
     * macro and would weaken the build. The environment contract is instead
     * verified end to end from the shell (unset, "0", "1", "2", "3" and an
     * invalid value), and what is proven here is that the whole environment path
     * is this one delegation plus this pure parser.
     */
    if (bounce_debug_level_from_env(NULL) != BOUNCE_DEBUG_LEVEL_DISABLED
        || bounce_debug_level_from_env("") != BOUNCE_DEBUG_LEVEL_DISABLED
        || bounce_debug_level_from_env("NBB_DEBUG_UNSET_IN_PROCESS_")
            != BOUNCE_DEBUG_LEVEL_DISABLED) {
        return -1;
    }
    if (bounce_debug_level_from_env("NBB_DEBUG_SELFTEST_LEVEL_THREE_")
        != BOUNCE_DEBUG_LEVEL_DISABLED) {
        return -1;
    }

    /* --- 3. disabled is silent ------------------------------------------ */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_DISABLED, buffer, sizeof buffer,
        debug_body_quiet);
    if (got != 0 || buffer[0] != '\0')
        return -1;
    /* A NULL sink silences a non-zero level too. */
    {
        BounceDebugTracker tracker;
        BounceGame app;

        bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_VERBOSE, NULL);
        if (bounce_debug_tracker_enabled(&tracker))
            return -1;
        memset(&app, 0, sizeof app);
        debug_body_quiet(&tracker, &app);
    }
    /* An out-of-range level is clamped to disabled, never to verbose. */
    {
        BounceDebugTracker tracker;
        BounceGame app;
        FILE *sink = tmpfile();

        if (sink == NULL)
            return -1;
        bounce_debug_tracker_init(
            &tracker,
            (BounceDebugLevel)99,
            sink
        );
        if (bounce_debug_tracker_level(&tracker) != BOUNCE_DEBUG_LEVEL_DISABLED) {
            (void)fclose(sink);
            return -1;
        }
        memset(&app, 0, sizeof app);
        debug_body_quiet(&tracker, &app);
        (void)fflush(sink);
        (void)rewind(sink);
        got = (int)fread(buffer, 1u, sizeof buffer - 1u, sink);
        buffer[got] = '\0';
        (void)fclose(sink);
        if (got != 0)
            return -1;
    }

    /* --- 4. the level gate ---------------------------------------------- */
    /* Level 1: events only, no state-transition or player line. */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_EVENTS, buffer, sizeof buffer,
        debug_body_state);
    if (got != 0 || buffer[0] != '\0')
        return -1;
    got = debug_capture(BOUNCE_DEBUG_LEVEL_EVENTS, buffer, sizeof buffer,
        debug_body_verbose);
    if (got != 0 || buffer[0] != '\0')
        return -1;

    /* Level 2: events plus state transitions, still no player line. */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_STATE, buffer, sizeof buffer,
        debug_body_events);
    if (strstr(buffer, "[NBB-SCORE]") != NULL
        || strstr(buffer, "[NBB-PLAYER]") != NULL) {
        return -1;
    }
    /*
     * The death ladder in both directions: the level-1 run above must NOT carry
     * a [NBB-DEATH] line, and the level-2 run must carry exactly the one the
     * ladder call produces.
     */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_EVENTS, buffer, sizeof buffer,
        debug_body_events);
    if (strstr(buffer, "[NBB-DEATH]") != NULL)
        return -1;
    bounce_debug_death_tick(NULL, NULL, 0, 0); /* must be inert, not a crash */
    {
        BounceDebugTracker tracker;
        BounceGame app;

        memset(&app, 0, sizeof app);
        bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_STATE, NULL);
        bounce_debug_death_tick(&tracker, &app, 2, 7);
        bounce_debug_death_tick(&tracker, NULL, 2, 7);
        bounce_debug_event_death(&tracker, NULL);
        bounce_debug_event_death(NULL, &app);
        bounce_debug_tile(&tracker, &app, BOUNCE_DEBUG_TILE_HOOP, 0u, 0, 0);
        bounce_debug_flow_change(&tracker, &app, BOUNCE_APP_STATE_MENU,
            BOUNCE_APP_STATE_MENU);
        bounce_debug_event_checkpoint(&tracker, &app, 0, 0, 0);
        bounce_debug_event_checkpoint(NULL, NULL, 0, 0, 0);
        bounce_debug_ball_size(&tracker, NULL, 0, 0);
        bounce_debug_ball_size(NULL, &app, 0, 0);
        bounce_debug_life(&tracker, NULL, 0, 0);
        bounce_debug_life(NULL, &app, 0, 0);
        bounce_debug_score(&tracker, NULL, 0, 0);
        bounce_debug_score(NULL, &app, 0, 0);
        bounce_debug_player_state(&tracker, NULL);
        bounce_debug_player_state(NULL, &app);
        bounce_debug_event_new_game(&tracker, NULL);
        bounce_debug_event_new_game(NULL, &app);
        bounce_debug_event_level_start(&tracker, NULL);
        bounce_debug_event_level_start(NULL, &app);
        bounce_debug_event_level_complete(&tracker, NULL);
        bounce_debug_event_level_complete(NULL, &app);
        bounce_debug_event_game_over(&tracker, NULL);
        bounce_debug_event_game_over(NULL, &app);
        bounce_debug_event_game_end(&tracker, NULL);
        bounce_debug_event_game_end(NULL, &app);
        bounce_debug_event_respawn(&tracker, NULL);
        bounce_debug_event_respawn(NULL, &app);
        bounce_debug_tracker_set_sink(NULL, NULL);
        bounce_debug_tracker_set_sink(&tracker, NULL);
        bounce_debug_tracker_reseed(NULL, &app);
        bounce_debug_tracker_reseed(&tracker, NULL);
        bounce_debug_tracker_init(NULL, BOUNCE_DEBUG_LEVEL_VERBOSE, NULL);
        bounce_debug_level_from_env(NULL);
    }
    got = debug_capture(BOUNCE_DEBUG_LEVEL_STATE, buffer, sizeof buffer,
        debug_body_state);
    if (strstr(buffer, "[NBB-SCORE] tick=18420 500 -> 1000\n") == NULL
        || strstr(buffer, "[NBB-LIFE] tick=18420 3 -> 2\n") == NULL
        || strstr(buffer, "[NBB-BALL] tick=18420 size=12 -> 16\n") == NULL
        || strstr(buffer, "[NBB-DEATH] tick=18420 z=1 q=0\n") == NULL
        || strstr(buffer, "[NBB-PLAYER]") != NULL) {
        return -1;
    }

    /* Level 3: everything, including the player line. */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_VERBOSE, buffer, sizeof buffer,
        debug_body_verbose);
    if (got <= 0
        || strstr(
               buffer,
               "[NBB-PLAYER] tick=18420 flow=GAMEPLAY level=1 x=30 y=18"
               " vx=6 vy=-4 size=12 p=6 C=0 z=0 q=0 lives=3 cp=2,3,12\n"
           ) == NULL) {
        return -1;
    }

    /* --- 5. exact event text -------------------------------------------- */
    got = debug_capture(BOUNCE_DEBUG_LEVEL_EVENTS, buffer, sizeof buffer,
        debug_body_events);
    if (got <= 0) {
        return -1;
    }
    if (strcmp(
            buffer,
            "[NBB-EVENT] NEW_GAME tick=18420 level=1\n"
            "[NBB-EVENT] LEVEL_START tick=18420 level=1\n"
            "[NBB-CHECKPOINT] tick=18420 x=2 y=3 size=12\n"
            "[NBB-EVENT] DEATH tick=18420 lives=3\n"
            "[NBB-EVENT] RESPAWN tick=18420 level=1 lives=3\n"
            "[NBB-FLOW] GAMEPLAY -> GAME_OVER tick=18420\n"
            "[NBB-TILE] CRYSTAL id=7 at=2,3 tick=18420\n"
            "[NBB-TILE] WIDE_HOOP id=21 at=5,6 tick=18420\n"
        ) != 0) {
        return -1;
    }

    /* --- 6. the tick is the existing counter, not a private one ---------- */
    {
        BounceGame app;
        BounceDebugTracker tracker;
        FILE *sink = tmpfile();

        if (sink == NULL)
            return -1;
        memset(&app, 0, sizeof app);
        bounce_game_timer_init(&app.game_timer);
        if (bounce_debug_tick(&app) != 0u) {
            (void)fclose(sink);
            return -1;
        }
        app.game_timer.tick_entry_count = 4242u;
        if (bounce_debug_tick(&app) != 4242u) {
            (void)fclose(sink);
            return -1;
        }
        if (bounce_debug_tick(NULL) != 0u) {
            (void)fclose(sink);
            return -1;
        }
        (void)fclose(sink);
        bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_DISABLED, NULL);
        if (bounce_debug_want(&tracker, BOUNCE_DEBUG_LEVEL_EVENTS))
            return -1;
        bounce_debug_tracker_init(&tracker, BOUNCE_DEBUG_LEVEL_STATE, NULL);
        if (!bounce_debug_want(&tracker, BOUNCE_DEBUG_LEVEL_EVENTS)
            || !bounce_debug_want(&tracker, BOUNCE_DEBUG_LEVEL_STATE)
            || bounce_debug_want(&tracker, BOUNCE_DEBUG_LEVEL_VERBOSE)) {
            return -1;
        }
        if (bounce_debug_tracker_observe(NULL, &app) != -1
            || bounce_debug_tracker_observe(&tracker, NULL) != -1) {
            return -1;
        }
    }

    /* --- 7. every flow state has a name --------------------------------- */
    {
        static const BounceAppState states[] = {
            BOUNCE_APP_STATE_MENU,
            BOUNCE_APP_STATE_GAMEPLAY,
            BOUNCE_APP_STATE_PAUSE,
            BOUNCE_APP_STATE_GAME_OVER,
            BOUNCE_APP_STATE_LEVEL_COMPLETE,
            BOUNCE_APP_STATE_SPLASH,
            BOUNCE_APP_STATE_ACTION_BOUNDARY,
            BOUNCE_APP_STATE_INSTRUCTIONS,
            BOUNCE_APP_STATE_HIGH_SCORE,
            BOUNCE_APP_STATE_LEVEL_SELECTION,
            BOUNCE_APP_STATE_GAMEPLAY_ENTRY,
            BOUNCE_APP_STATE_LEVEL_LOADED,
            BOUNCE_APP_STATE_SETTINGS,
            BOUNCE_APP_STATE_ABOUT,
            BOUNCE_APP_STATE_GAME_END
        };
        size_t state_index;

        for (state_index = 0u;
             state_index < sizeof states / sizeof states[0];
             ++state_index) {
            if (strcmp(bounce_debug_flow_state_name(states[state_index]),
                       "UNKNOWN") == 0) {
                return -1;
            }
        }
        if (strcmp(bounce_debug_flow_state_name((BounceAppState)999),
                   "UNKNOWN") != 0) {
            return -1;
        }
    }

    /* --- 8. edge detection and the level-3 throttle --------------------- */
    if (debug_expect_edges() != 0)
        return -1;
    if (debug_expect_verbose_throttle() != 0)
        return -1;
    return 0;
}

