static int verify_all_level_lifecycle(void)
{
    static const char *const level_paths[] = {
        "src/main/resources/levels/J2MElvl.001",
        "src/main/resources/levels/J2MElvl.002",
        "src/main/resources/levels/J2MElvl.003",
        "src/main/resources/levels/J2MElvl.004",
        "src/main/resources/levels/J2MElvl.005",
        "src/main/resources/levels/J2MElvl.006",
        "src/main/resources/levels/J2MElvl.007",
        "src/main/resources/levels/J2MElvl.008",
        "src/main/resources/levels/J2MElvl.009",
        "src/main/resources/levels/J2MElvl.010",
        "src/main/resources/levels/J2MElvl.011"
    };
    BounceGame game;
    BounceApp level001_app;
    size_t level_index;
    BounceLevel *saved_level;
    BounceRuntimeLevelTiles *saved_runtime;
    BouncePlayer saved_player;
    BounceGameState saved_state;

    if (bounce_game_init(&level001_app) != 0
        || app_load_level001(
            &level001_app,
            "src/main/resources/levels/J2MElvl.001"
        ) != 0
        || validate_level001(level001_app.level) != 0) {
        bounce_game_shutdown(&level001_app);
        return -1;
    }
    bounce_game_shutdown(&level001_app);

    if (bounce_game_init(&game) != 0
        || bounce_game_enter_menu(&game) != 0)
        return -1;

    for (level_index = 0u;
         level_index < sizeof level_paths / sizeof level_paths[0];
         ++level_index) {
        int expected_level_id = (int)level_index + 1;
        int expected_x;
        int expected_y;
        int expected_ball_size;
        int expected_half_size;
        uint8_t structural_value;
        uint16_t runtime_value;
        uint16_t changed_value;

        if (level_index != 0u
            && bounce_game_apply_event(
                    &game,
                    BOUNCE_APP_EVENT_MENU
                ) != 0)
            goto failure;

        game.next_player_tick_ms = INT64_C(12345);
        if (bounce_game_start_level(
                &game,
                level_paths[level_index],
                expected_level_id,
                3
            ) != 0
            || game.state != BOUNCE_GAME_STATE_PLAYING
            || game.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || game.level_id != expected_level_id
            || game.flow.level_id != expected_level_id
            || game.level == NULL
            || game.runtime == NULL
            || game.level_path == NULL
            || strcmp(game.level_path, level_paths[level_index]) != 0
            || game.next_player_tick_ms != 0
            || game.l != 0
            || game.k != 0
            || game.v != 0
            || !game.player.initialized
            || !game.spawn.initialized
            || bounce_level_width(game.level) == 0u
            || bounce_level_height(game.level) == 0u
            || bounce_runtime_level_tiles_width(game.runtime)
                != bounce_level_width(game.level)
            || bounce_runtime_level_tiles_height(game.runtime)
                != bounce_level_height(game.level))
            goto failure;

        expected_x = (int)bounce_level_initial_x(game.level)
            * BOUNCE_TILE_SIZE + 6;
        expected_y = (int)bounce_level_initial_y(game.level)
            * BOUNCE_TILE_SIZE + 6;
        expected_ball_size = bounce_level_is_big_ball(game.level) == 0u
            ? BOUNCE_REGULAR_BALL_SIZE : 16;
        expected_half_size = expected_ball_size == BOUNCE_REGULAR_BALL_SIZE
            ? BOUNCE_REGULAR_BALL_P : 8;
        if (game.player.TODO_unkX != expected_x
            || game.player.TODO_unkY != expected_y
            || game.player.ballSize != expected_ball_size
            || game.player.p != expected_half_size
            || game.spawn.world_x != expected_x
            || game.spawn.world_y != expected_y
            || game.spawn.tile_x != (int)bounce_level_initial_x(game.level)
            || game.spawn.tile_y != (int)bounce_level_initial_y(game.level)
            || game.spawn.ball_size != expected_ball_size
            || game.spawn.half_size != expected_half_size
            || game.spawn.ball_mode
                != (expected_ball_size == BOUNCE_REGULAR_BALL_SIZE
                    ? BOUNCE_PLAYER_BALL_MODE_REGULAR
                    : BOUNCE_PLAYER_BALL_MODE_BIG))
            goto failure;

        if (bounce_level_get_tile(
                game.level,
                0,
                0,
                &structural_value
            ) != 0
            || bounce_runtime_level_tiles_get(
                game.runtime,
                0,
                0,
                &runtime_value
            ) != 0
            || runtime_value != (uint16_t)structural_value)
            goto failure;
        changed_value = (uint16_t)(runtime_value ^ UINT16_C(0x20));
        if (bounce_runtime_level_tiles_set(
                game.runtime,
                0,
                0,
                changed_value
            ) != 0
            || bounce_runtime_level_tiles_get(
                game.runtime,
                0,
                0,
                &runtime_value
            ) != 0
            || runtime_value != changed_value)
            goto failure;

        /* Runtime mutation must not write through to parsed level data. */
        if (bounce_level_get_tile(
                game.level,
                0,
                0,
                &structural_value
            ) != 0
            || structural_value == (uint8_t)changed_value)
            goto failure;
    }

    saved_level = game.level;
    saved_runtime = game.runtime;
    saved_player = game.player;
    saved_state = game.state;
    if (saved_level == NULL
        || saved_runtime == NULL
        || bounce_game_load_level(
                &game,
                "src/main/resources/levels/does-not-exist",
                99
            ) == 0
        || game.level != saved_level
        || game.runtime != saved_runtime
        || game.player.TODO_unkX != saved_player.TODO_unkX
        || game.player.TODO_unkY != saved_player.TODO_unkY
        || game.state != saved_state)
        goto failure;

    bounce_game_release_level(&game);
    if (game.level != NULL
        || game.runtime != NULL
        || game.level_path != NULL
        || game.player.initialized
        || game.spawn.initialized
        || game.l != 0
        || game.k != 0
        || game.v != 0
        || game.next_player_tick_ms != 0)
        goto failure;
    bounce_game_shutdown(&game);
    return 0;

failure:
    bounce_game_shutdown(&game);
    return -1;
}

static int verify_gameplay_dispatch(void)
{
    BounceApp app;
    int32_t before_velocity;
    int32_t before_cycle;
    int32_t before_y;

    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0
        || bounce_game_start_level(
            &app,
            BOUNCE_LEVEL001_PATH,
            0,
            3
        ) != 0
        || bounce_input_apply_source(
            &app.input,
            BOUNCE_INPUT_SOURCE_RIGHT_ARROW,
            true
        ) != 0)
        goto failure;

    before_velocity = app.player.horizontal_velocity;
    before_cycle = app.player.C;
    before_y = app.player.TODO_unkY;
    app.next_player_tick_ms = 0;
    if (app_update_game(&app) != 0
        || app.player.horizontal_velocity <= before_velocity
        || app.player.C == before_cycle
        || app.player.TODO_unkY < before_y)
        goto failure;

    /* The fixed tick also performs Java's horizontal LoadSpriteSheet hand-off. */
    app.player.TODO_unkX = 100;
    app.next_player_tick_ms = 0;
    if (app_update_game(&app) != 0
        || app.l != 3
        || app.v != 0)
        goto failure;

    if (bounce_game_apply_event(&app, BOUNCE_APP_EVENT_PAUSE) != 0)
        goto failure;
    before_velocity = app.player.horizontal_velocity;
    before_cycle = app.player.C;
    before_y = app.player.TODO_unkY;
    app.next_player_tick_ms = 0;
    if (app_update_game(&app) != 0
        || app.player.horizontal_velocity != before_velocity
        || app.player.C != before_cycle
        || app.player.TODO_unkY != before_y)
        goto failure;

    bounce_game_shutdown(&app);
    return 0;

failure:
    bounce_game_shutdown(&app);
    return -1;
}

