static int verify_camera_transform_invariants(void)
{
    uint8_t tiles[16u * 8u];
    BounceRuntimeLevelTiles *runtime;
    BounceApp camera;
    int32_t stage_world_x = 36;
    int32_t stage_world_y = 24;
    int32_t ball_world_x = 200;
    int32_t ball_world_y = 24;
    int32_t stage_before_x;
    int32_t stage_before_y;
    int32_t ball_before_x;
    int32_t ball_before_y;
    int32_t stage_after_x;
    int32_t stage_after_y;
    int32_t ball_after_x;
    int32_t ball_after_y;
    int32_t expected_stage_after_x;
    int32_t expected_stage_after_y;
    int32_t expected_ball_after_x;
    int32_t expected_ball_after_y;
    int32_t saved_world_x;
    bool collision_before;
    bool collision_after;

    memset(tiles, 0, sizeof tiles);
    tiles[2u * 16u + 3u] = 1u;
    if (create_synthetic_runtime(16u, 8u, tiles, &runtime) != 0)
        return -1;
    memset(&camera, 0, sizeof camera);
    camera.flow.state = BOUNCE_APP_STATE_GAMEPLAY;
    camera.runtime = runtime;
    camera.player.TODO_unkX = ball_world_x;
    camera.player.TODO_unkY = ball_world_y;
    camera.player.ballSize = BOUNCE_REGULAR_BALL_SIZE;
    camera.player.p = BOUNCE_REGULAR_BALL_P;

    camera.l = 0;
    camera.k = 0;
    if (app_world_to_screen(
            &camera,
            stage_world_x,
            stage_world_y,
            &stage_before_x,
            &stage_before_y
        ) != 0
        || app_world_to_screen(
            &camera,
            ball_world_x,
            ball_world_y,
            &ball_before_x,
            &ball_before_y
        ) != 0)
        goto failure;
    collision_before = bounce_collision_query(
        (int)(3 * BOUNCE_TILE_SIZE + 6),
        (int)(2 * BOUNCE_TILE_SIZE + 6),
        BOUNCE_REGULAR_BALL_P,
        runtime
    );

    saved_world_x = camera.player.TODO_unkX;
    camera.player.TODO_unkX = 2000;
    camera.player.TODO_unkY = 110;
    if (app_update_camera_for_width(&camera, 112) != 0
        || camera.player.TODO_unkX != 2000
        || camera.player.TODO_unkY != 110
        || camera.l != 99
        || camera.k != 7
        || app_world_to_screen(
            &camera,
            stage_world_x,
            stage_world_y,
            &stage_after_x,
            &stage_after_y
        ) != 0
        || app_world_to_screen(
            &camera,
            ball_world_x,
            ball_world_y,
            &ball_after_x,
            &ball_after_y
        ) != 0)
        goto failure;
    expected_stage_after_x = java_int32_add(
        java_int32_add(
            stage_world_x,
            -(camera.l * BOUNCE_TILE_SIZE)
        ),
        camera.v
    );
    expected_stage_after_y = java_int32_add(
        stage_world_y,
        -(camera.k * BOUNCE_TILE_SIZE)
    );
    expected_ball_after_x = java_int32_add(
        java_int32_add(
            ball_world_x,
            -(camera.l * BOUNCE_TILE_SIZE)
        ),
        camera.v
    );
    expected_ball_after_y = java_int32_add(
        ball_world_y,
        -(camera.k * BOUNCE_TILE_SIZE)
    );
    if (stage_after_x != expected_stage_after_x
        || stage_after_y != expected_stage_after_y
        || ball_after_x != expected_ball_after_x
        || ball_after_y != expected_ball_after_y)
        goto failure;
    collision_after = bounce_collision_query(
        (int)(3 * BOUNCE_TILE_SIZE + 6),
        (int)(2 * BOUNCE_TILE_SIZE + 6),
        BOUNCE_REGULAR_BALL_P,
        runtime
    );
    if (collision_before != collision_after
        || stage_after_x - stage_before_x
            != ball_after_x - ball_before_x
        || stage_after_y - stage_before_y
            != ball_after_y - ball_before_y
        || stage_after_x - ball_after_x
            != stage_world_x - ball_world_x
        || stage_after_y - ball_after_y
            != stage_world_y - ball_world_y)
        goto failure;

    camera.l = 0;
    camera.k = 0;
    camera.v = 0;
    camera.player.TODO_unkX = saved_world_x;
    camera.player.TODO_unkY = 6;
    if (app_camera_needs_update(&camera))
        goto failure;
    camera.player.TODO_unkY = 90;
    if (app_camera_needs_update(&camera))
        goto failure;
    camera.player.TODO_unkY = 91;
    if (!app_camera_needs_update(&camera))
        goto failure;

    bounce_runtime_level_tiles_destroy(runtime);
    return 0;

failure:
    bounce_runtime_level_tiles_destroy(runtime);
    return -1;
}

