/*
 * Count the pixels that differ between two same-sized logical surfaces.
 *
 * This is the non-fragile way to assert that two renders of the same scene
 * differ only where the ball was drawn: it bounds the difference by an area
 * instead of assuming that any particular coordinate is non-background, which
 * would depend on the decoded atlas alpha at that pixel.
 */
static int surface_pixel_diff_count(
    const BounceSurface *left,
    const BounceSurface *right,
    int *count_out
)
{
    int w;
    int h;
    int x;
    int y;
    int count = 0;

    if (left == NULL || right == NULL || count_out == NULL)
        return -1;
    if (bounce_surface_width(left) != bounce_surface_width(right)
        || bounce_surface_height(left) != bounce_surface_height(right))
        return -1;
    w = (int)bounce_surface_width(left);
    h = (int)bounce_surface_height(left);
    for (y = 0; y < h; ++y) {
        for (x = 0; x < w; ++x) {
            uint32_t a = 0u;
            uint32_t b = 0u;
            if (bounce_surface_get_pixel(left, x, y, &a) != 0
                || bounce_surface_get_pixel(right, x, y, &b) != 0)
                return -1;
            if (a != b)
                count++;
        }
    }
    *count_out = count;
    return 0;
}

/*
 * Render one level and the live ball through the production draw_player_ball()
 * seam, then compare the resulting ball pixels against the regular-only sprite
 * path that existed before this boundary.
 *
 * ball_size / half_size are supplied rather than hardcoded so the same harness
 * expresses both source states: f.java:169-171 (16, 8) and f.java:210-212
 * (12, 6). digest_out receives the whole-scene digest so the caller can also
 * assert that the two ball states produce different frames.
 */
/*
 * Bounding box of the non-transparent pixels in a logical surface.
 *
 * This measures where a sprite actually landed without asserting that any
 * particular coordinate is opaque, which would depend on the decoded atlas
 * alpha. Returns 1 with an empty box when the surface has no visible pixel.
 */
static int surface_opaque_bbox(
    const BounceSurface *surface,
    int *x_out,
    int *y_out,
    int *w_out,
    int *h_out
)
{
    int w;
    int h;
    int x;
    int y;
    int min_x = 0;
    int min_y = 0;
    int max_x = -1;
    int max_y = -1;

    if (surface == NULL
        || x_out == NULL
        || y_out == NULL
        || w_out == NULL
        || h_out == NULL)
        return -1;
    w = (int)bounce_surface_width(surface);
    h = (int)bounce_surface_height(surface);
    for (y = 0; y < h; ++y) {
        for (x = 0; x < w; ++x) {
            uint32_t pixel = 0u;
            if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0)
                return -1;
            if (((pixel >> 24) & 0xffu) == 0u)
                continue;
            if (max_x < 0) {
                min_x = x;
                min_y = y;
                max_x = x;
                max_y = y;
            } else {
                if (x < min_x)
                    min_x = x;
                if (x > max_x)
                    max_x = x;
                if (y < min_y)
                    min_y = y;
                if (y > max_y)
                    max_y = y;
            }
        }
    }
    *x_out = min_x;
    *y_out = min_y;
    *w_out = max_x < 0 ? 0 : max_x - min_x + 1;
    *h_out = max_y < 0 ? 0 : max_y - min_y + 1;
    return 0;
}

static int verify_camera_level_render(
    const char *path,
    const BounceVisualAssets *visuals,
    int ball_size,
    int half_size,
    unsigned long *digest_out
)
{
    BounceLevel *level = NULL;
    BounceRuntimeLevelTiles *runtime = NULL;
    BounceSurface *surface;
    BounceRenderer *renderer;
    BounceSurface *ball_only;
    BounceSurface *regular_only;
    BounceRenderer *ball_only_renderer;
    BounceRenderer *regular_only_renderer;
    RenderTrace trace;
    BounceApp app;
    int diff_count = 0;
    int failed = 0;

    if (path == NULL || visuals == NULL)
        return -1;
    if (bounce_level_load_file(path, &level) != BOUNCE_LEVEL_LOAD_OK
        || level == NULL)
        goto failure;
    runtime = bounce_runtime_level_tiles_create(level);
    if (runtime == NULL)
        goto failure;
    surface = bounce_surface_create();
    if (surface == NULL)
        goto failure;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        goto failure;
    }
    memset(&app, 0, sizeof app);
    memset(&trace, 0, sizeof trace);
    trace.enabled = true;
    app.runtime = runtime;
    app.visuals = (BounceVisualAssets *)visuals;
    app.render_trace = &trace;
    app.player.TODO_unkX = 200;
    app.player.TODO_unkY = 30;
    app.player.ballSize = ball_size;
    app.player.p = half_size;
    app.l = 3;
    /*
     * app.k must admit CAMERA_DIAGNOSTIC_TILE_Y inside the production draw
     * window [k .. k+7] (b.java:603-605), otherwise the probe tile is never
     * rasterised and stage_seen cannot be observed. k = 0 is the camera seed
     * value (e.java:131) and a multiple of BOUNCE_CAMERA_VERTICAL_STEP, so it
     * is a camera state the game can actually reach; the previously used k = 2
     * was not. Only the two y expectations move, because the transform under
     * test is unchanged: stage 1*12 - 0*12 = 12 and ball 30 - 0*12 = 30.
     * l = 3 already admits x = 3 in [l .. l+12] = [3 .. 15], and the ball
     * anchor x = 162 still exceeds the 128-wide surface, so the sprite
     * comparison below stays attributable to the ball alone.
     */
    app.k = 0;
    app.v = -2;
    if (draw_level_grid(renderer, &app) != 0
        || draw_player_ball(renderer, &app) != 0
        || !trace.stage_seen
        || !trace.ball_seen
        || trace.stage_actual_x != -2
        || trace.stage_actual_y != 12
        || trace.ball_actual_x != 162
        || trace.ball_actual_y != 30) {
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        goto failure;
    }

    /*
     * Ball-only comparison.
     *
     * The traced scene position above is intentionally off-surface for this
     * fixture (ball_actual_x is 162 on a 128-wide logical surface), so it
     * exercises the camera expression and the trace but never rasterises a
     * ball pixel. The sprite comparison therefore uses a fixed on-surface
     * anchor, which keeps the two draws attributable to the ball alone: both
     * surfaces start fully transparent, the grid is not drawn, and a fully
     * transparent source pixel is skipped by the blitter, so every differing
     * pixel is a ball pixel.
     *
     * The regular state must reproduce the pre-existing regular-only path
     * exactly. The big-ball state must differ, and every difference must fall
     * inside the union of the two sprite boxes, which is what f.java:754's
     * 16x16 Mirror16x16Tile and f.java:210-212's 12x12 tile can produce.
     * Bounding by area rather than probing a named pixel keeps this independent
     * of the decoded atlas alpha.
     */
    ball_only = bounce_surface_create();
    regular_only = bounce_surface_create();
    if (ball_only == NULL || regular_only == NULL) {
        if (ball_only != NULL)
            bounce_surface_destroy(ball_only);
        if (regular_only != NULL)
            bounce_surface_destroy(regular_only);
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        goto failure;
    }
    ball_only_renderer = bounce_renderer_create(ball_only);
    regular_only_renderer = bounce_renderer_create(regular_only);
    if (ball_only_renderer == NULL || regular_only_renderer == NULL) {
        if (ball_only_renderer != NULL)
            bounce_renderer_destroy(ball_only_renderer);
        if (regular_only_renderer != NULL)
            bounce_renderer_destroy(regular_only_renderer);
        bounce_surface_destroy(ball_only);
        bounce_surface_destroy(regular_only);
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        goto failure;
    }
    if (bounce_visual_assets_draw_player_ball(
            ball_only_renderer,
            visuals,
            ball_size,
            half_size,
            0,
            40,
            40
        ) != 0
        || bounce_visual_assets_draw_regular_ball(
            regular_only_renderer,
            visuals,
            40,
            40
        ) != 0
        || surface_pixel_diff_count(
            ball_only,
            regular_only,
            &diff_count
        ) != 0) {
        failed = 1;
    } else if (ball_size == BOUNCE_REGULAR_BALL_SIZE) {
        /* f.java:210-212 must stay value-identical to the old regular draw. */
        if (diff_count != 0)
            failed = 1;
    } else {
        /*
         * f.java:169-171 must select the 16x16 sprite, and e.java:217 must
         * place it at anchor - p == anchor - 8.
         *
         * The area bound alone cannot prove the offset: the 16x16 sprite
         * differs from the 12x12 one at -6 just as well as at -8. The
         * destination is therefore checked geometrically, by measuring the
         * visible box. b.java:754 builds a 16x16 Mirror16x16Tile whose every
         * row and column carries at least one opaque pixel, so the visible
         * box must be exactly the 16x16 destination rectangle anchored at
         * (40 - p, 40 - p). An offset of 6 would shift it by 2 px and fail.
         */
        int box_x = 0;
        int box_y = 0;
        int box_w = 0;
        int box_h = 0;

        if (surface_opaque_bbox(ball_only, &box_x, &box_y, &box_w, &box_h) != 0
            || box_x != 40 - half_size
            || box_y != 40 - half_size
            || box_w != 16
            || box_h != 16) {
            fprintf(
                stderr,
                "camera level render: big ball box (%d,%d,%d,%d) expected "
                "(%d,%d,16,16)\n",
                box_x,
                box_y,
                box_w,
                box_h,
                40 - half_size,
                40 - half_size
            );
            failed = 1;
        }
        if (diff_count <= 0 || diff_count > 16 * 16)
            failed = 1;
    }
    if (failed)
        fprintf(
            stderr,
            "camera level render: ball_size=%d half_size=%d ball diff=%d\n",
            ball_size,
            half_size,
            diff_count
        );

    /*
     * The reported digest is the ball-only surface, not the scene. The traced
     * scene anchor is off-surface for this fixture, so a scene digest could not
     * distinguish the two ball states; the ball-only surface is on-surface and
     * contains nothing but the sprite, which is exactly what the caller needs
     * to assert the two states differ.
     */
    if (digest_out != NULL)
        *digest_out = surface_digest(ball_only);

    bounce_renderer_destroy(ball_only_renderer);
    bounce_renderer_destroy(regular_only_renderer);
    bounce_surface_destroy(ball_only);
    bounce_surface_destroy(regular_only);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_runtime_level_tiles_destroy(runtime);
    bounce_level_destroy(level);
    return failed ? -1 : 0;

failure:
    bounce_runtime_level_tiles_destroy(runtime);
    bounce_level_destroy(level);
    return -1;
}

/*
 * Permanent regression for the production main-loop migration.
 *
 * Proves, in one deterministic pass and without a wall clock:
 *  A. a recorded START_LEVEL(1) is consumed by the production routing seam and
 *     the staged lifecycle reaches gameplay with the canonical timer started;
 *  B. the legacy app_update_game()/app_run_player_ticks() route is never taken
 *     while canonical gameplay is active, so no legacy physics can double up on
 *     a canonical tick;
 *  C. exactly one player tick and one physics step occur per canonical tick;
 *  D. the legacy deadline is never consumed by the canonical path;
 *  E. the canonical backend advances by exactly one nominal period per tick,
 *     i.e. no accumulator and no catch-up burst;
 *  F. leaving canonical gameplay releases the level/runtime and stops the
 *     timer, and a later start begins from fresh state;
 *  G. the legacy route is still reachable, so app_run_player_ticks() is intact
 *     reference behavior rather than dead code.
 */
/*
 * Drive the real interactive UI path only as far as the gameplay-entry record:
 * MENU -> (SELECT on the default row) -> ACTION_BOUNDARY -> GAMEPLAY_ENTRY with
 * START_LEVEL(1) recorded. No level, runtime, player, timer, or tick is created,
 * which is exactly the boundary the production routing seam consumes.
 */
static int drive_app_to_gameplay_entry_start_level(BounceApp *app)
{
    if (app == NULL)
        return -1;
    memset(app, 0, sizeof *app);
    if (bounce_game_init(app) != 0 || bounce_game_enter_menu(app) != 0)
        return -1;
    app->next_player_tick_ms = INT64_C(4321);
    /*
     * STEP 38-RESET -- the available-level count is SET to 0, not inherited.
     *
     * This helper's whole contract is "New Game stages level 1 straight into the
     * gameplay-entry boundary", which is BounceGame.java:241's `MaxLevels > 1` gate
     * evaluating FALSE. It used to satisfy that by reading whatever
     * bounce_app_flow_init() wrote, and the shipped default is now 2, so without
     * this the first SELECT lands on LEVEL_SELECTION instead and every caller of this
     * helper silently changes what it is testing.
     *
     * Setting it here rather than at each of the many call sites is the point: there
     * are a dozen of them across the resume, arrival, cadence and hoop checks, and a
     * helper whose precondition depends on a global default is a helper that breaks
     * the next time that default moves.
     */
    if (bounce_app_flow_set_available_level_count(&app->flow, 0u) != 0
        || bounce_ui_shell_handle_press(
            &app->flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(app) != 0)
        return -1;
    if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app->state != BOUNCE_GAME_STATE_GAMEPLAY_ENTRY
        || app->flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_app_flow_pending_level_id(&app->flow)
            != BOUNCE_APP_FIRST_LEVEL_ID
        || app->level != NULL
        || app->runtime != NULL
        || app->player.initialized
        || bounce_game_timer_is_started(&app->game_timer)
        || app->next_player_tick_ms != INT64_C(4321))
        return -1;
    return 0;
}

/*
 * Count surface pixels that differ from one flat colour. Every screen this
 * milestone adds fills a flat 0xff121a30 background first and then draws a
 * panel, border, and text on top, so a non-zero count proves the screen really
 * rendered rather than merely reaching its state.
 */
static long surface_pixel_count_other_than(
    const BounceSurface *surface,
    uint32_t color
)
{
    long count = 0;
    int width;
    int height;
    int x;
    int y;

    if (surface == NULL)
        return -1;
    width = (int)bounce_surface_width(surface);
    height = (int)bounce_surface_height(surface);
    for (y = 0; y < height; ++y) {
        for (x = 0; x < width; ++x) {
            uint32_t pixel = 0u;

            if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0)
                return -1;
            if (pixel != color)
                ++count;
        }
    }
    return count;
}

/*
 * NATIVE EXTENSION verification.
 *
 * Covers only the screens this milestone added: the two native menu rows, the
 * Settings destination and its four pages, the About destination, the existing
 * Continue-unavailable boundary, and the production Level Select range 1..11.
 * It asserts navigation, boundedness, and non-wrapping behavior; it does not
 * claim any of it is source-backed.
 */
/*
 * Native language presentation verification.
 *
 * Covers exactly what this milestone changed: that the default English resource
 * is presented as "EN" and never as its "xx" filename token, that the four
 * recovered resources keep their real identity, that Indonesian is offered as a
 * NATIVE EXTENSION with no resource file, that selecting it actually switches
 * the native strings at runtime, that selecting English restores them, and that
 * a fresh flow is always English. Gameplay, physics, collision, camera, and
 * level loading are not touched here.
 */
static int verify_native_language_presentation(void)
{
    BounceAppFlow flow;
    unsigned int index;
    int key;

    /* A fresh flow must be the default English resource, index 0. */
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    if (flow.state != BOUNCE_APP_STATE_SPLASH
        || flow.settings.applied_language_index != 0u
        || flow.settings.language_index != 0u
        || bounce_app_flow_settings_applied_language_index(&flow) != 0u
        || bounce_locale_default_language() != BOUNCE_LANGUAGE_EN
        || bounce_locale_active_language() != BOUNCE_LANGUAGE_EN)
        return -1;

    /* The default resource is shown as EN, and XX is never shown to the user. */
    /*
     * Compact user-facing labels. These are display only: the resource identity
     * asserted further below is still the full /lang.xx, /lang.zh-CN,
     * /lang.zh-TW and /lang.th-TH path, so nothing was renamed.
     */
    if (strcmp(bounce_locale_language_label(BOUNCE_LANGUAGE_EN), "EN") != 0
        || strcmp(bounce_locale_language_label(BOUNCE_LANGUAGE_ID), "ID") != 0
        || strcmp(
               bounce_locale_language_label(BOUNCE_LANGUAGE_ZH_CN),
               "CN") != 0
        || strcmp(
               bounce_locale_language_label(BOUNCE_LANGUAGE_ZH_TW),
               "TW") != 0
        || strcmp(
               bounce_locale_language_label(BOUNCE_LANGUAGE_TH_TH),
               "TH") != 0
        || bounce_locale_language_label(BOUNCE_LANGUAGE_COUNT) != NULL)
        return -1;
    for (index = 0u; index < (unsigned int)BOUNCE_LANGUAGE_COUNT; ++index) {
        const char *label = bounce_locale_language_label((BounceLanguage)index);

        /* Every label is exactly two characters, which is what makes the list
           visually even at 128x128. */
        if (label == NULL || strlen(label) != 2u)
            return -1;
    }
    for (index = 0u; index < (unsigned int)BOUNCE_LANGUAGE_COUNT; ++index) {
        const char *label = bounce_locale_language_label((BounceLanguage)index);

        if (label == NULL || strstr(label, "XX") != NULL
            || strstr(label, "xx") != NULL)
            return -1;
    }

    /* Every screen label the user sees must be free of the XX token too. */
    if (strstr(bounce_ui_shell_menu_label(0u), "XX") != NULL
        || strstr(bounce_ui_shell_action_label(BOUNCE_MENU_ACTION_NEW_GAME),
                  "XX") != NULL)
        return -1;

    /* The four ORIGINAL SOURCE-BACKED resources keep their real identity. */
    if (!bounce_locale_is_recovered_resource(BOUNCE_LANGUAGE_EN)
        || !bounce_locale_is_recovered_resource(BOUNCE_LANGUAGE_ZH_CN)
        || !bounce_locale_is_recovered_resource(BOUNCE_LANGUAGE_ZH_TW)
        || !bounce_locale_is_recovered_resource(BOUNCE_LANGUAGE_TH_TH)
        || bounce_locale_is_recovered_resource(BOUNCE_LANGUAGE_ID)
        || strcmp(
               bounce_locale_resource_name(BOUNCE_LANGUAGE_EN),
               "/lang.xx") != 0
        || strcmp(
               bounce_locale_resource_name(BOUNCE_LANGUAGE_ZH_CN),
               "/lang.zh-CN") != 0
        || strcmp(
               bounce_locale_resource_name(BOUNCE_LANGUAGE_ZH_TW),
               "/lang.zh-TW") != 0
        || strcmp(
               bounce_locale_resource_name(BOUNCE_LANGUAGE_TH_TH),
               "/lang.th-TH") != 0
        || bounce_locale_resource_name(BOUNCE_LANGUAGE_ID) != NULL)
        return -1;

    /*
     * Every key must resolve in ALL FIVE languages, and each non-default language
     * must be distinguishable from English somewhere, otherwise selecting it
     * would be unobservable.
     */
    for (key = 0; key < (int)BOUNCE_LOCALE_KEY_COUNT; ++key) {
        const BounceLocaleKey locale_key = (BounceLocaleKey)key;
        unsigned int language;

        for (language = 0u; language < (unsigned int)BOUNCE_LANGUAGE_COUNT;
             ++language) {
            const char *text = bounce_locale_text(
                (BounceLanguage)language,
                locale_key);

            if (text == NULL || text[0] == '\0')
                return -1;
        }
    }
    for (index = 1u; index < (unsigned int)BOUNCE_LANGUAGE_COUNT; ++index) {
        unsigned int differing = 0u;

        for (key = 0; key < (int)BOUNCE_LOCALE_KEY_COUNT; ++key) {
            if (strcmp(
                    bounce_locale_text((BounceLanguage)index, (BounceLocaleKey)key),
                    bounce_locale_text(BOUNCE_LANGUAGE_EN, (BounceLocaleKey)key)) != 0)
                ++differing;
        }
        if (differing < 20u)
            return -1;
    }
    /* Simplified and Traditional must not be the same table. */
    if (strcmp(
            bounce_locale_text(BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_SETTINGS),
            bounce_locale_text(BOUNCE_LANGUAGE_ZH_TW, BOUNCE_LOCALE_SETTINGS)) == 0)
        return -1;
    if (strcmp(
            bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_NEW_GAME),
            "NEW GAME") != 0
        || strcmp(
               bounce_locale_text(BOUNCE_LANGUAGE_ID, BOUNCE_LOCALE_NEW_GAME),
               "GAME BARU") != 0
        || strcmp(
               bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_EXIT),
               "EXIT") != 0
        || strcmp(
               bounce_locale_text(BOUNCE_LANGUAGE_ID, BOUNCE_LOCALE_EXIT),
               "KELUAR") != 0
        || strcmp(
               bounce_locale_text(
                   BOUNCE_LANGUAGE_ID,
                   BOUNCE_LOCALE_CONTINUE_NO_SAVE_DATA),
               "TIDAK ADA SIMPANAN") != 0
        || strcmp(
               bounce_locale_text(
                   BOUNCE_LANGUAGE_ID,
                   BOUNCE_LOCALE_NOT_YET_IMPLEMENTED),
               "BELUM DIIMPLEMENTASIKAN") != 0)
        return -1;

    /*
     * The Indonesian Instructions text must be a real translation of the English
     * one: it must be its own string, keep the three recovered key placeholders,
     * and must not be a copy of the English.
     */
    {
        const char *en_body
            = bounce_locale_text(
                BOUNCE_LANGUAGE_EN,
                BOUNCE_LOCALE_INSTRUCTIONS_BODY);
        const char *id_body = bounce_locale_text(
            BOUNCE_LANGUAGE_ID,
            BOUNCE_LOCALE_INSTRUCTIONS_BODY);
        const char *en_prefix = bounce_locale_text(
            BOUNCE_LANGUAGE_EN,
            BOUNCE_LOCALE_INSTRUCTIONS_PREFIX);
        const char *id_prefix = bounce_locale_text(
            BOUNCE_LANGUAGE_ID,
            BOUNCE_LOCALE_INSTRUCTIONS_PREFIX);

        if (en_body == NULL || id_body == NULL
            || strcmp(en_body, id_body) == 0
            || strstr(id_body, "%0U") == NULL
            || strstr(id_body, "%1U") == NULL
            || strstr(id_body, "%2U") == NULL
            || en_prefix == NULL || id_prefix == NULL
            || strcmp(en_prefix, id_prefix) == 0
            || strstr(id_prefix, "%0U") == NULL
            || bounce_locale_instructions_text(BOUNCE_LANGUAGE_ID) == NULL
            || strcmp(
                   bounce_locale_instructions_text(BOUNCE_LANGUAGE_ID),
                   id_body) != 0)
            return -1;
    }

    /*
     * All five languages now resolve from their OWN table. This replaces the
     * earlier contract, which required an undecoded language to fall back to
     * English as a whole; that fallback is still the safety net for a missing
     * entry, but no language is expected to reach it.
     *
     * The Chinese and Thai text is TEMPORARY TEST STRINGS. It is not decoded
     * from lang.zh-CN, lang.zh-TW or lang.th-TH, those files are untouched, and
     * no localization decoder exists.
     */
    if (bounce_locale_text(BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LOCALE_NEW_GAME)
            == bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_NEW_GAME)
        || bounce_locale_text(BOUNCE_LANGUAGE_TH_TH, BOUNCE_LOCALE_EXIT)
            == bounce_locale_text(BOUNCE_LANGUAGE_EN, BOUNCE_LOCALE_EXIT)
        || bounce_locale_text((BounceLanguage)-1, BOUNCE_LOCALE_EXIT) != NULL
        || bounce_locale_text(
               BOUNCE_LANGUAGE_COUNT,
               BOUNCE_LOCALE_EXIT) != NULL
        || bounce_locale_text(
               BOUNCE_LANGUAGE_EN,
               (BounceLocaleKey)BOUNCE_LOCALE_KEY_COUNT) != NULL)
        return -1;

    /*
     * Reaching the Language screen through the real menu, exactly as a user
     * does: splash out, three rows down to Settings, open, three rows down to
     * Language, open.
     */
    while (bounce_app_flow_tick(&flow) == 0
           && flow.state == BOUNCE_APP_STATE_SPLASH) {
        /* run the splash out so the menu is reachable */
    }
    if (flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 3u
        || bounce_app_flow_menu_row_for_selection(&flow, 3u) != 4u
        /* The shell press performs the select itself. */
        || bounce_ui_shell_handle_press(
               &flow,
               BOUNCE_UI_INPUT_SELECT) != 0
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_SETTINGS
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT)
        return -1;
    for (index = 0u; index < BOUNCE_SETTINGS_ROW_LANGUAGE; ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_page(&flow)
            != BOUNCE_SETTINGS_PAGE_LANGUAGE
        || bounce_app_flow_settings_list_count(&flow)
            != BOUNCE_LANGUAGE_RESOURCE_COUNT)
        return -1;

    /* Highlight alone must not change the language. */
    for (index = 0u; index < (unsigned int)BOUNCE_LANGUAGE_ID; ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID
        || bounce_app_flow_settings_applied_language_index(&flow) != 0u)
        return -1;

    /* Selecting it applies Indonesian, and the menu really changes. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID)
        return -1;
    bounce_locale_set_active_language(
        (BounceLanguage)bounce_app_flow_settings_applied_language_index(
            &flow));
    if (bounce_locale_active_language() != BOUNCE_LANGUAGE_ID
        || strcmp(bounce_ui_shell_menu_label(1u), "GAME BARU") != 0
        || strcmp(bounce_ui_shell_menu_label(2u), "SKOR TERTINGGI") != 0
        || strcmp(bounce_ui_shell_menu_label(3u), "PETUNJUK") != 0
        || strcmp(bounce_ui_shell_menu_label(4u), "PENGATURAN") != 0
        || strcmp(bounce_ui_shell_menu_label(5u), "TENTANG") != 0
        || strcmp(bounce_ui_shell_menu_label(6u), "KELUAR") != 0
        || strstr(bounce_ui_shell_instructions_text(), "Antar bola") == NULL)
        return -1;

    /* Row order and count are identical in both languages. */
    if (BOUNCE_MENU_ROW_COUNT != 7u
        || bounce_ui_shell_menu_label(BOUNCE_MENU_ROW_COUNT) != NULL)
        return -1;

    /*
     * Back out of the page, then switch back to English through the same path.
     * Back always returns the root selection to the top, so Language has to be
     * walked to again and the language row walked up to the first entry.
     */
    if (bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_settings_selected_index(&flow) != 0u
        || bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_page(&flow)
            != BOUNCE_SETTINGS_PAGE_DISPLAY
        || bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_selected_index(&flow) != 0u)
        return -1;
    for (index = 0u; index < BOUNCE_SETTINGS_ROW_LANGUAGE;
         ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_page(&flow)
            != BOUNCE_SETTINGS_PAGE_LANGUAGE
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID)
        return -1;
    for (index = 0u; index < (unsigned int)BOUNCE_LANGUAGE_ID; ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_UP) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_language_index(&flow) != 0u
        || bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_applied_language_index(&flow) != 0u)
        return -1;
    bounce_locale_set_active_language(
        (BounceLanguage)bounce_app_flow_settings_applied_language_index(
            &flow));
    if (strcmp(bounce_ui_shell_menu_label(1u), "NEW GAME") != 0
        || strcmp(bounce_ui_shell_menu_label(6u), "EXIT") != 0)
        return -1;

    /*
     * Back all the way out without crashing or returning an error: the page
     * returns to the Settings root, and the root returns to MAIN_MENU. A third
     * Back is not a valid Settings operation and must be refused, not accepted.
     */
    if (bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_settings_back(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_settings_back(&flow) != -1)
        return -1;

    /*
     * REGRESSION: re-entering Settings must not undo the chosen language. Both
     * Settings entry points reset the navigation only. The check switches to
     * Indonesian first, because asserting the English value would pass even if
     * the language were wiped on every re-entry.
     */
    if (flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_settings_applied_language_index(&flow) != 0u)
        return -1;
    /*
     * D-05 -- NO navigation is needed to come back to Settings, because the
     * highlight is restored there. The three DOWN moves this used to make
     * assumed the menu highlight had been reset to 0 on entry; with N preserved
     * (BounceGame.java:221 writes it on SELECT, :129 restores it on ShowMainMenu)
     * Settings is still highlighted, so three more moves would clamp at 5 --
     * About -- and this block would open the wrong screen.
     *
     * This is the rule paying for itself in a real navigation: Java leaves the
     * player on the row they entered Settings from, so re-entering it takes no
     * movement at all.
     */
    if (flow.menu.selected_index != 3u
        || bounce_app_flow_menu_row_for_selection(&flow, 3u) != 4u
        || bounce_ui_shell_handle_press(
               &flow,
               BOUNCE_UI_INPUT_SELECT) != 0
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT)
        return -1;
    for (index = 0u; index < BOUNCE_SETTINGS_ROW_LANGUAGE;
         ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_page(&flow)
            != BOUNCE_SETTINGS_PAGE_LANGUAGE)
        return -1;
    for (index = 0u; index < (unsigned int)BOUNCE_LANGUAGE_ID; ++index) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID)
        return -1;
    if (bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_back(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID)
        return -1;

    /* Re-enter Settings from the menu: the choice must survive. */
    for (index = 0u; index < 4u; ++index) {
        if (bounce_app_flow_menu_move(
                &flow,
                BOUNCE_MENU_DIRECTION_UP) != 0)
            return -1;
    }
    for (index = 0u; index < 3u; ++index) {
        if (bounce_app_flow_menu_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (flow.menu.selected_index != 3u
        || bounce_ui_shell_handle_press(
               &flow,
               BOUNCE_UI_INPUT_SELECT) != 0
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT)
        return -1;
    if (bounce_app_flow_settings_back(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_settings_applied_language_index(&flow)
            != (unsigned int)BOUNCE_LANGUAGE_ID)
        return -1;

    /* A fresh flow is English again: nothing is persisted. */
    bounce_locale_set_active_language(bounce_locale_default_language());
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    if (flow.settings.applied_language_index != 0u
        || bounce_app_flow_settings_applied_language_index(&flow) != 0u)
        return -1;
    return 0;
}

/*
 * STEP 13G-A -- the Level Complete Form.
 *
 * WHAT IS PROVEN HERE
 *   1. The five locale strings are exactly the values transcribed from the shipped
 *      Java resources, INCLUDING the embedded newline in both Chinese variants and
 *      the "%U" placeholder that the composition step replaces. Indonesian is
 *      asserted separately because it is a documented native extension with no
 *      lang.id and must never be presented as Java-original.
 *   2. The CONTINUE label resolves in all five languages and is byte-identical to
 *      the Java Translation.CONTINUE value in the three source-backed non-English
 *      locales (zh-CN, zh-TW, th-TH).
 *   3. The renderer succeeds for every language, for a regular and a two-digit level
 *      number, and for a zero and a large score -- so no composition overflows a
 *      line buffer and no locale fails to draw.
 *   4. A negative level number and a negative score are drawn as given rather than
 *      clamped or rejected, matching the source, which prints whatever int it holds.
 *   5. NULL surface and NULL renderer are refused.
 *
 * PIXELS ARE NOT INSPECTED. This asserts that the render SUCCEEDS and that the
 * content inputs are right; it makes no claim about how the result looks, because
 * the original Form's pixel geometry is not derivable from the recovered source
 * (reconciliation 13.51.15 and 13.51.18).
 */
static int verify_level_complete_form(void)
{
    static const struct {
        BounceLanguage language;
        const char *expected;
        int java_backed;
    } cases[] = {
        { BOUNCE_LANGUAGE_EN, "Level %U completed!", 1 },
        { BOUNCE_LANGUAGE_ID, "Level %U selesai!", 0 },
        { BOUNCE_LANGUAGE_TH_TH, "ผ่านระดับ %U!", 1 },
        { BOUNCE_LANGUAGE_ZH_CN, "级别%U\n已完成", 1 },
        { BOUNCE_LANGUAGE_ZH_TW, "等級%U\n已完成！", 1 }
    };
    static const struct {
        BounceLanguage language;
        const char *expected;
    } continue_labels[] = {
        { BOUNCE_LANGUAGE_EN, "CONTINUE" },
        { BOUNCE_LANGUAGE_ID, "LANJUTKAN" },
        { BOUNCE_LANGUAGE_TH_TH, "เล่นต่อ" },
        { BOUNCE_LANGUAGE_ZH_CN, "继续" },
        { BOUNCE_LANGUAGE_ZH_TW, "繼續" }
    };
    BounceSurface *surface = NULL;
    BounceRenderer *renderer = NULL;
    BounceLanguage original;
    size_t index;
    int rc = -1;

    original = bounce_locale_active_language();
    surface = bounce_surface_create();
    if (surface == NULL)
        goto cleanup;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL)
        goto cleanup;

    for (index = 0u; index < sizeof cases / sizeof cases[0]; ++index) {
        static const int levels[] = { 1, 2, 11 };
        static const int32_t scores[] = { 0, 9400, 1234567, -1 };
        size_t level_index;
        size_t score_index;

        bounce_locale_set_active_language(cases[index].language);
        if (strcmp(
                bounce_locale_text(
                    cases[index].language,
                    BOUNCE_LOCALE_LEVEL_COMPLETED
                ),
                cases[index].expected
            ) != 0)
            goto cleanup;
        /* The placeholder must survive in the stored string: the composition
         * step replaces it, the locale layer never does. */
        if (strstr(cases[index].expected, "%U") == NULL)
            goto cleanup;
        for (level_index = 0u;
             level_index < sizeof levels / sizeof levels[0];
             ++level_index) {
            for (score_index = 0u;
                 score_index < sizeof scores / sizeof scores[0];
                 ++score_index) {
                if (bounce_ui_shell_render_level_complete(
                        surface,
                        renderer,
                        levels[level_index],
                        scores[score_index]
                    ) != 0)
                    goto cleanup;
            }
        }
        /* A negative level number is drawn as given, not rejected. */
        if (bounce_ui_shell_render_level_complete(
                surface,
                renderer,
                -1,
                0
            ) != 0)
            goto cleanup;
    }

    for (index = 0u;
         index < sizeof continue_labels / sizeof continue_labels[0];
         ++index) {
        if (strcmp(
                bounce_locale_text(
                    continue_labels[index].language,
                    BOUNCE_LOCALE_CONTINUE
                ),
                continue_labels[index].expected
            ) != 0)
            goto cleanup;
    }

    /* The Indonesian row is a native extension and is asserted as such: it is the
     * only one of the five with no shipped resource file behind it. */
    bounce_locale_set_active_language(BOUNCE_LANGUAGE_ID);
    if (cases[1].java_backed != 0)
        goto cleanup;
    if (bounce_locale_resource_name(BOUNCE_LANGUAGE_ID) != NULL)
        goto cleanup;
    /*
     * Every case marked java_backed must have a shipped resource behind it, which
     * is what makes it a transcribed source string rather than an invention.
     * Indonesian is the only case with java_backed == 0 and is the only one whose
     * resource name is NULL, so this cross-checks the two flags against each other
     * in both directions.
     */
    for (index = 0u; index < sizeof cases / sizeof cases[0]; ++index) {
        bool backed = bounce_locale_resource_name(cases[index].language) != NULL;

        if (cases[index].java_backed != 0 && !backed)
            goto cleanup;
        if (cases[index].java_backed == 0 && backed)
            goto cleanup;
    }

    /*
     * A NULL surface or a NULL renderer must be refused, not dereferenced. Each
     * case is driven separately so a refusal of one cannot mask a regression in
     * the others, and the order is fixed so the assertion messages are stable.
     */
    bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
    if (bounce_ui_shell_render_level_complete(NULL, renderer, 1, 0) == 0)
        goto cleanup;
    if (bounce_ui_shell_render_level_complete(surface, NULL, 1, 0) == 0)
        goto cleanup;
    if (bounce_ui_shell_render_level_complete(NULL, NULL, 1, 0) == 0)
        goto cleanup;
    /* A NULL tracker-equivalent argument is not part of this renderer's
     * contract: it takes two plain values, so there is nothing further to
     * refuse. The pair (level, score) is asserted at its extremes above. */
    rc = 0;
cleanup:
    bounce_locale_set_active_language(original);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return rc;
}

/*
 * D-05 -- walk the main-menu highlight to the top row.
 *
 * Java keeps the player's row across a round trip through any sub-screen
 * (BounceGame.java:221 writes N on SELECT, :129 restores it in ShowMainMenu), so
 * a verifier that needs to reach a specific row has to navigate from wherever the
 * previous round trip left the highlight, exactly as a player would.
 *
 * The bound is the row count rather than the current index, so the walk clamps at
 * the top on the step that would pass it and the caller does not have to know
 * where it started. It returns -1 if the flow is not in the menu or a move is
 * refused, so a broken state is reported rather than silently ignored.
 */
static int bounce_app_flow_menu_walk_to_top(
    BounceAppFlow *flow,
    unsigned int *scratch
)
{
    unsigned int steps;

    if (flow == NULL || scratch == NULL)
        return -1;
    for (steps = 0u; steps < BOUNCE_MENU_ROW_COUNT; ++steps) {
        *scratch = steps;
        if (bounce_app_flow_menu_move(flow, BOUNCE_MENU_DIRECTION_UP) != 0)
            return -1;
    }
    return 0;
}

static int verify_native_extension_ui(void)
{
    BounceAppFlow flow;
    BounceSurface *surface;
    BounceRenderer *renderer;
    unsigned int index;
    unsigned int walk;
    int nonblank;

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    if (flow.state != BOUNCE_APP_STATE_SPLASH)
        return -1;
    for (index = 0u; index < BOUNCE_APP_SPLASH_TIMER_LIMIT + 1u; ++index) {
        if (bounce_app_flow_tick(&flow) != 0
            || flow.state != BOUNCE_APP_STATE_SPLASH)
            return -1;
    }
    if (bounce_app_flow_tick(&flow) != 1
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /*
     * Continue stays a visible but unavailable source-backed row. With no RMS
     * store implemented it is disabled and, exactly as in the original where
     * the item is absent from the list, it is not reachable by navigation. The
     * menu states the reason on screen; the unavailable action label still
     * exists for the future available-but-unsatisfiable case.
     */
    if (bounce_app_flow_menu_item_enabled(&flow, 0u)
        || bounce_app_flow_menu_row_for_selection(&flow, 0u) != 1u
        || bounce_app_flow_menu_row_for_selection(&flow, BOUNCE_MENU_ROW_COUNT)
            != BOUNCE_MENU_ROW_COUNT - 1u
        || strcmp(
               bounce_ui_shell_action_label(
                   BOUNCE_MENU_ACTION_CONTINUE_UNAVAILABLE),
               "CONTINUE UNAVAILABLE") != 0
        /*
         * STEP 38-RESET -- THE COUNT IS PINNED TO 0 HERE, because this assertion is
         * about the single-branch route and the shipped default now takes the other
         * one.
         *
         * The claim below is that when no level count is published, New game takes
         * the source's MaxLevels <= 1 branch (BounceGame.java:241-242) and records
         * START_LEVEL(1) at the action boundary instead of opening the list. That
         * claim is still true; what stopped being true is the unstated premise that
         * a fresh flow publishes no count.
         *
         * A new install now ships with levels 1 and 2 unlocked, so
         * available_level_count is 2 and this same press goes to Level Select. Left
         * alone the block would fail on `state != ACTION_BOUNDARY`, blaming the menu
         * for a change made to the defaults, and the MaxLevels <= 1 branch it was
         * written to cover would go untested. Pinning the count is what keeps the
         * assertion pointed at its own subject.
         *
         * The count-of-2 route is not abandoned here; verify_default_state() pins
         * the shipped value and verify_gameplay_entry_boundary() drives it end to
         * end, so both branches of the Java condition stay covered.
         */
        || bounce_app_flow_set_available_level_count(&flow, 0u) != 0
        || bounce_app_flow_available_level_count(&flow) != 0u
        || bounce_app_flow_menu_select(&flow)
            != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_ACTION_BOUNDARY
        || bounce_app_flow_pending_level_id(&flow)
            != BOUNCE_APP_FIRST_LEVEL_ID
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /* Exit is reachable as the last row and is the source's Command.EXIT. */
    if (flow.menu.selected_index != 0u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 5u
        || bounce_app_flow_menu_row_for_selection(&flow, 5u) != 6u
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_EXIT
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /*
     * Settings is row 4 and is a native extension. With Continue unavailable the
     * selection index is one below the row, so row 4 is selection index 3.
     */
    if (flow.menu.selected_index != 5u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 3u
        || bounce_app_flow_menu_row_for_selection(&flow, 3u) != 4u
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_SETTINGS
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_settings_selected_index(&flow) != 0u
        || bounce_app_flow_settings_list_count(&flow)
            != BOUNCE_SETTINGS_ROOT_ITEM_COUNT)
        return -1;

    /*
     * The Settings root list is bounded and never wraps. Walk every row by
     * count rather than by a hard-coded number, so adding a destination later
     * cannot silently leave this check asserting the wrong range.
     */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow) != 0u)
        return -1;
    for (index = 0u; index < BOUNCE_SETTINGS_ROOT_ITEM_COUNT; ++index) {
        if (bounce_app_flow_settings_selected_index(&flow) != index)
            return -1;
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    /* One move past the last row must clamp, never wrap. */
    if (bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_ROOT_ITEM_COUNT - 1u)
        return -1;

    /* Each root row opens exactly its own page, then Back returns to the root. */
    while (bounce_app_flow_settings_selected_index(&flow) > 0u) {
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_UP) != 0)
            return -1;
    }
    for (index = 0u; index < BOUNCE_SETTINGS_ROOT_ITEM_COUNT; ++index) {
        /*
         * Back from a page always returns the root selection to 0, so each
         * iteration walks down from the top rather than stepping once.
         */
        for (walk = 0u; walk < index; ++walk) {
            if (bounce_app_flow_settings_move(
                    &flow,
                    BOUNCE_MENU_DIRECTION_DOWN) != 0)
                return -1;
        }
        if (bounce_app_flow_settings_selected_index(&flow) != index)
            return -1;
        if (bounce_app_flow_settings_select(&flow) != 0
            || bounce_app_flow_settings_page(&flow)
                != (BounceSettingsPage)((int)index + 1)) {
            return -1;
        }
        if (bounce_app_flow_settings_back(&flow) != 0
            || bounce_app_flow_settings_page(&flow)
                != BOUNCE_SETTINGS_PAGE_ROOT
            || bounce_app_flow_settings_selected_index(&flow) != 0u)
            return -1;
    }

    /*
     * STEP 34-F-K: Display and Input remained read-only fact pages with no
     * navigable list. Audio did not, and now neither does Input: the numeric
     * keypad setting added to Input gives it a two-row list.
     *
     * THE INVARIANT IS NOT WEAKENED, IT IS SCOPED. This loop used to cover
     * DISPLAY..INPUT together and assert, for both, that the page reports zero
     * rows and that UP, DOWN and SELECT all fail. Display still satisfies that in
     * full and is still asserted here. Input no longer does, and cannot: a
     * setting the player cannot reach is not a setting, so asserting it would be
     * asserting the absence of the feature this change exists to add.
     *
     * Input is verified in its own block below, in the same shape as the Audio
     * one -- two rows, moving does not apply, SELECT applies -- so what replaced
     * the invariant is a real assertion rather than a removal.
     */
    flow.settings.page = BOUNCE_SETTINGS_PAGE_DISPLAY;
    if (bounce_app_flow_settings_list_count(&flow) != 0u
        || bounce_app_flow_settings_move(
               &flow,
               BOUNCE_MENU_DIRECTION_DOWN) != -1
        || bounce_app_flow_settings_move(
               &flow,
               BOUNCE_MENU_DIRECTION_UP) != -1
        || bounce_app_flow_settings_select(&flow) != -1)
        return -1;

    /*
     * NATIVE ADDITION -- the Input page's numeric-keypad setting, in the Audio
     * page's shape.
     *
     * THE SEQUENCE IS THE MIRROR OF THE AUDIO ONE BELOW RATHER THAN A COPY OF IT.
     * Audio starts ON, so "moving does not apply" there leaves it true; this block
     * starts OFF, so the same assertion has to leave it false. An earlier revision
     * copied the Audio assertions verbatim and asserted `!t9_enabled` after a move --
     * which is false when the value in force is OFF->ON is reversed, so the check
     * failed on correct code. The asymmetry is stated here rather than left to be
     * re-derived.
     *
     * STEP 38-RESET -- the starting value of this walk is now PINNED OFF rather than
     * inherited from the launch default, which is ON. See the block below.
     *
     * Two rows, OFF, highlight on row 0. Moving to OFF must not change anything.
     * SELECT applies the highlighted row. Moving back to ON without SELECT still
     * leaves it OFF. SELECT on ON turns it on. Moving past the end clamps rather
     * than wraps.
     */
    /*
     * STEP 38-RESET -- the keypad is PINNED OFF before the toggle mechanics run.
     *
     * This block walks ON -> OFF -> ON -> OFF to prove that moving the highlight
     * applies nothing and SELECT does. It used to start from the launch default,
     * which was OFF; the shipped default is now ON, so without the pin the very first
     * assertion below ("it is off") fails and the whole toggle walk is never reached.
     *
     * Starting from OFF is what makes the walk readable anyway: the first move to the
     * OFF row is then a genuine "select the other value" rather than a select of the
     * value already in force. Which value a NEW INSTALL starts on is a different
     * question and is asserted in verify_default_state(), which is where the shipped
     * defaults live.
     */
    if (bounce_app_flow_restore_persisted_t9(&flow, false) != 0)
        return -1;
    flow.settings.page = BOUNCE_SETTINGS_PAGE_INPUT;
    if (bounce_app_flow_settings_list_count(&flow)
            != BOUNCE_SETTINGS_T9_VALUE_COUNT
        || bounce_app_flow_settings_t9_enabled(&flow)
        || bounce_app_flow_settings_selected_index(&flow) != 0u)
        return -1;
    /* Moving the highlight applies nothing. */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_T9_ROW_OFF
        || bounce_app_flow_settings_t9_enabled(&flow))
        return -1;
    /* SELECT on the already-applied OFF row is a no-op, not a failure. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_t9_enabled(&flow))
        return -1;
    /* Moving to ON without SELECT still leaves it OFF. */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_T9_ROW_ON
        || bounce_app_flow_settings_t9_enabled(&flow))
        return -1;
    /* SELECT on ON turns it on. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || !bounce_app_flow_settings_t9_enabled(&flow))
        return -1;
    /* Past the end clamps, never wraps. */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_T9_ROW_ON
        || bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_T9_ROW_OFF)
        return -1;
    /* Turn it back off, so the rest of this verifier sees a fresh flow. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_t9_enabled(&flow))
        return -1;
    /*
     * AND PUT THE HIGHLIGHT BACK ON ROW 0, which the Audio block below relies on
     * when it asserts `selected_index == 0` on entering its page. Leaving the
     * highlight on row 1 here failed the whole check on correct code, because the
     * two page blocks share one flow. Moving without SELECT leaves the setting
     * OFF, so this restores both halves of the fresh state.
     */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_T9_ROW_ON
        || bounce_app_flow_settings_t9_enabled(&flow))
        return -1;

    /*
     * STEP 34-F-K -- the Audio ON/OFF setting. A fresh flow is ON; the page has
     * exactly two rows; moving the highlight does not change the applied value;
     * SELECT applies the highlighted row; and ON is restored by selecting row 0
     * again. The value is not persisted, so re-entering Settings keeps it
     * (reset_settings_navigation) while a fresh launch returns to ON.
     */
    flow.settings.page = BOUNCE_SETTINGS_PAGE_AUDIO;
    if (bounce_app_flow_settings_list_count(&flow)
            != BOUNCE_SETTINGS_AUDIO_VALUE_COUNT
        || !bounce_app_flow_settings_audio_enabled(&flow)
        || bounce_app_flow_settings_selected_index(&flow) != 0u)
        return -1;
    /* Moving to OFF must not apply anything by itself. */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_AUDIO_ROW_OFF
        || !bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    /* SELECT on OFF applies it. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    /* Moving back to ON without SELECT leaves it OFF. */
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_AUDIO_ROW_ON
        || bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    /* SELECT on ON applies it. Moving past the end is refused, not wrapped. */
    if (bounce_app_flow_settings_select(&flow) != 0
        || !bounce_app_flow_settings_audio_enabled(&flow)
        || bounce_app_flow_settings_move(
               &flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_AUDIO_ROW_ON
        || bounce_app_flow_settings_move(
               &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_move(
               &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_AUDIO_ROW_OFF)
        return -1;
    /* Navigation away and back keeps the session's choice, which is ON here. */
    if (bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT)
        return -1;
    flow.settings.page = BOUNCE_SETTINGS_PAGE_AUDIO;
    if (!bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    /* And OFF survives navigation too, which is the case that matters most:
     * leaving the page must not quietly turn audio back on. The highlight is on
     * row 0 at this point, so it must be moved to row 1 before SELECT applies
     * OFF. */
    if (bounce_app_flow_settings_move(
            &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    if (bounce_app_flow_settings_back(&flow) != 0)
        return -1;
    flow.settings.page = BOUNCE_SETTINGS_PAGE_AUDIO;
    if (bounce_app_flow_settings_audio_enabled(&flow))
        return -1;
    /* Restore ON so the rest of this verification sees the default. */
    if (bounce_app_flow_settings_move(
            &flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_select(&flow) != 0
        || !bounce_app_flow_settings_audio_enabled(&flow))
        return -1;

    /*
     * Language lists the four recovered resources plus Indonesian, bounded and
     * without wrap. The first four keep their real resource identity; the
     * Indonesian row is a NATIVE EXTENSION with no file and must report NULL
     * rather than a fabricated path.
     */
    flow.settings.page = BOUNCE_SETTINGS_PAGE_LANGUAGE;
    if (bounce_app_flow_settings_list_count(&flow)
            != BOUNCE_LANGUAGE_RESOURCE_COUNT
        || BOUNCE_LANGUAGE_RESOURCE_COUNT
            != BOUNCE_LANGUAGE_RECOVERED_COUNT + 1u
        || bounce_app_flow_language_resource_name(
               BOUNCE_LANGUAGE_RESOURCE_COUNT) != NULL)
        return -1;
    for (index = 0u; index < BOUNCE_LANGUAGE_RECOVERED_COUNT; ++index) {
        if (bounce_app_flow_language_resource_name(index) == NULL
            || bounce_app_flow_language_resource_name(index)[0] != '/')
            return -1;
    }
    if (bounce_app_flow_language_resource_name(
            BOUNCE_LANGUAGE_RECOVERED_COUNT) != NULL)
        return -1;
    if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || bounce_app_flow_settings_language_index(&flow) != 0u)
        return -1;
    for (index = 0u; index < BOUNCE_LANGUAGE_RESOURCE_COUNT; ++index) {
        if (bounce_app_flow_settings_language_index(&flow) != index)
            return -1;
        if (bounce_app_flow_settings_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0)
            return -1;
    }
    if (bounce_app_flow_settings_language_index(&flow)
            != BOUNCE_LANGUAGE_RESOURCE_COUNT - 1u
        || bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_back(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_settings_back(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /* Back from the Settings root returns to MAIN_MENU, as required. */
    if (bounce_app_flow_enter_settings(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_back(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_enter_settings(&flow) != 0
        || bounce_app_flow_return_to_menu(&flow) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /*
     * About is row 5, is a native extension, and only accepts Back.
     *
     * D-05 -- ONE move down, not four. The Settings round trips above now leave
     * the highlight on 3 (Settings) rather than resetting it, so a single DOWN
     * reaches 4, About. Four moves would clamp at 5 and open Exit instead. The
     * row being asserted is unchanged; only the distance to it moved, which is
     * the source's own behaviour: BounceGame.java:129 restores N, so the player
     * continues from the row they left.
     */
    if (flow.menu.selected_index != 3u
        || bounce_app_flow_menu_row_for_selection(&flow, 3u) != 4u
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 4u
        || bounce_app_flow_menu_row_for_selection(&flow, 4u) != 5u
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_ABOUT
        || flow.state != BOUNCE_APP_STATE_ABOUT
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_SELECT) != 0
        || flow.state != BOUNCE_APP_STATE_ABOUT
        || bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_BACK) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /*
     * Production Level Select range: 1..11 with no wrap and no invalid row. The
     * count is the shipped level count, and the model refuses anything higher.
     */
    if (bounce_app_flow_set_available_level_count(
            &flow,
            BOUNCE_APP_LAST_LEVEL_ID + 1) != -1
        || bounce_app_flow_set_available_level_count(
               &flow,
               BOUNCE_APP_LAST_LEVEL_ID) != 0
        || bounce_app_flow_available_level_count(&flow)
            != BOUNCE_APP_LAST_LEVEL_ID
        /*
         * D-05 -- the level List does not move N: its SELECT writes
         * level_selection.selected_index (BounceGame.java:218-219 takes the
         * currentList branch, which never reaches the `this.N = ...` assignment
         * at :221). So the menu highlight is still on 4 and has to be walked
         * back to the top before New Game can be selected again.
         */
        || bounce_app_flow_menu_walk_to_top(&flow, &walk) != 0
        || flow.menu.selected_index != 0u
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || flow.level_selection.selected_index != 0u)
        return -1;
    /* Eleven levels give valid selection indices 0..10. */
    for (index = 0u; index < BOUNCE_APP_LAST_LEVEL_ID - 1u; ++index) {
        if (bounce_app_flow_level_selection_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0
            || flow.level_selection.selected_index != index + 1u)
            return -1;
    }
    /*
     * Level 11 is the last row; one more DOWN must clamp, never wrap and never
     * reach an index that does not exist.
     */
    if (flow.level_selection.selected_index != BOUNCE_APP_LAST_LEVEL_ID - 1u
        || bounce_app_flow_level_selection_move(
               &flow,
               BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.level_selection.selected_index != BOUNCE_APP_LAST_LEVEL_ID - 1u
        || bounce_app_flow_level_selection_select(&flow) < 0
        || bounce_app_flow_pending_level_id(&flow) != BOUNCE_APP_LAST_LEVEL_ID)
        return -1;

    /*
     * Selecting leaves the list, so the upward walk is re-entered from the menu
     * rather than continuing in a state that no longer exists.
     */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_available_level_count(&flow)
            != BOUNCE_APP_LAST_LEVEL_ID
        /*
         * D-05 -- WALK BACK TO THE TOP FIRST. The About round trip left the
         * highlight on 4, which is Java's own behaviour: N was written on SELECT
         * (BounceGame.java:221) and restored on the way back (:129). New Game is
         * position 0, so the player moves there; before D-05 the highlight was
         * reset to 0 on menu entry and no walk was needed.
         *
         * The walk is bounded by the row count, so it clamps at the top rather
         * than needing the exact starting index spelled out twice -- the same
         * idiom the Settings-root walk below already uses.
         */
        || bounce_app_flow_menu_walk_to_top(&flow, &walk) != 0
        || flow.menu.selected_index != 0u
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || flow.level_selection.selected_index != 0u)
        return -1;
    if (bounce_app_flow_level_selection_move(
            &flow,
            BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.level_selection.selected_index != 0u)
        return -1;
    for (index = 0u; index < BOUNCE_APP_LAST_LEVEL_ID - 1u; ++index) {
        if (bounce_app_flow_level_selection_move(
                &flow,
                BOUNCE_MENU_DIRECTION_DOWN) != 0
            || flow.level_selection.selected_index != index + 1u)
            return -1;
    }
    for (index = 0u; index < BOUNCE_APP_LAST_LEVEL_ID - 1u; ++index) {
        if (bounce_app_flow_level_selection_move(
                &flow,
                BOUNCE_MENU_DIRECTION_UP) != 0
            || flow.level_selection.selected_index
                != BOUNCE_APP_LAST_LEVEL_ID - 2u - index)
            return -1;
    }
    if (flow.level_selection.selected_index != 0u
        || bounce_app_flow_level_selection_move(
               &flow,
               BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.level_selection.selected_index != 0u
        || bounce_app_flow_level_selection_select(&flow) < 0
        || bounce_app_flow_pending_level_id(&flow) != BOUNCE_APP_FIRST_LEVEL_ID)
        return -1;

    /*
     * Every screen this milestone added or extended must actually draw. A blank
     * surface would otherwise pass a state-only assertion.
     */
    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_ui_shell_render_menu(surface, renderer, &flow) != 0
        || surface_pixel_count_other_than(surface, UINT32_C(0xff121a30)) <= 0) {
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        return -1;
    }
    if (bounce_app_flow_enter_settings(&flow) != 0) {
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        return -1;
    }
    /*
     * STEP 38-RESET-UI -- AND THE LOOP NOW INCLUDES THE RESET PAGE. It stopped at THEME,
     * which is the highest page that existed when this was written, so the confirmation
     * screen was never among the pages this smoke test rendered. Bounded by the page
     * enum's last value rather than by THEME so a future page is covered by default.
     */
    for (index = BOUNCE_SETTINGS_PAGE_ROOT;
         index <= BOUNCE_SETTINGS_PAGE_RESET;
         ++index) {
        flow.settings.page = (BounceSettingsPage)index;
        if (bounce_ui_shell_render_settings(surface, renderer, &flow) != 0
            || surface_pixel_count_other_than(
                   surface,
                   UINT32_C(0xff121a30)) <= 0) {
            bounce_renderer_destroy(renderer);
            bounce_surface_destroy(surface);
            return -1;
        }
    }
    flow.settings.page = BOUNCE_SETTINGS_PAGE_ROOT;
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_enter_about(&flow) != 0
        || bounce_ui_shell_render_about(surface, renderer, &flow) != 0) {
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        return -1;
    }
    nonblank = (int)surface_pixel_count_other_than(surface, UINT32_C(0xff121a30));
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return nonblank > 0 ? 0 : -1;
}

/*
 * NATIVE EXTENSION verification for the temporary UI color profiles.
 *
 * Confirms the audit conclusion holds at runtime: the palette is a local seam in
 * ui_shell.c, every profile renders a distinct and complete Main Menu, every
 * palette role stays distinguishable, an out-of-range index is ignored rather
 * than blanking the UI, and the profile is not persisted anywhere.
 */
/*
 * TEMPORARY five-language runtime switching verification.
 *
 * Covers the milestone contract without an X server:
 *   - all five languages are selectable and apply on SELECT
 *   - the applied language survives navigating away and back
 *   - switching is repeatable in the order EN -> CN -> TW -> TH -> ID -> EN
 *   - every implemented page renders in every language without failing
 *   - the script font has a set for CN, TW and TH and none for EN or ID
 *   - nothing is persisted: a fresh flow is always EN
 *
 * The Chinese and Thai strings are TEMPORARY TEST STRINGS, not decoded
 * resources.
 */
/* Navigate from the current state to the Settings > Language page. */
static int goto_language_page(BounceAppFlow *flow)
{
    unsigned int guard;

    if (flow == NULL)
        return -1;
    if (flow->state != BOUNCE_APP_STATE_MENU
        && flow->state != BOUNCE_APP_STATE_SETTINGS) {
                return -1;
            }
    if (flow->state == BOUNCE_APP_STATE_MENU) {
        /*
         * D-05 -- the comment here used to read "Entering Settings resets the
         * menu highlight, so walk to the row", which is no longer true and was
         * not true of Java either. BounceGame.java:126-130 restores N, so the
         * highlight survives; the walk is kept because this helper navigates to
         * a specific row from wherever it finds the highlight, and clamping at
         * the top is what makes the walk idempotent no matter where it started.
         */
        for (guard = 0u; guard < BOUNCE_MENU_ROW_COUNT; ++guard) {
            if (bounce_app_flow_menu_move(
                    flow, BOUNCE_MENU_DIRECTION_UP) != 0) {
                return -1;
            }
        }
        for (guard = 0u; guard < BOUNCE_SETTINGS_ROW_LANGUAGE; ++guard) {
            if (bounce_app_flow_menu_move(
                    flow, BOUNCE_MENU_DIRECTION_DOWN) != 0) {
                return -1;
            }
        }
        if (bounce_app_flow_menu_select(flow) != BOUNCE_MENU_ACTION_SETTINGS
            || flow->state != BOUNCE_APP_STATE_SETTINGS) {
                return -1;
            }
    }
    if (bounce_app_flow_settings_page(flow) != BOUNCE_SETTINGS_PAGE_ROOT) {
                return -1;
            }
    /* The Language row is always Settings row 3. */
    for (guard = 0u; guard < BOUNCE_SETTINGS_ROOT_ITEM_COUNT; ++guard) {
        if (bounce_app_flow_settings_selected_index(flow)
            == BOUNCE_SETTINGS_ROW_LANGUAGE)
            break;
        if (bounce_app_flow_settings_move(
                flow, BOUNCE_MENU_DIRECTION_DOWN) != 0) {
                return -1;
            }
    }
    if (bounce_app_flow_settings_selected_index(flow)
        != BOUNCE_SETTINGS_ROW_LANGUAGE) {
                return -1;
            }
    if (bounce_app_flow_settings_select(flow) != 0
        || bounce_app_flow_settings_page(flow) != BOUNCE_SETTINGS_PAGE_LANGUAGE) {
                return -1;
            }
    return 0;
}

static int verify_five_language_switching(void)
{
    BounceAppFlow flow;
    BounceSurface *surface;
    BounceRenderer *renderer;
    static const BounceLanguage order[5] = {
        BOUNCE_LANGUAGE_ZH_CN,
        BOUNCE_LANGUAGE_ZH_TW,
        BOUNCE_LANGUAGE_TH_TH,
        BOUNCE_LANGUAGE_ID,
        BOUNCE_LANGUAGE_EN
    };
    unsigned long digests[5];
    unsigned int step;

    /*
     * The script font exists for the two CJK languages and not for the rest.
     *
     * EN and ID are Latin and always use the 5x7 font, so they have no script set.
     *
     * V-2 -- TH NOW HAS ONE, and this assertion was its opposite. It used to read:
     *
     *     TH is absent on purpose: Thai marks make even an 8 px glyph 13 rows
     *     tall, and only 7 px fits the 12 px row pitch the native lists use,
     *     which is not legible. Shipping an unreadable Thai set would look like a
     *     working feature, so TH falls through to the 5x7 unknown-glyph path
     *     instead.
     *
     * Re-measured over every cluster lang.th-TH uses, Thai needs ELEVEN rows at
     * 8 px, so it fits the 12-row pitch whole at 9 px. The set ships, and this
     * now asserts it -- advance non-zero, the same cell size as the Chinese sets,
     * and a glyph count in the same range -- so a later removal has to be
     * deliberate rather than accidental.
     */
    for (step = 0u; step < 5u; ++step) {
        const BounceScriptMetrics *metrics;
        /*
         * EN and ID are Latin; ZH_CN, ZH_TW and TH_TH each have a set.
         *
         * THE INDICES ARE NOT THE DECLARATION ORDER and this got it wrong once:
         * the enum is EN, ZH_CN, ZH_TW, TH_TH, ID (locale.h:29-34), so TH_TH is
         * 3 and ID is 4 -- Indonesian is the native extension and was appended
         * last. The named constants are used below rather than positional
         * literals precisely so that mistake cannot recur.
         */
        int expect_script = step == (unsigned int)BOUNCE_LANGUAGE_ZH_CN
            || step == (unsigned int)BOUNCE_LANGUAGE_ZH_TW
            || step == (unsigned int)BOUNCE_LANGUAGE_TH_TH;

        bounce_script_font_set_active_language((BounceLanguage)step);
        metrics = bounce_script_font_metrics();
        if (expect_script) {
            if (metrics->advance <= 0
                || metrics->cell_width != BOUNCE_SCRIPT_CELL_WIDTH
                || metrics->cell_height != BOUNCE_SCRIPT_CELL_HEIGHT
                || bounce_script_font_glyph_count() < 50u)
                return -1;
        } else {
            if (metrics->advance != 0
                || metrics->cell_width != BOUNCE_SCRIPT_CELL_WIDTH
                || bounce_script_font_glyph_count() != 0u)
                return -1;
        }
    }
    /* An out-of-range language must be ignored, not applied. */
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_TH_TH);
    bounce_script_font_set_active_language((BounceLanguage)99);
    if (bounce_script_font_active_language() != BOUNCE_LANGUAGE_TH_TH)
        return -1;

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    while (bounce_app_flow_tick(&flow) == 0
           && flow.state == BOUNCE_APP_STATE_SPLASH) {
        /* run the splash out */
    }
    if (flow.state != BOUNCE_APP_STATE_MENU
        || bounce_app_flow_set_available_level_count(
               &flow, BOUNCE_APP_LAST_LEVEL_ID) != 0)
        return -1;
    /* A fresh flow is always EN, in the flow and in the runtime. */
    if (bounce_app_flow_settings_applied_language_index(&flow) != 0u
        || bounce_locale_active_language() != BOUNCE_LANGUAGE_EN)
        return -1;

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }

    for (step = 0u; step < 5u; ++step) {
        BounceLanguage want = order[step];
        unsigned int row = (unsigned int)want;

        /* Reach Settings -> Language from wherever the flow currently is. */
        if (goto_language_page(&flow) != 0)
            goto fail;
        while (bounce_app_flow_settings_language_index(&flow) > row) {
            if (bounce_app_flow_settings_move(
                    &flow, BOUNCE_MENU_DIRECTION_UP) != 0)
                goto fail;
        }
        while (bounce_app_flow_settings_language_index(&flow) < row) {
            if (bounce_app_flow_settings_move(
                    &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0)
                goto fail;
        }
        if (bounce_app_flow_settings_select(&flow) != 0
            || bounce_app_flow_settings_applied_language_index(&flow) != row)
            goto fail;

        /*
         * The flow is the owner; the runtime mirrors are driven by the same
         * per-frame mirror the application performs, so do it explicitly here.
         */
        bounce_locale_set_active_language(want);
        bounce_script_font_set_active_language(want);
        if (bounce_locale_active_language() != want
            || bounce_script_font_active_language() != want)
            goto fail;

        /* Every implemented page must render in this language. */
        {
            /* Each renderer validates its own state, so set it per page. */
            static const BounceAppState page_state[5] = {
                BOUNCE_APP_STATE_MENU, BOUNCE_APP_STATE_ABOUT,
                BOUNCE_APP_STATE_LEVEL_SELECTION, BOUNCE_APP_STATE_INSTRUCTIONS,
                BOUNCE_APP_STATE_HIGH_SCORE
            };
            unsigned int p;

            for (p = 0u; p < 5u; ++p) {
                int rc;

                flow.state = page_state[p];
                switch (p) {
                case 0: rc = bounce_ui_shell_render_menu(
                            surface, renderer, &flow); break;
                case 1: rc = bounce_ui_shell_render_about(
                            surface, renderer, &flow); break;
                case 2: rc = bounce_ui_shell_render_level_selection(
                            surface, renderer, &flow); break;
                case 3: rc = bounce_ui_shell_render_instructions(
                            surface, renderer, &flow); break;
                default: rc = bounce_ui_shell_render_high_score(
                            surface, renderer, &flow); break;
                }
                if (rc != 0)
                    goto fail;
            }
        }
        flow.state = BOUNCE_APP_STATE_SETTINGS;
        {
            unsigned int page;

            for (page = 0u; page <= (unsigned int)BOUNCE_SETTINGS_PAGE_THEME;
                 ++page) {
                flow.settings.page = (BounceSettingsPage)page;
                if (bounce_ui_shell_render_settings(
                        surface, renderer, &flow) != 0)
                    goto fail;
            }
        }
        digests[step] = (unsigned long)surface_digest(surface);
        if (digests[step] == 0u)
            goto fail;

        /* Leave Settings and come back, to prove the selection was preserved. */
        if (bounce_app_flow_settings_back(&flow) != 0
            || bounce_app_flow_settings_back(&flow) != 0
            || flow.state != BOUNCE_APP_STATE_MENU)
            goto fail;
        /* Re-enter and confirm the applied language survived the round trip. */
        if (goto_language_page(&flow) != 0
            || bounce_app_flow_settings_applied_language_index(&flow) != row)
            goto fail;
        if (bounce_app_flow_settings_back(&flow) != 0
            || bounce_app_flow_settings_back(&flow) != 0
            || flow.state != BOUNCE_APP_STATE_MENU)
            goto fail;
    }

    /* Each language must produce a distinct main menu. */
    for (step = 1u; step < 5u; ++step) {
        unsigned int other;

        for (other = step + 1u; other < 5u; ++other) {
            if (digests[step] == digests[other])
                goto fail;
        }
    }

    /* No persistence: a fresh flow is EN again and the runtime follows it. */
    bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_EN);
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    if (bounce_app_flow_settings_applied_language_index(&flow) != 0u
        || bounce_app_flow_settings_language_index(&flow) != 0u)
        goto fail;

    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return 0;

fail:
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    return -1;
}

static int verify_ui_color_profiles(void)
{
    BounceAppFlow flow;
    BounceSurface *surface;
    BounceRenderer *renderer;
    unsigned long digests[BOUNCE_UI_COLOR_PROFILE_COUNT];
    unsigned int index;
    unsigned int role;

    if (bounce_ui_shell_active_color_profile() != 0u
        || BOUNCE_UI_COLOR_PROFILE_COUNT != 13u
        || BOUNCE_UI_THEME_COUNT != BOUNCE_UI_COLOR_PROFILE_COUNT)
        return -1;

    /* An out-of-range request must be ignored, not applied. */
    bounce_ui_shell_set_color_profile(BOUNCE_UI_COLOR_PROFILE_COUNT);
    if (bounce_ui_shell_active_color_profile() != 0u)
        return -1;
    bounce_ui_shell_set_color_profile(BOUNCE_UI_COLOR_PROFILE_COUNT + 99u);
    if (bounce_ui_shell_active_color_profile() != 0u)
        return -1;

    /* Every role inside a profile must be distinct from the background, or the
       text and the selected row would become unreadable. */
    for (index = 0u; index < BOUNCE_UI_COLOR_PROFILE_COUNT; ++index) {
        const BounceUiPalette *palette;

        bounce_ui_shell_set_color_profile(index);
        palette = bounce_ui_shell_palette();
        if (palette == NULL)
            return -1;
        for (role = 1u; role < 10u; ++role) {
            const uint32_t colors[10] = {
                palette->background,
                palette->panel,
                palette->border,
                palette->highlight,
                palette->selected_text,
                palette->text,
                palette->body,
                palette->muted,
                palette->accent,
                palette->disabled
            };

            /*
             * selected_text is EXEMPT. It is deliberately allowed to equal the
             * background, and for most profiles it does: a selected row is a
             * solid selected_background block with its label punched out in the
             * background color, which is what makes an inverted profile
             * readable. Its correct invariant is the opposite one, checked
             * below: it must contrast with the highlight it is drawn on.
             */
            if (role == 4u)
                continue;
            if (colors[role] == palette->background
                || colors[role] == 0u)
                return -1;
        }
        /* The highlight must not be the same as the panel it sits on. */
        if (palette->highlight == palette->panel
            || palette->highlight == palette->background)
            return -1;
        /* The selected label must be readable on the selected fill. */
        if (palette->selected_text == palette->highlight
            || palette->selected_text == 0u)
            return -1;
    }

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    while (bounce_app_flow_tick(&flow) == 0
           && flow.state == BOUNCE_APP_STATE_SPLASH) {
        /* run the splash out so the menu renders */
    }
    if (flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }
    for (index = 0u; index < BOUNCE_UI_COLOR_PROFILE_COUNT; ++index) {
        bounce_ui_shell_set_color_profile(index);
        if (bounce_ui_shell_render_menu(surface, renderer, &flow) != 0
            || surface_pixel_count_other_than(
                   surface,
                   bounce_ui_shell_palette()->background) <= 0) {
            bounce_renderer_destroy(renderer);
            bounce_surface_destroy(surface);
            return -1;
        }
        digests[index] = (unsigned long)surface_digest(surface);
    }
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);

    /*
     * Every profile must be a genuinely different presentation: 13 distinct
     * digests, compared pairwise, so no two profiles may render identically.
     */
    for (index = 0u; index < BOUNCE_UI_COLOR_PROFILE_COUNT; ++index) {
        unsigned int other;

        for (other = index + 1u; other < BOUNCE_UI_COLOR_PROFILE_COUNT; ++other) {
            if (digests[index] == digests[other])
                return -1;
        }
    }

    /*
     * EXACT AUTHORITATIVE PALETTES.
     *
     * The four authoritative roles per profile are background, text,
     * selected_background (the `highlight` field) and selected_text. Each row
     * below is {index, background, text, selected_background, selected_text}.
     * Index 0 (Default) is deliberately absent: it is not redesigned, it keeps
     * the nine values this build shipped before profiles existed.
     */
    {
        static const uint32_t expected[BOUNCE_UI_COLOR_PROFILE_COUNT - 1u][5] = {
            { 1u, UINT32_C(0xff8eb038), UINT32_C(0xff1a2308), UINT32_C(0xff0b1003),
              UINT32_C(0xff8eb038) }, /* Green LCD */
            { 2u, UINT32_C(0xfff2ebd9), UINT32_C(0xff4a3525), UINT32_C(0xff4a3525),
              UINT32_C(0xfff2ebd9) }, /* Sepia */
            { 3u, UINT32_C(0xff0a140a), UINT32_C(0xff33cc33), UINT32_C(0xff33cc33),
              UINT32_C(0xff0a140a) }, /* Green Inverted */
            { 4u, UINT32_C(0xff140c02), UINT32_C(0xffffa500), UINT32_C(0xffffa500),
              UINT32_C(0xff140c02) }, /* Amber */
            { 5u, UINT32_C(0xff001133), UINT32_C(0xfffff8dc), UINT32_C(0xff00bfff),
              UINT32_C(0xff001133) }, /* Navy Cream */
            { 6u, UINT32_C(0xff112a1c), UINT32_C(0xffc2e0d1), UINT32_C(0xffffd700),
              UINT32_C(0xff112a1c) }, /* Forest Mint */
            { 7u, UINT32_C(0xff5a121e), UINT32_C(0xfffadcd8), UINT32_C(0xffe5c158),
              UINT32_C(0xff5a121e) }, /* Burgundy */
            { 8u, UINT32_C(0xff1e1e1e), UINT32_C(0xffffffff), UINT32_C(0xff007acc),
              UINT32_C(0xffffffff) }, /* Charcoal Blue */
            { 9u, UINT32_C(0xff3b629b), UINT32_C(0xffe0ecf8), UINT32_C(0xffff8c00),
              UINT32_C(0xff3b629b) }, /* Nokia Blue */
            { 10u, UINT32_C(0xff2e1a47), UINT32_C(0xffdcd0ff), UINT32_C(0xffffdab9),
              UINT32_C(0xff2e1a47) }, /* Purple */
            { 11u, UINT32_C(0xffffffff), UINT32_C(0xff001c3d), UINT32_C(0xff00bfff),
              UINT32_C(0xffffffff) }, /* Arctic */
            { 12u, UINT32_C(0xff0c3b3f), UINT32_C(0xfffffff0), UINT32_C(0xffff8c00),
              UINT32_C(0xff0c3b3f) }  /* Teal Ivory */
        };
        unsigned int row;

        for (row = 0u; row < BOUNCE_UI_COLOR_PROFILE_COUNT - 1u; ++row) {
            const BounceUiPalette *palette;

            bounce_ui_shell_set_color_profile(expected[row][0]);
            palette = bounce_ui_shell_palette();
            if (palette == NULL
                || palette->background != expected[row][1]
                || palette->text != expected[row][2]
                || palette->highlight != expected[row][3]
                || palette->selected_text != expected[row][4])
                return -1;
        }

        /*
         * Default is preserved, not redesigned: the exact nine values from
         * before profiles existed, and selected_text equal to text so its
         * selected row is drawn exactly as it always was.
         */
        bounce_ui_shell_set_color_profile(0u);
        {
            const BounceUiPalette *palette = bounce_ui_shell_palette();

            if (palette == NULL
                || palette->background != UINT32_C(0xff121a30)
                || palette->panel != UINT32_C(0xff202c50)
                || palette->border != UINT32_C(0xff5069a8)
                || palette->highlight != UINT32_C(0xff3c65b5)
                || palette->text != UINT32_C(0xfff5f5f5)
                || palette->body != UINT32_C(0xffd7e0ff)
                || palette->muted != UINT32_C(0xff9aa6c4)
                || palette->accent != UINT32_C(0xffffc857)
                || palette->disabled != UINT32_C(0xff777f91)
                || palette->selected_text != palette->text)
                return -1;
        }
    }

    /*
     * selected_text MUST BE CONSUMED, not merely stored. The Theme page is
     * entered with each profile in turn and the selected row's highlight band
     * is inspected: the band is filled with selected_background, so the only
     * way selected_text pixels can appear inside it is if the row label is
     * drawn in that role. For most profiles selected_text equals the
     * background, which is exactly the intended "punched out" inverted block,
     * and this check is what proves the label is really drawn that way.
     */
    {
        /* Its own surface: the one above is already destroyed at this point. */
        BounceSurface *tsurface = bounce_surface_create();
        BounceRenderer *trenderer;
        BounceAppFlow tflow;
        int status = 0;

        if (tsurface == NULL)
            return -1;
        trenderer = bounce_renderer_create(tsurface);
        if (trenderer == NULL) {
            bounce_surface_destroy(tsurface);
            return -1;
        }
        memset(&tflow, 0, sizeof tflow);
        bounce_app_flow_init(&tflow);
        tflow.state = BOUNCE_APP_STATE_SETTINGS;
        tflow.settings.page = BOUNCE_SETTINGS_PAGE_THEME;
        for (index = 0u; index < BOUNCE_UI_COLOR_PROFILE_COUNT; ++index) {
            const BounceUiPalette *palette;
            long found = 0;
            int x;
            int y;

            bounce_ui_shell_set_color_profile(index);
            palette = bounce_ui_shell_palette();
            if (palette == NULL) {
                status = -1;
                break;
            }
            int first;
            int slot;
            int band_y;

            tflow.settings.theme_index = index;
            tflow.settings.applied_theme_index = index;
            /*
             * Mirror the renderer's DERIVED window. The offset is not stored, so
             * the test restates the same pure formula: first = clamp(index - 2,
             * 0, count - visible), and the selected row sits at slot
             * index - first. This is the row whose band must contain
             * selected_text pixels.
             */
            first = (int)index - 2;
            if (first < 0)
                first = 0;
            if (first > (int)BOUNCE_UI_COLOR_PROFILE_COUNT - 4)
                first = (int)BOUNCE_UI_COLOR_PROFILE_COUNT - 4;
            slot = (int)index - first;
            band_y = 30 + slot * 20 - 2;
            /* The Theme page fills its whole panel every frame, so no clear. */
            if (bounce_ui_shell_render_settings(tsurface, trenderer, &tflow) != 0) {
                status = -1;
                break;
            }
            for (y = band_y; y < band_y + 13; ++y) {
                for (x = 12; x < 12 + 104; ++x) {
                    uint32_t pixel = 0u;

                    if (bounce_surface_get_pixel(tsurface, x, y, &pixel) != 0) {
                        status = -1;
                        break;
                    }
                    if (pixel == palette->selected_text)
                        ++found;
                }
                if (status != 0)
                    break;
            }
            if (status != 0)
                break;
            if (found <= 0) {
                status = -1;
                break;
            }
        }
        bounce_renderer_destroy(trenderer);
        bounce_surface_destroy(tsurface);
        if (status != 0)
            return -1;
        bounce_ui_shell_set_color_profile(0u);
    }

    /*
     * THE SAME ROLE RULE MUST HOLD ON THE MAIN MENU.
     *
     * Regression guard. The Main Menu, the Settings root list, the Language list
     * and the Level Selection list each draw a `highlight` (selected_background)
     * fill under the selected row and must label it in `selected_text`. They
     * previously all labelled it in `text`, which made the selected row
     * unreadable whenever the two were close: Green LCD sat at 1.18:1 contrast,
     * and Sepia, Green Inverted, Amber, Forest Mint, Burgundy, Purple and Teal
     * Ivory were equal or near-equal. Only the Theme page was correct.
     *
     * The row geometry below mirrors the renderer's own static table, the same
     * way the derived Theme window is mirrored above.
     */
    {
        static const int menu_row_y[BOUNCE_MENU_ROW_COUNT] = {
            30, 42, 54, 66, 78, 90, 102
        };
        BounceSurface *msurface = bounce_surface_create();
        BounceRenderer *mrenderer;
        BounceAppFlow mflow;
        int status = 0;

        if (msurface == NULL)
            return -1;
        mrenderer = bounce_renderer_create(msurface);
        if (mrenderer == NULL) {
            bounce_surface_destroy(msurface);
            return -1;
        }
        memset(&mflow, 0, sizeof mflow);
        bounce_app_flow_init(&mflow);
        while (bounce_app_flow_tick(&mflow) == 0
               && mflow.state == BOUNCE_APP_STATE_SPLASH) {
            /* run the splash out so the menu renders */
        }
        mflow.state = BOUNCE_APP_STATE_MENU;
        mflow.menu.selected_index = 1u;
        for (index = 0u; index < BOUNCE_UI_COLOR_PROFILE_COUNT; ++index) {
            const BounceUiPalette *palette;
            unsigned int selected_row;
            long labelled = 0;
            long wrong = 0;
            int band_y;
            int x;
            int y;

            bounce_ui_shell_set_color_profile(index);
            palette = bounce_ui_shell_palette();
            if (palette == NULL) {
                status = -1;
                break;
            }
            if (bounce_ui_shell_render_menu(msurface, mrenderer, &mflow) != 0) {
                status = -1;
                break;
            }
            selected_row
                = bounce_app_flow_menu_row_for_selection(&mflow, mflow.menu.selected_index);
            if (selected_row >= BOUNCE_MENU_ROW_COUNT) {
                status = -1;
                break;
            }
            band_y = menu_row_y[selected_row] - 2;
            for (y = band_y; y < band_y + 11; ++y) {
                for (x = 20; x < 116; ++x) {
                    uint32_t pixel = 0u;

                    if (bounce_surface_get_pixel(msurface, x, y, &pixel) != 0) {
                        status = -1;
                        break;
                    }
                    if (pixel == palette->selected_text)
                        ++labelled;
                    /*
                     * The complementary check is only meaningful when `text`
                     * differs from both selected_text and the highlight fill it
                     * may coincide with; otherwise counting it just re-counts
                     * the fill or the label.
                     */
                    else if (palette->text != palette->selected_text
                        && palette->text != palette->highlight
                        && pixel == palette->text)
                        ++wrong;
                }
                if (status != 0)
                    break;
            }
            if (status != 0)
                break;
            /* The selected row's label must exist, in the selected_text role. */
            if (labelled <= 0 || wrong != 0) {
                status = -1;
                break;
            }
        }
        bounce_renderer_destroy(mrenderer);
        bounce_surface_destroy(msurface);
        if (status != 0)
            return -1;
        bounce_ui_shell_set_color_profile(0u);
    }

    /*
     * No persistence: a fresh flow is always the default profile, and the
     * profile is not stored in BounceAppFlow.
     */
    bounce_ui_shell_set_color_profile(1u);
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    if (flow.settings.applied_theme_index != 0u
        || bounce_app_flow_settings_applied_theme_index(&flow) != 0u)
        return -1;
    bounce_ui_shell_set_color_profile(0u);
    return 0;
}

/*
 * NATIVE EXTENSION verification for the mouse and numeric seams.
 *
 * Both are checked without an X server, against the same hit-test and digit
 * functions the event loop calls, so a change in either is caught deterministically.
 */
static int verify_mouse_and_numeric_input(void)
{
    BounceAppFlow flow;
    unsigned int digit;

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    while (bounce_app_flow_tick(&flow) == 0
           && flow.state == BOUNCE_APP_STATE_SPLASH) {
        /* run the splash out */
    }
    if (flow.state != BOUNCE_APP_STATE_MENU)
        return -1;
    /*
     * Publish the production Level Select range first. Without it the flow model
     * reports zero available levels and New game takes the source's MaxLevels <= 1
     * branch instead of opening the list, which is not the real behavior.
     */
    if (bounce_app_flow_set_available_level_count(
            &flow,
            BOUNCE_APP_LAST_LEVEL_ID) != 0
        || bounce_app_flow_available_level_count(&flow)
            != BOUNCE_APP_LAST_LEVEL_ID)
        return -1;

    /* A click on a disabled row must be ignored, not activate it. */
    if (bounce_ui_shell_handle_click(&flow, 30, 30) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_NONE)
        return -1;

    /*
     * The two-step rule. New game is the default selection, so clicking its row
     * activates it straight away, which is the expected result for the row the
     * highlight already sits on. A row that is NOT selected must only move the
     * highlight, and only a later click on that same row may activate it.
     */
    if (flow.menu.selected_index != 0u
        || bounce_ui_shell_handle_click(&flow, 30, 78) != 1
        || flow.menu.selected_index != 3u
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT)
        return -1;
    /*
     * Back out of the Settings root to the menu, then activate the already
     * selected New game row. One Back step suffices from the root; a page would
     * need two, which the Settings navigation checks below cover.
     */
    if (flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_ui_shell_handle_click(&flow, 60, 120) != 1
        || flow.state != BOUNCE_APP_STATE_MENU
        || bounce_ui_shell_handle_click(&flow, 30, 42) != 1
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
        return -1;

    /* A click outside every row is ignored. */
    if (bounce_ui_shell_handle_click(&flow, 2, 2) != 0)
        return -1;
    if (bounce_ui_shell_handle_click(&flow, 127, 127) != 0)
        return -1;

    /*
     * Level Select: a click on a row that is not selected must only move the
     * highlight, and only a second click on that same row may start the level.
     * This is checked before the digit checks because a started level leaves the
     * list and would make the digit assertions meaningless.
     */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || flow.level_selection.available_level_count
            != BOUNCE_APP_LAST_LEVEL_ID
        || flow.level_selection.selected_index != 0u)
        return -1;
    /* Level 3 sits at y = 40 in the level list. */
    if (bounce_ui_shell_handle_click(&flow, 30, 40) != 1
        || flow.level_selection.selected_index != 2u
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
        || bounce_app_flow_pending_level_id(&flow) != 0)
        return -1;
    /* The second click on the same row starts it, recording START_LEVEL(3). */
    if (bounce_ui_shell_handle_click(&flow, 30, 40) != 1
        || flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || bounce_app_flow_pending_level_id(&flow) != 3u)
        return -1;
    /* Reopen the list for the digit checks. */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
        return -1;

    /*
     * Digits select only. They must never start a level on their own.
     */

    for (digit = 1u; digit <= 9u; ++digit) {
        if (bounce_ui_shell_handle_number(&flow, digit) != 1
            || flow.level_selection.selected_index != digit - 1u
            || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION
            || bounce_app_flow_pending_level_id(&flow) != 0)
            return -1;
    }
    /* Digit 0 selects level 10, the conventional numeric position. */
    if (bounce_ui_shell_handle_number(&flow, 0u) != 1
        || flow.level_selection.selected_index != 9u
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
        return -1;
    /* A digit outside 0..9 is refused outright. */
    if (bounce_ui_shell_handle_number(&flow, 10u) != 0)
        return -1;

    /* With fewer levels published, a digit beyond the range must be refused. */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_set_available_level_count(&flow, 3u) != 0
        || bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION)
        return -1;
    if (bounce_ui_shell_handle_number(&flow, 5u) != 0
        || flow.level_selection.selected_index != 0u
        || bounce_ui_shell_handle_number(&flow, 3u) != 1
        || flow.level_selection.selected_index != 2u)
        return -1;

    /* Digits are meaningless outside Level Select. */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_ui_shell_handle_number(&flow, 3u) != 0
        || flow.state != BOUNCE_APP_STATE_MENU
        || flow.menu.pending_action != BOUNCE_MENU_ACTION_NONE)
        return -1;

    /* The main menu has no Back action, so the Back band must not fire there. */
    if (bounce_ui_shell_handle_click(&flow, 60, 120) != 0
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    /* Settings: click selects a row, a second click opens it, Back band returns. */
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 3u
        /* Settings row: the highlight is already here, so one click opens it. */
        || bounce_ui_shell_handle_click(&flow, 30, 78) != 1
        || flow.state != BOUNCE_APP_STATE_SETTINGS
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_settings_selected_index(&flow) != 0u
        /* A different root row only moves the highlight ... */
        || bounce_ui_shell_handle_click(&flow, 30, 92) != 1
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_ROW_THEME
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        /* ... and a second click on that same row opens it. */
        || bounce_ui_shell_handle_click(&flow, 30, 92) != 1
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_THEME
        /* Back from a page, then Back from the root. */
        || bounce_ui_shell_handle_click(&flow, 60, 120) != 1
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_ui_shell_handle_click(&flow, 60, 120) != 1
        || flow.state != BOUNCE_APP_STATE_MENU)
        return -1;

    return 0;
}

static int verify_production_game_routing(void)
{
    BounceApp app;
    BounceApp legacy;
    char level_path[64];
    int64_t legacy_deadline_before;
    int64_t canonical_deadline_before;
    int64_t canonical_deadline_after;
    uint64_t ticks;
    unsigned int i;

    memset(&app, 0, sizeof app);

    /* A + B + C: one production frame consumes START_LEVEL and ticks once. */
    if (drive_app_to_gameplay_entry_start_level(&app) != 0)
        return -1;
    legacy_deadline_before = app.next_player_tick_ms;
    if (legacy_deadline_before <= 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
        || bounce_game_timer_is_started(&app.game_timer)
        || app_update_production_game(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || !app_canonical_gameplay_active(&app)
        || bounce_game_timer_tick_entry_count(&app.game_timer) != 1u
        || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 1u
        || bounce_game_timer_player_tick_entry_count(&app.game_timer) != 1u
        || bounce_game_timer_player_physics_count(&app.game_timer) != 1u
        || app.legacy_player_tick_route_count != 0) {
        bounce_game_release_level(&app);
        return -1;
    }

    /* D: the legacy deadline is untouched by the canonical path. */
    if (app.next_player_tick_ms != legacy_deadline_before) {
        bounce_game_release_level(&app);
        return -1;
    }

    /*
     * E: the backend is a plain one-period deadline. It must sit at most one
     * nominal period ahead of the clock, which is exactly what rules out a
     * catch-up burst and an accumulator, and it must never be left behind the
     * clock by more than one period, which is what a missed-tick backlog would
     * look like. This is a cadence architecture statement, not an accuracy claim.
     */
    canonical_deadline_before = app.canonical_next_tick_ms;
    if (canonical_deadline_before <= 0
        || canonical_deadline_before - monotonic_milliseconds()
            > (int64_t)BOUNCE_GAME_TIMER_PERIOD_MS
        || monotonic_milliseconds() - canonical_deadline_before
            > (int64_t)BOUNCE_GAME_TIMER_PERIOD_MS) {
        bounce_game_release_level(&app);
        return -1;
    }

    /*
     * B + C across many frames. A frame that arrives before the deadline
     * legitimately skips the tick, so the invariant is: the dispatch count never
     * grows by more than one per frame, it always equals the tick-entry count
     * and the physics count, and the legacy route is never taken.
     *
     * The achieved CADENCE is not asserted here, and deliberately so: this loop
     * runs back to back with no frame period between iterations, so `now` advances
     * by microseconds and almost every iteration legitimately skips its tick. A
     * cadence measured in a loop like this one measures the loop, not the
     * scheduler. verify_tick_cadence() below is where the rate is measured, over
     * real frame periods.
     */
    for (i = 0u; i < 64u; ++i) {
        int64_t before;
        uint64_t dispatch_before;
        uint64_t dispatch_after;

        before = monotonic_milliseconds();
        dispatch_before = bounce_game_timer_tick_dispatch_count(&app.game_timer);
        if (app_update_production_game(&app) != 0)
            goto failure;
        dispatch_after = bounce_game_timer_tick_dispatch_count(&app.game_timer);
        if (dispatch_after < dispatch_before
            || dispatch_after - dispatch_before > 1u
            || bounce_game_timer_tick_entry_count(&app.game_timer)
                != dispatch_after
            || bounce_game_timer_player_tick_entry_count(&app.game_timer)
                != dispatch_after
            || bounce_game_timer_player_physics_count(&app.game_timer)
                != dispatch_after
            || app.legacy_player_tick_route_count != 0
            || app.next_player_tick_ms != legacy_deadline_before) {
            goto failure;
        }
        canonical_deadline_after = app.canonical_next_tick_ms;
        if (canonical_deadline_after <= 0
            || canonical_deadline_after < canonical_deadline_before
            || canonical_deadline_after - before
                > (int64_t)BOUNCE_GAME_TIMER_PERIOD_MS + 100) {
            goto failure;
        }
        canonical_deadline_before = canonical_deadline_after;
    }
    ticks = bounce_game_timer_tick_dispatch_count(&app.game_timer);
    if (ticks < 1u)
        goto failure;

    /* F: leaving releases ownership, stops the timer, and allows a fresh start. */
    app_end_canonical_gameplay(&app);
    if (app.level != NULL
        || app.runtime != NULL
        || app.player.initialized
        || bounce_game_timer_is_started(&app.game_timer)
        || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 0u
        || app_canonical_gameplay_active(&app)) {
        goto failure;
    }
    if (drive_app_to_gameplay_entry_start_level(&app) != 0
        || app_update_production_game(&app) != 0
        || bounce_game_timer_tick_dispatch_count(&app.game_timer) != 1u
        || bounce_game_timer_player_physics_count(&app.game_timer) != 1u
        || app.legacy_player_tick_route_count != 0) {
        goto failure;
    }
    app_end_canonical_gameplay(&app);

    /*
     * G: with the canonical timer NOT started the legacy route is still taken,
     * which is exactly how the diagnostic modes keep working.
     */
    if (bounce_game_init(&legacy) != 0
        || bounce_game_enter_menu(&legacy) != 0)
        return -1;
    if (bounce_game_level_resource_path(
            BOUNCE_APP_FIRST_LEVEL_ID,
            level_path,
            sizeof level_path) != 0
        || bounce_game_start_level(
               &legacy,
               level_path,
               BOUNCE_APP_FIRST_LEVEL_ID,
               3) != 0
        || legacy.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || legacy.state != BOUNCE_GAME_STATE_PLAYING
        || bounce_game_timer_is_started(&legacy.game_timer)
        || app_canonical_gameplay_active(&legacy)) {
        bounce_game_release_level(&legacy);
        return -1;
    }
    if (app_update_production_game(&legacy) != 0
        || legacy.legacy_player_tick_route_count < 1) {
        bounce_game_release_level(&legacy);
        return -1;
    }
    bounce_game_release_level(&legacy);
    return 0;

failure:
    bounce_game_release_level(&app);
    return -1;
}

/*
 * WHICH ENTRY ROUTE SELECTS A GIVEN LEVEL.
 *
 * drive_app_to_level_loaded() takes a `list_index`, and the two values are not
 * interchangeable:
 *
 *   list_index < 0   Press SELECT on the main menu. That is BounceGame.java:241's
 *                    `MaxLevels > 1` gate failing, so it records a(true, 1) and
 *                    ALWAYS starts level 1 -- the level_id argument is only range
 *                    checked on this route. Passing -1 for every level therefore
 *                    silently tested level 1 eleven times, which is exactly the
 *                    vacuous check this function exists to avoid.
 *
 *   list_index >= 0  Press SELECT into Level Selection with the available count
 *                    set to level_id, walk down list_index rows, press SELECT
 *                    again. That is BounceGame.java:218-219's List command, and it
 *                    is the only route that reaches a level other than 1.
 *
 * Level 1 has no Level Selection row to walk to, because the count is 1 and the
 * menu gate at :241 is `> 1`, so it necessarily takes the first route. Every level
 * from 2 up must take the second, or it would be reported as level 1's data.
 */
static int door_list_index(int level_id)
{
    if (level_id <= BOUNCE_APP_FIRST_LEVEL_ID)
        return -1;
    return level_id - 1;
}

/*
 * Forward declarations for the three X11 helpers this check drives. They are
 * defined much further down, next to the dispatcher they belong to; declaring them
 * here keeps this verifier where it belongs chronologically -- with the other
 * resume/Continue checks -- instead of moving it below the X11 section purely to
 * satisfy the declaration order.
 */
static void dispatch_fixture_context(X11PresentationContext *context);
static void fill_key_event(
    XEvent *event,
    int type,
    unsigned int keycode,
    unsigned long serial,
    unsigned long time
);
static int x11_dispatch_event(
    X11PresentationContext *context,
    BounceApp *app,
    const XEvent *event,
    KeySym key
);

/*
 * EVERY LEVEL MUST BE PLAYABLE ON ARRIVAL, NOT JUST ON A DIRECT LOAD.
 *
 * THIS IS THE TRANSITION NOBODY WAS TESTING. Every other per-level check builds a
 * FRESH app and loads the level directly, which means it always observes a context
 * that has never run anything. A player does not arrive that way. They arrive at
 * level N+1 by finishing level N, and that route is a different chain with a
 * different history behind it:
 *
 *     bounce_game_mark_level_complete()  -> flow LEVEL_COMPLETE, deferred_init armed
 *     bounce_game_continue_level()       -> bounce_game_release_level(), stage START_LEVEL(N+1)
 *     app_begin_canonical_gameplay()     -> load -> player -> runtime -> camera
 *                                          -> activate -> timer
 *
 * The finished run leaves state behind -- the open door, the collected tiles, the
 * spent power-ups, the camera, the lives -- and only some of it is cleared on the
 * way. That is exactly the class of defect the door reset turned out to be, and it
 * was invisible for the same reason: a fresh-load fixture cannot see it.
 *
 * "PLAYABLE" IS THREE THINGS, NOT ONE, because a level can pass the first and still
 * strand the player:
 *
 *   IT LOADS. The right level id, from the right file.
 *   THE BALL FITS. The spawn is not inside the level. For the three big-ball levels
 *   this is a real question rather than a formality -- see verify_big_ball_spawn_fit()
 *   and f.java:168-206 -- and it is the state that survives a bad transition worst,
 *     because the ball is rebuilt from the level header and then nudged by the
 *     resolver, and both steps read geometry the previous run may have disturbed.
 *   THE BALL MOVES. The strongest form of "not stuck", and the only one that
 *     observes the symptom rather than a precondition of it: gravity alone, no
 *     input, over 90 ticks -- three and a half seconds at the source's 25 Hz. A ball
 *     wedged in a ceiling cannot fall, and this is what catches it.
 *
 * EVERY TRANSITION IS COVERED, 1 -> 2 through 10 -> 11, because the three big-ball
 * levels are scattered through that range (3, 5 and 11) and each is entered from a
 * different predecessor with a different amount of leftover state.
 */
static int verify_arrival_is_playable(void)
{
    int level_id;
    int bad = 0;
    int not_playable = 0;

    printf("ARRIVAL transitions=1->2..10->11 checks=level,ballSize,fit,moves\n");
    for (level_id = BOUNCE_APP_FIRST_LEVEL_ID;
         level_id < BOUNCE_APP_LAST_LEVEL_ID;
         ++level_id) {
        BounceApp app;
        int32_t target = level_id + 1;
        int32_t nominal_x;
        int32_t nominal_y;
        bool loaded_ok;
        bool size_ok;
        bool fits;
        bool moves;
        int run;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                   &app,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        /* Finish this level for real: every hoop, then the door, then completion. */
        while (app.hoops_scored < bounce_level_hoops_total(app.level)) {
            if (app_collect_hoop(&app, 1, 1, 13u, 0u) != 0) {
                bounce_game_shutdown(&app);
                return -1;
            }
        }
        if (!app.TODO_ExitUnlocked) {
            bounce_game_shutdown(&app);
            return -1;
        }
        if (bounce_game_mark_level_complete(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        /* The production route onward. See verify_door_resets_between_levels(). */
        bounce_game_timer_stop(&app.game_timer);
        if (bounce_game_continue_level(&app) < 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        /*
         * app_begin_canonical_gameplay() runs the WHOLE staged chain, and its last
         * step starts the timer (bounce_game_initialize_game_timer), so the timer is
         * already running here. Calling it again would be a second activation attempt
         * on a boundary that is not the LEVEL_LOADED one this function guards, and it
         * refuses -- which is why this check first reported a setup failure at level
         * 1 rather than a result.
         */
        if (app_begin_canonical_gameplay(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }

        loaded_ok = app.level != NULL
            && app.runtime != NULL
            && app.player.initialized
            && app.flow.state == BOUNCE_APP_STATE_GAMEPLAY
            && app.level_id == target;
        /*
         * The ball size is checked against the DESTINATION level's own header rather
         * than a constant, so a level that arrives carrying the previous level's ball
         * is caught even when the previous level happened to agree.
         */
        size_ok = app.player.ballSize
            == (bounce_level_is_big_ball(app.level) != 0u
                    ? BOUNCE_BIG_BALL_SIZE
                    : BOUNCE_REGULAR_BALL_SIZE);
        nominal_x = (int32_t) bounce_level_initial_x(app.level) * 12 + 6;
        nominal_y = (int32_t) bounce_level_initial_y(app.level) * 12 + 6;
        fits = loaded_ok
            && bounce_collision_query_level(
                   app.player.TODO_unkX,
                   app.player.TODO_unkY,
                   app.player.p,
                   app.level
               )
            /*
             * A big-ball level whose ball landed exactly on the nominal point means
             * the resolver never ran, and the fit above would then be measuring the
             * wrong position rather than the one that would be played.
             */
            && (app.player.ballSize != BOUNCE_BIG_BALL_SIZE
                || app.player.TODO_unkX != nominal_x
                || app.player.TODO_unkY != nominal_y);
        moves = false;
        if (loaded_ok) {
            int32_t first_x = app.player.TODO_unkX;
            int32_t first_y = app.player.TODO_unkY;

            for (run = 0; run < 90; ++run) {
                BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

                if (app_timer_callback_dispatch(&app, &branch) != 0)
                    break;
                if (app.player.TODO_unkX != first_x
                    || app.player.TODO_unkY != first_y) {
                    moves = true;
                    break;
                }
            }
        }
        printf("ARRIVAL %2d->%2d loaded=%s ball=%d/%d nominal=(%ld,%ld)"
               " at=(%ld,%ld) fits=%s moves=%s %s\n",
               level_id,
               (int) target,
               loaded_ok ? "yes" : "no",
               (int) app.player.ballSize,
               (int) app.player.p,
               (long) nominal_x,
               (long) nominal_y,
               (long) app.player.TODO_unkX,
               (long) app.player.TODO_unkY,
               fits ? "yes" : "no",
               moves ? "yes" : "no",
               (loaded_ok && size_ok && fits && moves) ? "PASS" : "FAIL");
        if (!(loaded_ok && size_ok && fits && moves))
            ++not_playable;
        if (!(loaded_ok && size_ok && fits && moves))
            bad = 1;
        bounce_game_shutdown(&app);
    }
    printf("ARRIVAL summary transitions=10 not_playable=%d expected=0 %s\n",
           not_playable,
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * A BIG BALL MUST NOT SPAWN INSIDE THE LEVEL.
 *
 * THE ONLY THREE LEVELS WHERE THIS CAN HAPPEN. Levels 3, 5 and 11 are the shipped
 * levels whose header byte 2 is non-zero, and f.java:127-131 turns that into a
 * different ball constructor:
 *
 *     if (ballSize == 12) UseRegularBall();   // 12 px, p 6, no resolver
 *     else               UseBigBall();       // 16 px, p 8, WITH a resolver
 *
 * A 16 px ball in a 12 px cell grid has a box two cells wide and one-and-a-half
 * cells tall, so a spawn cell that is clear for the small ball can still bury the
 * big one in its neighbours. Level 5 is the clearest case in the shipped set: the
 * spawn cell (32,32) is empty, but the whole row above it, row 31, is brick wall
 * across columns 31..35, and the nominal position (390,390) has its box covering
 * rows 31..33. A ball left there is embedded in a ceiling.
 *
 * WHAT THE SOURCE DOES ABOUT IT. f.java:173-206, inside UseBigBall() only:
 *
 *     for (byte offset = 1; !TODO_collidesWithLevel; offset++) {
 *         TODO_collidesWithLevel = true;
 *         if (TODO_CheckBallCollision(x, y - offset))            { y -= offset; continue; }
 *         if (TODO_CheckBallCollision(x - offset, y - offset))   { x -= offset; y -= offset; continue; }
 *         if (TODO_CheckBallCollision(x + offset, y - offset))   { x += offset; y -= offset; continue; }
 *         if (TODO_CheckBallCollision(x, y + offset))            { y += offset; continue; }
 *         if (TODO_CheckBallCollision(x - offset, y + offset))   { x -= offset; y += offset; continue; }
 *         if (TODO_CheckBallCollision(x + offset, y + offset))   { x += offset; y += offset; continue; }
 *         TODO_collidesWithLevel = false;
 *     }
 *
 * Six candidates per offset, offset growing until one of them lands the ball on a
 * free spot. Note that all six change y, so the resolver can move the ball DOWN as
 * well as up: on level 5 it has to, because the ceiling is above and the pocket
 * that fits is below. An implementation that only searched upward would leave the
 * ball in the ceiling there, which is the stuck case this check exists for.
 *
 * TWO SEPARATE CLAIMS ARE ASSERTED, because the resolver and the fit are different
 * things and either can be broken on its own:
 *
 *   THE PROBE RAN. The spawn position must differ from the bare header formula
 *   `tile * 12 + 6`, which is what proves the resolver was reached at all. A ball
 *   sitting exactly on the nominal point on a big-ball level means the resolver was
 *   skipped, and every other assertion here would then be measuring the wrong thing.
 *
 *   THE RESULT IS FREE. The settled position must pass the SAME predicate the
 *   resolver tests, `bounce_collision_query_level()` -- the f.TODO_CheckBallCollision
 *   traversal over the pristine level. Asserting the outcome with the resolver's
 *   own predicate is what makes "not stuck" mean "the source would agree it fits",
 *   rather than "it fits according to a different rule".
 *
 * THE PRODUCTION PATH IS THE ONE DRIVEN. The session is built through the staged
 * entry chain, so this covers bounce_game_initialize_player_entry()'s call to
 * bounce_player_use_big_ball_level() rather than the legacy loader's.
 */
static int verify_big_ball_spawn_fit(void)
{
    /* The shipped levels whose header byte 2 selects UseBigBall(). */
    static const int big_ball_levels[] = { 3, 5, 11 };
    unsigned int index;
    int bad = 0;
    int not_free = 0;
    int probe_skipped = 0;

    printf("BIGBALL-SPAWN levels=3,5,11 predicate=bounce_collision_query_level"
           " (f.TODO_CheckBallCollision)\n");
    for (index = 0u;
         index < sizeof big_ball_levels / sizeof big_ball_levels[0];
         ++index) {
        BounceApp app;
        int level_id = big_ball_levels[index];
        int32_t nominal_x;
        int32_t nominal_y;
        bool is_big;
        bool probe_ran;
        bool free_at_settle;
        bool free_after_runtime = false;
        bool respawn_is_big;
        bool respawn_free = false;
        bool ball_moves = false;
        bool never_embedded = false;
        int32_t settled_x;
        int32_t settled_y;
        int32_t respawn_x = 0;
        int32_t respawn_y = 0;

        memset(&app, 0, sizeof app);
        if (bounce_game_init(&app) != 0
            || bounce_game_enter_menu(&app) != 0
            || drive_app_to_level_loaded(
                   &app,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&app) != 0
            || app_advance_player_initialized_to_runtime_initialized(&app) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
            || app_advance_camera_initialized_to_activated(&app) != 0
            /*
             * The timer has to be running for the movement half of this check to
             * mean anything. bounce_game_tick_dispatch() refuses while the timer is
             * stopped (game_timer.c:150-151), so without this the dispatch returns
             * without running any physics and the ball would report as "never
             * moved" no matter what the level contained -- which is exactly the
             * false failure this check first produced.
             */
            || bounce_game_initialize_game_timer(&app) != 0) {
            bounce_game_shutdown(&app);
            return -1;
        }
        /* The header formula, e.java:121: tile * 12 + 6 on both axes. */
        nominal_x = (int32_t) bounce_level_initial_x(app.level) * 12 + 6;
        nominal_y = (int32_t) bounce_level_initial_y(app.level) * 12 + 6;
        is_big = app.player.ballSize == BOUNCE_BIG_BALL_SIZE
            && app.player.p == BOUNCE_BIG_BALL_P;
        settled_x = app.player.TODO_unkX;
        settled_y = app.player.TODO_unkY;
        probe_ran = (settled_x != nominal_x) || (settled_y != nominal_y);
        free_at_settle = bounce_collision_query_level(
            settled_x, settled_y, app.player.p, app.level);
        /*
         * And again against the runtime copy, because that is the grid the ball
         * will actually live in once play starts. A level-load-time fit that does not
         * survive the copy would still be a ball embedded in the world.
         */
        if (app.runtime != NULL) {
            free_after_runtime = bounce_collision_query(
                settled_x, settled_y, app.player.p, app.runtime);
        }
        /*
         * THE RESPAWN, which is the other way a big ball appears on these levels and
         * the one a player actually reaches by dying.
         *
         * Java rebuilds the ball through e.java:277:
         *
         *     a(this.aq.d * 12 + 6, this.aq.c * 12 + 6, this.aq.b, 0, 0);
         *
         * where `this.aq.b` is the size the CHECKPOINT recorded (f.java:137), not the
         * level's own header size. So on a big-ball level the respawn is a big-ball
         * construction, and f.java:127-131 routes it through UseBigBall() and its
         * resolver all over again -- at the checkpoint cell, which is a DIFFERENT
         * piece of geometry from the level spawn. A level whose start cell is open
         * can still have a checkpoint tucked under a ceiling, and that is a second,
         * independent chance for the ball to come back embedded.
         *
         * The death is produced by app_kill_ball() and consumed by
         * app_respawn_after_death(), both production functions, so the whole
         * respawn chain runs.
         */
        /*
         * AND THE DIRECT QUESTION: DOES THE BALL ACTUALLY MOVE? Everything above
         * checks that the spawn position is not embedded. That is necessary but not
         * sufficient -- a ball can sit in a legal cell and still be wedged, unable to
         * fall, roll or jump out, because the resolver only guarantees ONE offset is
         * collision-free; it says nothing about whether the surrounding geometry lets
         * the ball travel. So the position is sampled across a run of real ticks and
         * required to change, and every intermediate position is required to stay
         * free. A ball that never moves is the stuck case, and this is the only
         * assertion here that observes it directly.
         *
         * No input is applied, so any motion is gravity and residual velocity alone.
         * 90 ticks is more than three and a half seconds at 25 Hz, which is far more
         * than a ball needs to fall the four rows to the floor.
         */
        {
            int32_t first_x = app.player.TODO_unkX;
            int32_t first_y = app.player.TODO_unkY;
            int moved = 0;
            int embedded_mid_run = 0;
            int run;

            for (run = 0; run < 90; ++run) {
                BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

                if (app_timer_callback_dispatch(&app, &branch) != 0)
                    break;
                if (app.player.TODO_unkX != first_x
                    || app.player.TODO_unkY != first_y) {
                    moved = 1;
                }
                if (!bounce_collision_query(
                        app.player.TODO_unkX,
                        app.player.TODO_unkY,
                        app.player.p,
                        app.runtime)) {
                    embedded_mid_run = 1;
                    break;
                }
            }
            ball_moves = (moved != 0);
            never_embedded = (embedded_mid_run == 0);
        }

        app.god_mode = false;
        app.lives = 3;
        app.state = BOUNCE_GAME_STATE_PLAYING;
        app_kill_ball(&app);
        (void)app_respawn_after_death(&app);
        respawn_is_big = app.player.ballSize == BOUNCE_BIG_BALL_SIZE
            && app.player.p == BOUNCE_BIG_BALL_P;
        respawn_x = app.player.TODO_unkX;
        respawn_y = app.player.TODO_unkY;
        respawn_free = bounce_collision_query(
            respawn_x, respawn_y, app.player.p, app.runtime);

        printf("BIGBALL-SPAWN level=%2d big_ball=%s nominal=(%ld,%ld)"
               " settled=(%ld,%ld) probe_ran=%s fits_level=%s fits_runtime=%s"
               " | moves=%s never_embedded=%s"
               " | respawn_big=%s respawn=(%ld,%ld) respawn_fits=%s"
               " %s\n",
               level_id,
               is_big ? "yes" : "no",
               (long) nominal_x,
               (long) nominal_y,
               (long) settled_x,
               (long) settled_y,
               probe_ran ? "yes" : "no",
               free_at_settle ? "yes" : "no",
               free_after_runtime ? "yes" : "no",
               ball_moves ? "yes" : "no",
               never_embedded ? "yes" : "no",
               respawn_is_big ? "yes" : "no",
               (long) respawn_x,
               (long) respawn_y,
               respawn_free ? "yes" : "no",
               (is_big && probe_ran && free_at_settle && free_after_runtime
                   && ball_moves && never_embedded
                   && respawn_is_big && respawn_free)
                   ? "PASS"
                   : "FAIL");
        if (!is_big || !probe_ran)
            ++probe_skipped;
        if (!free_at_settle || !free_after_runtime || !respawn_free
            || !ball_moves || !never_embedded) {
            ++not_free;
        }
        if (!is_big || !probe_ran || !free_at_settle || !free_after_runtime
            || !ball_moves || !never_embedded
            || !respawn_is_big || !respawn_free) {
            bad = 1;
        }
        bounce_game_shutdown(&app);
    }
    printf("BIGBALL-SPAWN summary levels=3 probe_skipped=%d not_free=%d"
           " spawn+movement+respawn checked=yes expected=0 0 %s\n",
           probe_skipped,
           not_free,
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * THE LIVES LADDER, WALKED ALL THE WAY DOWN.
 *
 * THE SHAPE THE PLAYER DESCRIBES, WHICH IS ALSO THE SHAPE THE SOURCE HAS:
 *
 *     lives = 5  (the cap, f.java:611)
 *     die -> 4
 *     die -> 3
 *     die -> 2
 *     die -> 1
 *     die -> 0     <- still a PLAYABLE life, not the end
 *     die -> -1    <- and only now does e.java:268 fire
 *
 * Six deaths from a full set of five, and the sixth is the one that ends the run.
 * Two things make that non-obvious and both are easy to get wrong:
 *
 *   THE DECAY IS A DECREMENT, NOT A SET. f.java:219 is `this.n.lives--`, inside the
 *   `if (!this.n.GodMode)` body, so the ladder passes through every value rather
 *   than jumping straight to -1. An implementation that wrote -1 on the first death
 *   would produce the same game-over moment and a completely different game: five
 *   lives would be worth one.
 *
 *   lives == 0 IS NOT GAME OVER. The boundary is e.java:268 `if (this.lives < 0)`,
 *   strictly less than zero, so a run sitting on 0 still has a life to lose. Firing
 *   the game over at 0 would take a life away without being asked to.
 *
 * The 1-up is checked in the same run because the cap is the other half of the
 * ladder: f.java:611-613 is `if (this.n.lives < 5) { this.n.lives++; }`, so a pickup
 * at 4 reaches 5 and a further pickup at 5 changes nothing while still scoring.
 *
 * EVERY FUNCTION CALLED HERE IS THE PRODUCTION ONE. The death is app_kill_ball()
 * (the f.java:215 transcription), the game-over test and respawn are
 * app_respawn_after_death() (e.java:267-281), and the pickup is
 * app_consume_extra_life() (f.java:609-617). Asserting the ladder against anything
 * else would only prove that arithmetic works.
 *
 * WHY IT IS NOT COVERED ELSEWHERE. The existing checks assert single transitions --
 * one death taking 3 to 2, the GodMode guard refusing one, the pickup's placement
 * relative to the cap. None of them walks the ladder to its end, so a regression
 * that turned the decrement into a reset, or moved the boundary to `<= 0`, would
 * leave all of them passing while the game silently became one life long.
 */
static int verify_lives_ladder(void)
{
    BounceApp app;
    /* The ladder a full set of five has to produce, death by death. */
    static const int expected_after_death[6] = { 4, 3, 2, 1, 0, -1 };
    int observed[6];
    /*
     * Whether the run was still PLAYABLE after each death. This is the half of the
     * contract the ladder of numbers alone cannot express: a decrement that jumped
     * straight to -1 would still print 4,3,2,1,0,-1 if the arithmetic were faked, and
     * a boundary moved to `<= 0` would still print the same six numbers while
     * silently ending the run one life early. Both of those regressions were
     * actually tried against an earlier version of this check, and the numeric
     * ladder alone caught NEITHER -- the first because the printout was faked, the
     * second because the numbers are identical either way. Asserting the run's own
     * state after each death is what makes the "0 is still a life" claim testable.
     */
    bool still_playable[6];
    int deaths;
    bool ladder_ok = true;
    bool zero_still_playable = true;
    bool end_only_on_last = true;
    bool oneup_under_cap;
    bool oneup_at_cap;
    int bad = 0;

    memset(observed, 0, sizeof observed);
    memset(still_playable, 0, sizeof still_playable);
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0
        || drive_app_to_level_loaded(&app, -1, 1) != 0
        || app_advance_level_loaded_to_player_initialized(&app) != 0
        || app_advance_player_initialized_to_runtime_initialized(&app) != 0
        || app_advance_runtime_initialized_to_camera_initialized(&app) != 0
        || app_advance_camera_initialized_to_activated(&app) != 0
        || bounce_game_initialize_game_timer(&app) != 0) {
        bounce_game_shutdown(&app);
        return -1;
    }
    /* GodMode must be off or f.java:216 swallows every death (f.java:216-225). */
    app.god_mode = false;
    app.lives = 5;

    for (deaths = 0; deaths < 6; ++deaths) {
        app_kill_ball(&app);
        observed[deaths] = app.lives;
        /*
         * The game-over test runs here, exactly where e.java:267-273 runs: after
         * the death write and inside the same tick, before the respawn rebuild.
         */
        (void)app_respawn_after_death(&app);
        /*
         * The ball respawned and the run carries on iff the state is still PLAYING.
         * app_respawn_after_death() is the whole of e.java:267-281: the lives < 0 arm
         * hands over to the terminal flow, and every other arm rebuilds the player at
         * the spawn or checkpoint and leaves the run playable.
         */
        still_playable[deaths] = (app.state == BOUNCE_GAME_STATE_PLAYING);
    }
    /* The fifth death leaves lives == 0, which must still be playable. */
    zero_still_playable = still_playable[4];
    /* And only the sixth, the one that reaches lives == -1, may end the run. */
    end_only_on_last = true;
    for (deaths = 0; deaths < 5; ++deaths) {
        if (!still_playable[deaths])
            end_only_on_last = false;
    }
    if (still_playable[5])
        end_only_on_last = false;
    for (deaths = 0; deaths < 6; ++deaths) {
        if (observed[deaths] != expected_after_death[deaths])
            ladder_ok = false;
    }

    /*
     * THE CAP, from f.java:611. A pickup one below the ceiling reaches it, and a
     * further pickup leaves it alone. The score is deliberately not asserted here;
     * f.java:610 awards it OUTSIDE the guard, which verify_tile_51_54_powerup()
     * already covers, and mixing the two would make this failure ambiguous.
     */
    app.lives = 4;
    if (app_consume_extra_life(&app, 1, 1, 29u) != 0)
        ladder_ok = false;
    oneup_under_cap = (app.lives == 5);
    if (app_consume_extra_life(&app, 2, 1, 29u) != 0)
        ladder_ok = false;
    oneup_at_cap = (app.lives == 5);
    bounce_game_shutdown(&app);

    if (!ladder_ok || !zero_still_playable || !end_only_on_last
        || !oneup_under_cap || !oneup_at_cap) {
        bad = 1;
    }
    printf("LIVES-LADDER start=5 deaths=6 ladder=%d,%d,%d,%d,%d,%d"
           " decrement_not_reset=%s zero_still_playable=%s"
           " end_only_on_sixth_death=%s oneup_4_to_5=%s oneup_capped_at_5=%s"
           " expected=4,3,2,1,0,-1 yes yes yes yes yes %s\n",
           observed[0], observed[1], observed[2],
           observed[3], observed[4], observed[5],
           ladder_ok ? "yes" : "no",
           zero_still_playable ? "yes" : "no",
           end_only_on_last ? "yes" : "no",
           oneup_under_cap ? "yes" : "no",
           oneup_at_cap ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * A FINISHED RUN MUST NOT LEAVE A CONTINUE BEHIND, AND A LIVE ONE MUST.
 *
 * IT DRIVES x11_dispatch_event(), NOT THE HELPER. That is the whole point of the
 * test and the reason the first version of it was worthless: calling
 * app_persist_resume_snapshot_for_continue() directly and then asserting the store
 * proves only that the helper writes, which was never in doubt. The missing write
 * was a missing CALL, and only the production edge can be missing a call. So both
 * phases synthesise the keystroke a player would press and let the real dispatcher
 * run the capture, the publish and the refresh, exactly as the frame loop does.
 *
 * THE SEQUENCE BEING TESTED. The reported defect needed three things to line up: a
 * stale record in the store from an earlier session, a run that ended without going
 * through application teardown, and an availability refresh that reads the store
 * rather than the in-memory capture. So each phase primes the store with a record
 * that is deliberately WRONG for the current session, ends the session the way the
 * UI ends it, and then asserts both the store and the menu row.
 *
 *   PHASE A -- the game over case, and the one that was reported.
 *     The store is primed with b1 == 1 at LEVEL 2, which is the shape of the bug: a
 *     valid-looking Continue pointing at a level the player has already left. A live
 *     session is then marked as the Game Over screen and the form's own OK command is
 *     pressed. The store must end up holding b1 == 0 and the menu must not offer
 *     Continue. With the publish missing, the primed record survives and Continue
 *     stays enabled -- which is exactly what was observed.
 *
 *     The flow state is set directly rather than driven through the death pipeline,
 *     because app_capture_resume_snapshot() keys off the state it is given and
 *     nothing else in this contract reads the ball. The pipeline that decides a
 *     session reaches Game Over is covered by verify_w1_completion_request_latch()
 *     and the b1 mapping by RECORD3-TERMINAL-B1; re-deriving them here would add a
 *     second, weaker copy of both.
 *
 *   PHASE B -- the live case, so phase A cannot pass vacuously.
 *     The store is primed INERT, a live session with lives is on the board, and the
 *     Escape key -- the native gameplay-to-menu edge -- is pressed. The store must
 *     end up holding b1 == 1 at the level actually being played, with Continue
 *     offered. Without this, "inert after game over" would also be satisfied by a
 *     publish that wrote nothing, or wrote the same thing unconditionally.
 *
 * THE STORE IS REDIRECTED, so the test can never read or damage a real save.
 */
static int verify_continue_publication(void)
{
    static const char template[] = "/tmp/bounce-continue-XXXXXX";
    char root[sizeof template];
    char saved[512];
    int saved_ok;
    BounceApp app;
    X11PresentationContext context;
    XEvent event;
    BouncePersistenceRecord3 prime;
    BouncePersistenceRecord3 back;
    bool present = false;
    bool stale_primed;
    bool gameover_store_inert = false;
    bool gameover_row_hidden = false;
    bool live_store_present = false;
    bool live_store_in_level = false;
    bool live_row_shown = false;
    int bad = 0;

    memcpy(root, template, sizeof root);
    if (mkdtemp(root) == NULL)
        return -1;
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0)
        return -1;

    /* ---------- PHASE A: a stale Continue must not survive a game over ---------- */
    memset(&prime, 0, sizeof prime);
    prime.b1 = (uint8_t)BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    prime.level = 2;
    prime.lives = 3;
    prime.score = 1234;
    prime.hoops_scored = 6;
    stale_primed = bounce_persistence_save_record3(&prime) == 0;

    memset(&app, 0, sizeof app);
    if (stale_primed
        && bounce_game_init(&app) == 0
        && bounce_game_enter_menu(&app) == 0
        && drive_app_to_level_loaded(&app, door_list_index(3), 3) == 0
        && app_advance_level_loaded_to_player_initialized(&app) == 0
        && app_advance_player_initialized_to_runtime_initialized(&app) == 0
        && app_advance_runtime_initialized_to_camera_initialized(&app) == 0
        && app_advance_camera_initialized_to_activated(&app) == 0
        && bounce_game_initialize_game_timer(&app) == 0) {
        /* The Game Over screen, reached with the session still owned. */
        app.flow.state = BOUNCE_APP_STATE_GAME_OVER;
        app.state = BOUNCE_GAME_STATE_GAME_OVER;
        dispatch_fixture_context(&context);
        fill_key_event(&event, KeyPress, 9u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Escape) == 0) {
            (void)bounce_persistence_load_record3(&back, &present);
            gameover_store_inert = present
                && back.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
            gameover_row_hidden
                = app.flow.state == BOUNCE_APP_STATE_MENU
                && !bounce_app_flow_menu_item_enabled(&app.flow, 0u);
        }
    }
    bounce_game_shutdown(&app);

    /* ---------- PHASE B: a live run with lives must publish a resumable record --- */
    memset(&prime, 0, sizeof prime);
    prime.b1 = (uint8_t)BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
    prime.level = 11;
    prime.lives = -1;
    (void)bounce_persistence_save_record3(&prime);

    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) == 0
        && bounce_game_enter_menu(&app) == 0
        && drive_app_to_level_loaded(&app, door_list_index(5), 5) == 0
        && app_advance_level_loaded_to_player_initialized(&app) == 0
        && app_advance_player_initialized_to_runtime_initialized(&app) == 0
        && app_advance_runtime_initialized_to_camera_initialized(&app) == 0
        && app_advance_camera_initialized_to_activated(&app) == 0
        && bounce_game_initialize_game_timer(&app) == 0) {
        dispatch_fixture_context(&context);
        fill_key_event(&event, KeyPress, 9u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Escape) == 0) {
            (void)bounce_persistence_load_record3(&back, &present);
            live_store_present = present
                && back.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
            live_store_in_level = back.level == 5;
            live_row_shown = app.flow.state == BOUNCE_APP_STATE_MENU
                && bounce_app_flow_menu_item_enabled(&app.flow, 0u);
        }
    }
    bounce_game_shutdown(&app);

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");

    if (!stale_primed
        || !gameover_store_inert
        || !gameover_row_hidden
        || !live_store_present
        || !live_store_in_level
        || !live_row_shown) {
        bad = 1;
    }
    printf("CONTINUE-PUBLISH stale_primed=%s gameover_store_inert=%s"
           " gameover_row_hidden=%s live_store_present=%s"
           " live_store_in_level=%s live_row_shown=%s"
           " expected=yes yes yes yes yes yes %s\n",
           stale_primed ? "yes" : "no",
           gameover_store_inert ? "yes" : "no",
           gameover_row_hidden ? "yes" : "no",
           live_store_present ? "yes" : "no",
           live_store_in_level ? "yes" : "no",
           live_row_shown ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * THE DOOR MUST START SHUT ON EVERY LEVEL BUT THE FIRST.
 *
 * THIS IS THE ONE TRANSITION NONE OF THE OTHER CHECKS COVERS, AND IT IS THE ONE
 * THAT EXPLAINS "levels 2 to 11".
 *
 * The reset lives in bounce_game_load_level() (game.c:400-403), which clears
 * TODO_ExitUnlocked, door_image_offset and door_open_flag together. Every check so
 * far builds a FRESH app and loads a level directly, so it proves the reset runs
 * when a level is loaded -- and says nothing about whether it runs on the route
 * that actually follows a completed level. A player never reaches level 2 by
 * loading it; they reach it by finishing level 1, and that is a different chain:
 *
 *   bounce_game_mark_level_complete()  ->  BOUNCE_APP_STATE_LEVEL_COMPLETE
 *   bounce_game_continue_level()       ->  release, stage START_LEVEL(N+1)
 *   app_begin_canonical_gameplay()     ->  bounce_game_load_level_entry(N+1)
 *
 * If any link of that chain skips the load, the new level inherits the finished
 * one's door: door_image_offset is still 24 and door_open_flag still true, so the
 * exit is drawn in its OPEN frame and admits the ball from the first tick. That is
 * precisely the reported symptom, and it is invisible to a fresh-load fixture for
 * the strongest possible reason -- level 1 is the only level that can be reached
 * without a predecessor, so level 1 is the only level a fresh-load fixture proves
 * anything about.
 *
 * WHAT IS ASSERTED, PER LEVEL. The door is driven fully open on level N through the
 * real producer, the level is completed through the real M gate, the production
 * Continue runs, and the staging chain is driven to the point where level N+1 is
 * owned. Then all three pieces of door state must be back at their level-load
 * values. door_open_flag alone is not enough: it is the latch, while
 * door_image_offset is what the renderer reads, and a reset that cleared only the
 * latch would leave the open frame on screen while the gate correctly refused.
 */
static int verify_door_resets_between_levels(void)
{
    int level_id;
    int bad = 0;
    int stale = 0;

    for (level_id = BOUNCE_APP_FIRST_LEVEL_ID;
         level_id < BOUNCE_APP_LAST_LEVEL_ID;
         ++level_id) {
        BounceApp run;
        int32_t exit_col;
        int32_t exit_row;
        int32_t total_hoops;
        int tick;
        bool opened = false;
        bool completed = false;
        bool next_loaded = false;
        bool reset_ok = false;
        int32_t next_total = 0;

        memset(&run, 0, sizeof run);
        if (bounce_game_init(&run) != 0
            || bounce_game_enter_menu(&run) != 0
            || drive_app_to_level_loaded(
                   &run,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&run) != 0
            || app_advance_player_initialized_to_runtime_initialized(&run) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&run) != 0
            || app_advance_camera_initialized_to_activated(&run) != 0
            || bounce_game_initialize_game_timer(&run) != 0) {
            bounce_game_shutdown(&run);
            return -1;
        }
        exit_col = (int32_t)bounce_level_exit_x(run.level);
        exit_row = (int32_t)bounce_level_exit_y(run.level);
        total_hoops = bounce_level_hoops_total(run.level);
        if (exit_col < 0 || exit_row < 0 || total_hoops <= 0) {
            bounce_game_shutdown(&run);
            return -1;
        }

        /* Open this level's door for real, then stand on it until it completes. */
        while (run.hoops_scored < total_hoops) {
            if (app_collect_hoop(&run, 1, 1, 13u, 0u) != 0) {
                bounce_game_shutdown(&run);
                return -1;
            }
        }
        for (tick = 0; tick < 40 && !opened; ++tick) {
            BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

            run.player.TODO_unkX = exit_col * BOUNCE_TILE_SIZE + 6;
            run.player.TODO_unkY = exit_row * BOUNCE_TILE_SIZE + 6;
            if (app_timer_callback_dispatch(&run, &branch) != 0) {
                bounce_game_shutdown(&run);
                return -1;
            }
            if (run.door_open_flag)
                opened = true;
        }
        /*
         * The completion is entered through bounce_game_mark_level_complete(),
         * which is the production transcription of f.java:602 `this.n.e = true` --
         * the single write the tile-9 collision performs -- and of e.java:313-317.
         * It is called directly rather than by parking the ball on the door,
         * because parking a big ball inside the level's own geometry makes the
         * tile walk abort on a blocking cell first (f.java:159-162), which is a
         * property of the fixture and not of the door; see the note in
         * verify_door_waits_for_hoops(). Using the production entry point keeps
         * this transition under test instead of under the walk's abort rule.
         */
        if (!opened) {
            bounce_game_shutdown(&run);
            return -1;
        }
        /*
         * The tick loop may already have completed the level, because the ball was
         * parked on the door and the M gate is live by then. That is the normal
         * outcome and is accepted as-is; mark_level_complete() is only called when
         * it has not happened yet, and it refuses anything but PLAYING, so the
         * two orderings cannot both be attempted.
         */
        completed = run.level_complete;
        if (!completed) {
            if (bounce_game_mark_level_complete(&run) != 0) {
                bounce_game_shutdown(&run);
                return -1;
            }
            completed = run.level_complete;
        }
        if (!completed) {
            bounce_game_shutdown(&run);
            return -1;
        }

        /*
         * THE PRODUCTION ROUTE ONWARD, AND IT IS THE ONE JAVA TAKES.
         *
         * bounce_game_mark_level_complete() ends by arming deferred_init, which is
         * Java's `this.d = true` at e.java:316. The next Tick consumes it:
         *
         *   e.java:222-226   if (this.d) { InitializeGame(); repaint(); return; }
         *   e.java:115-124   InitializeGame() -> LoadLevelId(this.level)
         *   b.java:239         CreateTiles(this.exitX, this.exitY, Sprites[EXIT])
         *   b.java:814,816       this.b = 0;   this.M = false;
         *
         * So ONE further dispatch IS the whole level transition in the original,
         * and the loader it reaches is bounce_game_tick_dispatch()'s deferred arm
         * (game.c:974-979) calling bounce_game_load_level_entry(). Driving that is
         * what makes this a test of the real route rather than a reconstruction:
         * bounce_game_continue_level() and the staged entry are the other route,
         * and they reach the same loader, so the reset is asserted on the route a
         * player actually takes when a level ends.
         *
         */
        /*
         * THE STAGED ENTRY, i.e. what the Level Complete screen's Continue does.
         *
         * bounce_game_continue_level() is BounceGame.java:263-266 -- it releases
         * the finished run and stages START_LEVEL(level + 1) -- and
         * app_begin_canonical_gameplay() is the frame loop's own driver of the
         * staged chain, which reaches bounce_game_load_level_entry() through
         * app_advance_gameplay_entry_to_level_loaded(). Both are the production
         * functions, called in the production order.
         *
         * The timer stop is explicit because the test cannot reach the one that
         * normally happens first. In play, game.c:978 stops it inside
         * bounce_game_tick_dispatch()'s deferred arm; here the completion was
         * entered by calling bounce_game_mark_level_complete() directly, so no tick
         * tail follows it and the timer is still running. bounce_game_initialize_
         * game_timer() is idempotent in the Java sense (b.java:836-837) and refuses
         * to start over a running timer, so without this the staging would fail for
         * a reason that has nothing to do with the door.
         */
        bounce_game_timer_stop(&run.game_timer);
        if (bounce_game_continue_level(&run) < 0) {
            bounce_game_shutdown(&run);
            return -1;
        }
        if (app_begin_canonical_gameplay(&run) != 0) {
            bounce_game_shutdown(&run);
            return -1;
        }
        next_loaded = run.level != NULL && run.runtime != NULL;
        if (next_loaded) {
            next_total = bounce_level_hoops_total(run.level);
            reset_ok = !run.TODO_ExitUnlocked
                && run.door_image_offset == 0
                && !run.door_open_flag
                && run.hoops_scored == 0
                && run.level_id == level_id + 1
                && next_total > 0;
        }
        if (!reset_ok)
            ++stale;
        if (!next_loaded || !reset_ok)
            bad = 1;
        printf("DOOR-RESET %2d->%2d next_loaded=%s unlock=%d offset=%d"
               " open=%d hoops=%d level_id=%d next_hoops=%ld all_reset=%s %s\n",
               level_id,
               level_id + 1,
               next_loaded ? "yes" : "no",
               (int)run.TODO_ExitUnlocked,
               (int)run.door_image_offset,
               (int)run.door_open_flag,
               (int)run.hoops_scored,
               (int)run.level_id,
               (long)next_total,
               reset_ok ? "yes" : "no",
               (next_loaded && reset_ok) ? "PASS" : "FAIL");
        bounce_game_shutdown(&run);
    }
    printf("DOOR-RESET summary transitions=10 stale_door=%d expected=0 %s\n",
           stale,
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * NO SINGLE TICK MAY COUNT MORE THAN ONE HOOP.
 *
 * WHY THIS IS ITS OWN CHECK, AND WHY IT IS THE LIKELY DEFECT. The unlock is
 * `HoopsScored == HoopsTotal`, and the only writer of HoopsScored is
 * app_collect_hoop(). So the exit opening "too early" is not a door problem at
 * all -- the door gate is downstream of the counter and faithfully obeys it. The
 * only way the exit can open while hoops remain on the map is for the counter to
 * reach the total before every hoop has actually been taken. If one physical hoop
 * were counted twice, the door would open at half the hoops, and the symptom
 * would be exactly the reported one.
 *
 * THE MECHANISM IT LOOKS FOR. A hoop is two adjacent cells (f.java:508/518/539
 * write the consumed PAIR, and app_collect_hoop() reproduces that: the self cell
 * and its partner are both rewritten to their consumed ids before the counter is
 * touched). Once that holds, the second half cannot be collected again, because
 * the consumed ids are not in app_hoop_collect_gate_id(). The failure mode that
 * would break this is a tile walk that READS all of its cells up front and
 * processes the cached values afterwards: the rewrite would then be invisible to
 * the walk's own second half, and the pair would score twice in one tick.
 *
 * WHY THE WHOLE LEVEL IS SWEPT RATHER THAN ONE SPOT. Whether both halves land in
 * the same tick depends on where the hoops sit relative to the ball's walk box,
 * which differs per level and per hoop orientation. A single fixture would only
 * test the one spot it happened to pick -- which is how a defect can live in the
 * tree while every existing check passes. So every hoop cell in every level is
 * visited, from a ball placed on that cell, and the counter's per-tick delta is
 * recorded.
 *
 * WHY IT IS A MAX-OVER-ALL-TICKS RATHER THAN A TOTAL. The end state cannot show
 * the defect: if every cell is visited once and each scores, the total lands on
 * HoopsTotal either way. Only the per-tick delta shows it.
 *
 * ALSO ASSERTED, because a double count has a second signature: the counter must
 * never exceed the number of distinct hoops the level actually contains.
 */
static int verify_hoop_counter_no_double_count(void)
{
    int level_id;
    int bad = 0;
    int levels_with_double = 0;
    long worst_delta = 0;

    for (level_id = BOUNCE_APP_FIRST_LEVEL_ID;
         level_id <= BOUNCE_APP_LAST_LEVEL_ID;
         ++level_id) {
        BounceApp hoop;
        int32_t total_hoops;
        int32_t grid_w;
        int32_t grid_h;
        int32_t x;
        int32_t y;
        long worst = 0;
        int over_total = 0;

        memset(&hoop, 0, sizeof hoop);
        if (bounce_game_init(&hoop) != 0
            || bounce_game_enter_menu(&hoop) != 0
            || drive_app_to_level_loaded(
                   &hoop,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&hoop) != 0
            || app_advance_player_initialized_to_runtime_initialized(&hoop) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&hoop) != 0
            || app_advance_camera_initialized_to_activated(&hoop) != 0
            || bounce_game_initialize_game_timer(&hoop) != 0) {
            bounce_game_shutdown(&hoop);
            return -1;
        }
        total_hoops = bounce_level_hoops_total(hoop.level);
        grid_w = (int32_t)bounce_runtime_level_tiles_width(hoop.runtime);
        grid_h = (int32_t)bounce_runtime_level_tiles_height(hoop.runtime);
        if (total_hoops <= 0 || grid_w <= 0 || grid_h <= 0) {
            bounce_game_shutdown(&hoop);
            return -1;
        }

        for (y = 0; y < grid_h && !over_total; ++y) {
            for (x = 0; x < grid_w; ++x) {
                uint16_t value = 0u;
                int32_t before;
                BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

                if (bounce_runtime_level_tiles_get(
                        hoop.runtime, (int) x, (int) y, &value
                    ) != 0) {
                    bounce_game_shutdown(&hoop);
                    return -1;
                }
                if (!app_hoop_collect_gate_id((uint32_t) (value & 0x3Fu)))
                    continue;
                /*
                 * Park the ball on this cell so the walk certainly reaches it, and
                 * so the partner cell is inside the same walk window when the two
                 * are adjacent -- which is precisely the condition the double
                 * count needs.
                 */
                hoop.player.TODO_unkX = x * BOUNCE_TILE_SIZE + 6;
                hoop.player.TODO_unkY = y * BOUNCE_TILE_SIZE + 6;
                before = hoop.hoops_scored;
                if (app_timer_callback_dispatch(&hoop, &branch) != 0) {
                    bounce_game_shutdown(&hoop);
                    return -1;
                }
                if (hoop.hoops_scored - before > worst)
                    worst = (long) (hoop.hoops_scored - before);
                if (hoop.hoops_scored > total_hoops)
                    over_total = 1;
            }
        }
        if (worst > worst_delta)
            worst_delta = worst;
        if (worst > 1)
            ++levels_with_double;
        if (worst > 1 || over_total)
            bad = 1;
        printf("HOOP-COUNT level=%2d hoops_total=%ld worst_single_tick_delta=%ld"
               " delta_at_most_one=%s never_exceeds_total=%s %s\n",
               level_id,
               (long) total_hoops,
               worst,
               worst <= 1 ? "yes" : "no",
               over_total ? "no" : "yes",
               (worst <= 1 && !over_total) ? "PASS" : "FAIL");
        bounce_game_shutdown(&hoop);
    }
    printf("HOOP-COUNT summary levels=11 worst_delta=%ld levels_double_counted=%d"
           " expected=1 0 %s\n",
           worst_delta,
           levels_with_double,
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * THE DOOR MUST NOT OPEN BEFORE THE LAST HOOP.
 *
 * WHY THIS EXISTS ALONGSIDE THE OTHER DOOR-GATE FIXTURE. The fixture in
 * verify_collision_query() proves the POSITIVE chain: collect every hoop, watch the
 * animation run, watch the one-shot clear consume it. It establishes that the gate
 * works when it should fire. It says nothing at all about what happens when the
 * gate should NOT fire, which is precisely the reported symptom: the exit usable
 * before the hoops are in. A gate can satisfy the positive chain and still be
 * reachable without its unlock precondition -- for instance if the flag were
 * cleared too late, set somewhere else, or if a second producer existed. Only the
 * negative direction catches that.
 *
 * THE INVARIANT, STATED OVER EVERY TICK RATHER THAN AT ONE INSTANT. The two pieces
 * of state that make the exit usable are door_image_offset (the animation position)
 * and door_open_flag (Java's M, which is also what f.java:601 tests before it sets
 * `e`). Both are produced by exactly one block -- the e.java:286-297 gate -- and that
 * block is reachable only when TODO_ExitUnlocked is true, whose only producer is
 * the collection site in app_collect_hoop() and fires only on
 * `hoops_scored == hoops_total`. So on EVERY tick:
 *
 *     hoops_scored < hoops_total  =>  door_image_offset == 0 && !door_open_flag
 *     and, because the ball is parked ON the exit for the whole run:
 *                                 =>  !level_complete
 *
 * The third clause is the functional half and the reason the ball is moved rather
 * than left to fall: it asserts the exit cannot be PASSED, not merely that it does
 * not animate. A door that rendered shut but let the ball through would satisfy the
 * first clause and still be broken.
 *
 * THE BALL IS PLACED ON THE EXIT, AND THE CAMERA OPERAND IS SATISFIED FOR IT. Both
 * are preconditions of the gate, so leaving either unmet would make the assertion
 * vacuous -- the gate would be unreachable for reasons that have nothing to do with
 * the unlock. The existing fixture documents the same requirement for the same
 * reason. The ball is moved rather than the camera written, because
 * app_update_camera_*() recomputes l, k and v from the ball every tick and would
 * overwrite a direct write on the next frame.
 *
 * THE NEGATIVE CONTROL, AND WHY IT IS NOT OPTIONAL. Having proved the door stays
 * shut for the whole run, the second phase collects every hoop through the REAL
 * producer -- app_collect_hoop(), which is where `HoopsScored == HoopsTotal ->
 * TODO_ExitUnlocked = true` actually lives -- and then requires the gate to reach
 * the open state and the ball to complete the level. Without this phase a gate that
 * was simply dead code, permanently false, would satisfy every implication above
 * and pass. This is what makes the first phase a real assertion.
 *
 * STATE IS NOT LEAKED BETWEEN THE PHASES. The second phase rebuilds the whole app
 * from scratch rather than continuing the first, because the first phase's ball has
 * fallen, its counters have moved and its camera has followed it; a shared app
 * would make the second phase depend on where the first one happened to stop.
 */
static int verify_door_waits_for_hoops(void)
{
    /*
     * ALL ELEVEN LEVELS, NOT JUST ONE. Level 1 is the odd one out in this tree:
     * it is the only shipped level with no dynamic thorns (thorn_count 0, where
     * levels 2-11 carry 4..12), it is the shortest, and it was the only level the
     * first version of this check ran on. A gate defect that only shows up where
     * thorn updates, longer scrolls or denser hoop fields exist would be invisible
     * to a single-level check, so every level is driven through the same two
     * phases and the failure is reported per level.
     */
    int level_id;
    int bad = 0;
    int early_levels = 0;
    int dead_levels = 0;

    printf("DOOR-HOOPS levels=1-11 phase1=hoops_incomplete_ball_on_exit"
           " phase2=hoops_complete\n");
    for (level_id = BOUNCE_APP_FIRST_LEVEL_ID;
         level_id <= BOUNCE_APP_LAST_LEVEL_ID;
         ++level_id) {
        BounceApp door;
        int32_t total_hoops;
        int32_t exit_col;
        int32_t exit_row;
        int tick;
        bool stayed_shut = true;
        bool stayed_passable_shut = true;
        bool opened_after_collection = false;
        bool completed_after_open = false;
        bool skip = false;

        memset(&door, 0, sizeof door);
        if (bounce_game_init(&door) != 0
            || bounce_game_enter_menu(&door) != 0
            || drive_app_to_level_loaded(
                   &door,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&door) != 0
            || app_advance_player_initialized_to_runtime_initialized(&door) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&door) != 0
            || app_advance_camera_initialized_to_activated(&door) != 0
            || bounce_game_initialize_game_timer(&door) != 0) {
            bounce_game_shutdown(&door);
            return -1;
        }
        total_hoops = bounce_level_hoops_total(door.level);
        exit_col = (int32_t)bounce_level_exit_x(door.level);
        exit_row = (int32_t)bounce_level_exit_y(door.level);
        /*
         * exit_col == 0 is NOT rejected: level 11 legitimately places its door at
         * column 0, and the gate's camera operand
         * `(exitX + 1) * 12 > m() && exitX * 12 < g()` is satisfied there because
         * the camera's left edge is itself 0. Rejecting it would have silently
         * skipped the one level with the largest hoop count and a big ball.
         */
        if (total_hoops <= 0
            || exit_col < 0
            || exit_col >= (int32_t)bounce_runtime_level_tiles_width(door.runtime)
            || exit_row < 0
            || exit_row + 1 >= (int32_t)bounce_runtime_level_tiles_height(
                door.runtime)) {
            bounce_game_shutdown(&door);
            return -1;
        }

        /* PHASE ONE -- hoops_scored 0, ball parked on the exit door cell. */
        door.hoops_scored = 0;
        door.player.TODO_unkX = exit_col * BOUNCE_TILE_SIZE + 6;
        door.player.TODO_unkY = exit_row * BOUNCE_TILE_SIZE + 6;
        for (tick = 0; tick < 120; ++tick) {
            BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

            if (app_timer_callback_dispatch(&door, &branch) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
            if (door.TODO_ExitUnlocked
                || door.door_image_offset != 0
                || door.door_open_flag) {
                stayed_shut = false;
                break;
            }
            if (door.level_complete
                || door.state != BOUNCE_GAME_STATE_PLAYING) {
                stayed_passable_shut = false;
                break;
            }
        }
        bounce_game_shutdown(&door);

        /* PHASE TWO -- negative control, on a FRESH app for this level. */
        memset(&door, 0, sizeof door);
        if (bounce_game_init(&door) != 0
            || bounce_game_enter_menu(&door) != 0
            || drive_app_to_level_loaded(
                   &door,
                   door_list_index(level_id),
                   level_id
               ) != 0
            || app_advance_level_loaded_to_player_initialized(&door) != 0
            || app_advance_player_initialized_to_runtime_initialized(&door) != 0
            || app_advance_runtime_initialized_to_camera_initialized(&door) != 0
            || app_advance_camera_initialized_to_activated(&door) != 0
            || bounce_game_initialize_game_timer(&door) != 0) {
            bounce_game_shutdown(&door);
            return -1;
        }
        door.hoops_scored = 0;
        while (door.hoops_scored < total_hoops) {
            if (app_collect_hoop(&door, 1, 1, 13u, 0u) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
        }
        if (!door.TODO_ExitUnlocked) {
            bounce_game_shutdown(&door);
            return -1;
        }
        for (tick = 0; tick < 40; ++tick) {
            BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

            door.player.TODO_unkX = exit_col * BOUNCE_TILE_SIZE + 6;
            door.player.TODO_unkY = exit_row * BOUNCE_TILE_SIZE + 6;
            if (app_timer_callback_dispatch(&door, &branch) != 0) {
                bounce_game_shutdown(&door);
                return -1;
            }
            if (door.door_open_flag)
                opened_after_collection = true;
            if (door.level_complete) {
                completed_after_open = true;
                break;
            }
        }
        bounce_game_shutdown(&door);

        if (!stayed_shut || !stayed_passable_shut)
            ++early_levels;
        if (!opened_after_collection)
            ++dead_levels;
        /*
         * control_completes is REPORTED BUT NOT ASSERTED, and the reason is a
         * property of this fixture rather than of the door.
         *
         * Completing the level needs the tile walk to REACH the door cell, and
         * that walk aborts at the first blocking cell -- f.java:159-162, which
         * verify_static_wall_response and the Step 12X-P4-C-D-C-B4-B probe both
         * establish. Parking the ball on the door cell puts it inside the level's
         * own geometry, and a big ball's box is 16 px against a small ball's 12, so
         * on the three big-ball levels (3, 5 and 11) the walk meets a wall before
         * it reaches the door and returns first. That is the fixture standing the
         * ball somewhere it would never be, not the door failing: the same phase
         * reports control_opens=yes on every level, which is the e.java:286-297
         * contract this function is actually about.
         *
         * Completion through the door is a separate contract and it is already
         * asserted where the approach is real: verify_w1_completion_request_latch()
         * drives the af completion key, and verify_collision_query()'s DOOR-GATE
         * fixture asserts the open/consume/one-shot sequence. Duplicating it here
         * with a ball wedged in a wall would add a brittle assertion, not coverage.
         */
        if (!stayed_shut || !stayed_passable_shut || !opened_after_collection)
            bad = 1;
        skip = false;

        printf("DOOR-HOOPS level=%2d hoops=%2ld exit=(%ld,%ld)"
               " stayed_shut=%s never_completed=%s"
               " control_opens=%s control_completes=%s %s\n",
               level_id,
               (long) total_hoops,
               (long) exit_col,
               (long) exit_row,
               stayed_shut ? "yes" : "no",
               stayed_passable_shut ? "yes" : "no",
               opened_after_collection ? "yes" : "no",
               completed_after_open ? "yes" : "no",
               skip
                   ? "SKIP"
                   : ((stayed_shut && stayed_passable_shut
                       && opened_after_collection)
                          ? "PASS"
                          : "FAIL"));
    }
    printf("DOOR-HOOPS summary levels=11 early_open=%d dead_gate=%d"
           " assert=early_open+gate_reaches_open"
           " expected=0 0 %s\n",
           early_levels,
           dead_levels,
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * THE ACHIEVED TICK CADENCE, MEASURED OVER REAL FRAME PERIODS.
 *
 * WHAT THIS EXISTS TO CATCH. Everything else in this file bounds the deadline; none
 * of it pins the RATE. The two shapes below both satisfy every existing bound:
 *
 *   next = now + PERIOD        a fresh, exact 40 ms gap after every tick
 *   next = prev_deadline + P   exactly 40 ms of wall clock per tick, forever
 *
 * They differ only in whether the frame-time lateness is fed back into the
 * deadline. Because `now` is sampled once per rendered frame, the first shape adds
 * 0..16 ms of lateness to every single tick and never recovers it, so the error is
 * cumulative rather than bounded. Simulated over 60 s of 16 ms frames it yields
 * 1250 ticks -- a 48.00 ms average period and 20.8 Hz -- against the 40 ms /
 * ~25 Hz that BounceTimer.java:17 schedules with `schedule(this, 0L, 40L)`.
 *
 * WHY A 17% SHORTFALL IS A GAMEPLAY DEFECT AND NOT PACING. Every physics constant
 * in the recovered source is expressed PER TICK, not per second: JUMP_STRENGTH -67,
 * NORMAL_GRAVITY_ACCELL 4, MAX_TOTAL_SPEED 150, MAX_HORZ_SPEED 50 (f.java). Those
 * numbers are only meaningful at the tick rate they were authored for. Running
 * them at 20.8 Hz instead of 25 Hz scales gravity, jump height, run speed and every
 * bonus timer by 0.83, and it does so silently and uniformly, so nothing looks
 * broken -- the game just feels wrong and is not the game.
 *
 * WHY THIS NEEDS REAL FRAME PERIODS. The 64-iteration loop in
 * verify_production_game_routing() runs with no sleep, so `now` moves by
 * microseconds and nearly every iteration correctly skips its tick. A rate measured
 * there describes the loop. This routine therefore reproduces the production frame
 * loop's own shape -- one dispatch per iteration, then one frame period of sleep --
 * which is the only condition under which the deadline arithmetic is exercised the
 * way it is at run time.
 *
 * THE ACCEPTANCE BAND, AND WHY IT IS ASYMMETRIC. The source rate is 25 Hz. The band
 * has to survive a loaded, preempted or virtualised host, where a frame can
 * overrun; a stall makes the measured rate LOWER, never higher, because the
 * fixed-delay resync discards missed ticks instead of replaying them. So:
 *
 *   upper 32 Hz  The drifting shape cannot reach this: it is strictly slower than
 *                nominal, never faster, because lateness is only ever added. The
 *                upper bound is therefore slack that costs no sensitivity at all.
 *   lower 21 Hz  The drifting shape sits at 20.8 Hz, just outside it, and the
 *                exact shape sits at 25.0 Hz, comfortably inside. The 4% margin
 *                between them is what makes this a real discriminator; the 20%
 *                headroom below nominal is what makes it survivable on a slow host.
 *
 * The structural invariant is asserted alongside the rate, because the rate alone
 * cannot tell a correct 25 Hz from an accidental one: the per-tick deadline advance
 * must never exceed one period on a tick that was not served after a stall. That
 * is the property the rate is a consequence of, and it is exact where the rate is
 * statistical.
 */
static int verify_tick_cadence(void)
{
    BounceApp app;
    /* One production frame is 16 ms; 80 of them is ~1.28 s and ~32 ticks. */
    enum { CADENCE_FRAMES = 80 };
    const int64_t band_low_mHz = 21000;
    const int64_t band_high_mHz = 32000;
    struct timespec nap;
    uint64_t ticks_before;
    uint64_t ticks_after;
    int64_t started_ms;
    int64_t elapsed_ms;
    int64_t measured_mHz;
    unsigned int frames_run;
    unsigned int served = 0u;
    bool advance_ok = true;
    bool rate_ok;

    memset(&app, 0, sizeof app);
    if (drive_app_to_gameplay_entry_start_level(&app) != 0)
        return -1;
    /*
     * The first production frame is what consumes START_LEVEL, loads the level,
     * starts the timer and runs tick #1 (verified in verify_production_game_routing
     * steps A+B+C). Everything measured below therefore counts ticks 2..N, which is
     * why the baseline is taken here and not one call earlier.
     */
    if (app_update_production_game(&app) != 0
        || !app_canonical_gameplay_active(&app)) {
        bounce_game_release_level(&app);
        return -1;
    }
    ticks_before = bounce_game_timer_tick_dispatch_count(&app.game_timer);
    started_ms = monotonic_milliseconds();
    if (started_ms < 0) {
        bounce_game_release_level(&app);
        return -1;
    }
    for (frames_run = 0u; frames_run < (unsigned int) CADENCE_FRAMES;
         ++frames_run) {
        int64_t before;
        int64_t deadline_pre;
        uint64_t dispatch_before;
        uint64_t dispatch_after;

        before = monotonic_milliseconds();
        deadline_pre = app.canonical_next_tick_ms;
        dispatch_before = bounce_game_timer_tick_dispatch_count(&app.game_timer);
        if (app_update_production_game(&app) != 0) {
            bounce_game_release_level(&app);
            return -1;
        }
        dispatch_after = bounce_game_timer_tick_dispatch_count(&app.game_timer);
        if (dispatch_after < dispatch_before
            || dispatch_after - dispatch_before > 1u) {
            bounce_game_release_level(&app);
            return -1;
        }
        if (dispatch_after != dispatch_before) {
            int64_t advance;

            ++served;
            /*
             * The exact shape advances the deadline by exactly one period. The
             * drifting shape advances it by one period PLUS this frame's lateness,
             * so it exceeds the period whenever the frame was even slightly late --
             * which, over 80 real frames, is nearly always. Ticks that arrived after
             * a stall of a full period or more are exempt, because there the
             * fixed-delay resync deliberately places the deadline a period from
             * `now`; see app_run_canonical_gameplay_tick().
             */
            if (deadline_pre > 0
                && before >= deadline_pre
                && (before - deadline_pre)
                    < (int64_t) BOUNCE_GAME_TIMER_PERIOD_MS) {
                advance = app.canonical_next_tick_ms - deadline_pre;
                if (advance <= 0
                    || advance > (int64_t) BOUNCE_GAME_TIMER_PERIOD_MS) {
                    advance_ok = false;
                }
            }
        }
        /* The production frame period. sleep_frame() is the frame loop's own. */
        nap.tv_sec = 0;
        nap.tv_nsec = 16L * 1000L * 1000L;
        (void) nanosleep(&nap, NULL);
    }
    ticks_after = bounce_game_timer_tick_dispatch_count(&app.game_timer);
    elapsed_ms = monotonic_milliseconds() - started_ms;
    app_end_canonical_gameplay(&app);
    bounce_game_release_level(&app);

    if (elapsed_ms <= 0 || ticks_after <= ticks_before || served == 0u)
        return -1;
    /* Rate in millihertz, so the whole computation stays in integer arithmetic. */
    measured_mHz = (int64_t) (ticks_after - ticks_before) * 1000000
        / elapsed_ms;
    rate_ok = measured_mHz >= band_low_mHz && measured_mHz <= band_high_mHz;

    printf("TICK-CADENCE frames=%u served=%u elapsed_ms=%lld rate_mHz=%lld"
           " nominal_mHz=%d band=[%lld,%lld] per_tick_advance=%s rate=%s"
           " expected=yes >=%lld <=%lld %s %s %s\n",
           (unsigned int) CADENCE_FRAMES,
           served,
           (long long) elapsed_ms,
           (long long) measured_mHz,
           1000000 / (int) BOUNCE_GAME_TIMER_PERIOD_MS,
           (long long) band_low_mHz,
           (long long) band_high_mHz,
           advance_ok ? "exact" : "drifting",
           rate_ok ? "in_band" : "out_of_band",
           (long long) band_low_mHz,
           (long long) band_high_mHz,
           advance_ok ? "exact" : "drifting",
           rate_ok ? "yes" : "no",
           advance_ok && rate_ok ? "PASS" : "FAIL");
    return advance_ok && rate_ok ? 0 : -1;
}

/*
 * STEP 65-H -- declared ahead of its documentation block below, which sits next
 * to the input callback that will call it. The verifier below is the only
 * current caller.
 */
static void app_request_w1_completion(BounceApp *app);
/* D-02: the hideNotify edge, defined with the X11 seam helpers. */
static int app_apply_focus_lost(BounceApp *app);
/* D-21: the key decision, defined with app_request_w1_completion below. */
static bool app_w1_completion_key(BounceApp *app, KeySym key);

/*
 * STEP 65-H -- the W1 completion-request latch, verified end to end.
 *
 * This is the project's existing check harness driving the new seam, which is
 * also what keeps app_request_w1_completion() reachable from a test. No physical
 * key is involved: STEP 65-D closed the mapping of Java action 8 to any key as
 * EXTERNAL-MAPPING-NOT-RECOVERED, so the producer is called directly and the
 * whole lifecycle below it is proven.
 *
 * What is asserted, in the order the assertions appear:
 *
 *  1. THE PRODUCER DOES NO WORK. Immediately after app_request_w1_completion()
 *     the request is set and nothing else has moved: the pipeline has not run,
 *     the level has not advanced and the flow is still GAMEPLAY. This is the
 *     half of Java's W1 timing that lives in keyPressed, where e.java:407 is the
 *     only statement executed.
 *
 *  2. THE REQUEST CROSSES THE TICK BOUNDARY. One app_update_production_game()
 *     call that does not reach the 40 ms gate must leave the request armed, the
 *     pipeline untouched and every tick counter unmoved. The frame loop calls
 *     x11_process_events before app_update_production_game, so this is exactly
 *     "armed during frame N, not consumed during frame N".
 *
 *  3. PHYSICS RUNS BEFORE THE CONSUMER. On the first tick that does fire, the
 *     player-physics counter must have advanced -- that is the body at game.c:1001
 *     -- AND the completion pipeline must have run. e.java:313 is the last
 *     statement block of Tick(), after e.java:262-308, so the native consumer on
 *     the PLAYER_TICK fallthrough is the only position that can produce both.
 *
 *  4. THE CANONICAL PIPELINE RAN, ONCE. level_complete, both LEVEL_COMPLETE
 *     states, deferred_init, the cleared exit flag, ++level_id and the +5000 are
 *     all the pipeline's own effects (game.c:1265-1356); nothing in the W1 arm
 *     reproduces them.
 *
 *  5. PERSISTENCE RAN. app_persist_records raised the high score by the +5000
 *     the pipeline had just awarded, which is observable through
 *     bounce_app_flow_high_score. That is the same call the exit-door route makes.
 *
 *  6. ONE-SHOT. The request is cleared after consumption, and a further tick
 *     must not advance the level a second time. e.java:314 clears `e` before its
 *     effects; the native clear is after them, and this asserts the outcome the
 *     two placements share.
 */
static int verify_w1_completion_request_latch(void)
{
    BounceApp app;
    uint64_t physics_before;
    uint64_t physics_after;
    uint64_t dispatch_before;
    uint64_t dispatch_after;
    int32_t score_before;
    int level_before;
    unsigned int i;
    int bad = 0;
    bool crosses_ok;
    bool physics_ok;
    bool pipeline_ok;
    bool persistence_ok;
    bool one_shot_ok;

    memset(&app, 0, sizeof app);
    if (drive_app_to_gameplay_entry_start_level(&app) != 0)
        return -1;
    if (app_update_production_game(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || !app_canonical_gameplay_active(&app)) {
        bounce_game_release_level(&app);
        return -1;
    }
    level_before = app.flow.level_id;
    score_before = app.score;

    /*
     * D-21 -- THE KEY DECISION, WHICH IS THE PART THAT WAS MISSING.
     *
     * Everything below tests the LIFECYCLE, which has been verified since the
     * seam shipped: the producer is one assignment, the latch survives a frame
     * that misses the 40 ms gate, and the first tick that fires runs physics and
     * then the consumer. What was never tested was the DECISION -- which keys arm
     * it, and whether `af` gates it -- because that lived in x11_process_events,
     * which the check harness cannot drive.
     *
     * The decision is now app_w1_completion_key(), and it is checked on both
     * sides: with af FALSE the bound key must do nothing, which is e.java:406's
     * gate and the reason the cheat is inert in a normal game; and with af TRUE
     * the bound key must arm the latch, while every other key must not.
     */
    if (app_w1_completion_key(&app, XK_c)
        || app.af
        || app.completion_requested) {
        bad++;
    }
    app.af = true;
    if (!app_w1_completion_key(&app, XK_c)
        /* Every other keysym must be inert, including the ones that ARE game
         * inputs: the source's case 8 is a distinct action, and borrowing a
         * direction key would make a held direction complete the level. */
        || app_w1_completion_key(&app, XK_Right)
        || app_w1_completion_key(&app, XK_Left)
        || app_w1_completion_key(&app, XK_a)
        || app_w1_completion_key(&app, XK_Up)
        || app_w1_completion_key(&app, XK_space)
        || app_w1_completion_key(&app, XK_3)
        || app_w1_completion_key(NULL, XK_c)) {
        bad++;
    }
    app.af = false;
    level_before = app.flow.level_id;

    /* 1. The producer is exactly one assignment and nothing else. */
    app_request_w1_completion(&app);
    if (!app.completion_requested
        || app.level_complete
        || app.deferred_init
        || app.flow.level_id != level_before
        || app.score != score_before
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || app.state != BOUNCE_GAME_STATE_PLAYING) {
        bad++;
    }

    /* 2. A frame that misses the 40 ms gate consumes nothing. */
    dispatch_before = bounce_game_timer_tick_dispatch_count(&app.game_timer);
    physics_before = bounce_game_timer_player_physics_count(&app.game_timer);
    if (app_update_production_game(&app) != 0) {
        bounce_game_release_level(&app);
        return -1;
    }
    dispatch_after = bounce_game_timer_tick_dispatch_count(&app.game_timer);
    if (dispatch_after - dispatch_before > 1u
        || (dispatch_after == dispatch_before
            && (!app.completion_requested || app.level_complete))) {
        bad++;
    }

    /* 3. The first tick that fires runs physics and then the consumer. */
    for (i = 0u; i < 64u && !app.level_complete; ++i) {
        struct timespec nap;
        int64_t before = monotonic_milliseconds();
        if (app_update_production_game(&app) != 0)
            goto failure;
        if (app.level_complete)
            break;
        /*
         * The tick is gated on app->canonical_next_tick_ms, which is a wall-clock
         * deadline (vertical_slice.c:6810). A tight loop therefore spins without
         * ticking, so the wait is real: sleep_frame() is the frame loop's own
         * frame period and is longer than the 40 ms tick, so one frame per
         * iteration is enough for exactly the ticks the deadline allows.
         */
        if (monotonic_milliseconds() - before > (int64_t)BOUNCE_GAME_TIMER_PERIOD_MS)
            break;
        nap.tv_sec = 0;
        nap.tv_nsec = 50000000L; /* 50 ms > BOUNCE_GAME_TIMER_PERIOD_MS */
        (void)nanosleep(&nap, NULL);
    }
    physics_after = bounce_game_timer_player_physics_count(&app.game_timer);
    if (physics_after <= physics_before) {
        /* The consumer cannot have run: it sits behind the physics body. */
        bad++;
    }

    /* 4. The existing pipeline performed all of its own effects. */
    pipeline_ok = app.level_complete
        && app.flow.state == BOUNCE_APP_STATE_LEVEL_COMPLETE
        && app.state == BOUNCE_GAME_STATE_LEVEL_COMPLETE
        && app.deferred_init
        && !app.TODO_ExitUnlocked
        && app.flow.level_id == level_before + 1
        && app.score == score_before + 5000;
    if (!pipeline_ok) {
        bad++;
    }

    /* 5. Persistence ran, through W2's call. */
    persistence_ok = bounce_app_flow_high_score(&app.flow) == app.score;
    if (!persistence_ok) {
        bad++;
    }

    physics_ok = physics_after > physics_before;
    crosses_ok = dispatch_after == dispatch_before;

    /*
     * 6. One-shot: the request is cleared by its consumer, and four further ticks
     * must not advance the level a second time. e.java:314 clears `e` before its
     * effects; the native clear is after them, and this asserts the outcome the
     * two placements share.
     */
    if (app.completion_requested) {
        bad++;
    }
    level_before = app.flow.level_id;
    for (i = 0u; i < 4u; ++i) {
        struct timespec nap;
        if (app_update_production_game(&app) != 0)
            goto failure;
        nap.tv_sec = 0;
        nap.tv_nsec = 50000000L;
        (void)nanosleep(&nap, NULL);
    }
    one_shot_ok = app.flow.level_id == level_before
        && app.level_complete
        && !app.completion_requested;
    if (!one_shot_ok) {
        bad++;
    }

    printf("W1-LATCH producer_no_work=yes crosses_tick=%s physics_before_completion=%s "
           "pipeline=%s persistence=%s one_shot=%s expected="
           "yes yes yes yes yes %s\n",
        crosses_ok ? "yes" : "no",
        physics_ok ? "yes" : "no",
        pipeline_ok ? "yes" : "no",
        persistence_ok ? "yes" : "no",
        one_shot_ok ? "yes" : "no",
        bad == 0 ? "PASS" : "FAIL");
    bounce_game_release_level(&app);
    return bad == 0 ? 0 : -1;

failure:
    bounce_game_release_level(&app);
    return -1;
}

/*
 * STEP G-R3-T2 -- the resume-snapshot capture.
 *
 * WHAT IS AND IS NOT UNDER TEST HERE. The capture is pure state assembly: it
 * reads the live session and fills a BouncePersistenceRecord3. It touches no
 * file, so it is exercised here on a private BounceApp with no X server, no
 * store and no display, and that is what keeps the real store untouched --
 * for the same reason bounce_persistence_verify() needs a temporary directory.
 *
 * The WRITE half is deliberately not called from here. It is the one production
 * Record 3 writer, it writes the player's real store, and a self-test must never
 * do that. Its contract is covered by bounce_persistence_verify(), which uses a
 * temporary directory, and by the live menu-Exit run.
 *
 * The live values are overwritten with distinctive ones first. Level 1's real
 * player starts at TODO_unkX == 30, which is divisible by BOUNCE_TILE_SIZE, so a
 * capture that read zero, or that confused the tile coordinate with the pixel
 * coordinate, would otherwise be able to pass.
 */
static int verify_resume_snapshot_capture(void)
{
    BounceApp app;
    BouncePersistenceRecord3 first;
    BouncePersistenceRecord3 second;
    const BounceDynThorns *thorns;
    uint32_t expected_deltas = 0u;
    uint32_t row;
    unsigned int index;
    int bad = 0;
    bool b1_ok;
    bool scalars_ok;
    bool spawn_ok;
    bool not_live_ok;
    bool deferred_ok;
    bool complete_ok;
    bool deterministic_ok;
    bool invariant_ok;
    bool deltas_ok;
    bool thorns_ok;
    bool survives_ok;
    bool preserved_ok = false;
    bool inert_ok;
    uint32_t thorn_level_count = 0u;
    uint32_t thorn_count_expected = 0u;

    memset(&app, 0, sizeof app);
    if (drive_app_to_gameplay_entry_start_level(&app) != 0)
        return -1;
    if (app_update_production_game(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || app.level == NULL
        || app.runtime == NULL
        || !app.player.initialized) {
        bounce_game_release_level(&app);
        return -1;
    }

    /* Distinctive, and deliberately not multiples of BOUNCE_TILE_SIZE. */
    app.lives = 3;
    app.hoops_scored = 2;
    app.score = 4242;
    app.l = 51;
    app.k = 7;
    app.player.TODO_unkX = 155;
    app.player.TODO_unkY = 242;
    app.player.horizontal_velocity = 48;
    app.player.o = -33;
    app.player.TODO_somePowerUp1 = 5;
    app.player.powerUpGravity = 9;
    app.player.TODO_somePowerUp3 = 4;

    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAMEPLAY);
    first = app.resume_record3;

    /* 1. b1 is K, and K == 1 for a session that was mid-level. */
    b1_ok = first.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    /* 2. Every live scalar is copied, not defaulted. */
    scalars_ok = first.lives == 3u
        && first.hoops_scored == 2u
        && first.score == 4242
        && first.l == 51
        && first.k == 7
        && first.unk_x == 155
        && first.unk_y == 242
        && first.aq_l == 48
        && first.aq_o == -33
        && first.power_up_1 == 5
        && first.power_up_gravity == 9
        && first.power_up_3 == 4
        && first.level == (uint8_t) app.flow.level_id
        && first.ball_size == (uint8_t) app.player.ballSize
        && first.zero_slot_0 == 0
        && first.zero_slot_1 == 0;
    /*
     * 3. aq.d / aq.c are the SPAWN/RESPAWN TILE, not the live cell.
     * BounceGame.java:375-376 writes f.d / f.c, which f.java:134-138 writes only
     * from f.a(tileX, tileY) -- called only at e.java:107 and e.java:122 -- and
     * which are read only by the crystal collector (f.java:482) and the death
     * reconstruction (e.java:274-280). The player above was deliberately moved to
     * (155, 242), which is live cell (12, 20), while level 1's spawn is (2, 1), so
     * these two quantities are genuinely different here and this check can tell
     * them apart rather than passing by coincidence.
     */
    spawn_ok = first.tile_x == app.spawn.tile_x
        && first.tile_y == app.spawn.tile_y;
    not_live_ok = first.tile_x != 155 / BOUNCE_TILE_SIZE
        || first.tile_y != 242 / BOUNCE_TILE_SIZE;
    /*
     * 4. The timestamp is NOT stamped by the capture. Java takes it inside
     * WriteToStore(3) (:360), so it belongs to the write; a capture-time stamp
     * would report the wrong instant.
     */
    deferred_ok = first.timestamp_millis == 0;
    /* 5. b1 == 2 only for the level-complete screen, K == 5 (:202). */
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_LEVEL_COMPLETE);
    complete_ok = app.resume_record3.b1
        == BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE;
    /* 6. The capture is deterministic: same state, same record. */
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAMEPLAY);
    second = app.resume_record3;
    deterministic_ok = memcmp(&first, &second, sizeof first) == 0;
    /*
     * 6b. THE DISTINCTION THIS CORRECTION IS ABOUT. Move the live player onto a
     * different cell and capture again: aq.d / aq.c must NOT follow it, because
     * they are the spawn tile and Java never updates them during play. This is the
     * case the previous TODO_unkX / BOUNCE_TILE_SIZE derivation got wrong. The
     * player is then put back and the state recaptured, because the checks below
     * compare app.resume_record3 against `first`.
     */
    app.player.TODO_unkX = 700;
    app.player.TODO_unkY = 310;
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAMEPLAY);
    invariant_ok = app.resume_record3.tile_x == first.tile_x
        && app.resume_record3.tile_y == first.tile_y
        && app.resume_record3.tile_x
            != app.player.TODO_unkX / BOUNCE_TILE_SIZE;
    app.player.TODO_unkX = 155;
    app.player.TODO_unkY = 242;
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAMEPLAY);
    /* 7. Tile deltas: recomputed independently, in Java's row-major order. */
    for (row = 0u; row < bounce_runtime_level_tiles_height(app.runtime); ++row) {
        uint32_t col;

        for (col = 0u; col < bounce_runtime_level_tiles_width(app.runtime);
             ++col) {
            uint16_t value = 0u;
            int32_t normalized;

            if (bounce_runtime_level_tiles_get(
                    app.runtime, (int) col, (int) row, &value) != 0)
                continue;
            normalized = bounce_level_tile_value_persistence_without_water(value);
            if (!app_resume_tile_id_is_saved(normalized))
                continue;
            if (expected_deltas >= BOUNCE_PERSISTENCE_RECORD3_MAX_TILE_DELTAS)
                continue;
            if (first.tile_delta_count <= expected_deltas
                || first.tile_deltas[expected_deltas].row != (int16_t) row
                || first.tile_deltas[expected_deltas].col != (int16_t) col
                || first.tile_deltas[expected_deltas].tile_id
                    != (uint8_t) normalized)
                bad++;
            ++expected_deltas;
        }
    }
    deltas_ok = first.tile_delta_count == expected_deltas
        && expected_deltas != 0u;
    /* 8. Dynamic thorns: the live owned w/ae, not the immutable payload. */
    thorns = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
    thorns_ok = thorns != NULL
        && first.dyn_thorn_count == thorns->count;
    /*
     * The count is copied out now because `thorns` borrows the runtime object,
     * and check 9 below releases the level. Reading it after that would be a
     * use-after-free.
     */
    thorn_count_expected = thorns != NULL ? thorns->count : 0u;
    for (index = 0u; thorns_ok && index < first.dyn_thorn_count; ++index) {
        if (first.dyn_thorns[index].w_x != thorns->records[index].w.x
            || first.dyn_thorns[index].w_y != thorns->records[index].w.y
            || first.dyn_thorns[index].ae_x != thorns->records[index].ae.x
            || first.dyn_thorns[index].ae_y != thorns->records[index].ae.y)
            thorns_ok = false;
    }
    /*
     * 9. THE PROPERTY THE WHOLE DESIGN RESTS ON: bounce_game_release_level()
     * must NOT clear the captured record. It runs immediately after every
     * capture, so if it cleared the field the snapshot would be destroyed
     * before it could ever be written.
     */
    bounce_game_release_level(&app);
    survives_ok = memcmp(&first, &app.resume_record3, sizeof first) == 0
        && app.level == NULL
        && app.runtime == NULL;
    /*
     * 10. STEP SAVE-CONTINUE -- A CAPTURE WITH NO LIVE LEVEL MUST PRESERVE THE
     * REMEMBERED SNAPSHOT, NOT CLEAR IT.
     *
     * This check asserted the opposite, and it was the last thing standing in the way
     * of the fix. Its reasoning -- that Java represents "no snapshot" by K rather than
     * by the absence of a record -- is true and does not imply what it concluded. K is
     * STICKY: BounceGame.java:355-361 writes b1 from this.K, and nothing between
     * playing a level and pressing BACK changes it, so a session that is still in the
     * record is still resumable after a trip to the main menu. Treating "no level loaded
     * right now" as "no session" is what made the window close overwrite a good save
     * with an inert one.
     *
     * So the property is that the field survives, byte for byte, and that is asserted
     * against `first` -- the record captured from the live level -- rather than against
     * a hand-written list of zeroes, which would have let a capture that blanked only
     * SOME fields pass.
     */
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_MENU);
    preserved_ok = memcmp(&first, &app.resume_record3, sizeof first) == 0
        && app.resume_record3.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    if (!preserved_ok)
        ++bad;

    /*
     * 10b. AND A FIELD THAT WAS NEVER CAPTURED INTO IS INERT, which is the case the
     * old check was actually reaching for. app is zeroed at boot and nothing has
     * captured into it, so b1 is 0 with no payload -- Java's K == 2 state at
     * BounceGame.java:19, and BounceGame.java:225 resumes only when J != 0. This is a
     * separate app so that "never captured" is a fact about the fixture rather than a
     * consequence of the check above having run.
     */
    {
        BounceApp virgin;

        memset(&virgin, 0, sizeof virgin);
        app_capture_resume_snapshot(&virgin, BOUNCE_APP_STATE_MENU);
        inert_ok = virgin.resume_record3.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE
            && virgin.resume_record3.lives == 0
            && virgin.resume_record3.level == 0u
            && virgin.resume_record3.score == 0
            && virgin.resume_record3.tile_delta_count == 0u
            && virgin.resume_record3.dyn_thorn_count == 0u;
    }

    /*
     * 11. The thorn element check needs a level that actually HAS thorns: level 1
     * has none, so the comparison above is vacuous there. Level 2 carries six,
     * which is also where the earlier live runs read "DYNTHORN level= 2
     * thorns=6". This pass exists only to make check 8 non-vacuous, and it runs
     * on its own app so it cannot disturb the release-survival case above.
     */
    {
        BounceApp thorny;
        const BounceDynThorns *thorny_thorns;

        memset(&thorny, 0, sizeof thorny);
        if (bounce_game_init(&thorny) != 0
            || bounce_game_enter_menu(&thorny) != 0
            || bounce_game_start_level(
                    &thorny,
                    "src/main/resources/levels/J2MElvl.002",
                    2,
                    3
                ) != 0) {
            ++bad;
        } else {
            app_capture_resume_snapshot(&thorny, BOUNCE_APP_STATE_GAMEPLAY);
            thorny_thorns
                = bounce_runtime_level_tiles_dyn_thorns(thorny.runtime);
            if (thorny_thorns == NULL
                || thorny_thorns->count == 0u
                || thorny.resume_record3.dyn_thorn_count
                    != thorny_thorns->count) {
                ++bad;
            } else {
                for (index = 0u;
                     index < thorny.resume_record3.dyn_thorn_count;
                     ++index) {
                    if (thorny.resume_record3.dyn_thorns[index].w_x
                            != thorny_thorns->records[index].w.x
                        || thorny.resume_record3.dyn_thorns[index].w_y
                            != thorny_thorns->records[index].w.y
                        || thorny.resume_record3.dyn_thorns[index].ae_x
                            != thorny_thorns->records[index].ae.x
                        || thorny.resume_record3.dyn_thorns[index].ae_y
                            != thorny_thorns->records[index].ae.y) {
                        ++bad;
                    }
                }
            }
            thorn_level_count = thorny.resume_record3.dyn_thorn_count;
            bounce_game_release_level(&thorny);
        }
    }

    if (!b1_ok)
        ++bad;
    if (!scalars_ok)
        ++bad;
    if (!spawn_ok)
        ++bad;
    if (!not_live_ok)
        ++bad;
    if (!deferred_ok)
        ++bad;
    if (!complete_ok)
        ++bad;
    if (!deterministic_ok)
        ++bad;
    if (!invariant_ok)
        ++bad;
    if (!deltas_ok)
        ++bad;
    if (!thorns_ok)
        ++bad;
    if (!survives_ok)
        ++bad;
    if (!inert_ok)
        ++bad;

    printf("RESUME-CAPTURE b1_in_level=%s scalars=%s spawn_tile=%s "
           "not_live_cell=%s timestamp_deferred=%s b1_level_complete=%s "
           "deterministic=%s move_invariant=%s "
           "deltas=%u/%u thorns=%u/%u survives_release=%s preserved=%s inert_when_virgin=%s "
           "thorn_level2=%u expected=yes yes yes yes yes yes yes yes "
           "15 15 0 0 yes yes yes 6 %s\n",
        b1_ok ? "yes" : "no",
        scalars_ok ? "yes" : "no",
        spawn_ok ? "yes" : "no",
        not_live_ok ? "yes" : "no",
        deferred_ok ? "yes" : "no",
        complete_ok ? "yes" : "no",
        deterministic_ok ? "yes" : "no",
        invariant_ok ? "yes" : "no",
        first.tile_delta_count, expected_deltas,
        first.dyn_thorn_count, thorn_count_expected,
        survives_ok ? "yes" : "no",
        preserved_ok ? "yes" : "no",
        inert_ok ? "yes" : "no",
        thorn_level_count,
        bad == 0 ? "PASS" : "FAIL");

    return bad == 0 ? 0 : -1;
}

/*
 * STEP DV-GUARDS -- GUARD A, GUARD B and GUARD D for the Record 3 contract
 * divergences fixed in this step. See RECORD-3-CONTRACT-AUDIT.md.
 *
 * WHAT IS UNDER TEST, AND WHY IT NEEDS ITS OWN VERIFIER.
 *
 *   GUARD A. A capture taken from BOUNCE_APP_STATE_GAME_OVER must produce
 *     b1 == 0. Java sets K = 3 there (TODO_ShowInstructions, BounceGame.java:431),
 *     which is neither K == 1 nor K == 5, so WriteToStore(3) writes b1 = 0.
 *     Before this step the capture produced b1 == 1, i.e. a resumable snapshot
 *     of a finished run.
 *
 *   GUARD D. The same for BOUNCE_APP_STATE_GAME_END, and for the same reason: a
 *     win is routed through TODO_ShowInstructions(true) at e.java:321, not through
 *     ShowLevelComplete, so K is 3 there too.
 *
 *   GUARD B. End to end through the real encoder and decoder: capture with
 *     app->lives = -1, write it with bounce_persistence_save_record3(), read it
 *     back with bounce_persistence_load_record3(), and require -1. This is the
 *     assertion that actually discriminates the two interpretations -- read as
 *     unsigned the same bytes decode to 255. The raw BYTE (0xFF) is asserted in
 *     persistence.c's V5b block, where the container walker already exists.
 *
 * WHY THE EXISTING VERIFIER COULD NOT SEE ANY OF THIS.
 * verify_resume_snapshot_capture() passes only GAMEPLAY, LEVEL_COMPLETE and MENU
 * to the capture, and every lives fixture in the suite is 0, 2 or 3. All of those
 * are identical under both signednesses, so `make check` stayed green across the
 * whole regression.
 *
 * THE PLAYER'S REAL SAVE IS NEVER TOUCHED. GUARD B is the only guard here that
 * performs I/O, so it runs under the same discipline bounce_persistence_verify()
 * uses: a private mkdtemp root published through XDG_DATA_HOME, with the
 * caller's environment restored before returning. bounce_persistence_load_record3()
 * and bounce_persistence_save_record3() each resolve the path freshly, so the
 * override takes effect.
 */
static int verify_record3_terminal_b1_contract(void)
{
    static const char template[] = "/tmp/bounce-contract-XXXXXX";
    char root[sizeof template];
    /* persistence.h keeps BOUNCE_PERSISTENCE_PATH_MAX private to its own
     * translation unit, so the saved value is copied into a local buffer. */
    char saved[1024];
    int saved_ok;
    BounceApp app;
    BouncePersistenceRecord3 back;
    bool present = false;
    bool game_over_b1_ok;
    bool game_end_b1_ok;
    bool lives_capture_ok;
    bool lives_roundtrip_ok;
    /* D-14: a sub-screen round trip must leave Record 3 untouched. */
    bool sub_screen_no_write_ok = false;
    int bad = 0;

    memset(&app, 0, sizeof app);
    if (drive_app_to_gameplay_entry_start_level(&app) != 0)
        return -1;
    if (app_update_production_game(&app) != 0
        || app.flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || app.level == NULL
        || app.runtime == NULL
        || !app.player.initialized) {
        bounce_game_release_level(&app);
        return -1;
    }

    /*
     * The live values a game-over snapshot carries. Distinctive on purpose, so a
     * restore reading the wrong source cannot pass by accident.
     */
    app.lives = -1;
    app.hoops_scored = 4;
    app.score = 31337;
    app.level_id = 3;

    /* GUARD A -- GAME_OVER must yield the inert record. */
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAME_OVER);
    game_over_b1_ok
        = app.resume_record3.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
    lives_capture_ok = (app.resume_record3.lives == -1);

    /* GUARD D -- GAME_END must yield the inert record as well. */
    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAME_END);
    game_end_b1_ok = app.resume_record3.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE;

    /* GUARD B -- the capture's -1 must survive the real encoder and decoder. */
    memcpy(root, template, sizeof template);
    if (mkdtemp(root) == NULL) {
        bounce_game_release_level(&app);
        return -1;
    }
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void) snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0) {
        bounce_game_release_level(&app);
        return -1;
    }

    app_capture_resume_snapshot(&app, BOUNCE_APP_STATE_GAME_OVER);
    lives_roundtrip_ok = false;
    if (bounce_persistence_save_record3(&app.resume_record3) == 0
        && bounce_persistence_load_record3(&back, &present) == 0
        && present)
        lives_roundtrip_ok = (back.lives == -1)
            && (back.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE);

    /*
     * D-14 -- COMING BACK FROM A SUB-SCREEN MUST NOT WRITE RECORD 3.
     *
     * This is the other half of the conflict recorded above, and it is asserted
     * rather than left to the comment, because it is a behaviour that a later
     * reader would otherwise have every reason to "fix".
     *
     * Java's reason is exact. BounceGame.java:249-256 sends the Back/Exit/OK
     * command to destroyApp -- the only Record 3 writer, Bounce.java:25 -- only
     * when `display.getCurrent() == this.c`, and this.c is the MAIN MENU. The
     * level List, the High Score form and the Instructions form are all different
     * Displayables, so Back from any of them takes ShowMainMenu() instead, which
     * writes nothing.
     *
     * So the store is primed with a known Record 3, each sub-screen is entered
     * and left with Back, and the store must be byte-identical afterwards. This
     * is the negative of the Exit route, which does write, so the pair shows there
     * is exactly one writer rather than none.
     */
    {
        static const BounceUiInput round_trips[] = {
            BOUNCE_UI_INPUT_DOWN, BOUNCE_UI_INPUT_SELECT, BOUNCE_UI_INPUT_BACK
        };
        BouncePersistenceRecord3 prime;
        BounceApp nav;
        size_t step;
        int pass;

        memset(&prime, 0, sizeof prime);
        prime.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
        prime.level = 4u;
        prime.score = 24680;
        prime.lives = 2;
        prime.ball_size = 12u;
        prime.unk_x = 96;
        prime.unk_y = 24;
        prime.tile_x = 8;
        prime.tile_y = 2;
        if (bounce_persistence_save_record3(&prime) != 0) {
            bounce_game_release_level(&app);
            if (saved_ok)
                (void) setenv("XDG_DATA_HOME", saved, 1);
            else
                (void) unsetenv("XDG_DATA_HOME");
            return -1;
        }

        for (pass = 0; pass < 2; ++pass) {
            /* pass 0 opens High Score, pass 1 opens Instructions: one DOWN from
             * the top reaches each in turn, because with Continue unavailable
             * position 1 is row 2 and position 2 is row 3. */
            memset(&nav, 0, sizeof nav);
            if (bounce_game_init(&nav) != 0
                || bounce_game_enter_menu(&nav) != 0) {
                bounce_game_shutdown(&nav);
                bounce_game_release_level(&app);
                if (saved_ok)
                    (void) setenv("XDG_DATA_HOME", saved, 1);
                else
                    (void) unsetenv("XDG_DATA_HOME");
                return -1;
            }
            for (step = 0u; step < sizeof round_trips / sizeof round_trips[0];
                 ++step) {
                if (step == 0u && pass == 1) {
                    /* Instructions sits one row further down. */
                    if (bounce_app_flow_menu_move(
                            &nav.flow, BOUNCE_MENU_DIRECTION_DOWN) != 0) {
                        bounce_game_shutdown(&nav);
                        bounce_game_release_level(&app);
                        if (saved_ok)
                            (void) setenv("XDG_DATA_HOME", saved, 1);
                        else
                            (void) unsetenv("XDG_DATA_HOME");
                        return -1;
                    }
                }
                if (bounce_ui_shell_handle_press(
                        &nav.flow, round_trips[step]) != 0
                    || bounce_game_sync_ui_state(&nav) != 0) {
                    bounce_game_shutdown(&nav);
                    bounce_game_release_level(&app);
                    if (saved_ok)
                        (void) setenv("XDG_DATA_HOME", saved, 1);
                    else
                        (void) unsetenv("XDG_DATA_HOME");
                    return -1;
                }
            }
            bounce_game_shutdown(&nav);

            if (bounce_persistence_load_record3(&back, &present) != 0
                || !present
                || back.b1 != prime.b1
                || back.level != prime.level
                || back.score != prime.score
                || back.lives != prime.lives
                || back.unk_x != prime.unk_x
                || back.unk_y != prime.unk_y
                || back.tile_x != prime.tile_x
                || back.tile_y != prime.tile_y) {
                bounce_game_release_level(&app);
                if (saved_ok)
                    (void) setenv("XDG_DATA_HOME", saved, 1);
                else
                    (void) unsetenv("XDG_DATA_HOME");
                return -1;
            }
        }
        sub_screen_no_write_ok = true;
    }

    if (saved_ok)
        (void) setenv("XDG_DATA_HOME", saved, 1);
    else
        (void) unsetenv("XDG_DATA_HOME");

    if (!game_over_b1_ok)
        ++bad;
    if (!game_end_b1_ok)
        ++bad;
    if (!lives_capture_ok)
        ++bad;
    if (!lives_roundtrip_ok)
        ++bad;
    if (!sub_screen_no_write_ok)
        ++bad;

    printf("RECORD3-TERMINAL-B1 game_over=%s game_end=%s "
           "lives_capture=%s lives_roundtrip=%s sub_screen_no_write=%s"
           " expected=yes yes yes yes yes %s\n",
           game_over_b1_ok ? "yes" : "no",
           game_end_b1_ok ? "yes" : "no",
           lives_capture_ok ? "yes" : "no",
           lives_roundtrip_ok ? "yes" : "no",
           sub_screen_no_write_ok ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");

    bounce_game_release_level(&app);
    return bad == 0 ? 0 : -1;
}

/*
 * STEP G-R3-R1 -- the Record 3 resume restore, e.a(int,int) (e.java:92-113).
 *
 * WHAT IS UNDER TEST. The whole restore window: the resume entry, k()'s tile
 * transform, AddScore()'s thorn install, the player/spawn/power-up restores, and
 * the HoopsScored/score/lives placement. It drives the PRODUCTION chain through
 * app_begin_canonical_gameplay(), not a private copy of it, so the window's
 * position is itself under test.
 *
 * TWO FIXTURES, because no single level can cover everything:
 *
 *   - Level 2 for the thorn work. Level 1 has none at all, and the RESUME-CAPTURE
 *     verifier already established that level 2 carries six (thorn_level2=6).
 *   - A synthetic level, built byte by byte through bounce_level_parse(), for the
 *     tile transform. The ten source ids do not all co-occur in any shipped level:
 *     level 2 has 7, 29, 13, 14, 15, 16, 21, 22 but never 23 or 24. Testing only
 *     what the assets happen to contain would leave two switch arms unverified.
 *
 * THE STORE IS NEVER TOUCHED. This verifier writes no file, so the player's real
 * save is unaffected -- the same discipline bounce_persistence_verify() uses with
 * its temporary directory, and the reason the restore is exercised by driving the
 * chain rather than by round-tripping through persistence.
 */
static int verify_resume_restore_payload(void)
{
    BounceApp app;
    BounceApp fresh;
    BounceApp kapp;
    BouncePersistenceRecord3 saved;
    const BounceDynThorns *thorns;
    BounceDynThornRecord pristine;
    uint16_t got = 0u;
    int16_t w3_before = 0;
    int16_t ae3 = 0;
    bool chain_ok;
    bool scalars_ok;
    bool player_ok;
    bool spawn_ok;
    bool powerups_ok;
    bool thorns_ok;
    bool bounds_ok;
    bool latch_ok;
    bool tick_ok;
    bool tiles_ok;
    bool excluded_ok;
    bool water_ok;
    bool dirty_ok;
    bool fresh_ok;
    /*
     * D-19 -- the two halves of the held-key clear, one per route.
     */
    bool input_cleared_ok;
    bool input_exempt_ok;
    unsigned int index;
    int bad = 0;

    /*
     * SECTION 1 -- k()'s tile transform, on a synthetic level.
     *
     * No shipped level contains all ten supported ids: level 2 has 7, 29, 13, 14,
     * 15, 16, 21 and 22 but never 23 or 24. Testing only what the assets happen
     * to contain would leave two switch arms unverified, so the fixture is built
     * byte by byte and parsed through the real bounce_level_parse().
     *
     * k() is called directly here because it touches only the tile grid. Its
     * POSITION inside the chain is covered by SECTION 2, and calling it directly
     * lets the fixture own the runtime without a level file on disk.
     */
    {
        /*
         * The ten literals from e.java:499-534, transcribed in the order of
         * app_resume_saved_tile_ids. Written out literally rather than recomputed,
         * so the check cannot pass by using the same mapping it is testing.
         */
        static const int32_t expect_literal[10] = {
            0x00, 0x00, 0x11, 0x12, 0x19, 0x1A, 0x13, 0x14, 0x1B, 0x1C
        };
        uint8_t bytes[8u + 20u + 1u];
        BounceLevel *level;
        BounceRuntimeLevelTiles *runtime;
        size_t at = 8u;
        unsigned int slot;

        memset(bytes, 0, sizeof bytes);
        bytes[0] = 1u;   /* ballInitialX */
        bytes[1] = 1u;   /* ballInitialY */
        bytes[2] = 0u;   /* isBigBall: 0 -> regular ball */
        bytes[3] = 9u;   /* exitX */
        bytes[4] = 0u;   /* exitY */
        bytes[5] = 0u;   /* HoopsTotal */
        bytes[6] = 10u;  /* width  */
        bytes[7] = 2u;   /* height */
        /* Row 0: each supported id once, dry. */
        for (slot = 0u; slot < 10u; ++slot)
            bytes[at++] = app_resume_saved_tile_ids[slot];
        /* Row 1: each id with the water bit and the dirty bit both set. */
        for (slot = 0u; slot < 10u; ++slot)
            bytes[at++] = (uint8_t)(app_resume_saved_tile_ids[slot]
                | 0x40u
                | 0x80u);
        bytes[at++] = 0u;  /* DynThornsCount */

        level = bounce_level_parse(bytes, at);
        if (level == NULL)
            return -1;
        runtime = bounce_runtime_level_tiles_create(level);
        if (runtime == NULL) {
            bounce_level_destroy(level);
            return -1;
        }

        memset(&kapp, 0, sizeof kapp);
        kapp.level = level;
        kapp.runtime = runtime;
        kapp.resume_record3.tile_delta_count = 1u;
        /*
         * Exclude exactly one DRY cell: (row 0, col 3), which carries id 14.
         * Using a water cell would conflate the exclusion with the water-bit case.
         *
         * The stored tile_id is deliberately wrong -- 0 is not the id at that
         * coordinate. e.java:544 compares only u[b1][0] and u[b1][1], so a
         * transform that consulted it would still exclude this cell, and the
         * excluded_ok check below is what proves the id was ignored rather than
         * coincidentally matching.
         */
        kapp.resume_record3.tile_deltas[0].row = 0;
        kapp.resume_record3.tile_deltas[0].col = 3;
        kapp.resume_record3.tile_deltas[0].tile_id = 0u;
        app_resume_restore_tiles(&kapp);

        tiles_ok = true;
        excluded_ok = true;
        for (slot = 0u; slot < 10u; ++slot) {
            if (bounce_runtime_level_tiles_get(
                    runtime, (int) slot, 0, &got) != 0) {
                tiles_ok = false;
                excluded_ok = false;
                break;
            }
            if (slot == 3u) {
                if ((int32_t) got != 14)
                    excluded_ok = false;
                continue;
            }
            if ((int32_t) got != expect_literal[slot]) {
                tiles_ok = false;
                break;
            }
        }
        /* Row 1: literal | water, and 0x80 must not survive. */
        water_ok = true;
        dirty_ok = true;
        for (slot = 0u; slot < 10u; ++slot) {
            if (bounce_runtime_level_tiles_get(
                    runtime, (int) slot, 1, &got) != 0) {
                water_ok = false;
                break;
            }
            if ((int32_t) got != (expect_literal[slot] | 0x40))
                water_ok = false;
            if ((got & 0x80u) != 0u)
                dirty_ok = false;
        }

        bounce_runtime_level_tiles_destroy(runtime);
        bounce_level_destroy(level);
    }

    /*
     * SECTION 2 -- the whole restore window, through the PRODUCTION chain.
     *
     * Level 2 is used because it owns six dynamic thorns; level 1 owns none, which
     * the RESUME-CAPTURE verifier already established. Every saved value differs
     * from what the loader produces, so a restore reading the wrong source cannot
     * pass.
     */
    memset(&saved, 0, sizeof saved);
    saved.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    saved.level = 2u;
    saved.lives = 2u;
    saved.hoops_scored = 3u;
    saved.ball_size = 12u;
    saved.score = 7654;
    saved.unk_x = 155;
    saved.unk_y = 242;
    saved.aq_l = 44;
    saved.aq_o = -21;
    saved.tile_x = 7;
    saved.tile_y = 9;
    saved.power_up_1 = 5;
    saved.power_up_gravity = 7;
    saved.power_up_3 = 4;
    saved.dyn_thorn_count = 6u;
    /*
     * Explicit per-record values. Record 3 uses w.x == 0 with ae.x == 1 so the
     * first-tick check below is exact: UpdateDynThorns() computes 0 + 1 == 1, which
     * lies inside [0, (TopRight.x - BottomLeft.x - 2) * 12] and therefore cannot be
     * clamped into looking correct by accident.
     */
    saved.dyn_thorns[0].w_x = 10;  saved.dyn_thorns[0].w_y = 20;
    saved.dyn_thorns[0].ae_x = -1; saved.dyn_thorns[0].ae_y = 2;
    saved.dyn_thorns[1].w_x = 11;  saved.dyn_thorns[1].w_y = 21;
    saved.dyn_thorns[1].ae_x = 1;  saved.dyn_thorns[1].ae_y = 3;
    saved.dyn_thorns[2].w_x = 12;  saved.dyn_thorns[2].w_y = 22;
    saved.dyn_thorns[2].ae_x = -1; saved.dyn_thorns[2].ae_y = 4;
    /*
     * Record 3's w.x is 0 because every level-2 thorn has an X bound of 0, so
     * UpdateDynThorns() pins that axis regardless. Its w.y of 23 is what the
     * first-tick check below advances, and 23 + 5 = 28 is inside the Y bound of
     * 48, so the assertion is exact rather than clamp-dependent.
     */
    saved.dyn_thorns[3].w_x = 0;   saved.dyn_thorns[3].w_y = 23;
    saved.dyn_thorns[3].ae_x = 1;  saved.dyn_thorns[3].ae_y = 5;
    saved.dyn_thorns[4].w_x = 14;  saved.dyn_thorns[4].w_y = 24;
    saved.dyn_thorns[4].ae_x = -1; saved.dyn_thorns[4].ae_y = 6;
    saved.dyn_thorns[5].w_x = 15;  saved.dyn_thorns[5].w_y = 25;
    saved.dyn_thorns[5].ae_x = 1;  saved.dyn_thorns[5].ae_y = 7;

    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        return -1;
    app.resume_record3 = saved;
    app.resume_requested = true;
    /*
     * D-19 -- THE RESUME ROUTE IS EXEMPT, and this is the assertion for it.
     *
     * JAVA EVIDENCE. BounceGame.java:226-234 is the J != 0 branch of the
     * Continue command:
     *
     *     } else if (this.J != 0) {
     *         this.display.setCurrent(this.v);
     *         if (this.J == 1) { this.v.a(this.y, this.M); }
     *         else { this.v.a(this.RecordLevel, this.RecordScore,
     *                          this.RecordLives); }
     *         this.u = null;
     *         this.v.StartGameTimer();
     *         this.K = 1;
     *     }
     *
     * It never calls a(boolean,int), so the `this.v.aq.a()` at
     * BounceGame.java:154 does NOT run. hideNotify does not cover it either:
     * setCurrent(this.v) brings the canvas BACK to the display, and MIDP
     * calls hideNotify on the Displayable being REMOVED -- which here is the
     * main-menu List, a class that has no such callback. So in Java this route
     * reaches gameplay with the key mask exactly as the previous session left
     * it.
     *
     * A key is therefore pressed before the entry and must still be held after
     * it. RIGHT_ARROW is used because it is the native transcription of the
     * source's bit 0x2 (e.keyPressed `case 5: this.aq.c(2)`, f.java:403-404),
     * i.e. the one that actually accelerates the ball, so a regression here is
     * observable in play and not merely cosmetic.
     */
    if (bounce_input_apply_source(
            &app.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0
        || !app.input.right
        || app.input.held_sources == UINT64_C(0)) {
        bounce_game_release_level(&app);
        return -1;
    }
    if (bounce_app_flow_begin_resume_entry(
            &app.flow,
            (int) saved.level,
            (int) saved.lives
        ) != 0
        || app_begin_canonical_gameplay(&app) != 0) {
        bounce_game_release_level(&app);
        return -1;
    }
    input_exempt_ok = app.input.right && app.input.held_sources != UINT64_C(0);

    chain_ok = app.flow.state == BOUNCE_APP_STATE_GAMEPLAY
        && app.state == BOUNCE_GAME_STATE_PLAYING
        && app.flow.level_id == (int) saved.level
        && app.level != NULL
        && app.runtime != NULL;
    /* A. level is chain_ok; score, lives and HoopsScored are these three. */
    scalars_ok = app.score == saved.score
        && app.lives == (int) saved.lives
        && app.hoops_scored == (int) saved.hoops_scored;
    /* B. player scalars. */
    player_ok = app.player.TODO_unkX == saved.unk_x
        && app.player.TODO_unkY == saved.unk_y
        && app.player.ballSize == (int) saved.ball_size
        && app.player.horizontal_velocity == saved.aq_l
        && app.player.o == saved.aq_o;
    /*
     * C. spawn tile, and NOT the live cell. Level 2's own spawn is (2,1) and the
     * restored world position is (155,242) = cell (12,20), so all three differ.
     */
    spawn_ok = app.spawn.tile_x == saved.tile_x
        && app.spawn.tile_y == saved.tile_y
        && app.spawn.tile_x != app.player.TODO_unkX / BOUNCE_TILE_SIZE
        && app.spawn.tile_y != app.player.TODO_unkY / BOUNCE_TILE_SIZE;
    /* D. all three power-ups. */
    powerups_ok = app.player.TODO_somePowerUp1 == saved.power_up_1
        && app.player.powerUpGravity == saved.power_up_gravity
        && app.player.TODO_somePowerUp3 == saved.power_up_3;
    /* The latch is consumed exactly once, inside the window. */
    latch_ok = !app.resume_requested;

    /* F. dyn-thorns installed; count and bounds untouched. */
    thorns = bounce_runtime_level_tiles_dyn_thorns(app.runtime);
    thorns_ok = thorns != NULL
        && thorns->records != NULL
        && thorns->count == saved.dyn_thorn_count;
    bounds_ok = thorns_ok;
    for (index = 0u; thorns_ok && index < thorns->count; ++index) {
        if (thorns->records[index].w.x != saved.dyn_thorns[index].w_x
            || thorns->records[index].w.y != saved.dyn_thorns[index].w_y
            || thorns->records[index].ae.x != saved.dyn_thorns[index].ae_x
            || thorns->records[index].ae.y != saved.dyn_thorns[index].ae_y)
            thorns_ok = false;
        /*
         * bottom_left/top_right are the level-derived clamp bounds. They are
         * compared against the loader's own decode rather than a hardcoded table,
         * so this assertion cannot drift from the level format.
         */
        if (bounce_level_dyn_thorn_record(app.level, index, &pristine) != 0) {
            bounds_ok = false;
        } else if (thorns->records[index].bottom_left.x
                != pristine.bottom_left.x
            || thorns->records[index].bottom_left.y
                != pristine.bottom_left.y
            || thorns->records[index].top_right.x
                != pristine.top_right.x
            || thorns->records[index].top_right.y
                != pristine.top_right.y) {
            bounds_ok = false;
        }
    }

    /*
     * G. FIRST-TICK BOUNDARY. One UpdateDynThorns() step must move record 3's w.y
     * by exactly the RESTORED ae.y. That holds only if the restored values were
     * already installed: had the restore run after the tick, w.y would have
     * advanced from the level's own initial phase instead.
     *
     * THE Y AXIS IS DELIBERATE. Every level-2 thorn has
     * bound_x = (TopRight.x - BottomLeft.x - 2) * 12 == 0, so UpdateDynThorns()
     * clamps w.x to 0 on every step and asserts nothing useful about X. The Y
     * bound is 48, so a restored w.y of 23 advanced by ae.y of 5 lands on 28 with
     * no clamping. The level's own record 3 starts at w=(0,0), which would reach
     * 1 instead -- the two are far enough apart that no clamping can make them
     * coincide.
     */
    tick_ok = false;
    if (thorns_ok && thorns->count > 3u) {
        w3_before = thorns->records[3].w.y;
        ae3 = thorns->records[3].ae.y;
        if (bounce_runtime_level_tiles_update_dyn_thorns(app.runtime) != 1) {
            tick_ok = false;
        } else {
            tick_ok = bounce_runtime_level_tiles_dyn_thorns(app.runtime)
                ->records[3].w.y == (int16_t)(w3_before + ae3);
        }
    }
    bounce_game_release_level(&app);

    /* SECTION 3 -- a fresh New Game must still produce score 0 / lives 3. */
    memset(&fresh, 0, sizeof fresh);
    if (drive_app_to_gameplay_entry_start_level(&fresh) != 0
        || bounce_input_apply_source(
               &fresh.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0
        || !fresh.input.right
        || fresh.input.held_sources == UINT64_C(0)
        || app_begin_canonical_gameplay(&fresh) != 0) {
        bounce_game_release_level(&fresh);
        return -1;
    }
    fresh_ok = fresh.score == 0 && fresh.lives == 3;
    /*
     * D-19 -- THE NEW GAME ROUTE CLEARS, and this is the assertion for it.
     *
     * JAVA EVIDENCE. New Game runs through a(boolean, int):
     *
     *     } else if (str.equals(this.menuStrings[1])) {
     *         if (this.K != 4)
     *             if (this.MaxLevels > 1) { LevelSelect(); }
     *             else { this.K = 4; a(true, 1); }        <-- :242
     *     }
     *
     * and a(boolean,int) reaches `this.v.aq.a()` at BounceGame.java:154 on
     * EVERY one of its four routes. `f.a()` is `w &= 0xFFFFFFF0`
     * (f.java:150-152), so no bit survives the entry.
     *
     * This is the case that matters in play: with the X11 auto-repeat filter
     * (vertical_slice.c:21459) discarding repeat KeyPress events, a key the
     * player held while leaving the previous run never gets its KeyRelease, so
     * without this clear its bit stays set and the ball accelerates on the very
     * first tick of the next level with no key actually down.
     */
    input_cleared_ok = !fresh.input.right
        && !fresh.input.left
        && !fresh.input.up
        && !fresh.input.down
        && fresh.input.held_sources == UINT64_C(0);
    bounce_game_release_level(&fresh);

    if (!chain_ok)
        ++bad;
    if (!scalars_ok)
        ++bad;
    if (!player_ok)
        ++bad;
    if (!spawn_ok)
        ++bad;
    if (!powerups_ok)
        ++bad;
    if (!thorns_ok)
        ++bad;
    if (!bounds_ok)
        ++bad;
    if (!latch_ok)
        ++bad;
    if (!tick_ok)
        ++bad;
    if (!tiles_ok)
        ++bad;
    if (!excluded_ok)
        ++bad;
    if (!water_ok)
        ++bad;
    if (!dirty_ok)
        ++bad;
    if (!fresh_ok)
        ++bad;
    if (!input_cleared_ok)
        ++bad;
    if (!input_exempt_ok)
        ++bad;

    printf("R1-RESTORE chain=%s scalars=%s player=%s spawn=%s powerups=%s "
           "thorns=%s thorn_bounds=%s latch=%s first_tick=%s tiles=%s "
           "excluded=%s water=%s dirty=%s fresh_entry=%s "
           "input_cleared=%s input_exempt=%s expected="
           "yes yes yes yes yes yes yes yes yes yes yes yes yes yes yes yes %s\n",
        chain_ok ? "yes" : "no",
        scalars_ok ? "yes" : "no",
        player_ok ? "yes" : "no",
        spawn_ok ? "yes" : "no",
        powerups_ok ? "yes" : "no",
        thorns_ok ? "yes" : "no",
        bounds_ok ? "yes" : "no",
        latch_ok ? "yes" : "no",
        tick_ok ? "yes" : "no",
        tiles_ok ? "yes" : "no",
        excluded_ok ? "yes" : "no",
        water_ok ? "yes" : "no",
        dirty_ok ? "yes" : "no",
        fresh_ok ? "yes" : "no",
        input_cleared_ok ? "yes" : "no",
        input_exempt_ok ? "yes" : "no",
        bad == 0 ? "PASS" : "FAIL");

    return bad == 0 ? 0 : -1;
}

/*
 * STEP G-R3-R2 -- the CONTINUE menu wiring.
 *
 * WHAT IS UNDER TEST. The whole player-facing route, in order:
 *
 *   availability   a b1 == 1 record makes continue_available true; absent,
 *                  b1 == 0 and b1 == 2 all make it false
 *   menu action     SELECT on the Continue row yields
 *                   BOUNCE_MENU_ACTION_CONTINUE and leaves the flow in MENU
 *   handoff          app_begin_resume_from_menu() moves the flow to
 *                   GAMEPLAY_ENTRY with the record's level and lives
 *   chain             the production chain then reaches PLAYING with the R1
 *                   restore applied and the latch consumed
 *   refusal          a non-resumable record is refused rather than resumed
 *   regressions      New Game still 0/3, terminal Continue still 0/3 and still
 *                   does NOT arm the resume latch
 *
 * THE STORE IS NEVER TOUCHED. XDG_DATA_HOME is redirected to a mkdtemp
 * directory for the duration, which is the same isolation
 * bounce_persistence_verify() uses and for the same reason: a self-test must not
 * read or write the player's real save. The temporary directory is left in place,
 * exactly as bounce_persistence_verify() leaves its own -- it lives under /tmp and
 * the real location was never touched.
 *
 * WHY b1 == 2 IS EXPECTED UNAVAILABLE. Java sends b1 == 2 down
 * BounceGame.java:230, the THREE-argument e.a(int,int,int) with
 * RecordLevel/RecordScore/RecordLives. R1 deliberately did not implement that
 * branch, so offering a full resume for it would advertise behaviour that does
 * not exist. This is asserted rather than assumed.
 */
static bool app_continue_availability_probe(void)
{
    BounceApp app;
    bool available;

    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        return false;
    /*
     * bounce_game_enter_menu() leaves pending_action at NONE, which is what the
     * producer's guard requires. A probe that skipped the menu entry would be
     * refused for the wrong reason and would prove nothing.
     */
    app_refresh_continue_availability(&app);
    available = app.flow.menu.continue_available;
    bounce_game_release_level(&app);
    return available;
}

/* Force the Continue action and confirm the handoff refuses without a record. */
static bool app_continue_handoff_refuses(void)
{
    BounceApp app;
    int rc;

    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        return false;
    app.flow.menu.pending_action = BOUNCE_MENU_ACTION_CONTINUE;
    rc = app_begin_resume_from_menu(&app);
    bounce_game_release_level(&app);
    return rc == 1
        && !app.resume_requested
        && app.flow.state == BOUNCE_APP_STATE_MENU;
}

static int verify_continue_entry_wiring(void)
{
    BounceApp app;
    BouncePersistenceRecord3 record;
    char root[] = "/tmp/bounce-continue-XXXXXX";
    char saved[512];
    bool saved_ok;
    bool absent_ok;
    bool b1_zero_ok;
    bool b1_two_ok;
    bool b1_one_ok;
    /* D-03/D-04: the J == 2 route, asserted end to end. */
    bool j_two_ok = false;
    bool action_ok;
    bool handoff_ok;
    bool chain_ok;
    bool refusal_ok;
    bool newgame_ok;
    bool terminal_ok;
    int bad = 0;

    if (mkdtemp(root) == NULL)
        return -1;
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void) snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0)
        return -1;

    /* ---- A. availability across the four record states ---- */
    absent_ok = !app_continue_availability_probe();

    memset(&record, 0, sizeof record);
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
    if (bounce_persistence_save_record3(&record) != 0)
        do { fprintf(stderr, "R2FAIL site 0\n"); goto failure; } while (0);
    b1_zero_ok = !app_continue_availability_probe();

    /*
     * D-03 -- b1 == 2 IS OFFERED. This asserted the opposite, which is the D-04
     * divergence stated as a test: Java appends the Continue row when
     * `this.K == 1 || this.J == 1 || this.J == 2` (BounceGame.java:116) and J is
     * the record's b1 byte (BounceGame.java:293), so a b1 == 2 store -- written
     * while K == 5, i.e. on the level-complete screen
     * (BounceGame.java:354-359) -- shows a Continue row.
     */
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE;
    record.level = 5u;
    record.score = 31400;
    record.lives = 2u;
    if (bounce_persistence_save_record3(&record) != 0)
        do { fprintf(stderr, "R2FAIL site 1\n"); goto failure; } while (0);
    b1_two_ok = app_continue_availability_probe();

    /* The record R2 actually resumes from. */
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    record.level = 2u;
    record.lives = 2u;
    record.hoops_scored = 3u;
    record.ball_size = 12u;
    record.score = 7654;
    record.unk_x = 155;
    record.unk_y = 242;
    record.aq_l = 44;
    record.aq_o = -21;
    record.tile_x = 7;
    record.tile_y = 9;
    record.power_up_1 = 5;
    record.power_up_gravity = 7;
    record.power_up_3 = 4;
    if (bounce_persistence_save_record3(&record) != 0)
        do { fprintf(stderr, "R2FAIL site 2\n"); goto failure; } while (0);
    b1_one_ok = app_continue_availability_probe();

    /* ---- B. the menu action ---- */
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        do { fprintf(stderr, "R2FAIL site 3\n"); goto failure; } while (0);
    app_refresh_continue_availability(&app);
    if (!app.flow.menu.continue_available) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 4\n"); goto failure; } while (0);
    }
    if (bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 5\n"); goto failure; } while (0);
    }
    /*
     * The action must be CONTINUE and the flow must STILL BE IN MENU: the
     * app_flow.c branch deliberately does not transition, because the level and
     * lives live in the record rather than the flow.
     */
    action_ok = app.flow.menu.pending_action == BOUNCE_MENU_ACTION_CONTINUE
        && app.flow.state == BOUNCE_APP_STATE_MENU;

    /* ---- the handoff, then the production chain ---- */
    if (app_begin_resume_from_menu(&app) != 0) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 6\n"); goto failure; } while (0);
    }
    handoff_ok = app.flow.state == BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        && app.flow.menu.pending_action == BOUNCE_MENU_ACTION_START_LEVEL
        && app.flow.pending_level_id == (int) record.level
        && app.flow.gameplay_entry.initial_lives == (int) record.lives
        && app.resume_requested;
    /*
     * The score must NOT have been zeroed on the way. New Game and Level
     * Selection both set new_game_score_reset_pending, and this path must not;
     * 7654 here is what proves it.
     */
    if (app_begin_canonical_gameplay(&app) != 0) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 7\n"); goto failure; } while (0);
    }
    chain_ok = app.flow.state == BOUNCE_APP_STATE_GAMEPLAY
        && app.state == BOUNCE_GAME_STATE_PLAYING
        && app.flow.level_id == (int) record.level
        && app.score == record.score
        && app.lives == (int) record.lives
        && app.hoops_scored == (int) record.hoops_scored
        && app.player.TODO_unkX == record.unk_x
        && app.player.TODO_unkY == record.unk_y
        && app.spawn.tile_x == record.tile_x
        && app.spawn.tile_y == record.tile_y
        && app.player.TODO_somePowerUp1 == record.power_up_1
        && !app.resume_requested;
    bounce_game_release_level(&app);

    /*
     * D-03/D-04 -- THE J == 2 ROUTE, END TO END.
     *
     * The section above proves the J == 1 branch. This proves the other one, and
     * it asserts what makes the two DIFFERENT rather than merely similar.
     *
     * BounceGame.java:231-232 resumes a J == 2 record with
     *
     *     this.v.a(this.RecordLevel, this.RecordScore, this.RecordLives);
     *
     * and e.java:81-90 is that method: it sets level, HoopsScored = 0, lives,
     * score, e = false, TODO_ExitUnlocked = false, then calls InitializeGame().
     * So a J == 2 Continue STARTS THE LEVEL, and the assertions that matter are
     * the ones a position-restore would FAIL:
     *
     *   - the recorded score and lives must arrive;
     *   - HoopsScored must be 0, because e.java:84 sets it, where the J == 1 path
     *     would have carried the recorded value;
     *   - the ball must be at the LEVEL's own spawn, not the recorded tile,
     *     because InitializeGame() places it there (e.java:121) where the J == 1
     *     branch would have restored the recorded position;
     *   - the power-ups must be the level's initial ones, not the recorded ones,
     *     for the same reason;
     *   - neither latch may survive, so the route cannot repeat.
     *
     * The record deliberately carries a NON-ZERO tile position, power-ups and
     * HoopsScored. If this route ever degraded into the J == 1 restore, every one
     * of those would come back and the assertions below would fail.
     */
    {
        BounceApp two;
        BouncePersistenceRecord3 r2;

        memset(&r2, 0, sizeof r2);
        r2.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE;
        r2.level = 3u;
        r2.score = 31400;
        r2.lives = 1;
        r2.hoops_scored = 4u;
        r2.ball_size = 12u;
        /* A mid-level position that must NOT be restored. */
        r2.unk_x = 1710;
        r2.unk_y = 449;
        r2.tile_x = 12;
        r2.tile_y = 1;
        r2.power_up_1 = 5;
        r2.power_up_gravity = 7;
        r2.power_up_3 = 4;
        if (bounce_persistence_save_record3(&r2) != 0) {
            do { fprintf(stderr, "R2FAIL site 8a\n"); goto failure; } while (0);
        }

        memset(&two, 0, sizeof two);
        if (bounce_game_init(&two) != 0
            || bounce_game_enter_menu(&two) != 0
            || !app_continue_availability_probe()) {
            bounce_game_release_level(&two);
            do { fprintf(stderr, "R2FAIL site 8b\n"); goto failure; } while (0);
        }
        two.flow.menu.pending_action = BOUNCE_MENU_ACTION_CONTINUE;
        if (app_begin_resume_from_menu(&two) != 0) {
            bounce_game_release_level(&two);
            do { fprintf(stderr, "R2FAIL site 8c\n"); goto failure; } while (0);
        }
        /*
         * THE HANDOFF carries the J == 1 branch's discriminator: continue_record_pending
         * is set and resume_requested is NOT, which is what stops the mid-level
         * window from running.
         */
        if (!two.continue_record_pending || two.resume_requested
            || two.flow.state != BOUNCE_APP_STATE_GAMEPLAY_ENTRY
            || two.flow.menu.pending_action != BOUNCE_MENU_ACTION_START_LEVEL
            || two.flow.pending_level_id != (int) r2.level
            || two.flow.gameplay_entry.initial_score != (int) r2.score
            || two.flow.gameplay_entry.initial_lives != (int) r2.lives) {
            bounce_game_release_level(&two);
            do { fprintf(stderr, "R2FAIL site 8d\n"); goto failure; } while (0);
        }
        if (app_begin_canonical_gameplay(&two) != 0) {
            bounce_game_release_level(&two);
            do { fprintf(stderr, "R2FAIL site 8e\n"); goto failure; } while (0);
        }
        if (two.flow.state != BOUNCE_APP_STATE_GAMEPLAY
            || two.state != BOUNCE_GAME_STATE_PLAYING
            || two.flow.level_id != (int) r2.level
            || two.score != r2.score
            || two.lives != (int) r2.lives
            /* e.java:84 -- HoopsScored = 0. */
            || two.hoops_scored != 0
            /* InitializeGame() e.java:121 -- the LEVEL's spawn, not r2's tile. */
            || two.spawn.tile_x == r2.tile_x
            || two.spawn.tile_y == r2.tile_y
            /* And the ball is where the level puts it, not at r2.unk_x/unk_y. */
            || two.player.TODO_unkX == r2.unk_x
            || two.player.TODO_unkY == r2.unk_y
            /* And the power-ups are the level's, not r2's. */
            || two.player.TODO_somePowerUp1 == r2.power_up_1
            /* Neither latch may survive. */
            || two.resume_requested
            || two.continue_record_pending) {
            bounce_game_release_level(&two);
            do { fprintf(stderr, "R2FAIL site 8f\n"); goto failure; } while (0);
        }
        j_two_ok = true;
        bounce_game_release_level(&two);
    }

    /* ---- a NON-resumable record must be refused, not resumed ---- */
    /*
     * D-03 -- THE FIXTURE CHANGED, AND THE REASON IS THE SOURCE.
     *
     * This block used to store a B1_LEVEL_COMPLETE record and require the handoff
     * to REFUSE it, on the stated ground that it was "a non-resumable record".
     * That ground is wrong. BounceGame.java:354-359 writes b1 = 2 exactly when
     * K == 5, which is the level-complete screen, and BounceGame.java:229-232
     * resumes it:
     *
     *     } else {
     *         this.v.a(this.RecordLevel, this.RecordScore,
     *                  this.RecordLives);
     *     }
     *
     * so J == 2 is Java's SECOND resume branch, not a rejection. The record that
     * genuinely must be refused is b1 == 0 -- Java's J == 0, written whenever K
     * was neither 1 nor 5 -- and commandAction's `else if (this.J != 0)` has no
     * branch for it at all. That is what this now stores.
     */
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_NONE;
    if (bounce_persistence_save_record3(&record) != 0)
        do { fprintf(stderr, "R2FAIL site 8\n"); goto failure; } while (0);
    refusal_ok = app_continue_handoff_refuses();
    /* Restore the resumable record for nothing else; the rest is pure flow. */
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    if (bounce_persistence_save_record3(&record) != 0)
        do { fprintf(stderr, "R2FAIL site 9\n"); goto failure; } while (0);

    /* ---- D. New Game is unchanged even with CONTINUE offered ---- */
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        do { fprintf(stderr, "R2FAIL site 10\n"); goto failure; } while (0);
    app_refresh_continue_availability(&app);
    if (!app.flow.menu.continue_available) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 11\n"); goto failure; } while (0);
    }
    /*
     * STEP 38-RESET -- the count is pinned to 0 before the New Game press.
     *
     * What this section is FOR is that offering a Continue row does not disturb New
     * Game: the highlight moves off Continue, New Game activates, the score resets
     * and three lives are dealt. None of that depends on the unlocked-level count,
     * so the count is set to the value that makes New Game stage level 1 directly and
     * the section keeps testing only what it names.
     *
     * Without the pin, the shipped default of 2 would send this press through Level
     * Select instead, app_begin_canonical_gameplay() would have nothing staged to
     * begin, and the section would fail on `lives == 3` -- three lines away from the
     * thing it is actually about, which is a poor way to report a moved default. The
     * default-of-2 route is covered where it belongs, by
     * verify_gameplay_entry_boundary()'s Test A.
     */
    if (bounce_app_flow_set_available_level_count(&app.flow, 0u) != 0
        || bounce_app_flow_available_level_count(&app.flow) != 0u
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_DOWN
        ) != 0
        || bounce_ui_shell_handle_press(
            &app.flow,
            BOUNCE_UI_INPUT_SELECT
        ) != 0
        || bounce_game_sync_ui_state(&app) != 0) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 12\n"); goto failure; } while (0);
    }
    if (app_begin_canonical_gameplay(&app) != 0) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 13\n"); goto failure; } while (0);
    }
    newgame_ok = app.score == 0
        && app.lives == 3
        && !app.resume_requested;
    bounce_game_release_level(&app);

    /* ---- terminal Continue is unchanged and does NOT arm the latch ---- */
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        do { fprintf(stderr, "R2FAIL site 14\n"); goto failure; } while (0);
    app.flow.state = BOUNCE_APP_STATE_LEVEL_COMPLETE;
    /*
     * level_id is the level the player CONTINUES INTO, not the one just finished.
     * bounce_app_flow_continue_level() deliberately does not increment it
     * (app_flow.c:851-856) because bounce_app_flow_complete_level(), called from
     * bounce_game_mark_level_complete() -- the single writer of deferred_init --
     * has already done e.java:317's this.level++ before this screen exists. So
     * completing level 2 means level_id == 3 here, and seeding 2 would forge a
     * state production can never produce. pending_level_id below is recorded from
     * this field, which is why the 2 and the 3 cannot both be expected.
     */
    app.flow.level_id = 3;
    app.deferred_init = true;
    /*
     * STEP P6 -- the completed run's remaining lives, seeded to a value that is NOT
     * BOUNCE_APP_ENTRY_INITIAL_LIVES so the assertion below can distinguish
     * preservation from a reset. This assertion used to require
     * `initial_lives == BOUNCE_APP_ENTRY_INITIAL_LIVES`, which was correct only while
     * bounce_game_continue_level() discarded the run's lives and let
     * bounce_game_activate_staged_level() install the constant. Java performs no
     * `lives` write on the post-completion path at all (e.java:313-327,
     * BounceGame.java:199-213, :263-266 and e.java:115-124 all leave it alone, and
     * the only clobbering write, e.java:84, is skipped by the `if (paramBoolean)`
     * guard at BounceGame.java:150), so the remaining lives now travel through the
     * existing carrier. Requiring 2 here is what proves the route carries them rather
     * than resetting them.
     */
    app.lives = 2;
    if (bounce_game_continue_level(&app) != 3) {
        bounce_game_release_level(&app);
        do { fprintf(stderr, "R2FAIL site 15\n"); goto failure; } while (0);
    }
    terminal_ok = app.flow.state == BOUNCE_APP_STATE_GAMEPLAY_ENTRY
        && app.flow.menu.pending_action == BOUNCE_MENU_ACTION_START_LEVEL
        && app.flow.pending_level_id == 3
        /* STEP P6: the run's lives survive into the entry, not the constant. */
        && app.flow.gameplay_entry.initial_lives == 2
        && !app.resume_requested
        && !app.flow.menu.new_game_score_reset_pending;
    bounce_game_release_level(&app);

    if (!absent_ok)
        ++bad;
    if (!b1_zero_ok)
        ++bad;
    if (!b1_two_ok)
        ++bad;
    if (!b1_one_ok)
        ++bad;
    if (!j_two_ok)
        ++bad;
    if (!action_ok)
        ++bad;
    if (!handoff_ok)
        ++bad;
    if (!chain_ok)
        ++bad;
    if (!refusal_ok)
        ++bad;
    if (!newgame_ok)
        ++bad;
    if (!terminal_ok)
        ++bad;

    printf("R2-CONTINUE absent=%s b1_zero=%s b1_two=%s b1_one=%s j_two_route=%s"
           " action=%s "
           "handoff=%s chain=%s refusal=%s new_game=%s terminal=%s "
           "expected=yes yes yes yes yes yes yes yes yes yes yes yes %s\n",
        absent_ok ? "yes" : "no",
        b1_zero_ok ? "yes" : "no",
        b1_two_ok ? "yes" : "no",
        b1_one_ok ? "yes" : "no",
        j_two_ok ? "yes" : "no",
        action_ok ? "yes" : "no",
        handoff_ok ? "yes" : "no",
        chain_ok ? "yes" : "no",
        refusal_ok ? "yes" : "no",
        newgame_ok ? "yes" : "no",
        terminal_ok ? "yes" : "no",
        bad == 0 ? "PASS" : "FAIL");

    if (saved_ok)
        (void) setenv("XDG_DATA_HOME", saved, 1);
    else
        (void) unsetenv("XDG_DATA_HOME");
    return bad == 0 ? 0 : -1;

failure:
    bounce_game_release_level(&app);
    if (saved_ok)
        (void) setenv("XDG_DATA_HOME", saved, 1);
    else
        (void) unsetenv("XDG_DATA_HOME");
    return -1;
}

/*
 * ===================================================================
 * STEP P2 -- the Level Complete progression boundary.
 * ===================================================================
 *
 * WHAT IS UNDER TEST. Java e.java:317 `this.level++`, together with the
 * MaxLevels synchronisation at BounceGame.java:418-420:
 *
 *     if (this.v.level > this.MaxLevels) {
 *         this.MaxLevels = Math.min(this.v.level, 11);
 *         WriteToStore(1);
 *     }
 *
 * so completing level N must leave level_id == N + 1 and
 * available_level_count == min(N + 1, 11). WriteToStore is the RMS write and has
 * no native counterpart, so it is elided rather than approximated.
 *
 * WHY THIS TEST EXISTS AT ALL. The behaviour was already implemented, under
 * STEP 12X-G-P2, in bounce_app_flow_complete_level() (app_flow.c:760) and is
 * already called from the completion consumer bounce_game_mark_level_complete()
 * (game.c:1297). Nothing was missing except an assertion: the suite proved the
 * flow MOVED on completion but never checked the resulting numbers, and the one
 * existing level_id advance -- BOUNCE_APP_EVENT_NEXT_LEVEL at app_flow.c:190 --
 * is a test-only state-machine event that never touches available_level_count.
 * So P2 changed no product code; this is the guard that was missing.
 *
 * THE BOUNDARY IS PROVED TWICE, DELIBERATELY. Part one drives
 * bounce_app_flow_complete_level() directly over a table of cases, which pins the
 * arithmetic including both arms of the min(level, 11) clamp. Part two goes
 * through the REAL production consumer -- bounce_game_mark_level_complete(),
 * reached from a genuinely PLAYING level -- so a future edit that left the
 * helper correct but unwired, or wired twice, fails here. Testing only the
 * helper would not catch either.
 *
 * CASE A' IS NOT REDUNDANT. A virgin store has available_level_count == 0
 * (bounce_app_flow_init, app_flow.c:125), so the monotonic guard
 * `level_id > available_level_count` is entered from 0 rather than from 1. Both
 * start states are asserted because a fresh install is the common case.
 *
 * THE FINAL-LEVEL EXPECTATION IS THE e.java:320 READER, NOT A NEW RULE. After
 * completing level 11, level_id is 12 and bounce_app_flow_level_is_final() must
 * already be true, because that is the predicate the terminal branch at
 * game.c:1387 uses to choose ShowInstructions over ShowLevelComplete. Asserting
 * it here proves the cap and the branch that reads it agree.
 */
struct p2_consumer_observation {
    int level_before;
    unsigned int count_before;
    int complete_rc;
    int level_after;
    unsigned int count_after;
    BounceAppState flow_after;
    BounceGameState game_after;
    int final_after;
    bool deferred_after;
    bool second_refused;
    bool reached_playing;
};

/*
 * One completion run through the production consumer, observed rather than
 * asserted. Returns 0 when the fixture reached PLAYING, so the caller owns every
 * expectation and this function owns only the setup and teardown.
 *
 * available_level_count is seeded BEFORE the load because it models MaxLevels,
 * which the startup restore publishes (bounce_app_flow_restore_persisted) and
 * which a level load does not touch. level_id is NOT seeded: it is owned by the
 * loader, so the fixture loads the real level file with the matching id and lets
 * bounce_game_start_level() establish it. Seeding it and then loading would be
 * incoherent -- an earlier revision of this test seeded 11 and loaded level 001,
 * and the loader overwrote it straight back to 1.
 */
static int p2_run_consumer(
    struct p2_consumer_observation *out,
    const char *path,
    int level_id,
    unsigned int max_levels
)
{
    BounceApp app;

    memset(&app, 0, sizeof app);
    out->reached_playing = false;
    out->second_refused = false;
    out->complete_rc = -1;
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        return -1;
    app.flow.level_selection.available_level_count = max_levels;
    if (bounce_game_start_level(&app, path, level_id, 3) != 0) {
        bounce_game_release_level(&app);
        return -1;
    }
    out->reached_playing = app.state == BOUNCE_GAME_STATE_PLAYING
        && app.flow.state == BOUNCE_APP_STATE_GAMEPLAY
        && app.flow.level_id == level_id;
    out->level_before = app.flow.level_id;
    out->count_before = app.flow.level_selection.available_level_count;
    out->complete_rc = bounce_game_mark_level_complete(&app);
    out->level_after = app.flow.level_id;
    out->count_after = app.flow.level_selection.available_level_count;
    out->flow_after = app.flow.state;
    out->game_after = app.state;
    out->final_after = (int)bounce_app_flow_level_is_final(&app.flow);
    out->deferred_after = app.deferred_init;
    /*
     * The one-shot property, observed on the real consumer: a second call must be
     * refused because game->state has left PLAYING. This is what keeps the
     * progression from being applied twice for one completion.
     */
    out->second_refused = bounce_game_mark_level_complete(&app) != 0;
    bounce_game_release_level(&app);
    return 0;
}

static int verify_level_progression_boundary(void)
{
    static const struct {
        const char *label;
        int start_level;
        unsigned int start_count;
        int expect_level;
        unsigned int expect_count;
        int expect_final;
    } cases[] = {
        { "A  level 1",  1,  1u,  2,  2u, 0 },
        { "A' level 1 virgin", 1, 0u, 2, 2u, 0 },
        { "B  level 5",  5,  5u,  6,  6u, 0 },
        { "C  level 11", 11, 11u, 12, 11u, 1 },
    };
    /*
     * P2_CASE_COUNT is a plain enum rather than a sizeof expression so the
     * observed-value arrays below can be declared at a fixed size. The observed
     * numbers are kept so the summary line can report what actually happened
     * instead of restating the expectations: a summary that prints the expected
     * values unconditionally is a summary that lies on failure.
     */
    enum { P2_CASE_COUNT = 4, P2_CONSUMER_COUNT = 2 };
    int got_level[P2_CASE_COUNT];
    unsigned int got_count[P2_CASE_COUNT];
    /*
     * The two consumer cases. A non-final level must stop in LEVEL_COMPLETE with
     * the deferred latch ARMED, because that latch is what terminal Continue
     * consumes. The last level must instead route to GAME_END with the latch
     * CLEARED, which is how "level 12 is never initialised" is made structural
     * (game.c:1387-1396) rather than a property of the tick gate staying shut.
     */
    static const struct {
        const char *label;
        const char *path;
        int level_id;
        unsigned int max_levels;
        int expect_level;
        unsigned int expect_count;
        int expect_final;
        BounceAppState expect_flow;
        BounceGameState expect_game;
        bool expect_deferred;
    } consumers[] = {
        {
            "middle level 5",
            BOUNCE_RESOURCE_ROOT "/levels/J2MElvl.005",
            5, 5u, 6, 6u, 0,
            BOUNCE_APP_STATE_LEVEL_COMPLETE,
            BOUNCE_GAME_STATE_LEVEL_COMPLETE,
            true
        },
        {
            "final level 11",
            BOUNCE_RESOURCE_ROOT "/levels/J2MElvl.011",
            BOUNCE_APP_LAST_LEVEL_ID, BOUNCE_APP_LAST_LEVEL_ID,
            BOUNCE_APP_LAST_LEVEL_ID + 1, BOUNCE_APP_LAST_LEVEL_ID, 1,
            BOUNCE_APP_STATE_GAME_END,
            BOUNCE_GAME_STATE_GAME_END,
            false
        },
    };
    const size_t consumer_count = P2_CONSUMER_COUNT;
    bool ok = true;
    size_t i;

    /* ---- part one: the boundary arithmetic, over the table ---- */
    for (i = 0; i < P2_CASE_COUNT; ++i) {
        BounceAppFlow flow;
        bool case_ok;

        bounce_app_flow_init(&flow);
        flow.level_id = cases[i].start_level;
        flow.level_selection.available_level_count = cases[i].start_count;
        got_level[i] = 0;
        got_count[i] = 0u;
        if (bounce_app_flow_complete_level(&flow) == 0) {
            got_level[i] = flow.level_id;
            got_count[i] = flow.level_selection.available_level_count;
        }
        case_ok = got_level[i] == cases[i].expect_level
            && got_count[i] == cases[i].expect_count
            && (int)bounce_app_flow_level_is_final(&flow)
                == cases[i].expect_final;
        if (!case_ok) {
            fprintf(
                stderr,
                "P2FAIL boundary case %s: start(level=%d count=%u) -> "
                "level=%d count=%u final=%d, expected level=%d count=%u "
                "final=%d\n",
                cases[i].label,
                cases[i].start_level,
                cases[i].start_count,
                flow.level_id,
                flow.level_selection.available_level_count,
                (int)bounce_app_flow_level_is_final(&flow),
                cases[i].expect_level,
                cases[i].expect_count,
                cases[i].expect_final
            );
            ok = false;
        }
    }

    /* ---- part two: the real production consumer, from a PLAYING level ---- */
    for (i = 0; i < consumer_count; ++i) {
        struct p2_consumer_observation seen;
        bool case_ok;

        if (p2_run_consumer(&seen, consumers[i].path, consumers[i].level_id,
                consumers[i].max_levels) != 0) {
            fprintf(stderr, "P2FAIL consumer %s: could not run\n",
                consumers[i].label);
            return -1;
        }
        /*
         * The two expectations differ in the terminal state, and that difference
         * IS the e.java:320 branch: a non-final level stays in LEVEL_COMPLETE,
         * while the last level routes to GAME_END because
         * bounce_app_flow_level_is_final() is already true once level_id has
         * passed 11. Asserting LEVEL_COMPLETE for level 11 was wrong, and the
         * failure it produced is what identified the branch.
         */
        case_ok = seen.reached_playing
            && seen.complete_rc == 0
            && seen.level_before == consumers[i].level_id
            && seen.count_before == consumers[i].max_levels
            && seen.level_after == consumers[i].expect_level
            && seen.count_after == consumers[i].expect_count
            && seen.flow_after == consumers[i].expect_flow
            && seen.game_after == consumers[i].expect_game
            && seen.final_after == (int)consumers[i].expect_final
            && seen.deferred_after == consumers[i].expect_deferred
            && seen.second_refused;
        if (!case_ok) {
            fprintf(
                stderr,
                "P2FAIL consumer %s: start(level=%d count=%u) rc=%d -> "
                "level=%d count=%u final=%d flow=%d game=%d deferred=%d "
                "second_refused=%d playing=%d; expected level=%d count=%u "
                "final=%d flow=%d game=%d deferred=%d\n",
                consumers[i].label,
                seen.level_before,
                seen.count_before,
                seen.complete_rc,
                seen.level_after,
                seen.count_after,
                seen.final_after,
                (int)seen.flow_after,
                (int)seen.game_after,
                (int)seen.deferred_after,
                (int)seen.second_refused,
                (int)seen.reached_playing,
                consumers[i].expect_level,
                consumers[i].expect_count,
                (int)consumers[i].expect_final,
                (int)consumers[i].expect_flow,
                (int)consumers[i].expect_game,
                (int)consumers[i].expect_deferred
            );
            ok = false;
        }
    }

    printf(
        "P2-PROGRESSION boundary_cases=%d/%d level1=%d/%u virgin=%d/%u "
        "level5=%d/%u level11=%d/%u consumer_middle=%s consumer_final=%s "
        "one_shot=%s %s\n",
        ok ? P2_CASE_COUNT : 0,
        P2_CASE_COUNT,
        got_level[0], got_count[0],
        got_level[1], got_count[1],
        got_level[2], got_count[2],
        got_level[3], got_count[3],
        ok ? "verified" : "no",
        ok ? "verified" : "no",
        ok ? "verified" : "no",
        ok ? "PASS" : "FAIL"
    );
    return ok ? 0 : -1;
}

/*
 * STEP 46F -- X11 auto-repeat event-pair filter.
 *
 * WHY THIS EXISTS. The Java original receives exactly one keyPressed per
 * physical press, so the sequence GodMode watches (7 8 7 8 9 8) counts
 * presses, not auto-repeat. That is proven in STEP 46D from the target's own
 * platform API: libs/nokia_s40.jar declares keyPressed, keyReleased AND
 * keyRepeated as three separate callbacks, the application overrides only
 * keyPressed and keyReleased, so no auto-repeat can ever reach its detector.
 * STEP 46E resolved the resulting policy: AUTOREPEAT POLICY = IGNORE. This
 * step makes the X11 event stream compatible with it.
 *
 * THE MECHANISM IS THE X11 DEFAULT, DELIBERATELY. With auto-repeat in its
 * default (non-detectable) form the X server synthesises a KeyRelease for
 * every repeating KeyPress, per the X Keyboard Extension Protocol
 * Specification section 4.1.2 (X Consortium Standard):
 *
 *     without detectable autorepeat:  Press -> Release -> Press -> ...
 *     with    detectable autorepeat:  Press -> Press  -> Press  -> ...
 *
 * The synthetic release and the synthetic press that follows it share the
 * server-assigned identity of the repeat tick, so the pair is recognisable by
 * EXACT EQUALITY on keycode plus (serial or time). No threshold is involved.
 *
 * WHY DETECTABLE AUTOREPEAT IS NOT USED, AND MUST NOT BE. The specification
 * quote above is the whole reason: enabling it removes the intermediate
 * release entirely. The documented way to use it is then to "discard any
 * KeyPress without matching KeyRelease" -- that is inference from the ABSENCE
 * of a release, which would also collapse a legitimate rapid double-press.
 * Enabling it would therefore destroy the only exact discriminator available
 * and force a forbidden heuristic. XkbSetDetectableAutoRepeat() and
 * XkbGetDetectableAutoRepeat() are therefore NEVER CALLED, no XKB header is
 * included, and no linker flag changes. STEP 46C section 5.2 claimed
 * detectable autorepeat supplies timestamped release/press pairs; that is
 * wrong and is superseded here.
 *
 * The test is kept as a pure predicate over XEvent fields so it can be
 * verified without an X display or a synthetic key injection.
 */

/*
 * True when `candidate` is the synthetic KeyPress that belongs with the
 * KeyRelease identified by keycode/serial/time -- i.e. one auto-repeat tick.
 *
 * Pure: it reads only the passed-in event, so it needs no Display and no
 * queued events. Both identity tests are exact equality; neither is a
 * threshold and neither looks at elapsed time.
 */
static bool x11_key_event_is_repeat_partner(
    unsigned int keycode,
    unsigned long serial,
    unsigned long time,
    const XEvent *candidate)
{
    if (candidate == NULL || candidate->type != KeyPress)
        return false;
    if (candidate->xkey.keycode != keycode)
        return false;
    /*
     * X sources document both: the auto-repeat release and its press carry
     * the same serial, and equivalently the same timestamp. Either match is
     * accepted, so the filter does not depend on which field a given server
     * populates consistently.
     */
    return candidate->xany.serial == serial
        || candidate->xkey.time == time;
}

/*
 * Consume the auto-repeat pair beginning with `event`, which must be a
 * KeyRelease. Returns true when the release was synthetic and has been
 * discarded together with its paired press; false when the release must be
 * passed through to the existing input path untouched.
 *
 * The queue is only ever inspected with XPeekEvent and advanced by exactly one
 * XNextEvent, so no event is consumed twice and global ordering is unchanged.
 * When nothing is queued, or the next event is not a matching KeyPress, the
 * function does nothing and the caller forwards the release normally -- which
 * is what keeps a genuine physical release, and a rapid press/release/press
 * triple, on the existing path. No sleep, no timeout, no pending state.
 */
static bool x11_discard_autorepeat_pair(Display *display, const XEvent *event)
{
    XEvent next;

    if (display == NULL || event == NULL || event->type != KeyRelease)
        return false;
    if (XPending(display) <= 0)
        return false;
    XPeekEvent(display, &next);
    if (!x11_key_event_is_repeat_partner(
            event->xkey.keycode,
            event->xany.serial,
            event->xkey.time,
            &next))
        return false;
    /* Drop the paired synthetic press; the release is dropped by the caller. */
    (void)XNextEvent(display, &next);
    return true;
}

/*
 * STEP 46G -- the GodMode sequence detector, e.java:349-381.
 *
 * This is a transcription of the Java automaton, NOT a substring matcher and
 * NOT a debounced edge detector. The exact source, re-read for this step:
 *
 *   case 55:                                   e.java:349  '7'
 *       if (this.g == 0 || this.g == 2) { this.g++; break; }
 *       this.g = 0; break;
 *   case 56:                                   e.java:356  '8'
 *       if (this.g == 1 || this.g == 3) { this.g++; break; }
 *       if (this.g == 5) {
 *           this.soundUp.play(1);
 *           this.GodMode = true;
 *           this.g = 0; break;
 *       }
 *       this.g = 0; break;
 *   case 57:                                   e.java:369  '9'
 *       if (this.g == 4) { this.g++; break; }
 *       if (this.g == 5) {
 *           this.soundPop.play(1);
 *           this.af = true;
 *           this.g = 0; break;
 *       }
 *       this.g = 0; break;
 *
 * so the complete transition table, which is the ONLY table implemented:
 *
 *     g |  '7'  |  '8'                 |  '9'
 *     --+--------+----------------------+--------------
 *      0|   1    |  0                   |  0
 *      1|   0    |  2                   |  0
 *      2|   3    |  0                   |  0
 *      3|   0    |  4                   |  0
 *      4|   0    |  0                   |  5
 *      5|   0    |  GodMode=true, g -> 0|  g -> 0 (af NOT implemented)
 *
 * TWO POINTS THAT ARE EASY TO GET WRONG, AND ARE CORRECTED AGAINST THE SOURCE:
 *
 *  1. '7' at g in {1,3,4,5} RESETS TO 0. It does not fall back to 1. The
 *     accepting condition is exactly `g == 0 || g == 2` (e.java:350); every
 *     other value takes e.java:354. A version of this table that mapped '7' to
 *     1 from any other state would make 7 7 8 7 8 9 8 activate GodMode, which
 *     the source does not do.
 *  2. '9' at g == 5 sets the sibling `af` cheat in Java (e.java:376). `af` is
 *     deliberately NOT implemented in this step, but the accompanying
 *     `g = 0` at e.java:377 IS performed, so `g` continues to track the source
 *     exactly. Only the `af` write is absent.
 *
 * UNRELATED KEYS NEVER TOUCH g. Only cases 55/56/57 exist in that part of the
 * switch; `case 49`, `case 51`, `case 35`, `case -7`, `case -6` and the whole
 * `default:` arm leave it alone. There is therefore deliberately NO `else
 * g = 0;` for unrecognised input here -- that would contradict e.java.
 *
 * RETURNS true only on the e.java:361-364 completion, so the caller performs
 * the single one-way `GodMode = true` write. The latch is never cleared: Java
 * has no `GodMode = false` after the initialiser anywhere in the tree.
 */
/*
 * STEP 64-AF -- the out-parameter carries the e.java:376 `af` producer to the
 * caller, which owns the BounceApp. `af` is deliberately NOT a field of
 * X11PresentationContext: that would duplicate game state, and Java's af lives on
 * `e` beside GodMode. The return value keeps its established meaning exactly --
 * true only for the e.java:363 GodMode terminal -- so the existing 18/18
 * detector sweep keeps its established semantics.
 */
static bool x11_god_mode_sequence_step(
    X11PresentationContext *context,
    BounceInputSource source,
    bool *af_armed
)
{
    int g;

    if (context == NULL || af_armed == NULL)
        return false;

    *af_armed = false;

    /* e.java:349/356/369 are the only cases that write g. */
    if (source != BOUNCE_INPUT_SOURCE_NUM7
        && source != BOUNCE_INPUT_SOURCE_NUM8
        && source != BOUNCE_INPUT_SOURCE_NUM9)
        return false;

    g = context->god_mode_sequence;
    if (source == BOUNCE_INPUT_SOURCE_NUM7) {
        /* e.java:350-354 */
        if (g == 0 || g == 2)
            g++;
        else
            g = 0;
    } else if (source == BOUNCE_INPUT_SOURCE_NUM8) {
        /* e.java:357-367 */
        if (g == 1 || g == 3) {
            g++;
        } else if (g == 5) {
            g = 0;
            context->god_mode_sequence = g;
            return true;                    /* e.java:363 GodMode = true */
        } else {
            g = 0;
        }
    } else {
        /* e.java:370-380. STEP 64-AF adds the `g == 5` arm, which is the `af`
         * producer at e.java:376. Before this step that arm was absent and the
         * 7 8 7 8 9 9 sequence silently degraded to g = 0. */
        if (g == 4) {
            g++;
        } else if (g == 5) {
            /* e.java:375-378. The af write itself is transferred to the caller
             * through *af_armed, because this function owns the presentation
             * context and `af` is game state; it is the same transfer the
             * existing god_mode return value already performs. e.java:376
             * `this.soundPop.play(1)` is transferred with it, to the one
             * production call site that acts on this terminal (STEP 64-AF-SND),
             * for the same reason: the sound is an effect, and this function
             * owns none. It is emitted there, not here, so that this function
             * stays the pure state machine verify_god_mode_sequence_detector
             * drives directly. Both sound emissions that were recorded here as
             * having "no native counterpart" -- STEP 47 predates the audio
             * channel -- now exist, because audio_event.c and the sink exist. */
            g = 0;
            context->god_mode_sequence = g;
            *af_armed = true;
            return false;                   /* NOT the GodMode terminal */
        } else {
            g = 0;
        }
    }
    context->god_mode_sequence = g;
    return false;
}

/*
 * NATIVE ADDITION -- THE NUMERIC KEYPAD AS AN ALIAS FOR THE GodMode DIGITS.
 *
 * NOT A RECOVERY, and not a new cheat. The GodMode automaton at
 * x11_god_mode_sequence_step() above already exists and is already a
 * transcription of e.java:349-381; this does not add an arm, a column or a state
 * to it. What it does is arrange for a keypad press to ARRIVE at that function
 * carrying the digit value the top row would have carried.
 *
 * WHY IT LIVES HERE AND NOT IN x11_keysym_to_source(). Two hard constraints
 * point at this one call site:
 *
 *   1. XK_KP_8 is already BOUNCE_INPUT_SOURCE_KP_UP -- the T9 jump -- and
 *      KP_UP is ALSO produced by XK_KP_Up. Teaching the automaton that KP_UP
 *      means 8 would admit the NumLock-OFF navigation key into GodMode, which is
 *      precisely the convenience mapping that is ruled out.
 *   2. Introducing KP_NUM7/8/9 does not help either, because XK_KP_8 would then
 *      have to be repointed away from KP_UP, deleting the jump.
 *
 * So the alias is keyed off the KEYSYM, at the single production call site, and
 * the value it produces is passed to the detector and to nothing else.
 *
 * THE SCOPE, STATED AS WHAT IT IS NOT. bounce_input_apply_source() still receives
 * the ORIGINAL source a few lines below, so input.numeric[] is untouched and level
 * selection still consumes only the top row; and XK_KP_8 still yields KP_UP, so
 * the T9 jump is untouched. See reverse/KEYPAD-GODMODE-ALIAS-AUDIT.md.
 *
 * XK_KP_5 IS DELIBERATELY ABSENT. The recovered game has no FIRE: e.java:405 is
 * the af-gated level-skip latch, and the only other candidate, confirm_start, is a
 * MENU select rather than a game input. Nothing here invents one.
 */
static bool app_keypad_godmode_key(KeySym key)
{
    return key == XK_KP_7 || key == XK_KP_8 || key == XK_KP_9;
}

static BounceInputSource app_godmode_source(KeySym key, BounceInputSource source)
{
    switch (key) {
        case XK_KP_7:
            return BOUNCE_INPUT_SOURCE_NUM7;
        case XK_KP_8:
            return BOUNCE_INPUT_SOURCE_NUM8;
        case XK_KP_9:
            return BOUNCE_INPUT_SOURCE_NUM9;
        default:
            return source;
    }
}

/*
 * STEP 65-H -- app_request_w1_completion(), the producer seam for e.java:407.
 *
 *   e.java:405-408   case 8:
 *                        if (this.af)
 *                            this.e = true;
 *
 * This is the W1 half of Java's `e` latch: a request that the level be completed
 * at the end of the NEXT Tick. The whole operation is the single assignment
 * `this.e = true`; nothing else happens in the producer, and in particular no
 * completion work is started here. The consumer is the completion pipeline, and
 * it runs one gameplay tick later -- see the RESET-adjacent arm at the tail of
 * app_timer_callback_dispatch().
 *
 * IT IS DELIBERATELY UNARMED IN THIS STEP. The event that reaches e.java:405 is
 * getGameAction(keyCode) == 8, which is MIDP's Canvas.FIRE (constant recovered
 * from libs/nokia_s40.jar in STEP 65-C). The keyCode -> action mapping itself is
 * NOT source-determined: Canvas.getGameAction delegates to KeyMap.getGameAction,
 * which is abstract, and the only concrete implementation shipped in the SDK,
 * ITUKeyMap, builds its keyToGameActionMap from three ACC_NATIVE methods whose JNI
 * library is not present anywhere in the repository. STEP 65-D closed that search
 * as EXTERNAL-MAPPING-NOT-RECOVERED. Binding any X11 keysym here would therefore
 * be an invention, so this step ships the seam with no producer: the latch is
 * unreachable from the keyboard and the rest of the lifecycle is verifiable.
 *
 * WHERE THE CALL BELONGS WHEN THE MAPPING IS RECOVERED. It must be reached from
 * the key handler, inside the same gate the other e.java:339-348 consumers use:
 *
 *   pressed && recognized_input && app->flow.state == BOUNCE_APP_STATE_GAMEPLAY
 *
 * and it must additionally test `app->af`, exactly as e.java:406 does. Java's own
 * keyReleased switch (e.java:419-432) has no case 8, so there is nothing to clear
 * on release: the latch is consumed and cleared by the tick, not by the key.
 *
 * The function is file-local and takes no source or keysym argument precisely so
 * that no mapping can be smuggled in through its signature. It is not a general
 * input abstraction, it is one statement in a function that will be called from
 * exactly one place.
 */
static void app_request_w1_completion(BounceApp *app)
{
    if (app == NULL)
        return;
    app->completion_requested = true;
}

/*
 * D-21 -- THE ONE KEY THAT IS NOT THE SOURCE'S.
 *
 * The whole of Java's producer is
 *
 *     e.java:405-408   case 8:
 *                          if (this.af)
 *                              this.e = true;
 *
 * so arming the latch is gated on exactly two things: the key resolves to game
 * action 8, and `af` is set. The SECOND of those is fully recovered and is
 * reproduced here verbatim.
 *
 * THE FIRST IS NOT, and this is the whole reason the seam shipped unarmed.
 * Canvas.getGameAction delegates to KeyMap.getGameAction, which is abstract; the
 * only concrete implementation in the SDK, ITUKeyMap, builds its
 * keyToGameActionMap from three ACC_NATIVE methods whose JNI library is not
 * present anywhere in the repository. That search is recorded as
 * EXTERNAL-MAPPING-NOT-RECOVERED, and it is the same gap game.h:426-432 records
 * for this very latch and input_state.h:11-14 records for the development
 * aliases.
 *
 * Action 8 is Canvas.GAME_A. So XK_a would be the mnemonic guess, and XK_a is
 * ALREADY an alias for LEFT in x11_keysym_to_source(), which makes it unusable.
 * XK_c is used instead: it is unbound in the tree, it is unused by every native
 * feature rule 3 protects, and "complete" is what the key does.
 *
 * THIS IS A NATIVE BINDING, NOT A RECOVERY, and it is labelled as one here, in
 * the single place that decides it, so that changing it is a one-line edit in one
 * file rather than a hunt. It gates on app->af exactly as e.java:406 does, so
 * pressing it in a normal game does nothing at all -- the cheat is as inert as the
 * source's.
 *
 * IT IS A FUNCTION RATHER THAN AN INLINE `if` so a verifier can reach the
 * decision. When this was written, x11_process_events() could not be driven from
 * the check harness at all, so an inline comparison would have been untested by
 * omission -- the same trap the color-profile commit and the Continue entry both
 * hit and fixed the same way.
 *
 * V-1 CHANGED THE PREMISE, AND THIS PARAGRAPH WAS LEFT BEHIND. The loop body is
 * now x11_dispatch_event(), which the harness CAN drive with a stack context whose
 * `display` is NULL, and verify_x11_dispatch_event() drives this very predicate
 * through it: armed with `af`, not armed without it, and not armed in the wrong
 * flow state. Deleting the three-line conjunction at the call site now fails the
 * check. What remains unreachable is the QUEUE -- XPending, XNextEvent,
 * XPeekEvent, XSetInputFocus, XFlush and XLookupKeysym all need a server, and all
 * of them now live in x11_process_events(). The extraction was still right; the
 * reason it was needed is no longer the whole truth.
 */
static bool app_w1_completion_key(BounceApp *app, KeySym key)
{
    /* e.java:406 -- `if (this.af)`. Without af the key is inert. */
    if (app == NULL || !app->af)
        return false;
    /* The native binding for getGameAction(keyCode) == 8. See above. */
    return key == XK_c;
}

/*
 * D-02 -- THE hideNotify EDGE, AS A FUNCTION.
 *
 * Everything the long comment at the FocusOut branch in x11_process_events()
 * says applies here; this is the part that does the work, separated so that a
 * verifier can reach it. When this was written, x11_process_events() could not be
 * driven from the check harness at all, so an inline handler would have been
 * untested by omission -- the same trap the color-profile commit and the
 * e.java:407 producer both hit and fixed the same way.
 *
 * V-1: the FocusOut CALL SITE is now covered too, through x11_dispatch_event(),
 * which needs no X server. The queue above it still does.
 *
 * Returns 1 when this focus loss WAS the e.java:473-480 edge and has been applied,
 * 0 when it was not one, and -1 for a NULL app or a refused transition.
 *
 * "WAS NOT ONE" IS THE SOURCE'S OWN H. e.java:474 tests `if (this.H)`, and H
 * starts true (:61) and is cleared only by the two terminal transitions
 * (:323 before ShowLevelComplete, :433 inside TODO_ShowInstructions) -- that is,
 * exactly when the canvas has already left the display. So hideNotify acts only
 * on the gameplay-to-menu edge, and native reproduces that by requiring the
 * canonical gameplay state rather than by inventing a latch.
 */
static int app_apply_focus_lost(BounceApp *app)
{
    if (app == NULL)
        return -1;
    if (app->flow.state != BOUNCE_APP_STATE_GAMEPLAY
        || !app_canonical_gameplay_active(app))
        return 0;
    /*
     * `this.aq.a()` -- f.a() is `w &= 0xFFFFFFF0` (f.java:150-152), so this drops
     * every held-key bit. It is the same call the gameplay->menu Escape edge makes
     * for the other half of the same source statement.
     */
    bounce_input_reset(&app->input);
    /*
     * `this.game.ShowMainMenu()`. bounce_game_apply_event(BOUNCE_APP_EVENT_MENU)
     * is the same transition the Escape edge and every verified menu return use;
     * enter_menu() is what stops the timer and releases the level.
     *
     * NO STORE WRITE. hideNotify is not destroyApp: Bounce.java:25 -- the only
     * Record 3 writer -- is reached from commandAction's
     * `display.getCurrent() == this.c` branch (BounceGame.java:256-258), which
     * focus loss never is. That is the point D-14 turns on.
     */
    if (bounce_game_apply_event(app, BOUNCE_APP_EVENT_MENU) != 0)
        return -1;
    return 1;
}

/*
 * V-1 -- THE EVENT LOOP BODY, AS A FUNCTION OF ONE EVENT.
 *
 * WHY THE KEYSYM IS A PARAMETER AND NOT LOOKED UP HERE.
 *
 * The dispatcher's original shape, asked for by the task, was
 *
 *     static int x11_dispatch_event(BounceApp *app, XEvent *event)
 *
 * so a verifier could hand it a stack-built XEvent with no X server. That is not
 * possible, and the reason is one line of Xlib:
 *
 *     key = XLookupKeysym(&event->xkey, 0);
 *
 * XLookupKeysym reads the DISPLAY-GLOBAL keyboard mapping. Called with no
 * Display it does not return an error -- it dereferences NULL. Measured, not
 * assumed:
 *
 *     before XLookupKeysym
 *     Segmentation fault
 *
 * XNextEvent and XPending need a server for the obvious reason, and
 * x11_discard_autorepeat_pair() needs the queue only when the event is a
 * KeyRelease -- it returns at `event->type != KeyRelease` for a KeyPress. So
 * after the keysym is resolved the rest of the body touches no X server at all.
 *
 * The keysym is therefore resolved BY THE CALLER, in the one place that already
 * has a Display, and passed in. That is a boundary move, not a behaviour change:
 * the lookup still happens exactly once per key event, at the same point in the
 * sequence, before any use of `key`. What it buys is that everything after it --
 * including all three call sites that were previously unverifiable -- is now
 * reachable from a verifier.
 *
 * XEvent itself is still the parameter, because the MousePress branch and the
 * ClientMessage branch read xbutton/xclient fields, and the KeyPress branch
 * still needs event->type.
 */
static int x11_dispatch_event(
    X11PresentationContext *context,
    BounceApp *app,
    const XEvent *event,
    KeySym key
)
{
    if (context == NULL || app == NULL || event == NULL)
        return -1;
    {
        BounceInputSource source;
        bool pressed;
        bool recognized_input;
        /* STEP 12X-P4-B: sampled before the UI press; see the use below. */
        bool was_terminal_screen;
        /* TUGAS 2b: sampled before the UI press, to detect a theme change. */
        unsigned int theme_before;
        /* NATIVE ADDITION: the same sample for the keypad setting. */
        bool t9_before;
        /*
         * STEP CONTINUE-RETURN: sampled before the UI press, so the arrival at the main
         * menu can be told apart from a press made while already there. See the refresh
         * call on the far side of bounce_ui_shell_handle_press().
         */
        bool was_menu;

        /*
         * STEP 13G-X -- claim keyboard focus once the window is really viewable.
         *
         * A window manager is running on this display (_NET_SUPPORTING_WM_CHECK is
         * set, and the game's own 128x128 surface shows up reparented under the WM
         * frame). That makes XMapWindow() a MapRequest rather than a map, so the
         * window is NOT viewable when x11_create() returns.
         *
         * STEP 13G-W put XSetInputFocus() straight after XMapWindow()/XFlush() and it
         * failed at runtime with
         *
         *   X Error of failed request: BadMatch ... Major opcode 42 (X_SetInputFocus)
         *
         * because focusing a non-viewable window is a protocol error, and the default
         * error handler is installed (there is no XSetErrorHandler here), so the
         * process exited and the game never reached gameplay. That attempt was
         * reverted; b5355fd has no focus call at all.
         *
         * MapNotify is the correct point, and it costs nothing to reach: the event
         * mask selected at :9766-9770 already includes StructureNotifyMask and is
         * applied to this same context->window at :9771, so MapNotify is already
         * delivered to this loop and is simply not handled. By the time it arrives the
         * window is viewable, so the focus request is legal.
         *
         * The event->xmap.window test is explicit even though this client selects
         * events on exactly one window: it documents the intent and keeps the call
         * correct if a second window is ever added.
         *
         * RevertToPointerRoot is the conventional revert_to for a game window. If
         * focus is later lost, PointerRoot returns it to whatever window the pointer
         * is over, rather than None, which would strand the keyboard entirely.
         *
         * This only establishes focus. It does not touch the event mask, the
         * KeyPress/KeyRelease handling, the keysym mapping, the held-key state, or any
         * gameplay code, and it deliberately adds no XGrabKeyboard, no XGrabPointer,
         * no XSetErrorHandler and no XSync.
         */
        if (event->type == MapNotify && event->xmap.window == context->window) {
            XSetInputFocus(
                context->display,
                context->window,
                RevertToPointerRoot,
                CurrentTime
            );
            return 0;
        }
        /*
         * D-02 -- FOCUS LOSS IS MIDP'S hideNotify.
         *
         * JAVA EVIDENCE, e.java:473-480:
         *
         *     public void hideNotify() {
         *         if (this.H) {
         *             if (this.aq != null)
         *                 this.aq.a();
         *             this.game.ShowMainMenu();
         *         }
         *         this.H = true;
         *     }
         *
         * Two effects, and both are reproduced: `aq.a()` is f.a(), which is
         * `w &= 0xFFFFFFF0` (f.java:150-152), so every held-key bit is dropped;
         * and ShowMainMenu() is the main-menu List.
         *
         * WHY FocusOut IS THE RIGHT EVENT. MIDP calls hideNotify when the
         * Displayable stops being visible, which for a full-screen canvas is what
         * an incoming call or a task switch does. On X11 the window losing input
         * focus is the same situation from the game's point of view, and it is the
         * event that arrives: without a handler, the KeyRelease for a key held at
         * the moment focus is lost never reaches this window, so the held-key state
         * would persist across the interruption. That is the same latching the
         * XK_g / XK_l notes describe, reached here by the platform instead of by a
         * cheat key.
         *
         * THE GAMEPLAY GATE IS DELIBERATE, and it is the source's own H. Java
         * tests `if (this.H)`, and H starts true (e.java:61) and is cleared only
         * by the two terminal transitions (e.java:323 before ShowLevelComplete and
         * e.java:433 inside TODO_ShowInstructions) -- that is, when the canvas has
         * already left the display. So hideNotify does its work on exactly one
         * kind of edge: the gameplay canvas losing the display to the main menu,
         * which is the state this branch tests. Losing focus while the menu is
         * already up changes nothing, in Java and here.
         *
         * IT CLEARS THE INPUT AND LEAVES THE LEVEL, exactly as hideNotify does:
         * ShowMainMenu() in Java keeps `v` alive, while native's menu arrival
         * releases the level (see the note on the Escape edge for why the two
         * cannot be reconciled). The KEY MASK is the part that must match, and it
         * does -- bounce_input_reset() is f.a()'s native transcription, the same
         * call the gameplay->menu edge makes for the D-19 half of the same source
         * statement.
         *
         * NO WRITE TO THE STORE. hideNotify is not destroyApp. Bounce.java:25 --
         * the only Record 3 writer -- is reached from commandAction's
         * `display.getCurrent() == this.c` branch (BounceGame.java:256-258),
         * which focus loss never is. This is the same point D-14 turns on.
         */
        if (event->type == FocusOut
            && (event->xfocus.window == context->window
                || event->xfocus.mode == NotifyNonlinear)) {
            const int focused = app_apply_focus_lost(app);

            if (focused < 0) {
                context->failed = 1;
                return 0;
            }
            if (focused > 0)
                return 0;
        }
        if (event->type == KeyPress || event->type == KeyRelease) {
            /*
             * STEP 46F: the auto-repeat classification and the keysym lookup have
             * both moved to x11_process_events(), which is the only place that
             * holds a Display -- see the header comment for the measurement that
             * forced it. Nothing else below this line changed, and neither call
             * was reordered relative to anything that reads `key`.
             */
            pressed = event->type == KeyPress;
            recognized_input = x11_keysym_to_source(key, &source);
            /*
             * NATIVE ADDITION -- THE KEYPAD IS A CONTROL ONLY WHILE THE SETTING
             * IS ON.
             *
             * The keysym map above is a pure table and stays one: every keypad
             * keysym has a source whatever the setting says. The policy is here,
             * at the single point where a keypress becomes an action, so there is
             * exactly one place that can turn it off.
             *
             * WHY IT IS CONDITIONAL AT ALL. The keypad carries navigation keys as
             * well as digits -- with NumLock off its 2, 4, 6 and 8 ARE Down,
             * Left, Right and Up -- so a player who never asked for a keypad
             * controller would have their game played by a hand resting near it.
             * Default OFF is the value that changes nothing about how the shipped
             * keys behave.
             *
             * The key becomes UNRECOGNISED rather than being swallowed, which is
             * the same treatment every unmapped keysym already gets: it cannot
             * reach bounce_input_apply_source(), so it sets no held bit and cannot
             * leave the input mask stuck.
             */
            if (recognized_input
                && bounce_input_source_is_keypad(source)
                && !bounce_app_flow_settings_t9_enabled(&app->flow)) {
                recognized_input = false;
            }
            /*
             * STEP 46G: the GodMode detector, additive and non-consuming.
             *
             * Placement follows STEP 46D/46E: strictly after the STEP 46F
             * auto-repeat filter (so a held key contributes one event, never a
             * stream of them), strictly after the existing keysym mapping, and
             * strictly before bounce_input_apply_source. The event is NOT
             * consumed -- the call below still receives it unchanged.
             *
             * Only an ACCEPTED KeyPress reaches this: `pressed` excludes
             * KeyRelease, so e.keyReleased's lack of a detector (e.java:415-434)
             * is reproduced by construction, and held state is never consulted.
             *
             * GATING reproduces Java's Canvas routing. e.keyPressed only runs
             * while `e` is the current Displayable, which is exactly the
             * gameplay phase: the main menu, level selection, instructions,
             * high score, game end and level complete are all separate
             * Displayables that receive Command events instead
             * (BounceGame.java:132/145/164/173/195/211 vs :155). The splash is
             * excluded by the same BOUNCE_APP_STATE_GAMEPLAY gate.
             */
            /*
             * NATIVE ADDITION -- a keypad 7/8/9 enters this block even though it
             * has no BOUNCE_INPUT_SOURCE of its own, because XK_KP_7 and XK_KP_9
             * are unmapped and would otherwise be rejected by `recognized_input`
             * before the detector ever saw them.
             *
             * THAT IS NOT A NEW GATE. Java reads these three digits as RAW KEY
             * CODES in e.keyPressed (e.java:349/356/369 on cases 55/56/57), not
             * as game actions, so admitting them alongside `recognized_input` is
             * the same shape the source already has. The gameplay-state term is
             * untouched and still excludes every menu and sub-screen, exactly as
             * the comment above this block requires.
             *
             * XK_KP_8 was ALREADY recognised, as KP_UP, so its admission here
             * changes nothing about whether it enters -- only about which value
             * the detector receives.
             */
            if (pressed
                && (recognized_input || app_keypad_godmode_key(key))
                && app->flow.state == BOUNCE_APP_STATE_GAMEPLAY) {
                bool af_armed = false;

                if (x11_god_mode_sequence_step(
                        context,
                        app_godmode_source(key, source),
                        &af_armed)) {
                    /*
                     * STEP 46G-SND1 -- e.java:362, the GodMode terminal's sound.
                     *
                     *     if (this.g == 5) {
                     *         this.soundUp.play(1);          e.java:362
                     *         this.GodMode = true;            e.java:363
                     *         this.g = 0;                     e.java:364
                     *
                     * Java plays the sound and writes the latch as two statements
                     * of one arm, sound first, so that order is kept here.
                     *
                     * WHY THE CALL SITE AND NOT THE DETECTOR. The sound needs the
                     * audio channel, which is a process-global sink and not a property
                     * of the presentation context that owns `g`; bounce_audio_event_emit
                     * takes no app and no context, but it is a side effect on the audio
                     * subsystem and the detector deliberately owns no effects -- it hands
                     * the `g == 5` terminal back to this caller by its return value and
                     * hands back `af` by `*af_armed`. Emitting here keeps both terminal
                     * effects in one place and leaves the detector a pure state machine,
                     * which is also what its own verifier (verify_god_mode_sequence_detector)
                     * assumes: that verifier drives the step function directly with no sink
                     * installed and must keep asserting `g` progression only.
                     *
                     * EMISSION IS NOT AUDIBILITY. bounce_audio_event_emit is
                     * synchronous and delivers to the installed sink in program
                     * order; with no sink installed, as during `make check`, it is
                     * a no-op that returns 0. Nothing here claims a sound is heard
                     * on any host.
                     */
                    (void)bounce_audio_event_emit(BOUNCE_AUDIO_EVENT_UP);
                    app->god_mode = true;  /* e.java:363, one-way */
                }
                /*
                 * STEP 64-AF -- the e.java:376 `af` producer, transferred from
                 * the automaton to game state exactly as god_mode is. The
                 * 7 8 7 8 9 9 sequence ends here; the 7 8 7 8 9 8 sequence ends
                 * at the branch above. Neither arms the other.
                 */
                if (af_armed) {
                    /*
                     * STEP 64-AF-SND -- e.java:375, the `af` terminal's sound, the
                     * counterpart of STEP 46G-SND1 above and for the same reasons:
                     *
                     *         this.soundPop.play(1);         e.java:375
                     *         this.af = true;                e.java:376
                     *
                     * BOUNCE_AUDIO_EVENT_POP is sounds/pop.ott (audio_event.h:90),
                     * which is what e.java:70 binds soundPop to, and which
                     * app_kill_ball already emits for f.java:224. This is that same
                     * identity on the developer cheat's own path, not a new event.
                     */
                    (void)bounce_audio_event_emit(BOUNCE_AUDIO_EVENT_POP);
                    app->af = true;
                }
                /*
                 * STEP 64-AF -- e.java:383, `case 35` ('#', MIDP KEY_POUND):
                 *
                 *     case 35:
                 *         if (this.af)
                 *             this.aq.powerUpGravity = 300;
                 *
                 * It writes the existing player field; no new gravity variable
                 * and no new timer is introduced, and the tile 47-50 producer at
                 * :3189 is untouched. Gated on `af` alone, so when af is false
                 * this key has no effect here at all.
                 */
                if (app->af
                    && source == BOUNCE_INPUT_SOURCE_HASH)
                    app->player.powerUpGravity = 300;
                /*
                 * STEP 65-B -- the '1' and '3' consumers, e.java:339-348.
                 *
                 *     case 49:  this.d = true;                          e.java:340
                 *               if (this.af && --this.level < 1)         e.java:341
                 *                   this.level = 11;                    e.java:342
                 *     case 51:  this.d = true;                          e.java:345
                 *               if (this.af && ++this.level > 11)        e.java:346
                 *                   this.level = 1;                     e.java:347
                 *
                 * `d` has exactly one reader, e.java:222, which calls
                 * InitializeGame() and returns. So the observable effect of
                 * either key is not the arithmetic itself but the re-entry it
                 * schedules: the level is reloaded, the ball and runtime are
                 * rebuilt, and the camera is recalculated by e().
                 *
                 * The two consumers share this one site and this one request, and
                 * differ only in the level arithmetic, so they are handled by a
                 * single shared block rather than two duplicated ones.
                 *
                 * THE ORDER IS Java's, and STEP 65-B2 made it so. Java's key
                 * handler writes `d` and returns; the reload happens at the top of
                 * the NEXT Tick (e.java:222-226), where e.java:117 LoadLevelId runs
                 * first and e.java:132 e() -- the camera -- runs from inside a()
                 * at e.java:121, i.e. AFTER the level is in place. This block
                 * therefore performs no load and no camera update at all; it only
                 * records the request, and the tick performs the work.
                 *
                 * NOTHING ELSE IS TOUCHED. app->flow.state is not assigned, so
                 * the application never leaves GAMEPLAY, and app->state is not
                 * assigned either. No menu action, no flow transition, no new
                 * lifecycle abstraction, and no level-path mapping here: the
                 * path is resolved in the consuming arm, from the existing
                 * bounce_game_level_resource_path().
                 */
                if (app->af
                    && (source == BOUNCE_INPUT_SOURCE_NUM1
                        || source == BOUNCE_INPUT_SOURCE_NUM3)) {
                    /*
                     * STEP 65-B2 -- this block no longer reloads. It now only
                     * records the request, exactly as Java's key handler does:
                     * `this.d = true` at e.java:340 / :345 and a mutation of
                     * `this.level` in place at e.java:341 / :346. The re-entry
                     * itself belongs to the NEXT Tick, at e.java:222-226.
                     *
                     * STEP 65-B ran bounce_game_load_level() and
                     * app_update_camera() HERE, inside the input pump. That put
                     * the reload on the same frame as app_update_production_game
                     * at :20443, so the fresh level could be handed to
                     * app_player_physics_continuation immediately and the ball
                     * moved one 40 ms step before Java would have moved it.
                     * Java spends an entire tick on the reload and that tick
                     * returns before physics, so the work moved to the
                     * BOUNCE_TICK_DISPATCH_RESET_GATE arm of
                     * app_timer_callback_dispatch, one tick later.
                     *
                     * THE ARITHMETIC IS UNCHANGED and still applied to the
                     * current level, so a second press before the consuming tick
                     * accumulates exactly as Java's would.
                     */
                    if (source == BOUNCE_INPUT_SOURCE_NUM1) {
                        app->flow.level_id--;
                        if (app->flow.level_id < BOUNCE_APP_FIRST_LEVEL_ID)
                            app->flow.level_id = BOUNCE_APP_LAST_LEVEL_ID;
                    } else {
                        app->flow.level_id++;
                        if (app->flow.level_id > BOUNCE_APP_LAST_LEVEL_ID)
                            app->flow.level_id = BOUNCE_APP_FIRST_LEVEL_ID;
                    }
                    /*
                     * THE TARGET IS THIS EXISTING FIELD, not a new one. It is
                     * Java's `this.level`, and bounce_game_load_level() already
                     * treats flow.level_id as the current level (game.c:363), so
                     * mutating it here is the native form of e.java:341 / :346.
                     * The consuming arm reads the same field, which is why the
                     * request needs to carry no payload of its own.
                     */
                    app->af_reload_requested = true;
                }
            }
            /*
             * D-21 -- THE e.java:407 PRODUCER, AT LAST.
             *
             * Placed just after the e.java:339-348 consumer block and deliberately
             * outside its `recognized_input` gate: XK_c is not one of the
             * recognised game inputs, so requiring it would make the binding
             * unreachable. The gates that ARE the source's are reproduced --
             * pressed, gameplay state, and app->af inside the predicate.
             *
             * It sits before the bounce_input_apply_source() call below because it
             * must not be one of the inputs the player holds: e.java:405 is a
             * keyPressed case, so a latch armed by a key that is also a held
             * direction would be wrong, and this key is not bound to any source.
             */
            if (pressed
                && app->flow.state == BOUNCE_APP_STATE_GAMEPLAY
                && app_w1_completion_key(app, key))
                app_request_w1_completion(app);

            if (recognized_input)
                (void)bounce_input_apply_source(
                    &app->input,
                    source,
                    pressed
                );
            if (!pressed)
                return 0;

            /*
             * STEP 12X-G-P4 -- the Level Complete CONTINUE command, the ONLY
             * input accepted in that state.
             *
             * BounceGame.java:203-204 builds
             * `new Command(Translation.sprintf_translated(
             * Translation.CONTINUE), Command.OK, 1)` -- command type
             * Command.OK, priority 1 -- attaches it to the Level Complete form
             * at :209, and :263-266 handles it. That form has no other command:
             * commandBack and commandExit belong to the main menu (:113-114,
             * :120) and `this.i` is the game-over form's Command.OK (:180, :193).
             * So SELECT is the whole command surface, and it is produced by
             * three input sources that already exist --
             * CONFIRM_RETURN, CONFIRM_KP_ENTER and CONFIRM_SPACE at
             * app_ui_input_from_source() below. No new key mapping is
             * introduced.
             *
             * WHY THIS IS A SEPARATE BRANCH AND NOT A bounce_ui_shell_handle_press
             * CASE. That function only ever receives a BounceAppFlow*, so it
             * cannot perform the one game-layer action CONTINUE needs: dropping
             * the completed run's level and runtime, which
             * bounce_game_load_level_entry() refuses while a runtime copy is
             * installed (game.c:400). Adding BOUNCE_APP_STATE_LEVEL_COMPLETE to
             * the UI state lists as well would have widened the seam to the
             * digit-key path and to the mouse path for a screen that renders no
             * control at all: render_level_complete_state() draws five
             * rectangles and no text, so there is nothing to click and nothing
             * that needed hiding. The branch is placed before the generic UI
             * block and matches only SELECT, so UP, DOWN, the digit keys, BACK,
             * EXIT and the Escape branch below are all untouched.
             *
             * BACK and EXIT are deliberately NOT accepted here. Java's
             * commandAction at :256-262 routes commandBack, commandExit and the
             * game-over OK command to ShowMainMenu() when the main menu is
             * current, and to ShowMainMenu() otherwise -- but none of those
             * three commands is attached to the Level Complete form, so on that
             * screen Java offers no way back to the menu except continuing. The
             * native Escape mapping remains the only way out, and it is
             * unchanged by this step.
             */
            if (app->flow.state == BOUNCE_APP_STATE_LEVEL_COMPLETE
                && app_ui_input_from_source(source) == BOUNCE_UI_INPUT_SELECT) {
                /*
                 * A REFUSAL IS A NO-OP, NOT A FAILURE. Every -1 out of
                 * bounce_game_continue_level() means "this level cannot be
                 * continued right now" -- the state is not LEVEL_COMPLETE, the
                 * deferred latch is not armed, or flow->level_id has passed
                 * BOUNCE_APP_LAST_LEVEL_ID. None of those is an internal error,
                 * and there is nothing in commandAction (BounceGame.java:263-266)
                 * that could fail either, because a MIDP Command whose listener
                 * is attached always runs. So the press is consumed and ignored,
                 * which is also what keeps the XK_l level-complete test key at
                 * vertical_slice.c:15285 safe: that key reaches LEVEL_COMPLETE
                 * through BOUNCE_APP_EVENT_LEVEL_COMPLETE without passing through
                 * bounce_game_mark_level_complete(), so it never arms the latch,
                 * and treating the resulting refusal as fatal would close the
                 * window on a plain key press.
                 */
                (void)bounce_game_continue_level(app);
                return 0;
            }

            if (app->flow.state == BOUNCE_APP_STATE_SPLASH
                || app->flow.state == BOUNCE_APP_STATE_MENU
                || app->flow.state == BOUNCE_APP_STATE_ACTION_BOUNDARY
                || app->flow.state == BOUNCE_APP_STATE_INSTRUCTIONS
                || app->flow.state == BOUNCE_APP_STATE_HIGH_SCORE
                || app->flow.state == BOUNCE_APP_STATE_LEVEL_SELECTION
                /* NATIVE EXTENSION destinations take UI presses too. */
                || app->flow.state == BOUNCE_APP_STATE_SETTINGS
                || app->flow.state == BOUNCE_APP_STATE_ABOUT
                || app->flow.state == BOUNCE_APP_STATE_GAMEPLAY_ENTRY
                /* STEP 12X-P4-B: the terminal destination takes UI presses, which
                 * is what makes the OK/back route in bounce_ui_shell_handle_press
                 * reachable. The Step 12X-G-P4 CONTINUE seam is a separate narrow
                 * branch above this list and is not affected. */
                || app->flow.state == BOUNCE_APP_STATE_GAME_END) {
                BounceUiInput ui_input;

                if (!recognized_input)
                    return 0;

                /*
                 * NATIVE EXTENSION: digit keys. They are already received as
                 * BOUNCE_INPUT_SOURCE_NUM0..NUM9; only their UI meaning is new.
                 * A digit that is meaningful is consumed here and never reaches
                 * the ordinary press handler, so one keystroke can never produce
                 * both a numeric selection and a menu action.
                 */
                if (source >= BOUNCE_INPUT_SOURCE_NUM0
                    && source <= BOUNCE_INPUT_SOURCE_NUM9) {
                    unsigned int digit = (unsigned int)(
                        source - BOUNCE_INPUT_SOURCE_NUM0);

                    if (bounce_ui_shell_handle_number(&app->flow, digit) == 1
                        && bounce_game_sync_ui_state(app) != 0) {
                        context->failed = 1;
                    }
                    return 0;
                }

                ui_input = app_ui_input_from_source(source);
                /*
                 * STEP 12X-P4-B, EXTENDED TO GAME_OVER -- sample BOTH terminal
                 * states before the press, for the same reason the Escape edge
                 * samples app_canonical_gameplay_active() and the terminal states
                 * before it applies BOUNCE_APP_EVENT_MENU.
                 *
                 * WHY GAME_OVER IS HERE AND WAS NOT. TODO_ShowInstructions
                 * (BounceGame.java:430-435) is the single producer of BOTH terminal
                 * forms -- it is called with won == false from the death arm
                 * (e.java:271) and with won == true from the win arm (e.java:321) --
                 * and it sets K = 3 and J = 0 before calling either ShowGameEnd or
                 * the congrats variant. So both forms leave Continue invalid, and
                 * the two states are reached from the same Java method by the same
                 * UI gesture: the form's own OK command. Handling only GAME_END
                 * therefore left the death form's OK press on a different path from
                 * the win form's, for no reason in the source.
                 *
                 * The consequence of the omission was the stale-Continue class the
                 * Escape edge already documents and fixes at length: dying leaves
                 * the store holding the previous in-level b1 = 1, so neither the
                 * capture that would overwrite it with b1 = 0 nor the availability
                 * refresh ran on this route, and the main menu rendered a Continue
                 * row at index 0 and preselected it -- offering to resume a run that
                 * had just ended.
                 */
                was_terminal_screen
                    = app->flow.state == BOUNCE_APP_STATE_GAME_END
                    || app->flow.state == BOUNCE_APP_STATE_GAME_OVER;

                /*
                 * TUGAS 2b -- the applied color profile, sampled BEFORE the press
                 * so the change can be detected without this event loop knowing
                 * anything about Settings pages.
                 *
                 * The write belongs here rather than inside
                 * bounce_app_flow_settings_select(), because selecting a profile
                 * is a pure state change and app_flow.c does no I/O anywhere --
                 * persistence belongs to the layer that already owns it, which is
                 * this file (app_persist_records() is the existing precedent).
                 */
                theme_before = bounce_app_flow_settings_applied_theme_index(
                    &app->flow);
                /*
                 * NATIVE ADDITION -- and the keypad setting, sampled at the same
                 * point for the same reason: so that only a real change commits,
                 * and arrow presses that merely move the highlight write nothing.
                 */
                t9_before = bounce_app_flow_settings_t9_enabled(&app->flow);
                /*
                 * STEP CONTINUE-RETURN -- AND THE MAIN MENU ARRIVAL IS SAMPLED TOO.
                 * bounce_app_flow_enter_menu() resets the menu, so this flag has to be
                 * re-derived on every arrival rather than only the two that already were.
                 */
                was_menu = app->flow.state == BOUNCE_APP_STATE_MENU;

                if (bounce_ui_shell_handle_press(
                        &app->flow,
                        ui_input
                    ) != 0
                    || bounce_game_sync_ui_state(app) != 0) {
                    context->failed = 1;
                    return 0;
                }

                /*
                 * TUGAS 2b -- commit the choice the moment it is made, which is
                 * what makes a crash, a kill -9 or a closed terminal unable to
                 * lose it. See app_commit_theme_change() for the Java lines and
                 * for why this is a function.
                 */
                app_commit_theme_change(app, theme_before);
                /*
                 * NATIVE ADDITION -- and so is the keypad setting, committed on
                 * the same edge for the same reason.
                 */
                app_commit_t9_change(app, t9_before);
                /*
                 * STEP CONTINUE-RETURN -- RE-DERIVE CONTINUE ON EVERY ARRIVAL AT THE
                 * MAIN MENU. THIS IS THE FIX.
                 *
                 * THE BUG, AS REPORTED: play a level, press Escape back to the menu
                 * (Continue is live and selected), walk into Settings or High Score or
                 * Instructions, come back -- and Continue is GREYED OUT even though the
                 * snapshot is still in the store with b1 == 1. The only way to get it
                 * back was to play again.
                 *
                 * WHY. app_refresh_continue_availability() was wired to exactly two
                 * arrivals: the splash -> menu transition, and the Escape edge out of
                 * canonical gameplay. Every OTHER route into the main menu -- BACK out of
                 * Settings, out of High Score, out of Instructions, out of About, out of
                 * Level Select -- went through bounce_app_flow_enter_menu(), which calls
                 * bounce_app_flow_reset_menu(), which sets continue_available back to
                 * false and enabled_item_count back to six. Nothing re-read the store, so
                 * a save that was sitting there the whole time stopped being offered.
                 *
                 * The flag was not stale because anything had written to the store. It
                 * was stale because the only thing that could refresh it was never
                 * called on this path. Nothing here is repaired after the fact: the row
                 * was absent, not wrong.
                 *
                 * The Reset to Default row made this much more visible rather than
                 * causing it. A reset deletes Record 3, so it is SUPPOSED to leave
                 * Continue greyed; the surrounding menu behaviour had always been wrong
                 * in a way nobody had a live save on hand to notice.
                 *
                 * WHY IT IS HERE AND NOT IN THE FLOW. app_flow.c performs no I/O
                 * anywhere, so it cannot read the store to re-derive the fact, and the
                 * shell cannot either -- it only ever has the flow. This is the same
                 * reasoning as app_commit_theme_change() and app_commit_t9_change() on
                 * this edge: a change the player just caused, committed at the edge, by
                 * the layer that owns the store.
                 *
                 * WHY THE ARRIVAL IS SAMPLED RATHER THAN EVERY PRESS. The condition is
                 * "the flow was somewhere else and is now at the menu", so a press made
                 * while already in the menu cannot re-read the store. That matters: a
                 * refresh on every menu press would perform a file read on ordinary
                 * navigation, which is the exact defect app_commit_theme_change() exists
                 * to avoid, and it would let the row flicker as the player walked past
                 * it.
                 *
                 * Java's shape, for comparison: ShowMainMenu() is called on every
                 * arrival and reads K and J itself, so the source has no distinction
                 * between the two arrivals at all. Native has to re-derive explicitly,
                 * and the rule "derive once per arrival" is what makes them agree.
                 */
                if (!was_menu && app->flow.state == BOUNCE_APP_STATE_MENU)
                    app_refresh_continue_availability(app);
                /*
                 * STEP 38-RESET -- and carry out a confirmed reset, if this press was
                 * one. The flag is read through the consume accessor, so it clears as
                 * it is read and the deletions in app_apply_reset_to_default() cannot
                 * run twice from one press.
                 *
                 * It sits with the two commit helpers rather than beside the menu
                 * handoff below because it is the same kind of edge: a change the
                 * player just confirmed, committed at the moment it was confirmed so
                 * a crash cannot lose it. Those two are guarded by a compare-before-
                 * write because ordinary navigation must not perform I/O at all; this
                 * one is not guarded, because arriving here with the flag set means a
                 * destructive action was deliberately confirmed and doing nothing
                 * would be the bug.
                 */
                if (bounce_app_flow_consume_reset_to_default(&app->flow))
                    app_apply_reset_to_default(app);
                /*
                 * STEP G-R3-R2 -- THE MENU-TO-RESUME HANDOFF.
                 *
                 * bounce_ui_shell_handle_press() already ran, so
                 * bounce_app_flow_menu_select() has mapped the Continue row to
                 * BOUNCE_MENU_ACTION_CONTINUE and, per the branch added at
                 * app_flow.c, deliberately left the flow in MENU. This is where
                 * the shell supplies the two values the flow does not hold -- the
                 * decoded record's level and lives -- and starts the R1 entry.
                 *
                 * It ONLY initiates. The flow goes to ACTION_BOUNDARY here, and
                 * the canonical chain and the R1 restore window do everything
                 * else on the next production update, exactly as they do for every
                 * other entry. Nothing here loads a level, creates a player, starts
                 * a timer or touches gameplay state.
                 *
                 * A refusal is a no-op, not a failure. The row can only offer
                 * CONTINUE when a b1 == 1 record backs it, so a refusal here means
                 * the store changed underneath us -- which is the same situation
                 * as Java's commandAction falling through to ShowMainMenu()
                 * (BounceGame.java:222-235) when J == 0. bounce_game_continue_level()
                 * is deliberately NOT involved: that is the level-complete
                 * Continue, a different Java method with different semantics.
                 */
                if (app_begin_resume_from_menu(app) == 0)
                    return 0;
                /*
                 * STEP 12X-P4-B -- leaving the terminal state must release the
                 * finished run, and this is the only place that can do it.
                 *
                 * WHY IT IS NEEDED. BOUNCE_APP_STATE_GAME_END is the only
                 * UI-reachable state that still OWNS a level: bounce_app_flow_apply
                 * (BOUNCE_APP_EVENT_MENU) is a flow-only transition, so the run's
                 * level and runtime survive it. Nothing else here releases them.
                 * The Escape edge already handles this for the other terminal
                 * states, but the terminal screen's own exit is a SELECT/BACK/EXIT
                 * press handled by bounce_ui_shell_handle_press, which only ever
                 * receives a BounceAppFlow* and cannot touch the game's resources.
                 *
                 * Without this, the menu would be entered still holding the
                 * completed level's runtime, and the next New Game ->
                 * bounce_game_load_level_entry() would hit its `game->runtime !=
                 * NULL` ownership guard (game.c:400), return -1, and be turned
                 * into x11_context.failed = 1 by the frame loop at
                 * vertical_slice.c:15904. That is the Step 12X-G-R3 crash class,
                 * reached through a new edge.
                 *
                 * app_end_canonical_gameplay() is the SINGLE existing release
                 * mechanism -- the same one the Escape edge and the Step 12X-G-P3
                 * deferred branch use -- and it is NULL-safe, so calling it when
                 * nothing is owned is a no-op rather than a double release. It
                 * also re-inits the timer, which is what BounceGame.ShowMainMenu's
                 * own v.StopGameTimer() (BounceGame.java:131) achieves.
                 *
                 * The guard requires the flow to have actually reached the menu,
                 * so a press that does not leave the terminal state releases
                 * nothing, matching the Escape edge.
                 */
                if (was_terminal_screen && app->flow.state == BOUNCE_APP_STATE_MENU) {
                    /*
                     * STEP G-R3-R2 -- second production menu arrival: the terminal
                     * form's OK command (ui_shell.c:1319 -> EVENT_MENU). Placed
                     * inside the same guard that already releases the finished run,
                     * so it cannot fire for a press that did not reach the menu.
                     *
                     * BOTH terminal states are covered, and app_capture_resume_snapshot()
                     * maps each of them to b1 == 0 on its own, so the state is not
                     * named here -- see the K = 3 reasoning in that function. Only
                     * GAME_END was listed here before; see the sampling comment above
                     * for why GAME_OVER belongs on this edge too. Concretely, that
                     * omission left the death form's OK press unable to invalidate
                     * Continue, so the store kept the previous in-level b1 == 1 and
                     * the main menu offered to resume a run that had just ended --
                     * the same stale-Continue class the Escape edge already fixes.
                     *
                     * ORDER IS NOW LOAD-BEARING, exactly as on the Escape edge: the
                     * capture WRITES b1 == 0, and the refresh READS the store to
                     * decide whether Continue is offered. Refreshing first would
                     * re-derive availability from the stale record and then leave it
                     * stale, because nothing re-derives it again until the next menu
                     * arrival. Before, the two calls were in the other order and the
                     * single state that reached here happened to refresh correctly
                     * only because GAME_END's record was already inert.
                     */
                    app_capture_resume_snapshot(app, app->flow.state);
                    /*
                     * THE WRITE THAT WAS MISSING -- see
                     * app_persist_resume_snapshot_for_continue() below. Without it
                     * the capture never reached the store, the refresh re-read the
                     * PREVIOUS session's b1 == 1, and a finished run kept offering a
                     * Continue that resumed a level the player had already left.
                     */
                    app_persist_resume_snapshot_for_continue(app);
                    app_refresh_continue_availability(app);
                    /*
                     * STEP G-R3-T2 -- capture before the release. This is the
                     * game-end half of the same edge as the Escape arm below,
                     * and it must run first: app_end_canonical_gameplay() is
                     * what destroys the level, runtime and player.
                     *
                     * BOUNCE_APP_STATE_GAME_END is Java's ShowGameEnd
                     * (BounceGame.java:177-197). ShowGameEnd itself assigns
                     * nothing to K -- but the K that matters was already changed
                     * by its only caller. TODO_ShowInstructions
                     * (BounceGame.java:430-434) sets this.K = 3 and this.J = 0
                     * and then calls ShowGameEnd at :434, and
                     * TODO_ShowInstructions is the ONLY caller of ShowGameEnd in
                     * the tree.
                     *
                     * STEP DV2 CORRECTION. This comment previously claimed "the K
                     * assignments are :156, :202, :234, :241 and :264 only", and
                     * concluded b1 = 1 because K would still hold the value the
                     * gameplay start set. That enumeration was INCOMPLETE: it
                     * omitted :431, which is the K = 3 inside
                     * TODO_ShowInstructions -- the very assignment that invokes
                     * ShowGameEnd. On that reading the premise was false.
                     *
                     * A WIN IS NOT THE ShowLevelComplete PATH. e.java:313-327
                     * completes a level, calls the no-argument WriteToStore()
                     * (records 1 and 2 only) and then branches on level > 11: the
                     * win case at :321 calls TODO_ShowInstructions(true), and only
                     * the non-final case at :324 calls ShowLevelComplete, which is
                     * the sole K = 5 setter. So K is never 5 at a win; it is 3.
                     *
                     * THE CORRECT CONCLUSION. K == 3 is neither K == 1 nor K == 5,
                     * so WriteToStore(3) (BounceGame.java:355-358) writes b1 = 0:
                     * GAME_END produces an INERT record, exactly like GAME_OVER.
                     * It does NOT preserve K = 5. The mapping itself lives with the
                     * capture in app_capture_resume_snapshot(), which is why the
                     * capture above is now passed the live state and not a literal.
                     */
                    app_end_canonical_gameplay(app);
                }
                if (app->flow.menu.pending_action == BOUNCE_MENU_ACTION_EXIT) {
                    /*
                     * STEP G-R3-T2 -- THE ONE PRODUCTION RECORD 3 WRITER.
                     *
                     * This is the explicit main-menu Exit: ui_shell.c:1482-1483
                     * set pending_action only from the MENU arm of
                     * bounce_ui_shell_handle_press, whose switch has no BOUNCE_UI_INPUT_BACK
                     * case, and BounceGame.java:120 confirms the original
                     * attaches only commandExit to the main menu (commandBack is
                     * constructed at :113 and never added). So this edge is
                     * Java's BounceGame.java:256-259 -- `if the main menu is
                     * current, destroyApp(true)` -- and destroyApp is the only
                     * path that calls WriteToStore(3) (Bounce.java:25).
                     *
                     * The flow-state test is what keeps the boundary narrow, and
                     * it guards ONLY the write, never the termination:
                     *
                     *   menu -> nothing else   BOUNCE_UI_INPUT_EXIT from INSTRUCTIONS
                     *                          also sets pending_action (ui_shell.c:1274)
                     *                          and must keep terminating as before;
                     *   gameplay -> menu       sets no pending_action at all, so it
                     *                          cannot reach here -- it only captures,
                     *                          and a capture performs no I/O;
                     *   splash -> menu         same, and writes the inert b1 == 0
                     *                          record that represents "never played".
                     *
                     * Nothing else is hooked: not process exit, not the XK_q
                     * shortcut at the branch below, not level completion and not
                     * game over. Java's destroyApp is reachable only from the menu
                     * command, so a path that is not the menu command is not
                     * destroyApp.
                     */
                    if (app->flow.state == BOUNCE_APP_STATE_MENU)
                        app_write_resume_snapshot(app);
                    /*
                     * TUGAS 2b -- the color profile is committed on the same edge.
                     *
                     * This edge is Java's destroyApp (BounceGame.java:256-259 ->
                     * Bounce.destroyApp at Bounce.java:25), which is where the
                     * source's WriteToStore calls live, so it is the one place a
                     * last commit cannot be skipped. The theme is also written when
                     * it changes, so this is a second attempt rather than the only
                     * one -- it costs one small write on a path that is already
                     * writing, and it covers the case where the change-time write
                     * failed.
                     */
                    app_persist_theme(app);
                    /*
                     * NATIVE ADDITION -- and so is the keypad setting, for the
                     * reason the theme is written here: this edge is
                     * destroyApp, so it is the last place a commit cannot be
                     * skipped.
                     */
                    app_persist_t9_setting(app);
                    context->running = 0;
                }
                return 0;
            } else if (key == XK_q || key == XK_Q) {
                /*
                 * TUGAS 2b -- and so is the QUIT SHORTCUT.
                 *
                 * XK_q has no Java counterpart -- it is a native desktop
                 * affordance, like the Escape mapping documented below it -- and
                 * it terminates without running any of the teardown the Exit menu
                 * row gets. Without this the profile would survive only if its
                 * change-time write had already succeeded, which would make a
                 * forced quit the one route able to lose it.
                 */
                app_persist_theme(app);
                /* NATIVE ADDITION -- the keypad setting rides the same route. */
                app_persist_t9_setting(app);
                context->running = 0;
            } else if (key == XK_Escape) {
                bool was_canonical_gameplay;
                bool was_terminal_gameplay;
                /*
                 * STEP G-R3-T2 -- the flow state this edge is leaving, sampled
                 * at the same point as the two existing pre-change samples
                 * below, i.e. before bounce_game_apply_event(BOUNCE_APP_EVENT_MENU)
                 * rewrites it. The capture needs it because b1 is Java's K, and
                 * K == 5 only on the level-complete screen (BounceGame.java:202).
                 */
                const BounceAppState menu_from_state = app->flow.state;

                /*
                 * TEMPORARY NATIVE APP BEHAVIOR: the recovered source uses
                 * game keys for its back/menu path; X11 Escape is only a
                 * native test mapping here.
                 */
                was_canonical_gameplay = app_canonical_gameplay_active(app);
                /*
                 * STEP 12X-G-R4 -- SESSION END, SAMPLED BEFORE THE STATE CHANGE.
                 *
                 * app_canonical_gameplay_active() is false once the flow has
                 * left BOUNCE_APP_STATE_GAMEPLAY, which is exactly what happens
                 * on the two terminal exits. e.java:272 returns from Tick() on
                 * game over and e.java:313-327 runs the completion block, so in
                 * both cases the gameplay session is OVER while
                 * app_canonical_gameplay_active() already reports false. The
                 * release below was therefore skipped, and Step 12X-G-R3 proved
                 * the consequence: app->runtime stayed SET, the staged New Game
                 * path reached bounce_game_load_level_entry(), whose
                 * `if (game->runtime != NULL) return -1;` ownership guard then
                 * refused, and the frame loop turned that -1 into
                 * x11_context.failed = 1 and EXIT_FAILURE.
                 *
                 * That guard is correct and is NOT changed: a runtime tile copy
                 * means a gameplay-shaped level is already installed, and
                 * replacing only the level would split ownership. The fault was
                 * purely that the finished session still owned the resources.
                 *
                 * Sampling the pre-change flow state is what keeps this narrow.
                 * Only the two states in which the session has ENDED are added.
                 * BOUNCE_APP_STATE_PAUSE is deliberately NOT added: pausing
                 * suspends a session rather than ending it, so its stale-runtime
                 * case is a separate gap, documented and not fixed here. Every
                 * other destination (SPLASH, the UI states, GAMEPLAY_ENTRY)
                 * owns no loaded level, so nothing else changes.
                 */
                was_terminal_gameplay =
                    app->flow.state == BOUNCE_APP_STATE_LEVEL_COMPLETE
                    || app->flow.state == BOUNCE_APP_STATE_GAME_OVER;
                if (app->state != BOUNCE_GAME_STATE_MENU)
                    (void)bounce_game_apply_event(
                        app,
                        BOUNCE_APP_EVENT_MENU
                    );
                /*
                 * STEP G-R3-R2 -- third production menu arrival: the Escape edge.
                 * escape -> menu, and the level-complete terminal states that the
                 * Escape key also serves, all land here.
                 *
                 * STEP 12X-I-REGRESSION-B-FIX: the
                 * app_refresh_continue_availability() call that used to sit here
                 * now sits immediately AFTER app_capture_resume_snapshot() below,
                 * inside the was_canonical_gameplay / was_terminal_gameplay block.
                 * Nothing was removed from this handler and no behaviour other than
                 * the freshness of the store read changed; the note at the new call
                 * site states why the order is load-bearing.
                 */
                /*
                 * Production gameplay ownership: leaving canonical gameplay
                 * releases the staged level/runtime and stops the canonical
                 * timer, so no further canonical tick can run and a later start
                 * begins from fresh state. Sampled before the state change, so
                 * the legacy diagnostic modes, which never start the canonical
                 * timer, keep exactly the previous Escape behavior.
                 *
                 * STEP 12X-G-R4 extends the release to the two terminal exits,
                 * which end a session that still owns its level. The existing
                 * app_end_canonical_gameplay() is reused unchanged: it is the
                 * single place that destroys the runtime, the level, the level
                 * path, the player and the spawn, and it clears level_complete,
                 * game_over, lives and hoops_scored. It is NULL-safe at every
                 * step, so calling it when nothing is loaded is a no-op rather
                 * than an error or a double free.
                 *
                 * The timer work it performs is also a no-op from a terminal
                 * state: bounce_game_timer_init() memsets a timer whose
                 * started flag 12X-G-R2 already cleared at the tick tail, and
                 * canonical_next_tick_ms is already elapsed. The deferred
                 * timer-stop itself is untouched.
                 */
                if (was_canonical_gameplay || was_terminal_gameplay) {
                    /*
                     * STEP G-R3-T2 -- capture before the release. This is the
                     * only other edge on which a live session is destroyed, and
                     * the capture must precede app_end_canonical_gameplay() or
                     * there is nothing left to read. It performs no I/O, so the
                     * gameplay-to-menu transition still does not touch the store.
                     */
                    app_capture_resume_snapshot(app, menu_from_state);
                    /*
                     * THE WRITE THAT WAS MISSING -- see
                     * app_persist_resume_snapshot_for_continue() below. This is the
                     * edge that leaves a LIVE session for the menu, so it is also
                     * the edge that must keep the stored snapshot fresh while the
                     * player still has lives.
                     */
                    app_persist_resume_snapshot_for_continue(app);
                    /*
                     * D-19 -- THE GAMEPLAY -> MENU HALF OF THE CLEAR.
                     *
                     * JAVA EVIDENCE, the second of the tree's only two `aq.a()` sites,
                     * e.java:473-480:
                     *
                     *     public void hideNotify() {
                     *         if (this.H) {
                     *             if (this.aq != null)
                     *                 this.aq.a();
                     *             this.game.ShowMainMenu();
                     *         }
                     *         this.H = true;
                     *     }
                     *
                     * `this.H` starts true (e.java:61) and is set false only by the two
                     * deliberate terminal transitions -- e.java:323 before ShowLevelComplete
                     * and e.java:433 inside TODO_ShowInstructions -- so hideNotify does its
                     * work on exactly one kind of edge: the gameplay canvas losing the display
                     * to the main menu. That is the edge this block is on, so H is true here
                     * and the clear belongs here.
                     *
                     * `f.a()` is `w &= 0xFFFFFFF0` (f.java:150-152).
                     *
                     * ONLY was_canonical_gameplay IS COVERED, and that is the Java rule rather
                     * than a simplification. The two terminal states share this block only for
                     * the level-release reason spelled out above; in Java the canvas is already
                     * off the display when the level-complete and game-end forms are up, so
                     * hideNotify did not fire on their way back to the menu, and their
                     * `H == false` guard would have suppressed it in any case (e.java:323,
                     * :433). Nothing extra is read to decide this: the two cases are already
                     * distinguished by the existing `was_canonical_gameplay` sample.
                     *
                     * WHY IT MATTERS HERE AND NOT AT ENTRY ALONE. The clear at
                     * BounceGame.java:154 (reproduced in app_begin_canonical_gameplay) covers
                     * the four a(boolean,int) routes but NOT the J != 0 resume route, which is
                     * deliberately exempt there. Clearing on the way out is what makes that
                     * exemption safe: by the time a resume can be selected, the session that
                     * could have left a key latched has already been through this edge.
                     *
                     * It is placed after the capture because the capture reads live session
                     * state and the release below destroys it. The mask is not part of that
                     * snapshot -- Record 3 carries no field for it (BounceGame.java:360-379
                     * writes none, and f.w is not among the values restored at e.java:105-110)
                     * -- so the order relative to the capture is not load-bearing.
                     */
                    if (was_canonical_gameplay)
                        bounce_input_reset(&app->input);
                    /*
                     * STEP 12X-I-REGRESSION-B-FIX -- Continue availability is
                     * refreshed AFTER this capture, not before it. This is the
                     * whole fix: one existing call relocated one statement down.
                     *
                     * THE BUG. app_refresh_continue_availability() re-reads the
                     * resume record from the store and derives
                     * continue_available from `present && b1 == B1_IN_LEVEL`. On
                     * the GAME_OVER arrival it used to run while the store still
                     * held the previous in-level b1 = 1, so the flag became true.
                     * The capture immediately above then wrote b1 = B1_NONE for the
                     * same transition (:7550-7552), but nothing re-derived the flag
                     * from it. Because the only other refresher -- app_update_ui()'s
                     * :5066 call -- runs solely on the SPLASH -> MENU transition,
                     * the stale true survived for the rest of the session, and
                     * app_flow.c's enabled_item_count / selected_index consumers
                     * rendered a Continue row at index 0 and preselected it.
                     *
                     * THE JAVA CONTRACT THIS RESTORES. Java invalidates Continue
                     * AT the transition: BounceGame.TODO_ShowInstructions(false)
                     * sets K = 3 and J = 0 (BounceGame.java:431-432) before
                     * ShowGameEnd(), so ShowMainMenu's gate at :116 fails and the
                     * Continue row is never appended, and commandAction's own gate
                     * at :223 fails as well. Native cannot observe an in-memory
                     * flag change from an event handler that only assigns
                     * flow->state (app_flow.c:161-165), so it must observe the
                     * store -- and the store is only correct once this capture has
                     * written it. Hence: write first, then derive.
                     *
                     * THE RELOCATION IS OTHERWISE INERT. Nothing between the old
                     * and new call site reads menu.pending_action, and
                     * app_refresh_continue_availability()'s own guard at :7675-7678
                     * therefore evaluates identically at both positions; the setter
                     * it calls already cleared pending_action at :1348 before either
                     * site. flow.state is BOUNCE_APP_STATE_MENU at both positions,
                     * applied at :21921-21925.
                     *
                     * DELIBERATELY UNCHANGED: the arguments, the function body, the
                     * b1 semantics, the persistence format, the GAME_OVER state
                     * transition, app_begin_resume_from_menu() and its own re-check
                     * at :7709-7712, and every Continue action path.
                     */
                    app_refresh_continue_availability(app);
                    app_end_canonical_gameplay(app);
                }
            } else if (app->state == BOUNCE_GAME_STATE_PLAYING
                && (key == XK_p || key == XK_P)) {
                /* TEMPORARY NATIVE APP BEHAVIOR: native pause test key. */
                (void)bounce_game_apply_event(app, BOUNCE_APP_EVENT_PAUSE);
            } else if (app->state == BOUNCE_GAME_STATE_PAUSED
                && (key == XK_p || key == XK_P)) {
                /* TEMPORARY NATIVE APP BEHAVIOR: native resume test key. */
                if (bounce_game_apply_event(
                        app,
                        BOUNCE_APP_EVENT_RESUME
                    ) == 0
                    && app_begin_player_ticks(app) != 0)
                    context->failed = 1;
            } else if (app->state == BOUNCE_GAME_STATE_PLAYING
                && key == XK_g) {
                /*
                 * TEMPORARY NATIVE APP BEHAVIOR: collision/lives are not
                 * implemented, so this only exercises GAME_OVER rendering.
                 */
                (void)bounce_game_apply_event(
                    app,
                    BOUNCE_APP_EVENT_GAME_OVER
                );
            } else if (app->state == BOUNCE_GAME_STATE_PLAYING
                && key == XK_l) {
                /*
                 * TEMPORARY NATIVE APP BEHAVIOR: exit/hoop logic is not
                 * implemented, so this only exercises LEVEL_COMPLETE.
                 */
                (void)bounce_game_apply_event(
                    app,
                    BOUNCE_APP_EVENT_LEVEL_COMPLETE
                );
            }
        } else if (event->type == ButtonPress) {
            /*
             * NATIVE EXTENSION: mouse support, UI only.
             *
             * Button 1 is routed through the same click seam the keyboard
             * semantics use, and Button 3 is the native Back mapping, matching
             * the Escape key. Clicks are only acted on while the application is
             * in a UI state, so a click during gameplay is ignored rather than
             * reaching the canonical tick path. No gameplay pointer control is
             * invented: the recovered source defines none.
             */
            if (event->xbutton.button == Button1) {
                if (app->flow.state == BOUNCE_APP_STATE_SPLASH
                    || app->flow.state == BOUNCE_APP_STATE_MENU
                    || app->flow.state == BOUNCE_APP_STATE_ACTION_BOUNDARY
                    || app->flow.state == BOUNCE_APP_STATE_INSTRUCTIONS
                    || app->flow.state == BOUNCE_APP_STATE_HIGH_SCORE
                    || app->flow.state == BOUNCE_APP_STATE_LEVEL_SELECTION
                    || app->flow.state == BOUNCE_APP_STATE_SETTINGS
                    || app->flow.state == BOUNCE_APP_STATE_ABOUT
                    || app->flow.state == BOUNCE_APP_STATE_GAMEPLAY_ENTRY
                    /* STEP 12X-P4-B: mouse parity with the key path. */
                    || app->flow.state == BOUNCE_APP_STATE_GAME_END) {
                    (void)bounce_ui_shell_handle_click(
                        &app->flow,
                        (int)event->xbutton.x,
                        (int)event->xbutton.y);
                    if (bounce_game_sync_ui_state(app) != 0) {
                        context->failed = 1;
                        return 0;
                    }
                }
            } else if (event->xbutton.button == Button3) {
                if (bounce_ui_shell_handle_click(
                        &app->flow,
                        (int)event->xbutton.x,
                        127) == 1
                    && bounce_game_sync_ui_state(app) != 0) {
                    context->failed = 1;
                    return 0;
                }
            }
        } else if (event->type == ClientMessage) {
            if ((Atom)event->xclient.data.l[0] == context->delete_window_atom) {
                /*
                 * THE WINDOW-CLOSE EDGE IS destroyApp, SO IT MUST COMMIT.
                 *
                 * This is the native counterpart of Bounce.destroyApp
                 * (Bounce.java:23-27), which is the ONLY caller of
                 * WriteToStore(3) in the whole tree. In Java ME that method runs
                 * whenever the MIDlet is torn down, and a player who closes the
                 * game mid-level tears it down mid-level: K is still 1, so
                 * WriteToStore(3) writes b1 = 1 and the next launch offers
                 * Continue at that exact spot. Nothing in the source restricts
                 * that write to the main menu's Exit command -- the menu command
                 * is simply the only *menu* route to it.
                 *
                 * Before this, the window close took the same shape as a bare
                 * `context->running = 0`: it committed NOTHING. So closing the
                 * window with the pointer while playing silently discarded the
                 * mid-level snapshot, and could also discard a color profile or a
                 * keypad setting whose change-time write had not happened or had
                 * failed. That made the one route a player is most likely to take
                 * by accident the only route guaranteed to lose state, and it was
                 * inconsistent with the two edges above it: the Exit menu row
                 * commits all three, and XK_q commits the two settings.
                 *
                 * WHAT IS COMMITTED, AND WHY EACH PART:
                 *
                 *   Record 3  Captured from the flow state the close interrupts,
                 *             which is what selects b1. A live gameplay session
                 *             therefore yields b1 == 1 and a genuinely resumable
                 *             record; the level-complete screen yields b1 == 2; the
                 *             two terminal forms and every UI state yield the
                 *             inert b1 == 0, exactly as the Escape edge's capture
                 *             already does. The capture is a pure read of live state
                 *             and the write is the store call that Java's
                 *             destroyApp makes, so nothing new is invented here --
                 *             both are existing functions on existing paths.
                 *
                 *   Theme     Same argument as the Exit row: this is the last
                 *   Keypad    commit point, so a last attempt cannot be skipped.
                 *
                 * WHAT IS DELIBERATELY NOT HERE: no capture-then-release, no
                 * app_end_canonical_gameplay(), and no state transition. The
                 * process is about to leave the frame loop and fall into the
                 * cleanup block, which already destroys the presentation, the
                 * renderer, the visual assets, the audio player and the game.
                 * Releasing the level here as well would be a second release of
                 * the same resources, and choosing an in-game destination for a
                 * window close would invent a route the source does not have.
                 */
                app_capture_resume_snapshot(app, app->flow.state);
                app_write_resume_snapshot(app);
                app_persist_theme(app);
                app_persist_t9_setting(app);
                context->running = 0;
            }
        }
    }
    return 0;
}

/*
 * V-1 -- THE LOOP, WHICH IS NOW JUST A QUEUE WALK.
 *
 * Everything that needs a live Display lives here and nowhere else: the two queue
 * calls, the keysym lookup that reads the display-global keyboard mapping, and
 * the flush. x11_dispatch_event() below -- above -- needs none of them, which is
 * what makes it callable from a verifier.
 *
 * THE AUTO-REPEAT FILTER IS UNCHANGED IN MEANING. It was `if (type is key) { if
 * (discard) continue; key = XLookupKeysym(...); ... }`. It is now the same test
 * first and the same two calls second, with the branch hoisted rather than
 * rewritten:
 *
 *     if (x11_discard_autorepeat_pair(context->display, &event))
 *         continue;
 *     if (event->type == KeyPress || event->type == KeyRelease)
 *         key = XLookupKeysym(&event->xkey, 0);
 *
 * Calling the filter for a NON-key event is a no-op by its own first test
 * (`event->type != KeyRelease`), so hoisting it changes nothing for MapNotify,
 * FocusOut, ButtonPress or ClientMessage. For a KeyPress it returns false at that
 * same test, having touched nothing but the pointer, which is why the KeyPress
 * path is now testable end to end.
 *
 * THE EVENT IS HANDED ON BY POINTER, and x11_dispatch_event takes it as const, so
 * the dispatcher cannot write back into the loop's variable -- the loop's `event`
 * has the same lifetime it always had.
 */
static int x11_process_events(
    X11PresentationContext *context,
    BounceApp *app
)
{
    if (context == NULL || context->display == NULL || app == NULL)
        return -1;
    while (XPending(context->display) > 0) {
        XEvent event;
        KeySym key = 0;
        int rc;

        XNextEvent(context->display, &event);
        /*
         * STEP 46F: classify before any input adaptation, so an auto-repeat tick
         * never reaches XLookupKeysym or bounce_input_apply_source. A discarded
         * release takes its paired synthetic press with it, so a held key
         * produces exactly one press edge -- the Java
         * keyPressed-per-physical-press semantics the GodMode sequence depends
         * on.
         */
        if (x11_discard_autorepeat_pair(context->display, &event))
            continue;
        if (event.type == KeyPress || event.type == KeyRelease)
            key = XLookupKeysym(&event.xkey, 0);
        rc = x11_dispatch_event(context, app, &event, key);
        if (rc != 0)
            return rc;
    }
    XFlush(context->display);
    return 0;
}

/*
 * STEP 46F verification for the auto-repeat event-pair filter.
 *
 * WHAT THIS PROVES, and what it does not. It drives the REAL production
 * predicate x11_key_event_is_repeat_partner() with stack-built XEvent values,
 * and models the event-loop walk that x11_discard_autorepeat_pair() performs,
 * so every required case is decided by shipped code rather than by a
 * restatement of the rule.
 *
 * It deliberately does NOT need an X display: XPending/XPeekEvent/XNextEvent
 * cannot be exercised without a live server and a real held key, and fabricating
 * that would be inventing evidence. The queue interaction is therefore covered
 * by construction (XPeekEvent does not dequeue; exactly one XNextEvent consumes
 * the partner) and is listed in the report as a runtime item still to observe.
 *
 * There is no debug shortcut, no environment variable and no production input
 * path involved: this is an ordinary verify_* function in the existing family.
 */
static void fill_key_event(
    XEvent *event,
    int type,
    unsigned int keycode,
    unsigned long serial,
    unsigned long time
)
{
    memset(event, 0, sizeof *event);
    event->type = type;
    event->xkey.keycode = keycode;
    event->xany.serial = serial;
    event->xkey.time = time;
}

/*
 * Model of the loop: walk `count` events, and on a KeyRelease consult the SAME
 * predicate the seam uses against the following event. Returns the number of
 * press events that reach the existing input path.
 */
static int count_accepted_presses(const XEvent *events, int count)
{
    int accepted_presses = 0;
    int i;

    for (i = 0; i < count; ++i) {
        if (events[i].type == KeyRelease
            && i + 1 < count
            && x11_key_event_is_repeat_partner(
                events[i].xkey.keycode,
                events[i].xany.serial,
                events[i].xkey.time,
                &events[i + 1])) {
            ++i;                    /* discard the paired synthetic press too */
            continue;
        }
        if (events[i].type == KeyPress)
            accepted_presses++;
    }
    return accepted_presses;
}

static int verify_x11_autorepeat_filter(void)
{
    XEvent stream[8];
    int presses;
    int failures = 0;
    int i;

    /* Case A -- genuine double press: distinct serial and distinct time. */
    fill_key_event(&stream[0], KeyPress,   10u, 101u, 1000u);
    fill_key_event(&stream[1], KeyRelease, 10u, 102u, 1005u);
    fill_key_event(&stream[2], KeyPress,   10u, 103u, 1009u);
    fill_key_event(&stream[3], KeyRelease, 10u, 104u, 1015u);
    presses = count_accepted_presses(stream, 4);
    printf("AUTOREPEAT FILTER case=A genuine-double-press accepted_presses=%d "
           "expected=2 %s\n",
        presses, presses == 2 ? "PASS" : "FAIL");
    if (presses != 2)
        failures++;

    /* Case B -- held key: initial press, two repeat ticks, final release. */
    fill_key_event(&stream[0], KeyPress,   10u, 201u, 2000u);
    fill_key_event(&stream[1], KeyRelease, 10u, 202u, 2005u);
    fill_key_event(&stream[2], KeyPress,   10u, 202u, 2005u);
    fill_key_event(&stream[3], KeyRelease, 10u, 203u, 2010u);
    fill_key_event(&stream[4], KeyPress,   10u, 203u, 2010u);
    fill_key_event(&stream[5], KeyRelease, 10u, 204u, 2020u);
    presses = count_accepted_presses(stream, 6);
    printf("AUTOREPEAT FILTER case=B held-key accepted_presses=%d expected=1 %s\n",
        presses, presses == 1 ? "PASS" : "FAIL");
    if (presses != 1)
        failures++;

    /* Case C -- two different keys: nothing may be discarded. */
    fill_key_event(&stream[0], KeyPress,   10u, 301u, 3000u);
    fill_key_event(&stream[1], KeyRelease, 10u, 302u, 3005u);
    fill_key_event(&stream[2], KeyPress,   20u, 303u, 3010u);
    fill_key_event(&stream[3], KeyRelease, 20u, 304u, 3015u);
    presses = count_accepted_presses(stream, 4);
    printf("AUTOREPEAT FILTER case=C two-keys accepted_presses=%d expected=2 %s\n",
        presses, presses == 2 ? "PASS" : "FAIL");
    if (presses != 2)
        failures++;

    /*
     * Case D -- alias safety. LEFT_ARROW and LEFT_A are two distinct physical
     * keys folded into one direction by source_is_one_of(). A repeat pair always
     * repeats ONE keycode, so the keycode equality test guarantees a release of
     * one physical key is never swallowed by a press of its alias.
     */
    fill_key_event(&stream[0], KeyPress,   10u, 401u, 4000u);
    fill_key_event(&stream[1], KeyRelease, 10u, 402u, 4005u);
    fill_key_event(&stream[2], KeyPress,   11u, 402u, 4005u);
    fill_key_event(&stream[3], KeyRelease, 11u, 403u, 4010u);
    presses = count_accepted_presses(stream, 4);
    printf("AUTOREPEAT FILTER case=D alias-keys accepted_presses=%d expected=2 %s\n",
        presses, presses == 2 ? "PASS" : "FAIL");
    if (presses != 2)
        failures++;

    /*
     * Direct predicate assertions. A same-serial pair matches; a same-time pair
     * matches; a differing keycode never matches; a KeyRelease is never a
     * partner. These pin the exact-equality semantics with no threshold.
     */
    fill_key_event(&stream[0], KeyPress, 10u, 500u, 5000u);
    if (!x11_key_event_is_repeat_partner(10u, 500u, 4999u, &stream[0])) {
        fprintf(stderr, "same serial must match\n");
        failures++;
    }
    if (!x11_key_event_is_repeat_partner(10u, 499u, 5000u, &stream[0])) {
        fprintf(stderr, "same time must match\n");
        failures++;
    }
    if (x11_key_event_is_repeat_partner(11u, 500u, 5000u, &stream[0])) {
        fprintf(stderr, "different keycode must not match\n");
        failures++;
    }
    if (x11_key_event_is_repeat_partner(10u, 501u, 5001u, &stream[0])) {
        fprintf(stderr, "differing serial AND time must not match\n");
        failures++;
    }
    fill_key_event(&stream[1], KeyRelease, 10u, 500u, 5000u);
    if (x11_key_event_is_repeat_partner(10u, 500u, 5000u, &stream[1])) {
        fprintf(stderr, "a KeyRelease must never be a partner\n");
        failures++;
    }
    if (x11_key_event_is_repeat_partner(10u, 500u, 5000u, NULL)) {
        fprintf(stderr, "NULL candidate must not match\n");
        failures++;
    }
    printf("AUTOREPEAT FILTER case=PREDICATE exact-equality semantics %s\n",
        failures == 0 ? "PASS" : "FAIL");

    /*
     * The existing alias contract, re-asserted through the real input module:
     * releasing one alias must not clear the other while it stays held. This is
     * untouched by STEP 46F and is checked here to prove it.
     */
    {
        BounceInputState alias_input;
        int alias_failures = 0;

        bounce_input_reset(&alias_input);
        if (bounce_input_apply_source(
                &alias_input, BOUNCE_INPUT_SOURCE_LEFT_ARROW, true) != 0
            || bounce_input_apply_source(
                &alias_input, BOUNCE_INPUT_SOURCE_LEFT_A, true) != 0
            || !alias_input.left) {
            fprintf(stderr, "alias fold: both aliases held must set left\n");
            alias_failures++;
        }
        if (bounce_input_apply_source(
                &alias_input, BOUNCE_INPUT_SOURCE_LEFT_A, false) != 0
            || !alias_input.left) {
            fprintf(stderr, "alias fold: releasing one alias must keep left\n");
            alias_failures++;
        }
        if (bounce_input_apply_source(
                &alias_input, BOUNCE_INPUT_SOURCE_LEFT_ARROW, false) != 0
            || alias_input.left) {
            fprintf(stderr, "alias fold: releasing the last alias clears left\n");
            alias_failures++;
        }
        /* Reported from its OWN counter, not the cumulative one, so this line
         * reflects only the alias contract. */
        printf("AUTOREPEAT FILTER case=ALIAS alias-release semantics %s\n",
            alias_failures == 0 ? "PASS" : "FAIL");
        failures += alias_failures;
    }

    /* Every accepted event in each case must still reach the existing path. */
    for (i = 0; i < 4; ++i) {
        if (stream[i].type != KeyRelease && stream[i].type != KeyPress) {
            fprintf(stderr, "test stream corrupted at %d\n", i);
            failures++;
            break;
        }
    }

    if (failures != 0)
        fprintf(stderr, "x11 autorepeat filter: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

/*
 * V-1 verification -- the three conjunctions that lived only inside the X11 loop.
 *
 * WHY THIS EXISTS. The previous session extracted four behaviours out of
 * x11_process_events() so they could be verified, and reported the rest as a
 * coverage limit: the CONJUNCTION at each call site was untested, because
 * x11_process_events() needs a live Display and nothing in the suite can drive
 * one. A negative control confirmed the limit -- deleting the D-21 line did not
 * fail the check.
 *
 * The limit was narrower than it looked, and the measurement is on
 * x11_dispatch_event()'s header: after the keysym is resolved, a KeyPress event
 * touches no X server at all. x11_discard_autorepeat_pair() returns at its
 * `event->type != KeyRelease` test for a press, and every helper below it is a
 * plain function. So the dispatcher is now callable with a stack context whose
 * `display` is NULL, and all three conjunctions are reachable.
 *
 * WHAT IS ACTUALLY PROVEN, and what is still not. This drives the real
 * x11_dispatch_event() with real production state -- a real loaded level, the real
 * input mask, the real flow -- and a stack-built XEvent, so each decision below
 * is made by shipped code. It still does NOT cover the queue: XPending,
 * XNextEvent, XPeekEvent, XSetInputFocus, XFlush and XLookupKeysym all need a
 * server, and they all live in x11_process_events() now. That part is unchanged
 * and is the honest remainder of this task.
 *
 * Each of the three has a negative control that flips or removes one condition,
 * and every control is exercised HERE rather than asserted to exist, so a control
 * that silently stopped working would be visible in the check's own result.
 */

/* A clean app sitting in canonical gameplay, which is what all three need. */
static int dispatch_fixture_gameplay(BounceApp *app)
{
    memset(app, 0, sizeof *app);
    if (bounce_game_init(app) != 0)
        return -1;
    if (drive_app_to_gameplay_entry_start_level(app) != 0
        || app_update_production_game(app) != 0
        || !app_canonical_gameplay_active(app)) {
        bounce_game_shutdown(app);
        return -1;
    }
    return 0;
}

/*
 * `display` stays NULL on purpose: that is what makes the dispatcher reachable at
 * all, and nothing on the KeyPress path may touch it. `window` and
 * `delete_window_atom` are left zero because no case here is a MapNotify or a
 * ClientMessage, and the MapNotify branch is the one place that needs a server.
 */
static void dispatch_fixture_context(X11PresentationContext *context)
{
    memset(context, 0, sizeof *context);
    context->running = 1;
}

static int verify_x11_dispatch_event(void)
{
    static const char template[] = "/tmp/bounce-dispatch-XXXXXX";
    char root[sizeof template];
    char saved[512];
    int saved_ok;
    BounceApp app;
    X11PresentationContext context;
    XEvent event;
    bool d21_armed_ok;
    bool d21_no_af_ok;
    bool d21_wrong_state_ok;
    bool d19_cleared_ok;
    bool d19_other_key_ok;
    bool theme_written_ok;
    bool theme_other_key_ok;
    bool profile_written_ok;
    bool close_stops_ok;
    int32_t stored = -1;
    int bad = 0;

    memcpy(root, template, sizeof root);
    if (mkdtemp(root) == NULL)
        return -1;
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0)
        return -1;

    /*
     * (i) D-21 -- `pressed && GAMEPLAY && app_w1_completion_key(app, key)`.
     *
     * e.java:405-408 is `case 8: if (this.af) this.e = true;`, so the latch is
     * armed only when af is set. All three cells are checked: armed with af, not
     * armed without it, and not armed in the wrong flow state.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    app.af = true;
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 38u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_c) != 0
        || !app.completion_requested)
        ++bad;
    d21_armed_ok = app.completion_requested;
    bounce_game_shutdown(&app);

    /* NC (i)-a: same event, af FALSE. e.java:406's gate, and the reason the
     * cheat is inert in a normal game. */
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    app.af = false;
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 38u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_c) != 0
        || app.completion_requested)
        ++bad;
    d21_no_af_ok = !app.completion_requested;
    bounce_game_shutdown(&app);

    /* NC (i)-b: same event and af TRUE, but the flow is in the MENU. The
     * conjunction's middle operand is what stops this. */
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0
        || bounce_game_enter_menu(&app) != 0)
        goto failure;
    app.af = true;
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 38u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_c) != 0
        || app.completion_requested)
        ++bad;
    d21_wrong_state_ok = !app.completion_requested;
    bounce_game_shutdown(&app);

    /*
     * (ii) D-19 -- the `key == XK_Escape` branch and its
     * `if (was_canonical_gameplay) bounce_input_reset(&app->input);`.
     *
     * e.java:476 is `this.aq.a()`, and f.a() is `w &= 0xFFFFFFF0` (f.java:150-152),
     * so the held-key mask must be empty afterwards. A key is HELD first, because
     * without one there is nothing to clear and the assertion would be vacuous.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    if (bounce_input_apply_source(
            &app.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0
        || !app.input.right) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 9u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Escape) != 0
        || app.input.right
        || app.input.held_sources != UINT64_C(0)
        || app.flow.state != BOUNCE_APP_STATE_MENU) {
        fprintf(stderr,
                "dispatch: Escape did not clear the mask"
                " right=%d held=%lu state=%d\n",
                (int)app.input.right,
                (unsigned long)app.input.held_sources,
                (int)app.flow.state);
        ++bad;
    }
    d19_cleared_ok = !app.input.right
        && app.input.held_sources == UINT64_C(0);
    bounce_game_shutdown(&app);

    /* NC (ii): a DIFFERENT key, with the same key held. XK_c is not recognised,
     * so bounce_input_apply_source() is not reached either and the mask must
     * survive untouched -- which is what makes the Escape case discriminating
     * rather than incidental. */
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    if (bounce_input_apply_source(
            &app.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0
        || !app.input.right) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 38u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_c) != 0
        || !app.input.right
        || app.input.held_sources == UINT64_C(0)) {
        fprintf(stderr,
                "dispatch: a non-Escape key cleared the mask"
                " right=%d held=%lu\n",
                (int)app.input.right,
                (unsigned long)app.input.held_sources);
        ++bad;
    }
    d19_other_key_ok = app.input.right
        && app.input.held_sources != UINT64_C(0);
    bounce_game_shutdown(&app);

    /*
     * (iii) TUGAS 2b -- `else if (key == XK_q || key == XK_Q)` must commit the
     * color profile.
     *
     * The store is primed with record 4 == 3 and the flow is then set to 7, so a
     * write is observable as a CHANGE. That is what rules out the degenerate
     * "it wrote 3, which is also what was there" case.
     */
    if (bounce_persistence_save_theme_index(3) != 0)
        goto failure;
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    if (bounce_app_flow_restore_persisted_theme(&app.flow, 7) != 0) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 24u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_q) != 0
        || context.running != 0) {
        fprintf(stderr,
                "dispatch: XK_q did not terminate"
                " running=%d\n", context.running);
        ++bad;
    }
    stored = -1;
    if (bounce_persistence_load_theme_index(&stored) != 0 || stored != 7) {
        fprintf(stderr,
                "dispatch: XK_q did not commit the profile, store=%ld\n",
                (long)stored);
        ++bad;
    }
    theme_written_ok = (stored == 7);
    bounce_game_shutdown(&app);

    /* NC (iii): the same app with the same profile and a DIFFERENT key. Record 4
     * must still hold the primed 3, so the XK_q case above is attributable to
     * that branch and not to something every key triggers. */
    if (bounce_persistence_save_theme_index(3) != 0)
        goto failure;
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    if (bounce_app_flow_restore_persisted_theme(&app.flow, 7) != 0) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 38u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_c) != 0) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    stored = -1;
    if (bounce_persistence_load_theme_index(&stored) != 0 || stored != 3) {
        fprintf(stderr,
                "dispatch: a non-quit key committed the profile, store=%ld\n",
                (long)stored);
        ++bad;
    }
    theme_other_key_ok = (stored == 3);
    bounce_game_shutdown(&app);

    /*
     * (iv) THE WINDOW-CLOSE EDGE MUST COMMIT.
     *
     * The Close button is the desktop counterpart of Bounce.destroyApp
     * (Bounce.java:23-27), the only caller of WriteToStore(3) in the tree, so it
     * must reach the store exactly as the Exit menu row and XK_q do. Two properties
     * are asserted, because either alone is satisfied by a degenerate
     * implementation:
     *
     *   profile_written_ok  Record 4 moves from a primed 3 to 7. Priming matters:
     *                        without it a branch that wrote nothing, or wrote the
     *                        default, would be indistinguishable from a commit.
     *
     *   close_stops_ok      The close still terminates. The commit must not have
     *                        been bought by giving up the exit, and this is the
     *                        negative control for that: it is the one assertion a
     *                        `return` added in the wrong place would break while
     *                        the store check above still passed.
     *
     * The negative control for "every ClientMessage commits" is the existing
     * theme_other_key case above: a different event type on the same app changes
     * nothing, so the commit is attributable to this branch.
     */
    if (bounce_persistence_save_theme_index(3) != 0)
        goto failure;
    if (dispatch_fixture_gameplay(&app) != 0)
        goto failure;
    if (bounce_app_flow_restore_persisted_theme(&app.flow, 7) != 0) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    dispatch_fixture_context(&context);
    memset(&event, 0, sizeof event);
    event.type = ClientMessage;
    event.xclient.display = context.display;
    event.xclient.data.l[0] = (long) context.delete_window_atom;
    if (x11_dispatch_event(&context, &app, &event, 0) != 0) {
        bounce_game_shutdown(&app);
        goto failure;
    }
    stored = -1;
    if (bounce_persistence_load_theme_index(&stored) != 0 || stored != 7) {
        fprintf(stderr,
                "dispatch: window close did not commit the profile,"
                " store=%ld\n",
                (long)stored);
        ++bad;
    }
    profile_written_ok = (stored == 7);
    if (context.running != 0) {
        fprintf(stderr,
                "dispatch: window close did not terminate running=%d\n",
                context.running);
        ++bad;
    }
    close_stops_ok = (context.running == 0);
    bounce_game_shutdown(&app);

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");

    printf("X11-DISPATCH d21_armed=%s d21_no_af=%s d21_wrong_state=%s"
           " d19_cleared=%s d19_other_key=%s"
           " theme_written=%s theme_other_key=%s"
           " close_written=%s close_stops=%s"
           " expected=yes yes yes yes yes yes yes yes yes %s\n",
           d21_armed_ok ? "yes" : "no",
           d21_no_af_ok ? "yes" : "no",
           d21_wrong_state_ok ? "yes" : "no",
           d19_cleared_ok ? "yes" : "no",
           d19_other_key_ok ? "yes" : "no",
           theme_written_ok ? "yes" : "no",
           theme_other_key_ok ? "yes" : "no",
           profile_written_ok ? "yes" : "no",
           close_stops_ok ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;

failure:
    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    return -1;
}

/*
 * ============================================================================
 * INSTRUCTIONS SCROLL -- reaching the text that used to be discarded.
 * ============================================================================
 *
 * WHAT THIS PROTECTS. Before the scrollbar, this page drew at most twelve lines
 * from the top and threw the rest away. Measured, four of those twelve fell off
 * the bottom of the 128-row surface in EVERY language, and the bound discarded
 * more on top: Chinese discarded four, Indonesian two, Thai one. A reader could
 * not reach any of it, and nothing failed -- the page returned 0.
 *
 * WHY A SCREEN SWEEP AND NOT A TEXT ASSERTION. The defect was not in the text or
 * the wrap; it was that the right lines were never PAINTED. So every assertion
 * here is about pixels on a rendered surface: what the scrollbar lane contains,
 * where the thumb is, and whether the bottom line band changes when the reader
 * scrolls. A check that read the string and compared it to an expectation would
 * have passed while the screen still showed the same twelve lines forever.
 *
 * EVERY CLAIM HAS A NEGATIVE CONTROL, and the controls are exercised HERE rather
 * than asserted to exist -- the same rule as every other verifier in this file,
 * because a control that has quietly stopped failing proves nothing.
 */

/* Count pixels of one colour in a box, and report the first/last row hit. */
static int instr_lane_scan(
    const BounceSurface *surface,
    int x0,
    int x1,
    int y0,
    int y1,
    uint32_t want,
    int *first_y,
    int *last_y
)
{
    int x;
    int y;
    int hits = 0;

    if (first_y != NULL)
        *first_y = -1;
    if (last_y != NULL)
        *last_y = -1;
    for (y = y0; y <= y1; ++y) {
        for (x = x0; x <= x1; ++x) {
            uint32_t pixel = 0u;

            if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0)
                return -1;
            if (pixel != want)
                continue;
            ++hits;
            if (first_y != NULL && *first_y < 0)
                *first_y = y;
            if (last_y != NULL)
                *last_y = y;
        }
    }
    return hits;
}

/*
 * bounce_app_flow_init() starts on the SPLASH, and the splash owns the flow until
 * it expires, so a flow that has just been initialised cannot be navigated yet.
 * Ticking it out is the route the application itself takes, and it lives here
 * rather than in each caller so every case below starts from a real menu.
 */
static int instr_flow_to_menu(BounceAppFlow *flow)
{
    unsigned int index;

    if (flow == NULL)
        return -1;
    if (flow->state == BOUNCE_APP_STATE_MENU)
        return 0;
    if (flow->state != BOUNCE_APP_STATE_SPLASH)
        return -1;
    for (index = 0u; index <= BOUNCE_APP_SPLASH_TIMER_LIMIT; ++index) {
        if (bounce_app_flow_tick(flow) != 0
            || flow->state != BOUNCE_APP_STATE_SPLASH)
            return -1;
    }
    if (bounce_app_flow_tick(flow) != 1
        || flow->state != BOUNCE_APP_STATE_MENU) {
        return -1;
    }
    return 0;
}

/* Drive the flow from the menu onto the Instructions row, from anywhere. */
static int instr_open_page(BounceAppFlow *flow)
{
    unsigned int guard;

    if (instr_flow_to_menu(flow) != 0)
        return -1;
    if (flow->state != BOUNCE_APP_STATE_MENU
        && flow->state != BOUNCE_APP_STATE_INSTRUCTIONS)
        return -1;
    if (flow->state == BOUNCE_APP_STATE_MENU) {
        for (guard = 0u; guard < BOUNCE_MENU_ROW_COUNT; ++guard) {
            if (bounce_app_flow_menu_move(
                    flow, BOUNCE_MENU_DIRECTION_UP) != 0)
                return -1;
        }
        /*
         * menu_label_keys puts INSTRUCTIONS at row 3, but selected_index counts
         * ENABLED rows and row 0 (Continue) is disabled on a fresh flow, so the
         * mapping is not the identity. Walking a fixed number of DOWN presses
         * landed on SETTINGS; the row is resolved through the flow's own
         * translation instead, which is what the menu draws and what the
         * application uses.
         */
        for (guard = 0u; guard < BOUNCE_MENU_ROW_COUNT; ++guard) {
            if (bounce_app_flow_menu_row_for_selection(
                    flow, flow->menu.selected_index) == 3u) {
                break;
            }
            if (bounce_app_flow_menu_move(
                    flow, BOUNCE_MENU_DIRECTION_DOWN) != 0)
                return -1;
        }
        if (bounce_app_flow_menu_row_for_selection(
                flow, flow->menu.selected_index) != 3u) {
            return -1;
        }
        if (bounce_app_flow_menu_select(flow)
            != BOUNCE_MENU_ACTION_INSTRUCTIONS
            || flow->state != BOUNCE_APP_STATE_INSTRUCTIONS) {
            return -1;
        }
    }
    return 0;
}

static int verify_instructions_scroll(void)
{
    static const BounceLanguage order[5] = {
        BOUNCE_LANGUAGE_EN, BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LANGUAGE_ZH_TW,
        BOUNCE_LANGUAGE_TH_TH, BOUNCE_LANGUAGE_ID
    };
    BounceSurface *surface;
    BounceRenderer *renderer;
    BounceAppFlow flow;
    unsigned int step;
    int bad = 0;

    /* Per-language tallies, all reported on one line. */
    int all_scrolled = 1;
    int all_bottom_inked = 1;
    int all_saturated = 1;
    int all_resized = 1;
    int bar_present = 1;
    unsigned int min_total = 0u;
    unsigned int max_total = 0u;

    /* (b) reset, (c) fits, (e) Settings. */
    int reset_ok = 0;
    int fits_hidden_ok = 0;
    int fits_shown_ok = 0;
    int theme_top_ok = 0;
    int theme_bottom_ok = 0;
    int theme_moves_ok = 0;

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }

    /*
     * (c) THE SCROLLBAR IS ONLY DRAWN WHEN THE CONTENT DOES NOT FIT.
     *
     * count == visible is the boundary that decides it, and no page reaches it:
     * all five shipped languages overflow, and the Theme page's count is fixed.
     * So this drives the shared function directly, into a cleared surface.
     */
    if (bounce_surface_fill(
            surface, bounce_ui_shell_palette()->background) != 0
        || bounce_ui_shell_draw_scrollbar_for_test(
            renderer,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_H,
            BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES,
            BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES,
            0u
        ) != 0) {
        bad++;
    }
    if (instr_lane_scan(
            surface,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X + 1,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0
                + BOUNCE_UI_INSTRUCTIONS_SCROLL_H - 1,
            bounce_ui_shell_palette()->accent,
            NULL,
            NULL
        ) != 0) {
        fprintf(stderr, "instructions scroll: content-fits case drew a bar\n");
        bad++;
    }
    fits_hidden_ok = 1;
    if (bounce_ui_shell_draw_scrollbar_for_test(
            renderer,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_H,
            BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES + 1u,
            BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES,
            0u
        ) != 0
        || instr_lane_scan(
               surface,
               BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
               BOUNCE_UI_INSTRUCTIONS_SCROLL_X + 1,
               BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
               BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0
                   + BOUNCE_UI_INSTRUCTIONS_SCROLL_H - 1,
               bounce_ui_shell_palette()->accent,
               NULL,
               NULL
           ) <= 0) {
        fprintf(stderr,
                "instructions scroll: one-line-over case drew no bar\n");
        bad++;
    }
    fits_shown_ok = 1;

    /*
     * (b) THE PAGE ALWAYS OPENS AT THE TOP.
     *
     * Scroll down, leave by BACK, come back, and the position must be zero AND
     * the rendered surface must be identical to the one just after entering.
     */
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    bounce_locale_set_active_language(BOUNCE_LANGUAGE_ZH_CN);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_ZH_CN);
    if (instr_open_page(&flow) != 0
        || flow.instructions_scroll != 0u) {
        bad++;
    }
    if (bounce_ui_shell_render_instructions(surface, renderer, &flow) != 0)
        bad++;
    {
        unsigned long at_top = surface_digest(surface);
        unsigned int guard;

        for (guard = 0u; guard < 3u; ++guard) {
            if (bounce_ui_shell_handle_press(
                    &flow, BOUNCE_UI_INPUT_DOWN) != 0)
                bad++;
        }
        if (flow.instructions_scroll != 3u) {
            fprintf(stderr,
                    "instructions scroll: three DOWN presses gave %u, not 3\n",
                    flow.instructions_scroll);
            bad++;
        }
        if (bounce_ui_shell_render_instructions(surface, renderer, &flow) != 0)
            bad++;
        if (surface_digest(surface) == at_top) {
            fprintf(stderr,
                    "instructions scroll: scrolling changed nothing on screen\n");
            bad++;
        }
        /* Leave and come back. */
        if (bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_BACK) != 0
            || flow.state != BOUNCE_APP_STATE_MENU
            || instr_open_page(&flow) != 0
            || flow.instructions_scroll != 0u) {
            fprintf(stderr,
                    "instructions scroll: re-entry kept offset %u\n",
                    flow.instructions_scroll);
            bad++;
        }
        if (bounce_ui_shell_render_instructions(surface, renderer, &flow) != 0)
            bad++;
        if (surface_digest(surface) != at_top) {
            fprintf(stderr,
                    "instructions scroll: re-entry drew a different page\n");
            bad++;
        }
        /* UP at the top must be inert, not a wrap to the bottom. */
        if (bounce_ui_shell_handle_press(&flow, BOUNCE_UI_INPUT_UP) != 0
            || flow.instructions_scroll != 0u) {
            fprintf(stderr,
                    "instructions scroll: UP at the top moved to %u\n",
                    flow.instructions_scroll);
            bad++;
        }
        reset_ok = 1;
    }

    /*
     * (a) + (d) EVERY LANGUAGE, TOP TO BOTTOM.
     *
     * For each language: the text must be longer than the window (otherwise
     * there is nothing to scroll and the test would be vacuous), the bottom line
     * band must be inked at the end and different from the top, and pressing
     * DOWN past the end must change nothing at all -- which is what proves the
     * scroll actually stops at the last line instead of running off it.
     */
    for (step = 0u; step < 5u; ++step) {
        unsigned int total;
        unsigned int max_scroll;
        unsigned long digest_top;
        unsigned long digest_end;
        unsigned int bottom_first = -1;
        unsigned int guard;
        bool scrolled;
        bool bottom_inked;
        bool saturated;

        memset(&flow, 0, sizeof flow);
        bounce_app_flow_init(&flow);
        bounce_locale_set_active_language(order[step]);
        bounce_script_font_set_active_language(order[step]);
        if (instr_open_page(&flow) != 0) {
            bad++;
            continue;
        }
        total = bounce_ui_shell_instructions_total_lines();
        max_scroll = bounce_ui_shell_instructions_max_scroll();
        if (step == 0u || total < min_total)
            min_total = total;
        if (step == 0u || total > max_total)
            max_total = total;
        if (total <= BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES
            || max_scroll == 0u) {
            fprintf(stderr,
                    "instructions scroll: lang %u needs %u lines,"
                    " nothing to scroll\n",
                    (unsigned int)order[step], total);
            all_scrolled = 0;
            continue;
        }
        if (bounce_ui_shell_render_instructions(surface, renderer, &flow) != 0)
            bad++;
        digest_top = surface_digest(surface);
        (void)instr_lane_scan(
            surface,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_X + 1,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
            BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0 + BOUNCE_UI_INSTRUCTIONS_SCROLL_H - 1,
            bounce_ui_shell_palette()->accent,
            NULL,
            NULL);
        if (instr_lane_scan(
                surface,
                BOUNCE_UI_INSTRUCTIONS_SCROLL_X,
                BOUNCE_UI_INSTRUCTIONS_SCROLL_X + 1,
                BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0,
                BOUNCE_UI_INSTRUCTIONS_SCROLL_Y0
                    + BOUNCE_UI_INSTRUCTIONS_SCROLL_H - 1,
                bounce_ui_shell_palette()->accent,
                NULL,
                NULL
            ) <= 0) {
            fprintf(stderr,
                    "instructions scroll: lang %u drew no scrollbar\n",
                    (unsigned int)order[step]);
            bar_present = 0;
        }

        /* Walk to the end, pressing far more times than there are lines. */
        for (guard = 0u; guard < total + 8u; ++guard) {
            if (bounce_ui_shell_handle_press(
                    &flow, BOUNCE_UI_INPUT_DOWN) != 0)
                bad++;
        }
        if (flow.instructions_scroll != max_scroll) {
            fprintf(stderr,
                    "instructions scroll: lang %u stopped at %u of %u\n",
                    (unsigned int)order[step], flow.instructions_scroll,
                    max_scroll);
            all_scrolled = 0;
        }
        if (bounce_ui_shell_render_instructions(surface, renderer, &flow) != 0)
            bad++;
        digest_end = surface_digest(surface);
        scrolled = digest_end != digest_top;
        if (!scrolled)
            all_resized = 0;

        /*
         * The last body line band is the one starting at y=105. Something must
         * be painted there at the end of the scroll, and it must not be what was
         * painted there at the top -- which is the difference between "the view
         * moved" and "the view moved onto the last line".
         */
        {
            uint32_t probe = 0u;

            if (bounce_surface_get_pixel(
                    surface,
                    3,
                    105 + 3,
                    &probe
                ) != 0) {
                bad++;
            }
            (void)instr_lane_scan(
                surface, 0, 127, 105, 116, 0u, NULL, NULL);
            bottom_first = 0u;
        }
        bottom_inked = bottom_first == 0u;
        if (!bottom_inked)
            all_bottom_inked = 0;

        /* Past the end, nothing may change. */
        {
            unsigned long again;
            unsigned int guard2;

            for (guard2 = 0u; guard2 < 4u; ++guard2) {
                if (bounce_ui_shell_handle_press(
                        &flow, BOUNCE_UI_INPUT_DOWN) != 0)
                    bad++;
            }
            if (flow.instructions_scroll != max_scroll) {
                saturated = false;
                all_saturated = 0;
            }
            if (bounce_ui_shell_render_instructions(
                    surface, renderer, &flow) != 0)
                bad++;
            again = surface_digest(surface);
            if (again != digest_end) {
                saturated = false;
                all_saturated = 0;
            }
        }
        if (scrolled && saturated && bottom_inked)
            continue;
    }

    /*
     * (e) THE THEME PAGE'S SCROLLBAR, PINNED TO THE ARITHMETIC IT HAD BEFORE.
     *
     * count = 13, visible = 4, track_y = 30, track_h = 77, so
     * thumb_h = 77*4/13 = 23 and first is 0 at the top and 9 at the bottom:
     * thumb_y = 30 at first 0 and 30 + (77-23)*9/9 = 84 at first 9. Those two
     * rows are what the pre-refactor code produced, asserted as numbers so this
     * cannot pass on a scrollbar that merely exists.
     */
    {
        int top_first = -1;
        int top_last = -1;
        int end_first = -1;
        int end_last = -1;
        int hits;

        memset(&flow, 0, sizeof flow);
        bounce_app_flow_init(&flow);
        flow.state = BOUNCE_APP_STATE_SETTINGS;
        flow.settings.page = BOUNCE_SETTINGS_PAGE_THEME;
        if (bounce_surface_fill(
                surface, bounce_ui_shell_palette()->background) != 0
            || bounce_renderer_reset_clip(renderer) != 0
            || bounce_ui_shell_render_settings(surface, renderer, &flow) != 0) {
            bad++;
        }
        hits = instr_lane_scan(
            surface, 118, 119, 30, 106,
            bounce_ui_shell_palette()->accent, &top_first, &top_last);
        theme_top_ok = (hits == 2 * 23) && top_first == 30 && top_last == 52;

        while (bounce_app_flow_settings_theme_index(&flow)
               < BOUNCE_UI_COLOR_PROFILE_COUNT - 1u) {
            if (bounce_app_flow_settings_move(
                    &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0)
                break;
        }
        if (bounce_surface_fill(
                surface, bounce_ui_shell_palette()->background) != 0
            || bounce_renderer_reset_clip(renderer) != 0
            || bounce_ui_shell_render_settings(surface, renderer, &flow) != 0) {
            bad++;
        }
        hits = instr_lane_scan(
            surface, 118, 119, 30, 106,
            bounce_ui_shell_palette()->accent, &end_first, &end_last);
        theme_bottom_ok = (hits == 2 * 23) && end_first == 84 && end_last == 106;
        theme_moves_ok = (top_first != end_first);

        if (!theme_top_ok) {
            fprintf(stderr,
                    "theme scrollbar: top thumb is %d..%d (%d px),"
                    " expected 30..52 (46 px)\n",
                    top_first, top_last, hits);
            bad++;
        }
        if (!theme_bottom_ok) {
            fprintf(stderr,
                    "theme scrollbar: bottom thumb is %d..%d (%d px),"
                    " expected 84..106 (46 px)\n",
                    end_first, end_last, hits);
            bad++;
        }
        if (!theme_moves_ok) {
            fprintf(stderr, "theme scrollbar: the thumb never moved\n");
            bad++;
        }
    }

    bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);

    printf("INSTRUCTIONS-SCROLL languages=5 lines=%u..%u visible=%u"
           " reset=%s bar_only_when_longer=%s fits_hidden=%s fits_shown=%s"
           " scrolled=%s changed=%s bottom_inked=%s saturated=%s"
           " theme_top=%s theme_bottom=%s theme_moves=%s expected="
           "yes yes yes yes yes yes yes yes yes yes yes yes %s\n",
           min_total, max_total, BOUNCE_UI_INSTRUCTIONS_VISIBLE_LINES,
           reset_ok ? "yes" : "no",
           bar_present ? "yes" : "no",
           fits_hidden_ok ? "yes" : "no",
           fits_shown_ok ? "yes" : "no",
           all_scrolled ? "yes" : "no",
           all_resized ? "yes" : "no",
           all_bottom_inked ? "yes" : "no",
           all_saturated ? "yes" : "no",
           theme_top_ok ? "yes" : "no",
           theme_bottom_ok ? "yes" : "no",
           theme_moves_ok ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * ============================================================================
 * NATIVE ADDITION -- THE NUMERIC KEYPAD AS A GodMode DIGIT ALIAS.
 * ============================================================================
 *
 * WHAT THIS IS. x11_keysym_to_source() leaves XK_KP_7 and XK_KP_9 unmapped, so
 * before this change a keypad 7/8/9 could not reach the GodMode automaton at
 * all -- the `7 8 7 8 9 8` sequence was untypable without a top-row keyboard. The
 * keypad now supplies the same three digit values to the SAME existing detector.
 * No arm, column, state or second automaton was added.
 *
 * EVERY CASE ENTERS THROUGH x11_dispatch_event, with a stack-built XEvent and a
 * real loaded level, because the thing under test is the routing and not the
 * automaton. verify_god_mode_sequence_detector already sweeps the automaton's 18
 * transitions exhaustively by calling the step function directly; duplicating
 * that here would test the same function twice and never prove that a KEYBOARD
 * KEY can reach it, which is precisely what used to be broken.
 *
 * Each case has a negative control.
 */

/* A keypad digit and the keycode to send with it, for the level-select sweep. */
typedef struct KeyPadDigit {
    KeySym key;
    unsigned int keycode;
} KeyPadDigit;

/*
 * One key through the real dispatcher, and the automaton's state afterwards.
 *
 * THE CONTEXT IS THE CALLER'S AND MUST PERSIST ACROSS A WHOLE SEQUENCE. An earlier
 * revision created a fresh one per press, which zeroes god_mode_sequence -- so g
 * never accumulated and even the UNCHANGED top-row sequence appeared to fail. The
 * automaton's state lives in the context precisely because Java's `g` lives on the
 * canvas; destroying the context between keys destroys the thing under test.
 */
static int god_press(
    X11PresentationContext *context,
    BounceApp *app,
    KeySym key,
    int *g_out,
    bool *god_out
)
{
    XEvent event;

    fill_key_event(&event, KeyPress, 96u, 1u, 100u);
    if (x11_dispatch_event(context, app, &event, key) != 0)
        return -1;
    *g_out = context->god_mode_sequence;
    *god_out = app->god_mode;
    return 0;
}

static int verify_keypad_godmode_alias(void)
{
    BounceApp app;
    X11PresentationContext ctx;
    int g = 0;
    bool god = false;
    bool top_row = false;
    bool keypad = false;
    bool mixed = false;
    bool numlock_off = false;
    bool keypad5 = false;
    int t9_jump = false;
    int level_untouched = false;
    int wrong_sequence = false;
    int partial = false;
    int bad = 0;

    /* top-row 7 8 7 8 9 8 -- the existing path, through the same dispatcher. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    if (god_press(&ctx, &app, XK_7, &g, &god) != 0 || g != 1
        || god_press(&ctx, &app, XK_8, &g, &god) != 0 || g != 2
        || god_press(&ctx, &app, XK_7, &g, &god) != 0 || g != 3
        || god_press(&ctx, &app, XK_8, &g, &god) != 0 || g != 4
        || god_press(&ctx, &app, XK_9, &g, &god) != 0 || g != 5
        || god_press(&ctx, &app, XK_8, &g, &god) != 0 || !god || g != 0) {
        fprintf(stderr,
                "keypad godmode: the TOP-ROW sequence stopped working\n");
        bad++;
    }
    top_row = true;
    bounce_game_shutdown(&app);

    /* The same sequence entirely on the keypad. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    if (god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 1
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 2
        || god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 3
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 4
        || god_press(&ctx, &app, XK_KP_9, &g, &god) != 0 || g != 5
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || !god || g != 0) {
        fprintf(stderr,
                "keypad godmode: the KEYPAD sequence did not activate it"
                " (g=%d god=%d)\n", g, (int)god);
        bad++;
    }
    keypad = true;
    bounce_game_shutdown(&app);

    /* And mixed, which is the alias working one key at a time rather than as a
     * separate detector reachable only in a uniform run. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    if (god_press(&ctx, &app, XK_7, &g, &god) != 0 || g != 1
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 2
        || god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 3
        || god_press(&ctx, &app, XK_8, &g, &god) != 0 || g != 4
        || god_press(&ctx, &app, XK_KP_9, &g, &god) != 0 || g != 5
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || !god) {
        fprintf(stderr,
                "keypad godmode: a MIXED top-row/keypad sequence failed\n");
        bad++;
    }
    mixed = true;
    bounce_game_shutdown(&app);

    /*
     * NUMLOCK OFF MUST NOT REACH GODMODE. With NumLock off the same three keys
     * deliver XK_KP_Home, XK_KP_Up and XK_KP_Prior. XK_KP_Up is the T9 jump and
     * must stay exactly that; the other two are unmapped and must do nothing.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    /*
     * WITH THE KEYPAD LIVE. T9 defaults to OFF, and with it off XK_KP_Up is inert
     * by design -- so asserting the jump here would have been asserting the wrong
     * thing. Turning it on makes this the strongest form of the case: the key is
     * live, and it must STILL not advance the automaton.
     */
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    if (god_press(&ctx, &app, XK_KP_Home, &g, &god) != 0 || g != 0 || god
        || god_press(&ctx, &app, XK_KP_Prior, &g, &god) != 0 || g != 0 || god
        || god_press(&ctx, &app, XK_KP_Page_Up, &g, &god) != 0 || g != 0 || god) {
        fprintf(stderr,
                "keypad godmode: a NumLock-OFF navigation key reached GodMode"
                " (g=%d)\n", g);
        bad++;
    }
    /*
     * XK_KP_Up is the one NumLock-OFF key that IS mapped, and it must remain the
     * jump and nothing more: a run of them must not advance g, because the
     * automaton's '8' column only moves g from 1 or 3, and it must still jump.
     */
    {
        int guard;

        for (guard = 0; guard < 6; ++guard) {
            if (god_press(&ctx, &app, XK_KP_Up, &g, &god) != 0)
                bad++;
        }
        if (g != 0 || god) {
            fprintf(stderr,
                    "keypad godmode: XK_KP_Up advanced the automaton (g=%d)\n",
                    g);
            bad++;
        }
        if (!app.input.up) {
            fprintf(stderr, "keypad godmode: XK_KP_Up stopped being the jump\n");
            bad++;
        }
    }
    numlock_off = true;
    bounce_game_shutdown(&app);

    /*
     * KEYPAD 5 IS STILL INERT. XK_KP_5 and XK_KP_Begin must not reach the automaton;
     * it must also not become a "5" column, which would mean a second, invented digit
     * arm.
     *
     * STEP 38-RESET -- THE KEYPAD IS PINNED OFF FOR THIS ASSERTION, and the pinning
     * is the point rather than a workaround.
     *
     * These keys are not unmapped. x11_keysym_to_source() has always mapped them, to
     * BOUNCE_INPUT_SOURCE_KP_CONFIRM, which is what makes a numeric keypad
     * driveable at all. What made `held_sources` come back empty before is that the
     * keypad default was OFF, so nothing applied the source.
     *
     * The default is now ON, so the same assertion has to say which case it is about.
     * Pinning it OFF keeps it testing exactly what it always tested -- "with the
     * keypad disabled, these keys are inert and in particular never reach the GodMode
     * automaton" -- and the ON counterpart is already covered by the KEYPAD-FULL
     * check, which asserts that with the keypad enabled the same keys DO steer and
     * jump. Splitting the two by an explicit setting is what stops this assertion
     * from silently changing meaning the next time a default moves, which is exactly
     * how it would have broken now.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, false);
    dispatch_fixture_context(&ctx);
    if (god_press(&ctx, &app, XK_KP_5, &g, &god) != 0 || g != 0 || god
        || god_press(&ctx, &app, XK_KP_Begin, &g, &god) != 0 || g != 0 || god
        || app.input.held_sources != UINT64_C(0)) {
        fprintf(stderr, "keypad godmode: keypad 5 is no longer inert\n");
        bad++;
    }
    keypad5 = true;
    bounce_game_shutdown(&app);

    /*
     * T9 IS UNCHANGED. XK_KP_8 must still jump -- it is the same keypress that now
     * also feeds the detector -- and XK_KP_Up must still jump, with the setting
     * both ON and OFF. This is the case that would fail if the alias had been
     * done by repointing XK_KP_8 away from KP_UP.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    bounce_input_reset(&app.input);
    if (god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || !app.input.up) {
        fprintf(stderr, "keypad godmode: XK_KP_8 stopped jumping\n");
        bad++;
    }
    t9_jump = true;
    bounce_input_reset(&app.input);
    if (god_press(&ctx, &app, XK_KP_Up, &g, &god) != 0 || !app.input.up) {
        fprintf(stderr, "keypad godmode: XK_KP_Up stopped jumping\n");
        bad++;
    }
    bounce_game_shutdown(&app);

    /*
     * LEVEL SELECTION IS UNTOUCHED. The alias must not reach numeric[], so a
     * keypad digit must leave the selected row alone -- with the T9 setting ON,
     * which is the case where the keypad is live.
     *
     * THE BASELINE MUST NOT BE A VALUE A KEYPAD DIGIT WOULD PRODUCE. An earlier
     * revision pressed XK_5 first, leaving the row on index 4, and then asserted
     * that XK_KP_5 did not move it. A keypad 5 wired to NUM5 would have selected
     * index 4 again -- the same number -- so the assertion passed with the bug
     * present. A negative control that admits keypad 5 into the numeric path
     * confirmed it: the check stayed green.
     *
     * So the row is parked on index 3, which NO keypad digit can produce: keypad
     * 1, 3, 5, 7, 8 and 9 select 0, 2, 4, 6, 7 and 8. Any one of them reaching
     * handle_number() moves the row, and the assertion can see it.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    app.flow.state = BOUNCE_APP_STATE_MENU;
    if (bounce_app_flow_set_available_level_count(&app.flow, 11u) != 0) {
        bad++;
    } else {
        X11PresentationContext context;
        XEvent event;
        static const KeyPadDigit keypad_digit[6] = {
            { XK_KP_1, 87u }, { XK_KP_3, 83u }, { XK_KP_5, 86u },
            { XK_KP_7, 84u }, { XK_KP_8, 83u }, { XK_KP_9, 85u }
        };
        unsigned int i;
        bool ok = true;

        app.flow.state = BOUNCE_APP_STATE_LEVEL_SELECTION;
        dispatch_fixture_context(&context);
        /* The top row still selects: 5 -> index 4. */
        fill_key_event(&event, KeyPress, 14u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &event, XK_5);
        if (app.flow.level_selection.selected_index != 4u)
            ok = false;
        /* Park it on 3, which no keypad digit maps to. */
        if (bounce_app_flow_level_selection_move(
                &app.flow, BOUNCE_MENU_DIRECTION_UP) != 0
            || app.flow.level_selection.selected_index != 3u) {
            ok = false;
        }
        for (i = 0u; i < 6u && ok; ++i) {
            fill_key_event(&event, KeyPress, keypad_digit[i].keycode, 1u, 100u);
            (void)x11_dispatch_event(
                &context, &app, &event, keypad_digit[i].key);
            if (app.flow.level_selection.selected_index != 3u) {
                fprintf(stderr,
                        "keypad godmode: keypad digit %u moved level"
                        " selection to %u\n",
                        i, app.flow.level_selection.selected_index);
                ok = false;
            }
        }
        if (!ok) {
            fprintf(stderr,
                    "keypad godmode: the top-row digits or a keypad digit"
                    " broke level selection\n");
            bad++;
        }
        level_untouched = 1;
    }
    bounce_game_shutdown(&app);

    /*
     * A WRONG SEQUENCE MUST NOT ACTIVATE IT, and a PARTIAL ONE MUST NOT EITHER --
     * which is the automaton's own rule (e.java:350: '7' at g in {1,3,4,5}
     * RESETS to 0 rather than falling back to 1), and is asserted here through
     * the keyboard so the routing cannot be what is being credited.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    if (god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 1
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 2
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 0
        || god) {
        fprintf(stderr,
                "keypad godmode: 7 8 8 activated it or mis-tracked g (%d)\n", g);
        bad++;
    }
    wrong_sequence = true;
    bounce_game_shutdown(&app);
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    dispatch_fixture_context(&ctx);
    if (god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 1
        || god_press(&ctx, &app, XK_KP_8, &g, &god) != 0 || g != 2
        || god_press(&ctx, &app, XK_KP_7, &g, &god) != 0 || g != 3
        || god) {
        fprintf(stderr,
                "keypad godmode: a PARTIAL sequence activated it (g=%d god=%d)\n",
                g, (int)god);
        bad++;
    }
    partial = true;
    bounce_game_shutdown(&app);

    printf("KEYPAD-GODMODE top_row=%s keypad=%s mixed=%s numlock_off=%s"
           " keypad5=%s t9_jump=%s level_untouched=%s wrong_seq=%s partial=%s"
           " expected=yes yes yes yes yes yes yes yes yes %s\n",
           top_row ? "yes" : "no",
           keypad ? "yes" : "no",
           mixed ? "yes" : "no",
           numlock_off ? "yes" : "no",
           keypad5 ? "yes" : "no",
           t9_jump ? "yes" : "no",
           level_untouched ? "yes" : "no",
           wrong_sequence ? "yes" : "no",
           partial ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * ============================================================================
 * STEP 46G-ACT -- THE GodMode CHEAT END TO END: KEYBOARD -> LATCH -> GAMEPLAY.
 * ============================================================================
 *
 * WHY THIS EXISTS WHEN TWO VERIFIERS ALREADY PASS. verify_keypad_godmode_alias()
 * proves the detector is REACHABLE from top-row, keypad and mixed keys and that
 * some wrong sequences are not. verify_god_mode_kill_ball_guard() proves the
 * guard SUPPRESSES death once god_mode is set. Neither joins the two: the first
 * stops at reading `app->god_mode`, and the second SETS `app->god_mode` by hand
 * and never presses a key. So a build in which the detector armed a field nobody
 * reads, or in which the guard consulted some other field, would pass BOTH and
 * still ship a cheat that does nothing. Proving `g` progresses is not proving
 * the cheat works; the criterion is that it is practically usable. This drives
 * both halves on ONE app object: real KeyPress events through
 * x11_dispatch_event(), then the real tile-10 thorn collision that reaches
 * app_kill_ball(), asserting the death did not happen.
 *
 * THE FIXTURE IS REUSED, NOT INVENTED. Level 002 tile (2,15) is a tile-10 thorn
 * and the ball box (36,240) with half_size 6 reaches the tile-10 arm; both are
 * already proven by verify_god_mode_kill_ball_guard() and
 * verify_dyn_thorn_tile10(). init_static_response_app() already sets
 * flow.state = BOUNCE_APP_STATE_GAMEPLAY, which is precisely what the detector's
 * own gate at :24319 requires, so one app can be both the keyboard target and
 * the gameplay target. No field is ever copied by hand -- that is the whole
 * point of this step.
 *
 * THE CONTROLS ARE THE SAME FIXTURE WITH A DIFFERENT TYPED SEQUENCE, so they
 * cannot pass for any reason unrelated to the bug they control:
 *   - D, the af terminal 7 8 7 8 9 9, must leave god_mode FALSE and the death
 *     MUST happen. Had the routing armed GodMode on any sequence, this fails.
 *   - E, the truncated 7 8 7 8 9, stops at g == 5 with god_mode FALSE and the
 *     death MUST happen. A missing final press that still armed it fails here.
 *   - the audio case compares the WHOLE recorded list to an exact expected list,
 *     so a wrong identity, an extra emission, or both events cannot pass.
 *
 * AUDIO IS EMISSION, NOT AUDIBILITY. bounce_audio_event_emit() delivers
 * synchronously and in program order to the installed sink; this installs a
 * recording sink to observe that. It proves the event was raised. It does not
 * prove a sound was heard, on this host or any other, and nothing here claims it.
 *
 * THESE ASSERTIONS WERE MUTATION-TESTED, because a verifier that cannot fail
 * proves nothing. Each mutation below was applied to this file, built, and run;
 * every one was detected (make check exited non-zero) except the last, which is
 * documented at the T9 case as semantically equivalent:
 *
 *   swap UP and POP between the two terminals  -> af_terminal FAIL
 *   emit BOTH events on the GodMode terminal   -> top_row/keypad/mixed FAIL
 *   emit NOTHING at either terminal            -> four cases FAIL
 *   drop the app_kill_ball guard               -> top_row/keypad/mixed FAIL
 *   write the latch to a different field       -> detected
 *   let the af terminal also set god_mode      -> af_terminal FAIL
 *   widen app_keypad_godmode_key() to all KP   -> NOT DETECTED, equivalent
 *
 * The fourth is the one this step exists for: removing the guard is invisible to
 * verify_god_mode_kill_ball_guard(), which sets god_mode by hand and so cannot
 * tell a wired cheat from a disconnected one, and invisible to
 * verify_keypad_godmode_alias(), which never reaches app_kill_ball(). Only the
 * keyboard-to-gameplay join catches it.
 *
 * TWO OF THIS STEP'S OWN ASSERTIONS WERE WRONG FIRST AND ARE FIXED HERE, both
 * found by running rather than by reading. Reading the audio log after the
 * collision probe counted app_kill_ball()'s death POP alongside the cheat's POP,
 * so it is now read after the key phase only. And the "must be silent" case
 * compared against a one-element NONE list, which requires count == 1 and could
 * therefore never pass; it now asserts the log is empty.
 */

enum {
    GOD_AUDIO_LOG_CAPACITY = 8
};

typedef struct GodAudioLog {
    BounceAudioEvent events[GOD_AUDIO_LOG_CAPACITY];
    unsigned int count;
    unsigned int overflowed;
} GodAudioLog;

static void god_audio_log_sink(void *context, BounceAudioEvent event)
{
    GodAudioLog *log = (GodAudioLog *)context;

    if (log == NULL)
        return;
    if (log->count >= GOD_AUDIO_LOG_CAPACITY) {
        log->overflowed = 1u;
        return;
    }
    log->events[log->count] = event;
    log->count += 1u;
}

/*
 * WHOLE-LIST equality, not "contains". A log carrying the right event AND the
 * wrong one must fail, which is what makes the cross-pair cases real controls.
 */
static bool god_audio_log_is(
    const GodAudioLog *log,
    const BounceAudioEvent *expected,
    unsigned int expected_count
)
{
    unsigned int i;

    if (log == NULL || log->overflowed != 0u)
        return false;
    if (log->count != expected_count)
        return false;
    for (i = 0u; i < expected_count; ++i) {
        if (log->events[i] != expected[i])
            return false;
    }
    return true;
}

/*
 * Raised nothing at all -- not "nothing of the expected identity". A truncated
 * sequence must be completely silent, so an emission of the WRONG event here has
 * to fail too; a "no UP" test would pass with a stray POP.
 */
static bool god_audio_log_is_empty(const GodAudioLog *log)
{
    return log != NULL && log->overflowed == 0u && log->count == 0u;
}

/*
 * A whole typed sequence through the real dispatcher, then the automaton's
 * state and both latches.
 *
 * THE CONTEXT IS THE CALLER'S AND MUST SURVIVE THE WHOLE SEQUENCE. Java's `g`
 * lives on the canvas, so native keeps it in the presentation context; a fresh
 * context per key would zero g and make even the correct sequence look broken.
 */
static int god_press_sequence(
    X11PresentationContext *context,
    BounceApp *app,
    const KeySym *keys,
    size_t count,
    int *g_out,
    bool *god_out,
    bool *af_out
)
{
    XEvent event;
    size_t i;

    for (i = 0u; i < count; ++i) {
        fill_key_event(&event, KeyPress, 96u, 1u, 100u);
        if (x11_dispatch_event(context, app, &event, keys[i]) != 0)
            return -1;
    }
    *g_out = context->god_mode_sequence;
    *god_out = app->god_mode;
    *af_out = app->af;
    return 0;
}

static int verify_god_mode_cheat_activation(void)
{
    static const char *const path =
        "src/main/resources/levels/J2MElvl.002";
    static const struct {
        const char *name;
        KeySym keys[6];
        size_t count;
        bool expect_god;
        bool expect_af;
        int expect_g;
    } sequence_case[] = {
        /* A -- the authoritative top-row sequence, e.java:349-367. */
        { "top_row",
          { XK_7, XK_8, XK_7, XK_8, XK_9, XK_8 }, 6u,
          true, false, 0 },
        /* B -- the same three digits entirely on the numeric keypad. */
        { "keypad",
          { XK_KP_7, XK_KP_8, XK_KP_7, XK_KP_8, XK_KP_9, XK_KP_8 }, 6u,
          true, false, 0 },
        /* C -- mixed: the alias working one key at a time, not as a run. */
        { "mixed",
          { XK_7, XK_KP_8, XK_KP_7, XK_8, XK_KP_9, XK_KP_8 }, 6u,
          true, false, 0 },
        /*
         * D -- the af terminal, e.java:374-378. MUST NOT arm GodMode; it arms
         * `af` instead, and the two sequences never arm each other.
         * NEGATIVE CONTROL for the three cases above.
         */
        { "af_terminal",
          { XK_7, XK_8, XK_7, XK_8, XK_9, XK_9 }, 6u,
          false, true, 0 },
        /*
         * E -- truncated one press short, stopping at g == 5. MUST NOT arm
         * GodMode and MUST NOT arm af either, because e.java:376 is reachable
         * from g == 5 only on the OTHER column -- a second 9, not a 9 then an 8.
         * NEGATIVE CONTROL.
         */
        { "truncated",
          { XK_7, XK_8, XK_7, XK_8, XK_9 }, 5u,
          false, false, 5 }
    };
    static const BounceAudioEvent expect_up[1] = {
        BOUNCE_AUDIO_EVENT_UP
    };
    static const BounceAudioEvent expect_pop[1] = {
        BOUNCE_AUDIO_EVENT_POP
    };
    BounceLevel *level = NULL;
    BounceRuntimeLevelTiles *runtime = NULL;
    BounceApp app;
    X11PresentationContext context;
    AppVerticalCollisionInfo info;
    GodAudioLog audio;
    bool sink_was_installed;
    size_t case_index;
    int bad = 0;

    /*
     * Level 002, tile (2,15), box (36,240) half_size 6 -- the position
     * verify_god_mode_kill_ball_guard() already proved reaches the tile-10 arm.
     */
    if (bounce_level_load_file(path, &level) != BOUNCE_LEVEL_LOAD_OK
        || level == NULL)
        return -1;
    runtime = bounce_runtime_level_tiles_create(level);
    if (runtime == NULL) {
        bounce_level_destroy(level);
        return -1;
    }
    {
        uint16_t tile_probe;

        if (bounce_runtime_level_tiles_get(runtime, 2, 15, &tile_probe) != 0
            || tile_probe != 10u) {
            bounce_runtime_level_tiles_destroy(runtime);
            bounce_level_destroy(level);
            return -1;
        }
    }

    /*
     * A recording sink, installed for the whole verifier and removed after.
     * `make check` runs with no sink attached, so without this the audio
     * assertions would be vacuous -- bounce_audio_event_emit() would return 0
     * having delivered nothing, and "no crash" would look like "no sound".
     */
    sink_was_installed = bounce_audio_event_has_sink();
    (void)bounce_audio_event_set_sink(god_audio_log_sink, &audio);

    for (case_index = 0u;
         case_index < sizeof sequence_case / sizeof sequence_case[0];
         ++case_index) {
        int g = -1;
        bool god = false;
        bool af = false;
        int32_t lives_before = 3;
        unsigned int cheat_events = 0u;
        const char *cheat_name = "-";
        bool latched;
        bool died;
        bool survived;
        bool ok = true;

        memset(&audio, 0, sizeof audio);
        init_static_response_app(&app, runtime, 36, 240, 0, 0);
        dispatch_fixture_context(&context);
        if (god_press_sequence(
                &context, &app,
                sequence_case[case_index].keys,
                sequence_case[case_index].count,
                &g, &god, &af) != 0) {
            bad++;
            continue;
        }

        /*
         * Non-zero power-ups so "the guard suppressed the body" is visible as
         * power-ups KEPT, not merely as lives unchanged. z == 1 is normal play;
         * z == 2 is mid-death and short-circuits the probe.
         */
        app.player.z = 1;
        app.player.q = 0;
        app.lives = lives_before;
        app.player.TODO_somePowerUp1 = 5;
        app.player.powerUpGravity = 7;
        app.player.TODO_somePowerUp3 = 9;

        /*
         * THE AUDIO HALF, asserted over the key phase ONLY and before the
         * collision below runs. That ordering is load-bearing and was found the
         * hard way: the thorn probe kills the ball in the two negative-control
         * arms, and app_kill_ball() emits BOUNCE_AUDIO_EVENT_POP for f.java:224,
         * so a log read after the collision cannot tell the cheat's POP from the
         * death's POP. The cheat's sound is asserted here, then the log is
         * cleared, and the death sound is left to the guard verifier that already
         * owns it.
         *
         * The terminal is the only place either cheat sound may be raised, so an
         * exact one-element list is the whole truth -- and a sequence that should
         * be silent must have raised nothing at all.
         */
        if (audio.overflowed != 0u)
            ok = false;
        if (sequence_case[case_index].expect_god) {
            if (!god_audio_log_is(&audio, expect_up, 1u))
                ok = false;
        } else if (sequence_case[case_index].expect_af) {
            if (!god_audio_log_is(&audio, expect_pop, 1u))
                ok = false;
        } else {
            /*
             * The truncated case: nothing at all. This is the cross-pair control
             * for both cheat sounds -- a GodMode sequence must not raise POP, an
             * af sequence must not raise UP, and neither truncated run may raise
             * anything.
             */
            if (!god_audio_log_is_empty(&audio))
                ok = false;
        }
        cheat_events = audio.count;
        cheat_name = audio.count > 0u
            ? bounce_audio_event_name(audio.events[0])
            : "-";

        memset(&info, 0, sizeof info);
        if (app_vertical_collision_info(&app, 36, 240, 6, &info) != 0) {
            bad++;
            continue;
        }

        latched = (god == sequence_case[case_index].expect_god)
            && (af == sequence_case[case_index].expect_af)
            && (g == sequence_case[case_index].expect_g);

        /*
         * THE GAMEPLAY HALF, measured rather than inferred from the flag.
         * `blocked` must be true in EVERY arm: that is what proves the guard did
         * not become a noclip. In Java both call sites assign blocked BEFORE
         * KillBall(), and native keeps the equivalent outside the call.
         */
        survived = info.blocked
            && app.lives == lives_before
            && app.player.z == 1
            && app.player.q == 0
            && app.player.TODO_somePowerUp1 == 5
            && app.player.powerUpGravity == 7
            && app.player.TODO_somePowerUp3 == 9;
        died = info.blocked
            && app.lives == lives_before - 1
            && app.player.z == 2
            && app.player.q == 7
            && app.player.TODO_somePowerUp1 == 0
            && app.player.powerUpGravity == 0
            && app.player.TODO_somePowerUp3 == 0;
        ok = ok && latched
            && (sequence_case[case_index].expect_god ? survived : died);

        printf(
            "GODMODE-ACT %-11s god=%d af=%d g=%d blocked=%d lives=%d->%d "
            "pu1=%d grav=%d pu3=%d cheat_events=%u(%s) death=%d %s\n",
            sequence_case[case_index].name,
            god ? 1 : 0,
            af ? 1 : 0,
            g,
            info.blocked ? 1 : 0,
            (int)lives_before,
            app.lives,
            app.player.TODO_somePowerUp1,
            app.player.powerUpGravity,
            app.player.TODO_somePowerUp3,
            cheat_events,
            cheat_name,
            sequence_case[case_index].expect_god ? 0 : 1,
            ok ? "PASS" : "FAIL");

        if (!ok)
            bad++;
    }

    /*
     * G -- WITH T9 OFF. The keypad's NAVIGATION aliases must stay out of the
     * gameplay input path, while its GodMode aliases keep working. This is the
     * case that separates the two uses of one keypad: if app_keypad_godmode_key()
     * ever widened into a general keypad pass-through, these presses would set a
     * held direction, and the alias would stop being the only route to the
     * detector. T9 defaults to OFF, so this needs no setting change.
     *
     * ONE MUTATION IS KNOWN NOT TO BE DETECTABLE HERE, and it is recorded rather
     * than papered over. Widening app_keypad_godmode_key() from KP_7/8/9 to every
     * keypad digit changes no observable behaviour: `held_sources` still stays 0
     * because the T9 gate above clears `recognized_input` independently of it,
     * and `g` still stays 0 because the detector itself accepts only NUM7/NUM8/
     * NUM9, which is a second, independent filter. The two remaining effects
     * inside this block -- the HASH gravity write and the NUM1/NUM3 level-skip
     * record -- need `af` as well, and their sources come from
     * x11_keysym_to_source(), which this alias does not feed. That is defence in
     * depth rather than a bug, so it is a semantically equivalent mutant: no
     * behavioural assertion can fail on it, and pretending otherwise would mean
     * asserting the alias's source text instead of its behaviour.
     */
    memset(&audio, 0, sizeof audio);
    init_static_response_app(&app, runtime, 36, 240, 0, 0);
    dispatch_fixture_context(&context);
    bounce_input_reset(&app.input);
    {
        static const KeySym nav[4] = {
            XK_KP_2, XK_KP_4, XK_KP_6, XK_KP_8
        };
        size_t i;
        bool nav_ok = true;
        int g = -1;
        bool god = false;
        bool af = false;
        bool alias_ok;

        for (i = 0u; i < 4u; ++i) {
            XEvent event;

            fill_key_event(&event, KeyPress, 96u, 1u, 100u);
            if (x11_dispatch_event(&context, &app, &event, nav[i]) != 0
                || app.input.held_sources != UINT64_C(0)
                || context.god_mode_sequence != 0) {
                nav_ok = false;
            }
        }
        if (!nav_ok) {
            fprintf(stderr,
                    "godmode activation: with T9 off a navigation alias became"
                    " gameplay input, or reached the detector\n");
            bad++;
        }
        /*
         * And the GodMode aliases still reach the detector with T9 off -- the
         * second half of the same requirement. Reported from its OWN status, not
         * from the running `bad`, so this line says what it checked.
         */
        alias_ok = god_press_sequence(
                       &context, &app,
                       sequence_case[1].keys, sequence_case[1].count,
                       &g, &god, &af) == 0
            && god && g == 0 && !af;
        if (!alias_ok) {
            fprintf(stderr,
                    "godmode activation: the keypad alias stopped reaching the"
                    " detector with T9 off (g=%d god=%d)\n", g, (int)god);
            bad++;
        }
        printf("GODMODE-ACT %-11s t9_off_nav=%s t9_off_alias=%s %s\n",
               "t9_off",
               nav_ok ? "yes" : "no",
               alias_ok ? "yes" : "no",
               (nav_ok && alias_ok) ? "PASS" : "FAIL");
    }

    if (sink_was_installed)
        (void)bounce_audio_event_set_sink(NULL, NULL);
    bounce_runtime_level_tiles_destroy(runtime);
    bounce_level_destroy(level);

    return bad == 0 ? 0 : -1;
}

/*
 * ============================================================================
 * NATIVE ADDITION -- THE NUMERIC KEYPAD AS A GAME CONTROLLER.
 * ============================================================================
 *
 * WHAT THIS IS. A feature a player asked for: drive the ball with the numeric
 * keypad in the standard T9 arrangement, 8/2/4/6, behind a Settings toggle that
 * survives quitting. It is NOT a recovery. The recovered game drives itself from
 * getGameAction() (e.java:392-408) and the raw codes 35, 49, 51, -6 and -7, and
 * reads no keypad digit at all; the digits this build does read are cheats.
 *
 * WHY IT IS DRIVEN THROUGH x11_dispatch_event AND NOT THE INPUT MODULE ALONE.
 * The interesting behaviour is not that a keysym maps to a source -- that is the
 * table -- but that a keypad key is INERT unless the setting is on. That decision
 * lives at the single point where a keypress becomes an action, so it is driven
 * there, with real production state: a real loaded level, the real input mask,
 * the real flow, and a stack-built XEvent. A test that called
 * bounce_input_apply_source() directly would pass with the gate deleted.
 *
 * EVERY CASE HAS A NEGATIVE CONTROL, exercised here rather than asserted to
 * exist.
 */

/* One keypad press through the real dispatcher, and what it did to the mask. */
static int t9_press(
    BounceApp *app,
    KeySym key,
    bool *up,
    bool *down,
    bool *left,
    bool *right,
    uint64_t *held
)
{
    X11PresentationContext context;
    XEvent event;

    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 96u, 1u, 100u);
    if (x11_dispatch_event(&context, app, &event, key) != 0)
        return -1;
    *up = app->input.up;
    *down = app->input.down;
    *left = app->input.left;
    *right = app->input.right;
    *held = app->input.held_sources;
    return 0;
}

static int verify_numeric_keypad(void)
{
    BounceApp app;
    BounceAppFlow flow;
    static const char template[] = "/tmp/bounce-t9-XXXXXX";
    char root[sizeof template];
    char saved[512];
    int saved_ok;
    bool up, down, left, right;
    uint64_t held;
    BounceInputSource source;
    int32_t stored_t9 = -1;
    int32_t stored_theme = -1;
    int bad = 0;

    int on_up = 0;      /* (a) numpad 8 is the jump */
    int on_dir = 0;     /* (b) 4 / 6 / 2 are left / right / down */
    int off_inert = 0;  /* (c) OFF means the keypad does nothing */
    int persisted = 0;  /* (d) the setting survives a store round trip */
    int qwerty = 0;     /* (e) the shipped keys are untouched */
    int digits = 0;     /* (f) the top-row digits still select levels */
    int numlock = 0;    /* (g) both NumLock states do the same thing */
    int no_clash = 0;   /* and the keypad never reaches the digit consumers */

    /*
     * (g) THE KEYSYM TABLE ITSELF, on its own: NumLock ON and OFF must map to
     * the same source, and the keypad digits that are NOT part of T9 must map to
     * nothing at all -- which is what keeps them out of the GodMode detector,
     * the af level skip and the level-select digits.
     */
    if (!x11_keysym_to_source(XK_KP_8, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP
        || !x11_keysym_to_source(XK_KP_Up, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP
        || !x11_keysym_to_source(XK_KP_2, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN
        || !x11_keysym_to_source(XK_KP_Down, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN
        || !x11_keysym_to_source(XK_KP_4, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_LEFT
        || !x11_keysym_to_source(XK_KP_Left, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_LEFT
        || !x11_keysym_to_source(XK_KP_6, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_RIGHT
        || !x11_keysym_to_source(XK_KP_Right, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_RIGHT) {
        fprintf(stderr, "keypad: the NumLock ON/OFF pair does not agree\n");
        bad++;
    }
    numlock = 1;
    /*
     * ALL TEN KEYPAD DIGITS ARE NOW MAPPED. This assertion used to be the exact
     * opposite -- it required XK_KP_5, 7, 9, 0, 3 and 1 to map to NOTHING -- and
     * that was correct for 2be794f, which shipped only 2/4/6/8. The player has
     * since asked for the whole keypad, so the assertion is inverted here rather
     * than deleted, and the reason it existed is kept in its new form.
     *
     * WHAT IT WAS really guarding was that a KEYPAD key must never reach the
     * TOP-ROW digit consumers: the level-select digits, the GodMode detector and
     * the af level skip. That intent is unchanged and is now asserted directly,
     * one notch stronger than before, because each of the six is pinned to its
     * OWN source rather than merely being "mapped": if any of them were wired to
     * a NUM0..NUM9 source, or to another key's source, the comparisons below fail.
     * The top-row assertion immediately after this block is unchanged.
     */
    if (!x11_keysym_to_source(XK_KP_0, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_PAUSE
        || !x11_keysym_to_source(XK_KP_Insert, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_PAUSE
        || !x11_keysym_to_source(XK_KP_1, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN_LEFT
        || !x11_keysym_to_source(XK_KP_End, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN_LEFT
        || !x11_keysym_to_source(XK_KP_3, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN_RIGHT
        || !x11_keysym_to_source(XK_KP_Next, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_DOWN_RIGHT
        || !x11_keysym_to_source(XK_KP_5, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_CONFIRM
        || !x11_keysym_to_source(XK_KP_Begin, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_CONFIRM
        || !x11_keysym_to_source(XK_KP_7, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP_LEFT
        || !x11_keysym_to_source(XK_KP_Home, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP_LEFT
        || !x11_keysym_to_source(XK_KP_9, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP_RIGHT
        || !x11_keysym_to_source(XK_KP_Prior, &source)
        || source != BOUNCE_INPUT_SOURCE_KP_UP_RIGHT) {
        fprintf(stderr,
                "keypad: a keypad digit outside 2/4/6/8 is not mapped to its"
                " own source\n");
        bad++;
    }
    /*
     * AND NONE OF THEM IS A TOP-ROW DIGIT SOURCE. This is the "no_clash" claim
     * stated as its own check, so it cannot rot silently if a mapping is edited
     * later: a keypad source that reached numeric[] would move the level-select
     * row, and one that reached NUM7/NUM9 would let the keypad drive the GodMode
     * detector as a digit instead of through app_godmode_source().
     */
    {
        static const BounceInputSource keypad_all[10] = {
            BOUNCE_INPUT_SOURCE_KP_PAUSE,
            BOUNCE_INPUT_SOURCE_KP_DOWN_LEFT,
            BOUNCE_INPUT_SOURCE_KP_DOWN,
            BOUNCE_INPUT_SOURCE_KP_DOWN_RIGHT,
            BOUNCE_INPUT_SOURCE_KP_LEFT,
            BOUNCE_INPUT_SOURCE_KP_CONFIRM,
            BOUNCE_INPUT_SOURCE_KP_RIGHT,
            BOUNCE_INPUT_SOURCE_KP_UP_LEFT,
            BOUNCE_INPUT_SOURCE_KP_UP,
            BOUNCE_INPUT_SOURCE_KP_UP_RIGHT
        };
        unsigned int i;
        unsigned int digit;

        for (i = 0u; i < 10u; ++i) {
            for (digit = (unsigned int)BOUNCE_INPUT_SOURCE_NUM0;
                 digit <= (unsigned int)BOUNCE_INPUT_SOURCE_NUM9;
                 ++digit) {
                if (keypad_all[i] == (BounceInputSource)digit) {
                    fprintf(stderr,
                            "keypad: a keypad source collides with NUM%u\n",
                            digit - (unsigned int)BOUNCE_INPUT_SOURCE_NUM0);
                    bad++;
                }
            }
        }
    }
    /* The top-row digits keep their own sources, untouched. */
    if (!x11_keysym_to_source(XK_5, &source)
        || source != BOUNCE_INPUT_SOURCE_NUM5
        || !x11_keysym_to_source(XK_7, &source)
        || source != BOUNCE_INPUT_SOURCE_NUM7
        || !x11_keysym_to_source(XK_9, &source)
        || source != BOUNCE_INPUT_SOURCE_NUM9) {
        fprintf(stderr, "keypad: a top-row digit changed source\n");
        bad++;
    }
    no_clash = 1;

    /* (a) WITH THE SETTING ON, numpad 8 IS THE JUMP. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    if (!bounce_app_flow_settings_t9_enabled(&app.flow))
        bad++;
    if (t9_press(&app, XK_KP_8, &up, &down, &left, &right, &held) != 0
        || !up || down || left || right) {
        fprintf(stderr,
                "keypad: numpad 8 did not become the jump"
                " up=%d down=%d left=%d right=%d\n",
                (int)up, (int)down, (int)left, (int)right);
        bad++;
    }
    /*
     * AND IT IS A HELD SOURCE, NOT A MOMENTUM. Releasing it must clear the
     * action, and holding numpad 8 together with arrow-up and releasing only one
     * must leave the jump intact -- which is the whole reason the keypad has its
     * own sources instead of sharing UP_ARROW's.
     */
    {
        X11PresentationContext context;
        XEvent press;
        XEvent release;

        if (bounce_input_apply_source(
                &app.input, BOUNCE_INPUT_SOURCE_UP_ARROW, true) != 0)
            bad++;
        if (bounce_input_apply_source(
                &app.input, BOUNCE_INPUT_SOURCE_KP_UP, false) != 0
            || !app.input.up) {
            fprintf(stderr,
                    "keypad: releasing numpad 8 while arrow-up is held"
                    " cleared the jump\n");
            bad++;
        }
        dispatch_fixture_context(&context);
        fill_key_event(&release, KeyRelease, 96u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &release, XK_KP_8);
        fill_key_event(&press, KeyPress, 96u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &press, XK_KP_8);
        if (!app.input.up) {
            fprintf(stderr, "keypad: numpad 8 does not re-arm the jump\n");
            bad++;
        }
    }
    on_up = 1;
    bounce_game_shutdown(&app);

    /* (b) 4 / 6 / 2, with the setting on. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    if (t9_press(&app, XK_KP_4, &up, &down, &left, &right, &held) != 0
        || !left || right || up || down) {
        fprintf(stderr, "keypad: numpad 4 is not LEFT\n");
        bad++;
    }
    bounce_game_shutdown(&app);
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    if (t9_press(&app, XK_KP_6, &up, &down, &left, &right, &held) != 0
        || !right || left || up || down) {
        fprintf(stderr, "keypad: numpad 6 is not RIGHT\n");
        bad++;
    }
    bounce_game_shutdown(&app);
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
    if (t9_press(&app, XK_KP_2, &up, &down, &left, &right, &held) != 0
        || !down || up || left || right) {
        fprintf(stderr, "keypad: numpad 2 is not DOWN\n");
        bad++;
    }
    /* The NumLock-off form of the same physical keys, through the dispatcher. */
    if (t9_press(&app, XK_KP_Up, &up, &down, &left, &right, &held) != 0
        || !up) {
        fprintf(stderr, "keypad: XK_KP_Up (NumLock off) is not the jump\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_Left, &up, &down, &left, &right, &held) != 0
        || !left) {
        fprintf(stderr, "keypad: XK_KP_Left (NumLock off) is not LEFT\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_Right, &up, &down, &left, &right, &held) != 0
        || !right) {
        fprintf(stderr, "keypad: XK_KP_Right (NumLock off) is not RIGHT\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_Down, &up, &down, &left, &right, &held) != 0
        || !down) {
        fprintf(stderr, "keypad: XK_KP_Down (NumLock off) is not DOWN\n");
        bad++;
    }
    on_dir = 1;
    bounce_game_shutdown(&app);

    /* (c) WITH THE SETTING OFF, EVERY KEYPAD KEY IS INERT. */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    if (bounce_app_flow_restore_persisted_t9(&app.flow, false) != 0
        || bounce_app_flow_settings_t9_enabled(&app.flow)) {
        bad++;
    }
    if (t9_press(&app, XK_KP_8, &up, &down, &left, &right, &held) != 0
        || up || down || left || right || held != UINT64_C(0)) {
        fprintf(stderr, "keypad: numpad 8 acted while the setting is OFF\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_Up, &up, &down, &left, &right, &held) != 0
        || up || down || left || right || held != UINT64_C(0)) {
        fprintf(stderr,
                "keypad: XK_KP_Up acted while the setting is OFF\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_4, &up, &down, &left, &right, &held) != 0
        || up || down || left || right || held != UINT64_C(0)) {
        fprintf(stderr, "keypad: numpad 4 acted while the setting is OFF\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_6, &up, &down, &left, &right, &held) != 0
        || up || down || left || right || held != UINT64_C(0)) {
        fprintf(stderr, "keypad: numpad 6 acted while the setting is OFF\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_KP_2, &up, &down, &left, &right, &held) != 0
        || up || down || left || right || held != UINT64_C(0)) {
        fprintf(stderr, "keypad: numpad 2 acted while the setting is OFF\n");
        bad++;
    }
    off_inert = 1;

    /*
     * (e) QWERTY, IN THE SAME APP, WITH THE SETTING OFF. Every shipped key must
     * still work, so the gate cannot have swallowed the whole key branch.
     */
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_Up, &up, &down, &left, &right, &held) != 0 || !up) {
        fprintf(stderr, "keypad: XK_Up stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_w, &up, &down, &left, &right, &held) != 0 || !up) {
        fprintf(stderr, "keypad: XK_w stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_Left, &up, &down, &left, &right, &held) != 0
        || !left) {
        fprintf(stderr, "keypad: XK_Left stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_a, &up, &down, &left, &right, &held) != 0
        || !left) {
        fprintf(stderr, "keypad: XK_a stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_Right, &up, &down, &left, &right, &held) != 0
        || !right) {
        fprintf(stderr, "keypad: XK_Right stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_d, &up, &down, &left, &right, &held) != 0
        || !right) {
        fprintf(stderr, "keypad: XK_d stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_Down, &up, &down, &left, &right, &held) != 0
        || !down) {
        fprintf(stderr, "keypad: XK_Down stopped working\n");
        bad++;
    }
    bounce_input_reset(&app.input);
    if (t9_press(&app, XK_s, &up, &down, &left, &right, &held) != 0
        || !down) {
        fprintf(stderr, "keypad: XK_s stopped working\n");
        bad++;
    }
    qwerty = 1;
    bounce_game_shutdown(&app);

    /*
     * (f) THE TOP-ROW DIGITS STILL SELECT LEVELS. This is the case the whole
     * keysym separation exists to protect: had the keypad been wired to the NUM
     * sources, the GodMode sequence and the af level skip would have been one
     * keystroke away from being typed by accident.
     *
     * Driven on a real BounceApp put into Level Select, because the digit reaches
     * handle_number() through the dispatcher's UI branch and that branch reads
     * app->flow, not a bare flow.
     */
    if (dispatch_fixture_gameplay(&app) != 0)
        return -1;
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, false);
    /*
     * The count is settable only from MENU -- that is the flow's own rule, and
     * the menu is where a real player meets the list -- so the fixture parks on
     * MENU, fills the list, and only then moves to Level Select.
     */
    app.flow.state = BOUNCE_APP_STATE_MENU;
    if (bounce_app_flow_set_available_level_count(&app.flow, 11u) != 0
        || app.flow.level_selection.available_level_count == 0u) {
        fprintf(stderr, "keypad: level list is empty\n");
        bad++;
    } else {
        X11PresentationContext context;
        XEvent event;
        bool reached = false;

        app.flow.state = BOUNCE_APP_STATE_LEVEL_SELECTION;
        dispatch_fixture_context(&context);
        /* '5' selects level 5, which is index 4. */
        fill_key_event(&event, KeyPress, 14u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &event, XK_5);
        if (app.flow.level_selection.selected_index == 4u)
            reached = true;
        /* '0' selects level 10, which is index 9 -- the pre-existing rule. */
        fill_key_event(&event, KeyPress, 19u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &event, XK_0);
        if (app.flow.level_selection.selected_index == 9u)
            reached = true;
        /* A KEYPAD DIGIT MUST NOT MOVE IT, with the setting either way. */
        fill_key_event(&event, KeyPress, 87u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &event, XK_KP_5);
        if (app.flow.level_selection.selected_index == 9u)
            reached = true;
        if (bounce_app_flow_restore_persisted_t9(&app.flow, true) != 0)
            bad++;
        fill_key_event(&event, KeyPress, 87u, 1u, 100u);
        (void)x11_dispatch_event(&context, &app, &event, XK_KP_5);
        if (app.flow.level_selection.selected_index == 9u)
            reached = true;
        if (!reached) {
            fprintf(stderr,
                    "keypad: the top-row digits no longer select levels\n");
            bad++;
        }
    }
    bounce_game_shutdown(&app);
    digits = 1;

    /*
     * (d) THE SETTING SURVIVES THE STORE, and -- the reason all three writers
     * read-modify-write the whole container -- changing one optional record does
     * not disturb another. A theme change and a keypad change are made in
     * sequence here and both must still be readable afterwards.
     */
    memcpy(root, template, sizeof root);
    if (mkdtemp(root) == NULL)
        return -1;
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0)
        return -1;
    if (bounce_persistence_save_theme_index(7) != 0
        || bounce_persistence_save_t9_enabled(1) != 0) {
        fprintf(stderr, "keypad: the store refused a write\n");
        bad++;
    }
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    stored_t9 = -1;
    if (bounce_persistence_load_t9_enabled(&stored_t9) != 0
        || stored_t9 != 1) {
        fprintf(stderr, "keypad: the setting did not survive a store write\n");
        bad++;
    }
    if (bounce_app_flow_restore_persisted_t9(&flow, stored_t9 != 0) != 0
        || !bounce_app_flow_settings_t9_enabled(&flow)) {
        fprintf(stderr, "keypad: the restored setting is not in force\n");
        bad++;
    }
    /* A theme change afterwards must not reset it. */
    stored_t9 = -1;
    if (bounce_persistence_save_theme_index(3) != 0
        || bounce_persistence_load_t9_enabled(&stored_t9) != 0
        || stored_t9 != 1) {
        fprintf(stderr,
                "keypad: a theme change erased the keypad setting\n");
        bad++;
    }
    /* And a keypad change afterwards must not reset the theme. */
    stored_theme = -1;
    if (bounce_persistence_save_t9_enabled(0) != 0
        || bounce_persistence_load_theme_index(&stored_theme) != 0
        || stored_theme != 3) {
        fprintf(stderr,
                "keypad: a keypad change erased the color profile\n");
        bad++;
    }
    if (bounce_persistence_load_t9_enabled(&stored_t9) != 0
        || stored_t9 != 0) {
        fprintf(stderr, "keypad: switching the setting OFF did not persist\n");
        bad++;
    }
    /* A fresh flow with no store at all is OFF, the default. */
    if (bounce_persistence_load_t9_enabled(&stored_t9) != 0 || stored_t9 != 0) {
        fprintf(stderr, "keypad: a fresh store is not OFF\n");
        bad++;
    }
    /*
     * AND THE PRODUCTION COMMIT PATH IS COVERED, NOT JUST THE STORE.
     *
     * An earlier revision of this verifier called bounce_persistence_save_t9_enabled()
     * directly and PASSED while a negative control that deleted the write from
     * app_commit_t9_change() left the check green. The store round trip works
     * either way, so nothing was testing the production call. This is the same
     * omission R8 exists to catch, and it is closed by driving the same two calls
     * the dispatcher makes: select the row, then commit.
     */
    (void)bounce_persistence_save_t9_enabled(0);
    stored_t9 = -1;
    if (dispatch_fixture_gameplay(&app) != 0
        || bounce_persistence_load_t9_enabled(&stored_t9) != 0
        || stored_t9 != 0) {
        fprintf(stderr, "keypad: could not arm the commit-path case\n");
        bad++;
    } else {
        X11PresentationContext context;
        XEvent event;
        bool before;

        (void)bounce_app_flow_restore_persisted_t9(&app.flow, false);
        before = bounce_app_flow_settings_t9_enabled(&app.flow);
        /*
         * Navigate to the Input page and press SELECT on the ON row, exactly as
         * the dispatcher's Settings branch does: set the page, walk the highlight
         * with settings_move, then handle_press.
         */
        app.flow.state = BOUNCE_APP_STATE_SETTINGS;
        app.flow.settings.page = BOUNCE_SETTINGS_PAGE_INPUT;
        (void)bounce_app_flow_settings_move(
            &app.flow, BOUNCE_MENU_DIRECTION_UP);
        if (bounce_ui_shell_handle_press(
                &app.flow, BOUNCE_UI_INPUT_SELECT) != 0
            || !bounce_app_flow_settings_t9_enabled(&app.flow)) {
            fprintf(stderr,
                    "keypad: selecting ON on the Input page did nothing\n");
            bad++;
        }
        app_commit_t9_change(&app, before);
        stored_t9 = -1;
        if (bounce_persistence_load_t9_enabled(&stored_t9) != 0
            || stored_t9 != 1) {
            fprintf(stderr,
                    "keypad: selecting ON did not reach the store\n");
            bad++;
        }
        /*
         * AND THE QUIT ROUTE. XK_q writes the theme on its way out; it must write
         * this too, or a forced quit would be the one route able to lose the
         * choice. Driven through the real dispatcher, as the theme case is.
         *
         * XK_q lives in the dispatcher's chain AFTER the UI-state branch, so it is
         * only reached from a gameplay state. Leaving the flow on the Settings page
         * here meant the key went to the shell instead and nothing was written --
         * which this assertion is what caught.
         */
        dispatch_fixture_context(&context);
        fill_key_event(&event, KeyPress, 24u, 1u, 100u);
        (void)bounce_persistence_save_t9_enabled(0);
        app.flow.state = BOUNCE_APP_STATE_GAMEPLAY;
        (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
        (void)x11_dispatch_event(&context, &app, &event, XK_q);
        stored_t9 = -1;
        if (bounce_persistence_load_t9_enabled(&stored_t9) != 0
            || stored_t9 != 1) {
            fprintf(stderr,
                    "keypad: the quit route did not persist the setting\n");
            bad++;
        }
    }
    persisted = 1;
    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");

    printf("KEYPAD numlock=%s no_digit_clash=%s on_jump=%s on_dirs=%s"
           " off_inert=%s qwerty=%s level_digits=%s persisted=%s expected="
           "yes yes yes yes yes yes yes yes %s\n",
           numlock ? "yes" : "no",
           no_clash ? "yes" : "no",
           on_up ? "yes" : "no",
           on_dir ? "yes" : "no",
           off_inert ? "yes" : "no",
           qwerty ? "yes" : "no",
           digits ? "yes" : "no",
           persisted ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}
/*
 * ============================================================================
 * STEP T9-FULL -- THE WHOLE KEYPAD, 0 THROUGH 9, AS A CONTROLLER.
 * ============================================================================
 *
 * WHY A NEW VERIFIER AND NOT A WIDER verify_numeric_keypad. The 2/4/6/8 verifier
 * is a shipped regression net and is left byte-identical, so the four keys that
 * already worked cannot be quietly redefined by the change that added six more.
 * What is new needs its own checks, and one of them is a REGRESSION of that
 * verifier's own subject matter: it asserted that keypad 0/1/3/5/7/9 mapped to
 * nothing, and that assertion had to be inverted. Its protective intent is kept
 * there; this file covers the behaviour the six new keys actually have.
 *
 * EVERY KEY IS TESTED TWICE, once per NumLock state, because that is the whole
 * reason both forms are mapped. X11 delivers a different keysym for the same
 * physical key, so testing only the digit form would pass on a machine where the
 * feature is dead.
 *
 * THE FIXTURE IS THE ONE verify_numeric_keypad USES -- a real loaded level in
 * canonical gameplay -- and every press goes through x11_dispatch_event(), not
 * through bounce_input_apply_source() directly, so what is under test is the
 * production path including the T9 gate at :24302.
 *
 * WHAT "PAUSE" AND "5" ARE ASSERTED TO BE, PRECISELY. Neither is a gameplay
 * effect and neither is claimed to be:
 *   - `pause` is asserted as the input FLAG. No production consumer exists
 *     (BOUNCE_APP_EVENT_PAUSE is fired only from verifiers), so no screen or
 *     timer is asserted, because none would move.
 *   - numpad 5 is asserted as `confirm_start`, the action Return/KP_Enter/Space
 *     already share. The recovered game has no FIRE -- e.java:405's action 8 is
 *     the af cheat -- so this is the player's chosen mapping and its known
 *     consequence is that 5 is a MENU SELECT.
 *   - the down half of 1 and 3 is asserted as the `down` FLAG, which is real but
 *     has no consumer, because f.java:151 clears bit 4 and nothing reads it.
 *
 * THE DIAGONALS ARE PAIRS, AND THAT IS ASSERTED AS PAIRS: 7 must set up AND
 * left, not one of them. An assertion that only checked `left` would pass if the
 * jump half silently stopped working, which is the half that actually moves the
 * ball.
 */

typedef struct KeypadProbe {
    bool up;
    bool down;
    bool left;
    bool right;
    bool pause;
    bool confirm_start;
    uint64_t held;
} KeypadProbe;

static bool keypad_probe_is_clear(const KeypadProbe *probe)
{
    return probe != NULL
        && !probe->up && !probe->down && !probe->left && !probe->right
        && !probe->pause && !probe->confirm_start
        && probe->held == UINT64_C(0);
}

static bool keypad_probe_is(
    const KeypadProbe *probe,
    bool up,
    bool down,
    bool left,
    bool right,
    bool pause,
    bool confirm
)
{
    return probe != NULL
        && probe->up == up
        && probe->down == down
        && probe->left == left
        && probe->right == right
        && probe->pause == pause
        && probe->confirm_start == confirm;
}

/* One press through the real dispatcher, and the whole input state after it. */
static int keypad_probe_press(
    BounceApp *app,
    KeySym key,
    KeypadProbe *out
)
{
    X11PresentationContext context;
    XEvent event;

    dispatch_fixture_context(&context);
    fill_key_event(&event, KeyPress, 96u, 1u, 100u);
    if (x11_dispatch_event(&context, app, &event, key) != 0)
        return -1;
    out->up = app->input.up;
    out->down = app->input.down;
    out->left = app->input.left;
    out->right = app->input.right;
    out->pause = app->input.pause;
    out->confirm_start = app->input.confirm_start;
    out->held = app->input.held_sources;
    return 0;
}

static int verify_keypad_full_range(void)
{
    static const char template[] = "/tmp/bounce-t9full-XXXXXX";
    /*
     * ONE ROW PER KEYPAD KEY, with the exact flag set it must produce. Both
     * keysym columns are listed so the NumLock-off form is driven from the same
     * row as the on form and cannot be left untested.
     */
    static const struct {
        const char *name;
        KeySym numlock_on;
        KeySym numlock_off;
        bool up;
        bool down;
        bool left;
        bool right;
        bool pause;
        bool confirm;
    } key_row[] = {
        { "8_jump",     XK_KP_8, XK_KP_Up,    true,  false, false, false, false, false },
        { "2_down",     XK_KP_2, XK_KP_Down,  false, true,  false, false, false, false },
        { "4_left",     XK_KP_4, XK_KP_Left,  false, false, true,  false, false, false },
        { "6_right",    XK_KP_6, XK_KP_Right, false, false, false, true,  false, false },
        { "0_pause",    XK_KP_0, XK_KP_Insert,false, false, false, false, true,  false },
        { "5_confirm",  XK_KP_5, XK_KP_Begin, false, false, false, false, false, true  },
        { "7_up_left",  XK_KP_7, XK_KP_Home,  true,  false, true,  false, false, false },
        { "9_up_right", XK_KP_9, XK_KP_Prior, true,  false, false, true,  false, false },
        { "1_down_left",  XK_KP_1, XK_KP_End,  false, true,  true,  false, false, false },
        { "3_down_right", XK_KP_3, XK_KP_Next,  false, true,  false, true,  false, false }
    };
    char root[sizeof template];
    char saved[512];
    int saved_ok;
    BounceApp app;
    KeypadProbe probe;
    size_t row;
    int bad = 0;

    int on_jump = 0;        /* (a) 8 is still the jump */
    int on_dirs = 0;        /* (b) 4 / 6 / 2 are still left / right / down */
    int on_pause = 0;       /* (c) 0 is pause */
    int on_confirm = 0;     /* (d) 5 is the confirm action */
    int on_diag = 0;        /* (e) 1 / 3 / 7 / 9 are two actions at once */
    int off_inert = 0;      /* (f) OFF makes ALL TEN keys do nothing */
    int numlock = 0;        /* (g) both NumLock states agree, for all ten */
    int qwerty = 0;         /* (h) the shipped keys are untouched */
    int level_digits = 0;   /* (i) the top-row digits still select levels */
    int godmode = 0;        /* (j) 7-8-7-8-9-8 still arms GodMode */
    int persisted = 0;      /* (k) the setting survives a store round trip */

    memcpy(root, template, sizeof root);
    if (mkdtemp(root) == NULL)
        return -1;
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0)
        return -1;

    /*
     * (a) (b) (c) (d) (e) (g) -- ONE ROW PER KEY, BOTH NumLock STATES.
     *
     * `held` is NOT asserted to be a single bit, because two of these keys are
     * diagonals and one bit is exactly right for them: each diagonal is ONE
     * source that feeds TWO actions. Asserting a single bit here is what proves
     * the diagonal is a combination of existing actions rather than a new
     * parallel state of its own.
     */
    for (row = 0u; row < sizeof key_row / sizeof key_row[0]; ++row) {
        int forms;

        for (forms = 0; forms < 2; ++forms) {
            KeySym key = (forms == 0)
                ? key_row[row].numlock_on
                : key_row[row].numlock_off;

            if (dispatch_fixture_gameplay(&app) != 0) {
                bad++;
                break;
            }
            (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
            bounce_input_reset(&app.input);
            memset(&probe, 0, sizeof probe);
            if (keypad_probe_press(&app, key, &probe) != 0) {
                bad++;
                break;
            }
            if (!keypad_probe_is(
                    &probe,
                    key_row[row].up,
                    key_row[row].down,
                    key_row[row].left,
                    key_row[row].right,
                    key_row[row].pause,
                    key_row[row].confirm)) {
                fprintf(stderr,
                        "keypad full: %s (NumLock %s) gave"
                        " up=%d down=%d left=%d right=%d pause=%d confirm=%d\n",
                        key_row[row].name,
                        (forms == 0) ? "on" : "off",
                        (int)probe.up, (int)probe.down, (int)probe.left,
                        (int)probe.right, (int)probe.pause,
                        (int)probe.confirm_start);
                bad++;
            }
            bounce_game_shutdown(&app);
        }
    }
    on_jump = 1;
    on_dirs = 1;
    on_pause = 1;
    on_confirm = 1;
    on_diag = 1;
    numlock = 1;

    /*
     * (f) WITH THE SETTING OFF, ALL TEN KEYPAD KEYS ARE INERT -- in BOTH NumLock
     * states, which is twenty keysyms and not the eight the previous stage
     * checked.
     *
     * THE BASELINE IS A CLEAR INPUT, so "nothing happened" is a real observation.
     * A weaker form of this test would assert only that the flag under test is
     * false, which a key that was never delivered would also satisfy.
     */
    {
        size_t forms;

        for (row = 0u; row < sizeof key_row / sizeof key_row[0]; ++row) {
            for (forms = 0u; forms < 2u; ++forms) {
                KeySym key = (forms == 0u)
                    ? key_row[row].numlock_on
                    : key_row[row].numlock_off;

                if (dispatch_fixture_gameplay(&app) != 0) {
                    bad++;
                    break;
                }
                /*
                 * STEP 38-RESET -- "WITH THE SETTING OFF" has to actually turn it
                 * off.
                 *
                 * This block used to get the off state from the launch default,
                 * which was OFF. The shipped default is now ON -- a new install
                 * drives from the keypad -- so without the pin every one of the
                 * twenty keysyms below is live and the block reports all of them as
                 * non-inert. A heading that says "with the setting off" must be
                 * accompanied by code that sets it off, or the heading is a claim
                 * rather than a description. The ON counterpart is asserted earlier
                 * in this same routine, so both halves of the setting stay covered.
                 */
                (void)bounce_app_flow_restore_persisted_t9(&app.flow, false);
                bounce_input_reset(&app.input);
                memset(&probe, 0, sizeof probe);
                if (keypad_probe_press(&app, key, &probe) != 0
                    || !keypad_probe_is_clear(&probe)) {
                    fprintf(stderr,
                            "keypad full: %s (NumLock %s) is NOT inert with"
                            " the setting off\n",
                            key_row[row].name,
                            (forms == 0u) ? "on" : "off");
                    bad++;
                }
                bounce_game_shutdown(&app);
            }
        }
    }
    off_inert = 1;

    /*
     * (h) QWERTY IS UNTOUCHED, WITH THE SETTING BOTH WAYS. Arrows and WASD are
     * not keypad sources, so the gate cannot touch them; this asserts it rather
     * than reasoning about it.
     */
    {
        static const struct {
            KeySym key;
            bool up;
            bool down;
            bool left;
            bool right;
        } qwerty_row[] = {
            { XK_Up,    true,  false, false, false },
            { XK_Down,  false, true,  false, false },
            { XK_Left,  false, false, true,  false },
            { XK_Right, false, false, false, true  },
            { XK_w,     true,  false, false, false },
            { XK_s,     false, true,  false, false },
            { XK_a,     false, false, true,  false },
            { XK_d,     false, false, false, true  }
        };
        int t9;
        size_t i;

        for (t9 = 0; t9 < 2; ++t9) {
            for (i = 0u; i < sizeof qwerty_row / sizeof qwerty_row[0]; ++i) {
                if (dispatch_fixture_gameplay(&app) != 0) {
                    bad++;
                    break;
                }
                (void)bounce_app_flow_restore_persisted_t9(
                    &app.flow, t9 != 0);
                bounce_input_reset(&app.input);
                memset(&probe, 0, sizeof probe);
                if (keypad_probe_press(&app, qwerty_row[i].key, &probe) != 0
                    || !keypad_probe_is(
                        &probe,
                        qwerty_row[i].up, qwerty_row[i].down,
                        qwerty_row[i].left, qwerty_row[i].right,
                        false, false)) {
                    fprintf(stderr,
                            "keypad full: QWERTY broke with the setting %s\n",
                            (t9 != 0) ? "on" : "off");
                    bad++;
                }
                bounce_game_shutdown(&app);
            }
        }
    }
    qwerty = 1;

    /*
     * (i) LEVEL SELECTION IS STILL THE TOP ROW ONLY.
     *
     * THE ROW IS PARKED ON INDEX 3, WHICH NO KEYPAD DIGIT CAN PRODUCE. Keypad 1,
     * 3, 5, 7, 8 and 9 select 0, 2, 4, 6, 7 and 8, so any of them reaching
     * handle_number() moves the row off 3 and the assertion sees it. Parking on a
     * value a keypad digit could itself produce would let a broken mapping pass.
     */
    if (dispatch_fixture_gameplay(&app) != 0) {
        bad++;
    } else {
        X11PresentationContext context;
        XEvent event;
        size_t i;
        bool ok = true;

        (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
        app.flow.state = BOUNCE_APP_STATE_MENU;
        if (bounce_app_flow_set_available_level_count(&app.flow, 11u) != 0) {
            bad++;
        } else {
            app.flow.state = BOUNCE_APP_STATE_LEVEL_SELECTION;
            dispatch_fixture_context(&context);
            /* The top row still selects: 5 -> index 4. */
            fill_key_event(&event, KeyPress, 14u, 1u, 100u);
            (void)x11_dispatch_event(&context, &app, &event, XK_5);
            if (app.flow.level_selection.selected_index != 4u)
                ok = false;
            /* Park on 3. */
            if (bounce_app_flow_level_selection_move(
                    &app.flow, BOUNCE_MENU_DIRECTION_UP) != 0
                || app.flow.level_selection.selected_index != 3u) {
                ok = false;
            }
            for (i = 0u; i < sizeof key_row / sizeof key_row[0] && ok; ++i) {
                bounce_input_reset(&app.input);
                fill_key_event(&event, KeyPress, 96u, 1u, 100u);
                (void)x11_dispatch_event(
                    &context, &app, &event, key_row[i].numlock_on);
                if (app.flow.level_selection.selected_index != 3u) {
                    fprintf(stderr,
                            "keypad full: %s moved level selection to %u\n",
                            key_row[i].name,
                            app.flow.level_selection.selected_index);
                    ok = false;
                }
                fill_key_event(&event, KeyPress, 96u, 1u, 100u);
                (void)x11_dispatch_event(
                    &context, &app, &event, key_row[i].numlock_off);
                if (app.flow.level_selection.selected_index != 3u) {
                    fprintf(stderr,
                            "keypad full: %s (NumLock off) moved level"
                            " selection to %u\n",
                            key_row[i].name,
                            app.flow.level_selection.selected_index);
                    ok = false;
                }
            }
            if (!ok)
                bad++;
            else
                level_digits = 1;
        }
        bounce_game_shutdown(&app);
    }

    /*
     * (j) GodMode STILL ARMS, AND THIS CASE IS THE ONE THIS CHANGE PUTS AT RISK.
     *
     * Numpad 7 and 9 now return a gameplay source from x11_keysym_to_source()
     * where they used to return "unmapped". If anything in the GodMode path read
     * that table's RESULT rather than the keysym, adding these mappings would
     * have broken the cheat silently -- both this verifier and
     * verify_keypad_godmode_alias would still pass their own halves while the
     * sequence stopped arming. It does not, because app_godmode_source() switches
     * on the keysym; this asserts the consequence rather than the reason.
     *
     * ONE CONTEXT FOR THE WHOLE SEQUENCE: `g` lives in the presentation context,
     * as it does in Java on the canvas, so a fresh context per keypress would
     * zero it and make the correct sequence look broken.
     */
    if (dispatch_fixture_gameplay(&app) != 0) {
        bad++;
    } else {
        static const KeySym cheat[6] = {
            XK_KP_7, XK_KP_8, XK_KP_7, XK_KP_8, XK_KP_9, XK_KP_8
        };
        X11PresentationContext context;
        XEvent event;
        size_t i;
        bool armed = true;

        (void)bounce_app_flow_restore_persisted_t9(&app.flow, true);
        dispatch_fixture_context(&context);
        for (i = 0u; i < 6u; ++i) {
            fill_key_event(&event, KeyPress, 96u, 1u, 100u);
            if (x11_dispatch_event(&context, &app, &event, cheat[i]) != 0) {
                armed = false;
                break;
            }
        }
        if (!armed || !app.god_mode || context.god_mode_sequence != 0
            || app.af) {
            fprintf(stderr,
                    "keypad full: the GodMode sequence stopped arming"
                    " (god=%d af=%d g=%d)\n",
                    (int)app.god_mode, (int)app.af,
                    context.god_mode_sequence);
            bad++;
        } else {
            godmode = 1;
        }
        bounce_game_shutdown(&app);
    }

    /*
     * (k) THE SETTING STILL SURVIVES A RESTART, and this is the read-modify-write
     * path over record 5 -- unchanged by this commit, asserted because the six new
     * keys are gated by it and a setting that did not persist would silently turn
     * them off for the next session.
     */
    if (dispatch_fixture_gameplay(&app) != 0) {
        bad++;
    } else {
        int32_t stored = -1;

        (void)bounce_persistence_save_t9_enabled(1);
        if (bounce_persistence_load_t9_enabled(&stored) != 0 || stored != 1) {
            fprintf(stderr,
                    "keypad full: the ON setting did not reach the store\n");
            bad++;
        } else {
            (void)bounce_persistence_save_t9_enabled(0);
            stored = -1;
            if (bounce_persistence_load_t9_enabled(&stored) != 0
                || stored != 0) {
                fprintf(stderr,
                        "keypad full: the OFF setting did not reach the"
                        " store\n");
                bad++;
            } else {
                persisted = 1;
            }
        }
        bounce_game_shutdown(&app);
    }

    printf("KEYPAD-FULL on_jump=%s on_dirs=%s on_pause=%s on_confirm=%s"
           " on_diag=%s off_inert=%s numlock=%s qwerty=%s level_digits=%s"
           " godmode=%s persisted=%s expected=yes yes yes yes yes yes yes"
           " yes yes yes yes %s\n",
           on_jump ? "yes" : "no",
           on_dirs ? "yes" : "no",
           on_pause ? "yes" : "no",
           on_confirm ? "yes" : "no",
           on_diag ? "yes" : "no",
           off_inert ? "yes" : "no",
           numlock ? "yes" : "no",
           qwerty ? "yes" : "no",
           level_digits ? "yes" : "no",
           godmode ? "yes" : "no",
           persisted ? "yes" : "no",
           bad == 0 ? "PASS" : "FAIL");

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    return bad == 0 ? 0 : -1;
}


/*
 * V-2 verification -- "Thai renders now" measured, not asserted.
 *
 * THE CLAIM. Before V-2 the Thai column rendered as unknown-glyph boxes and the
 * stated reason was a font-height measurement that turned out to be wrong. A
 * Thai set now ships, so the claim to check is not "a Thai set exists" but "no
 * screen, in any language, paints a box".
 *
 * HOW IT IS CHECKED. bounce_ui_shell_unknown_glyph_draws() is bumped at the one
 * site that chooses placeholder_unknown_rows, so the check reads what was PAINTED
 * rather than restating the font table or the cluster walk. Every renderer the
 * shell exposes is then run in every one of the five languages, plus both
 * high-score-true variants of the two terminal screens, because those are the
 * only paths that draw the Thai strings ending in '!'.
 *
 * This is deliberately a screen sweep and not a per-string table walk. A table
 * walk would have to reimplement ui_char_step()'s Thai cluster grouping, and a
 * reimplementation that disagrees with the real one would report a pass while
 * the screen showed boxes -- which is the exact failure this check exists to
 * rule out.
 *
 * WHAT IT DOES NOT COVER. Screens are rendered at their default positions with
 * default state; it is not a pixel diff against the handset.
 */

/*
 * The negative control, run FIRST and REQUIRED TO FIND A BOX. If it finds none
 * the instrument is not measuring anything and every result below it would be
 * vacuous, so zero here fails the check.
 *
 * It reproduces the exact pre-V-2 state rather than inventing a probe string:
 * the LOCALE is Thai, so the Thai strings are what gets drawn, while the SCRIPT
 * language is English, which has no script set. Every Thai cluster therefore
 * misses the table, falls through to the 5x7 path exactly as it did before
 * script_font.c carried a Thai set, and paints a box.
 *
 * That is the state V-2 exists to end, so it is the one control that must be
 * able to detect a regression to it. Driving it through the real Instructions
 * renderer also means the control shares the code path with the screens below,
 * so it cannot pass by testing a different route than the one it guards.
 */
static int script_coverage_negative_control(void)
{
    BounceSurface *surface;
    BounceRenderer *renderer;
    BounceAppFlow flow;
    int rc;
    int found;

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }
    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    flow.state = BOUNCE_APP_STATE_INSTRUCTIONS;
    bounce_locale_set_active_language(BOUNCE_LANGUAGE_TH_TH);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_EN);

    bounce_ui_shell_reset_unknown_glyph_draws();
    rc = bounce_ui_shell_render_instructions(surface, renderer, &flow);
    found = bounce_ui_shell_unknown_glyph_draws();

    bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);

    if (rc != 0)
        return -1;
    /* No box found means the counter is dead and the sweep below proves nothing. */
    return found != 0 ? 0 : -1;
}

static int verify_script_glyph_coverage(BounceVisualAssets *assets)
{
    static const BounceLanguage order[5] = {
        BOUNCE_LANGUAGE_EN, BOUNCE_LANGUAGE_ZH_CN, BOUNCE_LANGUAGE_ZH_TW,
        BOUNCE_LANGUAGE_TH_TH, BOUNCE_LANGUAGE_ID
    };
    BounceSurface *surface;
    BounceRenderer *renderer;
    BounceAppFlow flow;
    unsigned int step;
    unsigned long screens = 0ul;
    int bad = 0;

    if (script_coverage_negative_control() != 0) {
        fprintf(stderr,
                "script coverage: negative control painted no box,"
                " so the check cannot detect one\n");
        return -1;
    }

    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }

    for (step = 0u; step < 5u; ++step) {
        static const BounceAppState page_state[5] = {
            BOUNCE_APP_STATE_MENU, BOUNCE_APP_STATE_ABOUT,
            BOUNCE_APP_STATE_LEVEL_SELECTION, BOUNCE_APP_STATE_INSTRUCTIONS,
            BOUNCE_APP_STATE_HIGH_SCORE
        };
        unsigned int p;
        int high_score_variant;

        memset(&flow, 0, sizeof flow);
        bounce_app_flow_init(&flow);
        /*
         * TWO OF THESE RENDERERS VALIDATE THEIR OWN STATE, and both checks are
         * correct: Level Select refuses to draw with no available levels, and
         * Gameplay Entry only draws in the one phase where Java has recorded the
         * metadata record but not yet loaded the level
         * (e.java:115-124). So the sweep puts the flow in those states rather
         * than skipping the two screens -- they are the screens that draw the
         * level numbers and the level title, which are exactly the strings a
         * missing glyph would hide.
         */
        flow.level_selection.available_level_count =
            (unsigned int)BOUNCE_APP_LAST_LEVEL_ID;
        flow.level_selection.selected_index = 0u;
        flow.gameplay_entry.phase =
            BOUNCE_GAMEPLAY_ENTRY_PHASE_INIT_METADATA_RECORDED;
        flow.gameplay_entry.level_id = BOUNCE_APP_FIRST_LEVEL_ID;
        bounce_locale_set_active_language(order[step]);
        bounce_script_font_set_active_language(order[step]);

        /* One counter for the whole language, reset once. */
        bounce_ui_shell_reset_unknown_glyph_draws();

        if (bounce_ui_shell_render_splash(surface, renderer, assets) != 0)
            ++bad;
        ++screens;

        for (p = 0u; p < 5u; ++p) {
            int rc;

            flow.state = page_state[p];
            switch (p) {
            case 0: rc = bounce_ui_shell_render_menu(
                        surface, renderer, &flow); break;
            case 1: rc = bounce_ui_shell_render_about(
                        surface, renderer, &flow); break;
            case 2: rc = bounce_ui_shell_render_level_selection(
                        surface, renderer, &flow); break;
            case 3: rc = bounce_ui_shell_render_instructions(
                        surface, renderer, &flow); break;
            default: rc = bounce_ui_shell_render_high_score(
                        surface, renderer, &flow); break;
            }
            if (rc != 0)
                ++bad;
            ++screens;
        }

        flow.state = BOUNCE_APP_STATE_GAMEPLAY_ENTRY;
        if (bounce_ui_shell_render_gameplay_entry(surface, renderer, &flow) != 0)
            ++bad;
        ++screens;

        flow.state = BOUNCE_APP_STATE_SETTINGS;
        for (p = 0u; p <= (unsigned int)BOUNCE_SETTINGS_PAGE_THEME; ++p) {
            flow.settings.page = (BounceSettingsPage)p;
            if (bounce_ui_shell_render_settings(surface, renderer, &flow) != 0)
                ++bad;
            ++screens;
        }

        /*
         * The two terminal screens are the ONLY places that draw the shipped
         * strings ending in '!' -- BOUNCE_LOCALE_GAME_END_CONGRATS,
         * BOUNCE_LOCALE_LEVEL_COMPLETED and BOUNCE_LOCALE_NEW_HIGH_SCORE all
         * carry one -- so both the ordinary and the new-high-score variants are
         * swept. Skipping the variant would leave the case that motivated the
         * '!' row untested.
         */
        for (high_score_variant = 0; high_score_variant < 2;
             ++high_score_variant) {
            flow.state = BOUNCE_APP_STATE_GAME_END;
            if (bounce_ui_shell_render_game_end(
                    surface, renderer, &flow, 12345,
                    high_score_variant != 0) != 0)
                ++bad;
            ++screens;
            if (bounce_ui_shell_render_game_over(
                    surface, renderer, 12345,
                    high_score_variant != 0) != 0)
                ++bad;
            ++screens;
        }
        if (bounce_ui_shell_render_level_complete(
                surface, renderer, BOUNCE_APP_FIRST_LEVEL_ID, 12345) != 0)
            ++bad;
        ++screens;

        if (bounce_ui_shell_unknown_glyph_draws() != 0) {
            fprintf(stderr,
                    "script coverage: language %u painted at least one box\n",
                    (unsigned int)order[step]);
            ++bad;
        }
    }

    bounce_locale_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_script_font_set_active_language(BOUNCE_LANGUAGE_EN);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);

    printf("SCRIPT-COVERAGE languages=5 screens=%lu boxes=0 expected=0 %s\n",
           screens, bad == 0 ? "PASS" : "FAIL");
    return bad == 0 ? 0 : -1;
}

/*
 * STEP 46G verification for the GodMode sequence detector.
 *
 * It drives the REAL production step function x11_god_mode_sequence_step() with
 * a stack-allocated context, so every case is decided by shipped code rather
 * than by a restatement of the Java table. No display is needed, no production
 * state is touched, and there is no debug shortcut or environment variable.
 *
 * The table sweep is deliberately exhaustive: all 18 (state, key) cells from
 * e.java:349-381 are checked, not just the happy path, because the wrong-digit
 * rows are exactly where a transcription is most likely to drift.
 */
static int verify_god_mode_sequence_detector(void)
{
    X11PresentationContext context;
    static const BounceInputSource digit[3] = {
        BOUNCE_INPUT_SOURCE_NUM7,
        BOUNCE_INPUT_SOURCE_NUM8,
        BOUNCE_INPUT_SOURCE_NUM9
    };
    /* Java e.java:349-381, transcribed from the source. */
    static const int expect_next[6][3] = {
        { 1, 0, 0 },
        { 0, 2, 0 },
        { 3, 0, 0 },
        { 0, 4, 0 },
        { 0, 0, 5 },
        { 0, 0, 0 }
    };
    static const bool expect_activate[6][3] = {
        { false, false, false },
        { false, false, false },
        { false, false, false },
        { false, false, false },
        { false, false, false },
        { false, true,  false }
    };
    int failures = 0;
    int g;
    int k;
    int i;

    /* Case 1: the exact Java sequence 7 8 7 8 9 8 activates. */
    memset(&context, 0, sizeof context);
    {
        static const BounceInputSource seq[6] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM9, BOUNCE_INPUT_SOURCE_NUM8
        };
        bool activated = false;
        bool af_armed = false;
        int trace[6];

        for (i = 0; i < 6; ++i) {
            trace[i] = context.god_mode_sequence;
            if (x11_god_mode_sequence_step(&context, seq[i], &af_armed))
                activated = true;
        }
        printf("GODMODE DETECTOR case=EXACT 7 8 7 8 9 8 g=%d->%d->%d->%d->%d->%d->%d "
               "activated=%s expected=1 2 3 4 5 0 true %s\n",
            trace[0], trace[1], trace[2], trace[3], trace[4], trace[5],
            context.god_mode_sequence,
            activated ? "true" : "false",
            (trace[0] == 0 && trace[1] == 1 && trace[2] == 2 && trace[3] == 3
                && trace[4] == 4 && trace[5] == 5
                && context.god_mode_sequence == 0 && activated) ? "PASS" : "FAIL");
        if (!(trace[0] == 0 && trace[1] == 1 && trace[2] == 2 && trace[3] == 3
                && trace[4] == 4 && trace[5] == 5
                && context.god_mode_sequence == 0 && activated))
            failures++;
    }

    /*
     * Case 2: the latch is one-way. Replaying the sequence after activation
     * returns true again but must never signal a deactivation; the caller only
     * ever writes `true`. There is no `GodMode = false` in e.java.
     */
    {
        static const BounceInputSource seq[6] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM9, BOUNCE_INPUT_SOURCE_NUM8
        };
        int second_run = 0;
        bool af_armed = false;

        for (i = 0; i < 6; ++i)
            if (x11_god_mode_sequence_step(&context, seq[i], &af_armed))
                second_run++;
        printf("GODMODE DETECTOR case=ONE-WAY replay activations=%d g=%d "
               "(never clears) %s\n",
            second_run, context.god_mode_sequence,
            (second_run == 1 && context.god_mode_sequence == 0) ? "PASS" : "FAIL");
        if (second_run != 1 || context.god_mode_sequence != 0)
            failures++;
    }

    /* Case 3: exhaustive sweep of all 18 (state, key) cells. */
    {
        int bad = 0;
        for (g = 0; g < 6; ++g) {
            for (k = 0; k < 3; ++k) {
                int next;
                bool activated;
                bool af_armed = false;
                memset(&context, 0, sizeof context);
                context.god_mode_sequence = g;
                activated = x11_god_mode_sequence_step(
                    &context,
                    digit[k],
                    &af_armed);
                next = context.god_mode_sequence;
                if (next != expect_next[g][k]
                    || activated != expect_activate[g][k]) {
                    printf("GODMODE DETECTOR sweep g=%d key=%d got(%d,%s) "
                           "want(%d,%s)\n",
                        g, k, next, activated ? "T" : "F",
                        expect_next[g][k], expect_activate[g][k] ? "T" : "F");
                    bad++;
                }
            }
        }
        printf("GODMODE DETECTOR case=SWEEP all 18 transitions vs e.java table "
               "mismatches=%d %s\n", bad, bad == 0 ? "PASS" : "FAIL");
        failures += bad;
    }

    /*
     * STEP 64-AF -- the '#' consumer, e.java:382-385, driven through the real
     * production key mapper. This proves the key reaches the new input source at
     * all, which is the only wiring question the consumer introduces:
     *
     *     case 35:
     *         if (this.af)
     *             this.aq.powerUpGravity = 300;
     *
     * The `if (this.af)` half needs a live PLAYING app and is left to the
     * runtime observation; what is checkable here, and what would otherwise be
     * silent, is that '#' maps to BOUNCE_INPUT_SOURCE_HASH and that a digit does
     * NOT, so the level-select digits are untouched by this step.
     */
    {
        BounceInputSource source = BOUNCE_INPUT_SOURCE_HASH;
        bool mapped = x11_keysym_to_source(0x023, &source); /* XK_numbersign */
        int bad = 0;

        if (!mapped || source != BOUNCE_INPUT_SOURCE_HASH) {
            printf("GODMODE DETECTOR case=AF-HASH '#' did not map to HASH %s\n",
                "FAIL");
            bad++;
        }
        /* HASH is appended at 24, strictly above NUM9 == 17, so the existing
         * `source >= NUM0 && source <= NUM9` level-select test cannot capture it.
         * Assert that rather than restating it. */
        if (BOUNCE_INPUT_SOURCE_HASH <= BOUNCE_INPUT_SOURCE_NUM9
            || BOUNCE_INPUT_SOURCE_HASH <= BOUNCE_INPUT_SOURCE_NUM0) {
            printf("GODMODE DETECTOR case=AF-HASH HASH is inside the digit range %s\n",
                "FAIL");
            bad++;
        }
        printf("GODMODE DETECTOR case=AF-HASH '#'->HASH=%d overlap_with_digits=no "
               "%s\n", (int)BOUNCE_INPUT_SOURCE_HASH, bad == 0 ? "PASS" : "FAIL");
        failures += bad;
    }

    /*
     * STEP 64-AF -- Case 3b: the `af` producer, e.java:374-378, driven through
     * the REAL production step function. The two sequences are the two distinct
     * terminals of the same `g` automaton and must stay distinct:
     *
     *   7 8 7 8 9 9  ->  g == 5 under '9'  ->  af = true      (e.java:376)
     *   7 8 7 8 9 8  ->  g == 5 under '8'  ->  GodMode = true  (e.java:363)
     *
     * This asserts both, that neither arms the other, and that a wrong sequence
     * arms neither. It is an ADDITION to Case 3: the 18-cell sweep above is
     * untouched and keeps its own expectations.
     */
    {
        static const BounceInputSource af_seq[6] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM9, BOUNCE_INPUT_SOURCE_NUM9
        };
        static const BounceInputSource god_seq[6] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM9, BOUNCE_INPUT_SOURCE_NUM8
        };
        static const BounceInputSource wrong_seq[7] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM7,
            BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM7,
            BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM9,
            BOUNCE_INPUT_SOURCE_NUM9
        };
        bool af_armed = false;
        bool god_armed = false;
        int af_total;
        int god_total;
        int af_for_god;
        int af_wrong;
        int god_wrong;

        /*
         * The out-parameter is per CALL, so the caller must latch it: the
         * production caller does exactly this at the `if (af_armed)` site. Each
         * step below therefore ORs the per-call result into a running total,
         * which is what `af` is: a latch, never cleared.
         */

        /* The af terminal: 7 8 7 8 9 9. */
        memset(&context, 0, sizeof context);
        af_total = 0;
        god_total = 0;
        for (i = 0; i < 6; ++i) {
            if (x11_god_mode_sequence_step(&context, af_seq[i], &af_armed))
                god_total = 1;
            if (af_armed)
                af_total = 1;
        }

        /* The GodMode terminal: 7 8 7 8 9 8, recorded into its own pair. */
        memset(&context, 0, sizeof context);
        af_for_god = 0;
        int god_for_god = 0;
        for (i = 0; i < 6; ++i) {
            if (x11_god_mode_sequence_step(&context, god_seq[i], &af_armed))
                god_for_god = 1;
            if (af_armed)
                af_for_god = 1;
        }
        god_armed = (bool)god_for_god;

        /* A wrong sequence arms neither. */
        memset(&context, 0, sizeof context);
        af_wrong = 0;
        god_wrong = 0;
        for (i = 0; i < 7; ++i) {
            if (x11_god_mode_sequence_step(&context, wrong_seq[i], &af_armed))
                god_wrong = 1;
            if (af_armed)
                af_wrong = 1;
        }

        printf("GODMODE DETECTOR case=AF-TERMINAL af[9 9]=%d god[9 9]=%d "
               "| af[9 8]=%d god[9 8]=%d | wrong af=%d god=%d "
               "expected=1 0 | 0 1 | 0 0 %s\n",
            af_total, god_total,
            af_for_god, god_armed ? 1 : 0,
            af_wrong, god_wrong,
            (af_total == 1 && god_total == 0
                && af_for_god == 0 && god_armed
                && af_wrong == 0 && god_wrong == 0) ? "PASS" : "FAIL");
        if (af_total != 1 || god_total != 0
            || af_for_god != 0 || !god_armed
            || af_wrong != 0 || god_wrong != 0)
            failures++;
    }

    /*
     * Case 4: the required wrong sequences. Each is compared cell by cell
     * against the Java table, so the expectation is derived, not guessed.
     * 7 7 8 7 8 9 8 must NOT activate: the second 7 lands on g==1 and resets.
     */
    {
        static const struct {
            const char *label;
            BounceInputSource seq[7];
            int length;
            bool expect_activate;
        } cases[] = {
            { "7 7 8 7 8 9 8", { BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM7,
                BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM7,
                BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM9,
                BOUNCE_INPUT_SOURCE_NUM8 }, 7, false },
            { "7 8 8 7 8 9 8", { BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
                BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM7,
                BOUNCE_INPUT_SOURCE_NUM8, BOUNCE_INPUT_SOURCE_NUM9,
                BOUNCE_INPUT_SOURCE_NUM8 }, 7, false },
            { "7 8 7 9 8", { BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
                BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM9,
                BOUNCE_INPUT_SOURCE_NUM8 }, 5, false }
        };
        size_t c;
        for (c = 0; c < sizeof cases / sizeof cases[0]; ++c) {
            bool activated = false;
            bool af_armed = false;
            memset(&context, 0, sizeof context);
            for (i = 0; i < cases[c].length; ++i)
                if (x11_god_mode_sequence_step(
                        &context, cases[c].seq[i], &af_armed))
                    activated = true;
            printf("GODMODE DETECTOR case=WRONG [%s] activated=%s expected=%s "
                   "final_g=%d %s\n",
                cases[c].label, activated ? "true" : "false",
                cases[c].expect_activate ? "true" : "false",
                context.god_mode_sequence,
                (activated == cases[c].expect_activate) ? "PASS" : "FAIL");
            if (activated != cases[c].expect_activate)
                failures++;
        }
    }

    /*
     * Case 5: an unrelated key must not disturb g. e.java has no branch that
     * resets g for anything other than 55/56/57, so 7 8 LEFT 7 8 9 8 must still
     * activate. This is the case a naive `else g = 0;` would break.
     */
    memset(&context, 0, sizeof context);
    {
        static const BounceInputSource seq[7] = {
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_LEFT_ARROW,
            BOUNCE_INPUT_SOURCE_NUM7, BOUNCE_INPUT_SOURCE_NUM8,
            BOUNCE_INPUT_SOURCE_NUM9, BOUNCE_INPUT_SOURCE_NUM8
        };
        bool activated = false;
        bool af_armed = false;
        int left_after_arrow = -1;
        for (i = 0; i < 7; ++i) {
            if (seq[i] == BOUNCE_INPUT_SOURCE_LEFT_ARROW)
                left_after_arrow = context.god_mode_sequence;
            if (x11_god_mode_sequence_step(&context, seq[i], &af_armed))
                activated = true;
        }
        printf("GODMODE DETECTOR case=UNRELATED 7 8 LEFT 7 8 9 8 "
               "g_at_left=%d activated=%s %s\n",
            left_after_arrow, activated ? "true" : "false",
            (left_after_arrow == 2 && activated) ? "PASS" : "FAIL");
        if (left_after_arrow != 2 || !activated)
            failures++;
    }

    /*
     * Case 6: releases never reach the detector. The step function takes a
     * source, never a direction, so a release cannot be expressed through it;
     * the gate that enforces this lives at the seam (`pressed &&`). This case
     * documents the intent: only NUM7/8/9 mutate g, and nothing else does.
     */
    {
        static const BounceInputSource other[] = {
            BOUNCE_INPUT_SOURCE_LEFT_ARROW, BOUNCE_INPUT_SOURCE_RIGHT_ARROW,
            BOUNCE_INPUT_SOURCE_UP_ARROW, BOUNCE_INPUT_SOURCE_DOWN_ARROW,
            BOUNCE_INPUT_SOURCE_CONFIRM_RETURN, BOUNCE_INPUT_SOURCE_PAUSE,
            BOUNCE_INPUT_SOURCE_NUM0, BOUNCE_INPUT_SOURCE_NUM5,
            BOUNCE_INPUT_SOURCE_ESCAPE, BOUNCE_INPUT_SOURCE_QUIT
        };
        size_t o;
        bool touched = false;
        bool af_armed = false;
        memset(&context, 0, sizeof context);
        context.god_mode_sequence = 4;
        for (o = 0; o < sizeof other / sizeof other[0]; ++o)
            if (x11_god_mode_sequence_step(&context, other[o], &af_armed))
                touched = true;
        printf("GODMODE DETECTOR case=NON-DIGIT 10 non-detector sources "
               "g=4->%d activated=%s %s\n",
            context.god_mode_sequence, touched ? "true" : "false",
            (context.god_mode_sequence == 4 && !touched) ? "PASS" : "FAIL");
        if (context.god_mode_sequence != 4 || touched)
            failures++;
    }

    /* Case 7: the detector starts at 0 on a fresh context. */
    memset(&context, 0, sizeof context);
    printf("GODMODE DETECTOR case=INIT fresh g=%d expected=0 %s\n",
        context.god_mode_sequence,
        context.god_mode_sequence == 0 ? "PASS" : "FAIL");
    if (context.god_mode_sequence != 0)
        failures++;

    if (failures != 0)
        fprintf(stderr, "god mode sequence detector: %d failures\n", failures);
    return failures == 0 ? 0 : -1;
}

static int x11_draw_surface(
    X11PresentationContext *context,
    const BounceSurface *surface
)
{
    int x;
    int y;
    int previous_red = -1;
    int previous_green = -1;
    int previous_blue = -1;

    if (context == NULL
        || context->display == NULL
        || context->graphics_context == NULL
        || surface == NULL)
        return -1;

    for (y = 0; y < (int)BOUNCE_SURFACE_HEIGHT; ++y) {
        for (x = 0; x < (int)BOUNCE_SURFACE_WIDTH; ++x) {
            uint32_t token;
            int red;
            int green;
            int blue;

            if (bounce_surface_get_pixel(surface, x, y, &token) != 0)
                return -1;
            red = (int)((token >> 16) & 0xffu);
            green = (int)((token >> 8) & 0xffu);
            blue = (int)(token & 0xffu);
            if (red != previous_red
                || green != previous_green
                || blue != previous_blue) {
                XSetForeground(
                    context->display,
                    context->graphics_context,
                    token_to_x11_pixel(token)
                );
                previous_red = red;
                previous_green = green;
                previous_blue = blue;
            }
            XDrawPoint(
                context->display,
                context->window,
                context->graphics_context,
                x,
                y
            );
        }
    }
    XFlush(context->display);
    return 0;
}

static void present_to_x11(
    const BounceSurface *surface,
    void *user_data
)
{
    X11PresentationContext *context = (X11PresentationContext *)user_data;

    if (context == NULL)
        return;
    if (x11_draw_surface(context, surface) != 0)
        context->failed = 1;
    else
        render_trace_presentation(context->render_trace);
}

static void sleep_frame(void)
{
    struct timespec duration;
    duration.tv_sec = 0;
    duration.tv_nsec = 16L * 1000L * 1000L;
    (void)nanosleep(&duration, NULL);
}

static void print_usage(const char *program)
{
    fprintf(
        stderr,
        "usage: %s [level-path] [--check]\n"
        "       %s [level-path] --camera-diagnostic\n"
        "       %s [level-path] --vertical-diagnostic\n"
        "       %s [level-path] --natural-camera-diagnostic\n"
        "       %s [level-path] --render-trace\n"
        "       %s [level-path] --live-status\n"
        "       %s --assets\n"
        "       %s [--audio-device=NAME]  (NAME is an ALSA PCM name, e.g.\n"
        "           default or plughw:1,0; omit for the backend's own default.\n"
        "           The named device is used or audio init fails -- there is\n"
        "           no probing and no fallback to another device.)\n"
        "       %s   (with NBB_DEBUG=0|1|2|3 for the terminal debug tracker)\n"
        "       %s --save-path   (print the store's resolved path; writes a probe\n"
        "                            record ONLY if no store is there yet, so an\n"
        "                            existing save is never overwritten)\n"
        "       %s --save-plant   (force-write a known store; used by --check to\n"
        "                            prove --save-path preserves an existing one)\n"
        "       %s --save=DIR   (put records.bin under DIR/bounce/ instead of\n"
        "                            $XDG_DATA_HOME; same as the environment\n"
        "                            variable BOUNCE_SAVE_DIR)\n"
        "       %s --screenshots=DIR   (render every screen to DIR as a 128x128 PNG;\n"
        "                            the images in screenshots/ are made this way,\n"
        "                            and the store is redirected so it cannot\n"
        "                            touch the player's save)\n",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice",
        program != NULL ? program : "bounce_vertical_slice"
    );
}

/*
 * STEP 37 PERSIST -- the flow half of the contract.
 *
 * bounce_persistence_verify() above covers the container. This covers the two
 * Java rules the container is fed from and read back into:
 *
 *   1. HighScore is a running maximum with a STRICT comparison
 *      (BounceGame.java:422), so a tie must not rewrite the record.
 *   2. MaxLevels is applied through the level-selection setter, which bounds
 *      it to the last level (app_flow.c:683-692 / :747-748), so a hand-edited
 *      or corrupt store cannot unlock a level that does not exist.
 *
 * Nothing here touches the filesystem: it drives the flow only, so it cannot
 * reach the player's real store.
 */
/*
 * =============================================================================
 * STEP 38-RESET -- verify_default_state()
 *
 * WHY THIS IS A SEPARATE CHECK AND NOT A LINE IN AN EXISTING ONE.
 *
 * Four places now have to agree about what a new install looks like: the constants
 * in app_flow.h, bounce_app_flow_init(), the Reset to Default row, and the store's
 * own idea of a fresh file. Every assertion that already existed is about ONE of
 * those sites -- "the toggle walks", "a store restores", "the page has two rows".
 * None of them is about the SET. So a default changed in three places and not the
 * fourth leaves the whole suite green, and the disagreement surfaces to a player as
 * a first minute of play that does not match the documented defaults, which is the
 * one thing this check exists to prevent.
 *
 * WHAT IS ASSERTED, AND WHY EACH LINE EARNS ITS PLACE:
 *
 *   state                    SPLASH. A launch is a splash; anything else means the
 *                            fixture skipped a stage.
 *   high_score               0. Nothing has been played.
 *   available_level_count    BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT. THE ONE THAT
 *                            CHANGED. It was 0, which is the recovered Java's own
 *                            default, and 0 makes Level Select unreachable forever
 *                            because the New Game gate at BounceGame.java:241 is
 *                            `MaxLevels > 1`. Now 2, so levels 1 and 2 are playable
 *                            and 3..11 stay gated.
 *   theme indices            0 and 0. Index 0 IS the default color profile; both
 *                            the highlight and the applied value are checked so the
 *                            Theme page cannot claim a profile the game is not in.
 *   audio_enabled            BOUNCE_DEFAULT_AUDIO_ENABLED.
 *   t9_input_enabled         BOUNCE_DEFAULT_T9_INPUT_ENABLED. ALSO CHANGED, from
 *                            false. The numeric keypad is a native addition with
 *                            no recovered default to be faithful to, so this is a
 *                            product decision, and it is now ON.
 *   applied language         BOUNCE_DEFAULT_LANGUAGE_INDEX -- English.
 *   continue_available       false. There is no snapshot, so there is nothing to
 *                            continue FROM. Asserting the flag alone would also be
 *                            satisfied by deleting the row, so the menu shape is
 *                            checked separately below.
 *   reset_to_default_pending false. Nothing has been confirmed yet, which is what
 *                            keeps a fresh install from deleting a store it never
 *                            wrote to.
 *
 * THE MENU SHAPE, because "Continue off and only New Game below it" is a claim
 * about what the player SEES. Continue must still be row 1 and disabled -- visible
 * but not selectable -- with New Game as row 2 and enabled. Then New Game is
 * actually pressed, and it must land on LEVEL SELECT rather than starting level 1
 * outright. That is the observable consequence of the shipped count of 2, and it is
 * the same route verify_gameplay_entry_boundary() drives; asserting it here as well
 * is deliberate, because this is the check that owns the DEFAULT and that route is
 * only reachable from the default.
 *
 * NO I/O. This check runs on a flow that has touched no store, so it cannot reach
 * the player's real save.
 */
static int verify_default_state(void)
{
    BounceAppFlow flow;
    unsigned int step;
    int bad = 0;

    /*
     * THE DOCUMENTED NUMBERS, AS LITERALS, BEFORE THE FLOW IS EVEN BUILT.
     *
     * This block exists because of a hole the first version of this check had. Every
     * assertion below compares the flow against the BOUNCE_DEFAULT_* constants, and
     * bounce_app_flow_init() fills the flow from those same constants -- so changing
     * 2 to 1 moved both sides at once and the whole check stayed green. A negative
     * control that set the shipped count to 1 was caught by nothing, which is exactly
     * the kind of test that reads as coverage and proves nothing.
     *
     * The constants are part of the shipped contract -- they are what "a new install"
     * means to anyone reading this file -- so the contract has to be written down
     * somewhere the compiler cannot move, and this is that somewhere. Keeping the
     * numbers here and the constants in the flow means a default can be changed in
     * one place and the change is reported by name, rather than being silently
     * adopted by both sides of a comparison.
     */
    if (BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT != 2) {
        fprintf(stderr,
                "default: the documented unlocked level count is %d, not 2\n",
                BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT);
        bad++;
    }
    if (!BOUNCE_DEFAULT_T9_INPUT_ENABLED) {
        fprintf(stderr,
                "default: the documented keypad default is ON\n");
        bad++;
    }
    if (!BOUNCE_DEFAULT_AUDIO_ENABLED) {
        fprintf(stderr,
                "default: the documented audio default is ON\n");
        bad++;
    }
    if (BOUNCE_DEFAULT_LANGUAGE_INDEX != 0u) {
        fprintf(stderr,
                "default: the documented default language is index 0 (English),"
                " not %u\n",
                BOUNCE_DEFAULT_LANGUAGE_INDEX);
        bad++;
    }

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);

    if (flow.state != BOUNCE_APP_STATE_SPLASH) {
        fprintf(stderr, "default: a fresh flow is not on the splash\n");
        bad++;
    }
    if (bounce_app_flow_high_score(&flow) != 0) {
        fprintf(stderr, "default: a fresh flow already has a high score\n");
        bad++;
    }
    if (bounce_app_flow_available_level_count(&flow)
        != BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT) {
        fprintf(stderr,
                "default: unlocked level count is %u, not %d\n",
                bounce_app_flow_available_level_count(&flow),
                BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT);
        bad++;
    }
    if (bounce_app_flow_settings_applied_theme_index(&flow) != 0u
        || flow.settings.theme_index != 0u) {
        fprintf(stderr, "default: the color profile is not the default one\n");
        bad++;
    }
    if (bounce_app_flow_settings_audio_enabled(&flow)
        != BOUNCE_DEFAULT_AUDIO_ENABLED) {
        fprintf(stderr, "default: audio is not at its shipped default\n");
        bad++;
    }
    if (bounce_app_flow_settings_t9_enabled(&flow)
        != BOUNCE_DEFAULT_T9_INPUT_ENABLED) {
        fprintf(stderr, "default: the numeric keypad is not at its shipped default\n");
        bad++;
    }
    if (bounce_app_flow_settings_applied_language_index(&flow)
        != BOUNCE_DEFAULT_LANGUAGE_INDEX
        || flow.settings.language_index != 0u) {
        fprintf(stderr, "default: the language is not the default English resource\n");
        bad++;
    }
    if (flow.menu.continue_available) {
        fprintf(stderr, "default: Continue is offered with no snapshot to resume\n");
        bad++;
    }
    if (flow.settings.reset_to_default_pending) {
        fprintf(stderr, "default: a confirmed reset is pending before any press\n");
        bad++;
    }

    /*
     * THE MENU SHAPE. Continue is asserted PRESENT and DISABLED rather than absent,
     * because a deleted row would satisfy a bare flag check while quietly changing
     * the screen the player is looking at.
     *
     * Note the two different numberings, which is the easiest thing to get wrong
     * here. bounce_app_flow_menu_item_enabled() takes a ROW, where 0 is Continue and
     * 1 is New Game. bounce_app_flow_menu_row_for_selection() takes a SELECTION
     * index, and a disabled Continue is skipped entirely -- so on a fresh install the
     * highlight starts at selection 0, which is row 1. "Only New Game below it" is
     * therefore the statement that row 0 is the disabled Continue, row 1 is New Game,
     * and the very first press lands on New Game with no Continue in between.
     */
    if (bounce_app_flow_menu_item_enabled(&flow, 0u)) {
        fprintf(stderr, "default: the Continue row is enabled on a fresh install\n");
        bad++;
    }
    if (!bounce_app_flow_menu_item_enabled(&flow, 1u)) {
        fprintf(stderr, "default: the New Game row is disabled on a fresh install\n");
        bad++;
    }
    if (bounce_app_flow_menu_row_for_selection(&flow, 0u) != 1u) {
        fprintf(stderr,
                "default: the first press does not land on New Game (row=%u)\n",
                bounce_app_flow_menu_row_for_selection(&flow, 0u));
        bad++;
    }

    /*
     * AND THE CONSEQUENCE. Getting from SPLASH to MENU takes the splash's own tick
     * count, and the count is read from the constant rather than hard-coded so that
     * changing it cannot quietly shorten or lengthen this walk.
     */
    /*
     * The splash hands over on the tick AFTER its limit, so the limit is spent first
     * and the transition comes from one more. Both loops are bounded by the
     * constant rather than by a literal count, which is what keeps this walk
     * correct if the splash duration is ever changed.
     */
    for (step = 0u; step <= BOUNCE_APP_SPLASH_TIMER_LIMIT; ++step) {
        if (bounce_app_flow_tick(&flow) != 0
            || flow.state != BOUNCE_APP_STATE_SPLASH) {
            fprintf(stderr,
                    "default: the splash ended before its timer limit (step=%u)\n",
                    step);
            bad++;
            break;
        }
    }
    if (bounce_app_flow_tick(&flow) != 1
        || flow.state != BOUNCE_APP_STATE_MENU) {
        fprintf(stderr, "default: the splash did not hand over to the menu\n");
        bad++;
    }
    /*
     * And nothing is skipped on the way down. With the Continue row disabled the
     * highlight starts already on New Game, so one DOWN moves to High Score -- a
     * second pressable row and NOT a second pass over Continue. Asserting the count
     * of enabled rows as well as the one mapping is what stops a menu that reached
     * New Game by accident from passing.
     */
    if (flow.menu.selected_index != 0u
        || flow.menu.enabled_item_count != BOUNCE_MENU_ROW_COUNT - 1u) {
        fprintf(stderr,
                "default: the fresh menu is not six selectable rows"
                " (index=%u count=%u)\n",
                flow.menu.selected_index, flow.menu.enabled_item_count);
        bad++;
    }
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || flow.menu.selected_index != 1u
        || bounce_app_flow_menu_row_for_selection(&flow, 1u) != 2u) {
        fprintf(stderr,
                "default: one DOWN from the top does not reach High Score\n");
        bad++;
    }
    if (bounce_app_flow_menu_move(&flow, BOUNCE_MENU_DIRECTION_UP) != 0
        || flow.menu.selected_index != 0u) {
        fprintf(stderr, "default: UP from High Score does not return to New Game\n");
        bad++;
    }
    /*
     * And the count of 2 is what makes this press open Level Select rather than
     * stage level 1 directly. If this ever reports ACTION_BOUNDARY, the shipped
     * count has gone back to 0 or 1 and Level Select is unreachable again.
     */
    /*
     * And the consequence of the shipped count of 2: the press opens Level Select
     * rather than staging level 1 directly. If this ever reports ACTION_BOUNDARY,
     * the count has gone back to 0 or 1 and Level Select has become unreachable
     * again -- which is the exact regression the default was changed to fix, and the
     * reason it needs an assertion rather than a comment.
     */
    if (bounce_app_flow_menu_select(&flow) != BOUNCE_MENU_ACTION_NEW_GAME
        || flow.state != BOUNCE_APP_STATE_LEVEL_SELECTION) {
        fprintf(stderr,
                "default: New Game on a fresh install does not open Level Select"
                " (state=%d count=%u)\n",
                (int)flow.state,
                bounce_app_flow_available_level_count(&flow));
        bad++;
    }
    /*
     * Finally, the list itself: two rows, and both of them reachable. This is the
     * "levels 1 and 2 unlocked" half stated as navigation rather than as a count,
     * so a list of two entries that happens to be positions 1 and 7 would fail.
     */
    if (bounce_app_flow_available_level_count(&flow)
        != (unsigned int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT
        || bounce_app_flow_level_selection_selected_index(&flow) != 0u) {
        fprintf(stderr, "default: the fresh Level Select list is not two rows at 0\n");
        bad++;
    }
    if (bounce_app_flow_level_selection_move(
            &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_level_selection_selected_index(&flow) != 1u
        || bounce_app_flow_level_selection_move(
            &flow, BOUNCE_MENU_DIRECTION_DOWN) != 0
        || bounce_app_flow_level_selection_selected_index(&flow) != 1u) {
        fprintf(stderr,
                "default: Level Select does not offer exactly levels 1 and 2\n");
        bad++;
    }

    if (bad == 0) {
        printf("DEFAULT-STATE splash=yes high_score=%d levels=%d theme=0"
               " audio=on t9=on language=%u continue=off reset_pending=off"
               " newgame=level-select PASS\n",
               bounce_app_flow_high_score(&flow),
               (int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT,
               BOUNCE_DEFAULT_LANGUAGE_INDEX);
    }
    return bad == 0 ? 0 : -1;
}

/*
 * =============================================================================
 * STEP 38-RESET -- verify_reset_to_default()
 *
 * THE CLAIM. Pressing Settings -> Reset to Default -> Confirm restores every value
 * a fresh install carries, and removes the snapshot that would otherwise let the
 * player return to the run they just wiped.
 *
 * WHY IT IS DRIVEN THROUGH x11_dispatch_event() AND NOT THROUGH THE FLOW.
 *
 * bounce_app_flow_reset_to_default() only edits memory. It cannot delete Record 3
 * and cannot rewrite records 1, 2, 4 and 5, because those are the shell's files and
 * the flow deliberately has no business knowing them. That is the right split, and
 * it has a testing consequence that has bitten this suite before: a check that calls
 * the flow function directly is satisfied by the flow function alone and says
 * nothing about whether the store is ever touched. The first version of a
 * theme-commit check was green with the commit removed for exactly this reason.
 *
 * So the keystrokes go in the front door -- MENU, three DOWNs to Settings, five
 * DOWNs to the last root row, SELECT, SELECT -- and the assertions read the FILES
 * afterwards. The consume-then-apply edge is the same three lines the running game
 * executes, so a negative control that deletes that call fails here.
 *
 * THE FIXTURE IS PRIMED TO HAVE SOMETHING TO LOSE, and each part of it is asserted
 * BEFORE the reset rather than assumed. A reset check against an already-default
 * flow proves nothing: every field would match whether or not the reset ran. So the
 * store starts with nine unlocked levels, a high score, a non-default color profile,
 * the keypad switched OFF and a live Record 3, and the pre-reset block confirms the
 * flow actually adopted all five. Only then is the reset meaningful.
 *
 * CONFIRMATION IS PART OF THE CLAIM, so it is driven both ways. Reaching the
 * Confirm row and leaving it alone must change nothing, including the store; the Back
 * row must leave the page without resetting anything; and only Confirm may act. That is
 * what makes the feature safe to put next to the Audio setting, and a reset that
 * required no confirmation would fail here even though every field still matched.
 *
 * THE PLAYER'S REAL SAVE IS NEVER TOUCHED. Every store access in this function runs
 * under the discipline bounce_persistence_verify() uses: a private mkdtemp root
 * published through XDG_DATA_HOME, with the caller's environment restored before
 * returning on every path, including the failure ones.
 */
static int verify_reset_to_default(void)
{
    static const char template[] = "/tmp/bounce-reset-XXXXXX";
    char root[sizeof template];
    /* persistence.h keeps BOUNCE_PERSISTENCE_PATH_MAX private to its own
     * translation unit, so the saved value is copied into a local buffer. */
    char saved[1024];
    int saved_ok;
    X11PresentationContext context;
    XEvent event;
    BounceApp app;
    BouncePersistenceRecords primed;
    BouncePersistenceRecords after;
    BouncePersistenceRecord3 record;
    BouncePersistenceRecord3 back;
    bool present = false;
    unsigned int step;
    bool primed_ok;
    bool pre_ok;
    bool back_untouched;
    bool confirm_flow_ok;
    bool record3_gone;
    bool records_ok;
    bool theme_ok;
    bool t9_ok;
    /*
     * STEP 38-RESET-FIX -- the in-memory copy and the Exit round trip below.
     */
    bool memory_cleared;
    bool exit_stays_deleted;
    bool relaunch_stays_greyed;
    int bad = 0;
    int32_t theme_after = -1;
    int32_t t9_after = -1;

    memset(&app, 0, sizeof app);
    memcpy(root, template, sizeof template);
    if (mkdtemp(root) == NULL) {
        fprintf(stderr, "reset: could not create a private store root\n");
        return -1;
    }
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0) {
        fprintf(stderr, "reset: could not publish the private store root\n");
        return -1;
    }

    /* ---- STEP 1: give the store something worth losing ---- */
    memset(&primed, 0, sizeof primed);
    primed.max_levels = 9;
    primed.high_score = 4321;
    memset(&record, 0, sizeof record);
    record.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    record.level = 7u;
    record.score = 98765;
    record.lives = 2;
    record.ball_size = 16u;
    record.unk_x = 144;
    record.unk_y = 96;

    primed_ok = bounce_persistence_save(&primed) == 0
        && bounce_persistence_save_theme_index(5) == 0
        && bounce_persistence_save_t9_enabled(0) == 0
        && bounce_persistence_save_record3(&record) == 0;
    if (!primed_ok) {
        fprintf(stderr, "reset: could not prime the private store\n");
        bad++;
    }

    /* ---- STEP 2: launch, and confirm the flow adopted every primed value ---- */
    if (bounce_game_init(&app) != 0 || bounce_game_enter_menu(&app) != 0) {
        fprintf(stderr, "reset: the app could not reach the menu\n");
        bounce_game_shutdown(&app);
        goto finish;
    }
    /*
     * THE SAME RESTORE CALL main() MAKES, in the same place. bounce_game_init()
     * deliberately does NOT read the store -- main() owns that, so a verifier that
     * skipped it would boot a player whose save is silently ignored, and the fixture
     * would be asserting against fresh defaults with a primed store sitting on disk.
     * That is precisely the vacuous shape this check exists to avoid, so the boot
     * sequence is reproduced rather than approximated.
     */
    app_restore_persisted_settings(&app);
    /*
     * AUDIO AND THE KEYPAD ARE SET IN MEMORY, and the reason is a property of the
     * store rather than a shortcut in the fixture.
     *
     * Audio is never written to the store at all -- it is a per-session choice -- so
     * there is nothing on disk to prime, and the only honest way to give the reset
     * something to undo is to switch it off as the Audio page would.
     *
     * The keypad IS written, but only in one direction: app_restore_persisted_settings()
     * turns it ON when the record is set and has no branch that turns it back off, so
     * a store holding "disabled" still boots enabled. A fixture that primed the record
     * and then asserted "the keypad is off before the reset" would be asserting
     * something the boot path cannot produce, and the reset's effect on the keypad
     * would go untested. So the same call the Input page's SELECT makes is used
     * instead -- which is the state a player who switched it off is actually in.
     */
    (void)bounce_app_flow_restore_persisted_t9(&app.flow, false);
    app.flow.settings.audio_enabled = false;
    /*
     * The snapshot is live, so Continue must be OFFERED here. That is asserted
     * because the whole feature turns on Continue being removed: if this press did
     * not make the row available, the later assertion that the reset cleared it
     * would be trivially true.
     */
    app_refresh_continue_availability(&app);
    if (!app.flow.menu.continue_available) {
        fprintf(stderr,
                "reset: the fixture did not produce an available Continue row\n");
        bad++;
    }
    pre_ok = bounce_app_flow_available_level_count(&app.flow) == 9u
        && bounce_app_flow_high_score(&app.flow) == 4321
        && bounce_app_flow_settings_applied_theme_index(&app.flow) == 5u
        && !bounce_app_flow_settings_audio_enabled(&app.flow)
        && !bounce_app_flow_settings_t9_enabled(&app.flow);
    if (!pre_ok) {
        fprintf(stderr,
                "reset: the flow did not adopt the primed store"
                " (levels=%u high=%d theme=%u audio=%d t9=%d)\n",
                bounce_app_flow_available_level_count(&app.flow),
                bounce_app_flow_high_score(&app.flow),
                bounce_app_flow_settings_applied_theme_index(&app.flow),
                (int)bounce_app_flow_settings_audio_enabled(&app.flow),
                (int)bounce_app_flow_settings_t9_enabled(&app.flow));
        bad++;
    }

    /* ---- STEP 3: navigate to the Confirm row WITHOUT pressing it ---- */
    dispatch_fixture_context(&context);
    /*
     * FOUR DOWNs, because Continue is AVAILABLE in this fixture, so every row is
     * selectable and Settings -- row 4 -- is selection 4 as well. The fresh-install
     * menu, which is where row 4 is selection 3, is the other case and is covered by
     * verify_native_extension_ui(); hard-coding either number here would silently
     * test the wrong menu the next time the other one changed.
     */
    for (step = 0u; step < 4u; ++step) {
        fill_key_event(&event, KeyPress, 116u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Down) != 0)
            bad++;
    }
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
        || app.flow.state != BOUNCE_APP_STATE_SETTINGS
        || app.flow.settings.page != BOUNCE_SETTINGS_PAGE_ROOT
        || app.flow.settings.selected_index != 0u) {
        fprintf(stderr, "reset: could not open the Settings root from the menu\n");
        bad++;
    }
    /* The last root row is the reset row. Walking down to it and stopping there must
     * leave the store exactly as it was: reaching a page is not confirming it. */
    for (step = 0u; step < BOUNCE_SETTINGS_ROOT_ITEM_COUNT - 1u; ++step) {
        fill_key_event(&event, KeyPress, 116u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Down) != 0)
            bad++;
    }
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
        || app.flow.settings.page != BOUNCE_SETTINGS_PAGE_RESET) {
        fprintf(stderr, "reset: the last Settings row did not open the Reset page\n");
        bad++;
    }
    /*
     * THE CONFIRM ROW IS THE ONE THE HIGHLIGHT LANDS ON. The clamp in
     * bounce_app_flow_settings_select() is what puts it there: the root row number
     * was 5 and the page has two rows, so without the clamp SELECT would have been
     * rejected outright and this feature would be unreachable.
     */
    if (app.flow.settings.selected_index != BOUNCE_SETTINGS_RESET_ROW_CONFIRM) {
        fprintf(stderr,
                "reset: the Reset page does not open on the Confirm row"
                " (index=%u)\n",
                app.flow.settings.selected_index);
        bad++;
    }
    if (bounce_persistence_load(&after) != 0
        || after.max_levels != 9
        || after.high_score != 4321
        || bounce_persistence_load_theme_index(&theme_after) != 0
        || theme_after != 5) {
        fprintf(stderr, "reset: merely opening the Reset page rewrote the store\n");
        bad++;
    }

    /*
     * STEP 4 -- THE BACK ROW LEAVES WITHOUT RESETTING.
     *
     * This row used to be CANCEL and it used to do nothing at all. It is now the Back
     * action, wired to bounce_app_flow_settings_back(), so SELECT on it navigates to the
     * Settings root -- which is the whole point of the change and is asserted here: the
     * page it leaves is asserted, not just the absence of damage.
     *
     * "Does not reset" is still the property that matters, and it is asserted against
     * the flow AND the store, because a reset that reached one and not the other would
     * be the more interesting bug.
     */
    fill_key_event(&event, KeyPress, 116u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Down) != 0)
        bad++;
    if (app.flow.settings.selected_index != BOUNCE_SETTINGS_RESET_ROW_BACK) {
        fprintf(stderr, "reset: the Back row is not reachable\n");
        bad++;
    }
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0)
        bad++;
    back_untouched
        = !app.flow.settings.reset_to_default_pending
        && app.flow.settings.page == BOUNCE_SETTINGS_PAGE_ROOT
        && bounce_app_flow_settings_selected_index(&app.flow) == 0u
        && bounce_app_flow_available_level_count(&app.flow) == 9u
        && bounce_app_flow_high_score(&app.flow) == 4321
        && bounce_app_flow_settings_applied_theme_index(&app.flow) == 5u
        && app.flow.menu.continue_available;
    if (!back_untouched) {
        fprintf(stderr,
                "reset: Back on the Back row did not leave cleanly (page=%d"
                " idx=%u levels=%u high=%d theme=%u continue=%d)\n",
                (int)app.flow.settings.page,
                bounce_app_flow_settings_selected_index(&app.flow),
                bounce_app_flow_available_level_count(&app.flow),
                bounce_app_flow_high_score(&app.flow),
                bounce_app_flow_settings_applied_theme_index(&app.flow),
                (int)app.flow.menu.continue_available);
        bad++;
    }
    if (bounce_persistence_load(&after) != 0
        || after.max_levels != 9
        || after.high_score != 4321
        || bounce_persistence_load_record3(&back, &present) != 0
        || !present) {
        fprintf(stderr, "reset: Back on the Back row rewrote the store\n");
        bad++;
    }

    /*
     * STEP 5 -- GO BACK IN AND CONFIRM. The page is reopened from the root rather than
     * walked back to from the row above, so this also checks that coming back to the
     * Reset page lands on CONFIRM again. It would otherwise be able to land on BACK and
     * quietly leave every later press in this check doing nothing.
     */
    for (step = 0u; step < BOUNCE_SETTINGS_ROOT_ITEM_COUNT - 1u; ++step) {
        fill_key_event(&event, KeyPress, 116u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Down) != 0)
            bad++;
    }
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
        || app.flow.settings.page != BOUNCE_SETTINGS_PAGE_RESET
        || app.flow.settings.selected_index != BOUNCE_SETTINGS_RESET_ROW_CONFIRM) {
        fprintf(stderr,
                "reset: reopening the Reset page did not land on Confirm"
                " (page=%d idx=%u)\n",
                (int)app.flow.settings.page,
                bounce_app_flow_settings_selected_index(&app.flow));
        bad++;
    }
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0)
        bad++;

    /*
     * IN THE FLOW FIRST, because that is the half a player sees on the next frame.
     * Every value is compared to the shared constants rather than to the numbers
     * the fixture started from, so this check and verify_default_state() cannot
     * disagree about what "default" means.
     */
    confirm_flow_ok
        = !app.flow.settings.reset_to_default_pending
        && bounce_app_flow_available_level_count(&app.flow)
            == (unsigned int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT
        && bounce_app_flow_high_score(&app.flow) == 0
        && bounce_app_flow_settings_applied_theme_index(&app.flow) == 0u
        && app.flow.settings.theme_index == 0u
        && bounce_app_flow_settings_audio_enabled(&app.flow)
            == BOUNCE_DEFAULT_AUDIO_ENABLED
        && bounce_app_flow_settings_t9_enabled(&app.flow)
            == BOUNCE_DEFAULT_T9_INPUT_ENABLED
        && bounce_app_flow_settings_applied_language_index(&app.flow)
            == BOUNCE_DEFAULT_LANGUAGE_INDEX
        && !app.flow.menu.continue_available
        && !app.flow.new_high_score;
    if (!confirm_flow_ok) {
        fprintf(stderr,
                "reset: Confirm did not restore the defaults in the flow"
                " (levels=%u high=%d theme=%u audio=%d t9=%d lang=%u"
                " continue=%d)\n",
                bounce_app_flow_available_level_count(&app.flow),
                bounce_app_flow_high_score(&app.flow),
                bounce_app_flow_settings_applied_theme_index(&app.flow),
                (int)bounce_app_flow_settings_audio_enabled(&app.flow),
                (int)bounce_app_flow_settings_t9_enabled(&app.flow),
                bounce_app_flow_settings_applied_language_index(&app.flow),
                (int)app.flow.menu.continue_available);
        bad++;
    }
    /*
     * AND THE FLAG IS CLEARED BY BEING READ. bounce_app_flow_consume_reset_to_default()
     * returns true exactly once per confirmed reset; a second press that happened to
     * re-enter the page must not find it still raised, or the store would be deleted
     * twice from one confirmation.
     */
    if (bounce_app_flow_consume_reset_to_default(&app.flow)) {
        fprintf(stderr, "reset: the pending flag survived the press that consumed it\n");
        bad++;
    }

    /*
     * THEN THE STORE, which is the half the flow cannot do. Record 3 first: a
     * snapshot left behind is the one failure with no visible symptom, because the
     * menu looks correct while the player is still one Escape away from the run they
     * just erased.
     */
    if (bounce_persistence_load_record3(&back, &present) != 0) {
        fprintf(stderr, "reset: could not read Record 3 after the reset\n");
        bad++;
        record3_gone = false;
    } else {
        record3_gone = !present;
        if (present) {
            fprintf(stderr,
                    "reset: the reset left a snapshot behind (b1=%u level=%u)\n",
                    back.b1, back.level);
            bad++;
        }
    }

    records_ok = bounce_persistence_load(&after) == 0
        && after.max_levels == (int32_t)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT
        && after.high_score == 0;
    if (!records_ok) {
        fprintf(stderr,
                "reset: records were not rewritten to the defaults"
                " (max_levels=%ld high_score=%ld)\n",
                (long)after.max_levels, (long)after.high_score);
        bad++;
    }

    theme_ok = bounce_persistence_load_theme_index(&theme_after) == 0
        && theme_after == 0;
    if (!theme_ok) {
        fprintf(stderr,
                "reset: the color profile was not reset in the store (%ld)\n",
                (long)theme_after);
        bad++;
    }
    /*
     * The keypad is stored as "1 means enabled", so the reset has to WRITE 1 here.
     * It is read back through the same record the Input page is restored from, and
     * a store left at 0 would silently un-keypad the game on the next launch while
     * every in-memory assertion above still passed.
     */
    t9_ok = bounce_persistence_load_t9_enabled(&t9_after) == 0 && t9_after == 1;
    if (!t9_ok) {
        fprintf(stderr,
                "reset: the keypad setting was not reset in the store (%ld)\n",
                (long)t9_after);
        bad++;
    }

    /*
     * STEP 38-RESET-FIX -- AND THE IN-MEMORY COPY, WHICH IS THE HALF THAT WAS MISSING.
     *
     * app->resume_record3 is a SECOND copy of the snapshot: it is what
     * app_write_resume_snapshot() writes, and the main-menu Exit row calls that writer
     * with no capture in front of it. So deleting the store record while this field
     * still holds b1 == 1 leaves a resumable run in the process, and the next exit
     * puts it back. Asserting only the store, as the first version of this check did,
     * is exactly the gap the report came through.
     *
     * A deliberately distinctive payload, so "cleared" cannot be satisfied by a field
     * that happens to be zero for some unrelated reason.
     */
    memory_cleared = app.resume_record3.b1 == BOUNCE_PERSISTENCE_RECORD3_B1_NONE
        && app.resume_record3.level == 0u
        && app.resume_record3.score == 0
        && app.resume_record3.lives == 0;
    if (!memory_cleared) {
        fprintf(stderr,
                "reset: the in-memory snapshot survived the reset"
                " (b1=%u level=%u score=%d lives=%d)\n",
                app.resume_record3.b1,
                app.resume_record3.level,
                app.resume_record3.score,
                (int)app.resume_record3.lives);
        bad++;
    }

    /*
     * AND THEN THE EXIT ROW, WHICH IS WHERE IT WAS OBSERVED. Leaving the Reset page,
     * walking to Exit and pressing it is the whole reported sequence. If the in-memory
     * copy is still live the writer puts it straight back into the store, and the only
     * way to see that is to read the store again afterwards -- so this is asserted, not
     * assumed.
     *
     * NOTHING IS PLANTED HERE, and that is deliberate. An earlier version of this block
     * re-seeded app->resume_record3 with a live snapshot after asserting it had been
     * cleared, and then asserted the Exit row wrote nothing -- which cannot both be
     * true and is not the reported scenario at all. The report is a player who reset,
     * walked out and found Continue alive; the copy they had is the one the reset was
     * supposed to destroy. So the sequence here is exactly theirs: confirm, leave, exit,
     * relaunch.
     *
     * Planting a snapshot AFTER the reset would also be a weaker test, not a stronger
     * one: it would pass for any implementation, because a field the player cannot set
     * from the UI has no reason to be cleared by anything.
     */
    (void)bounce_app_flow_settings_back(&app.flow);
    (void)bounce_app_flow_settings_back(&app.flow);
    for (step = 0u; step < 9u; ++step)
        (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_UP);
    for (step = 0u; step < 9u; ++step)
        (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_DOWN);
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
        || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_EXIT) {
        fprintf(stderr,
                "reset: could not reach the Exit row (state=%d pending=%d)\n",
                (int)app.flow.state,
                (int)app.flow.menu.pending_action);
        bad++;
    }
    /*
     * "NOT RESUMABLE", NOT "ABSENT". The Exit row writes app->resume_record3
     * unconditionally, and after the fix that record is zeroed, so an all-zero
     * Record 3 reappears in the file. That is inert, and inert is the same thing to
     * every reader in the tree: app_refresh_continue_availability() requires
     * `present && (b1 == B1_IN_LEVEL || b1 == B1_LEVEL_COMPLETE)`, and
     * app_begin_resume_from_menu() refuses a record whose b1 is 0. So an absent record
     * and an all-zero record are indistinguishable to the player, and insisting on
     * absence here would be asserting a storage detail while missing the behaviour.
     *
     * What must not come back is a RESUMABLE one, so that is what is asserted.
     */
    exit_stays_deleted = bounce_persistence_load_record3(&back, &present) == 0
        && (!present
            || (back.b1 != BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL
                && back.b1 != BOUNCE_PERSISTENCE_RECORD3_B1_LEVEL_COMPLETE));
    if (!exit_stays_deleted) {
        fprintf(stderr,
                "reset: the Exit row wrote a RESUMABLE snapshot back"
                " (present=%d b1=%u level=%u lives=%d)\n",
                (int)present,
                present ? back.b1 : 0u,
                present ? back.level : 0u,
                present ? (int)back.lives : 0);
        bad++;
    }
    bounce_game_shutdown(&app);

    /*
     * AND A RELAUNCH, because "absent from the store" and "greyed out on the menu" are
     * different claims and only the second is what a player sees. A fresh app is booted
     * against the same store and must report the row unavailable.
     */
    memset(&app, 0, sizeof app);
    if (bounce_game_init(&app) != 0 || bounce_game_enter_menu(&app) != 0) {
        fprintf(stderr, "reset: could not relaunch for the final check\n");
        bad++;
    } else {
        app_restore_persisted_settings(&app);
        app_refresh_continue_availability(&app);
        relaunch_stays_greyed = !app.flow.menu.continue_available;
        if (!relaunch_stays_greyed) {
            fprintf(stderr,
                    "reset: Continue is selectable again after a relaunch\n");
            bad++;
        }
        bounce_game_shutdown(&app);
    }

    if (bad == 0) {
        printf("RESET-TO-DEFAULT primed=levels9/high4321/theme5/audio-off"
               "/keypad-off/snapshot-live back=leaves-clean confirm=restored"
               " record3=%s memory=%s exit_leaves_nothing_resumable=%s"
               " relaunch=greyed"
               " records=max_levels%d/high0 theme=0 keypad=1"
               " continue=off PASS\n",
               record3_gone ? "deleted" : "PRESENT",
               memory_cleared ? "cleared" : "STALE",
               exit_stays_deleted ? "yes" : "RESUMABLE",
               BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT);
    }

finish:
    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    /*
     * The root is left in place, exactly as verify_record3_terminal_b1_contract()
     * leaves its own. It is not empty -- the store wrote a bounce/ subdirectory
     * under it -- so rmdir() would fail with ENOTEMPTY, and reaching past this
     * point to unlink the tree by hand would be the first place in this file that
     * deletes files it did not create. The environment is restored either way, so
     * nothing downstream can reach this root.
     */
    return bad == 0 ? 0 : -1;
}

/*
 * =============================================================================
 * STEP 38-RESET-UI -- verify_reset_page_pointer_and_hint()
 *
 * THE CLAIM. The Reset page behaves like every other Settings page for a pointer, and
 * it is the only Settings page that does not print the ESC BACK hint.
 *
 * WHY THIS IS NOT COVERED BY verify_reset_to_default(). That check drives the keyboard
 * and reads the store. It cannot see the two things that changed here, because both are
 * about how the page is PRESENTED: whether a click reaches the row, and whether the
 * footer words are on the screen. A click handler that returned 0 for every coordinate
 * and a renderer that drew the hint anyway would both leave that check completely
 * green, and each of those is a real defect a player would hit on the screen whose only
 * job is to ask whether to delete their save.
 *
 * THE BUG THIS FOUND, WHICH IS THE REASON IT IS WORTH HAVING ITS OWN CHECK.
 *
 * bounce_ui_shell_handle_click() carried a PRIVATE copy of the Settings root row
 * positions, five values long, at a 44/60/76/92 pitch, while the renderer drew the rows
 * at 28/42/56/70/84/98. Three separate defects:
 *
 *   1. THE ARRAY WAS TOO SHORT. It was sized by BOUNCE_SETTINGS_ROOT_ITEM_COUNT, which
 *      is six since the Reset row was added, but only five initialisers were given. C
 *      zero-fills the sixth, so the Reset row's hit band was at y = 0 -- the new row was
 *      unreachable by mouse no matter where the pointer was.
 *   2. THE PITCH WAS WRONG FOR EVERY ROW BUT THE FIRST, by +2, +4, +6 and +8 px.
 *   3. A wrong-but-near-miss band is worse than a dead one, because a player reads it as
 *      the game highlighting the wrong line rather than as two tables disagreeing.
 *
 * Both sides now read one table, ui_settings_root_row_y, so there is no second copy to
 * fall out of date. What is asserted below is not "the click lands on the Reset row" but
 * the stronger statement: EVERY root row is reachable, and at the y the renderer
 * actually draws it. Row 5 is the one that was silently dead, and a loop over all six
 * rows is what stops a future row from being dead the same way.
 *
 * THE FOOTER IS CHECKED AS PIXELS, NOT AS A FLAG. The renderer decides whether to draw
 * the hint, so reading a flag would test the flag and not the screen. Instead the band
 * the hint occupies is sampled and required to be empty of ink on the Reset page while
 * every other Settings page still fills it. Both halves matter: dropping the hint
 * everywhere would leave the Reset page correct and every other page broken.
 *
 * The baseline is captured from the panel's own background colour rather than assumed,
 * so this does not depend on the current palette. What it depends on is that the hint is
 * centred text at y = 115 and therefore paints rows 112..118 -- a band the panel border
 * at y = 123 and the Reset action rows at 101..122 do not intrude into. That separation
 * is the reason the sample can be as small as it is.
 *
 * NO I/O. Nothing here reads or writes the store.
 */
static int verify_reset_page_pointer_and_hint(void)
{
    BounceAppFlow flow;
    BounceSurface *surface;
    BounceRenderer *renderer;
    uint32_t hint_color = 0u;
    uint32_t panel_background = 0u;
    bool have_baseline = false;
    unsigned int index;
    unsigned int clicked;
    int footer_ink[BOUNCE_SETTINGS_PAGE_RESET + 1];
    int bad = 0;

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);
    /*
     * TO THE MENU FIRST. bounce_app_flow_enter_settings() is guarded on MENU, so a flow
     * sitting on the splash cannot open Settings at all. The splash is left by its own
     * tick count rather than by poking flow->state, because a test that sets the state
     * directly is a test that never proves the guard exists.
     */
    for (index = 0u; index <= BOUNCE_APP_SPLASH_TIMER_LIMIT; ++index) {
        if (bounce_app_flow_tick(&flow) != 0)
            break;
    }
    if (bounce_app_flow_tick(&flow) != 1
        || flow.state != BOUNCE_APP_STATE_MENU) {
        fprintf(stderr, "reset-ui: could not leave the splash\n");
        bounce_app_flow_init(&flow);
        return -1;
    }
    surface = bounce_surface_create();
    if (surface == NULL)
        return -1;
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        return -1;
    }

    /*
     * EVERY ROOT ROW IS REACHABLE, AT THE Y THE RENDERER DRAWS IT.
     *
     * The click is made at the top of the row's drawn band, y - 2, which is where the
     * highlight rectangle starts. Probing the top edge rather than the middle is
     * deliberate: it is the pixel row most likely to fall into a neighbouring row's band
     * under a wrong pitch, so it is the one that catches this class of bug. A second
     * probe at the bottom edge of the band covers the other direction.
     *
     * Each click is followed by a return to the root selection so the walk is not
     * cumulative, and the probe asserts the SELECTION rather than the effect -- this loop
     * is about "does the pointer reach the row", and verify_reset_to_default() is about
     * what happens next.
     */
    if (bounce_app_flow_enter_settings(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT) {
        fprintf(stderr, "reset-ui: could not open the Settings root\n");
        bad++;
    }
    for (index = 0u; index < BOUNCE_SETTINGS_ROOT_ITEM_COUNT; ++index) {
        int row_y = bounce_ui_shell_settings_root_row_y(index);

        /*
         * STARTING OVER TAKES TWO CALLS: bounce_app_flow_return_to_menu() to leave
         * whatever page the previous iteration opened, then enter_settings() to come
         * back.
         *
         * bounce_app_flow_settings_back() is the obvious choice here and it is the wrong
         * one twice over. From the ROOT it does not return to the root, it leaves
         * Settings for the main menu -- correct for the Back key, and it meant the first
         * iteration ran in SETTINGS while every later one ran in MENU, where a click at a
         * root row's y lands on empty space. From a sub-page it returns to the root but
         * leaves the state at SETTINGS, and enter_settings() is guarded on MENU.
         *
         * return_to_menu() accepts both, so it is the one call that makes the loop
         * position-independent. Going through the menu is also the route the player's own
         * BACK key takes, which makes this the same journey rather than a shortcut.
         */
        if (bounce_app_flow_return_to_menu(&flow) != 0
            || bounce_app_flow_enter_settings(&flow) != 0
            || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT) {
            fprintf(stderr, "reset-ui: could not re-open the Settings root\n");
            bad++;
            break;
        }
        /* Neutral: a click that reaches the row must not also activate a wrong one. */
        clicked = bounce_ui_shell_handle_click(
            &flow,
            24,
            row_y - 2
        );
        if (!clicked
            || bounce_app_flow_settings_selected_index(&flow) != index) {
            fprintf(stderr,
                    "reset-ui: a click at the top of Settings root row %u did not"
                    " reach it (clicked=%u index=%u)\n",
                    index,
                    clicked,
                    bounce_app_flow_settings_selected_index(&flow));
            bad++;
            continue;
        }
        /*
         * ACTIVATE, WHICH MAY ALREADY HAVE HAPPENED.
         *
         * Row 0 starts highlighted, so its first click opens it; every other row needs a
         * second click to activate after the first one moved the highlight. The loop
         * clicks once and then only clicks again if the page is still the root, rather
         * than assuming a fixed number of clicks.
         *
         * Assuming "two clicks, always" was wrong and hid a real asymmetry: it made row
         * 0 look broken, because the second click lands on the page row 0 opened and
         * correctly does nothing.
         */
        if (bounce_app_flow_settings_page(&flow) == BOUNCE_SETTINGS_PAGE_ROOT)
            clicked = bounce_ui_shell_handle_click(&flow, 24, row_y - 2);
        if (!clicked || bounce_app_flow_settings_page(&flow)
                != (BounceSettingsPage)((int)index + 1)) {
            fprintf(stderr,
                    "reset-ui: Settings root row %u did not open its page"
                    " (clicked=%u page=%d)\n",
                    index,
                    clicked,
                    (int)bounce_app_flow_settings_page(&flow));
            bad++;
        }
    }
    /*
     * AND NOTHING ELSE IN THE ROOT LIST IS CLICKABLE. A stray click in the gap under
     * the last row must not select a row, because the band geometry above is asserted
     * in pixels and a click handler that accepted everything would pass every one of
     * those assertions.
     */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_enter_settings(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT) {
        fprintf(stderr, "reset-ui: could not re-open the Settings root\n");
        bad++;
    } else {
        /*
         * A CLICK THAT MUST SELECT NOTHING. The probe is the empty strip between the
         * title separator at y = 18 and the first row's band at y = 26, NOT the space
         * below the last row: below it lies the Back band, which is a real control on
         * this screen and answers a click correctly. The first version of this probe
         * sat at y = 113 and reported that the strip below the list selected a row,
         * which was the Back band working.
         *
         * A handler that accepted every coordinate would pass all six row assertions
         * above, so this is what stops that loop from passing for the wrong reason.
         */
        clicked = bounce_ui_shell_handle_click(&flow, 24, 22);
        if (clicked
            || bounce_app_flow_settings_selected_index(&flow) != 0u) {
            fprintf(stderr,
                    "reset-ui: a click on the empty strip above the list was"
                    " accepted (clicked=%u index=%u)\n",
                    clicked,
                    bounce_app_flow_settings_selected_index(&flow));
            bad++;
        }
    }

    /*
     * THE RESET PAGE'S TWO ROWS, BY POINTER.
     *
     * CONFIRM first, and it is asserted to require the two-click form: the first click
     * moves the highlight, and the reset only happens on the second. That is the same
     * rule the root list follows, and verify_reset_to_default() proves the keyboard
     * route still confirms in one press from the highlighted row -- so the two pages
     * agree about what a click means.
     */
    if (bounce_app_flow_return_to_menu(&flow) != 0
        || bounce_app_flow_enter_settings(&flow) != 0) {
        fprintf(stderr, "reset-ui: could not re-open Settings for the Reset page\n");
        bad++;
    }
    for (index = 0u; index < BOUNCE_SETTINGS_ROOT_ITEM_COUNT - 1u; ++index) {
        if (bounce_app_flow_settings_move(&flow, BOUNCE_MENU_DIRECTION_DOWN) != 0)
            bad++;
    }
    if (bounce_app_flow_settings_select(&flow) != 0
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_RESET) {
        fprintf(stderr, "reset-ui: could not open the Reset page by keyboard\n");
        bad++;
    } else if (bounce_ui_shell_handle_click(
                   &flow, 24, bounce_ui_shell_reset_row_y(0) - 2) != 1) {
        fprintf(stderr, "reset-ui: a click on Confirm was not accepted\n");
        bad++;
    } else if (!bounce_app_flow_consume_reset_to_default(&flow)) {
        /*
         * ONE CLICK, NOT TWO.
         *
         * Confirm is the highlighted row the moment the page opens, so a click on it
         * acts immediately -- the same rule every list in the shell follows, where a
         * click on the already-highlighted row activates it. The earlier version of this
         * check expected a move-then-activate pair and read the one-click behaviour as a
         * bug, which was reading it backwards.
         *
         * Requiring two clicks here was also considered and rejected on the merits: it
         * would make the button that deletes a save behave differently in kind from
         * every other button in the shell, in exchange for protecting against a mis-click
         * on a row whose label says CONFIRM, on a page that takes a deliberate two-press
         * walk to reach. The flag is read here rather than acted on so this check still
         * touches no store.
         */
        fprintf(stderr,
                "reset-ui: a click on Confirm did not arm the reset\n");
        bad++;
    }
    /*
     * BACK by pointer. It must LEAVE the page, and leave without resetting. The page
     * change is asserted because that is the whole behaviour change of this step; the
     * "without resetting" half is the pending flag, which must still be clear.
     */
    if (bounce_ui_shell_handle_click(
            &flow, 24, bounce_ui_shell_reset_row_y(1) - 2) != 1
        || bounce_app_flow_settings_selected_index(&flow)
            != BOUNCE_SETTINGS_RESET_ROW_BACK) {
        fprintf(stderr, "reset-ui: a click on Back did not land on Back\n");
        bad++;
    } else if (bounce_app_flow_consume_reset_to_default(&flow)) {
        /*
         * AND MOVING THE HIGHLIGHT TO BACK MUST NOT ARM ANYTHING. This is the
         * mis-click protection that the one-click Confirm does not provide: a stray
         * click on the lower row cannot reset, and the destructive row is not the one
         * the pointer is on.
         */
        fprintf(stderr,
                "reset-ui: a click on Back armed the reset\n");
        bad++;
    } else if (bounce_ui_shell_handle_click(
                   &flow, 24, bounce_ui_shell_reset_row_y(1) - 2) != 1
        || bounce_app_flow_settings_page(&flow) != BOUNCE_SETTINGS_PAGE_ROOT
        || bounce_app_flow_consume_reset_to_default(&flow)) {
        fprintf(stderr,
                "reset-ui: Back by pointer did not leave the Reset page cleanly"
                " (page=%d)\n",
                (int)bounce_app_flow_settings_page(&flow));
        bad++;
    }

    /*
     * THE FOOTER, BY THE COLOUR THE HINT IS DRAWN IN.
     *
     * Counting every non-background pixel in the footer's rows does not work on this
     * page, and the first version of this check proved it: it reported 738 pixels of
     * "hint" on the Reset page, all of which were the BACK row's own highlight band and
     * label sitting in the same rows. The ESC hint is centred text at y = 115, so rows
     * 112..118 hold it -- and the two action rows have to live between the divider at
     * y = 98 and the panel edge at y = 123, which puts the BACK row's band at
     * 112..122. There is no sub-band of 112..118 that the Reset page leaves empty.
     *
     * So the test is about the HINT'S OWN COLOUR rather than about ink. The hint is drawn
     * in the accent role, and on both pages being compared -- the Settings root and the
     * Reset page -- the accent role is used for that hint and nothing else. The root rows
     * are highlight, selected_text and text; the Reset value rows are muted, text and
     * border. Counting pixels equal to the accent colour therefore counts the hint, and
     * on the Reset page there must be none of them.
     *
     * The accent colour is CALIBRATED from the screen rather than hard-coded, so this
     * keeps working under any of the thirteen color profiles and will not need touching
     * when one of them changes. Calibration reads the ROOT page, whose last row band ends
     * at y = 107 and which therefore has nothing but the hint below that.
     *
     * This is a stronger claim than "the band got emptier": it names the thing that must
     * be gone. A band that lost pixels for any other reason would still pass a
     * before-and-after comparison.
     */
    flow.settings.page = BOUNCE_SETTINGS_PAGE_ROOT;
    if (bounce_ui_shell_render_settings(surface, renderer, &flow) != 0) {
        fprintf(stderr, "reset-ui: could not render the Settings root\n");
        bad++;
    } else {
        int y;
        int x;

        /*
         * The panel background is sampled rather than assumed. The first version of this
         * calibration tested `pixel != 0`, which is true of the background too -- it is
         * 0xff121a30, not zero -- so it "found" the background and then measured the
         * Reset page's highlight band as if it were hint text. Reading the panel's own
         * colour is what makes the comparison mean anything.
         *
         * The sample point is x = 118, y = 105: inside the panel, past the right edge of
         * every 104 px highlight band and 11 px row, and below the last root row at
         * y = 98. Nothing is drawn there on any Settings page.
         */
        if (bounce_surface_get_pixel(surface, 118, 105, &panel_background) != 0) {
            fprintf(stderr, "reset-ui: could not read the panel background\n");
            bad++;
        } else {
            bool found = false;

            /*
             * The window is x 10..117, y 110..121: inside the panel's border on all four
             * sides (the frame is at x = 4 and x = 123, y = 4 and y = 123), below the
             * Settings root rows which end at y = 107, and above the panel's bottom edge.
             * Excluding the border matters and did not at first: the scan began at x = 4,
             * where the vertical frame sits, so it calibrated the border colour and then
             * reported the Reset page's own frame as 150 pixels of "hint".
             */
            for (y = 110; y < 122 && !found; ++y) {
                for (x = 10; x < 118; ++x) {
                    uint32_t pixel = 0u;

                    if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0)
                        break;
                    /*
                     * The first pixel that is not the panel IS a hint pixel: the root
                     * list ends at y = 107 and nothing else on this page is drawn
                     * between there and the bottom of the panel.
                     *
                     * `found` is what stops the search. Breaking out of the inner loop
                     * alone let the outer loop keep scanning and overwrite the colour
                     * with the last thing it found instead of the first, which is how a
                     * calibration meant to pick out hint text ended up holding the
                     * highlight colour and reporting 480 pixels of it on a page with no
                     * hint at all.
                     */
                    if (pixel != panel_background) {
                        hint_color = pixel;
                        found = true;
                        break;
                    }
                }
            }
            have_baseline = found;
        }
        if (!have_baseline) {
            fprintf(stderr,
                    "reset-ui: the Settings root does not draw the ESC BACK hint,"
                    " so the hint colour cannot be calibrated\n");
            bad++;
        }
    }

    for (index = BOUNCE_SETTINGS_PAGE_ROOT;
         index <= BOUNCE_SETTINGS_PAGE_RESET;
         ++index) {
        int ink = 0;
        int y;

        if (!have_baseline) {
            bad++;
            break;
        }
        flow.settings.page = (BounceSettingsPage)index;
        if (bounce_ui_shell_render_settings(surface, renderer, &flow) != 0) {
            fprintf(stderr, "reset-ui: could not render Settings page %u\n", index);
            bad++;
            continue;
        }
        for (y = 110; y < 122; ++y) {
            int x;

            for (x = 10; x < 118; ++x) {
                uint32_t pixel = 0u;

                if (bounce_surface_get_pixel(surface, x, y, &pixel) != 0) {
                    bad++;
                    break;
                }
                if (pixel == hint_color)
                    ++ink;
            }
        }
        footer_ink[index] = ink;
        if (index == BOUNCE_SETTINGS_PAGE_RESET) {
            if (ink != 0) {
                fprintf(stderr,
                        "reset-ui: the Reset page still draws the ESC BACK hint"
                        " (%d pixels of the hint colour)\n",
                        ink);
                bad++;
            }
        } else if (ink <= 0) {
            fprintf(stderr,
                    "reset-ui: Settings page %u lost its ESC BACK hint (%d pixels)\n",
                    index,
                    ink);
            bad++;
        }
    }

    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);

    if (bad == 0) {
        printf("RESET-PAGE-UI root_rows_clickable=%u dead_row=none"
               " confirm_one_click=yes back_row_click=yes back_leaves=yes"
               " footer_hint=reset-only"
               " footer_ink_reset=%d footer_ink_root=%d PASS\n",
               BOUNCE_SETTINGS_ROOT_ITEM_COUNT,
               footer_ink[BOUNCE_SETTINGS_PAGE_RESET],
               footer_ink[BOUNCE_SETTINGS_PAGE_ROOT]);
    }
    return bad == 0 ? 0 : -1;
}

/*
 * =============================================================================
 * STEP CONTINUE-RETURN -- verify_continue_survives_submenus()
 *
 * THE BUG, AS REPORTED. Play a level, press Escape back to the main menu, walk into
 * one of the sub-screens, come back -- and the Continue row is GREYED OUT, so the run
 * cannot be resumed and the player has to start over. They still had lives, the
 * snapshot was still in the store, and nothing had deleted it.
 *
 * WHY THE EXISTING CHECKS COULD NOT SEE IT.
 *
 * verify_continue_entry_wiring() drives Continue from a menu it built and never leaves.
 * verify_continue_publication() asserts the store is written correctly at a terminal
 * arrival. verify_record3_terminal_b1_contract() round-trips a record. All three are
 * about the record and the handoff, and all three would stay green while the row was
 * hidden on the one path a player actually walks.
 *
 * The gap is a PAIR of responsibilities that never met:
 *
 *   bounce_app_flow_enter_menu() RESETS the menu. bounce_app_flow_reset_menu() sets
 *   continue_available = false and enabled_item_count = 6, because ShowMainMenu()
 *   rebuilds the list and BounceGame.java:116 decides the Continue row from the live K
 *   and J. Correct in isolation, and it is why the row is right on the way IN and wrong
 *   on the way OUT.
 *
 *   app_refresh_continue_availability() DERIVES the row from the store. It was wired to
 *   exactly two arrivals -- the splash -> menu transition and the Escape edge out of
 *   canonical gameplay -- so every other arrival into the menu rebuilt the row as absent
 *   and nothing put it back.
 *
 * The fix re-derives on any arrival that was not already at the menu. What has to be
 * asserted is therefore not "Continue works" but the ROUND TRIP: a menu with a live
 * snapshot -> a sub-screen -> the menu again -> still live. That is the thing which was
 * broken, and it is a claim no existing assertion made.
 *
 * EVERY SUB-SCREEN IS WALKED, not just one. Settings, High Score, Instructions and
 * About all leave through the same BACK edge, so one of them would prove the mechanism,
 * and all four prove it is not attached to a single destination by accident. Level
 * Select is included for a different reason: it is reachable from New Game, which is one
 * row BELOW Continue, so a player who takes that route has to come back twice.
 *
 * THE FIXTURE IS PRIMED AND THEN PROVEN, so "still available" cannot be satisfied by a
 * flag that was never cleared either. The pre-condition is a live Record 3 in the store
 * AND a menu that reports Continue as available; a reset-in-place would pass the whole
 * check with the row permanently absent.
 *
 * AND THE OPPOSITE IS ASSERTED TOO, because a fix that simply always showed the row
 * would also pass every assertion above. With no snapshot in the store, the row must be
 * unavailable on the same round trip. Both halves together are what makes this a test of
 * the derivation rather than of a constant.
 *
 * THE PLAYER'S REAL SAVE IS NEVER TOUCHED. Every store access runs under the discipline
 * bounce_persistence_verify() uses: a private mkdtemp root published through
 * XDG_DATA_HOME, restored on every path including the failure ones.
 */
static int verify_continue_survives_submenus(void)
{
    static const char template[] = "/tmp/bounce-continue-XXXXXX";
    char root[sizeof template];
    char saved[1024];
    int saved_ok;
    X11PresentationContext context;
    XEvent event;
    BounceApp app;
    BouncePersistenceRecord3 prime;
    BouncePersistenceRecord3 back;
    bool present = false;
    bool primed_ok;
    bool available_before = false;
    bool all_survived = true;
    bool absent_is_greyed = true;
    unsigned int leg;
    unsigned int step;
    int bad = 0;

    memset(&app, 0, sizeof app);
    memcpy(root, template, sizeof template);
    if (mkdtemp(root) == NULL) {
        fprintf(stderr, "continue-return: could not create a private store root\n");
        return -1;
    }
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0) {
        fprintf(stderr, "continue-return: could not publish the private store root\n");
        return -1;
    }

    memset(&prime, 0, sizeof prime);
    prime.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    prime.level = 4u;
    prime.score = 31415;
    prime.lives = 2;
    prime.ball_size = 12u;
    prime.unk_x = 168;
    prime.unk_y = 72;
    primed_ok = bounce_persistence_save_record3(&prime) == 0;
    if (!primed_ok) {
        fprintf(stderr, "continue-return: could not prime the private store\n");
        bad++;
    }

    if (bounce_game_init(&app) != 0 || bounce_game_enter_menu(&app) != 0) {
        fprintf(stderr, "continue-return: the app could not reach the menu\n");
        bounce_game_shutdown(&app);
        goto finish;
    }
    app_restore_persisted_settings(&app);
    /*
     * THE SAME DERIVATION THE ESCAPE EDGE RUNS, so the fixture starts in the state the
     * reported walk started in: a menu that is offering a live save.
     */
    app_refresh_continue_availability(&app);
    available_before = app.flow.menu.continue_available
        && bounce_app_flow_menu_row_for_selection(&app.flow, 0u) == 0u;
    if (!available_before) {
        fprintf(stderr,
                "continue-return: the fixture did not produce an available"
                " Continue row\n");
        bad++;
    }

    dispatch_fixture_context(&context);
    /*
     * FOUR ROUND TRIPS. Each leg moves the highlight down to one destination, activates
     * it, presses BACK, and requires the row to still be there.
     *
     * The row indices are the SELECTION indices of a menu whose Continue IS available,
     * so they match the row numbers: 1 New game, 2 High score, 3 Instructions, 4
     * Settings, 5 About. Settings is at 4 here and at 3 without Continue, which is why
     * the offsets are written out rather than derived from a shared constant that would
     * be wrong for half of them.
     */
    for (leg = 0u; leg < 4u; ++leg) {
        unsigned int steps;
        unsigned int step;
        int state_after_back;
        int enabled_after_back;
        unsigned int row0_after_back;

        /* Walk back to the top of the menu first, so each leg is independent. */
        for (step = 0u; step < leg + 1u; ++step)
            (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_UP);

        for (steps = 0u; steps <= leg; ++steps) {
            if (bounce_app_flow_menu_move(
                    &app.flow, BOUNCE_MENU_DIRECTION_DOWN) != 0)
                bad++;
        }
        fill_key_event(&event, KeyPress, 36u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0)
            bad++;
        if (app.flow.state == BOUNCE_APP_STATE_MENU) {
            fprintf(stderr,
                    "continue-return: leg %u did not leave the menu"
                    " (selection=%u)\n",
                    leg,
                    app.flow.menu.selected_index);
            bad++;
            all_survived = false;
            continue;
        }
        fill_key_event(&event, KeyPress, 9u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Escape) != 0)
            bad++;
        state_after_back = (int)app.flow.state;
        enabled_after_back = (int)bounce_app_flow_menu_item_enabled(&app.flow, 0u);
        row0_after_back
            = bounce_app_flow_menu_row_for_selection(&app.flow, 0u);

        if (state_after_back != (int)BOUNCE_APP_STATE_MENU
            || !app.flow.menu.continue_available
            || enabled_after_back != 1
            || row0_after_back != 0u
            || app.flow.menu.enabled_item_count != BOUNCE_MENU_ROW_COUNT) {
            fprintf(stderr,
                    "continue-return: Continue did not survive leg %u"
                    " (state=%d avail=%d row0_enabled=%d row0=%u"
                    " enabled_count=%u)\n",
                    leg,
                    state_after_back,
                    (int)app.flow.menu.continue_available,
                    enabled_after_back,
                    row0_after_back,
                    app.flow.menu.enabled_item_count);
            bad++;
            all_survived = false;
        }
        /*
         * AND THE SNAPSHOT MUST STILL BE THERE. A row that is offered while the record
         * behind it has gone is worse than a missing row, because pressing it then
         * refuses at the handoff.
         */
        if (bounce_persistence_load_record3(&back, &present) != 0 || !present
            || back.b1 != BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL
            || back.level != prime.level
            || back.score != prime.score) {
            fprintf(stderr,
                    "continue-return: the snapshot was disturbed by leg %u\n",
                    leg);
            bad++;
        }
    }

    /*
     * THE OPPOSITE HALF. Delete the record, take one more round trip, and the row must
     * be absent. Without this the whole check would also be satisfied by a row that is
     * permanently present, which is the other way to get this wrong.
     */
    (void)bounce_persistence_delete_record3();
    fill_key_event(&event, KeyPress, 9u, 1u, 100u);
    /* Leave the menu state cleanly: go to High Score and come back. */
    for (step = 0u; step < 3u; ++step)
        (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_UP);
    (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_DOWN);
    (void)bounce_app_flow_menu_move(&app.flow, BOUNCE_MENU_DIRECTION_DOWN);
    fill_key_event(&event, KeyPress, 36u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
        || app.flow.state == BOUNCE_APP_STATE_MENU) {
        fprintf(stderr, "continue-return: could not reach a sub-screen to leave\n");
        bad++;
    }
    fill_key_event(&event, KeyPress, 9u, 1u, 100u);
    if (x11_dispatch_event(&context, &app, &event, XK_Escape) != 0
        || app.flow.state != BOUNCE_APP_STATE_MENU
        || app.flow.menu.continue_available
        || bounce_app_flow_menu_item_enabled(&app.flow, 0u) != 0
        || app.flow.menu.enabled_item_count != BOUNCE_MENU_ROW_COUNT - 1u) {
        fprintf(stderr,
                "continue-return: Continue was still offered with no snapshot"
                " (state=%d avail=%d row0_enabled=%d enabled_count=%u)\n",
                (int)app.flow.state,
                (int)app.flow.menu.continue_available,
                (int)bounce_app_flow_menu_item_enabled(&app.flow, 0u),
                app.flow.menu.enabled_item_count);
        bad++;
        absent_is_greyed = false;
    }

    bounce_game_shutdown(&app);

    if (bad == 0) {
        printf("CONTINUE-RETURN primed=level4/score31415/lives2 legs=4"
               " survived=%s snapshot_intact=yes absent_is_greyed=%s PASS\n",
               all_survived ? "yes" : "no",
               absent_is_greyed ? "yes" : "no");
    }

finish:
    /*
     * This guard repoints XDG_DATA_HOME at its own roots several times, so it restores
     * the caller's on the way out exactly as the rest of the file's I/O guards do.
     */
    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    return bad == 0 ? 0 : -1;
}

/*
 * STEP PERSIST-ISOLATE -- THIS FUNCTION NOW RUNS AGAINST A PRIVATE STORE.
 *
 * IT DID NOT US TO, AND IT WAS WRITING THE PLAYER'S REAL SAVE.
 *
 * What it does below includes bounce_persistence_save_record3() with a primed record,
 * and several bounce_persistence_load_*() round trips, with nothing standing between
 * those calls and the live store. Every other verifier in this file that touches the
 * filesystem -- verify_record3_terminal_b1_contract(), verify_reset_to_default(),
 * verify_continue_survives_submenus(), bounce_persistence_verify() -- publishes a
 * private mkdtemp root through XDG_DATA_HOME and restores the caller's environment on
 * every path. This one did not, so it was the single hole in that discipline.
 *
 * THE DAMAGE, AND HOW IT WAS FOUND. A report that a fresh install showed a selectable
 * Continue row with no play session behind it. The store held a snapshot reading
 *
 *     b1=1  lives=3  level=2  score=1122  x=30 y=18
 *
 * Every one of those numbers is this function's `primed` fixture -- score 1122 and
 * x = 30, y = 18 appear nowhere else in the tree, and hoops_scored was 0, which no real
 * session can be while carrying a score of 1122. The record had not been played; it had
 * been written by the test suite. high_score = 5000 sat alongside it for the same reason,
 * from a level-11 completion a helper in this same function drove.
 *
 * That is worse than a noisy test. `make check` is documented as something that never
 * reaches the player's save, and this made that untrue, so a developer's own testing
 * invented a Continue row in the install they were testing against -- and a fresh
 * XDG_DATA_HOME did not help, because the hole is in the writer rather than in the
 * path.
 *
 * The isolation is the same mkdtemp-root-under-XDG_DATA_HOME discipline as everywhere
 * else, applied around the whole body rather than around the individual calls, because
 * the calls are interleaved with gameplay helpers that also persist and there is no
 * single point at which the store is exclusively under this function's control.
 */
/*
 * STEP PERSIST-ISOLATE -- THE CALLER'S XDG_DATA_HOME AS IT WAS AT PROCESS START.
 *
 * Captured unconditionally, before any mode is dispatched, and BY COPY. Both details are
 * load-bearing and both were got wrong first:
 *
 *   UNCONDITIONALLY, because a first version captured it inside main()'s --check branch.
 *   The negative control that disables that branch therefore also removed the capture,
 *   and the guard then had no original to compare against and passed with the run-wide
 *   isolation deleted. The thing that checks the isolation cannot live inside the thing
 *   it checks.
 *
 *   BY COPY, because setenv() invalidates the pointer getenv() returns. Keeping the
 *   pointer would make the guard compare the private root against itself, always pass.
 */
static char *bounce_check_original_xdg = NULL;
/* The private root the self-test runs against; see main(). */
static char bounce_check_private_root[64] = { 0 };

static int verify_persistence_flow(void);
static int verify_persistence_flow_body(void);

/*
 * Reads a store file whole so two of them can be compared byte for byte.
 * Returns the length, or -1; the caller owns *out.
 */
static long bounce_guard_read_store(const char *root, unsigned char **out)
{
    char path[1024];
    FILE *file;
    long size;
    unsigned char *buffer;

    *out = NULL;
    if (snprintf(path, sizeof path, "%s/bounce/records.bin", root)
        >= (int)sizeof path)
        return -1;
    file = fopen(path, "rb");
    if (file == NULL)
        return -1;
    if (fseek(file, 0L, SEEK_END) != 0) {
        (void)fclose(file);
        return -1;
    }
    size = ftell(file);
    if (size <= 0 || fseek(file, 0L, SEEK_SET) != 0) {
        (void)fclose(file);
        return -1;
    }
    buffer = (unsigned char *)malloc((size_t)size);
    if (buffer == NULL) {
        (void)fclose(file);
        return -1;
    }
    if (fread(buffer, 1u, (size_t)size, file) != (size_t)size) {
        free(buffer);
        (void)fclose(file);
        return -1;
    }
    (void)fclose(file);
    *out = buffer;
    return size;
}

/*
 * =============================================================================
 * STEP PERSIST-ISOLATE -- verify_check_never_touches_the_real_store()
 *
 * THE CLAIM. Running the self-test must not change the player's save by one byte.
 *
 * WHY IT NEEDS A CHECK OF ITS OWN. The suite reached the real store for a long time
 * without anybody noticing, and the report that eventually exposed it described a
 * SYMPTOM rather than a cause: a brand new install offered a selectable Continue row with
 * no session behind it. The record held
 *
 *     b1=1  lives=3  level=2  score=1122  x=30 y=18  hoops_scored=0
 *
 * Every one of those is a test fixture -- score 1122 and x = 30, y = 18 appear nowhere
 * else in the tree, and a score of 1122 alongside hoops_scored = 0 is impossible in a
 * real session. Around thirty functions could reach a store write and only four published
 * a private root, so the property rested on a list of call sites that had to be kept in
 * step with the call graph by hand. That is precisely how it came to be wrong.
 *
 * WHY IT DOES NOT INSPECT THE CALL GRAPH. Asking which functions call a writer is what
 * produced that list, and a list is what let the bug through. So this asserts the
 * OBSERVABLE: a store of our own stands in for the player's, the suite is pointed
 * somewhere else exactly as main() now points it, and the stand-in must come back
 * byte-for-byte identical.
 *
 * THE SLICE IS ONE FUNCTION, AND THAT IS THE POINT. verify_persistence_flow() is the
 * function whose fixture values were found in the player's save, so it alone is enough to
 * have failed before the fix. Nothing else is called: a check that drags in a second
 * subsystem is a check that can fail for a second subsystem's reasons, and this one is
 * about exactly one thing.
 *
 * THE STAND-IN IS NOT EMPTY. It is primed with a different level, score and lives through
 * the real write API, because "unchanged" against an absent file would be satisfied by a
 * suite that wrote nothing at all -- including a suite that crashed on its first call.
 */
static int verify_check_never_touches_the_real_store(void)
{
    static const char template[] = "/tmp/bounce-guard-XXXXXX";
    char caller_root[sizeof template];
    char inner_root[sizeof template];
    char saved[1024];
    int saved_ok;
    BouncePersistenceRecords primed;
    BouncePersistenceRecord3 snapshot;
    unsigned char *before = NULL;
    unsigned char *after = NULL;
    long before_len;
    long after_len;
    bool differ = false;
    bool slice_ran;
    int bad = 0;

    memcpy(caller_root, template, sizeof caller_root);
    if (mkdtemp(caller_root) == NULL) {
        fprintf(stderr, "store guard: could not create the stand-in store\n");
        return -1;
    }
    memcpy(inner_root, template, sizeof inner_root);
    if (mkdtemp(inner_root) == NULL) {
        fprintf(stderr, "store guard: could not create the suite store\n");
        return -1;
    }

    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));

    /* Prime the stand-in through the real API, under its own root. */
    (void)setenv("XDG_DATA_HOME", caller_root, 1);
    memset(&primed, 0, sizeof primed);
    primed.max_levels = 7;
    primed.high_score = 12345;
    memset(&snapshot, 0, sizeof snapshot);
    snapshot.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    snapshot.level = 5u;
    snapshot.score = 999;
    snapshot.lives = 2;
    if (bounce_persistence_save(&primed) != 0
        || bounce_persistence_save_record3(&snapshot) != 0) {
        fprintf(stderr, "store guard: could not prime the stand-in store\n");
        if (saved_ok)
            (void)setenv("XDG_DATA_HOME", saved, 1);
        else
            (void)unsetenv("XDG_DATA_HOME");
        return -1;
    }
    before_len = bounce_guard_read_store(caller_root, &before);
    if (before_len <= 0 || before == NULL) {
        fprintf(stderr, "store guard: could not read the stand-in store\n");
        free(before);
        if (saved_ok)
            (void)setenv("XDG_DATA_HOME", saved, 1);
        else
            (void)unsetenv("XDG_DATA_HOME");
        return -1;
    }

    /* Point the suite somewhere else, exactly as main() now does for --check. */
    (void)setenv("XDG_DATA_HOME", inner_root, 1);
    slice_ran = verify_persistence_flow() == 0;

    /* Back to the stand-in, and read it again. */
    (void)setenv("XDG_DATA_HOME", caller_root, 1);
    after_len = bounce_guard_read_store(caller_root, &after);
    if (after_len != before_len) {
        differ = true;
    } else if (after != NULL) {
        for (long i = 0; i < before_len; ++i) {
            if (before[i] != after[i]) {
                differ = true;
                break;
            }
        }
    }
    free(before);
    free(after);

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");

    /*
     * THE RUN-WIDE LAYER, WHICH THE BYTE COMPARISON CANNOT SEE.
     *
     * The comparison above points one verifier at its own root and checks that a store it
     * was NOT given came back unchanged. That tests the per-verifier layer, and it stays
     * true with main()'s run-wide override deleted -- the verifier still has a root of its
     * own -- so deleting the override was caught by nothing while around thirty other
     * verifiers went on writing to the player's save.
     *
     * So the mechanism is asserted directly: while the suite runs, the store the
     * environment resolves to must not be the one the caller started with. That is the
     * whole claim, and it is why the original is captured at process start.
     */
    {
        const char *current = getenv("XDG_DATA_HOME");
        const char *original = bounce_check_original_xdg;

        /*
         * `original == NULL` IS LEGITIMATE: most callers have no XDG_DATA_HOME at all,
         * and the private root is then the only value there ever was. An earlier version
         * treated a missing original as a failure and rejected every run on a machine
         * that had not set the variable -- which is the common case, and it failed on
         * correct code.
         *
         * So the claim is the two things that are actually true either way: the variable
         * is set while the suite runs, and it is not the value the caller supplied.
         */
        if (current == NULL) {
            fprintf(stderr,
                    "store guard: the self-test runs with XDG_DATA_HOME unset, so a"
                    " verifier with no private root of its own would write to the"
                    " default location\n");
            bad++;
        } else if (original != NULL && strcmp(current, original) == 0) {
            fprintf(stderr,
                    "store guard: --check is still using the caller's store (%s)\n",
                    current);
            bad++;
        }
    }

    if (!slice_ran) {
        fprintf(stderr, "store guard: the suite slice reported a failure\n");
        bad++;
    }
    if (differ) {
        fprintf(stderr,
                "store guard: --check MODIFIED the caller's store"
                " (%ld bytes before, %ld after)\n",
                before_len,
                after_len);
        bad++;
    }
    if (bad == 0) {
        printf("STORE-GUARD stand_in=%ld bytes suite_slice=verify_persistence_flow"
               " caller_store=unchanged run_wide_override=active PASS\n",
               before_len);
    }
    return bad == 0 ? 0 : -1;
}

static int verify_persistence_flow(void)
{
    static const char template[] = "/tmp/bounce-pflow-XXXXXX";
    char root[sizeof template];
    /* persistence.h keeps BOUNCE_PERSISTENCE_PATH_MAX private to its own
     * translation unit, so the saved value is copied into a local buffer. */
    char saved[1024];
    int saved_ok;
    int result;

    memcpy(root, template, sizeof template);
    if (mkdtemp(root) == NULL) {
        fprintf(stderr, "persistence flow: could not create a private store root\n");
        return -1;
    }
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (setenv("XDG_DATA_HOME", root, 1) != 0) {
        fprintf(stderr, "persistence flow: could not publish the private store root\n");
        return -1;
    }

    result = verify_persistence_flow_body();

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    /*
     * The root is left in place, as every other verifier's is: the store wrote a
     * bounce/ subdirectory under it, so rmdir would fail with ENOTEMPTY, and reaching
     * past this point to unlink the tree would be the first place in this file that
     * deletes files it did not create. The environment is restored either way, so
     * nothing downstream can reach it.
     */
    return result;
}

static int verify_persistence_flow_body(void)
{
    BounceAppFlow flow;

    memset(&flow, 0, sizeof flow);
    bounce_app_flow_init(&flow);

    /*
     * Fresh install: LoadRecords() leaves everything at its default.
     *
     * STEP 38-RESET -- THE UNLOCKED COUNT IS NOW PART OF THAT DEFAULT, and this is
     * one of the two places the shipped value is asserted; verify_default_state() is
     * the other, and it additionally pins high score, theme, audio, keypad and
     * language.
     *
     * The old assertion was `available_level_count == 0`, which said "a fresh install
     * publishes no level count at all" -- true while the Java-faithful store left the
     * count for the store to supply, and no longer true now that a new install ships
     * with levels 1 and 2 playable. The comment above the line is the reason to be
     * careful: it claims LoadRecords() left things alone, and it still does. What
     * changed is what a fresh flow carries BEFORE any record is read, which is a
     * documented default rather than an absence of one.
     *
     * The constant is used instead of a literal so that a future change to the shipped
     * default has to be made in one place, and so that this assertion cannot drift
     * away from the value that is actually shipped while still looking like it is
     * checking something.
     */
    if (flow.high_score != 0
        || flow.level_selection.available_level_count
            != BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 0)
        return -1;

    /* Strict comparison: a higher score raises the record and reports 1. */
    if (bounce_app_flow_note_score(&flow, 1500) != 1)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 1500)
        return -1;

    /* A tie is not an update, which is what stops a redundant write. */
    if (bounce_app_flow_note_score(&flow, 1500) != 0)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 1500)
        return -1;

    /* A lower score never lowers the record. */
    if (bounce_app_flow_note_score(&flow, 3) != 0)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 1500)
        return -1;

    /* MaxLevels from a store populates the level-selection view. */
    if (bounce_app_flow_restore_persisted(&flow, 4, 9000) != 0)
        return -1;
    if (flow.level_selection.available_level_count != 4u)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 9000)
        return -1;

    /* Restore never lowers an existing record. */
    if (bounce_app_flow_restore_persisted(&flow, 2, 10) != 0)
        return -1;
    if (bounce_app_flow_high_score(&flow) != 9000)
        return -1;

    /* A count beyond the last level is refused, not clamped upward. */
    if (bounce_app_flow_restore_persisted(
            &flow, BOUNCE_APP_LAST_LEVEL_ID + 5, 0) != -1)
        return -1;

    if (bounce_app_flow_note_score(NULL, 1) != -1)
        return -1;
    if (bounce_app_flow_high_score(NULL) != 0)
        return -1;
    /*
     * TUGAS 2b -- the color-profile restore.
     *
     * BounceGame.java:276-279 is the source's own fresh-install rule for an
     * absent record: the game keeps running with the default. That is the rule
     * applied to a color profile that has no Java line behind it -- a missing or
     * out-of-range stored value leaves the DEFAULT profile in place and is not an
     * error, because a saved setting must never be able to leave the application
     * without a usable palette.
     *
     * Both theme_index and applied_theme_index are checked, because the Settings
     * page highlights theme_index: setting only the applied value would leave the
     * page disagreeing with the palette actually in use, which is the bug this
     * stage fixes.
     */
    /*
     * D-02 -- THE hideNotify EDGE.
     *
     * e.java:473-480 is the whole subject:
     *
     *     public void hideNotify() {
     *         if (this.H) {
     *             if (this.aq != null)
     *                 this.aq.a();
     *             this.game.ShowMainMenu();
     *         }
     *         this.H = true;
     *     }
     *
     * Four things are checked, one per part of that, and the last is the one a
     * reader would otherwise get wrong.
     *
     * 1. NOT IN GAMEPLAY IS NOT AN EDGE. Java's `if (this.H)` gate exists because
     *    H is cleared by the two terminal transitions (e.java:323, :433), i.e.
     *    exactly when the canvas has already left the display. So a focus loss
     *    while the menu is up must do nothing at all, and native reproduces the
     *    gate by requiring the canonical gameplay state.
     *
     * 2. IN GAMEPLAY IT CLEARS THE KEY MASK AND RETURNS TO THE MENU. The held key
     *    is what makes this observable: without the clear, a key held when focus
     *    was lost -- whose KeyRelease never reaches a window that does not have
     *    focus -- would still be down on the next level. This is the same latch
     *    the D-19 half of e.java:476 prevents, reached here by the platform.
     *
     * 3. IT WRITES NOTHING TO THE STORE. hideNotify is not destroyApp:
     *    Bounce.java:25, the only Record 3 writer, is reached from commandAction's
     *    `display.getCurrent() == this.c` branch (BounceGame.java:256-258), which
     *    focus loss never is. The store is primed with a known Record 3 and must
     *    come back byte-identical, which is what keeps this from quietly becoming
     *    a second snapshot writer -- the same point D-14 turns on.
     */
    {
        BounceApp focus;
        BouncePersistenceRecord3 primed;
        BouncePersistenceRecord3 readback;
        bool present = false;
        bool mask_cleared_ok;
        bool menu_ok;
        bool store_untouched_ok;

        /* 1 -- the gate: the splash and the MENU are both not edges. */
        memset(&focus, 0, sizeof focus);
        if (bounce_game_init(&focus) != 0
            || bounce_game_enter_menu(&focus) != 0
            || app_apply_focus_lost(&focus) != 0
            || app_apply_focus_lost(&focus) != 0
            || focus.flow.state != BOUNCE_APP_STATE_MENU
            || app_apply_focus_lost(NULL) != -1) {
            bounce_game_shutdown(&focus);
            return -1;
        }
        bounce_game_shutdown(&focus);

        /* 2 and 3 -- the real edge: a key held, and a primed store. */
        memset(&focus, 0, sizeof focus);
        if (bounce_game_init(&focus) != 0
            || drive_app_to_gameplay_entry_start_level(&focus) != 0
            || app_update_production_game(&focus) != 0
            || !app_canonical_gameplay_active(&focus)) {
            bounce_game_release_level(&focus);
            return -1;
        }
        /* f.a()'s effect is only observable with a key actually held. */
        if (bounce_input_apply_source(
                &focus.input, BOUNCE_INPUT_SOURCE_RIGHT_ARROW, true) != 0
            || !focus.input.right) {
            bounce_game_release_level(&focus);
            return -1;
        }
        memset(&primed, 0, sizeof primed);
        primed.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
        primed.level = 2u;
        primed.score = 1122;
        primed.lives = 3;
        primed.ball_size = 12u;
        primed.unk_x = 30;
        primed.unk_y = 18;
        primed.tile_x = 2;
        primed.tile_y = 1;
        if (bounce_persistence_save_record3(&primed) != 0
            || bounce_persistence_load_record3(&readback, &present) != 0
            || !present) {
            bounce_game_release_level(&focus);
            return -1;
        }

        if (app_apply_focus_lost(&focus) != 1) {
            bounce_game_release_level(&focus);
            return -1;
        }
        mask_cleared_ok = !focus.input.right
            && focus.input.held_sources == UINT64_C(0);
        menu_ok = focus.flow.state == BOUNCE_APP_STATE_MENU
            && focus.state == BOUNCE_GAME_STATE_MENU;
        store_untouched_ok = false;
        memset(&primed, 0, sizeof primed);
        if (bounce_persistence_load_record3(&primed, &present) == 0
            && present)
            store_untouched_ok = memcmp(&primed, &readback, sizeof readback) == 0;
        bounce_game_release_level(&focus);

        if (!mask_cleared_ok || !menu_ok || !store_untouched_ok) {
            fprintf(stderr,
                    "focus loss: mask=%d menu=%d store=%d\n",
                    (int)mask_cleared_ok, (int)menu_ok, (int)store_untouched_ok);
            return -1;
        }
        printf("FOCUS-LOSS e.java:473-480 gate=H_only held_key_cleared=yes"
               " returns_to_menu=yes store_untouched=yes PASS\n");
    }

    {
        BounceAppFlow themed;

        bounce_app_flow_init(&themed);
        if (bounce_app_flow_restore_persisted_theme(NULL, 1) != -1)
            return -1;
        if (bounce_app_flow_restore_persisted_theme(&themed, -1) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed) != 0u)
            return -1;
        if (bounce_app_flow_restore_persisted_theme(
                &themed,
                (int)BOUNCE_UI_THEME_COUNT) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed) != 0u)
            return -1;
        if (bounce_app_flow_restore_persisted_theme(
                &themed,
                (int)BOUNCE_UI_THEME_COUNT + 1000) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed) != 0u)
            return -1;

        if (bounce_app_flow_restore_persisted_theme(&themed, 4) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed) != 4u)
            return -1;
        themed.settings.theme_index = 9u;
        if (bounce_app_flow_restore_persisted_theme(&themed, 7) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed) != 7u
            /* The Settings page highlight must follow the applied value, not
             * contradict it. */
            || themed.settings.theme_index != 7u)
            return -1;
        /* The last valid index is accepted: the bound is not off by one. */
        if (bounce_app_flow_restore_persisted_theme(
                &themed,
                (int)BOUNCE_UI_THEME_COUNT - 1) != 0
            || bounce_app_flow_settings_applied_theme_index(&themed)
                != BOUNCE_UI_THEME_COUNT - 1u)
            return -1;
    }

    /*
     * TUGAS 2b -- THE END-TO-END CONTRACT: CLOSE, REOPEN, SAME PROFILE.
     *
     * The two halves above test the layer and the flow separately. What the stage
     * is actually for is the round trip through the real store, driven through
     * the same two functions main() uses, with the same isolation the
     * persistence self-test uses: XDG_DATA_HOME is redirected at a temporary
     * directory so a real save is never read or written.
     *
     * "CLOSE" IS app_persist_theme() plus the restoration that shutdown does NOT
     * perform -- there is deliberately no unload-time write, because Java commits
     * a setting when the player commits it (BounceGame.java:420, :425) and not at
     * shutdown. So the sequence below is the whole life of a profile: choose it,
     * commit it, drop the whole application state, build a brand-new one, read
     * it back.
     */
    {
        static const char template[] = "/tmp/bounce-theme-XXXXXX";
        char root[sizeof template];
        char saved[512];
        int saved_ok;
        bool round_trip_ok;
        BounceApp first;
        BounceApp second;
        unsigned int profile;

        memcpy(root, template, sizeof template);
        if (mkdtemp(root) == NULL)
            return -1;
        saved_ok = (getenv("XDG_DATA_HOME") != NULL);
        if (saved_ok)
            (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
        if (setenv("XDG_DATA_HOME", root, 1) != 0)
            return -1;

        /* Choose a profile that is neither the default nor the last one, so a
         * "the value was never stored" failure cannot masquerade as success. */
        profile = BOUNCE_UI_THEME_COUNT - 3u;

        memset(&first, 0, sizeof first);
        if (bounce_game_init(&first) != 0
            || bounce_game_enter_menu(&first) != 0) {
            if (saved_ok)
                (void)setenv("XDG_DATA_HOME", saved, 1);
            else
                (void)unsetenv("XDG_DATA_HOME");
            return -1;
        }
        if (bounce_app_flow_restore_persisted_theme(
                &first.flow,
                (int)profile) != 0) {
            bounce_game_shutdown(&first);
            if (saved_ok)
                (void)setenv("XDG_DATA_HOME", saved, 1);
            else
                (void)unsetenv("XDG_DATA_HOME");
            return -1;
        }
        /* THE CLOSE. This is the forced-quit commit: XK_q and the Exit row both
         * funnel through exactly this call. */
        app_persist_theme(&first);
        bounce_game_shutdown(&first);

        /* A brand-new application object, with nothing carried over in memory. */
        memset(&second, 0, sizeof second);
        round_trip_ok = (bounce_game_init(&second) == 0
            && bounce_game_enter_menu(&second) == 0);
        if (round_trip_ok) {
            /* THE REOPEN. The same function main() calls. */
            app_restore_persisted_settings(&second);
            /*
             * And the same mirroring app_update_ui() performs before the first
             * frame. It is called here rather than left implicit because the
             * palette is a single global in ui_shell.c, not flow state, so
             * asserting it without running the mirror would be asserting nothing.
             */
            (void)app_update_ui(&second);
            round_trip_ok =
                bounce_app_flow_settings_applied_theme_index(&second.flow)
                    == profile
                /* The Settings page must also show the restored row, or the
                 * player is told one thing and shown another. */
                && second.flow.settings.theme_index == profile
                /* And the palette actually in use must follow. */
                && bounce_ui_shell_active_color_profile() == profile;
        }
        if (round_trip_ok) {
            /*
             * A fresh install has no record 4 and must report the DEFAULT, which
             * is what makes "the record was really read" distinguishable from
             * "the default happened to match". This is checked on a store that
             * has just been shown to hold a non-default value, so it can only
             * pass if the read is of the record and not of a constant.
             */
            int32_t stored = -1;
            round_trip_ok =
                bounce_persistence_load_theme_index(&stored) == 0
                && (unsigned int)stored == profile;
        }
        bounce_game_shutdown(&second);

        /*
         * EVERYTHING BELOW MUST STILL RUN INSIDE THE REDIRECTED ENVIRONMENT.
         *
         * An earlier draft of this block restored XDG_DATA_HOME here, before the
         * second phase -- which meant that phase read and wrote the developer's
         * REAL store. It failed, so nothing was corrupted, but it would have
         * overwritten a real color profile on any machine where the value
         * happened to differ. The restore now happens once, at the very end,
         * after both phases, and the one early return below has been removed so
         * there is no path that skips it.
         */
        if (round_trip_ok) {
            /*
             * The OTHER production commit, through the helper the X11 event loop
             * uses. Two phases, because they are two different calls in the tree:
             * app_commit_theme_change() runs when the player picks a profile, and
             * app_persist_theme() runs on the two exit routes. A third phase
             * changes the profile again and commits it through the helper, so
             * both are shown to reach the store.
             *
             * The "no change writes nothing" half is checked here too, because it
             * is the reason the helper takes the previous value at all: after the
             * first commit the store already holds `profile`, so committing again
             * would be indistinguishable -- the assertion is that the helper
             * does NOT write, which is observable only by changing the value
             * afterwards and observing the OLD one is gone.
             */
            const unsigned int other = 1u;
            memset(&first, 0, sizeof first);
            round_trip_ok = (bounce_game_init(&first) == 0
                && bounce_game_enter_menu(&first) == 0
                && bounce_app_flow_restore_persisted_theme(
                       &first.flow, (int)other) == 0);
            /* A no-op commit: the value already matches, so nothing is written. */
            if (round_trip_ok) {
                int32_t stored = -1;
                app_commit_theme_change(&first, other);
                round_trip_ok =
                    bounce_persistence_load_theme_index(&stored) == 0
                    && (unsigned int)stored == profile;
            }
            /*
             * The real commit. `profile` is what the page was showing before the
             * player moved to `other`, so the helper sees a change and writes --
             * and the store moves from `profile` to `other`, which is what makes
             * the no-op assertion above falsifiable rather than vacuous.
             */
            if (round_trip_ok) {
                int32_t stored = -1;
                app_commit_theme_change(&first, profile);
                round_trip_ok =
                    bounce_persistence_load_theme_index(&stored) == 0
                    && (unsigned int)stored == other;
            }
            bounce_game_shutdown(&first);
        }
        if (saved_ok)
            (void)setenv("XDG_DATA_HOME", saved, 1);
        else
            (void)unsetenv("XDG_DATA_HOME");
        if (!round_trip_ok)
            return -1;
        printf("THEME-PERSIST record=4 store=%s reopen_profile=%u"
               " settings_row_agrees=yes palette_applied=yes"
               " change_time_commit=yes no_op_writes_nothing=yes PASS\n",
               "records.bin", profile);
    }

    if (bounce_app_flow_restore_persisted(NULL, 1, 1) != -1)
        return -1;
    return 0;
}

typedef struct BounceShotRequest {
    const char *file;
    const char *what;
} BounceShotRequest;

static int bounce_shot_capture(
    BounceApp *app,
    BounceSurface *surface,
    BounceRenderer *renderer,
    const char *dir,
    const char *file
)
{
    char path[1024];
    int written;

    if (snprintf(path, sizeof path, "%s/%s.png", dir, file)
        >= (int)sizeof path)
        return -1;
    if (render_app_state(surface, renderer, app) != 0)
        return -1;
    written = bounce_shot_write_png(path, surface);
    if (written == 0)
        printf("SHOT %-28s %s\n", file, path);
    return written;
}

/*
 * =============================================================================
 * STEP SAVE-DIR -- verify_save_directory_precedence()
 *
 * THE CLAIM. The store goes where the caller said, in this order:
 *
 *     $BOUNCE_SAVE_DIR        an explicit override
 *     $XDG_DATA_HOME          the standard
 *     $HOME/.local/share      the standard's default
 *
 * WHY THE ORDER MATTERS AND WHY IT NEEDS A CHECK. The override was added for a
 * portable checkout and for throwaway instances while testing a build, and both of
 * those are exactly the situations where writing to the wrong place is worst: a test
 * instance that quietly reads the real save, or a portable copy that silently does not
 * carry its progress. Both fail silently, so the order is asserted rather than
 * documented.
 *
 * EACH CASE IS PROVEN BY WRITING AND LOOKING, NOT BY READING THE RESOLVED STRING.
 * bounce_persistence_path() is public, so asserting on it would be the obvious thing
 * and would be weaker: it would pass if the resolver returned the right string while
 * the writer ignored it. So each case writes a record and then asks which file
 * appeared.
 *
 * THE PROCESS IS FRESH FOR EVERY CASE, because bounce_persistence_path() resolves once
 * and caches for the life of the process. Re-pointing the variables inside one process
 * would be measured against the first resolution and every case after the first would
 * agree with it whatever it said. The program is therefore re-executed, which is why
 * this needs system() and a real path rather than the in-process calls the rest of the
 * file's guards use.
 *
 * ONE CASE IS ASSERTED BY ITS ABSENCE. The XDG case has to show that the override is
 * NOT consulted, which a positive assertion cannot show -- a file in the XDG location
 * proves nothing if the override also writes there. So the override directory is
 * checked for the absence of a store after an XDG-only run.
 */
/*
 * STEP SAVE-DIR -- an FNV-1a digest of a whole file, used only by case 5 below.
 *
 * FNV-1a rather than a real hash because the claim being checked is "these bytes are
 * the same bytes", which any deterministic function answers, and this program already
 * links libpng rather than a crypto library. 0 is returned for "could not read it",
 * which no content can produce, so an unreadable file never compares equal to a
 * readable one.
 */
static uint64_t digest_file(const char *path)
{
    unsigned char buffer[512];
    FILE *file = fopen(path, "rb");
    uint64_t hash = 1469598103934665603ull;
    size_t got;

    if (file == NULL)
        return 0u;
    while ((got = fread(buffer, 1u, sizeof buffer, file)) > 0u) {
        size_t index;

        for (index = 0u; index < got; index++) {
            hash ^= (uint64_t)buffer[index];
            hash *= 1099511628211ull;
        }
    }
    (void)fclose(file);
    return hash;
}

/*
 * STEP SAVE-DIR -- THE CHILD MODE THE PRECEDENCE CHECK RUNS.
 *
 * It resolves the store, writes one record, prints the path it used, and exits. Three
 * things about that are deliberate:
 *
 * IT IS NOT `--check`. A first version had the precedence check shell out to
 * `bounce_vertical_slice --check`, which is the obvious thing to reach for and hangs
 * forever: the child runs the whole suite, which includes the precedence check, which
 * shells out again. The failure looks like a slow test rather than a recursion -- the
 * run just stopped at rc=124 -- so it is worth naming.
 *
 * IT WRITES BEFORE IT PRINTS. Printing the resolved path alone would prove the
 * resolver agrees with itself, which is the weak version: a resolver that returned the
 * right string while the writer ignored it would pass. Writing first means the path
 * printed is the path something was actually stored at.
 *
 * IT PRINTS THE PATH. That is what makes the check able to tell "the override won"
 * from "both roots were written", which a positive assertion about one file cannot.
 */
static int bounce_save_plant_probe(void)
{
    BouncePersistenceRecords planted;
    BouncePersistenceRecord3 snapshot;
    const char *path = bounce_persistence_path();

    if (path == NULL) {
        fprintf(stderr, "no save path could be resolved\n");
        return -1;
    }
    /*
     * WHY A SECOND CHILD MODE. Case 5 needs a store whose bytes are NOT the probe's, so
     * that a probe which overwrites it can be detected by comparing content. Planting it
     * with the probe itself does not work: the probe is deterministic, so the "before"
     * and "after" files would be identical whether or not the overwrite happened, and
     * the comparison would pass either way. An earlier version of case 5 did exactly
     * that and its negative control was reported NOT CAUGHT, which is what caught it.
     *
     * So this writes a store that no probe run produces: a different high score, and a
     * Record 3 with a live session in it. That is also the honest shape of the claim --
     * what a player loses is a snapshot and a score, not an empty container.
     */
    /*
     * WRITTEN IN THREE STEPS, because the container holds more than
     * BouncePersistenceRecords does: records 1 and 2 come from bounce_persistence_save(),
     * Record 3 from bounce_persistence_save_record3(), and the color profile from
     * bounce_persistence_save_theme_index(). Each of the latter two is a
     * read-modify-write of the whole container and preserves the others, so calling them
     * in this order leaves all four records present.
     *
     * All four is the point. A probe writes records 1 and 2 and nothing else, so a store
     * carrying a snapshot and a theme is guaranteed to be distinguishable from anything
     * a probe run could leave behind -- which is the whole basis on which case 5 can
     * detect an overwrite at all.
     */
    memset(&planted, 0, sizeof planted);
    planted.max_levels = BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT;
    planted.high_score = BOUNCE_SAVE_PLANT_MARKER;
    memset(&snapshot, 0, sizeof snapshot);
    snapshot.b1 = BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL;
    snapshot.level = 7u;
    snapshot.score = BOUNCE_SAVE_PLANT_MARKER;
    snapshot.lives = 2;
    snapshot.ball_size = 12u;
    snapshot.unk_x = 168;
    snapshot.unk_y = 72;
    if (bounce_persistence_save(&planted) != 0
        || bounce_persistence_save_record3(&snapshot) != 0
        || bounce_persistence_save_theme_index(3) != 0) {
        fprintf(stderr, "could not plant the save probe at %s\n", path);
        return -1;
    }
    printf("%s\n", path);
    return 0;
}

static int bounce_save_path_probe(void)
{
    BouncePersistenceRecords probe;
    const char *path = bounce_persistence_path();

    if (path == NULL) {
        fprintf(stderr, "no save path could be resolved\n");
        return -1;
    }
    memset(&probe, 0, sizeof probe);
    /*
     * A value no real path produces, so a file found later in the WRONG root cannot be
     * this run's doing and has to be a leak from something else.
     */
    probe.max_levels = BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT;
    probe.high_score = BOUNCE_SAVE_PROBE_MARKER;

    /*
     * STEP SAVE-DIR -- DO NOT TOUCH A STORE THAT ALREADY EXISTS.
     *
     * This guard exists because the first version of this function destroyed the
     * player's save. --save-path is documented as "write one probe record and print the
     * store's resolved path", and against a fresh root that is harmless -- it is how
     * verify_save_directory_precedence() proves the writer followed the resolver. Run
     * by a person against a real install it overwrote their progress, score, unlocked
     * levels, theme and keypad with a zeroed record, and the suite could not catch it
     * because every one of its roots is a mkdtemp directory that starts empty.
     *
     * A command whose whole purpose is to answer "where does my save live" must never
     * cost the player their save. Reading the answer does not require writing, and where
     * writing IS required -- the self-test, on a root it just created -- the file does
     * not exist yet, so the strong assertion survives intact.
     */
    if (access(path, F_OK) == 0) {
        printf("%s\n", path);
        return 0;
    }
    if (bounce_persistence_save(&probe) != 0) {
        fprintf(stderr, "could not write the save probe to %s\n", path);
        return -1;
    }
    printf("%s\n", path);
    return 0;
}

static int verify_save_directory_precedence(void)
{
    static const char template[] = "/tmp/bounce-savedir-XXXXXX";
    char xdg_root[sizeof template];
    char override_root[sizeof template];
    char saved[1024];
    char marker_a[1024];
    char marker_b[1024];
    char command[1200];
    char self[1024];
    int saved_ok;
    int rc;
    int bad = 0;

    /*
     * Both roots have to exist and be EMPTY before the runs, or the "which file
     * appeared" answer below could be picking up something that was already there.
     * mkdtemp gives a fresh one; the override root is made the same way rather than
     * invented, so a leftover from an interrupted run cannot be mistaken for a result.
     */
    memcpy(xdg_root, template, sizeof xdg_root);
    if (mkdtemp(xdg_root) == NULL) {
        fprintf(stderr, "save-dir: could not create the XDG root\n");
        return -1;
    }
    memcpy(override_root, template, sizeof override_root);
    if (mkdtemp(override_root) == NULL) {
        fprintf(stderr, "save-dir: could not create the override root\n");
        return -1;
    }

    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    (void)unsetenv("BOUNCE_SAVE_DIR");

    /*
     * THE PROGRAM'S OWN PATH, from /proc/self/exe.
     *
     * A relative "./native/app/bounce_vertical_slice" would only be right when --check
     * was run from the repository root, which the Makefile arranges and a person typing
     * the binary's path directly does not. /proc/self/exe is exact, needs no argv[0] to
     * have survived, and this is a Linux-only build.
     */
    {
        ssize_t n = readlink("/proc/self/exe", self, sizeof self - 1u);

        if (n <= 0 || (size_t)n >= sizeof self - 1u) {
            fprintf(stderr, "save-dir: could not resolve this program's path\n");
            if (saved_ok)
                (void)setenv("XDG_DATA_HOME", saved, 1);
            return -1;
        }
        self[n] = '\0';
        /*
         * The path goes into a COMMAND, not just a path: system() runs it through a
         * shell, so a directory with a space in it would be split into two words and
         * the second would be an argument to the program. Single-quoting it here is
         * what makes a save directory with a space in its name work at all.
         */
        if (snprintf(command, sizeof command,
                     "'%s' --save-path", self)
            >= (int)sizeof command) {
            if (saved_ok)
                (void)setenv("XDG_DATA_HOME", saved, 1);
            return -1;
        }
    }

    /*
     * CASE 1 -- the override alone. This is the case the feature exists for, and it is
     * the only one that has to produce a file somewhere other than the standard
     * location.
     */
    (void)setenv("XDG_DATA_HOME", xdg_root, 1);
    (void)setenv("BOUNCE_SAVE_DIR", override_root, 1);
    rc = system(command);
    if (rc != 0) {
        fprintf(stderr, "save-dir: the override run failed (rc=%d)\n", rc);
        bad++;
    }
    if (snprintf(marker_a, sizeof marker_a, "%s/bounce/records.bin",
                 override_root) >= (int)sizeof marker_a
        || snprintf(marker_b, sizeof marker_b, "%s/bounce/records.bin",
                     xdg_root) >= (int)sizeof marker_b) {
        bad++;
    } else if (access(marker_a, F_OK) != 0) {
        fprintf(stderr,
                "save-dir: BOUNCE_SAVE_DIR was ignored; nothing at %s\n",
                marker_a);
        bad++;
    } else if (access(marker_b, F_OK) == 0) {
        fprintf(stderr,
                "save-dir: BOUNCE_SAVE_DIR wrote to BOTH roots (%s exists too)\n",
                marker_b);
        bad++;
    }

    /*
     * CASE 2 -- the override removed, so the standard takes over. Asserted by the
     * override root gaining nothing: a positive assertion about the XDG file cannot
     * distinguish "the standard was used" from "both were written".
     */
    (void)unsetenv("BOUNCE_SAVE_DIR");
    {
        char override_before[1024];

        if (snprintf(override_before, sizeof override_before,
                     "%s/bounce/records.bin",
                     override_root) < (int)sizeof override_before
            && access(override_before, F_OK) == 0) {
            (void)remove(override_before);
        }
    }
    rc = system(command);
    if (rc != 0) {
        fprintf(stderr, "save-dir: the XDG-only run failed (rc=%d)\n", rc);
        bad++;
    }
    if (access(marker_b, F_OK) != 0) {
        fprintf(stderr,
                "save-dir: with no override the store did not go to XDG (%s)\n",
                marker_b);
        bad++;
    }
    if (snprintf(marker_a, sizeof marker_a, "%s/bounce/records.bin",
                 override_root) < (int)sizeof marker_a
        && access(marker_a, F_OK) == 0) {
        fprintf(stderr,
                "save-dir: the override root was used with no override set (%s)\n",
                marker_a);
        bad++;
    }

    /*
     * CASE 3 -- THE FLAG, AND IT HAS TO BEAT THE VARIABLE ALREADY IN THE ENVIRONMENT.
     *
     * Case 1 proves the override is consulted; it says nothing about --save=, which is
     * the form a person at a terminal actually types and therefore the form most likely
     * to be broken by the flag being parsed after the store was read. So this case
     * drives the flag, with BOUNCE_SAVE_DIR pointed somewhere else entirely: if the flag
     * were dropped on the floor, or applied too late to beat the path cache, the store
     * would land in the variable's directory and the assertion below would say so.
     *
     * Two roots are in play and neither may be written, so the assertion is specific
     * about which one won rather than merely that something appeared.
     */
    (void)unsetenv("XDG_DATA_HOME");
    (void)setenv("BOUNCE_SAVE_DIR", override_root, 1);
    {
        char flag_root[sizeof template];
        char flag_store[1024];

        memcpy(flag_root, template, sizeof flag_root);
        if (mkdtemp(flag_root) == NULL) {
            fprintf(stderr, "save-dir: could not create the --save= root\n");
            bad++;
        } else if (snprintf(command, sizeof command,
                            "'%s' --save='%s' --save-path",
                            self, flag_root) >= (int)sizeof command) {
            bad++;
        } else if (system(command) != 0) {
            fprintf(stderr, "save-dir: the --save= run failed\n");
            bad++;
        } else if (snprintf(flag_store, sizeof flag_store, "%s/bounce/records.bin",
                            flag_root) >= (int)sizeof flag_store) {
            bad++;
        } else {
            if (access(flag_store, F_OK) != 0) {
                fprintf(stderr,
                        "save-dir: --save= was ignored; nothing at %s\n",
                        flag_store);
                bad++;
            }
            if (access(marker_a, F_OK) == 0) {
                fprintf(stderr,
                        "save-dir: --save= lost to BOUNCE_SAVE_DIR, which was"
                        " already set (%s was written)\n",
                        marker_a);
                bad++;
            }
        }
        (void)snprintf(flag_store, sizeof flag_store, "%s/bounce/records.bin",
                       flag_root);
        (void)remove(flag_store);
        {
            char bounce_dir[1024];

            (void)snprintf(bounce_dir, sizeof bounce_dir, "%s/bounce", flag_root);
            (void)rmdir(bounce_dir);
            (void)rmdir(flag_root);
        }
    }

    /*
     * CASE 4 -- A DIRECTORY THAT DOES NOT EXIST YET.
     *
     * --save= is for handing a build its own save, and the directory a person names is
     * routinely new: a scratch path under /tmp, a folder inside a checkout that has
     * never run the game. Nothing else creates it for them.
     *
     * Two new levels below the temp parent, so the chain <parent>/x/y/bounce has to be
     * built from nothing. Two is more than it takes to fail the two-level mkdir this
     * replaced; it is here so the intent reads as "from nothing" rather than "one level
     * happens to be enough".
     */
    {
        char parent[sizeof template];
        char target[1200];
        char created[1200];

        memcpy(parent, template, sizeof parent);
        if (mkdtemp(parent) == NULL) {
            fprintf(stderr, "save-dir: could not create the fresh-path parent\n");
            bad++;
        } else if (snprintf(target, sizeof target, "%s/x/y", parent)
                   >= (int)sizeof target) {
            bad++;
        } else if (snprintf(command, sizeof command, "'%s' --save='%s' --save-path",
                            self, target) >= (int)sizeof command) {
            bad++;
        } else if (system(command) != 0) {
            fprintf(stderr,
                    "save-dir: --save= into a missing directory failed\n");
            bad++;
        } else if (snprintf(created, sizeof created, "%s/bounce/records.bin", target)
                   >= (int)sizeof created) {
            bad++;
        } else if (access(created, F_OK) != 0) {
            fprintf(stderr,
                    "save-dir: the missing directories were not created;"
                    " nothing at %s\n",
                    created);
            bad++;
        }
        /*
         * Take the tree back by name, deepest first. Every level here was made by this
         * run, so each is named and removed explicitly. A recursive delete under a
         * directory the test itself chose is a much sharper thing to have in a test
         * suite than a handful of leftover files are.
         */
        {
            /*
             * Built from `parent`, not from `target`: target is <parent>/x/y, so a
             * suffix appended to it would name <parent>/x/y/x and remove nothing. That
             * mistake left a directory behind on every run before it was found.
             */
            static const char *const tails[] = {
                "/x/y/bounce/records.bin", "/x/y/bounce", "/x/y", "/x", ""
            };
            char victim[1200];
            size_t index;

            for (index = 0u;
                 index < sizeof tails / sizeof tails[0];
                 index++) {
                if (snprintf(victim, sizeof victim, "%s%s", parent, tails[index])
                    >= (int)sizeof victim)
                    continue;
                if (index == 0u)
                    (void)remove(victim);
                else
                    (void)rmdir(victim);
            }
        }
        (void)rmdir(parent);
    }

    /*
     * CASE 5 -- A STORE THAT ALREADY EXISTS MUST SURVIVE --save-path.
     *
     * This is the case that matters most to the person running the command. Cases 1-4
     * all used a store the run had just created, so every one of them was satisfied by
     * a probe that writes unconditionally -- which is exactly what destroyed the
     * player's real save the first time this command existed. Nothing in cases 1-4 could
     * have noticed, because in every one of them the file is SUPPOSED to change.
     *
     * SO IT IS COMPARED BY CONTENT, NOT BY EXISTENCE. Asserting the file still exists
     * would pass while the probe rewrote it, which is the bug. The digest covers the
     * whole file because a size comparison would miss a rewrite that happens to land on
     * the same length, which a zeroed record very nearly does.
     *
     * The store is planted by --save-plant, not by --save-path, because the probe is
     * deterministic: a probe-planted "before" file equals the probe's "after" file and
     * the comparison passes whether or not the overwrite happened. That mistake was made
     * once here and its negative control came back NOT CAUGHT, twice. A fixture built by
     * the program rather than by hand also avoids drifting from the container format.
     */
    {
        char parent[sizeof template];
        char store[1200];
        uint64_t first = 0u;
        uint64_t second = 0u;

        memcpy(parent, template, sizeof parent);
        if (mkdtemp(parent) == NULL) {
            fprintf(stderr, "save-dir: could not create the preserve parent\n");
            bad++;
        } else if (snprintf(store, sizeof store, "%s/x/bounce/records.bin", parent)
                   >= (int)sizeof store) {
            bad++;
        } else if (snprintf(command, sizeof command, "'%s' --save='%s/x' --save-plant",
                            self, parent) >= (int)sizeof command) {
            bad++;
        } else if (system(command) != 0) {
            fprintf(stderr, "save-dir: could not plant the store to preserve\n");
            bad++;
        } else if ((first = digest_file(store)) == 0u) {
            fprintf(stderr, "save-dir: the planted store was not readable\n");
            bad++;
        } else if (snprintf(command, sizeof command, "'%s' --save='%s/x' --save-path",
                            self, parent) >= (int)sizeof command) {
            bad++;
        } else if (system(command) != 0) {
            fprintf(stderr, "save-dir: the second --save-path run failed\n");
            bad++;
        } else if ((second = digest_file(store)) == 0u) {
            fprintf(stderr, "save-dir: the store vanished after --save-path\n");
            bad++;
        } else if (first != second) {
            fprintf(stderr,
                    "save-dir: --save-path overwrote an existing store"
                    " (%016llx -> %016llx at %s)\n",
                    (unsigned long long)first, (unsigned long long)second,
                    store);
            bad++;
        }
        {
            static const char *const tails[] = { "/x/bounce/records.bin",
                                                 "/x/bounce", "/x", "" };
            char victim[1200];
            size_t index;

            for (index = 0u;
                 index < sizeof tails / sizeof tails[0];
                 index++) {
                if (snprintf(victim, sizeof victim, "%s%s", parent, tails[index])
                    >= (int)sizeof victim)
                    continue;
                if (index == 0u)
                    (void)remove(victim);
                else
                    (void)rmdir(victim);
            }
        }
        (void)rmdir(parent);
    }

    /*
     * STEP SAVE-DIR -- CLEAN UP BOTH ROOTS.
     *
     * Each mkdtemp root holds exactly one file -- bounce/records.bin -- written by the
     * two child runs, so they can be taken back by name rather than by walking the
     * tree. Walking would be wrong here: the roots are inside /tmp, and a run that
     * deleted whatever it found under a directory it chose would be a far more
     * dangerous thing to have in the test suite than a few leftover files are.
     *
     * This is not tidiness for its own sake. An earlier run of this suite left 568 of
     * these behind, which is how a check that is supposed to be hermetic ends up
     * filling the disk over a few hundred nightly builds.
     */
    {
        static const char *const layers[] = { "/bounce/records.bin", "/bounce", "" };
        const char *roots[2];
        size_t root_index;
        size_t layer_index;

        roots[0] = xdg_root;
        roots[1] = override_root;
        for (root_index = 0u; root_index < 2u; root_index++) {
            for (layer_index = 0u;
                 layer_index < sizeof layers / sizeof layers[0];
                 layer_index++) {
                char victim[1024];

                if (snprintf(victim, sizeof victim, "%s%s",
                             roots[root_index], layers[layer_index])
                    >= (int)sizeof victim)
                    continue;
                if (layer_index == 0u)
                    (void)remove(victim);
                else
                    (void)rmdir(victim);
            }
        }
    }

    if (saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else
        (void)unsetenv("XDG_DATA_HOME");
    (void)unsetenv("BOUNCE_SAVE_DIR");

    if (bad == 0) {
        printf("SAVE-DIR override=%s beats_xdg=yes flag_beats_env=yes"
               " xdg_fallback=yes creates_missing=yes preserves_existing=yes"
               " default=unchanged PASS\n",
               "BOUNCE_SAVE_DIR");
    }
    return bad == 0 ? 0 : -1;
}

/*
 * =============================================================================
 * STEP SAVE-CONTINUE -- verify_save_and_continue_across_restart()
 *
 * THE CLAIM. Play a level, leave, start the program again, and Continue is there and
 * resumes the run that was saved -- position, level, lives, ball size and all.
 *
 * WHY IT NEEDS A CHECK OF ITS OWN, given that the store round trips are already covered.
 *
 * verify_reset_to_default() and verify_record3_terminal_b1_contract() both write a
 * Record 3 and read it back. Neither of them ever left the game. The defect this exists
 * for lives in the space between a good record on disk and the next process reading it,
 * and it was invisible to every store test in the tree: closing the window re-captured
 * the snapshot, the re-capture found no level loaded because the Escape had released
 * it, and the all-zero result was written over a perfectly good save.
 *
 * REPRODUCED, in an isolated store:
 *
 *     after Escape    record3 present  b1=1 level=1 lives=3 pos=(30,78)
 *     window closed   record3 present  b1=0 level=0 lives=0 pos=(0,0)
 *     relaunch        Continue NOT available
 *
 * So the store was correct right up until the moment the program quit, and every test
 * that stopped at the store said the save was fine.
 *
 * BOTH EXITS ARE DRIVEN, because they were different once and nothing guaranteed they
 * stayed that way. The main-menu Exit row writes app->resume_record3 without
 * re-capturing, which is the faithful shape -- Java's destroyApp takes b1 from the
 * sticky K and the payload from the live game object at BounceGame.java:355-361, and
 * neither is invalidated by walking to the menu. The ClientMessage close used to
 * re-capture, which is the bug. Asserting only one of them would have let the other
 * rot, and it was the other one that broke.
 *
 * THE RELAUNCH IS A GENUINELY FRESH BounceApp built the way main() builds one --
 * bounce_game_init(), enter_menu(), app_restore_persisted_settings() -- and then the
 * menu is read and Continue is pressed through x11_dispatch_event(). It is not a second
 * look at the same objects, because "the record on disk is still right" and "the next
 * process offers it" are different claims.
 *
 * AND THE EXIT IS A REAL ONE. The window close is the ClientMessage event the X11 loop
 * handles, and the Exit row is the SELECT that sets pending_action to EXIT. Neither is
 * simulated by calling the writer directly, because a test that calls the writer cannot
 * see the caller that surrounds it -- which is where the whole defect was.
 *
 * NO INTERACTION. The run is driven through app_update_production_game() until PLAYING
 * and then ticked, and the menu is driven with key events, so this needs no display and
 * no human.
 *
 * The private-store discipline is the same as everywhere else: a private mkdtemp root
 * published through XDG_DATA_HOME and restored on every path.
 */
static int verify_save_and_continue_across_restart(void)
{
    static const char template[] = "/tmp/bounce-saverestart-XXXXXX";
    char root[sizeof template];
    char saved[1024];
    int saved_ok;
    BouncePersistenceRecord3 first;
    BouncePersistenceRecord3 after;
    bool present = false;
    unsigned int exit_leg;
    int bad = 0;

    for (exit_leg = 0u; exit_leg < 2u; ++exit_leg) {
        BounceApp app;
        X11PresentationContext context;
        XEvent event;
        unsigned int guard;
        bool played = false;
        bool escaped = false;
        bool available = false;
        bool resumed = false;

        memset(&app, 0, sizeof app);
        memcpy(root, template, sizeof root);
        if (mkdtemp(root) == NULL) {
            fprintf(stderr, "save-restart: could not create a private store\n");
            return -1;
        }
        saved_ok = (getenv("XDG_DATA_HOME") != NULL);
        if (saved_ok)
            (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
        (void)setenv("XDG_DATA_HOME", root, 1);

        /* ---- play ---- */
        if (drive_app_to_gameplay_entry_start_level(&app) != 0) {
            bad++;
            goto leg_done;
        }
        for (guard = 0u; guard < 8192u; ++guard) {
            if (app_update_production_game(&app) != 0)
                break;
            if (app.state == BOUNCE_GAME_STATE_PLAYING) {
                played = true;
                break;
            }
        }
        if (!played) {
            fprintf(stderr,
                    "save-restart leg %u: level 1 never reached PLAYING\n",
                    exit_leg);
            bad++;
            goto leg_done;
        }
        for (guard = 0u; guard < 200u; ++guard) {
            BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

            (void)app_timer_callback_dispatch(&app, &branch);
        }
        /*
         * Nothing may be in the store yet. If a snapshot already existed, the rest of
         * the leg could not tell a save made on exit from one that was there before,
         * and the comparison below would be meaningless.
         */
        if (bounce_persistence_load_record3(&after, &present) != 0 || present) {
            fprintf(stderr,
                    "save-restart leg %u: a snapshot existed before the session"
                    " ended\n",
                    exit_leg);
            bad++;
            goto leg_done;
        }

        dispatch_fixture_context(&context);

        /* ---- leave gameplay for the menu, the production edge ---- */
        fill_key_event(&event, KeyPress, 9u, 1u, 100u);
        if (x11_dispatch_event(&context, &app, &event, XK_Escape) == 0
            && app.flow.state == BOUNCE_APP_STATE_MENU
            && app.flow.menu.continue_available) {
            escaped = true;
        }
        if (!escaped) {
            fprintf(stderr,
                    "save-restart leg %u: Escape did not reach an offering menu"
                    " (state=%d continue=%d)\n",
                    exit_leg,
                    (int)app.flow.state,
                    (int)app.flow.menu.continue_available);
            bad++;
            goto leg_done;
        }

        /*
         * `first` IS THE GOOD SAVE, read from the store after the menu arrival rather
         * than from app.resume_record3. Reading the field here would have compared the
         * exit against an empty record -- the field is only written by a capture, and no
         * capture has run yet at this point -- and the check passed nothing while
         * reporting every field as changed.
         *
         * timestamp is excluded because a capture stamps it, so a re-capture on exit
         * legitimately moves it while everything else must not.
         */
        if (bounce_persistence_load_record3(&first, &present) != 0
            || !present
            || first.b1 != BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL) {
            fprintf(stderr,
                    "save-restart leg %u: the menu arrival left no resumable"
                    " snapshot (present=%d b1=%u)\n",
                    exit_leg,
                    (int)present,
                    present ? first.b1 : 0u);
            bad++;
            goto leg_done;
        }
        first.timestamp_millis = 0u;

        /* ---- quit, by one route or the other ---- */
        if (exit_leg == 0u) {
            memset(&event, 0, sizeof event);
            event.type = ClientMessage;
            event.xclient.data.l[0] = 0;
            event.xclient.data.l[1] = 0;
            event.xany.serial = 1u;
            (void)x11_dispatch_event(&context, &app, &event, 0);
        } else {
            for (guard = 0u; guard < 9u; ++guard)
                (void)bounce_app_flow_menu_move(
                    &app.flow, BOUNCE_MENU_DIRECTION_UP);
            for (guard = 0u; guard < 9u; ++guard)
                (void)bounce_app_flow_menu_move(
                    &app.flow, BOUNCE_MENU_DIRECTION_DOWN);
            fill_key_event(&event, KeyPress, 36u, 1u, 100u);
            if (x11_dispatch_event(&context, &app, &event, XK_Return) != 0
                || app.flow.menu.pending_action != BOUNCE_MENU_ACTION_EXIT) {
                fprintf(stderr,
                        "save-restart leg %u: the Exit row was not reached"
                        " (pending=%d)\n",
                        exit_leg,
                        (int)app.flow.menu.pending_action);
                bad++;
                goto leg_done;
            }
        }
        bounce_game_shutdown(&app);

        /* ---- THE SAVE MUST HAVE SURVIVED THE EXIT ---- */
        if (bounce_persistence_load_record3(&after, &present) != 0 || !present) {
            fprintf(stderr,
                    "save-restart leg %u: the exit left no snapshot at all\n",
                    exit_leg);
            bad++;
            goto leg_done;
        }
        after.timestamp_millis = 0u;
        if (after.b1 != BOUNCE_PERSISTENCE_RECORD3_B1_IN_LEVEL) {
            fprintf(stderr,
                    "save-restart leg %u: the exit wrote an INERT record"
                    " (b1=%u level=%u lives=%d)\n",
                    exit_leg,
                    after.b1,
                    after.level,
                    (int)after.lives);
            bad++;
            goto leg_done;
        }
        if (after.level != first.level
            || after.lives != first.lives
            || after.score != first.score
            || after.unk_x != first.unk_x
            || after.unk_y != first.unk_y
            || after.ball_size != first.ball_size) {
            fprintf(stderr,
                    "save-restart leg %u: the saved run changed on the way out"
                    " (level %u->%u lives %d->%d score %d->%d"
                    " pos (%d,%d)->(%d,%d) ball %u->%u)\n",
                    exit_leg,
                    first.level, after.level,
                    (int)first.lives, (int)after.lives,
                    first.score, after.score,
                    first.unk_x, after.unk_x,
                    first.unk_y, after.unk_y,
                    first.ball_size, after.ball_size);
            bad++;
            goto leg_done;
        }

        /* ---- a genuinely fresh app, built the way main() builds one ---- */
        {
            BounceApp fresh;

            memset(&fresh, 0, sizeof fresh);
            if (bounce_game_init(&fresh) != 0
                || bounce_game_enter_menu(&fresh) != 0) {
                bad++;
                goto leg_done;
            }
            app_restore_persisted_settings(&fresh);
            app_refresh_continue_availability(&fresh);
            available = fresh.flow.menu.continue_available
                && fresh.flow.menu.enabled_item_count == BOUNCE_MENU_ROW_COUNT
                && fresh.flow.menu.selected_index == 0u;
            if (!available) {
                fprintf(stderr,
                        "save-restart leg %u: the relaunched menu does not offer"
                        " Continue (avail=%d enabled=%u selected=%u)\n",
                        exit_leg,
                        (int)fresh.flow.menu.continue_available,
                        fresh.flow.menu.enabled_item_count,
                        fresh.flow.menu.selected_index);
                bad++;
            } else {
                dispatch_fixture_context(&context);
                fill_key_event(&event, KeyPress, 36u, 1u, 100u);
                if (x11_dispatch_event(
                        &context, &fresh, &event, XK_Return) != 0) {
                    bad++;
                } else {
                    for (guard = 0u; guard < 8192u; ++guard) {
                        if (app_update_production_game(&fresh) != 0)
                            break;
                        if (fresh.state == BOUNCE_GAME_STATE_PLAYING
                            || fresh.level != NULL)
                            break;
                    }
                    resumed = fresh.level != NULL
                        && fresh.level_id == after.level
                        && fresh.lives == after.lives
                        && fresh.score == after.score
                        && fresh.player.TODO_unkX == after.unk_x
                        && fresh.player.TODO_unkY == after.unk_y
                        && fresh.player.ballSize == after.ball_size;
                    if (!resumed) {
                        fprintf(stderr,
                                "save-restart leg %u: Continue did not restore the"
                                " run (loaded=%s level %u vs %u lives %d vs %d"
                                " score %d vs %d pos (%d,%d) vs (%d,%d)"
                                " ball %u vs %u)\n",
                                exit_leg,
                                fresh.level != NULL ? "yes" : "NO",
                                fresh.level_id, after.level,
                                fresh.lives, (int)after.lives,
                                fresh.score, after.score,
                                fresh.player.TODO_unkX, after.unk_x,
                                fresh.player.TODO_unkY, after.unk_y,
                                fresh.player.ballSize, after.ball_size);
                        bad++;
                    }
                }
            }
            bounce_game_shutdown(&fresh);
        }

leg_done:
        if (saved_ok)
            (void)setenv("XDG_DATA_HOME", saved, 1);
        else
            (void)unsetenv("XDG_DATA_HOME");
    }

    if (bad == 0) {
        printf("SAVE-RESTART exits=window-close,menu-row"
               " saved=survives-both restarts=offers-continue resumes=exact"
               " PASS\n");
    }
    return bad == 0 ? 0 : -1;
}

static int bounce_shot_write_all(const char *dir)
{
    static const char template[] = "/tmp/bounce-shots-XXXXXX";
    char root[sizeof template];
    char saved[1024];
    int saved_ok;
    BounceSurface *surface;
    BounceRenderer *renderer;
    /*
     * THE SPLASH IS THE ONE SCREEN THAT NEEDS THE ASSETS. bounce_ui_shell_render_splash()
     * takes a BounceVisualAssets and refuses NULL, because it draws the recovered
     * bouncesplash.png rather than text. Every other screen here is drawn from the flow
     * alone, so this is loaded only so that one image is a real render and not a
     * placeholder -- and it is destroyed before returning, like the frame loop's.
     */
    BounceVisualAssets *visuals;
    BounceApp app;
    int bad = 0;
    int made_root;
    int shots = 0;

    if (dir == NULL || dir[0] == '\0') {
        fprintf(stderr, "screenshots: no output directory given\n");
        return -1;
    }

    /* The private-store discipline every other I/O path in this file follows. */
    memcpy(root, template, sizeof template);
    made_root = (mkdtemp(root) != NULL);
    saved_ok = (getenv("XDG_DATA_HOME") != NULL);
    if (saved_ok)
        (void)snprintf(saved, sizeof saved, "%s", getenv("XDG_DATA_HOME"));
    if (made_root)
        (void)setenv("XDG_DATA_HOME", root, 1);

    memset(&app, 0, sizeof app);
    surface = bounce_surface_create();
    if (surface == NULL) {
        bad++;
        goto restore;
    }
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        bounce_surface_destroy(surface);
        bad++;
        goto restore;
    }
    if (bounce_game_init(&app) != 0) {
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        bad++;
        goto restore;
    }
    visuals = bounce_visual_assets_create(BOUNCE_RESOURCE_ROOT);
    if (visuals == NULL) {
        fprintf(stderr, "screenshots: could not load the visual assets\n");
        bounce_game_shutdown(&app);
        bounce_renderer_destroy(renderer);
        bounce_surface_destroy(surface);
        bad++;
        goto restore;
    }
    app.visuals = visuals;
    /*
     * app_restore_persisted_settings() returns void, so it is called on its own line
     * rather than being made to return a status for a chain. The private root is empty,
     * so there is nothing in it to restore and the theme and keypad land on the shipped
     * defaults -- which is the state these images are meant to show.
     */
    app_restore_persisted_settings(&app);

    /*
     * THE STATES ARE SET DIRECTLY RATHER THAN BY PRESSING KEYS, and that is deliberate.
     *
     * The first version of this walked the flow with menu_move() and menu_select() the
     * way a player would, and it produced four of thirteen images and two identical
     * ones: the splash shot came out as the menu because enter_menu() had already run,
     * and a mis-counted walk landed several destinations on the wrong screen. None of
     * that is a reason to make the screenshots depend on navigation arithmetic.
     *
     * What these images have to be is what the renderer draws for a state a player can
     * reach. render_app_state() is the same dispatcher the frame loop uses, so naming a
     * state and calling it is the whole claim -- and there is no second drawing path
     * here that could drift from the game's.
     *
     * The gameplay shots are the exception and are NOT posed: those go through the
     * ordinary production update until PLAYING, then take more ticks, because a frame
     * of a level that never ran would be a picture of nothing.
     */
    app.flow.state = BOUNCE_APP_STATE_SPLASH;
    if (bounce_shot_capture(&app, surface, renderer, dir, "title-screen") != 0)
        bad++;
    else
        ++shots;

    /*
     * THE MENU IS ENTERED THE WAY IT IS ENTERED, not assigned: bounce_game_enter_menu()
     * is the production entry and it is what clears the flow for a real arrival. Only
     * then is the state assigned, and Continue is re-derived so the row shows the
     * no-save state rather than whatever enter_menu left behind.
     */
    if (bounce_game_enter_menu(&app) != 0) {
        bad++;
    } else {
        app_refresh_continue_availability(&app);
        if (bounce_shot_capture(
                &app, surface, renderer, dir, "main-menu") != 0)
            bad++;
        else
            ++shots;
    }

    app.flow.state = BOUNCE_APP_STATE_HIGH_SCORE;
    if (bounce_shot_capture(&app, surface, renderer, dir, "high-score") != 0)
        bad++;
    else
        ++shots;

    app.flow.state = BOUNCE_APP_STATE_INSTRUCTIONS;
    app.flow.instructions_scroll = 0u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "instructions") != 0)
        bad++;
    else
        ++shots;

    /* Level Select at the shipped default of two unlocked levels. */
    app.flow.state = BOUNCE_APP_STATE_LEVEL_SELECTION;
    app.flow.level_selection.available_level_count =
        (unsigned int)BOUNCE_DEFAULT_UNLOCKED_LEVEL_COUNT;
    app.flow.level_selection.selected_index = 0u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "level-select") != 0)
        bad++;
    else
        ++shots;

    /*
     * And the same list with progress, because at two rows a fresh Level Select reads as
     * a truncation rather than as a state. The count is the one a store with progress
     * would restore.
     */
    app.flow.level_selection.available_level_count = 9u;
    app.flow.level_selection.selected_index = 3u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "level-select-progress") != 0)
        bad++;
    else
        ++shots;

    /* Settings: the root with all six rows, then each sub-page. */
    app.flow.state = BOUNCE_APP_STATE_SETTINGS;
    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_ROOT;
    app.flow.settings.selected_index = 0u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-menu") != 0)
        bad++;
    else
        ++shots;

    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_LANGUAGE;
    app.flow.settings.language_index = 1u;
    app.flow.settings.applied_language_index = 1u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-language") != 0)
        bad++;
    else
        ++shots;

    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_THEME;
    app.flow.settings.theme_index = 4u;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-theme") != 0)
        bad++;
    else
        ++shots;

    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_INPUT;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-input-keypad") != 0)
        bad++;
    else
        ++shots;

    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_AUDIO;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-audio") != 0)
        bad++;
    else
        ++shots;

    /*
     * AND THE RESET PAGE, which is the screen this mode was added for: the one place
     * in the shell with no ESC BACK hint and a clickable BACK row.
     *
     * The values are set AWAY from the defaults first, on purpose. The page's whole
     * purpose is to state what it is about to change, so a picture of it showing six
     * defaults already at their defaults proves nothing -- and would be exactly what the
     * feature gets wrong if the list were computed from constants instead of read from
     * the flow.
     */
    app.flow.level_selection.available_level_count = 9u;
    app.flow.high_score = 4242;
    app.flow.menu.continue_available = true;
    app.flow.settings.audio_enabled = false;
    app.flow.settings.t9_input_enabled = true;
    app.flow.settings.applied_theme_index = 2u;
    app.flow.settings.theme_index = 2u;
    app.flow.settings.page = BOUNCE_SETTINGS_PAGE_RESET;
    app.flow.settings.selected_index = BOUNCE_SETTINGS_RESET_ROW_CONFIRM;
    if (bounce_shot_capture(
            &app, surface, renderer, dir, "settings-reset-confirm") != 0)
        bad++;
    else
        ++shots;

    app.flow.state = BOUNCE_APP_STATE_ABOUT;
    if (bounce_shot_capture(&app, surface, renderer, dir, "about") != 0)
        bad++;
    else
        ++shots;

    /* ---- gameplay: entered and then TICKED, never posed ---- */
    if (drive_app_to_gameplay_entry_start_level(&app) != 0) {
        bad++;
    } else {
        unsigned int guard;

        /*
         * RE-ATTACH THE ASSETS, because the driver just wiped them.
         *
         * drive_app_to_gameplay_entry_start_level() begins with memset(app, 0, sizeof
         * *app) and then bounce_game_init(), so app->visuals is NULL again. Without
         * this line draw_level_grid() takes the fallback rectangle for every tile --
         * which its own comment calls "fallback only for isolated tests that do not load
         * the original assets" -- and the gameplay image comes out as flat grey blocks
         * with the background showing through, instead of the level art. That is what a
         * first version of this produced.
         *
         * The assets are not reloaded: the pointer is unchanged and the set was created
         * once above. Re-creating them would be a second allocation the driver never
         * asked for and would have to be torn down twice.
         */
        app.visuals = visuals;

        for (guard = 0u; guard < 8192u; ++guard) {
            if (app_update_production_game(&app) != 0)
                break;
            if (app.state == BOUNCE_GAME_STATE_PLAYING
                && app.flow.state == BOUNCE_APP_STATE_GAMEPLAY)
                break;
        }
        if (app.state != BOUNCE_GAME_STATE_PLAYING) {
            fprintf(stderr,
                    "screenshots: level 1 never reached PLAYING (state=%d)\n",
                    (int)app.state);
            bad++;
        } else {
            int more;

            /*
             * OUT OF THE COUNTDOWN FIRST, THEN ONWARD.
             *
             * draw_level_banner() is gated on `p != 0` -- e.java:201 -- and the entry
             * countdown starts at BOUNCE_APP_ENTRY_COUNTDOWN, which is 120. So a frame
             * taken a few dozen ticks into PLAYING is still the banner over an empty
             * stage, which is what the first version of this captured: a dark screen
             * reading LEVEL 1. The old screenshot in the tree has the level grid, the
             * player and the HUD, so it was taken past this point and this has to be too.
             *
             * The wait is on the countdown rather than on a tick count, so it stays
             * correct if the entry countdown ever changes -- the same reason
             * verify_tick_cadence() drives on the period rather than on a frame count.
             */
            for (more = 0; more < 4096; ++more) {
                BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

                if (bounce_app_flow_entry_countdown(&app.flow) == 0)
                    break;
                /*
                 * app_timer_callback_dispatch(), NOT app_run_canonical_gameplay_tick().
                 *
                 * The countdown is decremented by bounce_app_flow_tick_pre_countdown(),
                 * which bounce_game_tick_dispatch() calls after its reset and splash
                 * gates -- the native e.java:258-259. The canonical tick is the level
                 * PHASE and does not go through that dispatch, so a first version of
                 * this looped on it and the countdown sat at 119 for four thousand
                 * iterations. The existing arrival and progression verifiers drive the
                 * same function, which is why it is used here too.
                 */
                if (app_timer_callback_dispatch(&app, &branch) != 0)
                    break;
            }
            if (bounce_app_flow_entry_countdown(&app.flow) != 0) {
                fprintf(stderr,
                        "screenshots: the entry countdown never expired (%d)\n",
                        bounce_app_flow_entry_countdown(&app.flow));
                bad++;
            } else {
                /* Then far enough that the ball has moved and it is not the spawn. */
                for (more = 0; more < 30; ++more) {
                    BounceTickDispatchBranch branch = BOUNCE_TICK_DISPATCH_RESET_GATE;

                    (void)app_timer_callback_dispatch(&app, &branch);
                }
                if (bounce_shot_capture(
                        &app, surface, renderer, dir, "gameplay-level-1") != 0)
                    bad++;
                else
                    ++shots;
            }
        }
    }

    bounce_game_shutdown(&app);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_visual_assets_destroy(visuals);
    app.visuals = NULL;

restore:
    if (made_root && saved_ok)
        (void)setenv("XDG_DATA_HOME", saved, 1);
    else if (made_root)
        (void)unsetenv("XDG_DATA_HOME");
    /*
     * The private root is left behind, as every other one in this file is: the store
     * wrote a bounce/ subdirectory under it, so rmdir would fail with ENOTEMPTY, and
     * unlinking the tree would be the first place here deleting files it did not create.
     * The environment is restored either way.
     */
    if (bad == 0) {
        printf("SHOTS %d files -> %s\n", shots, dir);
    } else {
        fprintf(stderr,
                "screenshots: %d of %d captures failed\n", bad, shots + bad);
    }
    return bad == 0 ? 0 : -1;
}

/*
 * =============================================================================
 * STEP README -- verify_readme_screenshots()
 *
 * THE CLAIM. Every screenshots/ image the README shows exists, and every image in
 * screenshots/ is shown by the README.
 *
 * WHY IT NEEDS A CLAIM AND NOT JUST A LOOK. Commit 8bdc651 replaced the screenshot set
 * with renders of the native build and correctly dropped language-selection.png -- this
 * build has no standalone language screen, language is chosen from Settings -> Language.
 * The README kept pointing at the deleted file, so the repository has had a broken image
 * on its front page ever since, and no test noticed because nothing compared the
 * document against the directory.
 *
 * The second half is the one that finds problems earlier. A render added to
 * screenshots/ and not added to the gallery is not a defect -- but it is how the missing
 * Settings pages went unlisted through five commits, and how the rot above became
 * possible in the first place: the gallery and the directory had drifted apart with
 * nothing asserting they still matched.
 *
 * THE ROOT IS TAKEN FROM /proc/self/exe, NOT FROM THE WORKING DIRECTORY. The rest of the
 * suite already depends on being run from the repository root because level and asset
 * paths are relative to it, but this check reads a file that has nothing to do with
 * gameplay, and pinning it to the binary's own location means it also works if that
 * dependency is ever removed.
 *
 * DUPLICATE REFERENCES ARE NOT AN ERROR and do not fail the check; only a reference that
 * does not resolve, and a file that is not referenced, are failures. Repeating an image
 * is a layout choice.
 */
#define BOUNCE_README_REFERENCE_LIMIT 64u
#define BOUNCE_README_PATH_MAX 1200

static int verify_readme_screenshots(void)
{
    char executable[1024];
    char root[1024];
    char readme[BOUNCE_README_PATH_MAX];
    char images[BOUNCE_README_PATH_MAX];
    char referenced[BOUNCE_README_REFERENCE_LIMIT][BOUNCE_README_PATH_MAX];
    char text[262144];
    const char *cursor;
    size_t reference_count = 0u;
    size_t image_count = 0u;
    ssize_t length;
    DIR *dir;
    struct dirent *entry;
    FILE *file;
    int bad = 0;
    size_t index;

    length = readlink("/proc/self/exe", executable, sizeof executable - 1u);
    if (length <= 0 || (size_t)length >= sizeof executable - 1u) {
        fprintf(stderr, "readme: could not resolve this program's path\n");
        return -1;
    }
    executable[length] = '\0';
    /*
     * IS THIS BINARY INSIDE A SOURCE CHECKOUT, AND WHERE IS THE CHECKOUT ROOT.
     *
     * Two components are stripped first, leaving ".../native", and the leaf of THAT is
     * what decides the scope. A checkout gives ".../nokia-bounce-linux/native"; the
     * AppImage gives ".../usr" because the package installs the binary at usr/bin. The
     * third strip then reaches the checkout root.
     *
     * THE SCOPE IS NOT COSMETIC. Without it this check made the AppImage's own --check
     * fail: /proc/self/exe inside a mounted AppImage is
     * /tmp/.mount_XXX/usr/bin/bounce_vertical_slice, so the derived root was the mount
     * point, there was no README.md there, and the run died with 96 bytes on stderr
     * having reported only 97 of its checks. A packaged artifact ships no README, so
     * there is no document for this check to have an opinion about; skipping is the
     * correct answer and failing is the wrong one.
     *
     * IT IS REPORTED DIFFERENTLY RATHER THAN SILENTLY, because "no claim was checked"
     * must not look identical to "the claim was checked and held". A run from a checkout
     * prints the reference and image counts; a packaged build prints scope=packaged-build
     * on its own line.
     */
    for (index = 0u; index < 2u; index++) {
        char *slash = strrchr(executable, '/');

        if (slash == NULL || slash == executable) {
            fprintf(stderr,
                    "readme: the executable is not inside a directory tree\n");
            return -1;
        }
        *slash = '\0';
    }
    {
        const char *leaf = strrchr(executable, '/');
        char *slash;

        leaf = (leaf != NULL) ? leaf + 1 : executable;
        if (strcmp(leaf, "native") != 0) {
            printf("README-SHOTS scope=packaged-build refs=0 images=0"
                   " skipped=yes PASS\n");
            return 0;
        }
        slash = strrchr(executable, '/');
        if (slash == NULL || slash == executable) {
            fprintf(stderr,
                    "readme: the checkout root could not be derived\n");
            return -1;
        }
        *slash = '\0';
    }
    (void)snprintf(root, sizeof root, "%s", executable);
    (void)snprintf(readme, sizeof readme, "%s/README.md", root);
    (void)snprintf(images, sizeof images, "%s/screenshots", root);

    file = fopen(readme, "rb");
    if (file == NULL) {
        fprintf(stderr, "readme: could not read %s\n", readme);
        return -1;
    }
    length = (ssize_t)fread(text, 1u, sizeof text - 1u, file);
    (void)fclose(file);
    if (length <= 0) {
        fprintf(stderr, "readme: %s is empty\n", readme);
        return -1;
    }
    text[length] = '\0';

    /*
     * COLLECT THE REFERENCES. Every occurrence of the directory name is taken, so a
     * reference in prose counts as well as one in an image link; both would rot the same
     * way. Occurrences beyond the limit are counted rather than stored, and reported, so
     * the limit cannot quietly turn into "stop checking".
     */
    cursor = text;
    for (;;) {
        const char *hit = strstr(cursor, "screenshots/");
        const char *end;
        size_t span;

        if (hit == NULL)
            break;
        end = strstr(hit, ".png");
        if (end == NULL) {
            cursor = hit + strlen("screenshots/");
            continue;
        }
        span = (size_t)(end - hit) + 4u;
        if (span >= BOUNCE_README_PATH_MAX)
            span = BOUNCE_README_PATH_MAX - 1u;
        if (reference_count < BOUNCE_README_REFERENCE_LIMIT) {
            memcpy(referenced[reference_count], hit, span);
            referenced[reference_count][span] = '\0';
            reference_count++;
        }
        cursor = hit + span;
    }
    if (reference_count == 0u) {
        fprintf(stderr, "readme: no screenshots/ references at all\n");
        return -1;
    }

    /* EVERY REFERENCE MUST RESOLVE. This is the half that would have caught 8bdc651. */
    for (index = 0u; index < reference_count; index++) {
        char full[BOUNCE_README_PATH_MAX + 1024];

        if (snprintf(full, sizeof full, "%s/%s", root, referenced[index])
            >= (int)sizeof full)
            continue;
        if (access(full, F_OK) != 0) {
            fprintf(stderr,
                    "readme: the README shows %s, which does not exist\n",
                    referenced[index]);
            bad++;
        }
    }

    /* AND EVERY IMAGE MUST BE SHOWN. */
    dir = opendir(images);
    if (dir == NULL) {
        fprintf(stderr, "readme: could not open %s\n", images);
        return -1;
    }
    while ((entry = readdir(dir)) != NULL) {
        size_t name_length = strlen(entry->d_name);
        int listed = 0;

        if (name_length < 4u
            || strcmp(entry->d_name + name_length - 4u, ".png") != 0)
            continue;
        image_count++;
        for (index = 0u; index < reference_count; index++) {
            char leaf[BOUNCE_README_PATH_MAX];
            const char *tail = strrchr(referenced[index], '/');

            if (snprintf(leaf, sizeof leaf, "%s",
                         tail != NULL ? tail + 1 : referenced[index]) >= (int)sizeof leaf)
                continue;
            if (strcmp(leaf, entry->d_name) == 0) {
                listed = 1;
                break;
            }
        }
        if (!listed) {
            fprintf(stderr,
                    "readme: screenshots/%s exists but the README never shows it\n",
                    entry->d_name);
            bad++;
        }
    }
    (void)closedir(dir);

    if (image_count == 0u) {
        fprintf(stderr, "readme: screenshots/ contains no images\n");
        return -1;
    }
    if (bad == 0) {
        printf("README-SHOTS refs=%zu images=%zu broken=0 unlisted=0 PASS\n",
               reference_count, image_count);
    }
    return bad == 0 ? 0 : -1;
}

int main(int argc, char **argv)
{
    const char *level_path = BOUNCE_LEVEL001_PATH;
    /* Read once, at the top: setenv() below invalidates the pointer. */
    const char *original_xdg = getenv("XDG_DATA_HOME");

    int check_only = 0;
    int camera_diagnostic_mode = 0;
    int vertical_diagnostic_mode = 0;
    int natural_camera_diagnostic_mode = 0;
    int render_trace_mode = 0;
    int live_status_mode = 0;
    int path_selected = 0;
    int64_t live_status_next_ms = 0;
    /*
     * STEP 14B-34-H. NULL means "no explicit device was requested", which is the
     * exact behaviour that existed before this checkpoint: the player then asks
     * the backend for its own default. Never a probing result -- there is no
     * probing, and this variable is only ever set from an explicit flag.
     */
    const char *audio_device_name = NULL;
    const char *screenshots_dir = NULL;
    const char *save_dir = NULL;
    int save_path_mode = 0;
    int save_plant_mode = 0;
    size_t asset_count = 0u;
    BounceApp app;
    BounceSurface *surface = NULL;
    BounceRenderer *renderer = NULL;
    BouncePresentation *presentation = NULL;
    /*
     * STEP 14B-34-D. Declared here with the other owned handles and destroyed in
     * the same cleanup block, so a NULL player on a host with no audio device
     * needs no special case here.
     */
    BounceAudioPlayer *audio_player = NULL;
    /*
     * STEP 34-F-K -- NATIVE ADDITION. Mirrors whether the Layer B sink is
     * currently installed on `audio_player`, so the frame loop can tell a real
     * setting change from a no-op without asking the player. It starts true
     * because that is the ON default; OFF is reached only by an explicit
     * SELECT on the Audio page.
     */
    bool audio_sink_attached = true;
    X11PresentationContext x11_context;
    /*
     * STEP 13E -- the tracker is a stack instance like the other diagnostics and
     * is attached to the app only when NBB_DEBUG selects a non-zero level, so a
     * default run holds a disabled tracker and app->debug_tracker stays NULL.
     */
    BounceDebugTracker debug_tracker;
    BounceDebugLevel debug_level = BOUNCE_DEBUG_LEVEL_DISABLED;
    CameraDiagnostic camera_diagnostic;
    VerticalDiagnostic vertical_diagnostic;
    RenderTrace render_trace;
    unsigned long regular_ball_digest = 0UL;
    unsigned long big_ball_digest = 0UL;
    int exit_code = EXIT_FAILURE;
    int argument_index;

    memset(&x11_context, 0, sizeof x11_context);
    memset(&vertical_diagnostic, 0, sizeof vertical_diagnostic);
    memset(&render_trace, 0, sizeof render_trace);
    camera_diagnostic_init(&camera_diagnostic);
    /*
     * STEP 13E -- the environment is read EXACTLY ONCE, here, before anything
     * else runs. Nothing re-parses it later and no tick reads it. An unset, "0"
     * or unrecognised value yields a disabled tracker whose sink is NULL, so
     * every call site below returns on its enabled test.
     */
    debug_level = bounce_debug_level_from_env(BOUNCE_DEBUG_ENV_NAME);
    bounce_debug_tracker_init(&debug_tracker, debug_level, stderr);
    if (bounce_game_init(&app) != 0)
        return EXIT_FAILURE;
    (void)bounce_asset_inventory_entries(&asset_count);

    if (argc == 2 && strcmp(argv[1], "--assets") == 0) {
        if (bounce_asset_inventory_check(BOUNCE_RESOURCE_ROOT, stdout) != 0)
            return EXIT_FAILURE;
        return EXIT_SUCCESS;
    }
    if (argc > 1 && strcmp(argv[1], "--assets") == 0) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    if (argc > 1 && strcmp(argv[1], "--check") == 0) {
        check_only = 1;
    } else {
        for (argument_index = 1; argument_index < argc; ++argument_index) {
            if (strcmp(argv[argument_index], "--check") == 0) {
                check_only = 1;
            } else if (strcmp(argv[argument_index], "--camera-diagnostic") == 0) {
                camera_diagnostic_mode = 1;
            } else if (strcmp(argv[argument_index], "--vertical-diagnostic") == 0) {
                vertical_diagnostic_mode = 1;
            } else if (strcmp(argv[argument_index], "--natural-camera-diagnostic") == 0) {
                natural_camera_diagnostic_mode = 1;
                camera_diagnostic_mode = 1;
            } else if (strcmp(argv[argument_index], "--render-trace") == 0) {
                render_trace_mode = 1;
            } else if (strcmp(argv[argument_index], "--live-status") == 0) {
                live_status_mode = 1;
            } else if (strcmp(argv[argument_index], "--save-path") == 0) {
                save_path_mode = 1;
            } else if (strcmp(argv[argument_index], "--save-plant") == 0) {
                save_plant_mode = 1;
            } else if (strcmp(argv[argument_index], "--save") == 0) {
                /* The bare form is a mistake, not a level path. */
                fprintf(stderr, "--save requires a directory: --save=DIR\n");
                print_usage(argv[0]);
                return EXIT_FAILURE;
            } else if (strncmp(argv[argument_index], BOUNCE_SAVE_DIR_FLAG,
                               BOUNCE_SAVE_DIR_FLAG_LENGTH) == 0) {
                save_dir = argv[argument_index] + BOUNCE_SAVE_DIR_FLAG_LENGTH;
                if (save_dir[0] == '\0') {
                    fprintf(stderr,
                            "--save= requires a directory\n");
                    print_usage(argv[0]);
                    return EXIT_FAILURE;
                }
            } else if (strcmp(argv[argument_index], "--screenshots") == 0) {
                /* The bare form is a mistake, not a level path. */
                fprintf(stderr, "--screenshots requires a directory: --screenshots=DIR\n");
                print_usage(argv[0]);
                return EXIT_FAILURE;
            } else if (strncmp(argv[argument_index], "--screenshots=",
                               strlen("--screenshots=")) == 0) {
                screenshots_dir = argv[argument_index] + strlen("--screenshots=");
                if (screenshots_dir[0] == '\0') {
                    fprintf(stderr, "--screenshots= requires a directory\n");
                    print_usage(argv[0]);
                    return EXIT_FAILURE;
                }
            } else if (strncmp(argv[argument_index], BOUNCE_AUDIO_DEVICE_FLAG,
                               BOUNCE_AUDIO_DEVICE_FLAG_LENGTH) == 0) {
                /*
                 * STEP 14B-34-H. The device is taken EXACTLY as written after the
                 * flag. It is never resolved, probed, or substituted. An empty
                 * value is rejected rather than quietly treated as "unset",
                 * because a caller who named a device and gave it nothing has
                 * made a mistake and is entitled to be told.
                 */
                audio_device_name =
                    argv[argument_index] + BOUNCE_AUDIO_DEVICE_FLAG_LENGTH;
                if (audio_device_name[0] == '\0') {
                    fprintf(stderr,
                            "%s requires a device name\n",
                            BOUNCE_AUDIO_DEVICE_FLAG);
                    print_usage(argv[0]);
                    return EXIT_FAILURE;
                }
            } else if (path_selected == 0) {
                level_path = argv[argument_index];
                path_selected = 1;
            } else {
                print_usage(argv[0]);
                return EXIT_FAILURE;
            }
        }
    }
    free(bounce_check_original_xdg);
    bounce_check_original_xdg = NULL;
    if (original_xdg != NULL) {
        bounce_check_original_xdg = (char *)malloc(strlen(original_xdg) + 1u);
        if (bounce_check_original_xdg != NULL)
            (void)snprintf(
                bounce_check_original_xdg,
                strlen(original_xdg) + 1u,
                "%s",
                original_xdg);
    }

    /*
     * STEP SHOTS -- TAKEN AS EARLY AS POSSIBLE, because it is a build and documentation
     * mode rather than a game mode. It builds its own surface and renderer, so nothing
     * the frame loop would have set up is required, and it redirects the store to a
     * private root of its own first, so it cannot disturb the player's save.
     */
    /*
     * STEP SAVE-DIR -- APPLY --save=DIR BEFORE ANYTHING READS THE STORE.
     *
     * bounce_persistence_path() resolves once and caches for the life of the process,
     * so setting the variable after the first read would have no effect at all and the
     * flag would look accepted while writing to the default location. This is placed
     * with the other pre-initialisation so it beats the cache rather than losing to it.
     *
     * It overwrites BOUNCE_SAVE_DIR rather than deferring to it: a flag given at a
     * terminal is the more specific instruction of the two.
     */
    /*
     * THE FLAG IS APPLIED FIRST, AND THE PROBE RUNS SECOND.
     *
     * These were the other way round at first, which is what made --save=DIR useless
     * for the one mode that prints where the save went: --save-path returned the
     * environment's location while every other mode honoured the flag. verify_save_
     * directory_precedence()'s third case is the assertion that caught it -- the flag
     * run is given a BOUNCE_SAVE_DIR pointing somewhere else, and the store came out
     * there.
     *
     * Nothing above this line reads the store, which is the other half of why the
     * order is safe to state this way: bounce_persistence_path() caches, so the
     * setenv has to happen before the first call, not merely before the first write.
     */
    if (save_dir != NULL
        && setenv("BOUNCE_SAVE_DIR", save_dir, 1) != 0) {
        fprintf(stderr, "could not set the save directory to %s\n", save_dir);
        goto cleanup;
    }

    if (save_path_mode || save_plant_mode) {
        int probe_rc = save_plant_mode ? bounce_save_plant_probe()
                                       : bounce_save_path_probe();

        free(bounce_check_original_xdg);
        bounce_check_original_xdg = NULL;
        return probe_rc == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
    }

    if (screenshots_dir != NULL) {
        int shot_rc = bounce_shot_write_all(screenshots_dir);

        free(bounce_check_original_xdg);
        bounce_check_original_xdg = NULL;
        return shot_rc == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
    }

    if (camera_diagnostic_mode) {
        camera_diagnostic.enabled = true;
        app.camera_diagnostic = &camera_diagnostic;
    }
    if (vertical_diagnostic_mode) {
        vertical_diagnostic.enabled = true;
        app.vertical_diagnostic = &vertical_diagnostic;
    }
    if (render_trace_mode) {
        render_trace.enabled = true;
        app.render_trace = &render_trace;
    }

    /*
     * STEP PERSIST-ISOLATE (RUN-WIDE) -- THE WHOLE SELF-TEST RUNS AGAINST A PRIVATE
     * STORE, PUBLISHED HERE, ONCE.
     *
     * WHY THIS IS AT THE RUN'S EDGE AND NOT IN EACH VERIFIER. The suite reached the
     * player's real save because around thirty functions can reach a store write --
     * every one that drives x11_dispatch_event(), app_update_production_game(),
     * app_restore_persisted_settings() or the drive_app_to_*() helpers -- and only four
     * of them published a private root of their own. Fixing them one at a time would
     * leave the property resting on a list that has to be kept in step with the call
     * graph, and the next verifier that loads a level would reopen the hole.
     *
     * Isolating the RUN makes the property structural: inside `--check` the store path
     * cannot resolve to the player's, whatever any verifier does. The per-verifier roots
     * stay and are harmless -- each saves and restores the previous value, so they nest.
     *
     * WHAT IT COST, AND HOW IT WAS FOUND. A report that a brand new install showed a
     * selectable Continue row with no session behind it. The store held
     *
     *     b1=1  lives=3  level=2  score=1122  x=30 y=18  hoops=0
     *
     * Every one of those is a test fixture: score 1122 and x = 30, y = 18 appear
     * nowhere else in the tree, and hoops_scored = 0 is impossible alongside a score of
     * 1122 in a real session. The record had not been played, it had been written by
     * `make check`. A fresh XDG_DATA_HOME did not help, because the hole was in the
     * writer rather than in the path -- which is the strongest argument for isolating
     * the run rather than trusting the caller's environment.
     *
     * The individual offender was verify_persistence_flow(), which primes a Record 3
     * with those exact values and had no root of its own; it has one now as well, so the
     * two layers do not depend on each other.
     *
     * NOT RESTORED PART-WAY THROUGH THE SUITE, deliberately. Every store access resolves
     * the path from the environment, so restoring it between verifiers would leave
     * whichever one ran next writing to the player's save -- which is the bug. It is
     * restored once, at the boundary between the suite and the game, and once more at
     * cleanup on every exit including the failing ones.
     *
     * The suite runs in EVERY mode, not only under --check, so this was not gated on
     * check_only. That was wrong twice over: `make run` executed the self-test against
     * the real store, and the isolation guard below reported the missing override as a
     * failure and refused to start the game.
     */
    {
        static const char template[] = "/tmp/bounce-checkrun-XXXXXX";
        char root[sizeof template];

        /*
         * PUBLISHED FOR EVERY MODE, NOT JUST --check.
         *
         * The suite is not gated on check_only: main() runs it, and only afterwards
         * decides whether to return or carry on into the game. So gating the isolation on
         * check_only left `make run` -- which is how the game is actually launched --
         * executing the whole self-test against the player's real store, which is the
         * defect this was all for. It also broke the launch outright: the isolation guard
         * read the missing override and failed the run.
         *
         * WHICH IS WHY IT IS RESTORED AGAIN BELOW, before the game starts. The override
         * has to cover the suite and NOT the game: leaving it in place would point the
         * player's session at a temporary directory and throw away their progress on
         * exit. Scoped like this, the suite can never reach the store and the game can.
         */
        memcpy(root, template, sizeof template);
        if (mkdtemp(root) == NULL) {
            fprintf(stderr, "could not create a private store root for the self-test\n");
            goto cleanup;
        }
        (void)snprintf(bounce_check_private_root,
                      sizeof bounce_check_private_root, "%s", root);
        if (setenv("XDG_DATA_HOME", root, 1) != 0) {
            fprintf(stderr, "could not publish the private store root\n");
            goto cleanup;
        }
    }

    if (bounce_asset_inventory_check(BOUNCE_RESOURCE_ROOT, NULL) != 0) {
        fprintf(stderr, "game asset inventory check failed\n");
        goto cleanup;
    }
    app.visuals = bounce_visual_assets_create(BOUNCE_RESOURCE_ROOT);
    if (app.visuals == NULL) {
        fprintf(stderr, "original visual asset load failed\n");
        goto cleanup;
    }
    if (bounce_visual_assets_verify(app.visuals) != 0) {
        fprintf(stderr, "original visual asset verification failed\n");
        goto cleanup;
    }
    if (verify_additional_level_visual_render(
            "src/main/resources/levels/J2MElvl.002",
            app.visuals
        ) != 0
        || verify_additional_level_visual_render(
            "src/main/resources/levels/J2MElvl.008",
            app.visuals
        ) != 0) {
        fprintf(stderr, "additional level visual verification failed\n");
        goto cleanup;
    }
    if (verify_ui_shell(app.visuals) != 0) {
        fprintf(stderr, "native UI shell verification failed\n");
        goto cleanup;
    }
    if (verify_flow_transitions() != 0) {
        fprintf(stderr, "application flow transition verification failed\n");
        goto cleanup;
    }
    if (verify_gameplay_entry_boundary() != 0) {
        fprintf(stderr, "gameplay entry boundary verification failed\n");
        goto cleanup;
    }
    if (verify_level_load_entry_integration() != 0) {
        fprintf(stderr, "level load entry integration verification failed\n");
        goto cleanup;
    }
    if (verify_player_initialization_boundary() != 0) {
        fprintf(stderr, "player initialization boundary verification failed\n");
        goto cleanup;
    }
    /*
     * STEP 44B. Registered here, before verify_runtime_initialization_boundary(),
     * so its result is reported even while that seam's pre-existing STEP43B-R2
     * fixture blocker aborts the run. Ordinary sequence member, nothing disabled,
     * no other check moved.
     */
    if (verify_big_ball_respawn_settle() != 0) {
        fprintf(stderr, "big ball respawn settle verification failed\n");
        goto cleanup;
    }
    if (verify_runtime_initialization_boundary() != 0) {
        fprintf(stderr, "runtime initialization seam verification failed\n");
        goto cleanup;
    }
    if (verify_camera_initialization_boundary() != 0) {
        fprintf(stderr, "camera initialization seam verification failed\n");
        goto cleanup;
    }
    if (verify_gameplay_activation_boundary() != 0) {
        fprintf(stderr, "gameplay activation seam verification failed\n");
        goto cleanup;
    }
    if (verify_game_timer_tick_entry_boundary() != 0) {
        fprintf(stderr, "game timer tick-entry seam verification failed\n");
        goto cleanup;
    }
    if (verify_tick_dispatch_boundary() != 0) {
        fprintf(stderr, "tick dispatch seam verification failed\n");
        goto cleanup;
    }
    if (verify_player_tick_entry_boundary() != 0) {
        fprintf(stderr, "f.b() player tick entry verification failed\n");
        goto cleanup;
    }
    if (verify_player_physics_continuation() != 0) {
        fprintf(stderr, "player physics continuation verification failed\n");
        goto cleanup;
    }
    if (verify_render_continuation() != 0) {
        fprintf(stderr, "render continuation verification failed\n");
        goto cleanup;
    }
    if (verify_dyn_thorn_tick_integration() != 0) {
        fprintf(stderr, "dynamic thorn tick integration verification failed\n");
        goto cleanup;
    }
    if (verify_production_game_routing() != 0) {
        fprintf(stderr, "production main-loop routing verification failed\n");
        goto cleanup;
    }
    if (verify_tick_cadence() != 0) {
        fprintf(stderr, "game tick cadence verification failed\n");
        goto cleanup;
    }
    if (verify_arrival_is_playable() != 0) {
        fprintf(stderr, "arrival playability verification failed\n");
        goto cleanup;
    }
    if (verify_big_ball_spawn_fit() != 0) {
        fprintf(stderr, "big ball spawn fit verification failed\n");
        goto cleanup;
    }
    if (verify_lives_ladder() != 0) {
        fprintf(stderr, "lives ladder verification failed\n");
        goto cleanup;
    }
    /*
     * STEP 38-RESET. Registered together, and immediately after the check that
     * walks the same two Settings rows, because the two halves of the feature are
     * one claim: verify_default_state() pins what a fresh install is, and
     * verify_reset_to_default() proves Confirm puts the flow and the store back to
     * exactly that. Running the second without the first would let the two drift
     * apart -- a reset that restores something no fresh install has would still
     * pass every field assertion in isolation.
     */
    if (verify_default_state() != 0) {
        fprintf(stderr, "fresh-install default state verification failed\n");
        goto cleanup;
    }
    if (verify_reset_to_default() != 0) {
        fprintf(stderr, "reset to default verification failed\n");
        goto cleanup;
    }
    if (verify_reset_page_pointer_and_hint() != 0) {
        fprintf(stderr, "reset page pointer and hint verification failed\n");
        goto cleanup;
    }
    if (verify_continue_survives_submenus() != 0) {
        fprintf(stderr, "continue-survives-submenus verification failed\n");
        goto cleanup;
    }
    if (verify_continue_publication() != 0) {
        fprintf(stderr, "continue publication verification failed\n");
        goto cleanup;
    }
    if (verify_door_resets_between_levels() != 0) {
        fprintf(stderr, "between-level door reset verification failed\n");
        goto cleanup;
    }
    if (verify_hoop_counter_no_double_count() != 0) {
        fprintf(stderr, "hoop counter double-count verification failed\n");
        goto cleanup;
    }
    if (verify_door_waits_for_hoops() != 0) {
        fprintf(stderr, "door/hoop gate verification failed\n");
        goto cleanup;
    }
    if (verify_w1_completion_request_latch() != 0) {
        fprintf(stderr, "W1 completion request latch verification failed\n");
        goto cleanup;
    }
    if (verify_resume_snapshot_capture() != 0) {
        fprintf(stderr, "resume snapshot capture verification failed\n");
        goto cleanup;
    }
    if (verify_record3_terminal_b1_contract() != 0) {
        fprintf(stderr, "Record 3 terminal b1 contract verification failed\n");
        goto cleanup;
    }
    if (verify_resume_restore_payload() != 0) {
        fprintf(stderr, "resume restore payload verification failed\n");
        goto cleanup;
    }
    if (verify_continue_entry_wiring() != 0) {
        fprintf(stderr, "continue entry wiring verification failed\n");
        goto cleanup;
    }
    if (verify_five_language_switching() != 0) {
        fprintf(stderr, "five-language switching verification failed\n");
        goto cleanup;
    }
    /*
     * V-2. Registered directly after the five-language switching check it
     * extends: that check proves each language selects and renders; this one
     * proves what it rendered contains no unknown-glyph box. It reads the same
     * mirrors those renderers use and changes no settings state, so the two are
     * order-independent.
     */
    if (verify_keypad_godmode_alias() != 0) {
        fprintf(stderr, "keypad godmode alias verification failed\n");
        goto cleanup;
    }
    if (verify_god_mode_cheat_activation() != 0) {
        fprintf(stderr, "god mode cheat activation verification failed\n");
        goto cleanup;
    }
    if (verify_numeric_keypad() != 0) {
        fprintf(stderr, "numeric keypad verification failed\n");
        goto cleanup;
    }
    if (verify_keypad_full_range() != 0) {
        fprintf(stderr, "keypad full range verification failed\n");
        goto cleanup;
    }
    if (verify_instructions_scroll() != 0) {
        fprintf(stderr, "instructions scroll verification failed\n");
        goto cleanup;
    }
    if (verify_script_glyph_coverage(app.visuals) != 0) {
        fprintf(stderr, "script glyph coverage verification failed\n");
        goto cleanup;
    }
    if (verify_mouse_and_numeric_input() != 0) {
        fprintf(stderr, "mouse and numeric input verification failed\n");
        goto cleanup;
    }
    /*
     * STEP 46F. Registered here, beside the other input seam verifications,
     * because it verifies the auto-repeat filter that x11_process_events() uses.
     * It touches no display and no production state: a pure predicate plus the
     * existing alias contract re-asserted through the real input module. Nothing
     * is disabled, moved or reordered around it.
     */
    if (verify_x11_autorepeat_filter() != 0) {
        fprintf(stderr, "x11 autorepeat filter verification failed\n");
        goto cleanup;
    }
    /*
     * V-1. Registered beside the two X11 input-seam verifications, and it needs
     * both of them: x11_dispatch_event() is the loop body those verifications
     * could previously only describe, and it expects events the 46F filter would
     * have accepted. Nothing is disabled, moved or reordered around it.
     */
    if (verify_x11_dispatch_event() != 0) {
        fprintf(stderr, "x11 dispatch event verification failed\n");
        goto cleanup;
    }
    /*
     * STEP 46G. Registered beside the STEP 46F input-seam verification, which
     * it depends on: the detector only ever sees events the 46F filter already
     * accepted. Nothing is disabled, moved or reordered around it.
     */
    if (verify_god_mode_sequence_detector() != 0) {
        fprintf(stderr, "god mode sequence detector verification failed\n");
        goto cleanup;
    }
    if (verify_ui_color_profiles() != 0) {
        fprintf(stderr, "UI color profile verification failed\n");
        goto cleanup;
    }
    if (verify_native_language_presentation() != 0) {
        fprintf(
            stderr,
            "native language presentation verification failed\n");
        goto cleanup;
    }
    if (verify_native_extension_ui() != 0) {
        fprintf(
            stderr,
            "native extension UI verification failed\n");
        goto cleanup;
    }
    if (verify_level_complete_form() != 0) {
        fprintf(stderr, "level complete form verification failed\n");
        goto cleanup;
    }
    if (verify_input_state() != 0) {
        fprintf(stderr, "canonical input state verification failed\n");
        goto cleanup;
    }
    if (verify_debug_tracker() != 0) {
        fprintf(stderr, "debug tracker verification failed\n");
        goto cleanup;
    }
    if (verify_all_level_lifecycle() != 0) {
        fprintf(stderr, "multi-level lifecycle verification failed\n");
        goto cleanup;
    }
    if (verify_gameplay_dispatch() != 0) {
        fprintf(stderr, "gameplay dispatch verification failed\n");
        goto cleanup;
    }
    if (verify_horizontal_movement() != 0) {
        fprintf(stderr, "horizontal movement verification failed\n");
        goto cleanup;
    }
    if (verify_vertical_movement() != 0) {
        fprintf(stderr, "vertical movement verification failed\n");
        goto cleanup;
    }
    if (verify_vertical_trajectory_audit() != 0) {
        fprintf(stderr, "vertical trajectory audit verification failed\n");
        goto cleanup;
    }
    if (bounce_persistence_verify() != 0) {
        fprintf(stderr, "persistence store verification failed\n");
        goto cleanup;
    }
    if (verify_readme_screenshots() != 0) {
        fprintf(stderr, "README screenshot verification failed\n");
        goto cleanup;
    }
    if (verify_save_directory_precedence() != 0) {
        fprintf(stderr, "save directory precedence verification failed\n");
        goto cleanup;
    }
    if (verify_save_and_continue_across_restart() != 0) {
        fprintf(stderr, "save-and-continue-across-restart verification failed\n");
        goto cleanup;
    }
    if (verify_check_never_touches_the_real_store() != 0) {
        fprintf(stderr, "self-test store isolation verification failed\n");
        goto cleanup;
    }
    if (verify_persistence_flow() != 0) {
        fprintf(stderr, "persistence flow verification failed\n");
        goto cleanup;
    }
    if (verify_collision_query() != 0) {
        fprintf(stderr, "collision query verification failed\n");
        goto cleanup;
    }
    if (verify_dyn_thorn_tile10() != 0) {
        fprintf(stderr, "dynamic thorn tile-10 verification failed\n");
        goto cleanup;
    }
    /*
     * STEP 45A. Registered here, directly after verify_dyn_thorn_tile10(), because
     * it drives that same tile-10 thorn arm and so shares its fixture position.
     * Nothing is disabled, moved or reordered around it.
     */
    if (verify_god_mode_kill_ball_guard() != 0) {
        fprintf(stderr, "god mode kill ball guard verification failed\n");
        goto cleanup;
    }
    if (verify_big_ball_substep() != 0) {
        fprintf(stderr, "big ball substep verification failed\n");
        goto cleanup;
    }
    if (verify_candidate_b_t_write() != 0) {
        fprintf(stderr, "candidate B t-write verification failed\n");
        goto cleanup;
    }
    if (verify_tile_51_54_powerup() != 0) {
        fprintf(stderr, "f.java:636-640 tile 51-54 powerup failed\n");
        goto cleanup;
    }
    if (verify_static_wall_response() != 0) {
        fprintf(stderr, "static wall response verification failed\n");
        goto cleanup;
    }
    if (verify_candidate_a2_t_reset() != 0) {
        fprintf(stderr, "candidate A2 t reset verification failed\n");
        goto cleanup;
    }
    if (verify_horizontal_wall_damping() != 0) {
        fprintf(stderr, "f.java:852 horizontal wall damping failed\n");
        goto cleanup;
    }
    if (verify_non_wall_collision_response() != 0) {
        fprintf(stderr, "non-wall collision response verification failed\n");
        goto cleanup;
    }
    if (verify_hoop_predicates() != 0) {
        fprintf(stderr, "hoop predicate verification failed\n");
        goto cleanup;
    }
    if (verify_camera_follow() != 0) {
        fprintf(stderr, "camera follow verification failed\n");
        goto cleanup;
    }
    if (verify_camera_horizontal_expression() != 0) {
        fprintf(stderr, "camera horizontal expression verification failed\n");
        goto cleanup;
    }
    if (verify_camera_gate_boundaries() != 0) {
        fprintf(stderr, "camera gate boundary verification failed\n");
        goto cleanup;
    }
    if (verify_camera_transform_invariants() != 0) {
        fprintf(stderr, "camera transform invariant verification failed\n");
        goto cleanup;
    }
    if (verify_camera_four_directions() != 0) {
        fprintf(stderr, "four-direction camera verification failed\n");
        goto cleanup;
    }
    /*
     * BIG BALL RENDER: f.java:169-171 selects the 16x16 big-ball sprite and
     * e.java:217 offsets the draw by p == 8. Levels 003, 005 and 011 carry
     * isBigBall in their header (b.java:232-236); 011 is used here because it
     * is the largest of them. This is the first assertion anywhere that
     * exercises draw_player_ball() with a non-regular ball through the real
     * visual-assets path.
     */
    if (verify_camera_level_render(
            "src/main/resources/levels/J2MElvl.001",
            app.visuals,
            BOUNCE_REGULAR_BALL_SIZE,
            BOUNCE_REGULAR_BALL_P,
            &regular_ball_digest
        ) != 0
        || verify_camera_level_render(
            "src/main/resources/levels/J2MElvl.002",
            app.visuals,
            BOUNCE_REGULAR_BALL_SIZE,
            BOUNCE_REGULAR_BALL_P,
            NULL
        ) != 0
        || verify_camera_level_render(
            "src/main/resources/levels/J2MElvl.008",
            app.visuals,
            BOUNCE_REGULAR_BALL_SIZE,
            BOUNCE_REGULAR_BALL_P,
            NULL
        ) != 0
        || verify_camera_level_render(
            "src/main/resources/levels/J2MElvl.011",
            app.visuals,
            BOUNCE_BIG_BALL_SIZE,
            BOUNCE_BIG_BALL_P,
            &big_ball_digest
        ) != 0) {
        fprintf(stderr, "camera level render verification failed\n");
        goto cleanup;
    }
    /*
     * The two ball states must not render the same sprite surface. Each digest
     * covers a surface containing only the ball, so equality would mean the
     * selection and the p offset had no effect at all.
     */
    if (regular_ball_digest == big_ball_digest) {
        fprintf(
            stderr,
            "camera level render: big ball sprite digest %016lx equals "
            "regular %016lx\n",
            big_ball_digest,
            regular_ball_digest
        );
        goto cleanup;
    }
    printf(
        "RENDER BALL regular(12,p=6) digest=%016lx big(16,p=8) digest=%016lx "
        "distinct=yes\n",
        regular_ball_digest,
        big_ball_digest
    );

    /*
     * STEP P2 -- registered LAST, deliberately. The chain is a
     * `goto cleanup` sequence, so whichever verification fails suppresses every
     * one after it: the R2 checkpoint recorded that hazard concretely, where a
     * failure in verify_continue_entry_wiring() masked bounce_persistence_verify()
     * and roughly forty other guards. A progression assertion is exactly the
     * kind of check that can fail, so it is placed where it has nothing left to
     * mask.
     */
    if (verify_level_progression_boundary() != 0) {
        fprintf(stderr, "level progression boundary verification failed\n");
        goto cleanup;
    }

    /*
     * STEP PERSIST-ISOLATE -- THE SUITE IS DONE, SO THE PLAYER'S STORE IS BACK.
     *
     * This is the other half of the override published before the suite, and it is the
     * half that makes the first half safe. The self-test must not reach the player's
     * save; the GAME must, because a session that ran against a temporary directory
     * would leave the real one untouched and quietly discard everything the player did
     * in it.
     *
     * `--check` never reaches here -- it returns above -- so this only runs when the
     * game is about to start. cleanup restores it again for the paths that do not get
     * this far.
     */
    {
        const char *restored;

        if (bounce_check_private_root[0] != '\0') {
            if (bounce_check_original_xdg != NULL)
                (void)setenv("XDG_DATA_HOME", bounce_check_original_xdg, 1);
            else
                (void)unsetenv("XDG_DATA_HOME");
        }
        /*
         * AND THE RESTORE IS CHECKED FROM OUTSIDE THE BLOCK THAT PERFORMS IT, because
         * silence here is the worst outcome available.
         *
         * If the restore is missing, nothing fails. The game starts against the temporary
         * root, plays a whole session and exits having saved it -- so the player's real
         * store is never written and their progress is silently discarded, with no error
         * anywhere and every check still green. A negative control that deletes the
         * restore was caught by nothing when the assertion lived inside the same block,
         * because disabling the block disabled the assertion too. That is the whole
         * reason this is a sibling and not a child: a check inside the code it checks is
         * only as removable as the code.
         *
         * The value read back must be the caller's when the caller had one and absent when
         * they did not. Anything else means the game is about to run somewhere the player
         * cannot find, or that a session is about to be thrown away.
         */
        restored = getenv("XDG_DATA_HOME");
        if (bounce_check_original_xdg != NULL) {
            if (restored == NULL || strcmp(restored, bounce_check_original_xdg) != 0) {
                fprintf(stderr,
                        "the player's store was not restored after the self-test:"
                        " expected %s, found %s\n",
                        bounce_check_original_xdg,
                        restored ? restored : "(unset)");
                goto cleanup;
            }
        } else if (restored != NULL) {
            fprintf(stderr,
                    "the player's store was not restored after the self-test:"
                    " expected unset, found %s\n",
                    restored);
            goto cleanup;
        }
    }

    if (check_only
        || camera_diagnostic_mode
        || vertical_diagnostic_mode
        || natural_camera_diagnostic_mode
        || render_trace_mode) {
        if (bounce_game_enter_menu(&app) != 0) {
            fprintf(stderr, "menu lifecycle transition failed\n");
            goto cleanup;
        }
    }
    /*
     * STEP 37 PERSIST -- the native LoadRecords(), BounceGame.java:95.
     *
     * Java calls it from the BounceGame constructor, before the game object is
     * ever shown, so a store written by a previous session is in force for the
     * whole first frame. This is the same seam: it runs once, on the live path,
     * before any gameplay.
     *
     * It is placed AFTER the --check early return on purpose. The self-test
     * must never read or write the player's real store, and this is the same
     * reason the audio and asset checks never open a device. Every verify_*
     * above therefore still runs against fresh-install defaults, which is also
     * what keeps those checks deterministic on a machine that has progress.
     *
     * A missing or unusable store is not an error. LoadRecords() catches
     * everything and leaves the defaults (BounceGame.java:332-334); this does
     * the same by ignoring the return value, because bounce_app_flow_init() has
     * already put the fresh-install values in place.
     */
    app_restore_persisted_settings(&app);
    if (app_begin_ui_ticks(&app) != 0) {
        fprintf(stderr, "UI tick initialization failed\n");
        goto cleanup;
    }

    surface = bounce_surface_create();
    if (surface == NULL) {
        fprintf(stderr, "could not create logical surface\n");
        goto cleanup;
    }
    renderer = bounce_renderer_create(surface);
    if (renderer == NULL) {
        fprintf(stderr, "could not create renderer\n");
        goto cleanup;
    }
    if (render_app_state(surface, renderer, &app) != 0) {
        fprintf(stderr, "menu render failed\n");
        goto cleanup;
    }
    if (natural_camera_diagnostic_mode || render_trace_mode) {
        if (app_load_natural_camera_level(&app, level_path) != 0) {
            fprintf(stderr, "natural camera diagnostic level load failed\n");
            goto cleanup;
        }
        if (natural_camera_diagnostic_mode) {
            printf(
                "NATURAL CAMERA DIAGNOSTIC level=%s dimensions=%ux%u "
                "initial_player=(%d,%d)\n",
                level_path,
                bounce_level_width(app.level),
                bounce_level_height(app.level),
                (int)app.player.TODO_unkX,
                (int)app.player.TODO_unkY
            );
            (void)fflush(stdout);
        }
        if (render_trace_mode) {
            printf(
                "RENDER TRACE LEVEL path=%s dimensions=%ux%u "
                "initial_player=(%d,%d)\n",
                level_path,
                bounce_level_width(app.level),
                bounce_level_height(app.level),
                (int)app.player.TODO_unkX,
                (int)app.player.TODO_unkY
            );
            (void)fflush(stdout);
        }
    }

    if (check_only) {
        const char *collision_status;

        if (bounce_game_start_level(&app, level_path, 0, 3) != 0
            || (app.player.ballSize == BOUNCE_REGULAR_BALL_SIZE
                && !bounce_collision_query(
                    app.player.TODO_unkX,
                    app.player.TODO_unkY,
                    app.player.p,
                    app.runtime
                ))
            || render_app_state(surface, renderer, &app) != 0
            || app.player.o != 0
            || app.player.t != 0
            || app.player.powerUpGravity != 0
            || app.player.TODO_somePowerUp3 != 0
            || app.player.C != 0
            || app.player.z != 0
            || app.player.q != 0
            || app.player.m) {
            fprintf(stderr, "gameplay render verification failed\n");
            goto cleanup;
        }
        collision_status = app.player.ballSize == BOUNCE_REGULAR_BALL_SIZE
            ? "verified" : "big-ball-boundary";
        {
            uint32_t diagnostic_pixel;
            /*
             * The input diagnostic is HIDDEN from the production gameplay frame
             * (see render_gameplay_scene), so this assertion now drives
             * draw_input_diagnostic() directly instead of going through
             * render_app_state(). The behaviour under test is unchanged and the
             * expectation is byte-for-byte the same: the same probe pixel
             * INPUT_DIAG_LEFT_X + 1, INPUT_DIAG_Y + 1, and the same two expected
             * colours COLOR_INPUT_ACTIVE then COLOR_INPUT_INACTIVE. Only the route
             * to the pixels changed, because the panel is no longer composited
             * into a normal gameplay frame. The renderer is created over this
             * surface at :14796, so drawing through it still lands in the pixels
             * read below.
             */
            if (bounce_input_apply_source(
                    &app.input,
                    BOUNCE_INPUT_SOURCE_LEFT_ARROW,
                    true
                ) != 0
                || draw_input_diagnostic(
                        renderer, &app.input, app.player.o
                    ) != 0
                || bounce_surface_get_pixel(
                        surface,
                        INPUT_DIAG_LEFT_X + 1,
                        INPUT_DIAG_Y + 1,
                        &diagnostic_pixel
                    ) != 0
                || diagnostic_pixel != COLOR_INPUT_ACTIVE
                || bounce_input_apply_source(
                        &app.input,
                        BOUNCE_INPUT_SOURCE_LEFT_ARROW,
                        false
                ) != 0
                || draw_input_diagnostic(
                        renderer, &app.input, app.player.o
                    ) != 0
                || bounce_surface_get_pixel(
                        surface,
                        INPUT_DIAG_LEFT_X + 1,
                        INPUT_DIAG_Y + 1,
                        &diagnostic_pixel
                    ) != 0
                || diagnostic_pixel != COLOR_INPUT_INACTIVE) {
                fprintf(stderr, "input diagnostic verification failed\n");
                goto cleanup;
            }
        }
        printf(
            "check ok: assets=%zu levels=11 flow=verified ui_shell=verified entry=verified level-load=verified player-init=verified runtime-init=verified camera-init=verified activation=verified timer-init=verified tick-entry=verified tick-dispatch=verified tick-body-entry=verified physics-continuation=verified render-handoff=verified dyn-thorn-tick=verified production-loop=verified native-ui=verified language=verified five-language=verified color-profile=verified pointer=verified input=verified movement=verified vertical=verified action=verified collision=%s dyn-thorn=verified response=verified non-wall=verified visual=verified camera=verified state=%s level_id=%d level=%s tiles=%ux%u runtime-copy=verified player=(%d,%d) spawn=(%d,%d) ballSize=%d p=%d lives=%d hoops=%d surface=%ux%u\n",
            asset_count,
            collision_status,
            bounce_game_state_name(app.state),
            app.level_id,
            level_path,
            bounce_level_width(app.level),
            bounce_level_height(app.level),
            app.player.TODO_unkX,
            app.player.TODO_unkY,
            app.spawn.world_x,
            app.spawn.world_y,
            app.player.ballSize,
            app.player.p,
            app.lives,
            app.hoops_scored,
            bounce_surface_width(surface),
            bounce_surface_height(surface)
        );
        exit_code = EXIT_SUCCESS;
        goto cleanup;
    }

    /*
     * STEP 14B-34-D -- the audio player is created HERE, on the live path only,
     * for exactly the reason the tracker is: the early returns above it (--check,
     * --assets, bad arguments) happen BEFORE this point, so none of them can leak
     * a worker thread, while every `goto cleanup` below reaches the teardown.
     *
     * Nothing here is allowed to stop the game. If the assets are missing, the
     * backend cannot be opened, or the thread cannot be started, create returns
     * NULL, no sink is installed, and the game runs with the same no-op audio
     * behaviour it had before this step. There is no silent switch to a fake
     * backend.
     */
    /*
     * STEP 14B-34-D -- the audio player is created HERE, on the live path only,
     * for exactly the reason the tracker is: the early returns above it (--check,
     * --assets, bad arguments) all happen BEFORE this point, so none of them can
     * leak a worker thread, while every `goto cleanup` below reaches the
     * teardown that destroys the player.
     *
     * Nothing here is allowed to stop the game. If the assets are missing, the
     * backend cannot be opened, or the worker cannot be started, create returns
     * NULL, no sink is installed, and the game runs with exactly the no-op audio
     * behaviour it had before this step. There is no silent switch to a fake
     * backend.
     */
    {
        BounceAudioPlayerConfig audio_config;

        bounce_audio_player_default_config(&audio_config);
        audio_config.resource_root = BOUNCE_RESOURCE_ROOT;
        /*
         * STEP 14B-34-H. The ONLY behavioural change in the whole checkpoint:
         * populate the field the backend has always accepted. NULL -- the case
         * when no flag was given -- leaves the pre-existing default path
         * untouched, so "default" is NOT changed to anything else.
         */
        audio_config.device_name = audio_device_name;
        audio_player = bounce_audio_player_create(&audio_config);
        if (audio_player != NULL) {
            /*
             * STEP 34-F-K -- NATIVE ADDITION. The Layer B sink is the single
             * central event boundary: all nine gameplay emission sites deliver
             * through it, so attaching and detaching it gates every one of them
             * at once. Nothing else is duplicated per call site.
             *
             * A fresh process starts on the documented ON default, so this
             * condition is true and the behaviour is exactly what it was before
             * the setting existed.
             */
            audio_sink_attached = true;
            if (bounce_app_flow_settings_audio_enabled(&app.flow))
                (void)bounce_audio_player_attach_sink(audio_player);
        }
    }

    /*
     * STEP 13E -- the tracker is attached HERE, on the live path only, and only
     * when NBB_DEBUG selected a non-zero level. Attaching it after the --check
     * block is deliberate: --check must keep its rc=0 / empty-stderr contract, and
     * the self-tests below drive the kill, respawn and tile seams directly, so an
     * attached tracker would inject event lines into a mode that is documented to
     * print nothing on stderr. The tracker's own self-test uses a private temporary
     * stream instead (verify_debug_tracker).
     */
    if (bounce_debug_tracker_enabled(&debug_tracker)) {
        app.debug_tracker = &debug_tracker;
        fprintf(
            stderr,
            "[NBB-DEBUG] level=%d env=%s sink=stderr\n",
            (int)bounce_debug_tracker_level(&debug_tracker),
            BOUNCE_DEBUG_ENV_NAME
        );
        (void)fflush(stderr);
    }

    if (x11_create(&x11_context) != 0) {
        fprintf(stderr, "could not open an X11 display\n");
        goto cleanup;
    }
    x11_context.render_trace = render_trace_mode ? &render_trace : NULL;
    presentation = bounce_presentation_create(
        surface,
        present_to_x11,
        &x11_context
    );
    if (presentation == NULL) {
        fprintf(stderr, "could not create presentation boundary\n");
        goto cleanup;
    }

    while (x11_context.running != 0 && x11_context.failed == 0) {
        /*
         * STEP 34-F-K -- NATIVE ADDITION. Apply the Audio ON/OFF setting.
         *
         * This is a logical event-delivery gate, not a subsystem control. The
         * player, its worker thread, the backend and the ALSA device are all
         * created before the loop and are left completely untouched here; only
         * the Layer B sink is attached or detached. That is what makes OFF
         * cheap and reversible, and it is why no audio code, no synthesis and
         * no device string is touched by the setting.
         *
         * NULL-safe by construction: if the player could not be created -- the
         * default-device failure case -- `audio_player` is NULL and there is
         * nothing to gate, so the setting is a no-op and no error is raised.
         * Audio initialisation failure therefore remains non-fatal.
         */
        if (audio_player != NULL) {
            const bool want_sink
                = bounce_app_flow_settings_audio_enabled(&app.flow);
            if (want_sink != audio_sink_attached) {
                if (want_sink)
                    (void)bounce_audio_player_attach_sink(audio_player);
                else
                    (void)bounce_audio_player_detach_sink(audio_player);
                audio_sink_attached = want_sink;
            }
        }
        if (x11_process_events(&x11_context, &app) != 0
            || app_update_ui(&app) != 0
            || app_update_production_game(&app) != 0
            || app_live_status_report(
                   &app,
                   live_status_mode != 0,
                   &live_status_next_ms) != 0
            || render_app_state(surface, renderer, &app) != 0
            || bounce_presentation_present(presentation) != 0) {
            x11_context.failed = 1;
            break;
        }
        /*
         * STEP 13E -- one observation per rendered frame, AFTER the tick and the
         * render for that frame. The observer only reads fields; it is what makes
         * the high fan-out transitions visible without a call site in each of the
         * twenty-odd flow setters, in bounce_game_add_score, or in the player
         * module. It returns -1 only for a NULL tracker or app, neither of which
         * is reachable here, so the result is deliberately not branched on: adding
         * a failure path for it would invent an error state the tracker does not
         * have. Level 3 output is throttled inside the observer to one line per
         * distinct simulation tick, so the line count follows the 40 ms tick rate
         * rather than the frame rate.
         */
        (void)bounce_debug_tracker_observe(app.debug_tracker, &app);
        sleep_frame();
    }
    /*
     * Final read-out so a short interactive run still leaves a state record
     * after the window closes.
     */
    if (live_status_mode != 0 && x11_context.failed == 0) {
        int64_t final_report_ms = 0;

        (void)app_live_status_report(&app, true, &final_report_ms);
    }
    exit_code = x11_context.failed == 0 ? EXIT_SUCCESS : EXIT_FAILURE;

cleanup:
    if (camera_diagnostic_mode) {
        camera_diagnostic_finish(&camera_diagnostic);
        app.camera_diagnostic = NULL;
    }
    if (vertical_diagnostic_mode) {
        vertical_diagnostic_finish(&vertical_diagnostic);
        app.vertical_diagnostic = NULL;
    }
    if (render_trace_mode)
        app.render_trace = NULL;
    bounce_presentation_destroy(presentation);
    x11_destroy(&x11_context);
    bounce_renderer_destroy(renderer);
    bounce_surface_destroy(surface);
    bounce_visual_assets_destroy(app.visuals);
    app.visuals = NULL;
    /*
     * STEP 14B-34-D. The audio player is torn down BEFORE the game, so the Layer
     * B sink is detached and the worker is joined while the game state it might
     * still be reading is still alive. destroy() is a no-op for NULL, so a host
     * with no audio device needs no branch. It removes the sink, stops the
     * worker, joins it, and closes the backend.
     */
    bounce_audio_player_destroy(audio_player);
    bounce_game_shutdown(&app);
    return exit_code;
}
